    private val _messageRequests = MutableStateFlow<List<ZchatPreferences.MessageRequest>>(emptyList())
    val messageRequests: StateFlow<List<ZchatPreferences.MessageRequest>> = _messageRequests.asStateFlow()

    /** B17 — per-conversation disappearing-messages TTL (process-wide prefs flow, #226). */
    val disappearingTtls: StateFlow<Map<String, ZchatPreferences.DisappearingTtl>> get() = zchatPreferences.disappearingTtls

    // R9-6 (REVIEW_R8 F14): the clock the disappearing-messages filter and its ticker read; null = the wall clock.
    // Only tests set it (ExpiredMessageLeavesOpenChatTest drives it on virtual time).
    @Volatile private var ttlClock: (() -> Long)? = null

    // R9-6: where the conversation render runs; null = Dispatchers.Default. Only tests set it.
    @Volatile private var renderDispatcher: kotlinx.coroutines.CoroutineDispatcher? = null

    /** ZC-946 part 4: where [followStoredSends] reads the store (Dispatchers.IO when unset; tests use virtual time). */
    @Volatile private var storeReadDispatcher: kotlinx.coroutines.CoroutineDispatcher? = null

    private fun ttlNowMillis(): Long = ttlClock?.invoke() ?: System.currentTimeMillis()

    // Time-lock unlocks: Map of locked message txId -> unlock txId
    // This tracks which locked messages have been unlocked (by payment or answer)
    private val unlockedMessages = MutableStateFlow<Map<String, String>>(emptyMap())

    // Track processed transaction IDs to avoid duplicate kill detection
    // Thread-safe: accessed from multiple coroutines
    private val processedKillCheckTxIds: MutableSet<String> = Collections.synchronizedSet(mutableSetOf())

    // Mutex to prevent race conditions between sync (receiving INIT) and send
    // (generating ConvID) for the same peer. Both paths write to conversation mappings.
    private val convIdMutex = Mutex()

    // E2E ratchet — persistent encrypted store for counters/seen-counter sets. Survives
    // app restart so replay protection and counter state are maintained across sessions.
    private val ratchetStateStore = zchatPreferences.getRatchetStateStore()
    private val messageProcessors = java.util.concurrent.ConcurrentHashMap<String, co.electriccoin.zcash.ui.screen.chat.crypto.ratchet.E2EMessageProcessor>()

    // File sharing: decrypted image cache + download tracking
    private var _fileCache: co.electriccoin.zcash.ui.screen.chat.filesharing.FileDownloadCache? = null
    private val fileDownloadsInProgress = java.util.concurrent.ConcurrentHashMap<String, Boolean>()

    // Hard ceiling on a single ZFILE download. The `url` in a ZFILE memo is attacker-controlled
    // (a peer can point it at an arbitrarily large blob), and the body was previously buffered whole
    // into memory — a multi-GB response would OOM-kill the app. 25 MB comfortably covers compressed
    // images + short voice clips while bounding the worst case.
    private val maxFileDownloadBytes = 25L * 1024 * 1024

    // Per-hash download progress (0..1) for the receiver. UI reads via [fileDownloadProgress].
    // Map is replaced wholesale on each update so StateFlow emits and Compose recomposes.
    private val _fileDownloadProgress = MutableStateFlow<Map<String, Float>>(emptyMap())
    val fileDownloadProgress: StateFlow<Map<String, Float>> = _fileDownloadProgress.asStateFlow()

    private fun updateFileProgress(hash: String, fraction: Float?) {
        // CAS-loop via .update so two concurrent downloads can't lose each other's writes.
        _fileDownloadProgress.update { current ->
            current.toMutableMap().apply {
                if (fraction == null) remove(hash) else put(hash, fraction.coerceIn(0f, 1f))
            }
        }
    }

    // Per-hash download FAILURE set for the receiver. Lives separately from progress because the
    // download's `finally` clears progress on every outcome; this lets the UI keep showing a
    // "Download failed — tap to retry" affordance after the bar disappears. UI reads via
    // [fileDownloadFailures]; tapping retry re-invokes downloadAndCacheFile, which clears the entry.
    private val _fileDownloadFailures = MutableStateFlow<Set<String>>(emptySet())
    val fileDownloadFailures: StateFlow<Set<String>> = _fileDownloadFailures.asStateFlow()

    private fun setFileDownloadFailed(hash: String, failed: Boolean) {
        _fileDownloadFailures.update { current ->
            if (failed) current + hash else current - hash
        }
    }

    private fun getFileCache(context: android.content.Context): co.electriccoin.zcash.ui.screen.chat.filesharing.FileDownloadCache {
        return _fileCache ?: co.electriccoin.zcash.ui.screen.chat.filesharing.FileDownloadCache(
            java.io.File(context.cacheDir, "zchat_files")
        ).also { _fileCache = it }
    }

    // Gate that loadConversations awaits before processing, ensuring
    // validateAndRepairConvIdMappings completes first to prevent reading partial repairs.
    private val repairComplete = CompletableDeferred<Unit>()

    // Conversation loading job — tracked so setNickname can cancel+restart without
    // spawning duplicate collection coroutines that race to write _chatListState.
    private var conversationLoadJob: Job? = null

    // Auto-refresh timer job
    private var autoRefreshJob: Job? = null
    private var countdownJob: Job? = null

    // ── Fields read by init-launched coroutines — MUST be declared before init {} ──────────────────
    // (SR-B1: the self-avatar delivery guard is process-wide now, selfAvatarDeliveryLock in the companion.)
    // Construction-race class: the init block launches
    // observeNostrInbound (SharedFlow collector) and loadConversations → convertToConversations
    // (Dispatchers.Default), which transitively read the fields below DURING construction. Declared
    // AFTER init they are null / primitive-default on those worker threads → crash-on-launch NPE (the
    // mutable maps) or silent misparse (the Char sentinels). Full docs live at each field's use-site.
    // Reply linkage (see untagReply): replyRefPrefix depends on replyRefSentinel → keep this order.
    private val replyRefSentinel = '\u0001'
    private val replyRefPrefix = "${replyRefSentinel}RPL:"
    private val replyPreviewSep = '\u001f'
    // TUNNEL pre-bootstrap payload queue — PROCESS-WIDE, lives in the companion (see there). It used to
    // be a per-instance map here, which stranded queued messages across the list/detail VM split (#38).
    // kexAckedKeys / kexAckInFlight are PROCESS-WIDE (companion) since HS-1: see there.

    // D1-recovery Stage 3 — the single wired path for E2E key generation/recovery: seed-derived
    // per-peer keys (recoverable after a wipe + seed restore) with the never-overwrite guard and
    // the random fail-safe inside. Read by loadConversations → convertToConversations (the Stage
    // 3b restore trial-match hook) which init{} launches on Dispatchers.Default — so this MUST
    // stay declared BEFORE init {} (same construction-race NPE class as the fields above).
    private val seedKeyProvider =
        co.electriccoin.zcash.ui.screen.chat.crypto.SeedDerivedE2EKeyProvider.create(
            zchatPreferences, persistableWalletProvider
        )

    // A5 restore key recovery — pass-to-pass state of the history scan, read by convertToConversations on
    // Dispatchers.Default, so declared BEFORE init {} like the fields above. See RestoreKexPolicy.
    // restoreRecheck: bumped to re-run the conversion once more when a complete pass still left a restored
    // peer gated or a historical handshake waiting (the SDK transaction list does not re-emit by itself).
    private val restoreRecheck = MutableStateFlow(0)

    @Volatile private var lastCompletePassFingerprint: Int? = null

    @Volatile private var restoreRecheckStreak = 0

    // R3-3 (1): contacts a send found waiting for the settlement of an older conversation id's counters; the next
    // history pass settles them (settleLegacyFloorJumps). Nullable so an instance built without its constructor
    // (tests) reads it as empty.
    @Volatile private var peersAwaitingLegacySettlement: Set<String>? = null

    // R4-3 (2): how many pass-ends with a FINISHED chain scan each "$peer|$olderConvId" has already waited, so the
    // wait is bounded (RestoreKexPolicy.MAX_LEGACY_SETTLEMENT_WAITS) instead of lasting as long as one own memo
    // stays unreadable. Per process: a restart starts the budget again, and each budget is a few seconds of passes.
    private val legacySettlementWaits = java.util.concurrent.ConcurrentHashMap<String, Int>()

    // D3-2: the Quantum Shield claim records (QsClaimStore). Assigned first thing in init, with no preference call (the
    // store only wraps the instance); an instance built without its constructor (tests) keeps null, and every claim path
    // then does exactly what it did before D3.
    @Volatile private var qsClaims: QsClaimStore? = null

    // D3-3: the claim alert of each chat (QsAlert), in its own holder: never in the scan confirmation. Made on first use,
    // so an instance built without its constructor (tests) gets one too.
    @Volatile private var qsAlertFlow: MutableStateFlow<Map<String, QsAlert>>? = null

    // ZC-250: the contact whose send the key-change gate refused last ([keyChangeRefusal]). In memory only; made on first
    // use, so an instance built without its constructor (tests) gets one too.
    @Volatile private var keyChangeRefusalFlow: MutableStateFlow<String?>? = null

    // ZC-545, ZC-564 — the per-contact session epoch ([peerSessionEpochs]) this instance last built or served a ratchet
    // processor under; see [retireProcessorsOfEarlierEpoch]. Created on first use.
    @Volatile private var processorEpochsSeen: java.util.concurrent.ConcurrentHashMap<String, Long>? = null

    init {
        // D3-2: before the refresh timer and the relay reader start, which both use it.
        qsClaims = PrefsQsClaimStore(zchatPreferences)
        // Load hidden messages from preferences
        hiddenMessages.value = zchatPreferences.getHiddenMessageIds()
        // Load already-paid payment-request IDs so their "Pay" affordance stays hidden across restarts
        paidRequestIds.value = zchatPreferences.getPaidRequestIds()
        // Read markers are the shared ZchatPreferences flow (pre-seeded in the singleton) — no per-VM
        // seed needed; both list + detail instances observe the same source (#226).
        // Load pending messages from preferences (persisted across navigation)
        loadPendingMessagesFromPrefs()
        // Load persisted call-log entries (incoming/outgoing/missed call history)
        loadCallLogsFromPrefs()
        // Load user status from preferences
        loadUserStatus()
        // Load peer statuses from preferences
        loadPeerStatuses()
        // Load wallet birthday for sync status display
        viewModelScope.launch {
            try {
                val wallet = persistableWalletProvider.getPersistableWallet()
                walletBirthday = wallet?.birthday?.value
            } catch (e: Exception) {
                Log.d("ZCHAT_FLOW", "Could not load wallet birthday: ${e.message}")
            }
        }
        // Validate and repair conversation ID mappings (fix for misrouted messages after restore)
        validateAndRepairConvIdMappings()
        loadConversations()
        startAutoRefreshTimer()
        observeBlockHeight()
        observeExchangeRate()
        observeWalletSyncStatus()
        observeNostrInbound()
        observeLocalMessages()
        followStoredSends()
        observeMessageRequests()
        // #avatar-process-death + SR-B1: the launch tick of self-avatar delivery (see observeSelfAvatarDelivery).
        observeSelfAvatarDelivery()
    }

    /**
     * #224 — seed the Message Requests list from persisted storage, then keep it live by collecting
     * inbound first-contact INITs from [NostrChatBridge]. The persisted seed covers requests that
     * arrived while no ViewModel was running (the service stored them); the live collect surfaces new
     * ones the instant they arrive.
     */
    private fun observeMessageRequests() {
        // getMessageRequests() reads EncryptedSharedPreferences (AES-GCM decrypt per entry); keep it OFF
        // the main thread — this runs from init{} during composition (StrictMode DiskRead otherwise).
        viewModelScope.launch {
            _messageRequests.value = withContext(Dispatchers.IO) { zchatPreferences.getMessageRequests() }
            co.electriccoin.zcash.ui.nostr.NostrChatBridge.messageRequests.collect {
                // Re-read the authoritative persisted set (dedup + ordering handled there) rather than
                // appending — the service has already stored it before emitting.
                _messageRequests.value = withContext(Dispatchers.IO) { zchatPreferences.getMessageRequests() }
            }
        }
    }

    /** Outcome of [acceptMessageRequest] so the UI can distinguish a successful accept (navigate to the
     *  new chat) from a refused one (keep the sheet open, explain why). */
    enum class AcceptRequestResult { ACCEPTED, CONFLICT_KEY_CHANGED, CONFLICT_PUBKEY_REUSED, REJECTED_SELF }

    /**
     * Accept an inbound OPEN contact request (#224): bind the sender's NOSTR identity to their claimed
     * Zcash address (TOFU), set the conversation to OPEN, and surface their first message — so replies
     * flow free over NOSTR from here on. This is the deliberate user trust action the request inbox
     * gates on.
     *
     * Refuses (returns a CONFLICT_* / REJECTED_SELF result WITHOUT binding) when:
     *  - the claimed address is OUR OWN (spoof) — defense-in-depth behind dispatch's self-drop, closing
     *    the cold-start TOCTOU where the self-address registry wasn't yet populated when the INIT arrived;
     *  - the claimed address ALREADY has a DIFFERENT NOSTR key (key-change / impersonation) — refuses
     *    WITHOUT mutating the genuine peer's trust (#6: the claimed address is unauthenticated, so no
     *    setE2EKeyChanged/setE2EVerified — see NostrChatBridge's #187 ABSOLUTE RULE);
     *  - the claimed address is an EXISTING contact (has a conversation) with no NOSTR key bound yet
     *    (ZC-1402) — CONFLICT_KEY_CHANGED, the request stays a separate pending request;
     *  - the sender's NOSTR key is ALREADY bound to a DIFFERENT address (pubkey reuse / identity
     *    confusion — one attacker key fanned out across many victim addresses).
     * On every refusal the request is left in place (key-change) or dropped (self) and the caller is told
     * not to navigate to a chat that wasn't created.
     */
    // #15: dispatch OFF the main thread — the body does EncryptedSharedPreferences AES-GCM work
    // (getMessageRequests + findPeerByNostrPubkey full modePrefs.all scan) that ANRs the UI thread on a
    // large roster; observeMessageRequests wraps the identical getMessageRequests() in withContext(IO) for
    // the same reason. The body is IO-safe (prefs reads/writes, StateFlow .value=, pendingMessages.update,
    // Log, loadConversations() which launches its own viewModelScope job). withContext returns to the
    // caller's dispatcher, so the caller's UI writes still run on Main.
    suspend fun acceptMessageRequest(request: ZchatPreferences.MessageRequest): AcceptRequestResult = withContext(Dispatchers.IO) {
        val addr = request.senderAddress
        // Self-spoof guard (defense-in-depth for the dispatch-time TOCTOU): never bind our OWN address.
        if (zchatPreferences.isSelfAddress(addr)) {
            zchatPreferences.removeMessageRequest(request.senderNostrPubkeyHex)
            _messageRequests.value = zchatPreferences.getMessageRequests()
            Log.w("ZCHAT_NOSTR", "Accept request REJECTED: claims OUR OWN address (spoof)")
            return@withContext AcceptRequestResult.REJECTED_SELF
        }
        val existing = zchatPreferences.getPeerNostrPubkey(addr)
        if (existing != null && !existing.equals(request.senderNostrPubkeyHex, ignoreCase = true)) {
            // #6: `addr` (request.senderAddress) is an UNAUTHENTICATED, attacker-controlled INIT field —
            // any NOSTR key can claim any victim's public UA. Mutating the GENUINE peer's trust here
            // (setE2EKeyChanged/setE2EVerified, keyed on addr) let a remote attacker who merely knows a
            // contact's public address weaponise one Accept tap into a key-change banner + verification
            // wipe + send-lockout on that unrelated contact. Per NostrChatBridge's #187 ABSOLUTE RULE, do
            // NOT touch trust state from this field. The accept is still refused: the request stays in the
            // inbox and the out-of-band-verify dialog still shows; the genuine peer's entry is untouched.
            Log.w(
                "ZCHAT_NOSTR",
                "Accept request: ${addr.take(16)}… already bound to a DIFFERENT NOSTR key — refusing (NOT rebinding, trust state left untouched)",
            )
            return@withContext AcceptRequestResult.CONFLICT_KEY_CHANGED
        }
        // ZC-1402: the claimed address already has a conversation (an existing Tunnel/Open contact) but no
        // relay key bound. The claim is unauthenticated, so binding the stranger's relay key here would hand
        // that contact's chat to whoever knows its public address and switch it to Open. Refuse like a key
        // change: nothing is bound, the request stays in the inbox as a separate pending request.
        if (existing == null && zchatPreferences.getConversationId(addr) != null) {
            Log.w(
                "ZCHAT_NOSTR",
                "Accept request: ${addr.take(16)}… is an existing contact with no relay key — refusing (NOT binding)",
            )
            return@withContext AcceptRequestResult.CONFLICT_KEY_CHANGED
        }
        // Reverse-uniqueness: refuse a NOSTR key already mapped to a DIFFERENT address. Without this, one
        // attacker key could be accept-bound to many third-party addresses, and findPeerByNostrPubkey
        // (used for inbound dispatch + reply routing) would resolve to an arbitrary one of them.
        val existingPeerForKey = zchatPreferences.findPeerByNostrPubkey(request.senderNostrPubkeyHex)
        if (existingPeerForKey != null && existingPeerForKey != addr) {
            Log.w(
                "ZCHAT_NOSTR",
                "Accept request REFUSED: NOSTR key already bound to a different address ${existingPeerForKey.take(16)}… (pubkey reuse)",
            )
            return@withContext AcceptRequestResult.CONFLICT_PUBKEY_REUSED
        }
        // Bind the (unverified) NOSTR identity + relay and lock the chat to OPEN.
        zchatPreferences.setPeerNostrPubkey(addr, request.senderNostrPubkeyHex)
        zchatPreferences.setPeerNostrRelay(
            addr,
            request.relayUrl.ifBlank { co.electriccoin.zcash.ui.nostr.NostrRelayPool.DEFAULT_RELAYS.first() },
        )
        zchatPreferences.setConversationMode(addr, co.electriccoin.zcash.ui.screen.chat.model.ConversationMode.OPEN)
        // #250-r4: anchor what rotation index this peer can verify at the moment we establish the OPEN
        // channel. Accepting a request means the peer has our CURRENT NOSTR pubkey (they wrapped the INIT
        // to it / we are about to reply to them on it), so they can verify v4 ZBOOTs signed by our current
        // index. Without seeding this, knownIdx stays at its -1 default and the relay-ack writer (the only
        // other site that advances it) could let an announce get signed with a stale index the peer never
        // held — stranding rotation recovery. Seed only when unset so we never regress a higher known idx.
        if (zchatPreferences.getPeerKnownOurRotationIndex(addr) < 0) {
            zchatPreferences.setPeerKnownOurRotationIndex(addr, zchatPreferences.getNostrRotationIndex())
        }
        // Thread the conversation and surface the first message as an inbound bubble (persisted so it
        // survives reload). Key the id on the STABLE rumor id (so a reaction/reply the sender attaches to
        // its own copy correlates here) — matching observeNostrInbound — falling back to the event id.
        zchatPreferences.getOrCreateConversationId(addr)
        val msgId = if (request.rumorId.isNotBlank()) {
            "nmsg-${request.rumorId}"
        } else {
            "nmsg-req-${request.eventId.ifBlank { System.nanoTime().toString() }}"
        }
        val ts = Instant.ofEpochMilli(request.timestampMillis.takeIf { it > 0 } ?: Instant.now().toEpochMilli())
        val msg = ChatMessage(
            id = msgId,
            txId = null,
            text = request.firstMessage,
            timestamp = ts,
            isOutgoing = false,
            peerAddress = addr,
            isPending = false,
            status = MessageStatus.SENT,
        )
        pendingMessages.update { current -> if (current.any { it.id == msgId }) current else current + msg }
        zchatPreferences.addPendingMessage(
            ZchatPreferences.PendingMessageData(
                id = msgId,
                text = request.firstMessage,
                timestampMillis = ts.toEpochMilli(),
                peerAddress = addr,
                isOutgoing = false,
                isPending = false,
                status = MessageStatus.SENT.name,
            )
        )
        zchatPreferences.removeMessageRequest(request.senderNostrPubkeyHex)
        _messageRequests.value = zchatPreferences.getMessageRequests()
        loadConversations()
        Log.d("ZCHAT_NOSTR", "Accepted OPEN request from ${addr.take(16)}… — bound NOSTR key, conversation is now OPEN")
        return@withContext AcceptRequestResult.ACCEPTED
    }

    /**
     * Reject an inbound OPEN contact request (#224): drop it and block the sender's NOSTR pubkey so its
     * future unsolicited INITs are silently discarded (anti-nag / anti-spam). No trust is created and no
     * conversation is started.
     */
    fun rejectMessageRequest(request: ZchatPreferences.MessageRequest) {
        val key = request.senderNostrPubkeyHex
        // ZC-1464: at most one decline goes to a key while it is on the Declined list.
        val alreadyDeclined = zchatPreferences.getDeclinedMessageRequests().any { it.senderNostrPubkeyHex.equals(key, ignoreCase = true) }
        zchatPreferences.declineMessageRequest(request)
        zchatPreferences.blockNostrPubkey(key)
        zchatPreferences.removeMessageRequest(key)
        _messageRequests.value = zchatPreferences.getMessageRequests()
        // ZC-1464 (W-122: always notify): the sender learns it over the relays, to the request's own key only. The token
        // carries no claimed address and no message text; a 2.12.4 sender drops it silently.
        if (!alreadyDeclined) {
            publishRequestDecision(key, RequestDecisionToken.declined(_currentUserAddress.value))
        }
        Log.d("ZCHAT_NOSTR", "Rejected + blocked OPEN request from ${key.take(8)}…")
    }

    /** ZC-1464: the Declined requests list (newest first), for the screen that offers Restore. */
    fun declinedMessageRequests(): List<ZchatPreferences.MessageRequest> = zchatPreferences.getDeclinedMessageRequests()

    /**
     * ZC-1464 Restore: the declined [request] goes back to the requests inbox and its key is unblocked; the sender is told
     * over the relays (ZRCPT|RESTORED), so its composer opens again. When the inbox is full nothing changes and nothing
     * is sent.
     */
    fun restoreDeclinedRequest(request: ZchatPreferences.MessageRequest) {
        val key = request.senderNostrPubkeyHex
        zchatPreferences.restoreDeclinedMessageRequest(key)
        _messageRequests.value = zchatPreferences.getMessageRequests()
        if (zchatPreferences.isNostrPubkeyBlocked(key)) {
            Log.w("ZCHAT_NOSTR", "Restore of the declined request from ${key.take(8)}… did not happen (requests inbox full)")
            return
        }
        publishRequestDecision(key, RequestDecisionToken.restored(_currentUserAddress.value))
    }

    /** ZC-1464 (sender side): [peerAddress] declined our chat request; the composer stays closed with a note until a Restore. */
    fun isRequestDeclinedBy(peerAddress: String): Boolean = zchatPreferences.isPeerRequestDeclined(peerAddress)

    /** ZC-1465: the contact's bound relay key has sent us something (UpgradeReminders.showsChatRequestHint's flag). */
    fun wasHeardFromOverRelays(peerAddress: String): Boolean = zchatPreferences.wasPeerHeardFrom(peerAddress)

    /** ZC-1464: one relay copy of a decline or restore token to [recipientKey]; free, never on-chain. */
    private fun publishRequestDecision(
        recipientKey: String,
        token: String,
    ) {
        viewModelScope.launch(Dispatchers.IO) {
            val result =
                try {
                    NostrChatBridge.publish(token, recipientKey)
                } catch (e: kotlinx.coroutines.CancellationException) {
                    throw e
                } catch (e: Exception) {
                    Log.w("ZCHAT_NOSTR", "request decision to ${recipientKey.take(8)}… not published", e)
                    null
                }
            val took = NostrChatBridge.relayTookIt(result)
            Log.d("ZCHAT_NOSTR", "request decision to ${recipientKey.take(8)}…: relay took it = $took")
        }
    }

    /**
     * ZC-1464 (sender side): [peerAddress] (the seal-authenticated sender) declined our chat request, or undid it. A
     * decline closes the composer and marks our earlier relay messages there, which only a relay took and which were
     * never read, as not delivered (DECLINED: no Retry); a restore opens the composer again.
     */
    private fun onRequestDecision(
        peerAddress: String,
        kind: RequestDecisionToken.Kind,
    ) {
        val declined = kind == RequestDecisionToken.Kind.DECLINED
        zchatPreferences.setPeerRequestDeclined(peerAddress, declined)
        Log.d("ZCHAT_NOSTR", "chat request ${if (declined) "declined" else "restored"} by ${peerAddress.take(12)}…")
        if (!declined) {
            undoDeclinedMarks(peerAddress)
            return
        }

        fun neverDelivered(
            peer: String,
            outgoing: Boolean,
            id: String,
            status: MessageStatus,
        ) = peer == peerAddress && outgoing && id.startsWith(RELAY_ROW_PREFIX) && status == MessageStatus.SENT
        var marked: Set<String> = emptySet()
        pendingMessages.update { list ->
            val ids = mutableSetOf<String>()
            val next =
                list.map { m ->
                    if (m.txId == null && !m.isRead && neverDelivered(m.peerAddress, m.isOutgoing, m.id, m.status)) {
                        ids += m.id
                        m.copy(status = MessageStatus.DECLINED)
                    } else {
                        m
                    }
                }
            marked = ids
            next
        }
        zchatPreferences
            .getPendingMessages()
            .filter { row ->
                val stored = row.status?.let { runCatching { MessageStatus.valueOf(it) }.getOrNull() } ?: MessageStatus.SENT
                row.id in marked || neverDelivered(row.peerAddress, row.isOutgoing, row.id, stored)
            }.forEach { row -> zchatPreferences.addPendingMessage(row.copy(status = MessageStatus.DECLINED.name)) }
    }

    /**
     * ZC-1545 (Q2-21): the inverse of the decline mark in [onRequestDecision]. When [peerAddress] restores the request
     * or writes from its bound key again, our relay rows there that the decline marked DECLINED go back to SENT ("a relay
     * took it", what they showed before), on screen and in the stored rows. Only that contact's chat; nothing is sent.
     */
    private fun undoDeclinedMarks(peerAddress: String) {
        fun wasMarked(
            peer: String,
            outgoing: Boolean,
            id: String,
            status: MessageStatus,
        ) = peer == peerAddress && outgoing && id.startsWith(RELAY_ROW_PREFIX) && status == MessageStatus.DECLINED
        pendingMessages.update { list ->
            list.map { m ->
                if (m.txId == null && wasMarked(m.peerAddress, m.isOutgoing, m.id, m.status)) {
                    m.copy(status = MessageStatus.SENT)
                } else {
                    m
                }
            }
        }
        zchatPreferences
            .getPendingMessages()
            .filter { row ->
                val stored = row.status?.let { runCatching { MessageStatus.valueOf(it) }.getOrNull() }
                stored != null && wasMarked(row.peerAddress, row.isOutgoing, row.id, stored)
            }.forEach { row -> zchatPreferences.addPendingMessage(row.copy(status = MessageStatus.SENT.name)) }
    }

    /**
     * Subscribe to inbound NIP-17 DMs surfaced by the foreground service. Each DM is
     * pushed into [pendingMessages] as a ChatMessage so it renders alongside on-chain
     * messages in the same conversation flow.
     */
    private fun observeNostrInbound() {
        viewModelScope.launch {
            // KI-24 fixup G-KI24-4: inboundReader tells the bridge each event this handler finished (not cancelled midway),
            // so the relay since line never passes one it was handed but never finished and marked seen.
            co.electriccoin.zcash.ui.nostr.NostrChatBridge.inboundReader.collect { chat ->
                // Resilience: a single malformed inbound (a bad timestamp, an unexpected field) must never
                // throw out of this lambda — that cancels the whole collector and silently dead-messages the
                // app until restart (a remotely-triggerable DoS). Swallow per-event failures (rethrowing
                // cancellation so structured concurrency still works) and keep collecting the next event.
                runCatching {
                // #9 RECEIPT MARK: receiving the value in this collector is PROOF the DM was actually delivered.
                // NostrChatBridge.dispatch no longer marks a subscriptionCount SNAPSHOT at emit time — a collector
                // can cancel before draining a replay=0 buffered value, which then vanishes yet was persisted as
                // seen = permanent DM loss (#9). Mark it seen HERE, on real receipt, so the persistent relay dedup
                // suppresses future replays. Skip UNATTRIBUTED_BOOT so an un-adopted #251 rotation announce can
                // still redeliver; the group path's own unmark-to-defer / re-mark-on-success runs AFTER this top
                // mark (ordering unchanged from when dispatch marked it before hand-off).
                if (chat.peerAddress != co.electriccoin.zcash.ui.nostr.NostrChatBridge.UNATTRIBUTED_BOOT) {
                    zchatPreferences.markNostrEventSeen(chat.eventId)
                }
                    // Round 8 MA3 (design §2.4, §6.1): the sender reads group member announces (its rumor carries gp1).
                    if (chat.peerAddress.isNotEmpty() &&
                        chat.rumorTags.any { it == co.electriccoin.zcash.ui.nostr.Nip17.GP_CAPABILITY_TAG }
                    ) {
                        recordGp1Capable(chat.peerAddress)
                    }
                    // SR-C1 (KI-37): what this rumor says about the contact's ZChat. Every relay rumor from a known contact
                    // counts (a text, a ZBOOT, a mode change, a receipt); NostrChatBridge.dispatch already dropped replays
                    // it had handled (KI-24), and the newest rumor by its own created_at wins, not the last to arrive.
                    if (chat.peerAddress.isNotEmpty()) recordPeerIronwoodCap(chat)
                    // ZC-1474 (W-123): the same rule for zatt1 (the contact reads a free attachment); newest rumor wins.
                    if (chat.peerAddress.isNotEmpty()) recordPeerZattCap(chat)
                    // ZC-1464: a contact who declined and now writes from its bound key (it bound our code later) has the chat
                    // again, so the decline no longer closes our composer. A decline or its undo is handled below.
                    if (chat.peerAddress.isNotEmpty() &&
                        RequestDecisionToken.parse(chat.plaintext) == null &&
                        zchatPreferences.isPeerRequestDeclined(chat.peerAddress)
                    ) {
                        zchatPreferences.setPeerRequestDeclined(chat.peerAddress, false)
                        undoDeclinedMarks(chat.peerAddress)
                    }
                    // ZC-1465: any relay rumor from the contact's bound key (a receipt, a mode change, a text) shows they have
                    // the chat, so the Open chat-request hint is off. A decline or its undo is no such evidence.
                    if (chat.peerAddress.isNotEmpty() &&
                        RequestDecisionToken.parse(chat.plaintext) == null &&
                        !zchatPreferences.wasPeerHeardFrom(chat.peerAddress)
                    ) {
                        zchatPreferences.markPeerHeardFrom(chat.peerAddress)
                    }
                // #252 ADOPTION SIGNAL (the SOLE safe writer of the peer's known-our-rotation index besides
                // first-contact seeding). chat.recipientPubkeyHex is the OUR-side pubkey this inbound actually
                // decrypted under — i.e. the rotation key the sender currently holds for us. Map it back to
                // our rotation index and advance the peer's known index to EXACTLY that — never further. This
                // (a) replaces the unsafe relay-ack advance (a relay ack only proves a wrap was STORED, not
                // fetched + adopted — advancing then STRANDED an offline peer on the next rotation, signing
                // with a key they never held); (b) is TOCTOU-safe — we match the REAL decrypting key, never a
                // re-read of the live rotation index, so a rotation racing this handler cannot over-advance;
                // (c) self-heals a peer who reached an OLD (grace-window) key — we advance to THAT old index
                // so the next announce re-signs with the key they DO hold, letting them jump forward instead
                // of stranding. Applies to ALL inbound from a known peer (DMs, files, reactions, attributed
                // ZBOOTs). Gated on known < cur so the (seed-touching) index scan runs only while a rotation
                // is unconfirmed. Harmless for v3/E2E peers (they verify rotations against our rotation-
                // invariant E2E key and never read this index). Empty peerAddress / blank pubkey are skipped.
                if (chat.peerAddress.isNotEmpty() && chat.recipientPubkeyHex.isNotBlank()) {
                    val cur = zchatPreferences.getNostrRotationIndex()
                    val known = zchatPreferences.getPeerKnownOurRotationIndex(chat.peerAddress)
                    if (known < cur) {
                        val reached = ourRotationIndexForPubkey(chat.recipientPubkeyHex, maxOf(0, known + 1), cur)
                        if (reached > known) {
                            zchatPreferences.setPeerKnownOurRotationIndex(chat.peerAddress, reached)
                            Log.d(
                                "ZCHAT_NOSTR",
                                "#252 ${chat.peerAddress.take(16)}… reached our NOSTR key idx $reached → known rotation idx advanced",
                            )
                        }
                    }
                }
                // Drop ZBOOT handshakes here — they're handled by routeIncomingBoot below.
                if (co.electriccoin.zcash.ui.screen.chat.model.ZBootMessage.isBootMessage(chat.plaintext)) {
                    // #251 — an UNATTRIBUTED ZBOOT (sender pubkey not yet known, e.g. a peer's rotated key)
                    // is mapped to its conversation by convId / signature first; an attributed one routes
                    // straight to the verify+adopt path. Either way the trust gate is inside routeIncomingBoot.
                    if (chat.peerAddress == co.electriccoin.zcash.ui.nostr.NostrChatBridge.UNATTRIBUTED_BOOT) {
                        // NOSTR delivery: attribution alone is enough (the row was never convId-keyed), so
                        // the resolved-peer return is intentionally ignored here.
                        attributeBoot(chat.plaintext)
                    } else {
                            // ZC-893 (FC-2B, 5.4b item 4): attributed by the relay key already bound at that address.
                            routeIncomingBoot(chat.peerAddress, chat.plaintext, sealedByBoundKey = true)
                    }
                    return@collect
                }
                // B17 — disappearing-messages TTL control over NOSTR. Authenticated: NostrChatBridge.dispatch
                // already drops DMs whose NIP-17 seal pubkey isn't a mapped peer, so chat.peerAddress is
                // sender-authentic; the key-changed gate mirrors sendReadReceipt's TOFU guard. Never rendered.
                if (co.electriccoin.zcash.ui.screen.chat.model.ZMSGProtocol.isDisappearSetting(chat.plaintext)) {
                    if (!zchatPreferences.isE2EKeyChanged(chat.peerAddress)) {
                        handleDisappearControl(chat.peerAddress, chat.plaintext)
                    } else {
                        Log.w("ZCHAT_TTL", "IGNORED disappear control from key-changed peer ${chat.peerAddress.take(12)}… (#187)")
                    }
                    return@collect
                }
                // Conversation-mode change control over NOSTR (ZMODE) — same authentication story as the
                // B17 ZEXP gate above: NIP-17 seal attribution + the key-changed TOFU guard. Never rendered.
                if (co.electriccoin.zcash.ui.screen.chat.model.ZMSGProtocol.isModeChange(chat.plaintext)) {
                    if (!zchatPreferences.isE2EKeyChanged(chat.peerAddress)) {
                        handleModeControl(chat.peerAddress, chat.plaintext)
                    } else {
                        Log.w("ZCHAT_MODE", "IGNORED mode control from key-changed peer ${chat.peerAddress.take(12)}… (#187)")
                    }
                    return@collect
                }
                // Self-avatar propagation over NOSTR (ZPROF) — a peer pushing their own photo, chunked +
                // reassembled, saved as this peer's contact avatar (last-writer-wins; a LOCAL override still
                // wins on render). Metadata, never a chat row. NostrChatBridge.dispatch already mapped the
                // NIP-17 seal pubkey to this known peer, so chat.peerAddress is sender-authentic; the
                // key-changed TOFU guard mirrors the ZMODE/ZEXP gate so a key-substituted peer can't silently
                // swap the saved photo. Avatars are NOSTR-only — there is deliberately no on-chain ZPROF path.
                if (co.electriccoin.zcash.ui.screen.chat.model.ZPROFMessage.isProfileMessage(chat.plaintext)) {
                    if (!zchatPreferences.isE2EKeyChanged(chat.peerAddress)) {
                        handleProfileAvatar(chat.peerAddress, chat.plaintext)
                    } else {
                        Log.w("ZCHAT_PROF", "IGNORED avatar from key-changed peer ${chat.peerAddress.take(12)}… (#187)")
                    }
                    return@collect
                }
                // Group protocol over NOSTR (#11) — invites/messages/signed-control delivered FREE via
                // NIP-17 instead of an on-chain memo. NostrChatBridge.dispatch already mapped the seal
                // pubkey to a known peer, so chat.peerAddress is sender-authentic; processGroupMessage
                // then applies the SAME per-type trust gates as the on-chain scan (compact-invite k2
                // requires the authenticated KEX session with the inviter; #187 signed kick/key; the
                // GROUP_ACCEPT #219 signature). There is no on-chain txId over NOSTR, so processGroupMsg
                // derives a DETERMINISTIC message id (group|sender|epoch|seq) — a relay REPLAYS stored
                // gift-wraps on every resubscribe, and a random id would insert the message N times.
                // Never rendered as a raw text bubble.
                if (co.electriccoin.zcash.ui.screen.chat.model.ZMSGGroupProtocol.isGroupMessage(chat.plaintext)) {
                    val groupTs = Instant.ofEpochSecond(chat.createdAtSec.coerceIn(0L, Instant.now().epochSecond))
                    // chat.peerAddress is the NIP-17-seal-authenticated sender — bind attribution to it
                    // (see processGroupMessage) so a member can't stamp another member's address on a
                    // GROUP_MSG/GROUP_LEAVE they publish over the (now free, unlimited) NOSTR channel.
                    processGroupMessage(chat.plaintext, null, groupTs, authenticatedSender = chat.peerAddress, nostrEventId = chat.eventId)
                    return@collect
                }
                // #7 leak: ZSTAT (user status) + ZRCPT (read receipt) are metadata, not chat rows. The
                // on-chain scan filters them (isStatus/isReadReceipt), but the NOSTR path did not — so a
                // status broadcast (published to every non-VAULT peer) arrived here and the raw
                // "ZSTAT|…|<addr-hash>" wire string was RENDERED + PERSISTED as a chat bubble, leaking the
                // internal envelope + a truncated address hash. Mirror the on-chain handlers here.
                if (co.electriccoin.zcash.ui.screen.chat.model.ZMSGProtocol.isStatus(chat.plaintext)) {
                    val parsedStatus =
                        co.electriccoin.zcash.ui.screen.chat.model.ZMSGProtocol.parseStatus(chat.plaintext, addressCache)
                    if (parsedStatus?.senderAddress != null) {
                        peerStatuses.update { it + (parsedStatus.senderAddress to UserStatus(parsedStatus.statusText)) }
                        zchatPreferences.setPeerStatus(parsedStatus.senderAddress, parsedStatus.statusText)
                    }
                    return@collect
                }
                    // ZC-1464: a decline of our chat request, or its undo, from the contact's seal-authenticated bound relay key
                    // (chat.peerAddress; a stranger's key never reaches here). Read before the receipt and Quantum Shield claim
                    // sinks; never a row. The on-chain path never acts on these tokens.
                    val requestDecision = RequestDecisionToken.parse(chat.plaintext)
                    if (requestDecision != null) {
                        if (chat.peerAddress.isNotEmpty()) onRequestDecision(chat.peerAddress, requestDecision)
                        return@collect
                    }
                if (co.electriccoin.zcash.ui.screen.chat.model.ZMSGProtocol.isReadReceipt(chat.plaintext)) {
                        // D3-2: a Quantum Shield claim is a ZRCPT| line; it is stored only through its gate, never a row.
                        recordQsPeerClaim(chat.peerAddress, chat.plaintext)
                    return@collect
                }
                // Clamp a sender-asserted (possibly future-skewed) timestamp to "now" so a peer can't
                // reorder the thread by pinning their message to the bottom with a future date.
                val ts = Instant.ofEpochSecond(chat.createdAtSec.coerceIn(0L, Instant.now().epochSecond))
                // An inbound ZREACT over NOSTR is metadata, not a chat row: attach it to the target
                // message's reactions (matched on ChatMessage.id == targetTxId) instead of rendering
                // the raw "ZREACT|…" memo as a text bubble. Mirrors the on-chain reactionsByTarget path.
                if (co.electriccoin.zcash.ui.screen.chat.model.ZMSGProtocol.isReaction(chat.plaintext)) {
                    val parsedReaction = co.electriccoin.zcash.ui.screen.chat.model.ZMSGProtocol.parseReaction(chat.plaintext, addressCache)
                    if (parsedReaction != null) {
                        val reaction = co.electriccoin.zcash.ui.screen.chat.model.MessageReaction(
                            emoji = parsedReaction.emoji,
                            senderAddress = parsedReaction.senderAddress ?: chat.peerAddress,
                            timestamp = ts,
                        )
                        // Dedup: relays REPLAY stored gift-wraps on every (re)subscribe and the same
                        // reaction is published to multiple relays, so without this guard a single
                        // "👍" would attach N times and the count badge would grow on every reconnect.
                        // Skip if the same sender already reacted with the same emoji to this target.
                        pendingMessages.update { current ->
                            current.map { m ->
                                if (m.id == parsedReaction.targetTxId &&
                                    m.reactions.none { it.emoji == reaction.emoji && it.senderAddress == reaction.senderAddress }
                                ) {
                                    m.copy(reactions = m.reactions + reaction)
                                } else {
                                    m
                                }
                            }
                        }
                        // #210: persist so the reaction survives the next pendingMessages reload (which
                        // overwrites the in-memory list from storage). The in-memory update above only
                        // matches a target still in pendingMessages; persisting unconditionally also
                        // covers a target that has already been re-persisted (re-applied on load).
                        zchatPreferences.addNostrReaction(
                            parsedReaction.targetTxId,
                            reaction.emoji,
                            reaction.senderAddress ?: chat.peerAddress,
                            ts.toEpochMilli(),
                        )
                    }
                    return@collect
                }
                // Strip an embedded reply-ref BEFORE any ZFILE/text parsing: the U+0001 marker prepends
                // the body (even a "ZFILE|…" body), so file detection and the visible bubble must run on
                // the stripped text — otherwise a reply-to-file arrives as raw "…RPL…ZFILE|…" text and
                // the reply threading + media render are both lost. replyToId threads the rendered bubble.
                // #224: a known peer's first OPEN message may arrive as a v4 INIT envelope (it carries
                // their address so a first-contact recipient can place them). Unwrap to the inner text
                // so we render the message, never the raw "ZMSG|v4|…INIT|…" string. Non-INIT content is
                // returned unchanged.
                val unwrappedPlaintext =
                    co.electriccoin.zcash.ui.screen.chat.model.ZMSGProtocol.parseV4Init(chat.plaintext)?.second
                        ?: chat.plaintext
                    // ZC-1480 item 2: the INIT's conversation id goes to the seal-authenticated sender (the address bound to the
                    // relay key), never to the address the INIT body claims, so a later on-chain v4 REPLY under that id finds
                    // this chat. setConversationMapping writes an id once (ZC-892).
                    ZMSGProtocol.parseV4InitConvId(chat.plaintext)?.let { convId ->
                        if (chat.peerAddress.isNotEmpty()) zchatPreferences.setConversationMapping(convId, chat.peerAddress)
                    }
                val (incomingReplyTo, incomingReplyPreview, strippedBody) = untagReply(unwrappedPlaintext)
                // Dedup on the unique gift-wrap event id (identical across relays for the SAME
                // message, distinct for different messages) — keying on content+timestamp would
                // collapse two distinct messages that share text within the same second.
                // #202: use the STABLE rumor id as the message id so a reaction/reply the SENDER attaches
                // to its own copy (also keyed on the rumor id) correlates to OUR copy here. Fall back to
                // the per-gift-wrap eventId for legacy peers that don't send a rumor id.
                val baseId = if (chat.rumorId.isNotEmpty()) "nmsg-${chat.rumorId}" else "nostr-${chat.eventId}"
                // Parse a ZFILE ref (image/file/voice sent over NOSTR) into a file bubble with the
                // file fields set, so the view auto-downloads + renders the media exactly like the
                // on-chain receive path. Without this, a file sent over NOSTR arrived as raw "ZFILE|…"
                // text and the image/file/voice never displayed or downloaded.
                    // ZC-1474 (W-123): a free attachment (ZATT) carries its file key. It is read only here, from the seal-authenticated
                    // bound relay key (chat.peerAddress, mapped by NostrChatBridge.dispatch); a malformed one is dropped, never shown.
                    // Its row keeps the line in the encrypted pending store until the download.
                    val nostrZatt =
                        if (ZATTMessage.isZatt(strippedBody)) {
                            if (chat.peerAddress.isEmpty()) return@collect
                            ZATTMessage.parse(strippedBody) ?: run {
                                Log.w("ZCHAT_FILE", "ZC-1474: malformed free attachment from a bound contact dropped")
                                return@collect
                            }
                        } else {
                            null
                        }
                val nostrFile = if (co.electriccoin.zcash.ui.screen.chat.model.ZFILEMessage.isFileMessage(strippedBody)) {
                    co.electriccoin.zcash.ui.screen.chat.model.ZFILEMessage.parse(strippedBody)
                } else {
                        nostrZatt?.toFileRef()
                }
                // An inbound payment REQUEST (ZREQ) over NOSTR must render as a request bubble (amount +
                // Pay affordance), NOT as a raw "ZREQ|…" string. The on-chain receive path parses this into
                // PaymentRequestInfo; the NOSTR path did not, so a request sent in TUNNEL/OPEN never appeared
                // on the recipient at all. Mirror the on-chain handling here.
                val nostrPaymentRequest = if (co.electriccoin.zcash.ui.screen.chat.model.ZMSGProtocol.isPaymentRequest(strippedBody)) {
                    co.electriccoin.zcash.ui.screen.chat.model.ZMSGProtocol.parsePaymentRequest(strippedBody, addressCache)
                } else {
                    null
                }
                val msg = if (nostrFile != null) {
                    ChatMessage(
                        id = baseId,
                        txId = null,
                        text = "📎 ${nostrFile.displayText}",
                        timestamp = ts,
                        isOutgoing = false,
                        peerAddress = chat.peerAddress,
                        isPending = false,
                        status = MessageStatus.SENT,
                        replyToId = incomingReplyTo,
                        replyToPreview = incomingReplyPreview,
                        fileHash = nostrFile.hash,
                        fileZfileContent = strippedBody,
                        fileBlurhash = nostrFile.blurhash.takeIf { it.isNotEmpty() },
                        fileType = nostrFile.type,
                        fileViewOnce = nostrFile.viewOnce,
                        fileViewed = nostrFile.viewOnce && zchatPreferences.isFileViewed(nostrFile.hash),
                        // D9: NIP-17 seal already authenticates the sender (unmapped pubkeys are
                        // dropped upstream), so NOSTR-delivered rows are always authenticated.
                        authenticated = true,
                    )
                } else if (nostrPaymentRequest != null) {
                    ChatMessage(
                        id = baseId,
                        txId = null,
                        text = nostrPaymentRequest.reason.ifEmpty { "Payment request" },
                        timestamp = ts,
                        isOutgoing = false,
                        peerAddress = chat.peerAddress,
                        isPending = false,
                        status = MessageStatus.SENT,
                        replyToId = incomingReplyTo,
                        replyToPreview = incomingReplyPreview,
                        paymentRequest = PaymentRequestInfo(
                            amountZatoshi = nostrPaymentRequest.amountZatoshi,
                            reason = nostrPaymentRequest.reason,
                            isPaid = paidRequestIds.value.contains(baseId),
                            paidTxId = null,
                        ),
                        // D9: NIP-17 seal authenticates the sender.
                        authenticated = true,
                    )
                } else {
                    ChatMessage(
                        id = baseId,
                        txId = null,
                        text = strippedBody,
                        timestamp = ts,
                        isOutgoing = false,
                        peerAddress = chat.peerAddress,
                        isPending = false,
                        status = MessageStatus.SENT,
                        replyToId = incomingReplyTo,
                        replyToPreview = incomingReplyPreview,
                        // D9: NIP-17 seal authenticates the sender.
                        authenticated = true,
                    )
                }
                    // M1: a relay-only chat is not Shielded by default. Before the row is stored, a chat with no stored mode and
                    // no E2E key either way (nothing ever went on-chain: a contact whose code was pasted without a send, then who
                    // wrote first over the relays) becomes Open, unpinned, so its composer is free and a later ZMODE can still be
                    // adopted. A chat with an E2E key (on-chain history) or any stored mode is never changed.
                    openRelayOnlyChatIfUnset(chat.peerAddress)
                // Deduplicate — the same gift-wrap may arrive on multiple relays.
                var addedNew = false
                pendingMessages.update { current ->
                    if (current.any { it.id == msg.id }) {
                        current
                    } else {
                        addedNew = true
                        current + msg
                    }
                }
                    // ZC-421: a second copy of a message already shown (another wrap of the same rumor, e.g. a Retry's) is skipped.
                    if (!addedNew) {
                        val shown = msg.id.removePrefix(RELAY_ROW_PREFIX).take(8)
                        Log.d("ZCHAT_NOSTR", "relay message $shown already shown: second copy skipped")
                    }
                // Persist the inbound NOSTR row so it survives process death / ChatViewModel recreation
                // (it has no ledger entry to rebuild from). Keyed on msg.id (the unique gift-wrap event id),
                // so a replayed gift-wrap upserts the same record rather than duplicating it.
                if (addedNew) {
                    // QA oracle (debug-only, no-op in release): per-message accept event for the
                    // on-device runner. Redacted/hashed fields only — never plaintext (see InboundDiag).
                    InboundDiag.logMessageAdded(msg, InboundDiag.TRANSPORT_NOSTR)
                        // ZC-1366: the contact wrote over the relays: the ZC-1352 withdrawn mark lifts.
                        userStartsSetupAgain(msg.peerAddress)
                    zchatPreferences.addPendingMessage(
                        ZchatPreferences.PendingMessageData(
                            id = msg.id,
                            text = msg.text,
                            timestampMillis = msg.timestamp.toEpochMilli(),
                            peerAddress = msg.peerAddress,
                            isOutgoing = false,
                            isPending = false,
                            status = MessageStatus.SENT.name,
                            replyToId = msg.replyToId,
                            replyToPreview = msg.replyToPreview,
                            fileZfileContent = msg.fileZfileContent,
                            // Persist the ZREQ amount/reason so a restart rebuilds the request bubble
                            // (amount + Pay button) instead of a bare text row (#payment-req-lost-on-restart).
                            paymentRequestAmountZatoshi = msg.paymentRequest?.amountZatoshi,
                            paymentRequestReason = msg.paymentRequest?.reason
                        )
                    )
                }
                }.onFailure { e ->
                    if (e is kotlinx.coroutines.CancellationException) throw e
                    Log.e("ZCHAT_NOSTR", "inbound processing failed for ${chat.eventId.take(8)}… — skipped", e)
                }
            }
        }
    }

    /** M1 — see the call in [observeNostrInbound]. */
    private fun openRelayOnlyChatIfUnset(peerAddress: String) {
        if (zchatPreferences.getConversationModeOrNull(peerAddress) != null) return
        if (zchatPreferences.getE2EOurPublicKey(peerAddress) != null || zchatPreferences.getE2EPeerPublicKey(peerAddress) != null) return
        zchatPreferences.setConversationMode(peerAddress, co.electriccoin.zcash.ui.screen.chat.model.ConversationMode.OPEN)
        Log.d("ZCHAT_NOSTR", "relay-only chat with no mode set to Open (not pinned)")
    }

    /**
     * #251 — attribute an UNATTRIBUTED rotation ZBOOT (one that arrived over NOSTR from a sender pubkey
     * we do NOT yet hold — a peer's NEW key after rotation, or an idx-pre-swapped seal) to the right
     * established conversation, then let [routeIncomingBoot] authenticate + adopt it.
     *
     * Why this is needed: inbound DMs are mapped to a peer by SENDER pubkey ([NostrChatBridge.dispatch]),
     * but a rotation announce by definition arrives from a key we don't hold yet, so it could never reach
     * routeIncomingBoot and the rotated peer was permanently stranded (the #251 root cause).
     *
     * Attribution is ROUTING ONLY — the cryptographic trust gate is ENTIRELY inside [routeIncomingBoot]
     * (E2E-signature verify for v2/v3, Schnorr-vs-currently-known-NOSTR-key for v4, + epoch monotonicity
     * + the v4 downgrade guard). So a forged ZBOOT either maps to no peer or FAILS verification and is
     * dropped; nothing here grants trust.
     *   1) convId fast-path: the ZBOOT carries its convId; if we hold that mapping, try that peer.
     *   2) signature attribution: otherwise try each established conversation peer — routeIncomingBoot
     *      adopts ONLY the one whose stored key verifies the signature (every wrong peer returns false at
     *      the verify step BEFORE any state mutation or dedup mark, so iterating is side-effect-free for
     *      non-matches). Covers pure-OPEN (#224) pairs that never exchanged a convId mapping.
     *
     * @return the REAL peer address this ZBOOT was authenticated + adopted to (a Zcash UA), or null if no
     *   established peer's stored key verified it (forged / unrelated / E2E key not yet exchanged). The
     *   on-chain ZBOOT render path uses the returned address to re-key the row onto the real conversation
     *   (so it stops showing the misleading convId-keyed "Unknown sender" banner); the NOSTR caller ignores
     *   it (attribution is enough there). Trust is UNCHANGED — routeIncomingBoot remains the sole gate.
     */
    private fun attributeBoot(raw: String): String? {
        val boot = co.electriccoin.zcash.ui.screen.chat.model.ZBootMessage.parse(raw) ?: return null
        // 1) convId fast-path.
        zchatPreferences.getPeerByConversationId(boot.convId)?.let { peer ->
            if (routeIncomingBoot(peer, raw)) {
                Log.d("ZCHAT_NOSTR", "#251 adopted unknown-sender rotation via convId for ${peer.take(16)}…")
                return peer
            }
        }
        // 2) authenticated signature-attribution fallback (no convId mapping required). routeIncomingBoot
        // verifies the signature against EACH candidate's stored key and adopts only the true owner.
        for (peer in zchatPreferences.getAllConversationPeerAddresses()) {
            if (routeIncomingBoot(peer, raw)) {
                Log.d("ZCHAT_NOSTR", "#251 adopted unknown-sender rotation via signature-attribution for ${peer.take(16)}…")
                return peer
            }
        }
        Log.d("ZCHAT_NOSTR", "#251 unknown-sender ZBOOT matched no established peer — dropping (forged/unrelated)")
        return null
    }

    /**
     * A ZBOOT can arrive either via a shielded memo (handled in convertToConversations)
     * or via NOSTR if a peer published their boot through the relay. Either way: stash
     * the pubkey + relay so future routeOutgoing() calls pick NostrDirect.
     */
    /**
     * @return true ONLY if the ZBOOT verified and the peer's NOSTR pubkey was stored (the call/DM
     * channel is now actually established). false on every drop path (unverifiable, bad signature,
     * key-changed) — the caller MUST NOT claim "connection established" when this returns false, or
     * the UI lies (shows "established" while no pubkey is stored and calls can't route). This was the
     * bug: the on-chain ZBOOT handler printed the established system note unconditionally.
     *
     * ZC-893 (FC-2B, 5.4b items 4 and 5): [sealedByBoundKey] is true only from the relay reader's attributed call (the
     * relay key already bound at [peerAddress] sealed it, and the reader has marked that event seen), false from
     * [attributeBoot]. A v2/v3 ZBOOT signed with a key this phone never asked for ([holdsUnaskedKey]) is believed only
     * when sealed so; such a key does not count for the v4 downgrade guard.
     */
    private fun routeIncomingBoot(
        peerAddress: String,
        raw: String,
    ): Boolean = routeIncomingBoot(peerAddress, raw, sealedByBoundKey = false)

    /** [routeIncomingBoot]; [sealedByBoundKey]: see the two-argument form (that is [attributeBoot]'s, never sealed). */
    private fun routeIncomingBoot(
        peerAddress: String,
        raw: String,
        sealedByBoundKey: Boolean,
    ): Boolean = routeIncomingBoot(peerAddress, raw, sealedByBoundKey, ZbootOnChainRule.QUOTED_IN_SHIELDED)

    /**
     * [routeIncomingBoot]; [replyRule] is the rule of our reply ZBOOT: [ZbootOnChainRule.QUOTED_IN_SHIELDED] for every
     * delivery, [ZbootOnChainRule.RELAY_ONLY] for the hand-over of a held ZBOOT (ZC-634, 5.5 item 9: the release by "Mark
     * as verified" or by the proof pays nothing).
     *
     * ZC-634 (FC-5, 5.5 items 3, 4, 6): while [peerAddress]'s contact key is only a claim ([ZchatPreferences.getKeyClaim]),
     * a v2/v3 ZBOOT that would bind where no relay key is bound, or announce another relay key than the bound one, binds
     * nothing unless the bound relay key sealed it: refused, unrecorded, no key-changed flag, no note, no reply, no flush,
     * and kept as the held ZBOOT. A sealed one is adopted and releases the mark (the older identity vouches for the key).
     * The v4 downgrade guard does not apply while a mark stands.
     */
    private fun routeIncomingBoot(
        peerAddress: String,
        raw: String,
        sealedByBoundKey: Boolean,
        replyRule: ZbootOnChainRule,
    ): Boolean {
        // parse() accepts only the SIGNED v2 ZBOOT; unsigned/malformed are dropped.
        val boot = co.electriccoin.zcash.ui.screen.chat.model.ZBootMessage.parse(raw) ?: return false
        // AUTHENTICATE before trusting the NOSTR identity. Shielded receives hide the real sender and
        // the memo's address field is attacker-controlled plaintext, so we MUST verify the ZBOOT was
        // signed by the peer's KEX-verified E2E identity key — otherwise an attacker could inject a
        // ZBOOT claiming any NOSTR pubkey and MITM every NOSTR DM and voice/video call.
        val peerE2EPub = zchatPreferences.getE2EPeerPublicKey(peerAddress)
        val ok: Boolean
        if (boot.version >= 4) {
            // v4 = NOSTR-key-signed rotation (#250) — OPEN peers have no E2E identity. Authenticate the
            // ZBOOT against the peer's CURRENTLY-KNOWN NOSTR pubkey (their old key): only its holder can
            // sign a valid rotation to the new key, so trust chains from the TOFU-bound old key.
            // DOWNGRADE GUARD: refuse a v4 boot for any peer we hold an E2E key for — that peer must use
            // the stronger E2E-signed v3, else an attacker holding only the weaker NOSTR key could rotate
            // an E2E-bound peer and MITM the chat.
            // ZC-634 (5.5 item 4): a contact key that is only a claim must not stop the bound relay identity's own next key.
            if (peerE2EPub != null && !holdsUnaskedKey(peerAddress) && zchatPreferences.getKeyClaim(peerAddress) == null) {
                Log.w("ZCHAT_NOSTR", "v4 NOSTR-signed ZBOOT refused for E2E-bound peer ${peerAddress.take(16)}… (downgrade guard)")
                return false
            }
            val knownNostr = zchatPreferences.getPeerNostrPubkey(peerAddress)
            if (knownNostr == null) {
                Log.w("ZCHAT_NOSTR", "v4 ZBOOT from ${peerAddress.take(16)}… ignored: no known NOSTR identity to authenticate against")
                return false
            }
            val sigBytes = hexToBytesOrNull(boot.signature)
            val pubBytes = hexToBytesOrNull(knownNostr)
            ok = sigBytes != null && pubBytes != null &&
                co.electriccoin.zcash.ui.nostr.NOSTRIdentity.verifyHashSchnorr(sigBytes, sha256Bytes(boot.signedData()), pubBytes)
        } else {
            // v2/v3 = E2E-signed (TUNNEL/VAULT). A shielded receive hides the real sender, so we MUST
            // verify the ZBOOT was signed by the peer's KEX-verified E2E identity key — otherwise an
            // attacker could inject a ZBOOT claiming any NOSTR pubkey and MITM every NOSTR DM and call.
            if (peerE2EPub == null) {
                Log.w("ZCHAT_NOSTR", "ZBOOT from ${peerAddress.take(16)}… ignored: no verified E2E identity yet (complete key exchange first)")
                return false
            }
            // ZC-893 (FC-2B, 5.4b item 4): a key this phone never asked for vouches for nothing (not recorded, so the same
            // ZBOOT is read again once that key counts).
            if (!sealedByBoundKey && holdsUnaskedKey(peerAddress)) {
                Log.w("ZCHAT_NOSTR", "ZBOOT from ${peerAddress.take(16)}… ignored: signed by a key this phone never asked for")
                return false
            }
            ok = runCatching {
                E2EEncryption.verify(peerE2EPub, boot.signedData(), boot.signature)
            }.getOrDefault(false)
        }
        if (!ok) {
            Log.w("ZCHAT_NOSTR", "ZBOOT signature INVALID for ${peerAddress.take(16)}… — possible MITM, ignoring")
            return false
        }
        // ZC-634, ZC-950 (FC-4, 5.5 item 1): while a key waits for Accept it binds nothing: no relay key, no mode, no flush
        // of waiting Tunnel messages. Not recorded, so a later pass or delivery adopts the same ZBOOT after the tap. A
        // ZBOOT the relay key already bound there sealed is exempt; so is one whose waiting key this wallet's own mined
        // answer settled (the pass drops that hold, ZC-949).
        if (boot.version < 4 && !sealedByBoundKey && zchatPreferences.getInboundKexAwaitingAccept(peerAddress) != null) {
            // ZC-634 (5.5 item 3): where a claim mark stands beside the hold, the mark keeps the ZBOOT for after the tap.
            // ZC-1346: with no mark it has a slot beside the hold: it binds nothing, and the relay key it names is kept for.
            if (zchatPreferences.getKeyClaim(peerAddress) != null) {
                zchatPreferences.holdClaimedBoot(peerAddress, raw)
            } else {
                zchatPreferences.holdAcceptWaitingBoot(peerAddress, raw)
            }
            Log.w("ZCHAT_NOSTR", "ZBOOT from ${peerAddress.take(16)}… held back: its key waits for Accept")
            return false
        }
        // ZC-634 (FC-5, 5.5 item 3): a claimed key moves no relay identity. Only a ZBOOT that verified against the stored
        // contact key gets here, so only that key's holder can fill the held slot.
        val claimStands = boot.version < 4 && zchatPreferences.getKeyClaim(peerAddress) != null
        if (claimStands && !sealedByBoundKey) {
            val bound = zchatPreferences.getPeerNostrPubkey(peerAddress)
            if (bound == null || !bound.equals(boot.senderNostrPubkeyHex, ignoreCase = true)) {
                // ZC-1070 (c): a mark that went between the check and the hold (the user's "Mark as verified") leaves an
                // unmarked contact's ZBOOT, read on below; a mark that still stands keeps it held.
                if (zchatPreferences.holdClaimedBoot(peerAddress, raw) || zchatPreferences.getKeyClaim(peerAddress) != null) {
                    Log.w("ZCHAT_NOSTR", "ZBOOT from ${peerAddress.take(16)}… held back: this chat's key is not confirmed")
                    return false
                }
            } else {
                // Review of part B, finding 2: it names the relay key already bound, so it is a flush only: a claim writes
                // no relay URL (our publishes would follow it), no epoch (the contact's own rotations would read as stale)
                // and clears no key-changed flag (the one signal left when the contact's real answer arrives). Not recorded.
                flushTunnelPendingPayloads(peerAddress, bound)
                Log.d("ZCHAT_NOSTR", "ZBOOT of a claimed key names the bound relay key of ${peerAddress.take(16)}… — flush only")
                return true
            }
        }
        // W-72 (ZC-847, SPEC_F R3): a key stored before this build moves no relay identity either. Unlike a claim, a ZBOOT
        // the bound relay key sealed passes and leaves the mark (that relay key may be the plant's own); v4 is as before.
        if (boot.version < 4 && !sealedByBoundKey && zchatPreferences.getLegacyKeyMark(peerAddress) != null) {
            val bound = zchatPreferences.getPeerNostrPubkey(peerAddress)
            if (bound == null || !bound.equals(boot.senderNostrPubkeyHex, ignoreCase = true)) {
                // Review of 3426ade7d, finding 2 (as ZC-1070 (c) for the claim): a mark that went between the check and the
                // hold (the user's tap, or the probe's answer) leaves an unmarked contact's ZBOOT, read on below; a mark that
                // still stands keeps it held.
                if (zchatPreferences.holdLegacyBoot(peerAddress, raw) || zchatPreferences.getLegacyKeyMark(peerAddress) != null) {
                    Log.w("ZCHAT_NOSTR", "ZBOOT from ${peerAddress.take(16)}… held back: this chat's key was saved before 2.13")
                    return false
                }
            } else {
                // As a claim's (c94569c8e): it names the bound relay key, so a flush only; no relay URL, epoch or flag, not
                // recorded.
                flushTunnelPendingPayloads(peerAddress, bound)
                return true
            }
        }
        // FLOOD GUARD: the ON-CHAIN ZBOOT path re-runs routeIncomingBoot on EVERY convertToConversations
        // rebuild (per sync, per pendingMessages change) with NO per-tx dedup. Now that we ADOPT (not
        // reject) a verified pubkey change, re-processing historical ZBOOTs that carry DIFFERENT pubkeys
        // oscillates the stored key and emits a rotation pill each pass (→ thousands of pills). Dedup on
        // the ZBOOT's signature (stable per on-chain memo, unique per distinct ZBOOT) so each distinct
        // ZBOOT is acted on EXACTLY ONCE. A replay / re-scan short-circuits here: idempotent, no re-adopt,
        // no pill, no oscillation. Return whether a NOSTR identity is established so the caller's
        // "established" vs "in-progress" note stays correct. (NOSTR-delivered ZBOOTs are also eventId-
        // deduped upstream in dispatch; this covers the on-chain re-scan path.)
        // Dedup ZBOOTs in their OWN bounded store (hasProcessedBootSig), NOT the shared KEX-txid set:
        // fast-churning ZBOOT signatures used to evict genuine KEX/KEXACK txids from that FIFO, so a
        // later history re-scan re-processed a superseded OLD-key KEX and raised a false key-change.
        if (zchatPreferences.hasProcessedBootSig(boot.signature)) {
            // Already-processed sig ≠ nothing to do: with list + detail ChatViewModel instances both
            // collecting the same inbound flow, the OTHER instance may have claimed the sig (and run the
            // adopt) while THIS instance still holds queued TUNNEL payloads (process-wide outbox) or its
            // own "waiting for secure connection" placeholders. flushTunnelPendingPayloads is idempotent
            // (atomic process-wide queue claim + local placeholder cleanup), so always kick it when the
            // peer's NOSTR key is known — this was the dedup short-circuit that stranded the queued first
            // message forever (#38).
            val knownPub = zchatPreferences.getPeerNostrPubkey(peerAddress)
            if (knownPub != null) flushTunnelPendingPayloads(peerAddress, knownPub)
            return knownPub != null
        }
        zchatPreferences.markBootSigProcessed(boot.signature)
        // #225 EPOCH MONOTONICITY GUARD (signed replay-downgrade defense). Every ZBOOT carries the sender's
        // NOSTR rotation index as a signed `epoch` (inside signedData, so it can't be tampered with). We only
        // ever ADOPT a ZBOOT whose epoch is >= the highest we've already adopted for this peer. A re-scanned
        // historical ZBOOT or a network-replayed old one carries a LOWER epoch (it predates the rotation) and
        // is dropped here — so a stale handshake can NEVER downgrade the live pubkey back to a dead key, even
        // if the signature dedup above evicted it from its bounded LRU. (The flood fix made re-processing a
        // no-op per-signature; this makes re-adoption monotonic regardless of on-chain scan order or LRU
        // eviction.) Equal epoch is allowed (idempotent re-derivation of the same index → same pubkey). Note:
        // a peer who seed-restores resets its own index to 0; its epoch-0 ZBOOT would be dropped here against
        // our higher stored epoch — recovery is the peer rotating forward past our stored epoch or a re-KEX
        // (a deliberate fresh-start signal), which is the correct conservative behavior for an unordered
        // lower-epoch key change that is otherwise indistinguishable from a replay at this layer.
        val storedEpoch = zchatPreferences.getPeerBootEpoch(peerAddress)
        if (boot.epoch < storedEpoch) {
            Log.w(
                "ZCHAT_NOSTR",
                "ZBOOT from ${peerAddress.take(16)}… ignored: stale epoch ${boot.epoch} < adopted $storedEpoch (replay / re-scan)",
            )
            // Stale boot, but the peer's CURRENT key is on file — same idempotent flush as the
            // sig-dedup path so a queued first message can't be stranded by a replay arriving first.
            val knownPub = zchatPreferences.getPeerNostrPubkey(peerAddress)
            if (knownPub != null) flushTunnelPendingPayloads(peerAddress, knownPub)
            return knownPub != null
        }
        // REVERSE-UNIQUENESS (finding [11]): v4 only proves the sender holds the OLD (currently-known)
        // key — it NEVER proves possession of the ANNOUNCED new key. So refuse to adopt an announced
        // pubkey that is already bound to a DIFFERENT peer, or one attacker key ends up mapped to two
        // peer entries and findPeerByNostrPubkey (inbound DM dispatch) mis-attributes the genuine
        // owner's messages. Raw compare + '!= peerAddress' (mirrors acceptMessageRequest): idempotent
        // re-processing and genuine same-peer rotations (which announce a FRESH key → no prior binding)
        // are untouched.
        val priorPeerForKey = zchatPreferences.findPeerByNostrPubkey(boot.senderNostrPubkeyHex)
        if (priorPeerForKey != null && priorPeerForKey != peerAddress) {
            Log.w("ZCHAT_NOSTR", "ZBOOT REFUSED: announced NOSTR key already bound to a different peer (pubkey reuse)")
            return false
        }
        // #225 AUTHENTICATED ROTATION (not MITM): the ZBOOT above is verified against the peer's STORED
        // E2E identity key. A NOSTR-key rotation does NOT change that E2E key, so a ZBOOT carrying a
        // DIFFERENT NOSTR pubkey that STILL verifies is a legitimate self-rotation by the same owner — an
        // attacker can't forge this signature without the peer's E2E private key. So we ADOPT the new
        // pubkey and CONTINUE the same chat, rather than flagging the (blocking) key-changed banner.
        // A true MITM would carry a different E2E key, whose ZBOOT would FAIL verification above and never
        // reach here. (The old guard conflated the two and wedged every rotation — #225 root cause.)
        val existing = zchatPreferences.getPeerNostrPubkey(peerAddress)
        val isRotation = existing != null && existing != boot.senderNostrPubkeyHex
        zchatPreferences.setPeerNostrPubkey(peerAddress, boot.senderNostrPubkeyHex)
        zchatPreferences.setPeerNostrRelay(peerAddress, boot.relayUrl)
        // Advance the adopted epoch (boot.epoch >= storedEpoch is guaranteed by the guard above), so any
        // future LOWER-epoch ZBOOT for this peer is recognised as stale and can't downgrade this key.
        zchatPreferences.setPeerBootEpoch(peerAddress, boot.epoch)
        // ZC-634 (5.5 item 6): sealed by the bound relay key, the older identity vouches for the claimed key. The binding is
        // written first, then the mark goes: a kill in between leaves a right binding with a mark, the safe side.
        if (claimStands && sealedByBoundKey) zchatPreferences.releaseKeyClaim(peerAddress, verified = false)
        // The ZBOOT verified against our STORED E2E identity key above — which proves the sender holds
        // that key (a genuine E2E-key change / MITM would have FAILED verification and never reached
        // here). So clear any stale "key changed" flag that may be blocking sends to this peer, letting
        // a legitimate rotation auto-recover a previously-flagged conversation (#225 review).
        val flaggedBefore = zchatPreferences.isE2EKeyChanged(peerAddress)
        zchatPreferences.setE2EKeyChanged(peerAddress, false)
        clearKeyChangeRefusal(peerAddress)
        // ZC-739: only when that clear took the flag down (it changes nothing while a refused key is remembered).
        val keyDecided = flaggedBefore && !zchatPreferences.isE2EKeyChanged(peerAddress)
        if (isRotation) {
            // E2E verification stays intact (identity key unchanged); surface a non-blocking notice so the
            // user knows their contact rotated and the chat continued seamlessly.
            emitKeyRotationNote(peerAddress)
            Log.d("ZCHAT_NOSTR", "Peer ${peerAddress.take(16)}… rotated NOSTR key — adopted (authenticated by unchanged E2E identity), chat continues")
        }
        // Recipient-side mode sync: completing the bootstrap as the RESPONDER (we received the peer's
        // ZBOOT for a tunnel THEY initiated) means NOSTR is now available with this peer — so SILENTLY
        // follow to TUNNEL. This covers the never-set default AND an auto-adopted Shielded (VAULT)
        // chat: a peer bootstrapping a tunnel is unambiguously ON Tunnel, and the old "only when unset"
        // guard left the receiver asymmetric — sender's header said "tunnel" + its first message waited
        // on NOSTR delivery forever while the receiver kept charging on-chain per reply ("stuck
        // shielded"). Auto-adopting TUNNEL is money-SAFE (free transport; strictly cheaper than VAULT)
        // — the opposite direction, a peer moving us onto PAID Shielded, still always prompts (#187,
        // handleModeControl). An OPEN chat stays OPEN: it already routes free over NOSTR, and a peer's
        // rotation ZBOOT must not demote it. Re-scans are no-ops via the zboot-signature dedup above.
        //
        // HIGH-005 guard: an EXPLICITLY user-pinned Shielded chat is NEVER silently demoted — only the
        // user pins a mode, and any verified ZBOOT (incl. a routine rotation) must not override that
        // choice (mirrors handleModeControl's isConversationModeExplicit rule). The mode picker still
        // lets them match the peer anytime.
        //
        // Round 10b R10B-1 (F-R9C-1): the rule above holds only for the RESPONDER. When our own ZBOOT to this peer has
        // already gone out, we started this handshake and this ZBOOT is the peer's REPLY to ours: nothing about it says
        // the peer is on Tunnel (a pinned-Shielded peer replies too), so the chat keeps its mode and no note is shown.
        // Nothing between the top of this function and here writes our delivered-identity marker, so this is its value
        // at entry; our own reply below runs after it.
        val ownBootDelivered = zchatPreferences.getSentNostrBootPubkey(peerAddress) != null
        val modeBeforeBoot = zchatPreferences.getConversationModeOrNull(peerAddress)
        val pinnedVault = modeBeforeBoot == co.electriccoin.zcash.ui.screen.chat.model.ConversationMode.VAULT &&
            zchatPreferences.isConversationModeExplicit(peerAddress)
        val adoptsTunnel =
            !ownBootDelivered &&
                !pinnedVault &&
                (modeBeforeBoot == null || modeBeforeBoot == co.electriccoin.zcash.ui.screen.chat.model.ConversationMode.VAULT)
        if (ownBootDelivered) {
            Log.d("ZCHAT_NOSTR", "ZBOOT answers ours: mode of ${peerAddress.take(16)}… kept (${modeBeforeBoot?.name ?: "unset"})")
        } else if (adoptsTunnel) {
            zchatPreferences.setConversationMode(
                peerAddress,
                co.electriccoin.zcash.ui.screen.chat.model.ConversationMode.TUNNEL,
            )
            // B7b — tell the user their chat's transport just changed under them (once per adopted epoch;
            // the zboot-signature dedup makes re-scans no-ops). Informational pill, not a prompt.
            emitSystemNote(
                peerAddress,
                co.electriccoin.zcash.ui.screen.chat.model.SysNotes.modeUpgradeNoteId(peerAddress, boot.epoch),
                noteCopy.get(R.string.chat_note_tunnel_established),
            )
            Log.d("ZCHAT_NOSTR", "Responder bootstrap complete — adopted TUNNEL for ${peerAddress.take(16)}… (was ${modeBeforeBoot?.name ?: "unset"})")
        } else if (pinnedVault) {
            Log.d("ZCHAT_NOSTR", "ZBOOT bootstrap: kept user-pinned Shielded for ${peerAddress.take(16)}… (no silent demote)")
        }
        Log.d("ZCHAT_NOSTR", "Bootstrapped (verified) with ${peerAddress.take(16)}… on ${boot.relayUrl}")
        // Peer NOSTR key now known → flush any TUNNEL messages queued while it was unknown (these were
        // held off-chain, never charged) so they go out over NOSTR now instead of being lost.
        flushTunnelPendingPayloads(peerAddress, boot.senderNostrPubkeyHex)
        // Reply with OUR ZBOOT so the handshake completes BOTH ways — otherwise it's one-way and every
        // Call tap just re-requests. We reply with a ZBOOT (NOT a KEX): the KEX can't carry the NOSTR
        // pubkey on first contact (the address fills the 512-byte memo), and by now the peer holds our
        // E2E key (they verified this inbound ZBOOT's counterpart KEX) so they can authenticate ours.
        //
        // CRITICAL: gate on "have WE sent OUR identity?" (sendNostrBootHandshake's internal
        // getSentNostrBootPubkey guard), NOT on "do we already have THEIRS?" (`existing`). Those differ:
        // a peer who re-processed our OLD on-chain ZBOOT from chain history (reinstall + rescan, or a
        // half-finished prior handshake) ALREADY holds our pubkey (`existing != null`) yet has NEVER
        // sent us theirs — gating on `existing == null` would skip the reply forever and the tunnel
        // stays one-way (the exact stale-state deadlock seen in 2-device testing). Always calling
        // sendNostrBootHandshake fixes that; its idempotency (skip if we already sent THIS identity)
        // still prevents a ZBOOT ping-pong: once we've delivered ours, a later inbound ZBOOT is a no-op.
        // Round 10b R10B-1: in a Shielded chat only for free over the relays (the peer's relay key was just stored),
        // unless a confirmed first-message question quoted our on-chain ZBOOT.
        // ZC-634 (5.5 item 9): the hand-over of a held ZBOOT replies over the relays only.
        sendNostrBootHandshake(peerAddress, replyRule)
        // SR-B1: a chat that just adopted Tunnel (it left Shielded, or its unset Shielded default), or any chat that is not
        // Shielded and whose relay key we only now hold, gets our avatar now, after our reply ZBOOT is on its way. A no-op
        // unless the contact is owed it (a pinned Shielded chat never is).
        pushSelfAvatarTo(peerAddress)
        // ZC-739: the flag came down here, so what waited for it starts (the queued Tunnel messages and our reply went above).
        if (keyDecided) resumeAfterKeyDecision(peerAddress)
        return true
    }

    /**
     * #225 — insert a local, non-badging system note that a contact rotated their NOSTR key and the
     * chat continued seamlessly. In-memory only (informational; fine to vanish on reload). Excluded from
     * the unread count (isSystemNote) and rendered as a centered pill, not a sender bubble.
     */
    private fun emitKeyRotationNote(peerAddress: String) {
        // ONE stable pill per peer (overwritten on each rotation) so a hostile/buggy contact can't flood
        // the chat with unbounded persisted pills; the ZBOOT-signature dedup upstream stops re-processing.
        emitSystemNote(
            peerAddress,
            co.electriccoin.zcash.ui.screen.chat.model.SysNotes.rotationNoteId(peerAddress),
            "🔑 Your contact rotated their encryption key — this chat continues securely. " +
                "You can rotate yours too from the chat menu.",
        )
    }

    /**
     * Emit a persisted in-chat SYSTEM NOTE (centered pill). Persisted via addPendingMessage (id-keyed, so
     * re-emission with the same id is an idempotent overwrite — never a duplicate) AND broadcast via
     * NostrChatBridge.emitLocalMessage so EVERY ChatViewModel instance (list + detail — the #226 two-VM
     * problem) renders it live; the collector id-dedups (incl. the emitting VM itself).
     */
    private fun emitSystemNote(peerAddress: String, id: String, text: String) {
        val now = System.currentTimeMillis()
        zchatPreferences.addPendingMessage(
            co.electriccoin.zcash.ui.screen.chat.datasource.ZchatPreferences.PendingMessageData(
                id = id,
                text = text,
                timestampMillis = now,
                peerAddress = peerAddress,
                isOutgoing = false,
                isPending = false,
                status = MessageStatus.SENT.name,
            )
        )
        co.electriccoin.zcash.ui.nostr.NostrChatBridge.emitLocalMessage(
            ChatMessage(
                id = id,
                txId = null,
                text = text,
                timestamp = Instant.ofEpochMilli(now),
                isOutgoing = false,
                peerAddress = peerAddress,
                isPending = false,
                status = MessageStatus.SENT,
                isSystemNote = true,
            )
        )
    }

    /**
     * #225 — announce a NOSTR-key rotation to [peerAddress] over NOSTR, for free + instant continuity.
     *
     * Sends a signed ZBOOT carrying our NEW pubkey, addressed to the peer's CURRENT (known) pubkey, and
     * published FROM our OLD NOSTR identity — so the peer can still attribute the gift-wrap to us and, on
     * verifying the signature against our unchanged E2E identity key, adopt the new pubkey (routeIncomingBoot).
     * MUST be called BEFORE [NostrChatBridge.requestInboxRotation] swaps the live publisher to the new key.
     * Returns true if at least one relay acked. No on-chain spend — honors OPEN's no-on-chain rule.
     */
    private fun sha256Bytes(s: String): ByteArray =
        java.security.MessageDigest.getInstance("SHA-256").digest(s.toByteArray(Charsets.UTF_8))

    private fun bytesToHex(b: ByteArray): String = b.joinToString("") { "%02x".format(it) }

    private fun hexToBytesOrNull(hex: String): ByteArray? =
        runCatching {
            if (hex.length % 2 != 0) return null
            ByteArray(hex.length / 2) { hex.substring(it * 2, it * 2 + 2).toInt(16).toByte() }
        }.getOrNull()

    private suspend fun announceRotationOverNostr(peerAddress: String, newPubHex: String, relay: String): Boolean {
        if (!co.electriccoin.zcash.ui.nostr.NostrChatBridge.isOutboundReady()) return false
        // T1b-1 §2: held while a Keystone account is selected; the chat-open retry announces it later.
        if (keystoneAccountSelected()) return false
        val peerPub = zchatPreferences.getPeerNostrPubkey(peerAddress) ?: return false
        // R4-4 (1): through the per-message call, so an id this control creates is marked "INIT not sent" like
        // one a message creates (R2-6 c, R3-2 1). A control carries no user message; the first message after it
        // must still be the v4 INIT naming our address, never a REPLY the recipient cannot place. An existing
        // id is returned unchanged.
        val (convId, _) = convIdMutex.withLock { zchatPreferences.getOrCreateConversationIdForMessage(peerAddress) }
        // The rotation index was already bumped (rotateNostrIdentity bumps BEFORE calling this), so this is
        // the NEW epoch for the NEW pubkey — strictly higher than any the peer adopted before, so it wins
        // the monotonicity check on the recipient and a later replay of an older ZBOOT can't undo it (#225).
        val epoch = zchatPreferences.getNostrRotationIndex().toLong()
        val signedData = co.electriccoin.zcash.ui.screen.chat.model.ZBootMessage.signedDataFor(convId, newPubHex, relay, epoch)

        val ourE2EPriv = zchatPreferences.getE2EPrivateKey(peerAddress)
        val bootMemo: String
        val scheme: String
        // v3 (E2E-signed) whenever WE hold an E2E identity for this peer — i.e. we completed (at least our
        // half of) KEX, so the peer holds OUR E2E PUBLIC key and can verify a v3 rotation. We must NOT also
        // require holding the PEER's E2E pubkey: a v3 rotation is signed with OUR private key and verified
        // with OUR public key — the peer's key is irrelevant to it. Requiring `getE2EPeerPublicKey != null`
        // mis-classified an ASYMMETRIC pair (we lost/never-stored the peer's E2E pubkey while they still hold
        // ours) as OPEN and sent v4 — which the peer's downgrade guard (v4 refused for an E2E-bound peer)
        // then CORRECTLY rejected, permanently stranding the rotation (#251 on-device finding: Seeker logged
        // "v4 NOSTR-signed ZBOOT refused for E2E-bound peer … (downgrade guard)"). Pure-OPEN (#224) peers have
        // no E2E identity at all (ourE2EPriv == null) and still take the v4 branch below.
        if (ourE2EPriv != null) {
            // STRONG path: E2E-signed v3 — peers we hold a KEX-derived identity key for.
            val sig = E2EEncryption.sign(ourE2EPriv, signedData)
            bootMemo = co.electriccoin.zcash.ui.screen.chat.model.ZBootMessage(convId, newPubHex, relay, sig, epoch = epoch, version = 3).serialize()
            scheme = "E2E-signed v3"
        } else {
            // OPEN peer (no E2E identity, #224/#250): sign the rotation with the OUR-key index the peer
            // currently KNOWS (last adopted) — NOT blindly index-1 — so a missed/undelivered rotation can't
            // permanently strand them: the next announce re-signs with the key they still hold, letting them
            // jump straight to the current pubkey. Only its holder can forge this, so trust chains from the
            // TOFU-bound old key (no E2E ratchet required). Default 0 = the original identity. (v4)
            val knownIdx = zchatPreferences.getPeerKnownOurRotationIndex(peerAddress).let { if (it >= 0) it else 0 }
            val oldIdentity = runCatching {
                val wallet = persistableWalletProvider.requirePersistableWallet()
                val seed = Mnemonics.MnemonicCode(wallet.seedPhrase.joinToString()).toSeed()
                co.electriccoin.zcash.ui.nostr.NOSTRIdentity.fromSeed(seed, knownIdx)
            }.getOrNull() ?: return false
            val sigHex = bytesToHex(oldIdentity.signHashSchnorr(sha256Bytes(signedData)))
            bootMemo = co.electriccoin.zcash.ui.screen.chat.model.ZBootMessage(convId, newPubHex, relay, sigHex, epoch = epoch, version = 4).serialize()
            scheme = "NOSTR-key-signed v4 (signed w/ idx $knownIdx)"
        }
        // ZC-420: for a contact with keys, the mark of the new identity before the publish (a cut-off announce leaves it
        // beside a marker that still names the old key, and the repair runs the announce again). A pure Open contact's
        // memo needs the key that contact knows; its chat-open re-announce repairs it, so it gets no mark.
        val relayCopySlot = RelayCopySlots.identity(peerAddress)
        if (ourE2EPriv != null) NostrChatBridge.beginRelayCopy(relayCopySlot, extra = newPubHex)
        // ZC-393: a free-first relay copy: any readable relay is enough here, so ZC-393's stricter count never
        // starts an on-chain spend (residual R-1).
        val published =
            runCatching {
                co.electriccoin.zcash.ui.nostr.NostrChatBridge
                    .publish(bootMemo, peerPub)
            }.getOrNull()
        val acks = published?.readableAcks ?: 0
        if (acks > 0) {
            // Record the delivered identity so the on-chain fallback (sendNostrBootHandshake) skips a
            // duplicate ZBOOT for the same new pubkey.
            zchatPreferences.setSentNostrBootPubkey(peerAddress, newPubHex)
            // ZC-534: that marker now names an identity that WAS delivered, so no quoted ZBOOT is owed against it.
            if (zchatPreferences.isZbootOwed(peerAddress)) zchatPreferences.setZbootOwed(peerAddress, false)
            // ZC-420: a relay every version reads took it, so the mark goes; only a public one, so the mark names this copy.
            if (ourE2EPriv != null) NostrChatBridge.noteRelayCopy(relayCopySlot, published, extra = newPubHex)
            // #252: do NOT advance the peer's known-our-rotation index here. A relay ack only proves the
            // gift-wrap was STORED on a relay — NOT that the (possibly offline) peer fetched it and adopted
            // our new key. Advancing on a bare ack let the next rotation sign with a key the peer never
            // received, permanently stranding them. The index is now advanced ONLY on PROVEN adoption — an
            // inbound DM that decrypted under our current key (observeNostrInbound, #252). Until then the
            // chat-open retry (ensureNostrBootstrapSent, `known < cur`) keeps re-announcing with the key the
            // peer DOES hold, and the receiver dedups on the ZBOOT signature so the re-announce is idempotent.
            Log.d("ZCHAT_NOSTR", "Announced NOSTR rotation to ${peerAddress.take(16)}… over NOSTR ($scheme, free)")
        }
        return acks > 0
    }

    /**
     * Derive OUR NOSTR identity (x-only pubkey as 64-hex) + preferred relay from the wallet seed.
     * Same derivation [ensureNostrBootstrapSent] uses for the ZBOOT handshake. Returns null if the
     * wallet/seed isn't available yet. Used to piggyback our NOSTR keys onto the FIRST KEX/KEXACK
     * (BUG-4 one-tap calling) so a separate ZBOOT round-trip isn't required.
     */
    private data class OwnNostrIdentity(
        val publicKey: String,
        val relay: String,
        val rotation: Int,
    )

    /** Pure derivation: owned ZBOOT work checks its wallet generation before registering the result. */
    private suspend fun deriveOurNostrIdentity(): OwnNostrIdentity? =
        try {
            val wallet = persistableWalletProvider.requirePersistableWallet()
            val seed = Mnemonics.MnemonicCode(wallet.seedPhrase.joinToString()).toSeed()
            try {
                val rotation = zchatPreferences.getNostrRotationIndex()
                val identity =
                    co.electriccoin.zcash.ui.nostr.NOSTRIdentity
                        .fromSeed(seed, rotation)
                OwnNostrIdentity(
                    identity.publicKey.joinToString("") { "%02x".format(it) },
                    NostrRelayPool.DEFAULT_RELAYS.first(),
                    rotation,
                )
            } finally {
                seed.fill(0)
            }
        } catch (e: Throwable) {
            if (e is kotlinx.coroutines.CancellationException) throw e
            Log.w("ZCHAT_NOSTR", "Could not derive our NOSTR pubkey")
            null
        }

    private suspend fun getOurNostrPubkey(): Pair<String, String>? {
        return try {
            deriveOurNostrIdentity()?.let {
                // M1: retain legacy callers' registration and null-on-unavailable behavior.
                zchatPreferences.registerOwnNostrPubkey(it.publicKey)
                it.publicKey to it.relay
            }
        } catch (e: Throwable) {
            if (e is kotlinx.coroutines.CancellationException) throw e
            Log.w("ZCHAT_NOSTR", "Could not register our NOSTR pubkey")
            null
        }
    }

    /**
     * #252 — map an OUR-side NOSTR pubkey (x-only hex, as carried on an inbound gift-wrap's
     * recipientPubkeyHex) back to the rotation index that derives it, scanning the range from..to inclusive.
     * Returns the matched index, or -1 if [pubHex] isn't one of our keys in that range. Used to advance a
     * peer's known-our-rotation index to EXACTLY the key they proved they hold — never further (so a
     * rotation racing the inbound handler can't over-advance) and far enough that a peer who reached an old
     * grace-window key still self-heals. Caller gates this on (known < current), so the range — and hence
     * the number of seed-derivations — is bounded by the count of unconfirmed rotations (normally 0–1).
     */
    private suspend fun ourRotationIndexForPubkey(pubHex: String, from: Int, to: Int): Int {
        if (pubHex.isBlank() || from > to) return -1
        return runCatching {
            val wallet = persistableWalletProvider.requirePersistableWallet()
            val seed = Mnemonics.MnemonicCode(wallet.seedPhrase.joinToString()).toSeed()
            // Zero the derived seed bytes once we're done deriving — don't leave master key material
            // lingering in the heap longer than necessary (try/finally so it runs even on exception).
            try {
                var found = -1
                for (i in from..to) {
                    val pub = co.electriccoin.zcash.ui.nostr.NOSTRIdentity.fromSeed(seed, i)
                        .publicKey.joinToString("") { "%02x".format(it) }
                    if (pub.equals(pubHex, ignoreCase = true)) {
                        found = i
                        break
                    }
                }
                found
            } finally {
                seed.fill(0)
            }
        }.getOrDefault(-1)
    }

    /**
     * KEX one-tap calling (BUG-4): if a received KEX/KEXACK carried the peer's NOSTR pubkey + relay,
     * store them immediately so voice/video calls connect without waiting for a separate ZBOOT.
     *
     * Mirrors the trust model of [routeIncomingBoot]: the NOSTR identity is TOFU-bound to the
     * KEX-verified E2E key, and a CHANGED key on an existing peer is treated as a MITM/rotation
     * signal — we refuse to silently overwrite, flag the key-changed banner, and clear verification.
     * The KEX signature itself is verified by the caller before this runs.
     *
     * M1: through bindPeerNostrKey, like every other bind site. A key that already belongs to another address is not
     * bound (as routeIncomingBoot refuses it): one key on two addresses routed the contact's relay messages to one of
     * them by hash order. The key exchange itself is not touched; only the relay binding (and the flush) is skipped.
     * T4b2-G1: a KEX never takes a key from a cut copy of an address either (mayTakeFromBrokenHolder stays false): the
     * relay key does not sign the KEX, so only the user's paste or scan of the full code may do that.
     */
    private fun applyKEXNostr(peerAddress: String, nostrPubkeyHex: String?, relayUrl: String?) {
        if (nostrPubkeyHex == null || relayUrl == null) return // legacy KEX → fall back to ZBOOT
        val outcome = zchatPreferences.bindPeerNostrKey(peerAddress, nostrPubkeyHex, relayUrl)
        when (outcome.result) {
            NostrBindResult.BOUND, NostrBindResult.ALREADY_BOUND_SAME -> Unit
            NostrBindResult.KEY_CHANGED -> {
                Log.w("ZCHAT_NOSTR", "Peer NOSTR key in KEX CHANGED for ${peerAddress.take(16)}… — flagged, NOT auto-accepted")
                return
            }
            NostrBindResult.KEY_BOUND_ELSEWHERE -> {
                Log.w("ZCHAT_NOSTR", "Peer NOSTR key in KEX already bound to a different address — NOT bound (pubkey reuse)")
                return
            }
            NostrBindResult.SELF, NostrBindResult.INVALID_ADDRESS -> {
                Log.w("ZCHAT_NOSTR", "Peer NOSTR key in KEX not bound (${outcome.result})")
                return
            }
        }
        Log.d("ZCHAT_NOSTR", "Stored peer NOSTR pubkey from KEX for ${peerAddress.take(16)}… (one-tap calling enabled)")
        // Peer NOSTR key learned from the handshake → flush any off-chain-queued TUNNEL messages.
        flushTunnelPendingPayloads(peerAddress, nostrPubkeyHex)
    }

    /**
     * Bootstrap a NOSTR tunnel with [peerAddress] by sending OUR signed KEX. This is leg ONE of the
     * Tunnel handshake: the KEX delivers our E2E identity key + our authenticated address, which lets
     * the peer encrypt to us AND verify us (and reply with a KEXACK). Leg TWO — delivering our NOSTR
     * pubkey so voice/video calls + NOSTR DMs can route to us — happens in [sendNostrBootHandshake],
     * sent SEPARATELY and AFTER the E2E exchange (a first-contact KEX has no room for the NOSTR fields
     * under the 512-byte memo cap, and a second simultaneous on-chain tx would race the KEX for the one
     * spendable note). Idempotent: skipped once the peer's NOSTR pubkey is known (handshake complete) or
     * once we've already sent our KEX (unless [force], used by a Call-tap to recover a stuck/one-way
     * handshake). Triggered on a chat open, on a call attempt before keys are exchanged, and (T3b-1) by a confirmed switch
     * to Tunnel/Open through [switchConversationMode], never by the picker itself.
     */
    fun ensureNostrBootstrapSent(peerAddress: String, force: Boolean = false) = startNostrBootstrap(peerAddress, force, switch = null)

    /**
     * T3b-1 — what a confirmed [switchConversationMode] lets the bootstrap pay: [mode] is the mode switched to (read here
     * instead of the store, which the mode change writes in its own coroutine); our KEX only when [payKex] (it was in the
     * quote) and paid on that quote while [quoteStands], with no second automatic-setup question; our ZBOOT on-chain only
     * when [zbootOnChain] (it was in the quote; the allowance it leaves pays it, now or once the contact answers),
     * otherwise over the relays or not at all.
     */
    private class SwitchBootstrap(
        val mode: co.electriccoin.zcash.ui.screen.chat.model.ConversationMode,
        val payKex: Boolean,
        val zbootOnChain: Boolean,
        val quoteStands: () -> Boolean,
    )

    private fun startNostrBootstrap(
        peerAddress: String,
        force: Boolean,
        switch: SwitchBootstrap?,
        // ZC-1473: completed with how our KEX send ended, or null when this pass attempted none.
        kexEnded: CompletableDeferred<KexEnd?>? = null,
    ) {
        // ZC-1352: a Call or Reconnect tap and a confirmed mode switch are the user asking for this setup.
        if (force || switch != null) userStartsSetupAgain(peerAddress)
        // #250/#252 — OPEN-peer rotation RETRY (runs regardless of the bootstrap early-return below). If we
        // rotated but this OPEN peer has not yet PROVEN adoption (known idx < current), re-announce on
        // chat-open: the on-chain fallback is gated off for OPEN, and a one-shot announce can fail if the
        // publisher was momentarily down. Idempotent — the receiver dedups on the ZBOOT signature, and the
        // known idx now advances ONLY when the peer sends us an inbound under our current key (#252 adoption
        // signal in observeNostrInbound), so this re-fires until adoption is proven, then stops. Re-announces
        // sign with the key the peer DOES hold (known idx), so a missed rotation self-heals on next contact.
        viewModelScope.launch {
            if (zchatPreferences.getConversationMode(peerAddress) ==
                co.electriccoin.zcash.ui.screen.chat.model.ConversationMode.OPEN
            ) {
                val cur = zchatPreferences.getNostrRotationIndex()
                val known = zchatPreferences.getPeerKnownOurRotationIndex(peerAddress).let { if (it >= 0) it else 0 }
                if (known < cur && co.electriccoin.zcash.ui.nostr.NostrChatBridge.isOutboundReady()) {
                    getOurNostrPubkey()?.let { (pub, relay) ->
                        runCatching { announceRotationOverNostr(peerAddress, pub, relay) }
                    }
                }
            }
        }
        // #233 — the exchange is complete ONLY when BOTH directions are done: we hold the peer's NOSTR
        // pubkey AND we have delivered OURS (getSentNostrBootPubkey != null). The old check bailed as soon
        // as we held the PEER's pubkey — which is exactly the responder/leg-4 case: routeIncomingBoot stored
        // the initiator's pubkey then fired our reply-ZBOOT, but if that ZBOOT failed (single-note contention
        // → "gave up waiting for a new block"), this early-return then blocked every retry-on-open, leaving a
        // ONE-WAY tunnel forever (we can reach them over NOSTR, they can't reach us; their first message stays
        // queued). Requiring both directions lets sendNostrBootHandshake (idempotent, self-arming) re-attempt
        // our ZBOOT on each open until it lands. force=true (call placement) always proceeds.
        // ZC-739: our key exchange and our ZBOOT wait while the contact's new key waits for the user (the free signed
        // re-announce above is not held). A Call tap (force) says why.
        if (zchatPreferences.isE2EKeyChanged(peerAddress)) {
            if (force) blockedByKeyChange(peerAddress)
            kexEnded?.complete(null)
            return
        }
        // ZC-1352: nothing of the setup goes after the user deleted the first message it was for.
        if (zchatPreferences.isAutomaticSetupWithdrawn(peerAddress)) {
            kexEnded?.complete(null)
            return
        }
        if (!force &&
            zchatPreferences.getPeerNostrPubkey(peerAddress) != null &&
            zchatPreferences.getSentNostrBootPubkey(peerAddress) != null
        ) {
            kexEnded?.complete(null)
            return
        }
        viewModelScope.launch {
            var kexReported = false
            try {
                val ourAddress = _currentUserAddress.value ?: return@launch
                // LEG ONE — our KEX (E2E identity + authenticated address). The peer stores it
                // (handleKEXMessage) and replies with a KEXACK; our NOSTR pubkey is delivered SEPARATELY
                // in leg two below. The bootSent flag stops re-spending the KEX on every trigger (a
                // Call-tap passes force=true to re-publish for recovery). sendKEXMessage has its own
                // try/catch and resets isOwnBootSent on failure.
                //
                // The old flow published the ZBOOT in the SAME pass as the KEX. Under the single-note
                // (one spend per block) constraint the two on-chain txs RACED for the one spendable note:
                // the ZBOOT grabbed it and the KEX failed with "No Orchard input found", so the peer never
                // received our E2E key and the tunnel deadlocked. Sending the KEX alone (when due) gives
                // it the note to itself; the ZBOOT below self-gates until the E2E exchange lands, so on a
                // first call the two never contend.
                // OPEN never spends ZEC (#224 invariant): it messages free over NOSTR from message #1 and
                // exchanges keys out-of-band (QR / NOSTR INIT), so it must NOT fire a paid on-chain KEX.
                // Doing so was also the dual-KEX source — BOTH devices of an OPEN pair (each holding the
                // other's NOSTR pubkey) independently fired their own KEX on chat-open, giving divergent
                // ratchet roots. If the user later switches this chat to VAULT, the first VAULT send fires
                // the KEX then (sendMessage's keys-null path). TUNNEL still bootstraps on-chain as before.
                val bootstrapMode = switch?.mode ?: zchatPreferences.getConversationMode(peerAddress)
                val skipOnChainKex = bootstrapMode == co.electriccoin.zcash.ui.screen.chat.model.ConversationMode.OPEN
                // Gate the paid KEX on DELIVERY EVIDENCE (isE2EKeyExchangeComplete = we hold ourPriv +
                // the peer's E2E pubkey), NOT on the bootsent bookkeeping flag. Once the KEX round-trip has
                // finished (initiator: peer's KEXACK answered our KEX; responder: KEXACK path owns our-key
                // delivery), re-firing the KEX is pure waste AND — since the ZBOOT self-gate (:1464) is now
                // open — it would RACE the ZBOOT for the single spendable note (the #208 contention the
                // leg-1/leg-2 sequencing exists to prevent). A stale bootsent=false must not cause either.
                // T3b-1: a confirmed switch pays a KEX only when its quote counted one.
                // ZC-1306: a first message accepted and not sent yet owns this KEX: its send pays it, within its total.
                // ZC-1348: another account's question covers this key exchange: this account pays nothing, its leg stays.
                val coveredForAnother =
                    switch == null &&
                        quotedChatSetup(peerAddress)?.kex != null &&
                        !coveredSetupIsOf(peerAddress, selectedAccountOrNull()?.let(GetDefaultUnifiedAddressUseCase::accountKeyOf))
                // ZC-1478 (M1): a mode the contact moved this chat into starts no paid setup by itself (a chat open, a
                // block); the user's own Call or Reconnect tap (force) and a confirmed switch still do.
                val adoptedPaidMode = switch == null && !force && modeMovedToPaidByPeer(peerAddress)
                if (!skipOnChainKex &&
                    !adoptedPaidMode &&
                    switch?.payKex != false &&
                    !coveredForAnother &&
                    !firstMessageOwnsKex(peerAddress) &&
                    !zchatPreferences.isE2EKeyExchangeComplete(peerAddress) &&
                    (force || !zchatPreferences.isOwnBootSent(peerAddress))
                ) {
                    // R5-2: the marker goes down BEFORE the paid KEX, and only a marker the store confirmed
                    // may be paid against — without it a restart finds the bootstrap re-armed and pays for a
                    // second KEX. On a failed write nothing is sent and the next bootstrap trigger tries
                    // again; leg two below still runs (it self-gates on the unfinished exchange anyway).
                    // FC-ID (5.3a item 4): the key exchange goes out under an id this phone made for this address.
                    planOwnConversationId(peerAddress)
                    // ZC-1272: the one question's Pay covered this KEX: paid on it at its leg, with no second question.
                    val quotedLeg = if (switch == null) quotedChatSetup(peerAddress)?.kex else null
                    if (!zchatPreferences.setOwnBootSent(peerAddress, true)) {
                        Log.e("KEX", "KEX not paid: its bootstrap-sent marker could not be written")
                    } else if (quotedLeg != null) {
                        // ZC-1509 (money-path rule 4): a waiting Reconnect tap is told how this paid KEX ended, from its
                        // outcome and what its proposal paid, as on the reporting arm below; never "nothing was sent".
                        kexReported = kexEnded != null
                        launch {
                            var reached = false
                            var paid: Zatoshi? = null
                            val sink =
                                co.electriccoin.zcash.ui.screen.chat.usecase.ProposalPriceSink { price ->
                                    reached = true
                                    paid = price
                                }
                            try {
                                val outcome = withContext(sink) { sendQuotedKex(peerAddress, ourAddress, quotedLeg) }
                                kexEnded?.complete(KexEnd(outcome, reached, paid))
                            } finally {
                                kexEnded?.complete(null)
                            }
                        }
                    } else if (switch?.mode == co.electriccoin.zcash.ui.screen.chat.model.ConversationMode.TUNNEL || kexEnded != null) {
                        // ZC-1472: the same send as sendKEXMessage; the chat says the paid setup went out only from its
                        // outcome, with what its proposal paid (money-path rule 4), never before. ZC-1473: so does Reconnect.
                        kexReported = true
                        launchKexReporting(peerAddress, ourAddress, switch?.quoteStands) { end ->
                            if (switch?.mode == co.electriccoin.zcash.ui.screen.chat.model.ConversationMode.TUNNEL) {
                                noteTunnelSetup(peerAddress, end)
                            }
                            kexEnded?.complete(end)
                        }
                        Log.d("ZCHAT_NOSTR", "Tunnel bootstrap: sent KEX (E2E identity + address) to ${peerAddress.take(16)}…")
                    } else {
                        sendKEXMessage(peerAddress, ourAddress, confirmedByQuote = switch?.quoteStands)
                        Log.d("ZCHAT_NOSTR", "Tunnel bootstrap: sent KEX (E2E identity + address) to ${peerAddress.take(16)}…")
                    }
                } else if (skipOnChainKex) {
                    Log.d("ZCHAT_NOSTR", "OPEN chat — skipping paid on-chain KEX for ${peerAddress.take(16)}… (free NOSTR)")
                }
                // LEG TWO — (re)attempt the ZBOOT that delivers our NOSTR pubkey. sendNostrBootHandshake
                // SELF-GATES: it no-ops until we hold the peer's E2E key (so before the KEXACK lands it
                // bails — no contention with the KEX above for the single note) and once our pubkey is
                // delivered (idempotent). Calling it here — on EVERY bootstrap trigger, e.g. each chat
                // re-open via the AndroidChatDetail LaunchedEffect — is the fix for the single-note ZBOOT
                // deadlock: the KEX consumes the only note, so the sequenced ZBOOT must wait for the KEX's
                // CHANGE to mature (~10 confirmations). The per-send block-retry window is shorter, so the
                // first ZBOOT attempt (fired once on KEXACK-receipt) gives up with "Insufficient balance
                // (have 0)" while the change is still pending — and nothing ever retried it, leaving the
                // tunnel one-way forever (root-caused in 2-device testing). Re-attempting on chat-open
                // lets the ZBOOT land once the change is spendable, completing the handshake.
                when {
                    // ZC-1478 (M1): in a mode the contact moved this chat into, our ZBOOT goes over the relays or not at all.
                    adoptedPaidMode -> sendNostrBootHandshake(peerAddress, ZbootOnChainRule.RELAY_ONLY)
                    switch == null -> sendNostrBootHandshake(peerAddress)
                    // T3b-1: the quote counted our ZBOOT. Its allowance pays it (now, or once the contact answers) with no
                    // second question; an allowance that could not be saved pays nothing on-chain.
                    // ZC-1132: only while the confirmed pick still stands; a pick that replaced it leaves no allowance.
                    // ZC-1390: the allowance names the account that confirmed the switch; no other account pays it.
                    switch.zbootOnChain &&
                        switch.quoteStands() &&
                        recordZbootQuote(peerAddress, selectedAccountOrNull()?.let(GetDefaultUnifiedAddressUseCase::accountKeyOf)) ->
                        sendNostrBootHandshake(peerAddress, ZbootOnChainRule.QUOTED_IN_SHIELDED)
                    // T3b-1: the quote did not count one: over the relays or not at all.
                    else -> sendNostrBootHandshake(peerAddress, ZbootOnChainRule.RELAY_ONLY)
                }
            } catch (e: Exception) {
                // NOTE: do NOT reset bootsent here — both legs are fire-and-forget launches, so this
                // catch only ever sees a synchronous pref-read throw AFTER leg-1 may already be dispatched.
                // The real re-arm on a genuine send failure lives inside sendKEXMessage (cancellation path).
                Log.w("ZCHAT_NOSTR", "bootstrap send failed: ${e.message}")
            } finally {
                // ZC-1473: a pass that launched no reporting KEX says so (null), so a waiting Reconnect tap ends.
                if (!kexReported) kexEnded?.complete(null)
            }
        }
    }

    /** ZC-1272: the legs the one price question of this chat covered, as they stand on disk; null when none. */
    private fun quotedChatSetup(peerAddress: String): QuotedChatSetup? =
        runCatching { QuotedChatSetup.decode(zchatPreferences.getQuotedChatSetup(peerAddress)) }.getOrNull()

    /**
     * ZC-1348 (money-path rule 2): [accountKey], the account selected now, is the one that answered [peerAddress]'s question.
     * A selected account that cannot be read (null) is not that one. A record that names no account pays as before: every
     * writer of this build names one, so only a fixture or an earlier test build leaves it.
     */
    private fun coveredSetupIsOf(
        peerAddress: String,
        accountKey: String?,
    ): Boolean {
        val owner = quotedChatSetup(peerAddress)?.account ?: return true
        return accountKey == owner
    }

    /**
     * ZC-1390 (money-path rule 2): the quoted-ZBOOT allowance of [peerAddress] belongs to [accountKey], the account
     * selected now: the account recorded with it ([ZchatPreferences.getZbootQuotedAccount]) and that of a New Chat question
     * that covered the ZBOOT leg ([coveredSetupIsOf]). An account that cannot be read (null) is not that one. An allowance
     * with no account recorded pays as before (only an earlier 2.13.0 test build or a fixture leaves one).
     */
    private fun zbootAllowanceIsOf(
        peerAddress: String,
        accountKey: String?,
    ): Boolean {
        val owner = zchatPreferences.getZbootQuotedAccount(peerAddress)
        if (owner != null && owner != accountKey) return false
        return quotedChatSetup(peerAddress)?.zboot == null || coveredSetupIsOf(peerAddress, accountKey)
    }

    /** ZC-1390: an allowance stands for [peerAddress] and another account confirmed it: the account selected now pays nothing. */
    private fun zbootAllowanceOfAnother(
        peerAddress: String,
        accountKey: String?,
    ): Boolean =
        (zchatPreferences.isZbootQuoted(peerAddress) || quotedChatSetup(peerAddress)?.zboot != null) &&
            !zbootAllowanceIsOf(peerAddress, accountKey)

    /** ZC-1272: write [setup] back (an empty one leaves no record). @return whether it reached the disk. */
    private fun storeQuotedChatSetup(
        peerAddress: String,
        setup: QuotedChatSetup?,
    ): Boolean = zchatPreferences.setQuotedChatSetup(peerAddress, setup?.takeUnless { it.isEmpty }?.encode())

    /**
     * ZC-1272 (money-path rule 1) — our KEX on the leg [leg] the user's Pay covered, while that leg stands: never under the
     * standing consent, never above [leg]. Above it nothing is paid and the question comes back with the new figure.
     */
    private suspend fun sendQuotedKex(
        peerAddress: String,
        ourAddress: String,
        leg: Long,
    ): MemoSendOutcome? =
        sendKexOnce(
            peerAddress,
            ourAddress,
            // ZC-1348: re-read at each attempt: a switch during a block wait stops it, and the leg comes back for its account.
            confirmedByQuote = {
                quotedChatSetup(peerAddress)?.kex == leg &&
                    coveredSetupIsOf(peerAddress, selectedAccountNow()?.let(GetDefaultUnifiedAddressUseCase::accountKeyOf))
            },
            retryOf = null,
            payment =
                OwnSetupPayment(
                    price = KexAnswerPrice(Zatoshi(leg)),
                    onAbove = { actual -> askQuotedKexAgain(peerAddress, actual) },
                    coveredKexLeg = leg,
                ),
        )

    /** ZC-1272: a changed price asks again, with the new figure. Cancel pays nothing; the next chat open builds it again. */
    private fun askQuotedKexAgain(
        peerAddress: String,
        actual: Zatoshi,
    ) {
        val ourKey = zchatPreferences.getE2EOurPublicKey(peerAddress) ?: return
        askKexAnswerTruePrice(actual, PaidAction.OWN_SETUP_TRUE_PRICE) { price ->
            payHeldOwnSetup(peerAddress, HeldOwnSetupPrice(zboot = false, ourKey = ourKey, actual = actual), price)
        }
    }

    /**
     * ZC-1306 — a first message to [peerAddress] was accepted and has not gone out (waiting for its funds, or stopped for the
     * user): its own send pays the KEX, within its total, and no bootstrap pays one beside it.
     */
    @Suppress("TooGenericExceptionCaught")
    private fun firstMessageOwnsKex(peerAddress: String): Boolean =
        try {
            zchatPreferences.getPendingMessages().any {
                it.peerAddress == peerAddress &&
                    it.acceptedPriceZatoshi != null &&
                    it.submittedTxIds.isEmpty() &&
                    (it.waitsForFunds() || it.status == MessageStatus.FAILED.name)
            }
        } catch (e: Exception) {
            Log.w("KEX", "Stored rows not read: ${e.javaClass.simpleName}")
            true
        }

    /**
     * #256 — manual recovery for an asymmetric / one-way handshake. Re-arms our identity delivery (clears
     * the "already delivered" marker so [sendNostrBootHandshake] re-publishes) and forces a fresh bootstrap
     * pass. Safe + idempotent: if the channel is already two-way this re-publishes the SAME signed ZBOOT and
     * the receiver dedups on its signature, so nothing changes. Used by the in-chat "reconnect / re-send my
     * key" action so a pair stuck one-way (we hold their NOSTR key but they never got ours — the on-chain
     * leg-2 ZBOOT failed on a 0-ZEC wallet) recovers WITHOUT a reinstall: with the free-NOSTR delivery the
     * ZBOOT now lands over the relay and the peer learns our key → Open/calls unlock symmetrically.
     */
    fun reSendOurIdentity(peerAddress: String) {
        // ZC-739: nothing is re-sent to a contact whose new key waits for the user; the tap says why.
        if (blockedByKeyChange(peerAddress)) return
        userStartsSetupAgain(peerAddress)
        // B5 — the button "did nothing": it fired work but gave NO feedback, and it re-spent a paid KEX on
        // every tap even when the session was fine. Now: give the user a result, and only re-KEX when the
        // session is actually torn (peer key missing, e.g. right after a Reset). When we already hold the
        // peer's key, just RE-DELIVER our NOSTR identity — free over the relay when the peer's relay key is
        // known, otherwise as an on-chain ZBOOT.
        //
        // P2b: a tap pays for at most ONE chat setup per contact key until the contact replies or the stated
        // cooldown passes. A second tap within it sends nothing and says so; the paid-setup record behind this
        // check also stops a Call tap or another screen from paying the same setup again.
        viewModelScope.launch {
            try {
                // T1b-1 §2: Reconnect re-delivers our identity; not while a Keystone account is selected.
                if (keystoneAccountSelected()) {
                    _sendMessageState.value = SendMessageState.Error(ChatSendCopy.KEYSTONE_AUTOMATIC_SETUP)
                    return@launch
                }
                // ZC-634 (FC-5b, 5.5 item 8): while this chat's key is only a claim nothing paid is sent: with a relay key
                // bound and the relays ready our identity goes over the relays only; otherwise nothing, and the user is told
                // to compare the safety number. No cooldown is used.
                if (zchatPreferences.getKeyClaim(peerAddress) != null) {
                    if (zchatPreferences.getPeerNostrPubkey(peerAddress) != null && NostrChatBridge.isOutboundReady()) {
                        zchatPreferences.setSentNostrBootPubkey(peerAddress, null) // re-arm identity delivery
                        // ZC-1473: the result is told once the send ended, never at the tap.
                        val report = ZbootReport()
                        val job =
                            registerZbootFrame(peerAddress, ZbootOnChainRule.RELAY_ONLY, resumeOwed = false)?.let { frame ->
                                sendNostrBootHandshake(
                                    peerAddress,
                                    ZbootOnChainRule.RELAY_ONLY,
                                    resumeOwed = false,
                                    frame = frame,
                                    result = report.result,
                                    onRelay = report::relayed,
                                    priceSink = report.sink,
                                )
                            }
                        reportZbootReconnect(peerAddress, job, report)
                    } else {
                        _sendMessageState.value =
                            SendMessageState.Success(noteCopy.get(R.string.chat_reconnect_not_sent_key_unconfirmed))
                    }
                    return@launch
                }
                // F8 (ZC-112): a setup message of this chat was proven never to have reached the chain. Reconnect then opens
                // the same question as the notice's Retry, bound to that failed attempt, and pays nothing under the
                // standing consent (which would only meet PENDING).
                if (!openNeverSpends(peerAddress)) {
                    handshakeOffers()[peerAddress]?.let { offer ->
                        askHandshakeRetry(peerAddress, offer)
                        return@launch
                    }
                }
                if (zchatPreferences.isE2EKeyExchangeComplete(peerAddress)) {
                    val relayReady = NostrChatBridge.isOutboundReady()
                    val freeRoute = zchatPreferences.getPeerNostrPubkey(peerAddress) != null && relayReady
                    val identity = if (freeRoute) null else getOurNostrPubkey()?.first
                    val wait = paidSetupCooldown(AutomaticSetupKind.ZBOOT, peerAddress, identity)
                    if (wait > 0L) {
                        _sendMessageState.value = SendMessageState.Success(reconnectCooldownMessage(wait))
                        return@launch
                    }
                    zchatPreferences.setSentNostrBootPubkey(peerAddress, null) // re-arm identity delivery
                    // ZC-1473: the result is told once the send ended (over the relays, on-chain with what it paid, or
                    // nothing), as a note that stays in the chat; never at the tap.
                    val report = ZbootReport()
                    // ZC-792: the tap's own sender is not stopped by a history pass that reads this identity mined.
                    val job =
                        registerZbootFrame(peerAddress, ZbootOnChainRule.STANDING_CONSENT, resumeOwed = false)?.let { frame ->
                            frame.reconnectTap = true
                            sendNostrBootHandshake(
                                peerAddress,
                                ZbootOnChainRule.STANDING_CONSENT,
                                resumeOwed = false,
                                frame = frame,
                                result = report.result,
                                onRelay = report::relayed,
                                priceSink = report.sink,
                            )
                        }
                    reportZbootReconnect(peerAddress, job, report)
                } else if (openNeverSpends(peerAddress)) {
                    // ZC-1473: an Open chat has no key exchange to send again (Open never pays); the bootstrap only
                    // repeats a free relay announce of a rotated key. Say so, and claim no re-sent key.
                    ensureNostrBootstrapSent(peerAddress, force = true)
                    val text = noteCopy.get(R.string.chat_note_reconnect_open)
                    emitSystemNote(peerAddress, setupNoteId(peerAddress, "reconnect"), text)
                    _sendMessageState.value = SendMessageState.Success(text)
                } else {
                    val wait =
                        paidSetupCooldown(AutomaticSetupKind.KEX, peerAddress, zchatPreferences.getE2EOurPublicKey(peerAddress))
                    if (wait > 0L) {
                        _sendMessageState.value = SendMessageState.Success(reconnectCooldownMessage(wait))
                        return@launch
                    }
                    // Torn / first-contact: run the full bootstrap incl. a fresh KEX to re-establish.
                    // ZC-1473: the result is told once the KEX send ended, never at the tap.
                    val kexEnded = CompletableDeferred<KexEnd?>()
                    startNostrBootstrap(peerAddress, force = true, switch = null, kexEnded = kexEnded)
                    val end = kexEnded.await()
                    when {
                        end != null && end.sentNow ->
                            reportReconnect(
                                peerAddress,
                                end.paid?.let {
                                    noteCopy.get(R.string.chat_note_reconnect_kex_sent, zecDisplay(it, java.util.Locale.getDefault()))
                                } ?: noteCopy.get(R.string.chat_note_reconnect_kex_sent_unpriced),
                                SendMessageState.Success(ChatSendCopy.KEY_RESENT),
                            )
                        else -> reportReconnectWithoutSend(peerAddress, end?.outcome)
                    }
                }
            } catch (e: Exception) {
                if (e is kotlinx.coroutines.CancellationException) throw e
                _sendMessageState.value = SendMessageState.Error(e.toZchatUserMessage(ChatSendCopy.RECONNECT_FAILED))
            }
        }
    }

    /** ZC-1473 — what one Reconnect ZBOOT did: the relay route, the sender's outcome, and what an on-chain attempt paid. */
    private class ZbootReport {
        val result = CompletableDeferred<MemoSendOutcome>()

        @Volatile var viaRelay = false

        @Volatile var reachedSubmit = false

        @Volatile var paid: Zatoshi? = null

        val sink =
            co.electriccoin.zcash.ui.screen.chat.usecase.ProposalPriceSink { price ->
                reachedSubmit = true
                paid = price
            }

        fun relayed() {
            viaRelay = true
        }
    }

    /**
     * ZC-1473 — once the Reconnect ZBOOT's sender ended ([job]; null when another send of it was already running), the
     * chat gets one note saying what happened: sent over the relays (free), sent on-chain with what it paid, or that
     * nothing new was sent. Waits in the process-wide scope, as the sender runs there, so leaving the chat keeps it.
     */
    private fun reportZbootReconnect(
        peerAddress: String,
        job: kotlinx.coroutines.Job?,
        report: ZbootReport,
    ) {
        processSendScope().launch {
            job?.join()
            val outcome = if (report.result.isCompleted) report.result.await() else null
            when {
                report.viaRelay ->
                    reportReconnect(
                        peerAddress,
                        noteCopy.get(R.string.chat_note_reconnect_sent_relay),
                        SendMessageState.Success(ChatSendCopy.RECONNECTED_DETAILS_RESENT),
                    )
                outcome == MemoSendOutcome.SENT && report.reachedSubmit ->
                    reportReconnect(
                        peerAddress,
                        report.paid?.let {
                            noteCopy.get(R.string.chat_note_reconnect_sent_onchain, zecDisplay(it, java.util.Locale.getDefault()))
                        } ?: noteCopy.get(R.string.chat_note_reconnect_sent_onchain_unpriced),
                        SendMessageState.Success(ChatSendCopy.RECONNECTED_DETAILS_RESENT),
                    )
                job == null -> reportReconnectWithoutSend(peerAddress, MemoSendOutcome.PENDING)
                else -> reportReconnectWithoutSend(peerAddress, outcome)
            }
        }
    }

    /**
     * ZC-1473 — a Reconnect whose send did not go out now: [outcome] SENT here means another attempt had delivered it
     * (nothing paid now), PENDING that a copy is still on its way, MAY_HAVE_BEEN_SENT that an on-chain attempt may have
     * gone out (never sent again by itself), anything else (NOTHING_SENT, nothing attempted) that nothing went out.
     */
    private fun reportReconnectWithoutSend(
        peerAddress: String,
        outcome: MemoSendOutcome?,
    ) {
        val text =
            when (outcome) {
                MemoSendOutcome.SENT, MemoSendOutcome.PENDING -> noteCopy.get(R.string.chat_note_reconnect_already)
                MemoSendOutcome.MAY_HAVE_BEEN_SENT -> noteCopy.get(R.string.chat_note_reconnect_maybe_sent)
                MemoSendOutcome.NOTHING_SENT, null -> noteCopy.get(R.string.chat_note_reconnect_not_sent)
            }
        reportReconnect(peerAddress, text, SendMessageState.Success(text))
    }

    /** ZC-1473 — the Reconnect result: a note that stays in the chat, and [state] for the open screen. */
    private fun reportReconnect(
        peerAddress: String,
        text: String,
        state: SendMessageState,
    ) {
        emitSystemNote(peerAddress, setupNoteId(peerAddress, "reconnect"), text)
        _sendMessageState.value = state
    }

    /** P2b — what a Reconnect tap inside the paid-setup cooldown tells the user (nothing was sent). */
    private fun reconnectCooldownMessage(waitMillis: Long): String {
        val minutes = ((waitMillis + 59_999L) / 60_000L).coerceAtLeast(1L)
        return "Your key was already sent, so nothing was sent or charged this time. Wait for your contact to " +
            "reply, or try again in about $minutes min (at most once an hour). If they still can't reach you, " +
            "they may need to update ZChat."
    }

    /**
     * USER-INITIATED "Reset Encryption" recovery for a contact whose secure session has desynced —
     * the classic "🔒 its decryption key isn't on this device" / AEADBadTagException state that follows
     * a wallet restore or an independent device wipe on EITHER side. The E2E ratchet keys are local-only
     * (random per-device keys, NOT seed-derived), so a wipe/restore regenerates them and the peer is left
     * holding a stale key → every message decrypts to garbage and there is no in-band recovery (a changed
     * key is (correctly) treated as a possible MITM and NOT auto-adopted, so the chat stays stuck).
     *
     * This tears the contact's crypto state back to FIRST-CONTACT and re-runs the handshake. Because the
     * stored peer key is wiped, the peer's fresh KEX is seen as first-contact and adopted (no key-changed
     * banner); when BOTH sides reset, fresh E2E keys + a fresh ratchet root are exchanged and messaging
     * resumes. It does NOT delete the chat or its history — only the (now-useless) keys. Messages sent
     * BEFORE the reset stay unreadable (their keys were wiped with the old root — plain key deletion,
     * not forward secrecy); everything after re-keys cleanly.
     *
     * SECURITY: this only RELAXES trust for THIS contact, by the user's explicit choice (a confirm dialog
     * gates the UI) — exactly like deleting and re-adding the contact, but without losing the thread. The
     * automatic MITM/key-change guard on the normal receive path is untouched.
     *
     * Round 8 D5 (DECISIONS_NIGHT §2 / M-NOS-21): the re-run handshake is paid — our KEX now and our ZBOOT once the
     * contact's new key lands, up to 2 on-chain transactions in any mode where the KEX goes on-chain. So nothing, the
     * key wipe included, happens before the paid-action question has shown that price and the user confirmed; Cancel
     * wipes nothing. The question is skipped only when nothing paid follows ([resetEncryptionPaysOnChain]). With a
     * Keystone account selected the KEX can never be paid (ZC-102): nothing is wiped and the Keystone text is shown.
     *
     * ZC-285, ZC-286 (fix-all 2.13.0): the confirm is the consent for exactly what the question quoted, our KEX and our
     * ZBOOT, and for nothing else: the standing "Allow handshake transactions" consent is neither asked, read for them nor
     * written. The confirmed reset runs on the process-wide send scope ([processSendScope]), so leaving the chat never
     * cancels it between the wipe and its KEX. Before anything is wiped it records the KEX as owed (the mark, the
     * confirming account and the reason [ZchatPreferences.KEX_OWED_REASON_RESET]) and the ZBOOT allowance; if the store
     * does not confirm any of those writes, nothing is wiped, nothing is sent and the user is told
     * ([ChatSendCopy.STORAGE_PAUSED_PAID_STEP]). The KEX is then paid at once through [payOwedKex]; when it cannot go
     * now (funds still confirming, no funds, the app closed) it stays owed and a later block or chat open pays it,
     * once, at the price the user confirmed here, with no second question (the R9-2 rule for a first message's KEX).
     * Our ZBOOT follows the contact's KEXACK, over the relays first and on-chain at most once, against the allowance
     * written here, which it uses up.
     */
    fun resetSecureSession(peerAddress: String) {
        viewModelScope.launch {
            // T1b-1 §2: the Keystone check is the reset's first step, whatever the mode. An Open chat's reset pays
            // nothing, but it wiped the keys and sent a relay handshake under the Keystone identity before this check.
            if (keystoneAccountSelected()) {
                _sendMessageState.value = SendMessageState.Error(ChatSendCopy.KEYSTONE_AUTOMATIC_SETUP)
                return@launch
            }
            userStartsSetupAgain(peerAddress)
            if (!resetEncryptionPaysOnChain(peerAddress)) {
                val skippedOnChainStep = zchatPreferences.getPeerNostrPubkey(peerAddress) == null
                wipeAndReestablishSecureSession(peerAddress)
                if (skippedOnChainStep) _sendMessageState.value = SendMessageState.Success(ChatSendCopy.OPEN_NO_ONCHAIN_STEP)
                return@launch
            }
            askBeforePaying(PaidAction.RESET_ENCRYPTION, onChainMessages = 2) {
                // ZC-285: the process-wide scope, not this screen's: leaving the chat never cancels the paid reset.
                processSendScope().launch(Dispatchers.Main.immediate) {
                    try {
                        resetAndPayOwedKex(peerAddress)
                    } catch (e: Exception) {
                        if (e is kotlinx.coroutines.CancellationException) throw e
                        Log.w("KEX", "Reset encryption failed: ${e.javaClass.simpleName}")
                    }
                }
            }
        }
    }

    /**
     * ZC-285, ZC-286 — the confirmed, paid reset of [resetSecureSession]: Keystone check, the owed KEX and the ZBOOT
     * allowance recorded (each write confirmed), the wipe, then the KEX paid on the Reset's own confirm.
     */
    private suspend fun resetAndPayOwedKex(peerAddress: String) {
        // The selected account may have changed while the question was open (T1b-1: in any mode).
        if (keystoneAccountSelected()) {
            _sendMessageState.value = SendMessageState.Error(ChatSendCopy.KEYSTONE_AUTOMATIC_SETUP)
            return
        }
        // The mode may have changed while the price question was open.
        if (openNeverSpends(peerAddress)) {
            wipeAndReestablishSecureSession(peerAddress)
            _sendMessageState.value = SendMessageState.Success(ChatSendCopy.OPEN_NO_ONCHAIN_STEP)
            return
        }
        if (!recordQuotedOwedKex(peerAddress, ZchatPreferences.KEX_OWED_REASON_RESET)) {
            _sendMessageState.value = SendMessageState.Error(ChatSendCopy.STORAGE_PAUSED_PAID_STEP)
            return
        }
        kexOwedPeers.add(peerAddress)
        wipeAndReestablishSecureSession(peerAddress, kexOwed = true)
        payQuotedOwedKex(peerAddress, "Reset")
    }

    /**
     * ZC-285, ZC-300 — pay now the KEX a confirmed question (Reset encryption, the key-change reconnect) recorded as owed
     * to [peerAddress] ([recordQuotedOwedKex]); [what] names that action in the log. The confirm is the consent. When it
     * cannot go now (our chat identity not read, funds still confirming, no funds, another attempt running) it stays owed
     * and a later block or chat open pays it, once ([retryOwedKeyExchange]). A Keystone refusal (the account changed after
     * the caller's check) keeps it owed for the account that confirmed it and shows the Keystone text.
     */
    private suspend fun payQuotedOwedKex(
        peerAddress: String,
        what: String,
        confirmedPrice: KexAnswerPrice? = null,
    ) {
        // T1b-1 §2: the KEX carries the selected account's address. Not readable now: the KEX stays owed for a later block.
        val ourAddress = currentChatIdentity()
        if (ourAddress == null) {
            Log.w("KEX", "$what KEX to ${peerAddress.redactAddress()} owed: our chat identity was not read; paid later")
            return
        }
        val result = payOwedKex(peerAddress, ourAddress, forSend = true, voidOnKeystoneRefusal = false, confirmedPrice = confirmedPrice)
        when (result) {
            OwedKex.Done -> Log.d("KEX", "$what KEX to ${peerAddress.redactAddress()} settled")
            OwedKex.Busy, OwedKex.OtherAccount -> Log.d("KEX", "$what KEX to ${peerAddress.redactAddress()} stays owed")
            OwedKex.KeptForAnotherMode -> Log.d("KEX", "$what KEX stays owed for another chat mode")
            OwedKex.KeyDecisionWaits -> Log.d("KEX", "$what KEX stays owed: the contact's new key waits for the user")
            // F8: an earlier KEX of this key is still on the chain (or waits for Retry): nothing paid, the mark stays.
            OwedKex.Pending -> Log.d("KEX", "$what KEX to ${peerAddress.redactAddress()} waits for an earlier attempt of its key")
            is OwedKex.NotSent ->
                if (result.error.isKeystoneRefusal()) {
                    // The account changed after the caller's check; the KEX stays owed for the account that confirmed it.
                    _sendMessageState.value = SendMessageState.Error(ChatSendCopy.KEYSTONE_AUTOMATIC_SETUP)
                } else {
                    Log.w("KEX", "$what KEX not sent yet (${result.error.javaClass.simpleName}); a later block or chat open pays it")
                }
        }
    }

    /**
     * ZC-285, ZC-300 — before a confirmed Reset wipes anything, or a confirmed key-change reconnect clears the flag and
     * drops the relay key: the KEX owed to [peerAddress] (the confirming account when it can be read, [reason]
     * ([ZchatPreferences.KEX_OWED_REASON_RESET] or [ZchatPreferences.KEX_OWED_REASON_RECONNECT]), the mark) and the
     * allowance of the ZBOOT the question quoted. True only when every write was confirmed; otherwise what this call wrote
     * is undone (a mark or allowance that was there before is kept) and false is returned, so nothing is changed or paid.
     *
     * ZC-535: a key-change reconnect records only the legs its plan found due ([reconnectPlan]): the account, the reason
     * and the owed mark only with [kexLeg], the allowance only with [zbootLeg]. The defaults are the Reset's: both.
     */
    private suspend fun recordQuotedOwedKex(
        peerAddress: String,
        reason: String,
        kexLeg: Boolean = true,
        zbootLeg: Boolean = true,
    ): Boolean {
        // ZC-1272: a Reset or a reconnect is its own confirmed question; what an earlier one covered no longer stands.
        if (quotedChatSetup(peerAddress) != null) storeQuotedChatSetup(peerAddress, null)
        val wasOwed = zchatPreferences.isKexOwed(peerAddress)
        val earlierAccount = zchatPreferences.getKexOwedAccount(peerAddress)
        val earlierReason = zchatPreferences.getKexOwedReason(peerAddress)
        val quoteScope = zbootScope(peerAddress)
        val confirmingAccount = selectedAccountOrNull()
        val kexSaved =
            !kexLeg ||
                (
                    // FC-ID (5.3a item 4): the lone key exchange's id is made where its owed mark is written.
                    planOwnConversationId(peerAddress) != null &&
                        (
                            confirmingAccount == null ||
                                zchatPreferences.setKexOwedAccount(
                                    peerAddress,
                                    GetDefaultUnifiedAddressUseCase.accountKeyOf(confirmingAccount),
                                )
                        ) &&
                        zchatPreferences.setKexOwedReason(peerAddress, reason) &&
                        zchatPreferences.setKexOwed(peerAddress, true)
                )
        val saved =
            kexSaved &&
                if (zbootLeg) {
                    // Publish this quote's owner only after the final synchronous paid-record check succeeds.
                    recordZbootQuote(
                        peerAddress,
                        account = confirmingAccount?.let(GetDefaultUnifiedAddressUseCase::accountKeyOf),
                        protectedSession =
                            reason == ZchatPreferences.KEX_OWED_REASON_RESET ||
                                reason == ZchatPreferences.KEX_OWED_REASON_RECONNECT,
                        scope = quoteScope,
                        finishGrant = { !kexLeg || forgetExpiredKexPaidRecord(peerAddress) },
                    )
                } else {
                    !kexLeg || forgetExpiredKexPaidRecord(peerAddress)
                }
        if (!saved) {
            Log.e("KEX", "Paid step ($reason) not started: its owed-KEX records could not be saved — nothing changed or paid")
            if (kexLeg) {
                if (wasOwed) {
                    zchatPreferences.setKexOwedAccount(peerAddress, earlierAccount)
                    zchatPreferences.setKexOwedReason(peerAddress, earlierReason)
                } else {
                    // Also removes the account and the reason written above.
                    zchatPreferences.setKexOwed(peerAddress, false)
                }
            }
        }
        return saved
    }

    /** ZC-880 — an Open contact never pays for a direct-chat handshake. */
    private fun openNeverSpends(peerAddress: String): Boolean =
        zchatPreferences.getConversationMode(peerAddress) == co.electriccoin.zcash.ui.screen.chat.model.ConversationMode.OPEN

    /** Round 8 D5, ZC-880 — Reset has a paid plan only outside an Open chat. */
    private fun resetEncryptionPaysOnChain(peerAddress: String): Boolean = !openNeverSpends(peerAddress)

    /**
     * The reset itself ([resetSecureSession]): wipe this contact's session and re-run the first-contact handshake.
     *
     * ZC-285: [kexOwed] is the paid reset, whose KEX is already recorded as owed and is paid by its caller through
     * [payOwedKex]. The bootstrap marker is then left SET (the owed mark carries our KEX, so no bootstrap trigger pays a
     * second KEX under the standing consent or raises its question) and no bootstrap is started here. The free reset (an
     * Open chat) re-runs the bootstrap without an on-chain KEX.
     */
    private suspend fun wipeAndReestablishSecureSession(
        peerAddress: String,
        kexOwed: Boolean = false,
    ) {
        // ZC-545, ZC-564: under the contact's session lock, so no decrypt or encrypt is in its ratchet call while the
        // state is deleted (a save after the delete left old-root counters for the next root), and none starts until the
        // keys are gone. The epoch is raised last: every ViewModel's cached processor of this contact is retired.
        withPeerSession(peerAddress) {
            wipeRatchetState(peerAddress)
            wipeSessionPrefs(peerAddress, ownBootSent = kexOwed, keepOurKeys = false, keepRefusal = false)
            bumpPeerSessionEpoch(peerAddress)
        }
        Log.d("ZCHAT_E2E", "Reset secure session for ${peerAddress.take(16)}… — re-running first-contact handshake")
        // B6 FIX 1 — re-establish with a SINGLE KEX. ensureNostrBootstrapSent(force=true) already fires
        // the KEX (leg 1); the old code ALSO called sendKEXMessage directly right before it, so two KEX
        // txs raced for the one spendable note → one failed with "No Orchard input" → the peer never got
        // our new key and the sender was wedged "can't send". One KEX, one note, clean re-establish.
        // ZC-285: the paid reset's KEX is the owed one its caller pays; no bootstrap here.
        if (!kexOwed) ensureNostrBootstrapSent(peerAddress, force = true)
    }

    /**
     * ZC-545 (G1) — the ratchet half of a session wipe: the cached processors and the persisted ratchet state under
     * every conversation id of [peerAddress]. Only ever called inside [withPeerSession]: by Reset encryption
     * ([wipeAndReestablishSecureSession]) and by the accept of a contact's new key ([adoptRefusedKey]).
     */
    private suspend fun wipeRatchetState(peerAddress: String) {
        // Drop cached in-memory ratchet processors for this peer (any convId) so the next decrypt/
        // encrypt rebuilds from the fresh root rather than the stale cached one.
        synchronized(messageProcessors) { messageProcessors.keys.removeAll { it.startsWith("$peerAddress:") } }
        // Wipe the persistent ratchet counters for this conversation — under EVERY conversation id of the peer:
        // a new ratchet carries the floors kept per conversation id into its root's floor (R2-4), so an old
        // id's counters left here would start the fresh root above 0. The fresh root has its own floor key.
        val convId = convIdMutex.withLock { zchatPreferences.getOrCreateConversationId(peerAddress).first }
        for (id in conversationIdsOf(peerAddress) + convId) runCatching { ratchetStateStore.delete(id) }
    }

    /**
     * ZC-545 (G1, G2) — the preference half of a session wipe; it does not suspend. Reset encryption wipes everything
     * ([keepOurKeys] and [keepRefusal] false, [ownBootSent] = its KEX is owed). The accept of a contact's new key keeps
     * our own key pair, the key-changed flag and the remembered key ([ZchatPreferences.clearE2EPeerState]) and the
     * refusal notice: they go with its last write.
     */
    private fun wipeSessionPrefs(
        peerAddress: String,
        ownBootSent: Boolean,
        keepOurKeys: Boolean,
        keepRefusal: Boolean,
        // ZC-636: keep the delivered-identity marker (a Tunnel accept whose quote did not count our ZBOOT).
        keepSentBoot: Boolean = false,
    ) {
        // Wipe E2E identity keys (+ kex txids + trust flags), the Quantum-Shield PSK (also feeds the
        // root), and ALL handshake progress markers so a clean first-contact KEX/ZBOOT is forced.
        if (keepOurKeys) zchatPreferences.clearE2EPeerState(peerAddress) else zchatPreferences.clearE2EKeys(peerAddress)
        // ZC-250: clearE2EKeys clears the key-change flag with the keys; its refusal notice goes too.
        if (!keepRefusal) clearKeyChangeRefusal(peerAddress)
        // clearE2EKeys also unsets the "E2E enabled" flag, but a Reset RE-establishes encryption — it
        // must NOT leave the chat marked unencrypted. Keep the intent ON so (a) the header reflects
        // "encryption: finishing key exchange…" not "Off", and (b) the send path's confidentiality
        // guard ABORTS any send during the keys-not-ready window instead of falling back to plaintext.
        zchatPreferences.setE2EEnabled(peerAddress, true)
        runCatching { zchatPreferences.clearQuantumShieldPSK(peerAddress) }
        zchatPreferences.setPeerBootEpoch(peerAddress, 0L)
        zchatPreferences.setOwnBootSent(peerAddress, ownBootSent)
        if (!keepSentBoot) zchatPreferences.setSentNostrBootPubkey(peerAddress, null)
        zchatPreferences.setSentKexAckPubkey(peerAddress, null)
        // B6 FIX 2 — do NOT wipe the peer's NOSTR transport identity here. Resetting E2E TRUST is not
        // the same as resetting the TRANSPORT: keeping the peer's NOSTR pubkey/relay preserves inbound
        // DM attribution (NostrChatBridge.dispatch) and the TUNNEL delivery channel THROUGHOUT the
        // re-KEX, which is what ends the "nothing arrives in the other chat" bidirectional blackout the
        // user hit. The fresh KEX's piggybacked pubkey is adopted via the authenticated rotation path
        // (#225), and E2E key-change TOFU is handled separately — so we don't need this wipe to avoid a
        // false MITM trip. (The B4 fail-closed decrypt + convergent-root recompute cover the crypto.)
        kexAckedKeys.remove(peerAddress)
    }

    /**
     * ZC-545, ZC-564 (G10, R9) — run [block] holding the per-contact session lock ([peerSessionLocks]). Users of a
     * ratchet processor take it around [obtain the processor, its ratchet call, its synchronous bookkeeping]; Reset's
     * wipe, the accept of a contact's new key and "Not their key" take it around their changes. Never held across a
     * proposal, a relay call or a screen state, and never nested (a coroutine Mutex is not re-entrant).
     */
    private suspend inline fun <T> withPeerSession(
        peerAddress: String,
        block: () -> T,
    ): T {
        val lock = peerSessionLocks.computeIfAbsent(peerAddress) { Mutex() }
        lock.lock()
        try {
            return block()
        } finally {
            lock.unlock()
        }
    }

    /** ZC-545, ZC-564 — the number of session wipes of [peerAddress] in this process ([peerSessionEpochs]). */
    private fun peerSessionEpoch(peerAddress: String): Long = peerSessionEpochs[peerAddress]?.get() ?: 0L

    /** ZC-545, ZC-564 — a wipe's last step inside the lock: every ViewModel's cached processor of the contact is retired. */
    private fun bumpPeerSessionEpoch(peerAddress: String) {
        val epoch =
            peerSessionEpochs
                .computeIfAbsent(peerAddress) {
                    java.util.concurrent.atomic
                        .AtomicLong()
                }.incrementAndGet()
        // This instance dropped its own processors in the wipe; it has seen the new epoch.
        synchronized(messageProcessors) { processorEpochsSeen?.put(peerAddress, epoch) }
    }

    /**
     * ZC-545, ZC-564 — the cross-instance half of the quiesce. The processor cache is per ViewModel instance and a wipe
     * drops only its own instance's entries, so the list's and another chat screen's cached processor kept the old
     * root. An instance remembers the session epoch it last looked a contact's processor up under; when the epoch has
     * moved (a wipe ran in any instance) it drops its cached processors of that contact before serving one. An
     * instance's first lookup has nothing stale to drop. Call inside `synchronized(messageProcessors)` with the
     * [epoch] read before anything else of the lookup.
     */
    private fun retireProcessorsOfEarlierEpoch(
        peerAddress: String,
        epoch: Long,
    ) {
        val seen =
            processorEpochsSeen
                ?: java.util.concurrent
                    .ConcurrentHashMap<String, Long>()
                    .also { processorEpochsSeen = it }
        val earlier = seen.put(peerAddress, epoch)
        if (earlier != null && earlier != epoch) {
            messageProcessors.keys.removeAll { it.startsWith("$peerAddress:") }
        }
    }

    /** B17 label for a TTL (seconds) → "1 minute" / "1 hour" / "2 days" etc. */
    private fun ttlLabel(seconds: Long): String = when (seconds) {
        60L -> "1 minute"; 3600L -> "1 hour"; 86400L -> "1 day"; 604800L -> "1 week"
        else -> when {
            seconds % 86400L == 0L -> "${seconds / 86400L} days"
            seconds % 3600L == 0L -> "${seconds / 3600L} hours"
            else -> "${seconds / 60L} minutes"
        }
    }

    /**
     * B17 — set (or turn off) disappearing messages for a conversation and SYNC it to the peer inside the
     * AUTHENTICATED carrier (E2E ratchet on-chain / NIP-17 seal on NOSTR). Never sends the control as
     * plaintext (#187 — TTL mutates message retention). Applies to NEW messages only, on both devices.
     *
     * ZC-297: the one note of a change (SysNotes.ttlNoteId) is written after the send and says what is known: handed
     * off (a relay every ZChat version reads took it, or the Shielded submit returned), on this phone only (not handed
     * off), or not known yet (a send that failed part-way may have gone out). With no chat identity nothing is set.
     */
    fun setDisappearingTtl(peerAddress: String, ttlSeconds: Long, costConfirmed: Boolean = false) {
        // T1b-1 §2: the chat is closed on every transport while a Keystone account is selected; the timer stays.
        if (chatClosedForSelectedAccount()) {
            refuseClosedChat("a disappearing timer")
            return
        }
        if (blockedByKeyChange(peerAddress)) return
        // R2-2 (b): in a Shielded chat the timer travels as one paid on-chain control message. Ask first; the
        // timer is not changed until the user confirms. T3-extra: never for one of our own addresses, which is never paid
        // (the refusal below says why).
        if (!costConfirmed &&
            zchatPreferences.getConversationMode(peerAddress) == co.electriccoin.zcash.ui.screen.chat.model.ConversationMode.VAULT &&
            !zchatPreferences.isSelfAddress(peerAddress)
        ) {
            // ZC-1822: the timer stays as it is.
            if (refusedByTheSpendableMargin(paidActionConfirmation(PaidAction.DISAPPEARING_TIMER, 1).totalCost)) return
            askBeforePaying(PaidAction.DISAPPEARING_TIMER, onChainMessages = 1) {
                setDisappearingTtl(peerAddress, ttlSeconds, costConfirmed = true)
            }
            return
        }
        viewModelScope.launch {
            val since = System.currentTimeMillis()
            // Round 8 D8: set by the use case right before it asks the SDK to store and broadcast the on-chain timer.
            var timerSubmitStarted = false
            // ZC-297: the id of this change's note from the moment the timer is set until the note is written.
            var owedNoteId: String? = null
            // F8 (ZC-112, SPEC §4.9): the paid timer's send attempt (note-only, fail-open, no gate: each tap is its own).
            var timerCapture: LedgerCapture? = null
            try {
                val mode = zchatPreferences.getConversationMode(peerAddress)
                // T3-extra, rule (E): in a Shielded chat the timer would be paid to the chat's address. For one of our own
                // addresses nothing is paid, also for a change confirmed earlier, and (as D10 below) nothing is set on this
                // phone alone.
                if (mode == co.electriccoin.zcash.ui.screen.chat.model.ConversationMode.VAULT &&
                    zchatPreferences.isSelfAddress(peerAddress)
                ) {
                    Log.w("ZCHAT_SEND", "T3-extra: a timer for one of our own addresses not set and not paid")
                    _sendMessageState.value = SendMessageState.Error(ChatSendCopy.TIMER_OWN_ADDRESS_NOT_PAID)
                    return@launch
                }
                // ZC-297: the control names our chat identity, so it is read before anything is set (as D10 below). It was
                // read after the timer and its "on both devices" note were written, and with none the change ended there
                // with no notice.
                val userAddress = currentChatIdentity()
                if (userAddress == null) {
                    Log.w("ZCHAT_SEND", "ZC-297: no chat identity, so the timer is not set and nothing is sent")
                    _sendMessageState.value = SendMessageState.Error(ChatSendCopy.TIMER_SYNC_FAILED)
                    return@launch
                }
                // Round 8 D10 (DECISIONS_NIGHT §5): in a Shielded chat the timer reaches the contact only inside the
                // ratchet. With no ratchet it is refused BEFORE anything is set on this phone: it used to be set here
                // (with its "Messages now disappear" note) and then refused, so it stayed on for this phone only while
                // the refusal said to set it once the key exchange finished.
                val vaultChannel =
                    if (mode != co.electriccoin.zcash.ui.screen.chat.model.ConversationMode.VAULT) {
                        null
                    } else {
                        // R4-4 (1): through the per-message call, so an id this control creates is marked "INIT not sent"
                        // like one a message creates (R2-6 c, R3-2 1). A control carries no user message; the first
                        // message after it must still be the v4 INIT naming our address, never a REPLY the recipient
                        // cannot place. An existing id is returned unchanged.
                        val convId = convIdMutex.withLock { zchatPreferences.getOrCreateConversationIdForMessage(peerAddress).first }
                        // ZC-545, ZC-564: a readiness probe only. The processor is obtained again, with its encrypt, in
                        // one session block below; none is held across the steps in between.
                        val ratchetReady =
                            withPeerSession(peerAddress) {
                                getOrCreateMessageProcessor(peerAddress, convId, forSend = true) != null
                            }
                        if (!ratchetReady) {
                            _sendMessageState.value =
                                SendMessageState.Error(
                                    // Round 8 D8 (F31): a toast has no Retry button, so the history hold says to set it again.
                                    sendRefusedReason(
                                        peerAddress,
                                        ChatSendCopy.TIMER_NEEDS_KEY_EXCHANGE,
                                        ChatSendCopy.CONTROL_STILL_READING_HISTORY,
                                    ),
                                )
                            return@launch
                        }
                        convId
                    }
                if (!zchatPreferences.setDisappearingTtl(peerAddress, ttlSeconds, since)) return@launch
                // ZC-297: the note waits for the send. It used to be written here, before anything was sent, and kept
                // saying "on both devices" in the chat history when nothing reached the contact.
                val noteId =
                    co.electriccoin.zcash.ui.screen.chat.model.SysNotes
                        .ttlNoteId(peerAddress, since)
                owedNoteId = noteId
                val deliveredNote =
                    if (ttlSeconds > 0L) {
                        "⏳ Messages now disappear after ${ttlLabel(ttlSeconds)}. Applies to new messages, on both devices."
                    } else {
                        "⏳ Disappearing messages turned off."
                    }
                val ttlMemo = ZMSGProtocol.createDisappearSetting(ttlSeconds, since, userAddress)
                if (vaultChannel == null) {
                    val peerPub = zchatPreferences.getPeerNostrPubkey(peerAddress)
                    val bridge = co.electriccoin.zcash.ui.nostr.NostrChatBridge
                    // Null: no publish was started (no relay key for the contact, or the relay service is not up).
                    val published =
                        if (peerPub != null && bridge.isOutboundReady()) {
                            runCatching { bridge.publish(ttlMemo, peerPub) }
                        } else {
                            null
                        }
                    // ZC-393: the relays every ZChat version reads that took it. A copy only a public relay took is not
                    // handed off, for the note as for the notice below.
                    val acks = published?.getOrNull()?.acks ?: 0
                    owedNoteId = null
                    emitSystemNote(
                        peerAddress,
                        noteId,
                        when {
                            acks > 0 -> deliveredNote
                            // A publish that started and then failed or was cancelled may have reached a relay.
                            published?.isFailure == true -> noteCopy.get(R.string.chat_note_timer_maybe_sent)
                            else -> noteCopy.get(R.string.chat_note_timer_this_phone_only)
                        },
                    )
                    if (acks == 0) {
                        // Round 8 D8: nothing re-sends a timer, so the user is told to set it again (it promised a sync).
                        _sendMessageState.value = SendMessageState.Error(ChatSendCopy.TIMER_NOT_DELIVERED)
                    }
                    return@launch
                }
                // VAULT: the control MUST ride inside an E2E1 ratchet blob (never plaintext).
                val convId: String = vaultChannel
                // ZC-545, ZC-564: obtain and encrypt in one session block. A session wiped since the probe (a Reset, an
                // accepted new key) has no processor: nothing is encrypted to the old root and nothing is sent.
                val enc =
                    withPeerSession(peerAddress) {
                        val processor =
                            getOrCreateMessageProcessor(peerAddress, convId, forSend = true)
                                ?: throw UserFacingSendRefusal(ChatSendCopy.TIMER_NEEDS_KEY_EXCHANGE)
                        // Self-cache the control plaintext so our own mined ZDIS tx is still recognized
                        // (and suppressed as a bubble) on rescan even if the ratchet state is gone.
                        processor.encryptOutgoing(ttlMemo).also { cacheOwnOutgoingPlaintext(convId, it, ttlMemo) }
                    }
                // R2-5 (c): inside the v4 envelope that names the conversation, like every encrypted message. A
                // bare E2E1 memo names no conversation, so the contact's device could never pick the ratchet to
                // decrypt it with and the timer never synced on chain.
                createChunkedMessageProposal(
                    destinationAddress = peerAddress,
                    senderAddress = userAddress,
                    message = enc,
                    isFirstMessage = false,
                    directSubmit = true,
                    skipNavigation = true,
                    conversationId = convId,
                    onSubmitStarting = {
                        timerCapture =
                            sendAttempts?.let { LedgerCapture(it, SendAttemptTag(SendAttemptKind.TIMER, peerAddress, since.toString())) }
                        timerCapture?.begin()
                        timerSubmitStarted = true
                        timerCapture?.killSeam()
                    },
                    onTransactionsStored = if (sendAttempts != null) ({ stored -> timerCapture?.stored(stored) }) else null,
                )
                // ZC-297: the submit returned, so the control was handed to the SDK.
                owedNoteId = null
                emitSystemNote(peerAddress, noteId, deliveredNote)
            } catch (e: Exception) {
                // Round 8 D8: a timer the SDK may have stored is not "try again" (that would pay a second time).
                val nothingSent = memoFailureProvesNothingSent(e, timerSubmitStarted)
                // F8: an attempt that provably sent nothing leaves no entry (its note below already says so).
                if (nothingSent) timerCapture?.discard()
                // ZC-297: the timer is set on this phone, so its note is still written, and says which of the two it is.
                owedNoteId?.let { noteId ->
                    emitSystemNote(
                        peerAddress,
                        noteId,
                        noteCopy.get(
                            if (nothingSent) R.string.chat_note_timer_this_phone_only else R.string.chat_note_timer_maybe_sent,
                        ),
                    )
                }
                _sendMessageState.value =
                    SendMessageState.Error(
                        if (nothingSent) {
                            e.toZchatUserMessage(ChatSendCopy.TIMER_SYNC_FAILED)
                        } else {
                            SubmitAttemptProof.MAY_HAVE_BEEN_SENT
                        },
                    )
            } finally {
                timerCapture?.close()
            }
        }
    }

    /**
     * B17 — adopt a peer's disappearing-messages TTL control (authenticated by the caller before this runs).
     * Monotonic (last-writer-wins on effectiveSince) so replays/rescans are idempotent; the incoming since is
     * clamped to now+5min so a forged far-future clock can't lock the victim out of changing their own timer.
     */
    private fun handleDisappearControl(peerAddress: String, memo: String) {
        val parsed = ZMSGProtocol.parseDisappearSetting(memo) ?: return
        val since = minOf(parsed.effectiveSinceMillis, System.currentTimeMillis() + 300_000L)
        if (!zchatPreferences.setDisappearingTtl(peerAddress, parsed.ttlSeconds, since)) return
        val name = peerLabel(peerAddress)
        emitSystemNote(
            peerAddress,
            co.electriccoin.zcash.ui.screen.chat.model.SysNotes.ttlNoteId(peerAddress, since),
            if (parsed.ttlSeconds > 0L) "⏳ $name set messages to disappear after ${ttlLabel(parsed.ttlSeconds)}."
            else "⏳ $name turned off disappearing messages.",
        )
        loadConversations()
    }

    /**
     * TX-1: the contact's name in a system note, in the chat header's order: the nickname, then the contact-book name,
     * then the short address (getDisplayName). A blank name counts as none. A contact-book read that throws falls back
     * to the short address, so naming the contact can never stop a note (or the mode or timer change it records).
     */
    private fun peerLabel(address: String): String =
        zchatPreferences.getNickname(address)?.takeIf { it.isNotBlank() }
            ?: runCatching { contactBook.getContact(address)?.name }.getOrNull()?.takeIf { it.isNotBlank() }
            ?: zchatPreferences.getDisplayName(address)

    /** User-facing label for a conversation mode (pills + notes). VAULT displays as "Shielded". */
    private fun modeLabel(mode: co.electriccoin.zcash.ui.screen.chat.model.ConversationMode): String =
        noteCopy.get(modeNoteLabelRes(mode))

    /** One pill per (peer, since) mode change — same shape as SysNotes.ttlNoteId (ID_PREFIX + tag +
     *  hashed peer + since), built here to keep SysNotes.kt untouched (owned by a parallel edit). */
    private fun modeChangeNoteId(peerAddress: String, sinceMillis: Long): String =
        co.electriccoin.zcash.ui.screen.chat.model.SysNotes.ID_PREFIX + "mode-" +
            java.security.MessageDigest.getInstance("SHA-256")
                .digest(peerAddress.toByteArray(Charsets.UTF_8))
                .joinToString("") { "%02x".format(it) }
                .take(12) + "-$sinceMillis"

    /**
     * Cross-device CONVERSATION-MODE change (mirrors B17 [setDisappearingTtl]): persist the user's
     * explicit mode choice locally, pill it, and SYNC it to the peer inside the AUTHENTICATED carrier
     * (NIP-17 seal over NOSTR / E2E ratchet on-chain) so the peer's device stops using the stale mode
     * — the old behavior left peer B on VAULT paying per message (or watching a dead tunnel) after A
     * had switched. Never sent as plaintext (#187 — the mode mutates transport routing + billing).
     *
     * Transport for the control itself: prefer the FREE NOSTR channel whenever the tunnel handshake
     * has completed (peer pubkey known + outbound ready); otherwise only a chat that was ALREADY on
     * paid VAULT may fall back to an on-chain E2E memo. A chat on OPEN/TUNNEL (or one switching to
     * OPEN) NEVER spends ZEC for this control (#224 invariant) — if the relay is unreachable the
     * change stays local and the user is told it hasn't synced yet.
     */
    fun changeConversationMode(
        peerAddress: String,
        newMode: co.electriccoin.zcash.ui.screen.chat.model.ConversationMode,
        costConfirmed: Boolean = false,
    ) {
        // T1b-1 §2: the chat is closed on every transport while a Keystone account is selected; the mode stays.
        if (chatClosedForSelectedAccount()) {
            refuseClosedChat("a mode change")
            return
        }
        if (blockedByKeyChange(peerAddress)) return
        // R2-2 (b): leaving a Shielded chat with no relay channel sends the change as one paid on-chain control
        // message (the rule below). Ask first; the mode is not changed until the user confirms.
        if (!costConfirmed && modeChangeGoesOnChain(peerAddress, newMode)) {
            // ZC-1822: the mode stays as it is.
            if (refusedByTheSpendableMargin(paidActionConfirmation(PaidAction.MODE_CHANGE, 1).totalCost)) return
            askBeforePaying(PaidAction.MODE_CHANGE, onChainMessages = 1) {
                changeConversationMode(peerAddress, newMode, costConfirmed = true)
            }
            return
        }
        viewModelScope.launch {
            val previousMode = zchatPreferences.getConversationMode(peerAddress)
            // Persist + pin FIRST, even when re-picking the current mode: the explicit pin is what makes
            // a deliberate VAULT choice sticky against rotation-ZBOOT auto-upgrades (P1.2) and against
            // peer ZMODE auto-adopt. Re-picking the same mode transmits NOTHING (and shows no pill).
            zchatPreferences.setConversationMode(peerAddress, newMode)
            zchatPreferences.setConversationModeExplicit(peerAddress)
            if (newMode == previousMode) return@launch
            val since = System.currentTimeMillis()
            // ZC-1478 (M3): our own last switch, so a contact's older crossed switch does not replace it. The user picked
            // this mode, so a mark that the contact moved the chat to a paid mode no longer applies (M1).
            zchatPreferences.setOwnModeChangeSince(peerAddress, since)
            zchatPreferences.setModeMovedToPaidByPeer(peerAddress, false)
            emitSystemNote(
                peerAddress,
                modeChangeNoteId(peerAddress, since),
                // ZC-1478 (S7): a switch to Shielded says what a contact on 2.13 and on 2.12.4 does with it.
                if (newMode == ConversationMode.VAULT) {
                    noteCopy.get(R.string.chat_note_you_switched_shielded, modeLabel(newMode))
                } else {
                    noteCopy.get(R.string.chat_note_you_switched, modeLabel(newMode))
                },
            )
            // Round 8 D8: set by the use case right before it asks the SDK to store and broadcast the on-chain change.
            var modeSubmitStarted = false
            try {
                val userAddress = _currentUserAddress.value ?: run {
                    // Address not loaded yet — arm the durable retry so the change still reaches the peer.
                    zchatPreferences.setPendingModeSync(peerAddress, newMode.name, since)
                    return@launch
                }
                val modeMemo = ZMSGProtocol.createModeChange(newMode, since, userAddress)
                val peerPub = zchatPreferences.getPeerNostrPubkey(peerAddress)
                if (peerPub != null && co.electriccoin.zcash.ui.nostr.NostrChatBridge.isOutboundReady()) {
                    val acks = runCatching {
                        co.electriccoin.zcash.ui.nostr.NostrChatBridge.publish(modeMemo, peerPub)
                    }.getOrNull()?.acks ?: 0
                    if (acks == 0) {
                        // #37 delivery fix: a one-shot publish with no ack used to be the END of the
                        // story — "it'll show on their side" was a lie (nothing ever re-sent, so a peer
                        // switching to Shielded never actually prompted the other device). Persist the
                        // undelivered control; retryPendingModeSyncs re-publishes it FREE over NOSTR
                        // until a relay acks. The receiver's monotonic since-guard dedups replays.
                        zchatPreferences.setPendingModeSync(peerAddress, newMode.name, since)
                        _sendMessageState.value = SendMessageState.Error(ChatSendCopy.MODE_NOT_DELIVERED)
                    } else {
                        zchatPreferences.clearPendingModeSync(peerAddress)
                    }
                    // SR-B1: the chat left Shielded — the contact gets our avatar now, after the mode change. Not taken by a
                    // relay → still owed, sent again by the next launch tick.
                    if (previousMode == ConversationMode.VAULT && newMode != ConversationMode.VAULT) pushSelfAvatarTo(peerAddress)
                    return@launch
                }
                // T3-extra, rule (E): the on-chain carrier below would pay the chat's address. For one of our own addresses
                // nothing is paid, also for a change confirmed earlier: the mode stays changed on this phone and no retry is
                // armed (there is no one else to tell).
                if (zchatPreferences.isSelfAddress(peerAddress)) {
                    Log.w("ZCHAT_MODE", "T3-extra: a mode change for one of our own addresses kept on this phone, not paid")
                    _sendMessageState.value = SendMessageState.Error(ChatSendCopy.MODE_OWN_ADDRESS_NOT_PAID)
                    return@launch
                }
                // No NOSTR channel. Only a chat that was ALREADY paying per message (VAULT) may carry the
                // control on-chain — and never toward OPEN (#224: an OPEN switch must not spend ZEC; OPEN
                // requires the peer's NOSTR key anyway, so the free path above is its real carrier).
                if (previousMode != co.electriccoin.zcash.ui.screen.chat.model.ConversationMode.VAULT ||
                    newMode == co.electriccoin.zcash.ui.screen.chat.model.ConversationMode.OPEN
                ) {
                    // Arm the free-NOSTR retry: delivers once the peer's key arrives / the relay is back.
                    zchatPreferences.setPendingModeSync(peerAddress, newMode.name, since)
                    _sendMessageState.value = SendMessageState.Error(ChatSendCopy.MODE_RELAY_UNREACHABLE)
                    return@launch
                }
                // VAULT: the control MUST ride inside an E2E1 ratchet blob (never plaintext).
                // R4-4 (1): through the per-message call, so an id this control creates is marked "INIT not sent" like
                // one a message creates (R2-6 c, R3-2 1). A control carries no user message; the first message after it
                // must still be the v4 INIT naming our address, never a REPLY the recipient cannot place. An existing
                // id is returned unchanged.
                val convId = convIdMutex.withLock { zchatPreferences.getOrCreateConversationIdForMessage(peerAddress).first }
                // ZC-545, ZC-564: a readiness probe only; the processor is obtained again with its encrypt below.
                val ratchetReady =
                    withPeerSession(peerAddress) {
                        getOrCreateMessageProcessor(peerAddress, convId, forSend = true) != null
                    }
                if (!ratchetReady) {
                    zchatPreferences.setPendingModeSync(peerAddress, newMode.name, since)
                    // Round 8 D8 (F31): neither text points to Retry (a toast has none) or to re-picking the mode (that
                    // sends nothing); finishing the key exchange does not send the change either, so neither promises it.
                    _sendMessageState.value =
                        SendMessageState.Error(
                            sendRefusedReason(
                                peerAddress,
                                ChatSendCopy.MODE_NEEDS_KEY_EXCHANGE,
                                ChatSendCopy.MODE_STILL_READING_HISTORY,
                            ),
                        )
                    return@launch
                }
                // T3b-1: the on-chain carrier is paid only on a confirmed quote. A change that reaches it unasked (the keys
                // or the relay changed after the question was decided) stays on this device and is delivered free later.
                if (!costConfirmed) {
                    Log.w("ZCHAT_MODE", "T3b-1: an on-chain mode change no question quoted — kept on this device, not paid")
                    zchatPreferences.setPendingModeSync(peerAddress, newMode.name, since)
                    _sendMessageState.value = SendMessageState.Error(ChatSendCopy.MODE_RELAY_UNREACHABLE)
                    return@launch
                }
                // ZC-545, ZC-564: obtain and encrypt in one session block; a session wiped since the probe has no processor,
                // so nothing is encrypted to the old root (the change stays on this device for the free retry, below).
                val enc =
                    withPeerSession(peerAddress) {
                        val processor =
                            getOrCreateMessageProcessor(peerAddress, convId, forSend = true)
                                ?: throw UserFacingSendRefusal(ChatSendCopy.MODE_NEEDS_KEY_EXCHANGE)
                        // Self-cache the control plaintext so our own mined ZMODE tx is still recognized
                        // (and suppressed as a bubble) on rescan even if the ratchet state is gone.
                        processor.encryptOutgoing(modeMemo).also { cacheOwnOutgoingPlaintext(convId, it, modeMemo) }
                    }
                // Round 8 D5 (sweep #14): inside the v4 envelope that names the conversation, like the timer control
                // (R2-5 c). A bare E2E1 memo names no conversation, so the contact's device could never pick the
                // ratchet to decrypt it with: the change was paid for and never synced.
                createChunkedMessageProposal(
                    destinationAddress = peerAddress,
                    senderAddress = userAddress,
                    message = enc,
                    isFirstMessage = false,
                    directSubmit = true,
                    skipNavigation = true,
                    conversationId = convId,
                    onSubmitStarting = { modeSubmitStarted = true },
                )
                // Submitted on-chain (reliable carrier) — no free-NOSTR retry needed.
                zchatPreferences.clearPendingModeSync(peerAddress)
            } catch (e: Exception) {
                // Not delivered, or (Round 8 D8) stored by the SDK and then rejected, so it may still be broadcast.
                // Arm the FREE retry either way (the receiver's since-guard drops a duplicate); we never auto-retry the
                // on-chain carrier (money-safety). A change that may have gone out is not reported as "not told".
                zchatPreferences.setPendingModeSync(peerAddress, newMode.name, since)
                _sendMessageState.value =
                    SendMessageState.Error(
                        if (memoFailureProvesNothingSent(e, modeSubmitStarted)) {
                            e.toZchatUserMessage(ChatSendCopy.MODE_SYNC_FAILED)
                        } else {
                            SubmitAttemptProof.MAY_HAVE_BEEN_SENT
                        },
                    )
            }
        }
    }

    /**
     * R2-2 (b) — the on-chain carrier rule of [changeConversationMode], read before anything is changed. T3b-1: the carrier
     * is an E2E ratchet memo, so with no key exchange finished (our private key and the contact's key) the change cannot
     * go on-chain at all and there is no price to ask about.
     */
    private fun modeChangeGoesOnChain(
        peerAddress: String,
        newMode: co.electriccoin.zcash.ui.screen.chat.model.ConversationMode,
    ): Boolean {
        val previousMode = zchatPreferences.getConversationMode(peerAddress)
        if (newMode == previousMode || _currentUserAddress.value == null) return false
        // T3-extra, rule (E): a change for one of our own addresses is never paid, so there is no price to ask about.
        if (zchatPreferences.isSelfAddress(peerAddress)) return false
        if (zchatPreferences.getPeerNostrPubkey(peerAddress) != null && NostrChatBridge.isOutboundReady()) return false
        if (zchatPreferences.getE2EPrivateKey(peerAddress) == null || zchatPreferences.getE2EPeerPublicKey(peerAddress) == null) {
            return false
        }
        return previousMode == co.electriccoin.zcash.ui.screen.chat.model.ConversationMode.VAULT &&
            newMode != co.electriccoin.zcash.ui.screen.chat.model.ConversationMode.OPEN
    }

    /**
     * T3b-1 — the on-chain transactions a switch of [peerAddress] to [newMode] makes: the mode change itself when it goes
     * on-chain ([modeChangeGoesOnChain]), our KEX and our ZBOOT, read the way [startNostrBootstrap] and
     * [sendNostrBootHandshake] decide them. A ZBOOT that waits for the contact's answer to our KEX is counted too.
     *
     * T3b fixup (G-T3b1-1): a ZBOOT that can only go after the contact answers our KEX (the switch sends it, or ours is
     * already out) is counted whatever the relays are now. They may be down, or acknowledge nothing, when the answer
     * arrives; that ZBOOT then goes on-chain against the allowance this question leaves, and is never paid unasked.
     */
    private data class ModeSwitchPlan(
        val modeChange: Boolean,
        val kex: Boolean,
        val zboot: Boolean,
    ) {
        val onChain: Int get() = listOf(modeChange, kex, zboot).count { it }
        val includesSetup: Boolean get() = kex || zboot
    }

    private suspend fun modeSwitchPlan(
        peerAddress: String,
        newMode: co.electriccoin.zcash.ui.screen.chat.model.ConversationMode,
    ): ModeSwitchPlan {
        val modeChange = modeChangeGoesOnChain(peerAddress, newMode)
        val none = ModeSwitchPlan(modeChange = modeChange, kex = false, zboot = false)
        // Only a switch to a relay mode runs the bootstrap; re-picking the chat's mode runs nothing (a chat open does).
        // ZC-1131: a switch to Open never pays our KEX or our ZBOOT ([startNostrBootstrap] skips the KEX for Open, the
        // ZBOOT goes over the relays only, [openNeverSpends]), so it counts neither and asks nothing.
        if (newMode == co.electriccoin.zcash.ui.screen.chat.model.ConversationMode.VAULT ||
            newMode == co.electriccoin.zcash.ui.screen.chat.model.ConversationMode.OPEN ||
            newMode == zchatPreferences.getConversationMode(peerAddress) ||
            zchatPreferences.isSelfAddress(peerAddress)
        ) {
            return none
        }
        val peerRelayKey = zchatPreferences.getPeerNostrPubkey(peerAddress)
        // The bootstrap's own early return: both directions of the relay exchange are done.
        if (peerRelayKey != null && zchatPreferences.getSentNostrBootPubkey(peerAddress) != null) return none
        val kex =
            !zchatPreferences.isE2EKeyExchangeComplete(peerAddress) &&
                !zchatPreferences.isOwnBootSent(peerAddress)
        val ourRelayIdentity = getOurNostrPubkey()?.first
        val zbootAfterAnswer =
            !zchatPreferences.isE2EKeyExchangeComplete(peerAddress) &&
                (kex || zchatPreferences.isOwnBootSent(peerAddress))
        val zboot =
            ourRelayIdentity != null &&
                zchatPreferences.getSentNostrBootPubkey(peerAddress) != ourRelayIdentity &&
                (zbootAfterAnswer || !(peerRelayKey != null && NostrChatBridge.isOutboundReady()))
        return ModeSwitchPlan(modeChange = modeChange, kex = kex, zboot = zboot)
    }

    /**
     * T3b-1 — the mode picker's Apply. Nothing is changed, sent or paid before the question: when the switch makes any
     * on-chain transaction ([modeSwitchPlan]: the mode change, our KEX, our ZBOOT, including the one sent after the
     * contact answers), one question counts them all with the total; Cancel pays nothing and leaves the chat as it was.
     * Pay and continue reads the plan again and asks again if it now makes more than it quoted; otherwise the mode is
     * changed ([changeConversationMode]) and the bootstrap runs with what the quote covered, paid on that answer. A
     * switch that makes nothing on-chain changes the mode at once (and delivers our relay identity free where it can).
     */
    fun switchConversationMode(
        peerAddress: String,
        newMode: co.electriccoin.zcash.ui.screen.chat.model.ConversationMode,
    ) {
        // T1b-1 §2: the chat is closed on every transport while a Keystone account is selected; the mode stays.
        if (chatClosedForSelectedAccount()) {
            refuseClosedChat("a mode change")
            return
        }
        if (blockedByKeyChange(peerAddress)) return
        val pick = modeSwitchPicks.merge(peerAddress, 1L, Long::plus) ?: 1L
        viewModelScope.launch { planModeSwitch(peerAddress, newMode, pick, quoted = null) }
    }

    private suspend fun planModeSwitch(
        peerAddress: String,
        newMode: co.electriccoin.zcash.ui.screen.chat.model.ConversationMode,
        pick: Long,
        quoted: Int?,
    ) {
        if (modeSwitchPicks[peerAddress] != pick) return // a later pick replaced this one
        // The selected account or peer key may have changed while the question was open.
        if (chatClosedForSelectedAccount()) {
            refuseClosedChat("a mode change")
            return
        }
        if (blockedByKeyChange(peerAddress)) return
        val plan = modeSwitchPlan(peerAddress, newMode)
        // ZC-777: the plan waited for the wallet. A pick made meanwhile replaced this one (a Shielded pick changes nothing
        // visible while the chat is still Shielded): stop, so a confirmed switch the user has replaced neither changes
        // and pins the mode nor pays its mode change and its ZBOOT. Nothing suspends between here and those writes.
        if (modeSwitchPicks[peerAddress] != pick) return
        // Planning reads the wallet asynchronously; refuse before quoting or starting the switch.
        if (chatClosedForSelectedAccount()) {
            refuseClosedChat("a mode change")
            return
        }
        if (blockedByKeyChange(peerAddress)) return
        // ZC-1107: a paid Tunnel switch with a contact whose newest relay rumor has no Ironwood tag (ZChat 2.12 or
        // older) would send our key exchange to a receiver that contact cannot see. Refuse before any question or
        // payment; this also runs again on Pay and continue, so a contact found old while the question is open is
        // refused too. No rumor on record is not a reason to refuse.
        if (newMode == co.electriccoin.zcash.ui.screen.chat.model.ConversationMode.TUNNEL &&
            plan.onChain > 0 &&
            isLegacyContact(peerAddress)
        ) {
            Log.w("ZCHAT_MODE", "ZC-1107: Tunnel switch refused — contact on 2.12 or older; nothing paid, mode unchanged")
            _sendMessageState.value = SendMessageState.Error(ChatSendCopy.MODE_TUNNEL_CONTACT_NEEDS_UPDATE)
            return
        }
        if (plan.onChain > 0 && (quoted == null || plan.onChain > quoted)) {
            if (quoted != null) Log.w("ZCHAT_MODE", "T3b-1: the switch now makes more than it quoted — asking again, nothing sent")
            val confirmation =
                paidActionConfirmation(PaidAction.MODE_CHANGE, plan.onChain).copy(includesChatSetup = plan.includesSetup)
            // ZC-1835: the picker's one-transaction switch applies the margin rule too; the mode stays as it is.
            if (plan.onChain == 1 && refusedByTheSpendableMargin(confirmation.totalCost)) return
            askBeforePaying(confirmation) {
                viewModelScope.launch { planModeSwitch(peerAddress, newMode, pick, quoted = plan.onChain) }
            }
            return
        }
        val previousMode = zchatPreferences.getConversationMode(peerAddress)
        changeConversationMode(peerAddress, newMode, costConfirmed = plan.modeChange)
        // ZC-1131: an Open chat never pays a ZBOOT, so a ZBOOT allowance an older confirmed question left is withdrawn
        // here; a later switch to Shielded or Tunnel asks on its own quote. A withdrawal only lowers what can be spent.
        if (newMode == co.electriccoin.zcash.ui.screen.chat.model.ConversationMode.OPEN) withdrawZbootQuote(peerAddress)
        if (newMode != co.electriccoin.zcash.ui.screen.chat.model.ConversationMode.VAULT && newMode != previousMode) {
            startNostrBootstrap(
                peerAddress,
                force = false,
                switch =
                    SwitchBootstrap(
                        mode = newMode,
                        payKex = plan.kex,
                        zbootOnChain = plan.zboot,
                        quoteStands = { modeSwitchPicks[peerAddress] == pick },
                    ),
            )
        }
    }

    /**
     * Adopt a peer's conversation-mode change (ZMODE — authenticated by the CALLER before this runs, #187: NIP-17 seal
     * on the NOSTR path, E2E-ratchet AEAD + known-peer resolution on-chain; a bare plaintext ZMODE is never routed
     * here). Replays and rescans are dropped by the monotonic since-guard; a forged far-future since is clamped to
     * now+5min so it can't permanently outrank later changes.
     *
     * ZC-1478 (owner decision W-122; reverses money guard #187 within [ModeAdoption]'s bounds): the change applies on
     * both phones, any direction, also to Shielded, with no Accept/Keep prompt, also in a chat whose mode the user picked
     * by hand. The newer of two crossed switches wins on both phones (a contact's switch older than our own last one is
     * answered by sending ours again, free over the relays); Shielded only from a contact recorded as ZChat 2.13 (a
     * 2.12.4 phone cannot read Shielded messages). The adopted mode is not pinned. M1: adopting a mode that can pay marks
     * the chat ([ZchatPreferences.isModeMovedToPaidByPeer]): nothing automatic pays for its setup, and the first on-chain
     * send asks with the price ([sendMessage]). Adopting a mode sends and pays nothing.
     */
    private fun handleModeControl(peerAddress: String, memo: String) {
        val parsed = ZMSGProtocol.parseModeChange(memo) ?: return
        val since = ZMSGProtocol.clampModeChangeSince(parsed.sinceMillis, System.currentTimeMillis())
        if (!zchatPreferences.advancePeerModeChangeSince(peerAddress, since)) return
        val newMode = parsed.mode
        val modeBeforeAdopt = zchatPreferences.getConversationMode(peerAddress)
        val ownSince = zchatPreferences.getModeSwitchRecord(peerAddress)?.ownSinceMillis ?: 0L
        val decision =
            co.electriccoin.zcash.ui.screen.chat.model.ModeAdoption.decide(
                currentMode = modeBeforeAdopt,
                newMode = newMode,
                ownSince = ownSince,
                peerSince = since,
                peerIronwoodCap = zchatPreferences.getPeerIronwoodCap(peerAddress)?.capIronwood,
                holdsPeerRelayKey = zchatPreferences.getPeerNostrPubkey(peerAddress) != null,
                keyChanged = zchatPreferences.isE2EKeyChanged(peerAddress),
            )
        // W-122: no Accept/Keep prompt any more; one stored by an earlier build is stale once the contact switched again.
        zchatPreferences.clearPendingModeSwitch(peerAddress)
        val name = peerLabel(peerAddress)
        val noteId = modeChangeNoteId(peerAddress, since)
        when (decision) {
            is co.electriccoin.zcash.ui.screen.chat.model.ModeAdoption.Decision.Adopt -> {
                // M1: the mark goes down BEFORE the mode, so a chat in a paid mode is never without it. No paid
                // adoption happens without it: Shielded (paid per message), ZC-1507 a Tunnel whose only paid leg is
                // our ZBOOT, and ZC-1516 a Tunnel still exchanging keys (its ZBOOT/KEX would pay under the standing
                // consent) are all refused when the mark does not read back.
                val exchangeComplete = zchatPreferences.isE2EKeyExchangeComplete(peerAddress)
                val movesToPaid =
                    co.electriccoin.zcash.ui.screen.chat.model.ModeAdoption.movesToPaid(
                        newMode,
                        exchangeComplete,
                        ourZbootSent = zchatPreferences.getSentNostrBootPubkey(peerAddress) != null,
                    )
                zchatPreferences.setModeMovedToPaidByPeer(peerAddress, movesToPaid)
                if (movesToPaid && !modeMovedToPaidByPeer(peerAddress)) {
                    Log.w("ZCHAT_MODE", "ZC-1478: the paid-mode mark could not be written — the contact's switch is not adopted")
                    emitSystemNote(
                        peerAddress,
                        noteId,
                        noteCopy.get(R.string.chat_note_peer_switched_unchanged, name, modeLabel(newMode)),
                    )
                    loadConversations()
                    return
                }
                // NOT pinned explicit — only the USER pins.
                zchatPreferences.setConversationMode(peerAddress, newMode)
                Log.d("ZCHAT_MODE", "Adopted peer mode ${newMode.name} for ${peerAddress.take(16)}…")
                // SR-B1: adopting a free mode moved the chat out of Shielded — the contact gets our avatar now.
                if (modeBeforeAdopt == ConversationMode.VAULT) pushSelfAvatarTo(peerAddress)
                emitSystemNote(
                    peerAddress,
                    noteId,
                    if (newMode == ConversationMode.VAULT) {
                        // ZC-1641 (Q2-48): the note names the least one on-chain message costs.
                        noteCopy.get(
                            R.string.chat_note_peer_switched_shielded,
                            name,
                            zecDisplay(onChainSendMinimumCost(), java.util.Locale.getDefault()),
                        )
                    } else {
                        noteCopy.get(R.string.chat_note_peer_switched_followed, name, modeLabel(newMode))
                    },
                )
            }
            co.electriccoin.zcash.ui.screen.chat.model.ModeAdoption.Decision.SendOursAgain -> {
                // M3: our switch is the newer one. Deliver it again (free, relays only) so the contact's phone ends in
                // our mode too. ZC-1505: the copy carries a since strictly newer than both switches and is recorded as our
                // own; with the same since, the contact's since-guard would drop it (it may already hold that since from
                // adopting our switch) and the phones would stay split under a clock offset.
                Log.d("ZCHAT_MODE", "ZC-1478: the contact's crossed switch is older than ours — sending ours again")
                val resendSince = maxOf(ownSince, since) + 1
                zchatPreferences.setOwnModeChangeSince(peerAddress, resendSince)
                zchatPreferences.setPendingModeSync(peerAddress, modeBeforeAdopt.name, resendSince)
                retryPendingModeSyncs()
            }
            co.electriccoin.zcash.ui.screen.chat.model.ModeAdoption.Decision.KeepNeeds213 ->
                emitSystemNote(
                    peerAddress,
                    noteId,
                    noteCopy.get(R.string.chat_note_peer_shielded_needs_2_13, name, modeLabel(modeBeforeAdopt)),
                )
            co.electriccoin.zcash.ui.screen.chat.model.ModeAdoption.Decision.KeepUnchanged ->
                emitSystemNote(
                    peerAddress,
                    noteId,
                    noteCopy.get(R.string.chat_note_peer_switched_unchanged, name, modeLabel(newMode)),
                )
            co.electriccoin.zcash.ui.screen.chat.model.ModeAdoption.Decision.AlreadyInMode -> Unit
        }
        loadConversations()
    }

    /** ZC-1478 (M1) — whether the contact moved [peerAddress]'s chat into a paid mode the user was asked no price in yet. */
    private fun modeMovedToPaidByPeer(peerAddress: String): Boolean =
        zchatPreferences.getModeSwitchRecord(peerAddress)?.movedToPaidByPeer == true

    /**
     * Send MY self-avatar (or, when it was removed, the removal) to every contact that is owed it — see
     * [deliverSelfAvatar]. Called by the photo picker after a set; the launch tick
     * ([observeSelfAvatarDelivery]) makes the same call, so the two together send it once.
     *
     * MONEY-SAFETY INVARIANTS (mirrors the ZMODE/rotation broadcasts):
     *  - avatar bytes ride [NostrChatBridge.publish] (free NIP-17 DM) ONLY — there is NO on-chain / VAULT /
     *    Zcash-transaction path here, so this can never spend ZEC;
     *  - a peer is a target ONLY when [ZchatPreferences.getPeerNostrPubkey] is non-null (we already hold their
     *    encrypted-DM key). Unknown-pubkey peers are silently skipped — no send, no handshake, no spend;
     *  - the DM is an encrypted, per-recipient gift-wrap to a KNOWN contact — never a public relay feed.
     *
     * SR-B1 PRIVACY: a contact whose chat is Shielded (VAULT) is never sent it over the relays; it gets it when its
     * chat leaves Shielded.
     */
    fun broadcastSelfAvatarToContacts() {
        deliverSelfAvatarInBackground(onlyPeer = null)
    }

    /**
     * Send the self-avatar REMOVAL tombstone to the contacts owed it, so their saved copy of our avatar is cleared.
     * Same path and guarantees as [broadcastSelfAvatarToContacts]: [deliverSelfAvatar] sends whichever of the set or the
     * removal is current, so a photo set again after the removal sends the photo instead.
     */
    fun broadcastSelfAvatarRemoveToContacts() {
        deliverSelfAvatarInBackground(onlyPeer = null)
    }

    /**
     * SR-B1 — a hook where a chat leaves Shielded ([changeConversationMode], the Tunnel adopt in [routeIncomingBoot],
     * the adopt in [handleModeControl]): sends [peerAddress] the current avatar or removal now, if it is owed. This only
     * makes delivery faster; a mode writer with no hook (M1's relay-only Open default, accepting a message request, a
     * new chat's mode) is caught by the next launch tick.
     */
    private fun pushSelfAvatarTo(peerAddress: String) {
        deliverSelfAvatarInBackground(onlyPeer = peerAddress)
    }

    private fun deliverSelfAvatarInBackground(onlyPeer: String?) {
        viewModelScope.launch(kotlinx.coroutines.Dispatchers.IO) {
            try {
                // NonCancellable: the user may navigate away the instant they pick a photo; finish the fan-out.
                kotlinx.coroutines.withContext(kotlinx.coroutines.NonCancellable) { deliverSelfAvatar(onlyPeer) }
            } catch (e: kotlinx.coroutines.CancellationException) {
                throw e
            } catch (e: Exception) {
                // Best effort: a contact not delivered stays owed and the next launch tick sends it again.
                Log.w("ZCHAT_PROF", "avatar delivery failed: ${e.javaClass.simpleName}")
            }
        }
    }

    /** SR-B1 — the current self-avatar version: the set's, else the removal's, else null (never set nor removed). */
    private fun currentSelfAvatarVersion(): Long? = avatarStore.selfAvatarUpdatedAt() ?: avatarStore.selfAvatarRemovedAt()

    /**
     * SR-B1 — whether [peerAddress] is owed [version] now: we hold its relay key, its chat is not Shielded (read now,
     * not when the avatar changed), and no relay took [version] for it yet.
     *
     * T7BH-N1: and the contact's new key does not wait for the user. A held contact is skipped and stays owed (its
     * delivered version is not set), so the next pass after the decision sends it.
     */
    private fun selfAvatarOwedTo(
        peerAddress: String,
        version: Long,
    ): Boolean =
        !zchatPreferences.isE2EKeyChanged(peerAddress) &&
            zchatPreferences.getPeerNostrPubkey(peerAddress) != null &&
            zchatPreferences.getConversationMode(peerAddress) != ConversationMode.VAULT &&
            avatarStore.getDeliveredSelfVersion(peerAddress) != version

    /**
     * SR-B1 upgrade (once): the contacts that are not Shielded and hold a relay key are taken to have the version the
     * old global marker records, so the first launch after the upgrade does not re-send it to all of them.
     */
    private fun seedDeliveredSelfAvatarVersions() {
        avatarStore.seedDeliveredSelfVersionsOnce(
            zchatPreferences.getAllConversationPeerAddresses().filter { peer ->
                zchatPreferences.getPeerNostrPubkey(peer) != null &&
                    zchatPreferences.getConversationMode(peer) != ConversationMode.VAULT
            },
        )
    }

    /**
     * SR-B1 — sends the current self-avatar (ZPROF chunks) or, when it was removed, the removal tombstone to every
     * contact owed it ([selfAvatarOwedTo]), or only to [onlyPeer]. A contact counts as delivered — its delivered
     * version is set — only when a relay took every memo; otherwise it stays owed and the next broadcast or launch tick
     * sends it again. Serialised process-wide ([selfAvatarDeliveryLock]): the picker, the launch tick and a hook (in
     * the list and the detail ChatViewModel alike) never send the same version to a contact twice at once. Returns the
     * number of contacts a relay took it for.
     */
    private suspend fun deliverSelfAvatar(onlyPeer: String?): Int =
        selfAvatarDeliveryLock.withLock {
            seedDeliveredSelfAvatarVersions()
            val setVersion = avatarStore.selfAvatarUpdatedAt()
            val version: Long
            val memos: List<String>
            if (setVersion != null) {
                val jpeg = avatarStore.getSelfAvatar()
                if (jpeg == null) {
                    Log.d("ZCHAT_PROF", "avatar delivery: no self avatar set → nothing to send")
                    return@withLock 0
                }
                val chunks = ZPROFMessage.build(jpeg)
                if (chunks == null) {
                    Log.w("ZCHAT_PROF", "self-avatar not broadcastable (empty/oversized ${jpeg.size}B)")
                    return@withLock 0
                }
                memos = chunks
                version = setVersion
            } else {
                version = avatarStore.selfAvatarRemovedAt() ?: return@withLock 0 // never set, never removed
                memos = listOf(ZPROFMessage.buildRemove(version))
            }
            if (!NostrChatBridge.isOutboundReady()) {
                Log.d("ZCHAT_PROF", "avatar delivery skipped — NOSTR outbound not ready")
                return@withLock 0
            }
            val peers = onlyPeer?.let { listOf(it) } ?: zchatPreferences.getAllConversationPeerAddresses().toList()
            var owed = 0
            var sentTo = 0
            for (peer in peers) {
                // Read per contact, right before its send: a chat switched to Shielded meanwhile is skipped.
                if (!selfAvatarOwedTo(peer, version)) continue
                val peerPub = zchatPreferences.getPeerNostrPubkey(peer) ?: continue
                owed++
                var ok = true
                for (memo in memos) {
                    val acks = runCatching { NostrChatBridge.publish(memo, peerPub) }.getOrNull()?.acks ?: 0
                    if (acks == 0) ok = false
                }
                if (ok) {
                    avatarStore.setDeliveredSelfVersion(peer, version)
                    sentTo++
                }
            }
            Log.d(
                "ZCHAT_PROF",
                "avatar delivery (${if (setVersion != null) "${memos.size} chunk(s)" else "removal"}): ${peers.size} peers, " +
                    "$owed owed (not Shielded, key known), delivered to $sentTo",
            )
            // The old global marker is kept up to date (it seeds the per-contact versions once); it no longer decides who
            // is sent the avatar.
            if (sentTo > 0) avatarStore.setLastBroadcastSelfAt(version)
            sentTo
        }

    /**
     * #avatar-process-death + SR-B1 — the launch tick. The picker-triggered send can be lost if the OS kills the app
     * while the image picker is open (Honor/Huawei). Driven by the avatar version flow: it fires on the CURRENT value
     * (launch) and on any change, and sends only when some contact is owed the current version
     * ([selfAvatarOwedTo]): a lost send, a relay outage, or a chat that left Shielded through a mode writer no hook
     * covers. Waits for NOSTR outbound to be ready; the receiver is idempotent (last-writer-wins).
     */
    private fun observeSelfAvatarDelivery() {
        viewModelScope.launch {
            avatarStore.version.collectLatest { ver ->
                val owed =
                    kotlinx.coroutines.withContext(kotlinx.coroutines.Dispatchers.IO) {
                        seedDeliveredSelfAvatarVersions()
                        val v = currentSelfAvatarVersion() ?: return@withContext 0
                        zchatPreferences.getAllConversationPeerAddresses().count { selfAvatarOwedTo(it, v) }
                    }
                Log.d("ZCHAT_PROF", "avatar-version tick=$ver owed=$owed")
                if (owed == 0) return@collectLatest
                repeat(20) {
                    if (NostrChatBridge.isOutboundReady()) {
                        Log.d("ZCHAT_PROF", "outbound ready → delivering self avatar to $owed owed contact(s)")
                        deliverSelfAvatarInBackground(onlyPeer = null)
                        return@collectLatest
                    }
                    kotlinx.coroutines.delay(3000)
                }
                Log.d("ZCHAT_PROF", "gave up waiting for NOSTR outbound to (re)broadcast self avatar")
            }
        }
    }

    /**
     * Handle an inbound ZPROF avatar chunk from an authenticated peer: reassemble, then save it as this
     * peer's contact avatar (last-writer-wins; a LOCAL override still wins on render). Malformed / undecodable
     * / oversized transfers are dropped inside the reassembler (bounded, self-evicting). NOSTR-only path.
     * A REMOVE tombstone clears the peer's saved avatar instead.
     */
    private fun handleProfileAvatar(peerAddress: String, memo: String) {
        co.electriccoin.zcash.ui.screen.chat.model.ZPROFMessage.parseRemove(memo)?.let {
            viewModelScope.launch(kotlinx.coroutines.Dispatchers.IO) {
                runCatching { avatarStore.removeContactAvatar(peerAddress) } // idempotent, best-effort
                Log.d("ZCHAT_PROF", "removed peer avatar (remove tombstone) from ${peerAddress.take(16)}…")
            }
            return
        }
        val chunk = co.electriccoin.zcash.ui.screen.chat.model.ZPROFMessage.parseChunk(memo) ?: return
        val jpeg = zprofReassembler.accept(peerAddress, chunk) ?: return // incomplete or failed validation
        viewModelScope.launch(kotlinx.coroutines.Dispatchers.IO) {
            val saved = runCatching { avatarStore.setContactAvatar(peerAddress, jpeg) }.getOrDefault(false)
            if (saved) {
                Log.d("ZCHAT_PROF", "saved avatar (${jpeg.size}B) from ${peerAddress.take(16)}…")
            } else {
                Log.w("ZCHAT_PROF", "discarded undecodable avatar from ${peerAddress.take(16)}…")
            }
        }
    }

    /**
     * User ACCEPTED a peer's request to switch this chat to a paid mode (from the accept/keep prompt).
     * Sets + PINS the mode locally WITHOUT broadcasting a ZMODE back: the peer initiated the switch and
     * is already on it, so echoing one back would ping-pong prompts and (for Vault) risk a needless spend.
     */
    fun acceptPendingModeSwitch(pending: co.electriccoin.zcash.ui.screen.chat.model.PendingModeSwitch) {
        zchatPreferences.clearPendingModeSwitch(pending.peerAddress)
        viewModelScope.launch {
            zchatPreferences.setConversationMode(pending.peerAddress, pending.newMode)
            zchatPreferences.setConversationModeExplicit(pending.peerAddress)
            emitSystemNote(
                pending.peerAddress,
                modeChangeNoteId(pending.peerAddress, System.currentTimeMillis()),
                noteCopy.get(
                    R.string.chat_note_you_switched_to_match,
                    modeLabel(pending.newMode),
                    pending.peerName,
                ),
            )
            loadConversations()
        }
    }

    /**
     * User DECLINED the peer's switch request — keep our current mode. Each side simply sends in its
     * own mode; the divergence is now an explicit, recorded choice rather than a silent surprise.
     */
    fun dismissPendingModeSwitch(pending: co.electriccoin.zcash.ui.screen.chat.model.PendingModeSwitch) {
        zchatPreferences.clearPendingModeSwitch(pending.peerAddress)
        emitSystemNote(
            pending.peerAddress,
            modeChangeNoteId(pending.peerAddress, System.currentTimeMillis()),
            noteCopy.get(R.string.chat_note_you_kept_mode, modeLabel(pending.currentMode)),
        )
    }

    /**
     * #37 delivery fix — re-publish OUTBOUND mode-change controls (ZMODE) that never got a relay ack,
     * so a switch to Shielded actually reaches the peer's accept/keep prompt instead of dying on the
     * old one-shot publish. Fired from the auto-refresh tick (~60s) in every ChatViewModel instance.
     *
     * MONEY-SAFETY: this loop is FREE-NOSTR ONLY — it never touches the on-chain path, so no retry can
     * ever spend ZEC. Idempotent end to end: the receiver's monotonic since-guard
     * (advancePeerModeChangeSince) drops replays, the process-wide [modeSyncInFlight] claim stops the
     * coexisting list+detail instances double-publishing concurrently, and the pending entry is only
     * cleared on a confirmed ack (so it keeps retrying until it lands — e.g. once the peer's NOSTR key
     * arrives for a chat that had no channel when the user flipped the mode).
     */
    private fun retryPendingModeSyncs() {
        val pending = zchatPreferences.getPendingModeSyncs()
        if (pending.isEmpty()) return
        if (!co.electriccoin.zcash.ui.nostr.NostrChatBridge.isOutboundReady()) return
        // T1b-1 §2: the mode control carries our address; held (still pending) while a Keystone account is selected,
        // and sent with the selected account's identity.
        if (chatClosedForSelectedAccount()) return
        val userAddress = chatIdentityForSelectedAccount() ?: return
        viewModelScope.launch {
            for ((peer, sync) in pending) {
                if (!modeSyncInFlight.add(peer)) continue // another instance is already on it
                try {
                    val mode = runCatching {
                        co.electriccoin.zcash.ui.screen.chat.model.ConversationMode.valueOf(sync.modeName)
                    }.getOrNull()
                    if (mode == null) { // unparseable legacy row — drop, never loop on it
                        zchatPreferences.clearPendingModeSync(peer)
                        continue
                    }
                    // A newer explicit choice supersedes the stale pending control — stop retrying it.
                    if (zchatPreferences.getConversationMode(peer) != mode) {
                        zchatPreferences.clearPendingModeSync(peer)
                        continue
                    }
                    if (zchatPreferences.isE2EKeyChanged(peer)) continue
                    val peerPub = zchatPreferences.getPeerNostrPubkey(peer) ?: continue // no channel yet — keep pending
                    val memo = ZMSGProtocol.createModeChange(mode, sync.sinceMillis, userAddress)
                    val acks = runCatching {
                        co.electriccoin.zcash.ui.nostr.NostrChatBridge.publish(memo, peerPub)
                    }.getOrNull()?.acks ?: 0
                    if (acks > 0) {
                        zchatPreferences.clearPendingModeSync(peer)
                        Log.d("ZCHAT_MODE", "Delivered pending mode-change (${mode.name}) to ${peer.take(16)}… on retry")
                    }
                } finally {
                    modeSyncInFlight.remove(peer)
                }
            }
        }
    }

    /**
     * #233 — RESPONDER-side handshake retry. The KEXACK (our reply to a peer's first-contact KEX) is the
     * ONE handshake leg with no retry: handleKEXMessage sends it exactly once on KEX-receipt, and under the
     * single-note rule it can fail (the spendable note is busy with our reply message) and is then NEVER
     * re-attempted — the initiator doesn't re-send its KEX, so nothing re-triggers our ack. With the KEXACK
     * lost, the initiator never learns our E2E key, so its sequenced ZBOOT (sendNostrBootHandshake, fired on
     * KEXACK-receipt) self-gates forever → no ZBOOT reaches us → routeIncomingBoot never upgrades us out of
     * VAULT → a cold TUNNEL first-contact DEADLOCKS at "Waiting for secure connection" (observed live on a
     * fresh 2-device pair). Re-attempting the KEXACK on every chat-open closes that gap: once it lands, the
     * initiator's ZBOOT (already retried on its own open) arrives, routeIncomingBoot upgrades us to TUNNEL +
     * replies with our ZBOOT, and the handshake completes both ways.
     *
     * SAFE + idempotent: the KEXACK only carries OUR E2E identity (no NOSTR pubkey / no mode change), so
     * re-sending it can never wrongly NOSTR-bootstrap a VAULT chat, and re-acking the SAME key is a no-op on
     * the receiver (key-change TOFU only fires on a DIFFERENT key). Gated to the RESPONDER (isOwnBootSent ==
     * false: we did NOT send the first KEX) so the initiator never emits a spurious ack, skipped once the
     * Tunnel handshake has completed (peer NOSTR pubkey known) and once we've acked this exact key this
     * session (kexAckedKeys), and serialized via kexAckInFlight so concurrent opens don't double-spend.
     * The claim, the durable marker and the stamp-before-submit all live in [payKexAckOnce], shared with
     * the received-KEX branch of handleKEXMessage (HS-1/HS-2/HS-3).
     */
    fun retryKexAckIfResponder(peerAddress: String) {
        viewModelScope.launch {
            if (!askHeldKexAnswerPrice(peerAddress) && !askHeldOwnSetupPrice(peerAddress)) retryKexAckOnce(peerAddress)
        }
    }

    /**
     * What a key-exchange answer brings to [sendAutomaticHandshakeMemoOutcome]: its [price] (the use case refuses a build
     * not at it), [onLedgerRefusal] (F8: the attempt sent nothing because the send-attempt ledger could not be read or
     * written), [onAttemptStarting] and [onAttemptFailed] (ZC-1230: the failure of the attempt that came last, none when
     * a gate stopped it).
     */
    private class KexAnswerAttempt(
        val price: KexAnswerPrice,
        val onLedgerRefusal: () -> Unit = {},
        val onAttemptStarting: () -> Unit = {},
        val onAttemptFailed: (Exception) -> Unit,
        // ZC-1338: an Accept tap says so at each wait for a block.
        val onBlockWait: (() -> Unit)? = null,
    )

    /**
     * ZC-1235 — what a question brings to our own KEX or ZBOOT: the [price] it confirmed, [stands] (re-read before every
     * attempt, null keeps the sender's rules) and [onAbove] (a build above [price]; null holds it for the next chat open).
     */
    private class OwnSetupPayment(
        val price: KexAnswerPrice,
        val stands: (() -> Boolean)? = null,
        val onAbove: ((Zatoshi) -> Unit)? = null,
        // ZC-1272: the KEX leg of the question this pays on, used up before anything is paid.
        val coveredKexLeg: Long? = null,
    )

    /** ZC-1235 — [ourKey] is the key of ours the setup carries or is signed with; [actual] what its build would cost. */
    private class HeldOwnSetupPrice(
        val zboot: Boolean,
        val ourKey: String,
        val actual: Zatoshi,
    )

    /** ZC-1233 round 3 — the request a key-exchange answer was built for changed before the submit. Nothing was stored or sent. */
    private class KexAnswerPreSubmitRefused : IllegalStateException("The request of this key exchange answer changed before the submit")

    /** ZC-1233: why [payKexAckOnce] built an answer and did not pay it. Nothing was stored or sent. */
    private sealed interface KexAnswerRefusal {
        /** The wallet cannot pay the build; [need] is the SDK's figure, null when it gave none. */
        data class TooLittle(
            val need: Zatoshi?,
            // ZC-1338: the funds are still confirming: a later block may pay it.
            val stillConfirming: Boolean = false,
        ) : KexAnswerRefusal

        /** The build is not at its price; [actual] is what it would cost. */
        data class AboveItsPrice(
            val actual: Zatoshi,
        ) : KexAnswerRefusal
    }

    /** ZC-1233: the price an answer nobody was asked about may be paid at: the one handshake every question and text quotes. */
    private fun handshakeAnswerPrice() = KexAnswerPrice(onChainSendMinimumCost())

    private fun kexAnswerRefusalOf(failure: Exception): KexAnswerRefusal? {
        val actual = CreateChunkedMessageProposalUseCase.kexAnswerActualPrice(failure)
        return when {
            actual != null -> KexAnswerRefusal.AboveItsPrice(actual)
            // Round 2: a wait for blocks that reaches here is out of waits (the last attempt failed, nothing was sent).
            CreateChunkedMessageProposalUseCase.isInsufficientFundsError(failure) || isTransientWait(failure) ->
                KexAnswerRefusal.TooLittle(
                    CreateChunkedMessageProposalUseCase.sdkShortfallNeed(failure),
                    stillConfirming = isTransientWait(failure),
                )
            else -> null
        }
    }

    /**
     * ZC-1230, ZC-1233 — what a tap that was refused shows: too little says the exact need; above its price asks the true
     * price, with [payAt] as Pay (that figure exactly) and nothing on Cancel.
     */
    private fun tellKexAnswerRefusal(
        refusal: KexAnswerRefusal,
        payAt: (KexAnswerPrice) -> Unit,
    ) {
        when (refusal) {
            is KexAnswerRefusal.TooLittle ->
                _sendMessageState.value =
                    // ZC-1343: never below what one answer costs: the SDK's figure can be for one small note.
                    SendMessageState.Error(
                        refusal.need?.let { need ->
                            ChatSendCopy.kexAnswerShortfall(Zatoshi(maxOf(need.value, onChainSendMinimumCost().value)))
                        } ?: ChatSendCopy.INSUFFICIENT_BALANCE_SHORT,
                    )
            is KexAnswerRefusal.AboveItsPrice -> askKexAnswerTruePrice(refusal.actual, PaidAction.KEX_ANSWER_TRUE_PRICE, payAt)
        }
    }

    private fun askKexAnswerTruePrice(
        actual: Zatoshi,
        action: PaidAction,
        payAt: (KexAnswerPrice) -> Unit,
    ) {
        val outputs = CreateChunkedMessageProposalUseCase.totalCost(1, CreateChunkedMessageProposalUseCase.DEFAULT_AMOUNT_PER_OUTPUT)
        askBeforePaying(
            PaidActionConfirmation(
                action = action,
                onChainMessages = 1,
                totalCost = actual,
                exact = true,
                networkFee = Zatoshi((actual.value - outputs.value).coerceAtLeast(0L)),
            ),
        ) { payAt(KexAnswerPrice(actual, exact = true)) }
    }

    /**
     * ZC-1233 (owner's decision, 30 Oct) — an automatic path (a chat open, an inbound key exchange) built an answer above
     * the handshake price: nothing is paid. The request goes on hold, so no later path builds it by itself, and the true
     * price is kept for the next chat open ([askHeldKexAnswerPrice]). The hold's Accept stays, so it is never stranded: after
     * a restart, which forgets the price, that Accept builds again and asks it.
     */
    private fun holdKexAnswerAtItsTruePrice(
        peerAddress: String,
        peerKey: String,
        actual: Zatoshi,
    ) {
        acceptedChatRequests.remove(peerAddress, peerKey)
        val held = zchatPreferences.setInboundKexAwaitingAccept(peerAddress, peerKey)
        synchronized(heldKexAnswerPrices) {
            heldKexAnswerPrices.getOrPut(zchatPreferences) { HashMap() }[peerAddress] = peerKey to actual
        }
        Log.w("KEX", "An automatic KEXACK above its price was not paid (hold saved: $held)")
    }

    /**
     * ZC-1233 — on a chat open, the true price an automatic path held ([holdKexAnswerAtItsTruePrice]) is asked once. Waits
     * for another open while anything else is on screen, while the chat is Open (its Tunnel offer asks) or while a new key
     * waits for the user; a price of another key, or of a request no longer held, is dropped. @return whether it asked.
     */
    private fun askHeldKexAnswerPrice(peerAddress: String): Boolean {
        val prices = synchronized(heldKexAnswerPrices) { heldKexAnswerPrices[zchatPreferences] } ?: return false
        val (key, actual) = synchronized(heldKexAnswerPrices) { prices[peerAddress] } ?: return false
        if (_sendMessageState.value != SendMessageState.Idle ||
            openNeverSpends(peerAddress) ||
            zchatPreferences.isE2EKeyChanged(peerAddress)
        ) {
            return false
        }
        synchronized(heldKexAnswerPrices) { prices.remove(peerAddress) }
        if (zchatPreferences.getE2EPeerPublicKey(peerAddress) != key ||
            zchatPreferences.getInboundKexAwaitingAccept(peerAddress) != key
        ) {
            return false
        }
        askKexAnswerTruePrice(actual, PaidAction.KEX_ANSWER_TRUE_PRICE) { price ->
            acceptInboundKexRequest(peerAddress, ConfirmedKexAnswer(price, key))
        }
        return true
    }

    /**
     * ZC-1235 — our own KEX or ZBOOT, as an answer's price guard sees it: at [payment]'s price, by default the one handshake
     * every text quotes. A build above it pays nothing.
     */
    private fun ownSetupAttempt(
        peerAddress: String,
        zboot: Boolean,
        payment: OwnSetupPayment?,
    ) = KexAnswerAttempt(
        // ZC-1272: a ZBOOT the one question covered is held to its leg while its allowance stands.
        price =
            payment?.price
                ?: peerAddress
                    .takeIf { zboot && zbootQuoteStands(it) }
                    ?.let { quotedChatSetup(it)?.zboot }
                    ?.let { KexAnswerPrice(Zatoshi(it)) }
                ?: handshakeAnswerPrice(),
        onAttemptFailed = { failure ->
            CreateChunkedMessageProposalUseCase.kexAnswerActualPrice(failure)?.let { actual ->
                val onAbove = payment?.onAbove
                if (onAbove != null) onAbove(actual) else holdOwnSetupAtItsTruePrice(peerAddress, zboot, actual)
            }
        },
    )

    /**
     * ZC-1235 — the true price of our own KEX or ZBOOT that was not paid, kept for the next chat open
     * ([askHeldOwnSetupPrice]). Its re-arm stands, so a later build at the usual price pays by itself and a restart, which
     * forgets the price, builds it again.
     */
    private fun holdOwnSetupAtItsTruePrice(
        peerAddress: String,
        zboot: Boolean,
        actual: Zatoshi,
    ) {
        val ourKey = zchatPreferences.getE2EOurPublicKey(peerAddress) ?: return
        synchronized(heldOwnSetupPrices) {
            heldOwnSetupPrices.getOrPut(zchatPreferences) { HashMap() }[peerAddress] = HeldOwnSetupPrice(zboot, ourKey, actual)
        }
        Log.w("KEX", "Our automatic ${if (zboot) "ZBOOT" else "KEX"} above its price was not paid")
    }

    /**
     * ZC-1235 — the KEX carrying [sentKey] is settled, so a true price kept for it asks nothing. A first message's owed KEX
     * never sets the bootstrap marker, so [askHeldOwnSetupPrice] could not tell that it was paid.
     */
    private fun dropHeldOwnKexPrice(
        peerAddress: String,
        sentKey: String,
    ) {
        synchronized(heldOwnSetupPrices) {
            val prices = heldOwnSetupPrices[zchatPreferences] ?: return
            val held = prices[peerAddress] ?: return
            if (!held.zboot && held.ourKey == sentKey) prices.remove(peerAddress)
        }
    }

    /**
     * ZC-1235 — on a chat open, the true price [holdOwnSetupAtItsTruePrice] kept is asked once, under the rules of
     * [askHeldKexAnswerPrice]; a price of a setup paid or replaced since is dropped. @return whether it asked.
     */
    private fun askHeldOwnSetupPrice(peerAddress: String): Boolean {
        val prices = synchronized(heldOwnSetupPrices) { heldOwnSetupPrices[zchatPreferences] } ?: return false
        val held = synchronized(heldOwnSetupPrices) { prices[peerAddress] } ?: return false
        if (_sendMessageState.value != SendMessageState.Idle ||
            openNeverSpends(peerAddress) ||
            zchatPreferences.isE2EKeyChanged(peerAddress)
        ) {
            return false
        }
        synchronized(heldOwnSetupPrices) { prices.remove(peerAddress) }
        val due =
            if (held.zboot) {
                zchatPreferences.getSentNostrBootPubkey(peerAddress) == null || zchatPreferences.isZbootOwed(peerAddress)
            } else {
                zchatPreferences.isKexOwed(peerAddress) ||
                    (!zchatPreferences.isE2EKeyExchangeComplete(peerAddress) && !zchatPreferences.isOwnBootSent(peerAddress))
            }
        if (!due || zchatPreferences.getE2EOurPublicKey(peerAddress) != held.ourKey) return false
        askKexAnswerTruePrice(held.actual, PaidAction.OWN_SETUP_TRUE_PRICE) { price -> payHeldOwnSetup(peerAddress, held, price) }
        return true
    }

    /** ZC-1235 — Pay on [askHeldOwnSetupPrice]'s question: exactly [price], while the key of ours it asked about stands. */
    private fun payHeldOwnSetup(
        peerAddress: String,
        held: HeldOwnSetupPrice,
        price: KexAnswerPrice,
    ) {
        val stands = { zchatPreferences.getE2EOurPublicKey(peerAddress) == held.ourKey }
        if (held.zboot) {
            val quoted = zbootQuoteStands(peerAddress)
            val rule = if (quoted) ZbootOnChainRule.QUOTED_IN_SHIELDED else ZbootOnChainRule.STANDING_CONSENT
            val resumeOwed = quoted && zchatPreferences.isZbootOwed(peerAddress)
            registerZbootFrame(peerAddress, rule, resumeOwed)?.let { frame ->
                sendNostrBootHandshake(peerAddress, rule, resumeOwed, frame, payment = OwnSetupPayment(price, stands))
            }
            return
        }
        processSendScope().launch(Dispatchers.Main.immediate) {
            try {
                val ourAddress = currentChatIdentity()
                when {
                    ourAddress == null || !stands() -> Log.w("KEX", "Pay on our KEX's true price: nothing sent")
                    zchatPreferences.isKexOwed(peerAddress) -> payQuotedOwedKex(peerAddress, "True-price", price)
                    zchatPreferences.setOwnBootSent(peerAddress, true) ->
                        // ZC-1272: this answer replaces the leg the first question covered, which goes when it pays.
                        sendKexOnce(
                            peerAddress,
                            ourAddress,
                            stands,
                            retryOf = null,
                            OwnSetupPayment(price, stands, coveredKexLeg = quotedChatSetup(peerAddress)?.kex),
                        )
                    else -> Log.e("KEX", "KEX not paid: its bootstrap-sent marker could not be written")
                }
            } catch (e: Exception) {
                if (e is kotlinx.coroutines.CancellationException) throw e
                Log.w("KEX", "Pay on our KEX's true price failed: ${e.javaClass.simpleName}")
            }
        }
    }

    /** [retryKexAckIfResponder]'s work, which R9-2's Allow ([grantHandshakeSpendConsent]) also runs for each held KEXACK. */
    private suspend fun retryKexAckOnce(peerAddress: String) {
        val peerKey = zchatPreferences.getE2EPeerPublicKey(peerAddress) ?: return
        // RESPONDER ONLY. We re-ack a peer iff we actually RECEIVED their KEX for this exact key —
        // `getReceivedKexPubkey` is set solely in the received-KEX path, so it (unlike isOwnBootSent,
        // which the VAULT KEX path never sets, and unlike kexTxId/kexAckTxId, which are set on BOTH
        // directions) is the one reliable "we are the responder" signal. The initiator never has it
        // set → it can never emit a spurious paid KEXACK here.
        if (zchatPreferences.getReceivedKexPubkey(peerAddress) != peerKey) return
        if (zchatPreferences.getPeerNostrPubkey(peerAddress) != null) return // Tunnel handshake already complete
        // DURABLE de-dupe (survives process death). A KEXACK is a ~1000-zatoshi on-chain spend; the
        // prior guard was in-memory only and re-drained on EVERY cold start for VAULT/idle contacts
        // (whose getPeerNostrPubkey never becomes non-null). A SUCCEEDED ack is recorded and never
        // re-sent; a FAILED ack is not recorded, so a stuck Tunnel handshake still recovers on open.
        // Cheap pre-check only; payKexAckOnce re-checks it AFTER taking the process-wide claim.
        if (zchatPreferences.getSentKexAckPubkey(peerAddress) == peerKey) return
        val ourAddress = _currentUserAddress.value ?: return
        try {
            val outcome = payKexAckOnce(peerAddress, peerKey, ourAddress, consumeBudget = false) { answerConversationId(peerAddress) }
            if (outcome == KexAckOutcome.SENT) {
                Log.d("KEX", "Responder re-sent KEXACK for ${peerAddress.take(16)}… (#233 handshake retry)")
            }
        } catch (e: Exception) {
            if (e is kotlinx.coroutines.CancellationException) throw e
            Log.w("KEX", "retryKexAckIfResponder failed: ${e.message}")
        }
    }

    /**
     * ZC-599 (FIRST-CONTACT-SPEC 5.4 item 4, FC-2a) — the id an answer to [peerAddress]'s key exchange goes out under: the
     * id of that key exchange, kept beside the responder mark; with none kept, this phone's id for the contact (as before).
     */
    private suspend fun answerConversationId(peerAddress: String): String =
        zchatPreferences.getReceivedKexConvId(peerAddress)
            ?: convIdMutex.withLock { zchatPreferences.getOrCreateConversationId(peerAddress) }.first

    /** What [payKexAckOnce] did. Only [SENT] submitted a transaction in this call. */
    private enum class KexAckOutcome {
        SENT,
        ALREADY_ACKED,
        IN_FLIGHT,
        BUDGET_EXHAUSTED,
        AWAITING_ACCEPT,
        NOT_SENT,

        /** ZC-739: the contact's new key waits for the user. Nothing was built, stamped or paid; no budget was used. */
        KEY_DECISION_WAITS,

        /**
         * ZC-660: the key is the one the user adopted with "Accept the new key", and our own key exchange to it was paid
         * within the hour or is still owed with the reconnect reason: that key exchange answers the contact. Nothing was
         * built, stamped or paid; no budget was used; no marker written.
         */
        ANSWERED_BY_OUR_KEX,

        /**
         * F8 (ZC-112): an earlier KEXACK for this key is unresolved, mined and not yet deep, or proven not sent and waiting
         * for the notice's Retry. Nothing was built, stamped or paid, and nothing is changed (callers treat it as [IN_FLIGHT]).
         */
        PENDING,
    }

    /**
     * R2-2 (a) — true when [peerAddress] has no chat with us yet: no key of ours for them, E2E never turned on for
     * them, not a saved contact. Read before an inbound key offer writes any of these.
     */
    private fun isFirstContact(peerAddress: String): Boolean =
        zchatPreferences.getE2EOurPublicKey(peerAddress) == null &&
            !zchatPreferences.isE2EEnabled(peerAddress) &&
            !contactBook.hasContact(peerAddress)

    /**
     * ZC-922 (W-137 B-4) — for the group invite banner: [inviterAddress] is a known contact (a key of ours, E2E, a saved
     * contact, or a chat mode such as an accepted Open chat), so its invitation, which waits for Join like every
     * invitation, does not get the stranger's text. A read only; nothing is written.
     */
    fun isKnownGroupInviter(inviterAddress: String): Boolean =
        runCatching {
            !isFirstContact(inviterAddress) || zchatPreferences.getConversationModeOrNull(inviterAddress) != null
        }.getOrDefault(false)

    /**
     * ZC-822 (W-52) — the Accept hold's own test for a first key exchange: no key of ours for [peerAddress] and E2E never
     * turned on for them. Unlike [isFirstContact] it does not read the address book: a key exchange's sender address is
     * claimed, so a first key at a saved contact waits for Accept too.
     */
    private fun isFirstKeyExchange(peerAddress: String): Boolean =
        zchatPreferences.getE2EOurPublicKey(peerAddress) == null &&
            // ZC-893 (FC-2B, 5.4b item 1): E2E on only because of a key this phone never asked for is no chat either.
            (!zchatPreferences.isE2EEnabled(peerAddress) || holdsUnaskedKey(peerAddress))

    /**
     * ZC-893 (FC-2B; FIRST-CONTACT-SPEC 5.4b) — [peerAddress] holds a contact key this phone neither asked for nor
     * answered: a stored key, no key pair of ours for that address, and no asked record that names it (what an answer
     * nobody asked for, or an invitation's key field, left before this build). It skips no hold, no ZBOOT is believed
     * on its word, and it is dropped when this phone starts its own exchange there.
     */
    private fun holdsUnaskedKey(peerAddress: String): Boolean {
        val key = zchatPreferences.getE2EPeerPublicKey(peerAddress) ?: return false
        return zchatPreferences.getE2EOurPublicKey(peerAddress) == null && zchatPreferences.getKexAskedKey(peerAddress) != key
    }

    /**
     * ZC-893 (FC-2B, 5.4b item 6) — this phone's own start at [peerAddress], before its key pair is made for a send: a
     * key it never asked for there goes, with the peer state it brought ([ZchatPreferences.clearE2EPeerState]) and a hold
     * that names it. Not while a restored wallet has not read its history (no key pair is made then, and the scan may
     * still put ours back beside that key). Under [peerKeyMonitor], so no answer stores a key in between.
     * @return whether a key was dropped.
     */
    private fun dropUnaskedKeyBeforeOwnStart(peerAddress: String): Boolean {
        if (seedKeyProvider.isKeyCreationWaitingForHistory(peerAddress)) return false
        val dropped =
            synchronized(peerKeyMonitor) {
                if (!holdsUnaskedKey(peerAddress)) return@synchronized false
                val key = zchatPreferences.getE2EPeerPublicKey(peerAddress)
                zchatPreferences.clearE2EPeerState(peerAddress)
                if (key != null && zchatPreferences.getInboundKexAwaitingAccept(peerAddress) == key) {
                    zchatPreferences.setInboundKexAwaitingAccept(peerAddress, null)
                }
                true
            }
        if (dropped) Log.w("KEX", "A key this phone never asked for at ${peerAddress.redactAddress()} was dropped before our own start")
        return dropped
    }

    /** ZC-822 — whether [peerAddress] is in the address book (the chat-request banner's words only). */
    fun isSavedContact(peerAddress: String): Boolean = contactBook.hasContact(peerAddress)

    /** R2-2 (a) — an inbound chat request may be offered only from a valid mainnet Unified Address that is not ours. */
    private fun mayOfferInboundChat(address: String): Boolean =
        UnifiedAddressCheck.isMainnetUnifiedAddress(address) && !zchatPreferences.isSelfAddress(address)

    /** R2-2 (a) — true while [peerAddress]'s first KEX waits for the user to accept the chat. */
    fun isInboundKexAwaitingAccept(peerAddress: String): Boolean =
        zchatPreferences.getInboundKexAwaitingAccept(peerAddress) != null

    /**
     * ZC-1792 F1 (QA2 k1, W-137: no crypto or wire change) — true while this phone is the responder for [peerAddress]'s
     * stored key and has not paid its own answer (KEXACK) to it: the request waits for Accept, or we received that key
     * exchange and our answer marker is not that key. A message sealed now uses a root without our answer's txid; once the
     * answer is mined the root moves and the contact can never open it. Nothing Shielded is sealed in this state; the
     * handshake memos themselves (KEX, KEXACK, ZBOOT) are never gated. A chat we began (no received-KEX mark) is not gated.
     */
    private fun ownAnswerToStoredKeyUnpaid(peerAddress: String): Boolean {
        val peerKey = zchatPreferences.getE2EPeerPublicKey(peerAddress) ?: return false
        if (zchatPreferences.getInboundKexAwaitingAccept(peerAddress) != null) return true
        return zchatPreferences.getReceivedKexPubkey(peerAddress) == peerKey &&
            zchatPreferences.getSentKexAckPubkey(peerAddress) != peerKey
    }

    /**
     * ZC-1816 — a send refused by the Accept-first gate ([ownAnswerToStoredKeyUnpaid]) with no hold (we received the stored
     * key, our answer marker is not that key, and nothing retries the answer) puts the request back on hold, so the Accept
     * banner (or the Tunnel offer) is on screen as the refusal says. Nothing is paid here: the answer goes only on the
     * user's Accept. An answer in flight, or an Accept waiting for funds for that key, is left alone.
     * ZC-1844 (QA2 k1b2): so is a key our own key exchange answers ([answeredByOurKeyExchange]: the user accepted the new
     * key and our reconnect KEX is out within the hour or owed). An Accept there answers ANSWERED_BY_OUR_KEX and does
     * nothing; the refusal says what waits instead ([acceptFirstRefusalText]).
     */
    private fun offerAcceptForUnpaidAnswer(peerAddress: String) {
        val peerKey = zchatPreferences.getE2EPeerPublicKey(peerAddress) ?: return
        if (zchatPreferences.getInboundKexAwaitingAccept(peerAddress) != null ||
            zchatPreferences.getReceivedKexPubkey(peerAddress) != peerKey ||
            zchatPreferences.getSentKexAckPubkey(peerAddress) == peerKey ||
            peerAddress in kexAckInFlight ||
            acceptsWaitingForFunds[peerAddress]?.key == peerKey ||
            answeredByOurKeyExchange(peerAddress, peerKey)
        ) {
            return
        }
        if (zchatPreferences.setInboundKexAwaitingAccept(peerAddress, peerKey)) {
            Log.i("KEX", "ZC-1816: our answer is not paid and nothing retries it — the request is offered for Accept again")
        } else {
            Log.w("KEX", "ZC-1816: putting the request back on hold was not saved")
        }
    }

    /**
     * ZC-1792 F1, ZC-1812, ZC-1816 — the Accept-first refusal of a send: nothing stored, built or paid for this message.
     * ZC-1843: [setupPaid] — this row's run paid the chat's key exchange first. @return the text shown.
     */
    private fun refuseAcceptFirst(
        peerAddress: String,
        setupPaid: Boolean = false,
    ): String {
        Log.w("ZCHAT_SEND", "ZC-1792: the answer to the contact's key exchange is not paid — nothing sealed, this message not paid")
        offerAcceptForUnpaidAnswer(peerAddress)
        val text = acceptFirstRefusalText(peerAddress, setupPaid)
        _sendMessageState.value = SendMessageState.Error(text)
        return text
    }

    /**
     * ZC-1843, ZC-1844 (QA2 k1b2) — what an Accept-first refusal says: our own key exchange answers the stored key (no Accept
     * can help: [ChatSendCopy.KEY_EXCHANGE_FINISHING_NOT_SENT]); else, after this row's run paid the chat's key exchange
     * ([setupPaid]), that the setup went out ([ChatSendCopy.ACCEPT_FIRST_NOT_SENT_SETUP_PAID]); else "nothing was paid".
     */
    private fun acceptFirstRefusalText(
        peerAddress: String,
        setupPaid: Boolean,
    ): String {
        val peerKey = runCatching { zchatPreferences.getE2EPeerPublicKey(peerAddress) }.getOrNull()
        return when {
            peerKey != null && answeredByOurKeyExchange(peerAddress, peerKey) -> ChatSendCopy.KEY_EXCHANGE_FINISHING_NOT_SENT
            setupPaid -> ChatSendCopy.ACCEPT_FIRST_NOT_SENT_SETUP_PAID
            else -> ChatSendCopy.ACCEPT_FIRST_NOT_SENT
        }
    }

    /**
     * R2-2 (a) — the user accepted a chat request from [peerAddress]: pay the one KEXACK its first KEX is waiting
     * for (through [payKexAckOnce], so at most one per key, and not from the automatic budget). The marker is
     * cleared first; if the KEXACK is not sent (no consent yet, funds confirming), opening the chat retries it
     * as for any responder. A request whose key was replaced meanwhile is dropped.
     */
    @JvmOverloads
    fun acceptInboundKexRequest(
        peerAddress: String,
        // ZC-1233: the true price the user just confirmed, paid on that answer while the request stands. ZC-1230, ZC-1233:
        // a build that is refused leaves the hold, forgets the Accept so no chat open builds it again, and tells the need
        // or asks the true price. Round 2: a Pay answers the key it asked about; for any other request it pays nothing and
        // that request's own Accept stands.
        confirmed: ConfirmedKexAnswer? = null,
    ) {
        userStartsSetupAgain(peerAddress)
        // ZC-739: no answer is paid while the contact's new key waits for the user; the hold stays and the tap says why.
        if (blockedByKeyChange(peerAddress)) return
        viewModelScope.launch {
            val waitingKey = zchatPreferences.getInboundKexAwaitingAccept(peerAddress) ?: return@launch
            if (confirmed != null && confirmed.key != waitingKey) {
                Log.w("KEX", "Pay on a true-price question: the request changed — nothing sent")
                return@launch
            }
            // ZC-1017 (W-57): an Open chat never pays. Its held key exchange is answered only through the Tunnel offer
            // ([acceptOpenChatTunnelOffer]), which switches the chat to Tunnel first; the hold stays.
            if (zchatPreferences.getConversationMode(peerAddress) == ConversationMode.OPEN) {
                Log.i("KEX", "Accepted chat request in an Open chat — nothing sent (the Tunnel offer answers it)")
                return@launch
            }
            // ZC-693: the hold is NOT cleared here. The accept is remembered for this process (the answer of this key
            // may pass the hold) and asked about again if it was declined; the hold goes only once the answer was sent
            // or may have been ([settleChatRequest]). "Not now" forgets the accept, so the banner stays.
            acceptedChatRequests[peerAddress] = waitingKey
            // ZC-1047: a new Accept asks the price question again, even after "Not now" to an earlier one.
            dismissedAutomaticSetups.remove(QueuedAutomaticSetup(AutomaticSetupKind.KEXACK, peerAddress))
            val peerKey = zchatPreferences.getE2EPeerPublicKey(peerAddress)?.takeIf { it == waitingKey }
            if (peerKey == null) {
                Log.w("KEX", "Accepted chat request's key was replaced — nothing sent")
                return@launch
            }
            val ourAddress = _currentUserAddress.value ?: return@launch
            // ZC-893 (FC-2B, 5.4b item 2): the key the user accepted is taken on purpose; recorded before its answer is paid.
            zchatPreferences.setKexAskedKey(peerAddress, peerKey)
            // ZC-634 (5.5 item 2): a key this wallet's own mined answer answered with no settled answer stays a claim after
            // the tap (the hold was the mark until now).
            val verdict = ownAnswerVerdicts[peerAddress]
            if (verdict != null && verdict.key == peerKey && !verdict.settled) {
                val marked =
                    synchronized(peerKeyMonitor) {
                        zchatPreferences.getKeyClaim(peerAddress) != null || zchatPreferences.markKeyClaim(peerAddress, peerKey)
                    }
                if (!marked) {
                    Log.w("KEX", "Accepted chat request: its claim mark was not saved — nothing sent")
                    return@launch
                }
            }
            var refusal: KexAnswerRefusal? = null
            // ZC-1392: the account this tap (or the wait it resumes, run only under that account) pays from.
            val tapAccount = selectedAccountOrNull()?.let(GetDefaultUnifiedAddressUseCase::accountKeyOf)
            val outcome =
                try {
                    payKexAckOnce(
                        peerAddress,
                        peerKey,
                        ourAddress,
                        consumeBudget = false,
                        confirmedByQuote =
                            confirmed?.let { asked ->
                                {
                                    zchatPreferences.getE2EPeerPublicKey(peerAddress) == asked.key &&
                                        zchatPreferences.getInboundKexAwaitingAccept(peerAddress) == asked.key &&
                                        !zchatPreferences.isE2EKeyChanged(peerAddress)
                                }
                            },
                        answerPrice = confirmed?.price ?: handshakeAnswerPrice(),
                        onRefused = { refusal = it },
                        onFundsWait = { tellAcceptWaitsForFunds(peerAddress, peerKey, tapAccount) },
                    ) {
                        answerConversationId(peerAddress)
                    }
                } catch (e: Exception) {
                    if (e is kotlinx.coroutines.CancellationException) throw e
                    Log.w("KEX", "Accepted chat request: KEXACK failed: ${e.message}")
                    KexAckOutcome.NOT_SENT
                }
            // ZC-1338: a later tap meets the waiting answer: the same words, and still one answer (kexAckInFlight).
            if (outcome == KexAckOutcome.IN_FLIGHT) tellAcceptWaitsForFunds(peerAddress, peerKey, tapAccount)
            offerAcceptAgainIfNothingSent(peerAddress, peerKey, outcome)
            // ZC-1338: this run's waits ended with the funds still confirming: a later block starts the next run, same tap.
            // ZC-1375: and a run of a standing wait that the funds gate stopped before any build (nothing spendable yet, no
            // refusal) is still that wait: it is kept within its limit, and a later block tries again.
            val keepsWaiting =
                (refusal as? KexAnswerRefusal.TooLittle)?.stillConfirming == true ||
                    (outcome == KexAckOutcome.NOT_SENT && refusal == null && fundsGateStopsWait(peerAddress, peerKey))
            if (keepsWaiting) tellAcceptWaitsForFunds(peerAddress, peerKey, tapAccount)
            if (!keepsWaiting && outcome != KexAckOutcome.IN_FLIGHT) {
                // ZC-1391: an earlier process's waits are read first, so this one's end removes it and keeps the others.
                restoreAcceptWaits()
                acceptsWaitingForFunds.remove(peerAddress)
                storeAcceptWaits()
            }
            refusal?.takeUnless { keepsWaiting }?.let {
                acceptedChatRequests.remove(peerAddress, peerKey)
                // Round 2: a question on a request that has changed could only be refused on Pay.
                if (it is KexAnswerRefusal.TooLittle || kexRequestStands(peerAddress, peerKey)) {
                    tellKexAnswerRefusal(it) { price -> acceptInboundKexRequest(peerAddress, ConfirmedKexAnswer(price, peerKey)) }
                }
            }
        }
    }

    /**
     * ZC-1338 — an Accept tap's answer to [peerAddress] goes on the block that can pay it, with no second tap: at most one
     * contact per block, while its hold still names that key, and within [ACCEPT_FUNDS_WAIT_LIMIT_MS] of the first wait. Who
     * consented: the tap. What it costs: the answer's price, as the tap. Paid once: [acceptInboundKexRequest] runs the same
     * [payKexAckOnce], whose in-flight set, sent marker, hour record and ledger entry stop a second payment.
     */
    private fun resumeAcceptsWaitingForFunds() {
        restoreAcceptWaits()
        val now = System.currentTimeMillis()
        for ((peer, wait) in acceptsWaitingForFunds) {
            if (now > wait.until || zchatPreferences.getInboundKexAwaitingAccept(peer) != wait.key) {
                acceptsWaitingForFunds.remove(peer, wait)
                storeAcceptWaits()
            }
        }
        // ZC-1392 (money-path rule 2): a wait is run only while the account that tapped Accept is selected; under another
        // account it stays, within its limit, for that one (also after a restart, and after a switch with no restart).
        viewModelScope.launch {
            val selected = selectedAccountOrNull()?.let(GetDefaultUnifiedAddressUseCase::accountKeyOf)
            for ((peer, wait) in acceptsWaitingForFunds) {
                if (peer in kexAckInFlight || wait.account != selected) continue
                acceptInboundKexRequest(peer)
                return@launch
            }
        }
    }

    /** ZC-1338 — what an Accept tap says while its answer waits for the funds. A question on screen is never replaced by it. */
    private fun tellAcceptWaitsForFunds(
        peerAddress: String,
        peerKey: String,
        // ZC-1392: the account selected at the tap.
        account: String?,
    ) {
        // ZC-1350: a run still ending after its Accept was withdrawn arms nothing again.
        if (acceptedChatRequests[peerAddress] != peerKey) return
        // ZC-1391: an earlier process's waits are read before this write replaces the slot.
        restoreAcceptWaits()
        acceptsWaitingForFunds.compute(peerAddress) { _, old ->
            old?.takeIf { it.key == peerKey && it.account == account }
                ?: AcceptFundsWait(peerKey, System.currentTimeMillis() + ACCEPT_FUNDS_WAIT_LIMIT_MS, account)
        }
        storeAcceptWaits()
        when (_sendMessageState.value) {
            is SendMessageState.NeedsHandshakeSpendConsent,
            is SendMessageState.NeedsPaidActionConfirmation,
            is SendMessageState.NeedsIronwoodMigration,
            is SendMessageState.NeedsOrchardShielding,
            -> return
            else -> _sendMessageState.value = SendMessageState.Error(ChatSendCopy.KEX_ANSWER_WAITS_FOR_FUNDS)
        }
    }

    /**
     * ZC-1375 — whether a run of [peerAddress]'s Accept that sent nothing and was refused nothing ended at the funds gate of a
     * wait still inside its limit: the wait for [peerKey] stands, and the selected account cannot pay one handshake yet. Only
     * such a stop keeps the wait; every other gate (the consent question, a changed key, a deleted chat) ends it as before.
     */
    private suspend fun fundsGateStopsWait(
        peerAddress: String,
        peerKey: String,
    ): Boolean {
        val wait = acceptsWaitingForFunds[peerAddress] ?: return false
        if (wait.key != peerKey || System.currentTimeMillis() > wait.until) return false
        return handshakeWalletCanPayOne(selectedAccountOrNull()) == false
    }

    /**
     * ZC-1375 — the Accept waits as they stand, written to the store (in the handshake-record store, so a reset or a wallet
     * change wipes them with the other handshake marks). A restart within the hour then keeps the tap's wait. Each entry is
     * the contact, the key its Accept answers and the wait's end; nothing is paid from it, only [acceptInboundKexRequest] is run.
     * ZC-1392: and the account that tapped (empty when it could not be read).
     * ZC-1391: the slot holds every contact's wait, so the store's waits are read first ([restoreAcceptWaits]): a write before
     * this screen's first block never drops another chat's kept wait. A writer that removes a wait reads them before it removes.
     */
    private fun storeAcceptWaits() {
        restoreAcceptWaits()
        val record =
            acceptsWaitingForFunds.entries
                .joinToString(ACCEPT_WAIT_ENTRY_SEPARATOR) { (peer, wait) ->
                    listOf(peer, wait.key, wait.until.toString(), wait.account.orEmpty()).joinToString(ACCEPT_WAIT_FIELD_SEPARATOR)
                }.ifEmpty { null }
        val saved = runCatching { zchatPreferences.setHandshakePaidRecord(ACCEPT_FUNDS_WAIT_SLOT, record) }.getOrDefault(false)
        if (!saved) Log.w("KEX", "Accept waiting for funds: the store did not save it")
    }

    /** ZC-1375 — once per screen, the Accept waits the store keeps (an earlier process's) that are still inside their limit. */
    private fun restoreAcceptWaits() {
        if (acceptWaitsRestored) return
        acceptWaitsRestored = true
        val record = runCatching { zchatPreferences.getHandshakePaidRecord(ACCEPT_FUNDS_WAIT_SLOT) }.getOrNull() ?: return
        val now = System.currentTimeMillis()
        for (entry in record.split(ACCEPT_WAIT_ENTRY_SEPARATOR)) {
            val fields = entry.split(ACCEPT_WAIT_FIELD_SEPARATOR)
            val until = fields.getOrNull(2)?.toLongOrNull()
            // ZC-1392: an entry with no account field (the ZC-1375 test build) names no tapping account: it is not run.
            if (fields.size != 4 || until == null || until < now || until > now + ACCEPT_FUNDS_WAIT_LIMIT_MS) continue
            acceptsWaitingForFunds.putIfAbsent(fields[0], AcceptFundsWait(fields[1], until, fields[3].ifEmpty { null }))
        }
    }

    /**
     * ZC-1047 — an Accept whose answer sent nothing (its price question is open or was declined, or the wallet cannot pay
     * yet) puts the request back on hold, so the Accept banner offers the key exchange again: for a contact whose relay
     * key is known no other path ever answers it, and the sender's payment for its key exchange was stranded. Allow on
     * that question answers it ([grantHandshakeSpendConsent]); nothing is paid without the question.
     */
    private fun offerAcceptAgainIfNothingSent(
        peerAddress: String,
        peerKey: String,
        outcome: KexAckOutcome,
    ) {
        if (outcome != KexAckOutcome.NOT_SENT ||
            zchatPreferences.getE2EPeerPublicKey(peerAddress) != peerKey ||
            zchatPreferences.getSentKexAckPubkey(peerAddress) == peerKey ||
            zchatPreferences.getInboundKexAwaitingAccept(peerAddress) != null
        ) {
            return
        }
        if (zchatPreferences.setInboundKexAwaitingAccept(peerAddress, peerKey)) {
            synchronized(acceptsAwaitingConsent) {
                acceptsAwaitingConsent.getOrPut(zchatPreferences) { HashMap() }[peerAddress] = peerKey
            }
            Log.i("KEX", "Accepted chat request: nothing sent — the request is offered again")
        } else {
            Log.w("KEX", "Accepted chat request: nothing sent, and putting the request back on hold was not saved")
        }
    }

    /**
     * ZC-1017 (decided under W-57) — what the chat with [peerAddress] shows for a paid key exchange held in a chat this
     * phone holds as Open ([OpenChatTunnelOffer]). A held key exchange in an Open chat is offered (unless Keep Open was
     * chosen for that key); after Accept the offer stays, without buttons, until the answer is mined, and comes back when
     * provably nothing was sent. A chat that is not Open keeps the earlier Accept banner (NONE here).
     */
    fun openChatTunnelOffer(peerAddress: String): OpenChatTunnelOffer.Stage {
        val record = runCatching { zchatPreferences.getOpenChatKexOffer(peerAddress) }.getOrNull()
        val held = zchatPreferences.getInboundKexAwaitingAccept(peerAddress)
        if (held != null) {
            val open = zchatPreferences.getConversationMode(peerAddress) == ConversationMode.OPEN
            return if (open && !OpenChatTunnelOffer.isKeptOpen(record, held)) {
                OpenChatTunnelOffer.Stage.OFFERED
            } else {
                OpenChatTunnelOffer.Stage.NONE
            }
        }
        val accepted = OpenChatTunnelOffer.acceptedKey(record) ?: return OpenChatTunnelOffer.Stage.NONE
        // ZC-1041: an acceptance of a key that is no longer the contact's is stale: no offer, so its Keep Open can never
        // put that key back on the hold or switch the chat to Open.
        if (zchatPreferences.getE2EPeerPublicKey(peerAddress) != accepted) return OpenChatTunnelOffer.Stage.NONE
        val entry =
            runCatching {
                sendAttempts?.ledger?.get(SendAttemptLedgerRules.key(SendAttemptKind.KEXACK, peerAddress, accepted))
            }.getOrNull()
        return OpenChatTunnelOffer.afterAccept(
            entryState = entry?.state,
            inFlight = peerAddress in kexAckInFlight,
            acked = zchatPreferences.getSentKexAckPubkey(peerAddress) == accepted,
        )
    }

    /**
     * ZC-1017 — "Accept and pay" on the Tunnel offer. Nothing happens unless the offer stands and the wallet can pay one
     * answer (the chat then stays Open). Otherwise, in this order: the acceptance is recorded (a checked write; refused:
     * nothing changes), the chat becomes Tunnel (and the user's own pick), the Accept hold is cleared, and only then is
     * the one answer (KEXACK) built and paid, through [payKexAckOnce] on this Accept's quote, which is re-read before every
     * attempt: the chat is still Tunnel and the acceptance still names this key. So no Open chat ever pays.
     *
     * ZC-1230, ZC-1233: a build that is refused (too little, or above this Accept's price) takes all of that back: the chat
     * is Open with its offer and hold ([undoTunnelOfferAccept]), and the user is told the need or asked the true price.
     * Round 2: only while this Accept still stands; a later mode or key wins, and no question is asked on it.
     */
    fun acceptOpenChatTunnelOffer(peerAddress: String) = acceptOpenChatTunnelOfferAt(peerAddress, null)

    private fun acceptOpenChatTunnelOfferAt(
        peerAddress: String,
        // Round 2: Pay on the true-price question; null is the offer's own Accept, at the handshake price.
        confirmed: ConfirmedKexAnswer?,
    ) {
        val price = confirmed?.price ?: handshakeAnswerPrice()
        viewModelScope.launch {
            val key = offeredTunnelKey(peerAddress) ?: return@launch
            if (confirmed != null && (confirmed.key != key || zchatPreferences.isE2EKeyChanged(peerAddress))) {
                Log.w("KEX", "Pay on a true-price question: the request changed — nothing changed, nothing sent")
                return@launch
            }
            if (zchatPreferences.getE2EPeerPublicKey(peerAddress) != key) {
                Log.w("KEX", "Tunnel offer: the contact's key was replaced — nothing sent")
                return@launch
            }
            val payer = selectedAccountOrNull()
            val canPay = handshakeWalletCanPayOne(payer)
            if (canPay != true) {
                Log.i("KEX", "Tunnel offer: the wallet cannot pay the answer yet — the chat stays Open, nothing sent")
                // ZC-1234: the same notice as a refused build. An unreadable account has no figure to tell. ZC-1417: a wallet
                // a little above the price needs the price plus a change the SDK accepts.
                if (canPay == false && offeredTunnelKey(peerAddress) == key) {
                    val need =
                        payer?.let { spendableNeed(it.peerSpendableBalance, price.figure) }
                            ?: price.figure
                    tellKexAnswerRefusal(KexAnswerRefusal.TooLittle(need)) {}
                }
                return@launch
            }
            // ZC-1040: the account read may have waited; a Keep Open (or any other change of the offer) made meanwhile is
            // the later choice and wins. Nothing suspends from here to the writes below.
            if (offeredTunnelKey(peerAddress) != key) {
                Log.i("KEX", "Tunnel offer: the choice changed while Accept waited — nothing changed, nothing sent")
                return@launch
            }
            val ourAddress = _currentUserAddress.value ?: return@launch
            // ZC-1038: a KEX still owed by an action confirmed before this chat became Open (ZC-880 keeps its mark) is not
            // in this question, which counts one answer. Once the chat is Tunnel that mark would be paid by the next block
            // or chat open. The answer carries our current key, which is what that KEX delivers, so the mark and the ZBOOT
            // allowance of its question are void here, before the mode changes: nothing pays them unasked.
            // ZC-1038-R1: only once the acceptance is saved, so a refused acceptance keeps the KEX the user confirmed; a void
            // that is not saved takes the acceptance back.
            val recordBefore = runCatching { zchatPreferences.getOpenChatKexOffer(peerAddress) }.getOrNull()
            val explicitBefore = zchatPreferences.isConversationModeExplicit(peerAddress)
            val owedBefore = owedKexBefore(peerAddress)
            if (!zchatPreferences.setOpenChatKexOffer(peerAddress, OpenChatTunnelOffer.accepted(key))) {
                Log.w("KEX", "Tunnel offer: the acceptance was not saved — nothing changed, nothing sent")
                return@launch
            }
            if (!voidOwedKexBeforeTunnelOffer(peerAddress)) {
                zchatPreferences.setOpenChatKexOffer(peerAddress, recordBefore)
                Log.w("KEX", "Tunnel offer: an earlier owed key exchange could not be voided — nothing changed, nothing sent")
                return@launch
            }
            zchatPreferences.setConversationMode(peerAddress, ConversationMode.TUNNEL)
            zchatPreferences.setConversationModeExplicit(peerAddress)
            if (zchatPreferences.getInboundKexAwaitingAccept(peerAddress) != null &&
                !zchatPreferences.setInboundKexAwaitingAccept(peerAddress, null)
            ) {
                Log.w("KEX", "Tunnel offer: clearing the hold was not saved — nothing sent")
                return@launch
            }
            val quoteStands = {
                zchatPreferences.getConversationMode(peerAddress) == ConversationMode.TUNNEL &&
                    OpenChatTunnelOffer.acceptedKey(runCatching { zchatPreferences.getOpenChatKexOffer(peerAddress) }.getOrNull()) == key
            }
            var refusal: KexAnswerRefusal? = null
            try {
                payKexAckOnce(
                    peerAddress,
                    key,
                    ourAddress,
                    consumeBudget = false,
                    confirmedByQuote = quoteStands,
                    answerPrice = price,
                    onRefused = { refusal = it },
                ) {
                    convIdMutex.withLock { zchatPreferences.getOrCreateConversationId(peerAddress) }.first
                }
            } catch (e: Exception) {
                if (e is kotlinx.coroutines.CancellationException) throw e
                Log.w("KEX", "Tunnel offer: the answer failed: ${e.message}")
            }
            refusal?.let {
                // Under the monitor every key writer holds, so no new key lands between the check and the undo.
                val undone =
                    synchronized(peerKeyMonitor) {
                        val stands = quoteStands() && kexRequestStands(peerAddress, key)
                        if (stands) undoTunnelOfferAccept(peerAddress, key, recordBefore, explicitBefore, owedBefore)
                        stands
                    }
                // A later mode or key stays. Its need is still told over an idle screen; a question could only be refused on Pay.
                if (undone || (it is KexAnswerRefusal.TooLittle && _sendMessageState.value == SendMessageState.Idle)) {
                    tellKexAnswerRefusal(it) { truePrice -> acceptOpenChatTunnelOfferAt(peerAddress, ConfirmedKexAnswer(truePrice, key)) }
                }
            }
        }
    }

    /**
     * ZC-1230, ZC-1233 round 2 — the contact's request is still the one for [key]: its key is stored, no other key is on the
     * hold, and no different key was refused and waits for the user (for a stored key a new KEX stores nothing and raises
     * that flag).
     */
    private fun kexRequestStands(
        peerAddress: String,
        key: String,
    ): Boolean =
        zchatPreferences.getE2EPeerPublicKey(peerAddress) == key &&
            (zchatPreferences.getInboundKexAwaitingAccept(peerAddress) ?: key) == key &&
            !zchatPreferences.isE2EKeyChanged(peerAddress)

    /** ZC-1230: the owed KEX mark [voidOwedKexBeforeTunnelOffer] may remove, with what goes with it; null when none is owed. */
    private class OwedKexBefore(
        val account: String?,
        val reason: String?,
    )

    private fun owedKexBefore(peerAddress: String): OwedKexBefore? =
        runCatching {
            if (zchatPreferences.isKexOwed(peerAddress)) {
                OwedKexBefore(zchatPreferences.getKexOwedAccount(peerAddress), zchatPreferences.getKexOwedReason(peerAddress))
            } else {
                null
            }
        }.getOrNull()

    /**
     * ZC-1230 — an Accept on the Tunnel offer whose build was refused paid nothing, so what it changed goes back: the hold
     * first, then Open, the user's pick, the offer record and the owed KEX it voided. A ZBOOT allowance it withdrew stays
     * withdrawn (it pays nothing; that ZBOOT then asks for itself).
     */
    private fun undoTunnelOfferAccept(
        peerAddress: String,
        key: String,
        recordBefore: String?,
        explicitBefore: Boolean,
        owedBefore: OwedKexBefore?,
    ) {
        val held = zchatPreferences.setInboundKexAwaitingAccept(peerAddress, key)
        zchatPreferences.setConversationMode(peerAddress, ConversationMode.OPEN)
        if (!explicitBefore) zchatPreferences.clearConversationModeExplicit(peerAddress)
        val offer = zchatPreferences.setOpenChatKexOffer(peerAddress, recordBefore)
        if (owedBefore != null &&
            zchatPreferences.setKexOwedAccount(peerAddress, owedBefore.account) &&
            zchatPreferences.setKexOwedReason(peerAddress, owedBefore.reason) &&
            zchatPreferences.setKexOwed(peerAddress, true)
        ) {
            kexOwedPeers.add(peerAddress)
        }
        if (!held || !offer) Log.w("KEX", "Tunnel offer: a refused Accept could not put everything back (hold: $held, offer: $offer)")
    }

    /**
     * ZC-1038 — before the Tunnel offer's Accept switches an Open chat to Tunnel: the KEX owed to [peerAddress] (kept by
     * ZC-880 for a later mode) and the ZBOOT allowance its question wrote are withdrawn, so neither is paid without a
     * question of its own. @return false when a withdrawal was not saved (the caller then changes and pays nothing).
     */
    private fun voidOwedKexBeforeTunnelOffer(peerAddress: String): Boolean {
        val owed =
            kexOwedPeers.contains(peerAddress) ||
                runCatching { zchatPreferences.isKexOwed(peerAddress) }.getOrDefault(true)
        if (!owed) return true
        if (!zchatPreferences.setKexOwed(peerAddress, false)) return false
        kexOwedPeers.remove(peerAddress)
        if (!withdrawZbootQuote(peerAddress)) return false
        Log.i("KEX", "Tunnel offer: the earlier owed key exchange is void (not in this question) — nothing paid for it")
        return true
    }

    /** ZC-1040 — the key the Tunnel offer of [peerAddress] stands for now, or null when no offer is shown. */
    private fun offeredTunnelKey(peerAddress: String): String? {
        if (openChatTunnelOffer(peerAddress) != OpenChatTunnelOffer.Stage.OFFERED) return null
        val record = runCatching { zchatPreferences.getOpenChatKexOffer(peerAddress) }.getOrNull()
        return zchatPreferences.getInboundKexAwaitingAccept(peerAddress) ?: OpenChatTunnelOffer.acceptedKey(record)
    }

    /**
     * ZC-1017 — "Keep Open" on the Tunnel offer: nothing is paid, the chat is (again) Open and the Accept hold stays (it is
     * put back when an Accept that sent nothing had cleared it), so no answer is paid later by itself. Keep Open is
     * remembered for that key, which hides the offer.
     */
    fun keepChatOpen(peerAddress: String) {
        viewModelScope.launch {
            if (openChatTunnelOffer(peerAddress) != OpenChatTunnelOffer.Stage.OFFERED) return@launch
            val record = runCatching { zchatPreferences.getOpenChatKexOffer(peerAddress) }.getOrNull()
            val held = zchatPreferences.getInboundKexAwaitingAccept(peerAddress)
            val key = held ?: OpenChatTunnelOffer.acceptedKey(record) ?: return@launch
            if (held == null && !zchatPreferences.setInboundKexAwaitingAccept(peerAddress, key)) {
                Log.w("KEX", "Keep Open: the hold was not saved — the offer stays")
                return@launch
            }
            if (zchatPreferences.getConversationMode(peerAddress) != ConversationMode.OPEN) {
                zchatPreferences.setConversationMode(peerAddress, ConversationMode.OPEN)
            }
            if (!zchatPreferences.setOpenChatKexOffer(peerAddress, OpenChatTunnelOffer.keptOpen(key))) {
                Log.w("KEX", "Keep Open: the decision was not saved — the offer shows again after a restart")
            }
        }
    }

    /**
     * MONEY SAFETY — the ONE place a KEXACK is paid for. Both entry points (the received-KEX branch of
     * handleKEXMessage and [retryKexAckIfResponder]) come through here, so at most one KEXACK per
     * (peer, key) is ever paid by this process:
     *
     * 1. HS-1: the in-flight claim is PROCESS-WIDE ([kexAckInFlight] in the companion). The chat list and
     *    the chat detail are different ChatViewModel instances; a per-instance claim let both pay.
     * 2. After the claim, the durable marker ([ZchatPreferences.getSentKexAckPubkey]) is checked — HS-3:
     *    a peer re-sending the SAME key under a new txid is a no-op, and consumes no budget.
     * 3. HS-2: the marker is stamped BEFORE each submit attempt (by the [HandshakeMarkerGuard] that
     *    [sendKEXAckMessage] hands the retry loop). The repository broadcasts in a detached scope, so a
     *    back-out (cancellation) can land after the transaction is already on the wire; the marker is then
     *    left set. It is cleared only when the send provably failed (the sender returned false) or threw
     *    something other than a cancellation ([mayReArmHandshakeMarker]), and while the loop waits for a
     *    block after a "still confirming" shortfall (nothing was sent). Trade-off, same as the KEX: a
     *    cancel between the stamp and the broadcast also leaves it set, and Reset Encryption clears it.
     * 4. The retry loop re-reads the marker before every attempt, so a KEXACK queued behind a block wait
     *    never pays for a key another attempt has already acked.
     *
     * 5. F8 (ZC-112, ZC-121): the KEXACK is one entry of the send-attempt ledger (the contact and the key it
     *    acknowledges), written before the SDK is asked, with its transaction ids before the first submit. While an entry
     *    of that key stands, this answers [KexAckOutcome.PENDING] before the in-memory "acked" map is written and with
     *    the marker untouched; callers treat it like [KexAckOutcome.IN_FLIGHT]. A KEXACK proven never to have reached the
     *    chain is shown in the chat ("Key exchange not sent"), and its Retry comes back here with [retryOf]. A cancel
     *    before the attempt was handed to the SDK withdraws the marker at once ([sendMemoWithBlockRetry]).
     *
     * @param convId supplies the conversation id, read only once the claim is held.
     */
    private suspend fun payKexAckOnce(
        peerAddress: String,
        peerKey: String,
        ourAddress: String,
        consumeBudget: Boolean,
        // F8: the marker of the NOT_SENT entry the notice's Retry was confirmed for; null for every other caller. It skips
        // only the "already acked" return (the marker and the map say "sent" for a KEXACK that never reached the chain)
        // and the automatic budget; a failure then clears no marker.
        retryOf: Long? = null,
        // ZC-1017: the Tunnel offer's Accept, paid on its own quote while it stands (never under the standing consent).
        confirmedByQuote: (() -> Boolean)? = null,
        // ZC-1233: no answer pays above this, on any path.
        answerPrice: KexAnswerPrice = handshakeAnswerPrice(),
        // ZC-1230, ZC-1233: a tap handles a refused build itself; with none, an automatic path holds one above its price.
        onRefused: ((KexAnswerRefusal) -> Unit)? = null,
        // ZC-1338: an Accept tap's; see sendKEXAckMessage.
        onFundsWait: (() -> Unit)? = null,
        convId: suspend () -> String,
    ): KexAckOutcome {
        // ZC-880: no paid answer in Open, and no automatic budget slot consumed for one.
        if (openNeverSpends(peerAddress)) return KexAckOutcome.NOT_SENT
        if (!kexAckInFlight.add(peerAddress)) {
            Log.d("KEX", "KEXACK already in flight for ${peerAddress.redactAddress()} — skipping duplicate")
            return KexAckOutcome.IN_FLIGHT
        }
        try {
            if (retryOf == null &&
                (kexAckedKeys[peerAddress] == peerKey || zchatPreferences.getSentKexAckPubkey(peerAddress) == peerKey)
            ) {
                Log.d("KEX", "KEXACK already sent for current key of ${peerAddress.redactAddress()} — skipping (no re-charge)")
                // ZC-693: a request whose answer is already out (a hold whose clearing was not saved) is settled.
                settleChatRequest(peerAddress, peerKey)
                return KexAckOutcome.ALREADY_ACKED
            }
            // ZC-739: no answer while the contact's new key waits for the user; checked before the hold and the budget,
            // so it uses none. The decision starts it again ([resumeAfterKeyDecision]).
            if (zchatPreferences.isE2EKeyChanged(peerAddress)) {
                Log.d("KEX", "KEXACK for ${peerAddress.redactAddress()} held: the contact's new key waits for the user")
                return KexAckOutcome.KEY_DECISION_WAITS
            }
            // ZC-660: after a paid accept, the contact's key exchange with the adopted key repeated (sent before ours reached
            // them) is answered by our own key exchange; no answer on top of the accept's quote, no budget.
            if (retryOf == null && answeredByOurKeyExchange(peerAddress, peerKey)) {
                Log.d("KEX", "KEXACK for ${peerAddress.redactAddress()} not paid: our key exchange to the accepted key answers it")
                return KexAckOutcome.ANSWERED_BY_OUR_KEX
            }
            // R2-2 (a): a stranger's chat request is paid for only after the user accepts it. Checked before the
            // budget, so a held request uses none.
            // ZC-693: an Accept of exactly this key in this process lets its answer pass the hold.
            val held = zchatPreferences.getInboundKexAwaitingAccept(peerAddress)
            if (held != null && acceptedChatRequests[peerAddress] != peerKey) {
                Log.d("KEX", "KEXACK for ${peerAddress.redactAddress()} waits for the user to accept the chat")
                return KexAckOutcome.AWAITING_ACCEPT
            }
            // D2 — wallet-wide rolling budget on AUTOMATIC paid KEXACKs from inbound KEXs: an attacker
            // spraying fresh-key KEXs from many addresses must not be able to drain the wallet one auto-ack
            // at a time. Checked only after the marker, so an already-acked key never spends budget.
            // ZC-599 (5.4 item 6): with no key pair of ours for the contact no answer can be built: nothing is spent.
            if (zchatPreferences.getE2EOurPublicKey(peerAddress) == null || zchatPreferences.getE2EPrivateKey(peerAddress) == null) {
                Log.w("KEX", "KEXACK for ${peerAddress.redactAddress()} not sent: no key pair of ours for this chat")
                return KexAckOutcome.NOT_SENT
            }
            if (consumeBudget &&
                retryOf == null &&
                !zchatPreferences.tryConsumeKexAckBudget(
                    System.currentTimeMillis(),
                    ZchatPreferences.MAX_KEXACK_PER_WINDOW,
                    ZchatPreferences.KEXACK_BUDGET_WINDOW_MS,
                )
            ) {
                // Budget exhausted: record nothing, so a later re-scan or peer KEX resend retries.
                Log.w("KEX", "KEXACK budget exhausted — NOT acking ${peerAddress.redactAddress()} this window")
                return KexAckOutcome.BUDGET_EXHAUSTED
            }
            val conversationId = convId()
            val outcome =
                try {
                    sendKEXAckMessage(
                        peerAddress,
                        ourAddress,
                        conversationId,
                        peerKey,
                        retryOf,
                        confirmedByQuote,
                        answerPrice,
                        onFundsWait,
                    ) { refusal ->
                        when {
                            onRefused != null -> onRefused(refusal)
                            refusal is KexAnswerRefusal.AboveItsPrice -> holdKexAnswerAtItsTruePrice(peerAddress, peerKey, refusal.actual)
                            else -> Unit
                        }
                    }
                } catch (e: Exception) {
                    if (!mayReArmHandshakeMarker(e)) throw e // may already be on the wire: keep the marker
                    Log.e("KEX", "KEXACK send failed", e)
                    KexAckOutcome.NOT_SENT
                }
            if (outcome == KexAckOutcome.NOT_SENT) {
                // F8: a failed Retry re-arms nothing; the failed state it was confirmed for still stands.
                if (retryOf == null) clearSentKexAckIfStill(peerAddress, peerKey)
                return KexAckOutcome.NOT_SENT
            }
            // ZC-693: the answer was sent, or an attempt of this key may be out (PENDING): the request is settled.
            settleChatRequest(peerAddress, peerKey)
            // F8: PENDING changes nothing: returned before the in-memory "acked" map is written.
            if (outcome == KexAckOutcome.PENDING) return KexAckOutcome.PENDING
            kexAckedKeys[peerAddress] = peerKey
            // P2h: ALREADY_ACKED when another attempt paid for this key while this one waited for a block.
            return outcome
        } finally {
            kexAckInFlight.remove(peerAddress)
        }
    }

    /**
     * ZC-660 — [peerKey] is the key the user adopted with "Accept the new key" ([ZchatPreferences.getAcceptedKey]) and our key
     * exchange to it is out within the hour (its paid record names our current key) or still owed with the reconnect
     * reason. A store that cannot be read answers false (the answer then goes as today).
     */
    private fun answeredByOurKeyExchange(
        peerAddress: String,
        peerKey: String,
    ): Boolean =
        runCatching {
            // Our key exchange first (the reads every answer path already makes); the accepted key only then.
            val ourKexOut =
                paidSetupCooldown(AutomaticSetupKind.KEX, peerAddress, zchatPreferences.getE2EOurPublicKey(peerAddress)) > 0L ||
                    (
                        zchatPreferences.isKexOwed(peerAddress) &&
                            owedKexReason(peerAddress) == ZchatPreferences.KEX_OWED_REASON_RECONNECT
                    )
            ourKexOut && zchatPreferences.getAcceptedKey(peerAddress) == peerKey
        }.getOrDefault(false)

    /**
     * ZC-693 — the one place a chat request's hold goes: the answer to [peerKey] was sent, may have been (an attempt of
     * that key stands), or was already out. A hold of another key stays. Its clearing write not saved: the hold comes
     * back after a restart and the next Accept finds the answer already sent and settles it then.
     */
    private fun settleChatRequest(
        peerAddress: String,
        peerKey: String,
    ) {
        acceptedChatRequests.remove(peerAddress, peerKey)
        if (zchatPreferences.getInboundKexAwaitingAccept(peerAddress) == peerKey &&
            !zchatPreferences.setInboundKexAwaitingAccept(peerAddress, null)
        ) {
            Log.w("KEX", "Chat request of ${peerAddress.redactAddress()} answered; clearing its hold was not saved")
        }
    }

    /** Re-arm a KEXACK marker this attempt stamped, without touching one a Reset or another key wrote. */
    private fun clearSentKexAckIfStill(peerAddress: String, peerKey: String) {
        if (zchatPreferences.getSentKexAckPubkey(peerAddress) == peerKey) {
            zchatPreferences.setSentKexAckPubkey(peerAddress, null)
        }
    }

    /**
     * P2b — no paid ZBOOT replay after a restore. Our own MINED ZBOOT, read from history, proves which relay
     * identity we already delivered to that conversation; record it as delivered where no marker exists yet
     * (a live marker is never overwritten by a row as it is read), so no trigger pays for the same identity again.
     * ZC-773: only the end of a complete pass replaces a marker, and only by our CURRENT identity when that pass read
     * it mined ([finishZbootHistoryPass]). The conversation id inside the ZBOOT names the peer; [resolvedPeer] is the
     * fallback.
     */
    private class ZbootScope(
        val store: ZchatPreferences,
        val generation: Long,
        val peer: String,
    ) {
        override fun equals(other: Any?): Boolean =
            other is ZbootScope && store === other.store && generation == other.generation && peer == other.peer

        override fun hashCode(): Int = 31 * (31 * System.identityHashCode(store) + generation.hashCode()) + peer.hashCode()
    }

    private class ZbootOwner(
        val order: Long = 0L,
        val protectedSession: Boolean = false,
    )

    private class ZbootFrame(
        val scope: ZbootScope,
        val owner: ZbootOwner,
        val quoteRequired: Boolean,
    ) {
        var identity: String? = null
        var handedOff = false
        var mined: Set<String> = emptySet()

        /**
         * ZC-792: the sender of a Reconnect tap. The user asked for our identity again, so a history pass that reads it
         * mined does not stop this sender (the hour rule of the paid record still does); every other sender is stopped.
         */
        var reconnectTap = false
    }

    private data class ZbootEvidence(
        val identities: Set<String> = emptySet(),
        val workers: Set<Any> = emptySet(),
        val revision: Long = 0L,
        val removalPending: Boolean = false,
        val markerPending: String? = null,
    )

    private class ZbootWork {
        var owner = ZbootOwner()
        val frames = mutableSetOf<ZbootFrame>()
        var evidence: ZbootEvidence? = null
    }

    private class ZbootHistoryPass(
        val generation: Long,
        val grantOrder: Long,
    ) {
        val token = Any()
        val owners = mutableMapOf<String, ZbootOwner>()

        /** ZC-773: the relay identities of our own mined ZBOOTs this pass read, by contact, enrolled or not. */
        val mined = mutableMapOf<String, MutableSet<String>>()
    }

    private enum class ZbootDisposition {
        ACTIVE,
        MINED,
        STALE,
    }

    private class ZbootPreSubmitRefused : IllegalStateException("ZBOOT attempt is no longer payable")

    private fun zbootScope(peer: String): ZbootScope =
        ZbootScope(zchatPreferences, zchatPreferences.walletScopeGeneration(), peer)

    /** Lock order is wallet then one peer compute. The block contains synchronous store decisions only. */
    private fun <T> withZbootWork(scope: ZbootScope, create: Boolean = true, block: (ZbootWork) -> T): T? =
        synchronized(ZchatPreferences.walletScopeLock) {
            if (scope.generation != zchatPreferences.walletScopeGeneration()) return@synchronized null
            zbootWorkByScope.keys.removeAll { it.store === scope.store && it.generation != scope.generation }
            var result: T? = null
            zbootWorkByScope.compute(scope) { _, existing ->
                val work = existing ?: if (create) ZbootWork() else return@compute null
                result = block(work)
                if (work.frames.isEmpty() &&
                    work.evidence == null &&
                    !zchatPreferences.isZbootQuoted(scope.peer) &&
                    !zchatPreferences.isZbootOwed(scope.peer)
                ) {
                    null
                } else {
                    work
                }
            }
            result
        }

    private fun <T> withZbootFrame(frame: ZbootFrame, block: (ZbootWork) -> T): T? =
        withZbootWork(frame.scope, create = false) { work ->
            if (work.owner === frame.owner && frame in work.frames) block(work) else null
        }

    private fun zbootDisposition(frame: ZbootFrame): ZbootDisposition =
        withZbootFrame(frame) {
            val identity = frame.identity
            if (identity != null && identity in frame.mined) ZbootDisposition.MINED else ZbootDisposition.ACTIVE
        } ?: ZbootDisposition.STALE

    private fun ownedZbootQuoteStands(scope: ZbootScope, work: ZbootWork): Boolean {
        if (work.evidence?.removalPending == true ||
            unsavedZbootWithdrawals.contains(scope.peer)
        ) {
            withdrawOwnedZbootQuote(scope, work)
            return false
        }
        return zchatPreferences.isZbootQuoted(scope.peer)
    }

    private fun frameZbootQuoteStands(frame: ZbootFrame): Boolean =
        withZbootFrame(frame) { ownedZbootQuoteStands(frame.scope, it) } == true

    /** A false commit can update memory. A pending removal requires another checked coupled removal. */
    private fun withdrawOwnedZbootQuote(scope: ZbootScope, work: ZbootWork): Boolean {
        val mustWrite =
            work.evidence?.removalPending == true ||
                unsavedZbootWithdrawals.contains(scope.peer) ||
                zchatPreferences.isZbootQuoted(scope.peer) ||
                zchatPreferences.isZbootOwed(scope.peer)
        val saved = !mustWrite || zchatPreferences.setZbootQuoted(scope.peer, false)
        if (saved) unsavedZbootWithdrawals.remove(scope.peer) else unsavedZbootWithdrawals.add(scope.peer)
        return saved
    }

    private fun withdrawFrameZbootQuote(frame: ZbootFrame) {
        withZbootFrame(frame) { withdrawOwnedZbootQuote(frame.scope, it) }
    }

    private fun registerZbootFrame(
        peer: String,
        rule: ZbootOnChainRule,
        resumeOwed: Boolean,
        rearmQuoted: Boolean = false,
    ): ZbootFrame? {
        val scope = zbootScope(peer)
        return withZbootWork(scope) { work ->
            val quoted = ownedZbootQuoteStands(scope, work)
            if ((resumeOwed || rearmQuoted) && !quoted) return@withZbootWork null
            if (rearmQuoted) zchatPreferences.setSentNostrBootPubkey(peer, null)
            ZbootFrame(scope, work.owner, rule == ZbootOnChainRule.QUOTED_IN_SHIELDED && (resumeOwed || quoted))
                .also { work.frames.add(it) }
        }
    }

    private fun removeZbootFrame(frame: ZbootFrame) {
        withZbootWork(frame.scope, create = false) { it.frames.remove(frame) }
    }

    /** Called under the wallet/owner guard: a volatile non-null marker cannot confirm a failed write. */
    private fun confirmPendingZbootMarker(scope: ZbootScope, work: ZbootWork): Boolean {
        val evidence = work.evidence ?: return true
        val identity = evidence.markerPending ?: return true
        val marker = zchatPreferences.getSentNostrBootPubkey(scope.peer)
        if (marker != null && marker != identity) return false
        if (!zchatPreferences.setSentNostrBootPubkey(scope.peer, identity)) return false
        work.evidence = evidence.copy(markerPending = null, revision = evidence.revision + 1)
        return true
    }

    /** Preserve mined delivery on every exit; stale callbacks cannot rearm a new action's marker. */
    private fun finishZbootFrame(frame: ZbootFrame, rearm: Boolean) {
        val own =
            withZbootFrame(frame) { work ->
                val identity = frame.identity ?: return@withZbootFrame
                val marker = zchatPreferences.getSentNostrBootPubkey(frame.scope.peer)
                if (identity in frame.mined) {
                    if (work.evidence?.markerPending != null) {
                        confirmPendingZbootMarker(frame.scope, work)
                    } else if (marker == null && !zchatPreferences.setSentNostrBootPubkey(frame.scope.peer, identity)) {
                        val evidence = work.evidence ?: ZbootEvidence()
                        work.evidence =
                            evidence.copy(
                                identities = evidence.identities + identity,
                                revision = evidence.revision + 1,
                                markerPending = identity,
                            )
                    }
                } else if (rearm && !frame.handedOff && marker == identity) {
                    zchatPreferences.setSentNostrBootPubkey(frame.scope.peer, null)
                }
            }
        // ZC-785 (c): a sender whose action a confirmed Reset or reconnect replaced, and that sent nothing, re-arms the
        // marker it wrote itself by the same rule. While it holds the in-flight claim no other sender wrote this contact's
        // marker (a Reset has cleared it already), so the new action's ZBOOT is not swallowed as "already delivered".
        // Never after the attempt was handed to the SDK, and never in another wallet's store ([withZbootWork]).
        val identity = frame.identity
        if (own == null && rearm && !frame.handedOff && identity != null && identity !in frame.mined) {
            withZbootWork(frame.scope, create = false) {
                if (zchatPreferences.getSentNostrBootPubkey(frame.scope.peer) == identity) {
                    zchatPreferences.setSentNostrBootPubkey(frame.scope.peer, null)
                }
            }
        }
    }

    private fun enrollZbootHistoryPeer(pass: ZbootHistoryPass, scope: ZbootScope, work: ZbootWork): Boolean {
        val enrolled = pass.owners[scope.peer]
        if (enrolled != null && enrolled !== work.owner) return false
        if (work.owner.protectedSession || work.owner.order > pass.grantOrder) return false
        if (enrolled == null &&
            work.evidence == null &&
            !zchatPreferences.isZbootOwed(scope.peer) &&
            work.frames.none { it.owner === work.owner && !it.handedOff }
        ) {
            return false
        }
        pass.owners[scope.peer] = work.owner
        val evidence = work.evidence ?: ZbootEvidence()
        work.evidence = evidence.copy(workers = evidence.workers + pass.token)
        return true
    }

    private fun beginZbootHistoryPass(): ZbootHistoryPass =
        synchronized(ZchatPreferences.walletScopeLock) {
            val pass = ZbootHistoryPass(zchatPreferences.walletScopeGeneration(), zbootGrantOrder.get())
            zbootWorkByScope.keys.removeAll { it.store === zchatPreferences && it.generation != pass.generation }
            val peers =
                zchatPreferences.getZbootOwedPeers() +
                    zbootWorkByScope.keys
                        .filter { it.store === zchatPreferences && it.generation == pass.generation }
                        .map { it.peer }
            for (peer in peers) {
                val scope = ZbootScope(zchatPreferences, pass.generation, peer)
                withZbootWork(scope) { enrollZbootHistoryPeer(pass, scope, it) }
            }
            pass
        }

    private fun recordOwnMinedZbootInPass(pass: ZbootHistoryPass, memo: String, resolvedPeer: String?, mined: Boolean) {
        if (!mined) return
        val boot = ZBootMessage.parse(memo) ?: return
        val peer = zchatPreferences.getPeerByConversationId(boot.convId) ?: resolvedPeer ?: return
        val scope = ZbootScope(zchatPreferences, pass.generation, peer)
        withZbootWork(scope) { work ->
            // ZC-789: only a confirmed Reset or Reconnect keeps its ZBOOT against what the history holds. Any other quote
            // confirmed after this pass began (a mode switch, a first message) is not enrolled ([enrollZbootHistoryPeer]
            // refuses an owner newer than the pass), but the restore below and the end-of-pass rule apply to it: skipping
            // its row whole left the marker empty, and the quoted sender then paid for an identity already on chain.
            if (work.owner.protectedSession) return@withZbootWork
            pass.mined.getOrPut(peer) { mutableSetOf() } += boot.senderNostrPubkeyHex
            if (enrollZbootHistoryPeer(pass, scope, work)) {
                val evidence = requireNotNull(work.evidence)
                if (boot.senderNostrPubkeyHex !in evidence.identities) {
                    work.evidence =
                        evidence.copy(
                            identities = evidence.identities + boot.senderNostrPubkeyHex,
                            revision = evidence.revision + 1,
                        )
                }
            }
            // P2b marker restoration remains null-only; marker existence never skips owed classification.
            if (zchatPreferences.getSentNostrBootPubkey(peer) == null) {
                zchatPreferences.setSentNostrBootPubkey(peer, boot.senderNostrPubkeyHex)
            }
        }
    }

    private fun abandonZbootHistoryPass(pass: ZbootHistoryPass) {
        for ((peer, owner) in pass.owners) {
            withZbootWork(ZbootScope(zchatPreferences, pass.generation, peer), create = false) { work ->
                if (work.owner === owner) {
                    work.evidence = work.evidence?.let { it.copy(workers = it.workers - pass.token) }
                }
            }
        }
    }

    private suspend fun finishZbootHistoryPass(pass: ZbootHistoryPass, complete: Boolean): Boolean {
        if (!complete) return false
        if (pass.owners.isEmpty() && pass.mined.isEmpty()) return pass.generation == zchatPreferences.walletScopeGeneration()
        val revisions =
            pass.owners.mapValues { (peer, owner) ->
                withZbootWork(ZbootScope(zchatPreferences, pass.generation, peer), create = false) {
                    if (it.owner === owner) it.evidence?.revision else null
                }
            }
        val current = deriveOurNostrIdentity()
        var ready = current != null
        for ((peer, owner) in pass.owners) {
            val scope = ZbootScope(zchatPreferences, pass.generation, peer)
            val settled =
                withZbootWork(scope, create = false) { work ->
                    if (work.owner !== owner) return@withZbootWork true
                    val evidence = work.evidence ?: return@withZbootWork true
                    val remaining = evidence.copy(workers = evidence.workers - pass.token)
                    work.evidence = remaining
                    if (current == null ||
                        current.rotation != zchatPreferences.getNostrRotationIndex() ||
                        evidence.revision != revisions[peer] ||
                        remaining.workers.isNotEmpty()
                    ) {
                        return@withZbootWork false
                    }
                    val minedCurrent = current.publicKey in remaining.identities
                    if (minedCurrent) {
                        work.frames
                            .filter { it.owner === owner && !it.handedOff && !it.reconnectTap }
                            .forEach { it.mined = it.mined + current.publicKey }
                    }
                    // Reconcile previously failed writes even if rotation made the latest identity OLD-only.
                    // Another successful modePrefs commit may persist them, but live getters are not that proof.
                    var removalSaved = true
                    if (minedCurrent || remaining.removalPending) {
                        removalSaved = withdrawOwnedZbootQuote(scope, work)
                        work.evidence = requireNotNull(work.evidence).copy(removalPending = !removalSaved)
                    }
                    var markerSaved = confirmPendingZbootMarker(scope, work)
                    // ZC-773: the mined CURRENT identity ends as the marker, also over an older one the restore rule set
                    // first. An older marker that could not be replaced is tried again from the kept evidence.
                    val marker = zchatPreferences.getSentNostrBootPubkey(peer)
                    if (markerSaved && minedCurrent && marker != current.publicKey) {
                        markerSaved = zchatPreferences.setSentNostrBootPubkey(peer, current.publicKey)
                        if (!markerSaved && marker == null) {
                            val pending = requireNotNull(work.evidence)
                            work.evidence = pending.copy(markerPending = current.publicKey, revision = pending.revision + 1)
                        }
                    }
                    if (!removalSaved || !markerSaved) return@withZbootWork false
                    work.evidence = null
                    true
                }
            if (settled != true) ready = false
        }
        // ZC-773: a complete pass that read a mined ZBOOT of our CURRENT relay identity for a contact leaves that
        // identity as the delivered one, also for a contact with nothing owed (not enrolled above) and also over an older
        // marker: rows are read oldest first, so the restore rule records the earlier identity, and a later send under the
        // standing consent would pay again for the current one. Not for a confirmed Reset or Reconnect: its ZBOOT is sent
        // again on purpose. Senders of the contact that have not handed off stop as delivered. A marker the store did not
        // save keeps this proof with the contact, so its senders wait and the next complete pass writes it again.
        if (current != null) {
            for ((peer, identities) in pass.mined) {
                if (current.publicKey !in identities) continue
                val scope = ZbootScope(zchatPreferences, pass.generation, peer)
                val saved =
                    withZbootWork(scope) { work ->
                        if (work.owner.protectedSession) return@withZbootWork true
                        if (current.rotation != zchatPreferences.getNostrRotationIndex()) return@withZbootWork false
                        // ZC-792: not the sender of a Reconnect tap.
                        work.frames.filter { !it.handedOff && !it.reconnectTap }.forEach { it.mined = it.mined + current.publicKey }
                        // ZC-789: the ZBOOT a question counted for this contact needs no payment, so its allowance goes, by
                        // the sender's own rule (ZC-536): not while its owed mark stands (the enrolled contact above), and
                        // not while the action that wrote it is still at its key exchange.
                        if (!zchatPreferences.isZbootOwed(peer) && !quotedActionAtItsKex(peer)) withdrawOwnedZbootQuote(scope, work)
                        if (zchatPreferences.getSentNostrBootPubkey(peer) == current.publicKey ||
                            zchatPreferences.setSentNostrBootPubkey(peer, current.publicKey)
                        ) {
                            return@withZbootWork true
                        }
                        val evidence = work.evidence ?: ZbootEvidence()
                        work.evidence =
                            evidence.copy(identities = evidence.identities + current.publicKey, revision = evidence.revision + 1)
                        false
                    }
                if (saved != true) ready = false
            }
        }
        // A pass belongs to the wallet whose stores were live when it began. One that touched no contact above (every row
        // it read carries an older identity) has not compared the generation yet: it is ready only for the same wallet.
        return ready && pass.generation == zchatPreferences.walletScopeGeneration()
    }

    /**
     * ZC-536 — the allowance of a quoted ZBOOT never outlives the action that quoted it: when the ZBOOT it counted needs
     * no payment (our identity is already recorded as delivered, or it was paid within the hour), or a Reset's key
     * exchange settles because the contact's own key exchange completed it (no key reply follows), the allowance is
     * withdrawn. The store removes the owed mark of ZC-534 with it. A withdrawal only lowers what can be spent.
     */
    private fun settleQuotedAllowance(peerAddress: String) {
        if (zchatPreferences.isZbootQuoted(peerAddress) && withdrawZbootQuote(peerAddress)) {
            Log.d("ZCHAT_NOSTR", "Quoted ZBOOT allowance for ${peerAddress.take(16)}… withdrawn: its ZBOOT needs no payment")
        }
    }

    /**
     * ZC-590 — withdraw the quoted-ZBOOT allowance of [peerAddress]. A withdrawal the store did not save is remembered
     * for this process ([unsavedZbootWithdrawals]): the allowance then pays nothing ([zbootQuoteStands]) and the
     * withdrawal is written again at every later look, until it is saved. @return whether nothing is left on disk.
     */
    private fun withdrawZbootQuote(peerAddress: String): Boolean {
        // ZC-785 (d): a withdrawal the store did not save is written again although the live value already reads "not
        // quoted" (a failed commit can change it), as [withdrawOwnedZbootQuote] does: the allowance may still be on disk.
        if (!zchatPreferences.isZbootQuoted(peerAddress) && !unsavedZbootWithdrawals.contains(peerAddress)) return true
        return if (zchatPreferences.setZbootQuoted(peerAddress, false)) {
            unsavedZbootWithdrawals.remove(peerAddress)
            true
        } else {
            unsavedZbootWithdrawals.add(peerAddress)
            Log.e("KEX", "Withdrawing a quoted ZBOOT was not saved: nothing is paid on it, and it is withdrawn again later")
            false
        }
    }

    /**
     * ZC-590 — whether a confirmed question's allowance for our ZBOOT to [peerAddress] may be spent: it is on disk
     * ([ZchatPreferences.isZbootQuoted]) and was not withdrawn. A withdrawal the store did not save is tried again here.
     */
    private fun zbootQuoteStands(peerAddress: String): Boolean {
        if (unsavedZbootWithdrawals.contains(peerAddress)) {
            withdrawZbootQuote(peerAddress)
            return false
        }
        return zchatPreferences.isZbootQuoted(peerAddress)
    }

    /**
     * ZC-590 — write the quoted-ZBOOT allowance a confirmed question gives [peerAddress]. A new confirmed question
     * replaces an earlier withdrawal that was never saved. @return whether the allowance reached the disk.
     *
     * ZC-1390 (money-path rule 2): [account] is the account that confirmed the question (accountKeyOf); it is written
     * first, with the allowance, and only that account pays the ZBOOT ([zbootAllowanceIsOf]). An account that could not
     * be read (null) leaves no owner, as an earlier test build's allowance.
     */
    private fun recordZbootQuote(
        peerAddress: String,
        account: String?,
        protectedSession: Boolean = false,
        scope: ZbootScope = zbootScope(peerAddress),
        finishGrant: () -> Boolean = { true },
    ): Boolean =
        withZbootWork(scope) { work ->
            val wasQuoted = zchatPreferences.isZbootQuoted(peerAddress)
            val saved =
                zchatPreferences.setZbootQuotedAccount(peerAddress, account) &&
                    zchatPreferences.setZbootQuoted(peerAddress, true) &&
                    finishGrant()
            if (saved) {
                work.owner = ZbootOwner(zbootGrantOrder.incrementAndGet(), protectedSession)
                work.evidence = null
                unsavedZbootWithdrawals.remove(peerAddress)
            } else if (!wasQuoted) {
                // This grant never became an owner; undo only while holding the same peer decision.
                if (!zchatPreferences.setZbootQuoted(peerAddress, false)) unsavedZbootWithdrawals.add(peerAddress)
            }
            saved
        } == true

    /**
     * Deliver OUR NOSTR identity to [peerAddress] via a compact signed ZBOOT (~200 bytes), the
     * SECOND leg of the Tunnel handshake (the first being the KEX that delivers our E2E key + address).
     *
     * WHY a separate ZBOOT instead of piggybacking the NOSTR pubkey on the KEX: a first-contact KEX
     * already carries our full u1 address (~213 B) so a recipient with no convId mapping can recover +
     * verify us — that plus pubkey+signature is ~481 B, leaving NO room for the NOSTR pubkey+relay
     * (~95 B) under the 512-byte memo cap (measured: address+NOSTR = ~575 B → MemoTooLong → the whole
     * send fails). So [buildKEXWire] deliberately DROPS the NOSTR fields whenever the address is
     * present, and the NOSTR identity must travel in its own memo. The ZBOOT is convId-routed (no
     * address needed) so it fits easily and is verified against the peer's KEX-established E2E key.
     *
     * SEQUENCING (single-note rule — one shielded spend per block): this MUST NOT be sent in the same
     * pass as a KEX/KEXACK, or the two on-chain txs race for the one spendable Orchard note and one
     * fails ("No Orchard input found"). Callers invoke it only AFTER the E2E exchange is established —
     * the initiator on KEXACK-receipt, the responder via [routeIncomingBoot]'s auto-reply on receiving
     * the initiator's ZBOOT — so each handler emits exactly one tx.
     *
     * Idempotent per (peer, our-NOSTR-identity): we record the pubkey we sent and skip a resend of the
     * SAME identity (prevents on-chain drain + a ZBOOT ping-pong), but a rotated identity (different
     * pubkey) is re-delivered. A failed send re-arms by clearing the marker.
     */
    private fun sendNostrBootHandshake(peerAddress: String) {
        // ZC-1272: a ZBOOT a confirmed question covered is paid on that answer, not asked about again.
        val rule = if (zbootQuoteStands(peerAddress)) ZbootOnChainRule.QUOTED_IN_SHIELDED else ZbootOnChainRule.STANDING_CONSENT
        sendNostrBootHandshake(peerAddress, rule)
    }

    /**
     * Round 10b R10B-1 (F-R9C-1) — when an automatic ZBOOT that cannot go over the relays may be paid on-chain.
     */
    private enum class ZbootOnChainRule {
        /** Under the standing handshake consent: a Call tap, Reconnect, a rotation, a Tunnel chat's bootstrap. */
        STANDING_CONSENT,

        /**
         * The KEXACK and reply-ZBOOT triggers. Outside a Shielded chat as [STANDING_CONSENT] (the consent says it covers
         * Tunnel chats). In a Shielded chat only against the per-contact allowance a confirmed first-message question
         * wrote when it quoted this ZBOOT ([ZchatPreferences.isZbootQuoted]); the ZBOOT that pays consumes it. Without
         * it nothing is paid and nothing is asked: the marker is re-armed as on a failed send, and a later trigger
         * delivers the ZBOOT free once the peer's relay key is known.
         *
         * T3b-1: outside a Shielded chat an allowance a confirmed question left (a mode switch that quoted our ZBOOT) is
         * spent first, as in a Shielded chat, so that question is not followed by the automatic-setup one; with no
         * allowance the standing consent decides, as before.
         */
        QUOTED_IN_SHIELDED,

        /**
         * T3b-1 — a confirmed mode switch whose quote did not count our ZBOOT: it goes over the relays or not at all. A
         * relay that cannot be reached, or does not acknowledge it, pays nothing on-chain; the marker is re-armed.
         */
        RELAY_ONLY,

        /**
         * F8 (ZC-112) — the Retry of the "Key exchange not sent" notice for a ZBOOT that never reached the chain. Over the
         * relays first, as always (free; an acknowledged copy deletes the failed entry). Otherwise on-chain against the
         * quote the user confirmed for that failed state, never under the standing consent and never against the
         * per-contact allowance: it neither uses the allowance up nor puts it back as owed. Every correctness guard stays
         * (our own address, the key the ZBOOT is signed with, a mined identity, the unread history, Keystone); only the
         * guards that stop an automatic second payment are skipped (the delivered-identity return, the paid record of
         * the last hour). A failure re-arms nothing.
         */
        USER_RETRY,
    }

    /** Round 10b R10B-1 — [ZbootOnChainRule.QUOTED_IN_SHIELDED] as the counts see it: may our ZBOOT to [peer] go on-chain. */
    private fun zbootMayPayOnChain(peer: String): Boolean =
        zchatPreferences.getConversationMode(peer) != co.electriccoin.zcash.ui.screen.chat.model.ConversationMode.VAULT ||
            zbootQuoteStands(peer)

    /**
     * Round 10b R10B-1 (F-R9C-5) — how many handshake transactions Accept on [peerAddress]'s chat request can lead to: our
     * KEXACK, plus our ZBOOT when it may go on-chain ([zbootMayPayOnChain]). The count the Allow question uses for the
     * same contact ([automaticSetupTransactions]), so the banner and the question say the same.
     */
    fun chatRequestAcceptTransactions(peerAddress: String): Int =
        automaticSetupTransactions(
            listOf(QueuedAutomaticSetup(AutomaticSetupKind.KEXACK, peerAddress)),
            emptyList(),
            ::zbootMayPayOnChain,
        )

    /**
     * ZC-534 — [resumeOwed] is set only by the per-block retry ([retryPendingTunnelZboots]) for a contact whose quoted
     * ZBOOT is marked owed: while that mark and its allowance both stand, the delivered-identity marker is known to be
     * stale (the attempt that set it provably sent nothing and was then cut off while it waited), so the "already
     * delivered" return is skipped. Everything after it is the same sender: the claim, the relay-first order, the
     * guard's re-read before every attempt, and the stamp that uses up the allowance (and with it the mark) first.
     */
    private fun sendNostrBootHandshake(
        peerAddress: String,
        rule: ZbootOnChainRule,
        resumeOwed: Boolean = false,
        // F8: the marker of the NOT_SENT entry a [ZbootOnChainRule.USER_RETRY] was confirmed for; null for every other rule.
        retryOf: Long? = null,
        // F8: completed with what the sender did when it delivered or attempted something; left open when it did not.
        result: CompletableDeferred<MemoSendOutcome>? = null,
    ): kotlinx.coroutines.Job? {
        // ZC-534: the process-wide scope, not this screen's (as the owed KEX, ZC-285): leaving the chat while the ZBOOT
        // waits for a block never cancels it with its delivered-identity marker already set.
        // Register before launch, but leave the in-flight claim inside the coroutine (including never-started jobs).
        val frame = registerZbootFrame(peerAddress, rule, resumeOwed) ?: return null
        return sendNostrBootHandshake(peerAddress, rule, resumeOwed, frame, retryOf, result)
    }

    private fun sendNostrBootHandshake(
        peerAddress: String,
        rule: ZbootOnChainRule,
        resumeOwed: Boolean,
        frame: ZbootFrame,
        retryOf: Long? = null,
        result: CompletableDeferred<MemoSendOutcome>? = null,
        // ZC-1235: a true-price question's answer; null is the one handshake, held for the next chat open when above it.
        payment: OwnSetupPayment? = null,
        // ZC-1473: told when a relay took it (before [result]), and what an on-chain attempt paid.
        onRelay: (() -> Unit)? = null,
        priceSink: co.electriccoin.zcash.ui.screen.chat.usecase.ProposalPriceSink? = null,
    ): kotlinx.coroutines.Job {
        // F8: a Retry is a Retry of one failed state; without it the rule pays nothing.
        val userRetry = rule == ZbootOnChainRule.USER_RETRY
        val job =
            try {
                processSendScope().launch(Dispatchers.Main.immediate) {
                    // Atomic claim taken INSIDE the coroutine (mirrors retryKexAckIfResponder): if a ZBOOT send to
                    // this peer is already in flight, bail so the N concurrent inbound-handler invocations don't
                    // each launch a duplicate on-chain send (single-note contention / transient-failure storm).
                    // Claiming here (not before launch) is CRITICAL now that the set is process-wide (companion):
                    // a never-started launch (a scope cancelled before the coroutine ran) would otherwise leak the
                    // claim PERMANENTLY and wedge every future ZBOOT for this peer until app restart. Paired with the
                    // finally-remove below.
                    if (!nostrBootInFlight.add(peerAddress)) {
                        Log.d("ZCHAT_NOSTR", "ZBOOT send already in flight for ${peerAddress.take(16)}… — skipping duplicate")
                        return@launch
                    }
                    try {
                        // ZC-739: nothing goes to a contact whose new key waits for the user: not over the relays, not
                        // on-chain. Nothing is written or withdrawn (the frame has no identity yet, so its end re-arms
                        // nothing); the decision starts the held ZBOOT again ([resumeAfterKeyDecision]).
                        if (zchatPreferences.isE2EKeyChanged(peerAddress)) {
                            Log.d("ZCHAT_NOSTR", "ZBOOT to ${peerAddress.take(16)}… held: the contact's new key waits for the user")
                            return@launch
                        }
                        // ZC-1352: over the relays neither. Nothing is written, as above.
                        if (zchatPreferences.isAutomaticSetupWithdrawn(peerAddress)) return@launch
                        // ZC-1390 (money-path rule 2): a ZBOOT whose allowance another account's question wrote is not sent by
                        // the account selected now, by any trigger (a block, a chat open, Reconnect, the contact's key
                        // answer). Nothing is written; the allowance and its owed mark stay for the account that confirmed it.
                        // The notice's Retry is paid on its own quote.
                        val selectedKey = selectedAccountOrNull()?.let(GetDefaultUnifiedAddressUseCase::accountKeyOf)
                        if (!userRetry && zbootAllowanceOfAnother(peerAddress, selectedKey)) {
                            Log.d("ZCHAT_NOSTR", "ZBOOT to ${peerAddress.take(16)}… held: another account confirmed its question")
                            return@launch
                        }
                        // T2-extra (a), rule (E): never a ZBOOT to one of our own addresses, over the relays or on-chain. Nothing is
                        // sent, nothing is asked, and a quoted-ZBOOT allowance for that address is dropped.
                        if (zchatPreferences.isSelfAddress(peerAddress)) {
                            withdrawFrameZbootQuote(frame)
                            Log.w("ZCHAT_NOSTR", "ZBOOT to one of our own addresses dropped — nothing sent")
                            return@launch
                        }
                        // The peer must hold our E2E key already (so they can VERIFY this signed ZBOOT); if not,
                        // there's nothing to authenticate against yet — bail and let the KEX round-trip finish.
                        val ourPriv = zchatPreferences.getE2EPrivateKey(peerAddress) ?: return@launch
                        if (zchatPreferences.getE2EPeerPublicKey(peerAddress) == null) return@launch
                        val identity = deriveOurNostrIdentity() ?: return@launch
                        if (withZbootFrame(frame) {
                                if (identity.rotation != zchatPreferences.getNostrRotationIndex()) {
                                    false
                                } else {
                                    frame.identity = identity.publicKey
                                    zchatPreferences.registerOwnNostrPubkey(identity.publicKey)
                                    true
                                }
                            } != true
                        ) {
                            return@launch
                        }
                        val ourNostrPub = identity.publicKey
                        val ourRelay = identity.relay
                        if (zbootDisposition(frame) == ZbootDisposition.MINED) {
                            finishZbootFrame(frame, rearm = false)
                            return@launch
                        }
                        // Idempotency / ping-pong guard: already delivered THIS identity → nothing to do.
                        // ZC-534: unless the block retry resumes a quoted ZBOOT marked owed (the marker is then stale). Both the
                        // mark and its allowance are re-read here, inside the claim.
                        val resumesOwed =
                            resumeOwed && zchatPreferences.isZbootOwed(peerAddress) && frameZbootQuoteStands(frame)
                        // F8: not for the notice's Retry either: the marker stands for a ZBOOT that never reached the chain.
                        if (userRetry && retryOf == null) return@launch
                        if (!resumesOwed && !userRetry && zchatPreferences.getSentNostrBootPubkey(peerAddress) == ourNostrPub) {
                            // ZC-536 (a): the ZBOOT an allowance counted needs no payment, so the allowance goes. Not while the
                            // mark of ZC-534 says the marker is stale (the block retry pays that ZBOOT), and not while the
                            // action that wrote the allowance is still at its key exchange (a Reset before its wipe, a
                            // reconnect before its KEX is out): the marker it reads is then the earlier exchange's.
                            if (!zchatPreferences.isZbootOwed(peerAddress) && !quotedActionAtItsKex(peerAddress)) {
                                withZbootFrame(frame) { withdrawOwnedZbootQuote(frame.scope, it) }
                            }
                            return@launch
                        }
                        val ourAddress = _currentUserAddress.value ?: return@launch
                        // R4-4 (1): through the per-message call, so an id this control creates is marked "INIT not sent" like
                        // one a message creates (R2-6 c, R3-2 1). A control carries no user message; the first message after it
                        // must still be the v4 INIT naming our address, never a REPLY the recipient cannot place. An existing
                        // id is returned unchanged.
                        val conversation =
                            convIdMutex.withLock {
                                withZbootFrame(frame) { zchatPreferences.getOrCreateConversationIdForMessage(peerAddress) }
                            } ?: return@launch
                        val (convId, _) = conversation

                        // Stamp our CURRENT NOSTR rotation index as the ZBOOT epoch (#225 hardening). It increments
                        // on every key rotation, so the recipient adopts this ZBOOT only if its epoch ≥ the highest
                        // it has already adopted for us — a re-scanned/replayed OLDER ZBOOT can never downgrade our
                        // live pubkey. The epoch is inside [signedData], so it can't be tampered with in transit.
                        val epoch = zchatPreferences.getNostrRotationIndex().toLong()
                        val bootMemo = zbootMemoFor(convId, ourPriv, ourNostrPub, ourRelay, epoch)

                        // Mark BEFORE the async send resolves so a rapid double-trigger can't double-charge;
                        // a failed send clears it so a genuine failure re-arms the next trigger.
                        // R5-2: and only a marker the store CONFIRMED may be delivered against. A marker lost to a
                        // kill lets the next trigger pay for the same identity again, so nothing is sent at all when
                        // the write is not confirmed; the marker is re-armed by definition (nothing was written).
                        if (withZbootFrame(frame) {
                                if (ourNostrPub in frame.mined) false else zchatPreferences.setSentNostrBootPubkey(peerAddress, ourNostrPub)
                            } != true
                        ) {
                            finishZbootFrame(frame, rearm = false)
                            Log.e("ZCHAT_NOSTR", "ZBOOT not sent: its delivered-identity marker could not be written")
                            return@launch
                        }

                        // FREE-FIRST DELIVERY (#256 asymmetric-handshake fix). If we ALREADY hold the peer's NOSTR
                        // pubkey (we scanned their contact code, or a prior inbound bound it), deliver this SAME
                        // E2E-signed v3 ZBOOT over NOSTR — free, no Orchard note — instead of on-chain. This is what
                        // closes the one-way / asymmetric handshake the user hit: the on-chain leg-2 ZBOOT can NEVER
                        // land on a 0-ZEC wallet ("Insufficient balance (have 0)"), so the scanned peer never learns
                        // our NOSTR key → Open/calls stay one-way forever. The relay path needs no funds and no
                        // spendable note, and we already know where to send (peer pubkey known). ONLY the transport
                        // changes: the recipient verifies the IDENTICAL signed ZBOOT via routeIncomingBoot with every
                        // MITM / v4-downgrade / epoch-replay guard intact (no new bind site, no relaxed gate). This
                        // mirrors the proven free-NOSTR delivery in announceRotationOverNostr. On-chain stays the
                        // fallback for when the peer's NOSTR pubkey is NOT yet known (can't route over the relay).
                        val peerNostrPub = zchatPreferences.getPeerNostrPubkey(peerAddress)
                        // T1b-1 §2: no relay delivery of our identity while a Keystone account is selected; the on-chain path
                        // below meets the Keystone rule of the automatic setups (nothing sent, the marker re-armed).
                        if (peerNostrPub != null && NostrChatBridge.isOutboundReady() && !keystoneAccountSelected()) {
                            // ZC-420: the mark before the publish: a kill during it, or during the on-chain wait after it, leaves
                            // a mark beside the marker set above, and the repair delivers this identity over the relays (ZC-736).
                            NostrChatBridge.beginRelayCopy(RelayCopySlots.identity(peerAddress), extra = ourNostrPub)
                            // ZC-393: a free-first relay copy: any readable relay is enough here, so ZC-393's stricter count never
                            // starts an on-chain spend (residual R-1).
                            val published =
                                runCatching {
                                    co.electriccoin.zcash.ui.nostr.NostrChatBridge
                                        .publish(bootMemo, peerNostrPub)
                                }.getOrNull()
                            val acks = published?.readableAcks ?: 0
                            if (acks > 0) {
                                // T3b fixup: a question that counted this ZBOOT on-chain is not needed any more; its allowance is
                                // withdrawn, so it can never pay a later ZBOOT that no question counted.
                                withdrawFrameZbootQuote(frame)
                                // F8: delivered by another route: a failed on-chain attempt of this identity needs no
                                // Retry any more (its NOT_SENT entry goes; a LIVE or MINED one is the chain's to settle).
                                runCatching {
                                    sendAttempts?.ledger?.settleDelivered(
                                        SendAttemptLedgerRules.key(SendAttemptKind.ZBOOT, peerAddress, ourNostrPub),
                                    )
                                }
                                onRelay?.invoke()
                                result?.complete(MemoSendOutcome.SENT)
                                Log.d(
                                    "ZCHAT_NOSTR",
                                    "Delivered ZBOOT (NOSTR identity) to ${peerAddress.take(16)}… over NOSTR (free, $acks ack)",
                                )
                                // ZC-420: a relay every version reads took it, so the mark goes; only a public one, so the mark
                                // names this copy and the repair delivers it again for free.
                                NostrChatBridge.noteRelayCopy(RelayCopySlots.identity(peerAddress), published, extra = ourNostrPub)
                                return@launch // marker already set above — our identity is delivered
                            }
                            Log.w("ZCHAT_NOSTR", "NOSTR ZBOOT publish 0-ack for ${peerAddress.take(16)}… — falling back to on-chain")
                        }

                        // Round 10b R10B-1 (F-R9C-1): a spend never exceeds its quote. In a Shielded chat the KEXACK and reply
                        // triggers pay an on-chain ZBOOT only against the allowance of a confirmed question that quoted it; a
                        // 0-ack relay publish above does not fall back to an unquoted on-chain ZBOOT either.
                        // T3b-1: a confirmed switch whose quote did not count this ZBOOT never pays it on-chain.
                        if (openNeverSpends(peerAddress)) {
                            finishZbootFrame(frame, rearm = true)
                            return@launch
                        }
                        if (rule == ZbootOnChainRule.RELAY_ONLY) {
                            finishZbootFrame(frame, rearm = true)
                            Log.d(
                                "ZCHAT_NOSTR",
                                "ZBOOT to ${peerAddress.take(16)}… not paid on-chain: the switch did not quote it — re-armed",
                            )
                            return@launch
                        }
                        val shielded =
                            zchatPreferences.getConversationMode(peerAddress) ==
                                co.electriccoin.zcash.ui.screen.chat.model.ConversationMode.VAULT
                        // T3b-1: outside a Shielded chat, the allowance a confirmed question left is spent before the standing consent.
                        val spendsQuote =
                            rule == ZbootOnChainRule.QUOTED_IN_SHIELDED &&
                                (frame.quoteRequired || shielded || frameZbootQuoteStands(frame))
                        if (spendsQuote && !frameZbootQuoteStands(frame)) {
                            finishZbootFrame(frame, rearm = true)
                            Log.d(
                                "ZCHAT_NOSTR",
                                "ZBOOT to ${peerAddress.take(16)}… not paid on-chain: unquoted in a Shielded chat — re-armed",
                            )
                            return@launch
                        }

                        // P2b: before EVERY paid on-chain attempt, including one after a block wait, re-read what
                        // makes this ZBOOT unnecessary or not yet payable:
                        // - a DIFFERENT identity is now recorded as delivered (a rotation announced it meanwhile), or a
                        //   Reset replaced the E2E key this ZBOOT is signed with: it is stale, send nothing;
                        // - a ZBOOT for this same identity was paid within the cooldown (Reconnect re-arms the marker);
                        // - the history has not been read yet in this process (after a restore the markers are empty
                        //   and the scan records the ZBOOTs the old phone paid for): defer, re-arm, no prompt.
                        val paid = PaidSetupRecord(AutomaticSetupKind.ZBOOT, peerAddress, ourNostrPub)
                        // T3b fixup: an allowance a question left is used up by whichever trigger pays this ZBOOT (a chat open under
                        // the standing consent too), so it never outlives the ZBOOT it counted.
                        // F8: the notice's Retry is paid on its own quote: it neither uses the allowance up nor restores it.
                        val usesAllowance = !userRetry && (spendsQuote || frameZbootQuoteStands(frame))
                        // ZC-536 (b): whether THIS attempt's stamp stands (it used up the allowance and may have paid).
                        var stamped = false
                        // ZC-1432: the account the used allowance named, read just before the stamp uses it up (which drops
                        // it), so an unstamp that puts the allowance back puts it back for that account and no other.
                        var allowanceOwner: String? = null
                        val marker =
                            HandshakeMarkerGuard(
                                alreadyDelivered = {
                                    zbootDisposition(frame) == ZbootDisposition.MINED ||
                                        zchatPreferences.getSentNostrBootPubkey(peerAddress).let { it != null && it != ourNostrPub } ||
                                        zchatPreferences.getE2EPrivateKey(peerAddress) != ourPriv ||
                                        // F8: the hour rule stops an automatic second payment; the Retry was quoted for this one.
                                        (!userRetry && paid.paidRecently())
                                },
                                stamp = {
                                    // R10B-1: checked allowance consumption remains FIRST, before marker/paid stamp/submit.
                                    // ZC-1390: an account switch during a block wait stops it (the account list's selection).
                                    val selectedNow = selectedAccountNow()?.let(GetDefaultUnifiedAddressUseCase::accountKeyOf)
                                    (
                                        withZbootFrame(frame) { work ->
                                            // ZC-1432: the allowance's account is read here, before it is used up; ZC-1433: an account that cannot be read is not the allowance's account (it pays nothing).
                                            allowanceOwner = zchatPreferences.getZbootQuotedAccount(peerAddress).takeIf { usesAllowance }
                                            ourNostrPub !in frame.mined &&
                                                work.evidence == null &&
                                                (!usesAllowance || zbootAllowanceIsOf(peerAddress, selectedNow)) &&
                                                (!usesAllowance || zchatPreferences.setZbootQuoted(peerAddress, false)) &&
                                                zchatPreferences.setSentNostrBootPubkey(peerAddress, ourNostrPub) &&
                                                paid.stamp()
                                        } == true
                                    ).also { stamped = it }
                                },
                                unstamp = {
                                    stamped = false
                                    val own =
                                        withZbootFrame(frame) {
                                            // Existing definitive nothing-sent proof, including strict nothingStored rejection.
                                            // A mined pre-handoff abort clears only its own identity/timestamp-matching stamp.
                                            if (ourNostrPub !in frame.mined) {
                                                frame.handedOff = false
                                                paid.unstamp()
                                                // ZC-1132: an Open chat pays no ZBOOT (openNeverSpends), so nothing that pays one is
                                                // written back while it is Open; the used allowance stays used.
                                                if (usesAllowance &&
                                                    !openNeverSpends(peerAddress) &&
                                                    !zchatPreferences.restoreQuotedZbootAsOwed(peerAddress, allowanceOwner)
                                                ) {
                                                    Log.w("ZCHAT_NOSTR", "ZBOOT allowance and owed restoration was not saved")
                                                }
                                            } else if (!frame.handedOff) {
                                                paid.unstamp()
                                            }
                                        }
                                    // ZC-785 (c): a sender whose action a confirmed Reset or reconnect replaced still withdraws
                                    // its own paid record (matched by identity and time) by the same rule; left behind, it makes
                                    // the new action's ZBOOT read "paid within the hour" and lose its allowance. The allowance on
                                    // disk is the new action's and is not touched here.
                                    if (own == null && (ourNostrPub !in frame.mined || !frame.handedOff)) paid.unstamp()
                                },
                                deferred = {
                                    !processHistoryRead.get() || withZbootFrame(frame) { it.evidence != null } != false
                                },
                            )
                        // R10B-1: the confirmed question is the consent for a quoted ZBOOT (as R9-2's owed KEX), re-read before
                        // every attempt; the standing consent decides every other one.
                        val zbootKey = SendAttemptLedgerRules.key(SendAttemptKind.ZBOOT, peerAddress, ourNostrPub)
                        val confirmedByQuote: (() -> Boolean)? =
                            when {
                                // F8: the Retry's consent is its quote, which stands only for the failed state it was shown for.
                                userRetry -> retryOf?.let { s -> { handshakeQuoteStands(zbootKey, s) } }
                                payment?.stands != null -> payment.stands
                                spendsQuote -> ({ frameZbootQuoteStands(frame) })
                                else -> null
                            }
                        val outcome =
                            withContext(priceSink ?: kotlin.coroutines.EmptyCoroutineContext) {
                                sendAutomaticHandshakeMemoOutcome(
                                    peerAddress,
                                    ourAddress,
                                    bootMemo,
                                    AutomaticSetupKind.ZBOOT,
                                    marker,
                                    confirmedByQuote = confirmedByQuote,
                                    beforeSubmit = {
                                        if (withZbootFrame(frame) { work ->
                                                if (ourNostrPub in frame.mined || work.evidence != null) {
                                                    false
                                                } else {
                                                    frame.handedOff = true
                                                    true
                                                }
                                            } != true
                                        ) {
                                            throw ZbootPreSubmitRefused()
                                        }
                                    },
                                    // F8: only an on-chain ZBOOT has an entry (a relay delivery has none).
                                    attempt = SendAttemptTag(SendAttemptKind.ZBOOT, peerAddress, ourNostrPub, retryOf = retryOf),
                                    kexAnswer = ownSetupAttempt(peerAddress, zboot = true, payment),
                                )
                            }
                        result?.complete(outcome)
                        when {
                            // F8: an earlier on-chain ZBOOT of this identity is unresolved or waits for Retry. Nothing was
                            // stamped or paid: no re-arm, no allowance change (the marker holds this identity, which is
                            // the truth while that entry stands).
                            outcome == MemoSendOutcome.PENDING -> {
                                finishZbootFrame(frame, rearm = false)
                                Log.d("ZCHAT_NOSTR", "ZBOOT to ${peerAddress.take(16)}… waits: an earlier attempt of this identity stands")
                            }
                            outcome == MemoSendOutcome.SENT || zbootDisposition(frame) == ZbootDisposition.MINED -> {
                                // ZC-536 (b): the funnel answered "already delivered" without this attempt stamping (a ZBOOT for this
                                // identity was paid within the hour, or a newer identity is recorded as delivered): the allowance
                                // that counted this ZBOOT goes. Not when a Reset replaced the key meanwhile: the allowance on disk
                                // is then that Reset's, for the ZBOOT after its own key exchange.
                                if (!stamped &&
                                    zbootDisposition(frame) == ZbootDisposition.ACTIVE &&
                                    zchatPreferences.getE2EPrivateKey(peerAddress) == ourPriv
                                ) {
                                    withZbootFrame(frame) { withdrawOwnedZbootQuote(frame.scope, it) }
                                }
                                // F8: a Retry that went out leaves no allowance for a ZBOOT that needs no payment any more (as a
                                // relay delivery does); it never spends or restores one.
                                if (userRetry && outcome == MemoSendOutcome.SENT) withdrawFrameZbootQuote(frame)
                                finishZbootFrame(frame, rearm = false)
                                Log.d("ZCHAT_NOSTR", "Sent ZBOOT (NOSTR identity) to ${peerAddress.take(16)}… on $ourRelay")
                            }
                            else -> {
                                // Re-arm on failure — only our own stamp, never a newer identity another path recorded.
                                // F8: a failed Retry re-arms nothing.
                                finishZbootFrame(frame, rearm = !userRetry)
                                Log.w("ZCHAT_NOSTR", "ZBOOT (NOSTR identity) not sent for ${peerAddress.take(16)}… — re-armed")
                            }
                        }
                    } catch (e: Exception) {
                        // Re-arm the sent-marker so the block-driven retry (retryPendingTunnelZboots) re-fires —
                        // but NEVER on cancellation, which can arrive after the tx was already broadcast; re-arming
                        // there re-sends and re-charges. Rethrow first so the marker is left exactly as it is.
                        if (!mayReArmHandshakeMarker(e)) throw e
                        finishZbootFrame(frame, rearm = !userRetry)
                        Log.w("ZCHAT_NOSTR", "ZBOOT (NOSTR identity) send failed: ${e.message}")
                    } finally {
                        // F8: every exit of a Retry keeps a mined identity's marker and re-arms nothing.
                        if (userRetry) finishZbootFrame(frame, rearm = false)
                        nostrBootInFlight.remove(peerAddress)
                        removeZbootFrame(frame)
                    }
                }
            } catch (e: Throwable) {
                removeZbootFrame(frame)
                throw e
            }
        job.invokeOnCompletion { removeZbootFrame(frame) }
        return job
    }

    /** What the block-aware memo retry loop does before each attempt ([sendMemoWithBlockRetry]). */
    private enum class MemoAttemptGate {
        /** Build and submit this attempt. */
        PROCEED,

        /** Send nothing and report "not sent"; the caller re-arms its marker. */
        STOP,

        /** Another attempt already delivered this memo: send nothing and report it as sent. */
        ALREADY_DELIVERED,
    }

    /**
     * The durable "already sent" marker of one automatic handshake leg, re-read by the retry loop before
     * every attempt: [alreadyDelivered] says another attempt has paid for it, [stamp] records it just
     * before an attempt submits, and [unstamp] withdraws this attempt's stamp when the attempt provably
     * sent nothing (a "still confirming" shortfall) before the loop waits for a block.
     *
     * R4-1: [stamp] returns whether the DURABLE part of the marker reached the disk. A marker that was not
     * written cannot stop a restart paying the same leg again, so the attempt sends nothing on false.
     */
    private class HandshakeMarkerGuard(
        val alreadyDelivered: () -> Boolean,
        val stamp: () -> Boolean,
        val unstamp: () -> Unit,
        /** P2b — true while this leg must not pay yet (nothing is sent; the caller re-arms, no prompt). */
        val deferred: () -> Boolean = { false },
    )

    /**
     * Submit an AUTOMATIC handshake memo (KEX / KEXACK / ZBOOT / GROUP_ACCEPT, and the on-chain
     * GROUP_KEY_REQUEST grant): one no user gesture asked for. Block-aware retry as in [sendMemoWithBlockRetry], and before EVERY attempt, not just the first:
     *
     * - MONEY SAFETY: the handshake-spend consent is checked. Each of these costs a carrier output plus a
     *   ZIP 317 fee, and nothing on screen would otherwise say a transaction had been paid for. While the
     *   wallet is stranded they fail and re-arm, so they queue and flush together the moment funds land —
     *   17,000 zatoshi went out that way on 2026-09-07. Ask once, then never get in the way again. HS-4:
     *   consent revoked while an attempt waits for a block (Move Old Balance clears it) stops the retry.
     * - When [marker] is given, its durable state is re-read, so a leg queued behind a block wait never
     *   pays for what another attempt already delivered or what is no longer needed (P2b: KEX, ZBOOT and
     *   KEXACK all pass one).
     *
     * [kind] names the setup for the consent prompt's total (HS-6).
     *
     * User-initiated sends (the time-lock senders) use [sendUserMemoWithBlockRetry] and never reach the
     * consent decision.
     *
     * R4-1 — the outcome tells a failure which paid nothing from one that may follow a stored transaction. Putting the
     * second kind back in a queue pays for it twice.
     *
     * GPT-6 F5 — [scope] separates two setups of the same [kind] towards the same [destination] (the group id
     * for a group action), so the consent prompt quotes each of them.
     *
     * C5 — [beforeSubmit] runs right before an attempt is handed to the SDK (see [sendMemoWithBlockRetry]).
     *
     * F8 (ZC-112) — the Boolean form of this function is gone: every caller reads the outcome with an exhaustive
     * `when`, so [MemoSendOutcome.PENDING] can never pass as "sent" or as "not sent". [attempt] is the memo's
     * send-attempt tag ([sendMemoWithBlockRetry]).
     * @return what the send did; callers re-arm only on an outcome that sent nothing, and change nothing on PENDING.
     */
    private suspend fun sendAutomaticHandshakeMemoOutcome(
        destination: String,
        sender: String,
        memo: String,
        kind: AutomaticSetupKind,
        marker: HandshakeMarkerGuard? = null,
        scope: String? = null,
        beforeSubmit: (() -> Unit)? = null,
        confirmedByQuote: (() -> Boolean)? = null,
        attempt: SendAttemptTag? = null,
        // ZC-1230, ZC-1233: what only a key-exchange answer brings.
        kexAnswer: KexAnswerAttempt? = null,
    ): MemoSendOutcome {
        val setup = QueuedAutomaticSetup(kind, destination, scope)
        return sendMemoWithBlockRetry(
            destination = destination,
            sender = sender,
            memo = memo,
            beforeAttempt = {
                kexAnswer?.onAttemptStarting?.invoke()
                when {
                    // ZC-880: direct-chat handshakes stop before quotes, consent and stamps. Groups keep their rules.
                    // ZC-1096: out of the queue only; a stored "Not now" mark stays (a declined setup stays declined).
                    kind in OPEN_NEVER_SPENDS_KINDS && openNeverSpends(destination) -> {
                        AutomaticSetupQueue.stoppedInOpenChat(setup)
                        MemoAttemptGate.STOP
                    }
                    // T2-extra (a), rule (E): no automatic setup is ever paid to one of our own addresses, and no
                    // question is asked for one. Nothing is sent; the caller re-arms as for any unsent attempt.
                    zchatPreferences.isSelfAddress(destination) -> {
                        AutomaticSetupQueue.done(setup, zchatPreferences)
                        Log.w("KEX", "$kind to one of our own addresses not sent")
                        MemoAttemptGate.STOP
                    }
                    // ZC-739-R1: read again before EVERY attempt, a block wait included: a direct-chat set-up that passed
                    // its sender's test before the contact's new key arrived pays nothing while that key waits for the
                    // user. Stopped before any stamp, so the caller re-arms its marker; an allowance or owed mark stays.
                    kind in OPEN_NEVER_SPENDS_KINDS && zchatPreferences.isE2EKeyChanged(destination) -> {
                        Log.d("KEX", "$kind to ${destination.redactAddress()} held: the contact's new key waits for the user")
                        MemoAttemptGate.STOP
                    }
                    // ZC-1352: read before every attempt: a run waiting for a block when the user deleted the row stops here.
                    kind in SETUP_KINDS_A_DELETED_ROW_WITHDRAWS && zchatPreferences.isAutomaticSetupWithdrawn(destination) -> {
                        Log.d("KEX", "$kind to ${destination.redactAddress()} withdrawn: the user deleted the first message it was for")
                        MemoAttemptGate.STOP
                    }
                    marker?.alreadyDelivered?.invoke() == true -> {
                        AutomaticSetupQueue.done(setup, zchatPreferences)
                        MemoAttemptGate.ALREADY_DELIVERED
                    }
                    marker?.deferred?.invoke() == true -> MemoAttemptGate.STOP
                    // R2-2 (a): no automatic key-exchange leg is paid towards a stranger whose chat request
                    // the user has not accepted (no consent prompt either: Accept is the question).
                    // ZC-693: except the answer to the key the user accepted in this process.
                    kind in STRANGER_HELD_KINDS &&
                        zchatPreferences.getInboundKexAwaitingAccept(destination).let { held ->
                            held != null && !(kind == AutomaticSetupKind.KEXACK && acceptedChatRequests[destination] == held)
                        } ->
                        MemoAttemptGate.STOP
                    // Round 10b R10B-1: a leg a confirmed question quoted is paid on that answer while it stands, and
                    // never under the standing consent once it is gone.
                    confirmedByQuote != null && !confirmedByQuote() -> MemoAttemptGate.STOP
                    confirmedByQuote == null && !automaticHandshakeSpendAllowed(setup) -> MemoAttemptGate.STOP
                    // R4-1: the durable marker goes down BEFORE the submit, and only a marker the store
                    // confirmed may be paid against. Without it a restart inside the cooldown pays this leg
                    // a second time, so nothing is sent and the caller re-arms as for any unsent attempt.
                    marker != null && !marker.stamp() -> {
                        Log.e("KEX", "$kind not paid: its durable paid marker could not be written")
                        MemoAttemptGate.STOP
                    }
                    else -> {
                        AutomaticSetupQueue.done(setup, zchatPreferences)
                        MemoAttemptGate.PROCEED
                    }
                }
            },
            afterNothingSent = { marker?.unstamp?.invoke() },
            beforeSubmit = beforeSubmit,
            onFailure = { e ->
                if (e is UserFacingSendRefusal && e.message == ChatSendCopy.STORAGE_PAUSED_PAID_STEP) kexAnswer?.onLedgerRefusal?.invoke()
                kexAnswer?.onAttemptFailed?.invoke(e)
            },
            attempt = attempt,
            kexAnswerPrice = kexAnswer?.price,
            onBlockWait = kexAnswer?.onBlockWait,
        )
    }

    /**
     * P2b — the paid-setup record guard for a KEX or ZBOOT that carries [identity] to [peer]: a record for
     * the same identity younger than the cooldown means it is already paid for; [stamp] writes one just
     * before an attempt submits and [unstamp] removes exactly that one when the attempt provably sent nothing.
     */
    private inner class PaidSetupRecord(
        kind: AutomaticSetupKind,
        peer: String,
        private val identity: String,
    ) {
        private val slot = HandshakePaidRecord.slot(kind, peer)

        @Volatile private var stampedAt: Long? = null

        fun paidRecently(): Boolean =
            HandshakePaidRecord.remainingCooldown(
                zchatPreferences.getHandshakePaidRecord(slot),
                identity,
                System.currentTimeMillis(),
            ) > 0L

        /** R4-1 — @return whether the record reached the disk. Only a written record may be paid against. */
        fun stamp(): Boolean {
            val now = System.currentTimeMillis()
            val saved = zchatPreferences.setHandshakePaidRecord(slot, HandshakePaidRecord.encode(identity, now))
            // Nothing to withdraw when nothing was written; a later unstamp must not remove another writer's record.
            stampedAt = if (saved) now else null
            return saved
        }

        fun unstamp() {
            val at = stampedAt ?: return
            stampedAt = null
            if (HandshakePaidRecord.isRecord(zchatPreferences.getHandshakePaidRecord(slot), identity, at)) {
                zchatPreferences.setHandshakePaidRecord(slot, null)
            }
        }
    }

    /** Milliseconds before a KEX / ZBOOT carrying [identity] to [peer] may be paid again (0 = now). */
    private fun paidSetupCooldown(
        kind: AutomaticSetupKind,
        peer: String,
        identity: String?,
    ): Long =
        if (identity == null) {
            0L
        } else {
            HandshakePaidRecord.remainingCooldown(
                zchatPreferences.getHandshakePaidRecord(HandshakePaidRecord.slot(kind, peer)),
                identity,
                System.currentTimeMillis(),
            )
        }

    /**
     * Submit a USER-INITIATED on-chain memo (the scheduled / block-locked / payment-locked / conditional
     * senders) with the same block-aware retry, but WITHOUT the automatic-handshake consent gate: the
     * user's tap is the consent. HS-7: routed through the automatic gate, a user who had never granted
     * handshake consent got nothing sent and a false "add ZEC" error in place of the consent prompt.
     */
    private suspend fun sendUserMemoWithBlockRetry(destination: String, sender: String, memo: String): Boolean =
        sendUserMemoOutcomeWithBlockRetry(destination, sender, memo).sent

    /** Round 8 D8 — [sendUserMemoWithBlockRetry] with its whole outcome, for callers that must tell MAY_HAVE_BEEN_SENT apart. */
    private suspend fun sendUserMemoOutcomeWithBlockRetry(
        destination: String,
        sender: String,
        memo: String,
        // ZC-283: the caller's durable "may have been sent" stamp. [beforeSubmit] runs right before an attempt is handed
        // to the SDK (if it throws, that attempt is not submitted and nothing is sent); [afterNothingSent] runs when an
        // attempt provably sent nothing. Both are [sendMemoWithBlockRetry]'s own hooks.
        beforeSubmit: (() -> Unit)? = null,
        afterNothingSent: () -> Unit = {},
        // F8: the memo's send-attempt tag (a locked message: note-only, fail-open).
        attempt: SendAttemptTag? = null,
    ): MemoSendOutcome =
        sendMemoWithBlockRetry(
            destination = destination,
            sender = sender,
            memo = memo,
            // ZC-1054-R2: read again before every attempt, a block wait included: a status copy or a scheduled message
            // whose contact's new key arrived meanwhile pays nothing while that key waits for the user.
            beforeAttempt = {
                if (zchatPreferences.isE2EKeyChanged(destination)) {
                    Log.d("ZCHAT_SEND", "User memo to ${destination.redactAddress()} held: the contact's new key waits")
                    MemoAttemptGate.STOP
                } else {
                    MemoAttemptGate.PROCEED
                }
            },
            afterNothingSent = afterNothingSent,
            beforeSubmit = beforeSubmit,
            attempt = attempt,
        )

    /**
     * F8 (ZC-112) — the send-attempt tag of a scheduled, block-locked, payment-locked or conditional message: the contact
     * and a hash of the memo (never its text). Note-only: if the chain proves it never went out, one note says so; nothing
     * is stored of the message and nothing re-sends it.
     */
    private fun lockedMessageTag(
        peerAddress: String,
        memo: String,
    ): SendAttemptTag = SendAttemptTag(SendAttemptKind.TIME_LOCK, peerAddress, memoHash(memo))

    /** F8: a short SHA-256 of [memo], the identity of a memo's send attempt (no memo text is kept). */
    private fun memoHash(memo: String): String =
        java.security.MessageDigest
            .getInstance("SHA-256")
            .digest(memo.toByteArray(Charsets.UTF_8))
            .take(MEMO_HASH_BYTES)
            .joinToString("") { "%02x".format(it) }

    /**
     * Round 8 D8 — what a scheduled, block-locked, payment-locked or conditional message send tells the user. A send
     * the SDK may have stored (MAY_HAVE_BEEN_SENT) is never reported as "not sent": sending it again could pay twice.
     * A proven NOTHING_SENT (a "still confirming" wait that ran out of blocks, a shortfall, or a refusal before the
     * submit) says so; it used to promise "it'll go through once that settles", which nothing does.
     */
    private fun reportLockedMessageOutcome(outcome: MemoSendOutcome) {
        when (outcome) {
            MemoSendOutcome.SENT -> Unit
            // F8: the same memo sent again while its first attempt is unresolved: nothing was built; it may be on its way.
            MemoSendOutcome.MAY_HAVE_BEEN_SENT, MemoSendOutcome.PENDING ->
                _sendMessageState.value = SendMessageState.Error(SubmitAttemptProof.MAY_HAVE_BEEN_SENT)
            MemoSendOutcome.NOTHING_SENT -> _sendMessageState.value = SendMessageState.Error(ChatSendCopy.LOCKED_MESSAGE_NOT_SENT)
        }
    }

    /**
     * The one handshake-spend consent decision for an automatic handshake. On "ask first" it raises the
     * consent prompt and returns false; callers re-arm their sent-marker, so the handshake resumes once
     * consent is given.
     *
     * HS-6: the prompt quotes every paid transaction the queued setups can spend ([automaticSetupTransactions]
     * over the blocked setups and the Tunnel peers whose ZBOOT is due), and after "Not now" it is not raised
     * again while every queued setup is one the user already declined.
     */
    private suspend fun automaticHandshakeSpendAllowed(setup: QueuedAutomaticSetup): Boolean {
        // Round 8 P1 (PHONE_TRIAGE F3): a group join is never paid under the standing consent, and never queued or
        // quoted by its question. A reply that cannot go free waits for Join (joinGroupInvite), which is its question.
        if (setup.kind == AutomaticSetupKind.GROUP_ACCEPT) return false
        // ZC1013-X1: a setup the user answered "Not now" to before turning the standing consent on in Advanced Settings is
        // not covered by it: it asks as before (and only about the setups held so), and is paid only on Allow.
        val underConsent = zchatPreferences.hasConsentedToHandshakeSpend()
        if (underConsent && !AutomaticSetupQueue.asksUnderConsent(setup, zchatPreferences)) return true
        // C5: after a phrase change the setups another wallet queued (and its answers) are dropped before this
        // question counts them. While both sets are empty there is nothing to drop.
        if (queuedAutomaticSetups.isNotEmpty() || dismissedAutomaticSetups.isNotEmpty()) {
            withHeldAcceptsLock { heldGroupAcceptsWallet() }
        }
        if (setup.kind.retried) queuedAutomaticSetups += setup
        // M3 (ZC-110): the selected account is read once, for the Keystone branch and for the funds gate below.
        val account = selectedAccountOrNull()
        // Round 8 D4 (round 7c C5): the send chokepoint refuses every automatic send on a Keystone account (ZC-102), so
        // Allow could never pay any of these. No question; a one-time explanation instead. Every setup stays queued
        // or held as before, and the question comes back once the software account is selected again.
        if (isKeystoneForAutomaticSends(account)) {
            if (keystoneAutomaticSetupExplained.compareAndSet(false, true)) {
                Log.w("KEX", "Automatic chat setup not asked about: a Keystone account is selected — nothing sent")
                _sendMessageState.value = SendMessageState.Error(ChatSendCopy.KEYSTONE_AUTOMATIC_SETUP)
            }
            return false
        }
        // M3 (ZC-110, KI-96): a wallet that cannot pay one handshake is not asked. Its Allow would be a standing consent
        // given while nothing could be paid, and the queued setups would be paid the moment ZEC arrives, with no second
        // question. The setup stays queued (not declined), nothing is shown or sent, and the caller re-arms as for any
        // unsent attempt; the block tick asks once the Ironwood funds are spendable ([raiseHandshakeQuestionWhenFunded]).
        // An account that cannot be read is asked as before: the question is the user's control.
        if (handshakeWalletCanPayOne(account) == false) {
            if (unfundedSetupWaitLogged.add(setup)) {
                Log.i("KEX", "${setup.kind} kept queued: the wallet cannot pay one handshake yet — not asking, nothing sent")
            }
            return false
        }
        unfundedSetupWaitLogged.remove(setup)
        // Round 8 P1: no group join is counted or quoted (Round 8 D4 / REVIEW_7C F13 counted only live ones); an Allow
        // never pays one.
        val asking =
            (queuedAutomaticSetups + setup).filterTo(mutableSetOf()) {
                it.kind != AutomaticSetupKind.GROUP_ACCEPT &&
                    (it.kind !in OPEN_NEVER_SPENDS_KINDS || !openNeverSpends(it.target)) &&
                    (!underConsent || AutomaticSetupQueue.asksUnderConsent(it, zchatPreferences))
            }
        // Round 10b R10B-1 (F-R9C-5): a peer's ZBOOT is counted only where it may go on-chain. ZC1013-X1: under the
        // standing consent a due ZBOOT is paid without the question, so it is not part of this one.
        val due = if (underConsent) emptySet() else zbootDuePeers()
        val transactions = automaticSetupTransactions(asking, due, ::zbootMayPayOnChain)
        when (val decision = decideHandshakeSpend(consentGranted = false, pendingPeers = transactions)) {
            is HandshakeSpendDecision.NeedsConsent -> {
                Log.w("KEX", "Automatic handshake needs spend consent (${decision.pendingPeers} transaction(s)) — not sending")
                if (!dismissedAutomaticSetups.containsAll(asking)) {
                    _sendMessageState.value =
                        // Round 8 P1: groupJoins stays 0 (R6-4's group-join line is no longer produced).
                        SendMessageState.NeedsHandshakeSpendConsent(
                            pendingPeers = decision.pendingPeers,
                            estimatedCost = decision.estimatedCost,
                        )
                }
            }

            HandshakeSpendDecision.Allowed -> Unit
        }
        return false
    }

    /**
     * Round 8 D4 (round 7c C5) — whether the selected account is a Keystone hardware wallet, read as
     * [heldGroupAcceptWalletRefusal] reads it. An account that cannot be read, or is not loaded within
     * [KEYSTONE_CHECK_TIMEOUT_MS] (the read waits for one), is not treated as Keystone: the question is asked as before,
     * and the chokepoint reads the account again before anything is sent.
     */
    private suspend fun keystoneAccountSelected(): Boolean = isKeystoneForAutomaticSends(selectedAccountOrNull())

    /** M3 (ZC-110) — [keystoneAccountSelected] for an account already read: no automatic send can be signed on it. */
    private fun isKeystoneForAutomaticSends(account: WalletAccount?): Boolean =
        !KeystoneAvailability.CHAT_SIGNING && account is KeystoneAccount

    /**
     * M3 (ZC-110, KI-96) — whether [account] can pay one automatic handshake now: what can pay another person
     * ([WalletAccount.peerSpendableBalance], confirmed Ironwood) is at least one one-memo transaction
     * ([onChainSendMinimumCost], 17,000 zatoshi). Null when the account could not be read: the caller then asks as before.
     * A value check: many small notes that add up to the floor still pass (residual R-M3-1, as before this check).
     */
    private fun handshakeWalletCanPayOne(account: WalletAccount?): Boolean? =
        account?.let {
            // ZC-1417: exactly the floor, or the floor plus a change the SDK accepts.
            spendableCovers(it.peerSpendableBalance.value, onChainSendMinimumCost().value)
        }

    /**
     * M3 (ZC-110, KI-96) — the block tick's half of the funds gate in [automaticHandshakeSpendAllowed]: setups queued
     * while the wallet could not pay one handshake are asked about once its Ironwood funds are spendable. It raises
     * "Allow handshake transactions?" with the count and quote the gate itself would raise, and only when all hold: the
     * consent is not given; the queue holds a setup (never a group join) the user has not declined; this screen shows
     * nothing else (Idle: never over another question or notice); no Keystone account is selected; the selected account
     * is readable and can pay one. It never sends, never writes the consent and never adds to or answers the queue (it
     * only drops another wallet's setups, as the gate does, C5): Allow and "Not now" answer it as any other raise.
     */
    private fun raiseHandshakeQuestionWhenFunded() {
        if (queuedAutomaticSetups.isEmpty()) return
        viewModelScope.launch {
            try {
                if (_sendMessageState.value != SendMessageState.Idle) return@launch
                if (zchatPreferences.hasConsentedToHandshakeSpend()) return@launch
                // C5: another wallet's queued setups (after a phrase change) are dropped before they are counted.
                withHeldAcceptsLock { heldGroupAcceptsWallet() }
                val account = selectedAccountOrNull()
                if (isKeystoneForAutomaticSends(account) || handshakeWalletCanPayOne(account) != true) return@launch
                // The account read may have waited: the answer may have come meanwhile.
                if (zchatPreferences.hasConsentedToHandshakeSpend()) return@launch
                val asking =
                    queuedAutomaticSetups.filterTo(mutableSetOf()) {
                        it.kind != AutomaticSetupKind.GROUP_ACCEPT &&
                            (it.kind !in OPEN_NEVER_SPENDS_KINDS || !openNeverSpends(it.target))
                    }
                if (asking.isEmpty() || dismissedAutomaticSetups.containsAll(asking)) return@launch
                val transactions = automaticSetupTransactions(asking, zbootDuePeers(), ::zbootMayPayOnChain)
                val decision = decideHandshakeSpend(consentGranted = false, pendingPeers = transactions)
                if (decision !is HandshakeSpendDecision.NeedsConsent) return@launch
                val question =
                    SendMessageState.NeedsHandshakeSpendConsent(
                        pendingPeers = decision.pendingPeers,
                        estimatedCost = decision.estimatedCost,
                    )
                if (_sendMessageState.compareAndSet(SendMessageState.Idle, question)) {
                    unfundedSetupWaitLogged.removeAll(asking)
                    Log.w("KEX", "Automatic handshake needs spend consent (${decision.pendingPeers} transaction(s)): funds spendable now")
                }
            } catch (e: Exception) {
                if (e is kotlinx.coroutines.CancellationException) throw e
                Log.w("KEX", "Funded-wallet handshake question not raised: ${e.javaClass.simpleName}")
            }
        }
    }

    /** T1b-1 — the selected account as [keystoneAccountSelected] reads it (waits up to [KEYSTONE_CHECK_TIMEOUT_MS]), or null. */
    private suspend fun selectedAccountOrNull(): WalletAccount? =
        try {
            kotlinx.coroutines.withTimeoutOrNull(KEYSTONE_CHECK_TIMEOUT_MS) {
                accountDataSource.getSelectedAccount()
            }
        } catch (e: Exception) {
            if (e is kotlinx.coroutines.CancellationException) throw e
            null
        }

    /**
     * T1b-1 — the selected account as the account list holds it right now (a synchronous read of the StateFlow the
     * Wallet-tab chip switches), or null when it is not known yet. For the entry points that are not suspend.
     */
    private fun selectedAccountNow(): WalletAccount? =
        try {
            accountDataSource.allAccounts.value?.firstOrNull { it.isSelected }
        } catch (e: Exception) {
            Log.w("ZCHAT_SEND", "Selected account not read: ${e.javaClass.simpleName}")
            null
        }

    /**
     * T1b-1 §2 (K0 §4) — the chat is closed while a Keystone account is selected: on EVERY transport, the free relay
     * routes included, not only at the on-chain chokepoint. Checked first by every user-started chat action, before
     * anything is stored or published. An account that is not known yet is not treated as Keystone (the chokepoint and
     * the suspend checks still read it).
     */
    private fun chatClosedForSelectedAccount(): Boolean =
        !KeystoneAvailability.CHAT_SIGNING && selectedAccountNow() is KeystoneAccount

    /** T1b-1 §2 — [chatClosedForSelectedAccount] said no: show why and log it. Nothing was stored or sent. */
    private fun refuseClosedChat(what: String) {
        Log.w("ZCHAT_SEND", "K0/T1b-1: $what refused — a Keystone account is selected; nothing stored, sent or paid")
        _sendMessageState.value = SendMessageState.Error(ChatSendCopy.KEYSTONE_CHATS_CLOSED)
    }

    /**
     * T1b-1 §2 — the chat identity to put in an outgoing message: [_currentUserAddress] while it belongs to the selected
     * account. A ChatViewModel that outlives an account switch holds the other account's identity; then the selected
     * account's saved identity is taken instead when the store has one, else null (the caller sends no identity) and a
     * refresh is started. Unknown account or unknown holder: as before.
     */
    private fun chatIdentityForSelectedAccount(): String? {
        val held = _currentUserAddress.value
        val heldKey = identityAccountKey ?: return held
        val selected = selectedAccountNow() ?: return held
        val selectedKey = GetDefaultUnifiedAddressUseCase.accountKeyOf(selected)
        if (selectedKey == heldKey) return held
        val saved = runCatching { zchatPreferences.pinnedIdentity(selectedKey) }.getOrNull()
        if (saved != null) {
            _currentUserAddress.value = saved
            identityAccountKey = selectedKey
            return saved
        }
        refreshChatIdentity()
        return null
    }

    /** T1b-1 §2 — [chatIdentityForSelectedAccount] for a suspend caller: a stale identity is re-read before it returns. */
    private suspend fun currentChatIdentity(): String? {
        chatIdentityForSelectedAccount()?.let { return it }
        return loadChatIdentity()
    }

    /** T1b-1 §2 — re-read the chat identity of the selected account (an account switch). */
    private fun refreshChatIdentity() {
        viewModelScope.launch { loadChatIdentity() }
    }

    /**
     * T1b-1 §2 — read the selected account once and set its chat identity and [identityAccountKey] from it. Also
     * registers it as one of our own addresses. Null when it cannot be read.
     */
    private suspend fun loadChatIdentity(): String? =
        try {
            val account = accountDataSource.getSelectedAccount()
            val address = getDefaultUnifiedAddress.forAccount(account)
            _currentUserAddress.value = address
            identityAccountKey = GetDefaultUnifiedAddressUseCase.accountKeyOf(account)
            zchatPreferences.registerSelfAddress(address)
            address
        } catch (e: Exception) {
            if (e is kotlinx.coroutines.CancellationException) throw e
            Log.w("ZCHAT_SEND", "Chat identity not re-read: ${e.javaClass.simpleName}")
            null
        }

    /**
     * Submit a raw memo, retrying ONLY on the TRANSIENT "funds still confirming" insufficient-funds error.
     * The single-note rule (one shielded spend per block) makes back-to-back sends — and crucially a send
     * right after the PEER's inbound message momentarily locks our note — fail with transient insufficient
     * funds even when our confirmed balance is ample. Left un-retried, that silently drops a KEXACK/ZBOOT
     * and STALLS the whole handshake (seen live: Honor's KEXACK failed the instant Seeker's KEX landed and
     * locked the note, nothing retried → Seeker never got Honor's E2E key → tunnel stuck). We wait for the
     * next block (the locking tx confirms / our change matures) and retry, up to [MAX_HANDSHAKE_RETRIES]. A
     * GENUINE shortfall ("add ZEC", no "confirm on-chain" marker) is NOT retried — waiting can't fix it.
     *
     * [beforeAttempt] runs before every attempt, including each one after a block wait. [afterNothingSent]
     * runs when an attempt failed with the transient shortfall (nothing was broadcast), before the wait.
     * Never call this directly: use [sendAutomaticHandshakeMemo] or [sendUserMemoWithBlockRetry] (R9-2: or [payOwedKex],
     * the KEX the user confirmed in the first-message quote, with the same durable paid record as every KEX).
     *
     * C5 — [beforeSubmit] runs right before an attempt is handed to the SDK, after everything that can refuse it
     * without storing a transaction. If it throws, that attempt is not submitted and counts as nothing sent.
     * R9-2 — [onFailure] is told every attempt's error (not a cancellation), the last one being why nothing was sent.
     * @return [MemoSendOutcome.SENT] if the memo was submitted (or [beforeAttempt] said it was already
     * delivered); otherwise whether the failure proves nothing was sent.
     */
    private suspend fun sendMemoWithBlockRetry(
        destination: String,
        sender: String,
        memo: String,
        beforeAttempt: suspend () -> MemoAttemptGate,
        afterNothingSent: () -> Unit,
        beforeSubmit: (() -> Unit)? = null,
        onFailure: ((Exception) -> Unit)? = null,
        // SR-A: the exact price this memo was quoted at (an owed KEX inside a quoted attachment send).
        sendQuote: ChatSendQuote? = null,
        // F8 (ZC-112): what this memo is in the send-attempt ledger; null (or no ledger) records nothing, as before F8.
        attempt: SendAttemptTag? = null,
        // ZC-1233: a key-exchange answer's price.
        kexAnswerPrice: KexAnswerPrice? = null,
        // ZC-1338: what a wait for a block tells the user.
        onBlockWait: (() -> Unit)? = null,
    ): MemoSendOutcome {
        var attemptNumber = 0
        while (true) {
            // F8 step 0: the gate, before the caller's own gate, before any stamp and before any proposal. It only
            // reads. An earlier attempt of this key that is unresolved, mined and not yet deep, or proven not sent and
            // waiting for the user's tap answers PENDING: nothing is built, stamped or paid, and the caller changes
            // nothing. A ledger that cannot be read sends nothing (the note-only kinds go on without it).
            val capture = attempt?.let { tag -> sendAttempts?.let { LedgerCapture(it, tag) } }
            if (capture != null) {
                when (capture.gate()) {
                    LedgerGateAnswer.PROCEED -> Unit
                    LedgerGateAnswer.PENDING -> return MemoSendOutcome.PENDING
                    LedgerGateAnswer.UNREADABLE -> {
                        onFailure?.invoke(UserFacingSendRefusal(ChatSendCopy.STORAGE_PAUSED_PAID_STEP))
                        return MemoSendOutcome.NOTHING_SENT
                    }
                }
            }
            when (beforeAttempt()) {
                MemoAttemptGate.STOP -> return MemoSendOutcome.NOTHING_SENT
                MemoAttemptGate.ALREADY_DELIVERED -> {
                    Log.d("KEX", "Memo already delivered by another attempt — not sending again")
                    return MemoSendOutcome.SENT
                }
                MemoAttemptGate.PROCEED -> Unit
            }
            // ZC-121: the caller's stamp for THIS attempt stands from here until it is withdrawn.
            var stamped = true
            // C1: set by the use case right before it asks the SDK to store and broadcast THIS attempt.
            var submitStarted = false
            try {
                createChunkedMessageProposal(
                    destinationAddress = destination,
                    senderAddress = sender,
                    message = memo,
                    isFirstMessage = false,
                    amountPerOutput = Zatoshi(1000L),
                    directSubmit = true,
                    skipNavigation = true,
                    rawMemo = true,
                    onSubmitStarting = {
                        // C5: the caller's last step first; the submit counts as started only once it succeeded.
                        beforeSubmit?.invoke()
                        // F8 step 1: the attempt is in the ledger before the SDK is asked. A throw here is before the
                        // submit, so nothing was sent.
                        capture?.begin()
                        submitStarted = true
                        // Debug fault seam: the process dies with the attempt's entry written and nothing created.
                        capture?.killSeam()
                    },
                    // F8 step 2 (F2): the ids are committed after the SDK stored every transaction and before the first
                    // submit; a throw there submits nothing.
                    onTransactionsStored = capture?.let { c -> { stored -> c.stored(stored) } },
                    sendQuote = sendQuote,
                    kexAnswerPrice = kexAnswerPrice,
                )
                // F8: stored, but its ids could not be recorded, so nothing was submitted: nothing is reported as sent.
                return if (capture?.idsCommitFailed == true) MemoSendOutcome.PENDING else MemoSendOutcome.SENT
            } catch (e: Exception) {
                // Coroutine cancellation (VM teardown / scope cancel) is NOT a send failure — let it
                // propagate so callers re-arm correctly rather than logging a false "permanent failure".
                if (e is kotlinx.coroutines.CancellationException) {
                    // ZC-121: cancelled before this attempt was handed to the SDK, so nothing of it can be on the wire:
                    // its own stamp is withdrawn at once. After the hand-over the stamp stays, as before.
                    if (stamped && !submitStarted) {
                        stamped = false
                        afterNothingSent()
                    }
                    throw e
                }
                // F8: another attempt of this key appeared since the gate (or the failed state this Retry was confirmed
                // for is gone). The other attempt owns the stamp, which holds the same values: nothing is withdrawn.
                if (capture?.lostToAnother == true) return MemoSendOutcome.PENDING
                // R9-2: the caller that must report why nothing was sent (a message waiting for its KEX) keeps the error.
                onFailure?.invoke(if (capture?.writeRefused == true) UserFacingSendRefusal(ChatSendCopy.STORAGE_PAUSED_PAID_STEP) else e)
                // C1: a shortfall is only waited out before the submit; after it, a transaction may be stored.
                if (!submitStarted && isTransientInsufficientFunds(e) && attemptNumber < MAX_HANDSHAKE_RETRIES) {
                    stamped = false
                    afterNothingSent()
                    capture?.discard()
                    attemptNumber++
                    Log.w(
                        "KEX",
                        "Memo hit transient insufficient funds (note locked by a just-landed tx) — " +
                            "waiting for next block, retry $attemptNumber/$MAX_HANDSHAKE_RETRIES"
                    )
                    onBlockWait?.invoke()
                    if (!waitForNextBlock()) {
                        Log.e("KEX", "Gave up waiting for a new block — memo send failed")
                        // The last attempt was the transient shortfall: nothing was broadcast.
                        return MemoSendOutcome.NOTHING_SENT
                    }
                } else {
                    Log.e("KEX", "Memo send failed permanently", e)
                    // P2b: withdraw this attempt's stamp only when the failure proves nothing was sent (no
                    // proposal could be built, or the submit was refused before the SDK stored anything). A
                    // stored transaction may still be broadcast (P2a), so its stamp stays.
                    // C1: every refusal before the submit started proves it (sealed Orchard, Keystone, a public
                    // crossing, …); after it, only a rejection that stored nothing does.
                    val nothingSent = memoFailureProvesNothingSent(e, submitStarted)
                    if (nothingSent) {
                        stamped = false
                        afterNothingSent()
                        // F8 step 3: only a fresh entry that holds no ids goes; one with ids stays for the chain.
                        capture?.discard()
                    }
                    return if (nothingSent) MemoSendOutcome.NOTHING_SENT else MemoSendOutcome.MAY_HAVE_BEEN_SENT
                }
            } finally {
                capture?.close()
            }
        }
    }

    /** F8: what [LedgerCapture.gate] answers. */
    private enum class LedgerGateAnswer { PROCEED, PENDING, UNREADABLE }

    /**
     * F8 (ZC-112, ZC-121; SPEC §3.2) — one attempt's calls into the send-attempt ledger, for [sendMemoWithBlockRetry]
     * and for the paid timer, which calls the use case itself.
     *
     * Fail-closed kinds: [begin] and [stored] throw when the ledger does not take the write, so no transaction is
     * handed to the SDK without its entry and none is submitted without its ids. The two note-only kinds
     * ([SendAttemptKind.failClosed] false) log and go on: their entry only decides whether a note appears later.
     */
    private inner class LedgerCapture(
        private val environment: SendAttemptEnvironment,
        private val tag: SendAttemptTag,
    ) {
        private val ledger = environment.ledger
        private var seen: Long? = null
        private var claim: SendAttemptClaim? = null
        private var entered = false

        /** The ids commit failed (or lost its entry): the stored transaction was not submitted. */
        var idsCommitFailed = false
            private set

        /** [begin] found another attempt of the key (or the failed state it retries gone). */
        var lostToAnother = false
            private set

        /** [begin] could not write the entry, or no account is known: nothing was handed to the SDK. */
        var writeRefused = false
            private set

        @Suppress("TooGenericExceptionCaught")
        fun gate(): LedgerGateAnswer =
            try {
                when (val answer = ledger.gate(tag.key, tag.retryOf)) {
                    is SendAttemptGate.Proceed -> {
                        seen = answer.seen
                        LedgerGateAnswer.PROCEED
                    }
                    SendAttemptGate.Pending -> {
                        Log.d("ZCHAT_PAY", "${tag.kind} waits: an earlier attempt of this key is unresolved or waits for Retry")
                        LedgerGateAnswer.PENDING
                    }
                }
            } catch (e: Exception) {
                if (e is kotlinx.coroutines.CancellationException) throw e
                Log.e("ZCHAT_PAY", "${tag.kind}: the send-attempt ledger could not be read (${e.javaClass.simpleName})")
                if (tag.kind.failClosed) LedgerGateAnswer.UNREADABLE else LedgerGateAnswer.PROCEED
            }

        /** Step 1, right before the SDK is asked. */
        fun begin() {
            try {
                val started = nextSubmitMarker()
                val taken = ledger.begin(tag, started, knownChainTip(), SendAttemptProcess.ID, environment.accountHash(), seen)
                claim = taken
                SendAttemptProcess.enter(taken.flightId)
                entered = true
            } catch (e: AttemptAliveException) {
                if (tag.kind.failClosed) {
                    lostToAnother = true
                    throw e
                }
            } catch (e: LedgerWriteFailedException) {
                Log.e("ZCHAT_PAY", "${tag.kind}: the send attempt could not be recorded (${e.javaClass.simpleName})")
                if (tag.kind.failClosed) {
                    writeRefused = true
                    throw e
                }
            }
        }

        /**
         * The debug fault seam "kill after the marker, before create" (a release build reads it as not armed): called
         * right after [begin], once the submit counts as started.
         */
        fun killSeam() {
            FaultSeams.killHereIfArmed(FaultSeam.KILL_AFTER_MARKER_BEFORE_CREATE)
        }

        /** Step 2, after the SDK stored every transaction and before the first submit. */
        fun stored(transactions: List<co.electriccoin.zcash.ui.common.datasource.StoredTransaction>) {
            val taken = claim ?: return
            try {
                ledger.recordStored(
                    taken,
                    transactions.map { it.txId },
                    transactions.mapNotNull { t -> t.expiryHeight?.let { t.txId to it } }.toMap(),
                )
            } catch (e: LedgerWriteFailedException) {
                Log.e("ZCHAT_PAY", "${tag.kind}: the stored ids could not be recorded; nothing is submitted")
                if (tag.kind.failClosed) {
                    idsCommitFailed = true
                    throw e
                }
            }
        }

        /** Step 3: a fresh attempt that provably sent nothing leaves no entry; a retry has none of its own to remove. */
        fun discard() {
            val taken = claim ?: return
            if (taken.replaces == null) ledger.discard(taken.key, taken.startedAt)
        }

        /** The loop iteration ended, by any path; only an attempt that entered leaves. */
        fun close() {
            val taken = claim ?: return
            if (!entered) return
            entered = false
            SendAttemptProcess.leave(taken.flightId)
            ledger.finish(taken)
        }
    }

    /**
     * R4-1 — what a memo send did, for the callers that must not queue a paid transaction again.
     *
     * [SENT] and [NOTHING_SENT] are proven. [MAY_HAVE_BEEN_SENT] is a failure that can follow a transaction
     * the SDK has stored and keeps re-broadcasting (P2a), so putting such a send back in a queue — or
     * re-arming a durable "not sent yet" marker for it — pays for the same leg a second time.
     *
     * F8 (ZC-112): [PENDING] — an earlier attempt of this key is unresolved, mined and not yet deep, or proven not sent
     * and waiting for the user's tap (or this attempt was stored but its ids could not be recorded, so it was not
     * submitted). Nothing was built, stamped or paid by this call, and the caller changes NOTHING: no marker, owed
     * mark, allowance or record, no delivery-success handling, no re-arm, and no rollback of anything it wrote.
     */
    private enum class MemoSendOutcome {
        SENT,
        NOTHING_SENT,
        MAY_HAVE_BEEN_SENT,
        PENDING,
        ;

        val sent: Boolean get() = this == SENT
    }

    /**
     * #11 — try to deliver a group protocol memo over NOSTR for FREE (used for GROUP_ACCEPT, and any
     * other group memo ChatViewModel originates). Returns true only on ≥1 relay ack; false → the caller
     * falls back to the on-chain path. NOT used for KEX/ZBOOT (those MUST bootstrap on-chain — that is
     * how the NOSTR channel gets established in the first place), only for already-NOSTR-reachable group
     * peers. The receiver runs the same processGroupMessage trust gates as the on-chain path.
     */
    private suspend fun trySendGroupMemoOverNostr(peerAddress: String, memo: String): Boolean {
        // T1b-1 §2: a group memo carries our address; none goes over the relays while a Keystone account is selected
        // (the on-chain fallback meets the chokepoint's refusal).
        if (keystoneAccountSelected()) return false
        val peerPub = findPeerNostrPubkeyAnyRep(peerAddress) ?: return false
        if (!co.electriccoin.zcash.ui.nostr.NostrChatBridge.isOutboundReady()) return false
        // ZC-393: a free-first relay copy: any readable relay is enough here, so ZC-393's stricter count never
        // starts an on-chain spend (residual R-1).
        return try {
            NostrChatBridge.publish(memo, peerPub).readableAcks > 0
        } catch (e: Exception) {
            if (e is kotlinx.coroutines.CancellationException) throw e
            Log.w("ZCHAT_GROUP", "NOSTR group memo to ${peerAddress.redactAddress()} failed — on-chain fallback", e)
            false
        }
    }

    /**
     * Rep-tolerant NOSTR-pubkey lookup (#205/#214 address drift) — a peer's key may be stored under a
     * DIFFERENT unified-address representation than the (resolved) roster/recipient address. Try the
     * given address, its canonical, then every known peer rep that canonicalizes to the same peer, so a
     * drifted rep doesn't wrongly force a paid on-chain fallback for a group memo.
     */
    private fun findPeerNostrPubkeyAnyRep(address: String): String? {
        zchatPreferences.getPeerNostrPubkey(address)?.let { return it }
        val canonical = zchatPreferences.resolvePeerAddress(address)
        if (canonical != address) zchatPreferences.getPeerNostrPubkey(canonical)?.let { return it }
        return zchatPreferences.getAllConversationPeerAddresses().asSequence()
            .filter { it != address && zchatPreferences.resolvePeerAddress(it) == canonical }
            .mapNotNull { zchatPreferences.getPeerNostrPubkey(it) }
            .firstOrNull()
    }

    /**
     * SHA-256(nonce ‖ ciphertext) as a short hex id — a per-message-unique, replay-STABLE, and
     * sender-UNSTEERABLE identity for a NOSTR-delivered GROUP_MSG (which has no on-chain txId). Using
     * the encrypted content (not sender/seq) prevents a group member from crafting a colliding id to
     * suppress another member's message via the store-dedup.
     */
    private fun groupMsgContentHash(nonce: String, ciphertext: String): String =
        java.security.MessageDigest.getInstance("SHA-256")
            .digest("$nonce:$ciphertext".toByteArray(Charsets.UTF_8))
            .joinToString("") { "%02x".format(it) }
            .take(24)

    /** True only for a TRANSIENT "funds still confirming" refusal (the "…confirm on-chain…" shortfall
     *  [CreateChunkedMessageProposalUseCase] words, or — Round 8 D7 — the sealed-Orchard refusal while Ironwood
     *  is still confirming) — resolves on the next blocks. A genuine shortfall, and the "move your old balance"
     *  refusal, must NOT be retried. The one rule is [isTransientWait]. */
    private fun isTransientInsufficientFunds(throwable: Throwable): Boolean = isTransientWait(throwable)

    /** Suspend until the network block height advances (the note-locking tx confirms / our change
     *  matures), or [timeoutMs] elapses. Returns true if a new block landed. */
    private suspend fun waitForNextBlock(timeoutMs: Long = HANDSHAKE_BLOCK_WAIT_TIMEOUT_MS): Boolean {
        return try {
            val synchronizer = synchronizerProvider.getSynchronizer()
            val startHeight = synchronizer.networkHeight.value?.value
            kotlinx.coroutines.withTimeoutOrNull(timeoutMs) {
                synchronizer.networkHeight.first { h ->
                    h != null && (startHeight == null || h.value > startHeight)
                }
            } != null
        } catch (e: Exception) {
            if (e is kotlinx.coroutines.CancellationException) throw e
            false
        }
    }

    /**
     * Dispatch through [routeOutgoing] when the conversation isn't VAULT. Returns true
     * if the message was handled (i.e. the caller should NOT continue with the existing
     * shielded path).
     *
     * Strategy:
     *   - VAULT  -> false, fall through to shielded.
     *   - OPEN   -> if peer NOSTR pubkey known, publish NIP-17 + insert "sent" bubble; else
     *               fall through to shielded as a safety net.
     *   - TUNNEL -> if both sides have boot-exchanged, publish NIP-17; if not, emit a ZBOOT
     *               via the shielded path AND queue the message until the peer ZBOOT lands.
     */
    // Reply linkage that survives E2E: the quoted txid is embedded INSIDE the message body (before
    // ratchet encryption) using a control-char sentinel that can never occur in user text or a ZMSG
    // envelope, so it rides the v4 envelope unchanged (convId preserved → ratchet still resolves on
    // receive). Format: <U+0001>RPL:<quoted_txid><U+0001><original message>. A naive switch to the v3 RPL
    // envelope would drop the convId and desync the ratchet, so the ref must live in the body.
    // replyRefSentinel — declared before init {} (construction-race class). See top.
    // replyRefPrefix — declared before init {} (construction-race class). See top.

    // 2nd separator between the quoted id and the quoted-message PREVIEW text in the marker:
    // <U+0001>RPL:<id><U+001F><previewEscaped><U+0001><body>. U+001F can never occur in a
    // ChatMessage.id ([A-Za-z0-9_-]) and is escaped out of the preview, so it's an unambiguous
    // delimiter. Carrying the preview lets a NOSTR receiver (whose local ids differ) render the quote.
    // replyPreviewSep — declared before init {} (construction-race class). See top.

    private fun escapeReplyPreview(s: String): String =
        s.replace("\\", "\\\\")
            .replace("\u0001", "\\a")
            .replace("\u001f", "\\b")
            .replace('\n', ' ')
            .replace('\r', ' ')

    private fun unescapeReplyPreview(s: String): String {
        val out = StringBuilder(s.length)
        var i = 0
        while (i < s.length) {
            val c = s[i]
            if (c == '\\' && i + 1 < s.length) {
                when (s[i + 1]) {
                    '\\' -> out.append('\\')
                    'a' -> out.append('\u0001')
                    'b' -> out.append('\u001f')
                    else -> out.append(s[i + 1])
                }
                i += 2
            } else {
                out.append(c)
                i++
            }
        }
        return out.toString()
    }

    /** Wrap a reply body with the quoted-id marker AND a short preview of the quoted message. */
    private fun tagReply(replyToId: String, body: String, preview: String): String {
        val previewSeg = if (preview.isNotEmpty()) "$replyPreviewSep${escapeReplyPreview(preview)}" else ""
        return "$replyRefPrefix$replyToId$previewSeg$replyRefSentinel$body"
    }

    /**
     * Strip an embedded reply-ref. Returns (quotedId?, quotedPreview?, cleanBody). Backward compatible
     * with the legacy id-only marker (<U+0001>RPL:<id><U+0001><body>) — preview is then null.
     */
    private fun untagReply(content: String): Triple<String?, String?, String> {
        if (!content.startsWith(replyRefPrefix)) return Triple(null, null, content)
        val end = content.indexOf(replyRefSentinel, replyRefPrefix.length)
        if (end == -1) return Triple(null, null, content)
        val ref = content.substring(replyRefPrefix.length, end)
        val sepIdx = ref.indexOf(replyPreviewSep)
        val txid = if (sepIdx == -1) ref else ref.substring(0, sepIdx)
        val preview = if (sepIdx == -1) null else unescapeReplyPreview(ref.substring(sepIdx + 1))
        // A real quoted id is a ChatMessage.id: an on-chain txid (hex), or a local id like
        // "nostr-<hex>" / "pending_<n>" / "nostr-out-<n>" — i.e. always [A-Za-z0-9_-]. If the
        // extracted token contains anything else (e.g. pasted binary that happens to begin with a
        // SOH control char), this wasn't our marker — return the content unchanged rather than
        // silently consuming its head. (Must NOT hex-only-validate: that would reject the very
        // common "nostr-…"/"pending_…" reply targets and leak the raw marker as text.)
        if (txid.isEmpty() || !txid.all { it.isLetterOrDigit() || it == '-' || it == '_' }) {
            return Triple(null, null, content)
        }
        return Triple(txid, preview, content.substring(end + 1))
    }

    /**
     * The funds pre-checks of an on-chain message, in the order sendMessage runs them; SR-A's Shielded attachment runs
     * the same ones before its price question. Null: go on. Otherwise the dialog to show; nothing was stored or sent.
     *
     * Messaging needs value in a shielded pool of the Orchard protocol. Since NU6.3 that means Ironwood OR Orchard:
     * reading Orchard alone falsely blocked every migrated wallet that still held a little transparent or Sapling dust,
     * and offered it a "shield your funds" dialog that could not help — its funds were already shielded, just in the
     * other pool.
     */
    private fun shieldedFundsRefusal(): SendMessageState? {
        val currentState = _chatListState.value as? ChatListState.Success ?: return null
        val privacyStatus = currentState.privacyStatus
        // Shielded, but stranded: every satoshi is in sealed Orchard and none in Ironwood. The chokepoint would refuse
        // this anyway (OrchardSealedException); catching it here first gives the user the explanation dialog instead of
        // an error toast. Round 8 D7 (sweep #10, #12): not when the only thing confirming is our own change (the wallet
        // still holds some Orchard and its only Ironwood note is locked by its own send). That resolves in a few blocks
        // with nothing for the user to do: the send goes on, the chokepoint refuses it before anything is stored
        // (OrchardSealedException with Ironwood pending), and doSendMessage queues it for the next block like any other
        // send that waits for funds to confirm. Nothing can be paid from Orchard on the way.
        if (privacyStatus.isOrchardStranded && !privacyStatus.isWaitingForOwnChange) {
            return SendMessageState.NeedsIronwoodMigration(
                orchardBalance = privacyStatus.orchardBalance,
                // Stranded means nothing in Ironwood is spendable, so its whole total is pending.
                ironwoodPending = privacyStatus.ironwoodBalance,
                ironwoodChangePending = privacyStatus.ironwoodChangePending,
                confirmationProgress = privacyStatus.confirmationProgress,
            )
        }
        val shieldedForMessaging = privacyStatus.ironwoodBalance + privacyStatus.orchardBalance
        if (shieldedForMessaging <= Zatoshi(0) &&
            (privacyStatus.saplingBalance > Zatoshi(0) || privacyStatus.transparentBalance > Zatoshi(0))
        ) {
            return SendMessageState.NeedsOrchardShielding(
                saplingBalance = privacyStatus.saplingBalance,
                transparentBalance = privacyStatus.transparentBalance
            )
        }
        return null
    }

    /**
     * TOFU / MITM gate shared by every user-initiated send entrypoint. If the peer's identity key
     * changed since we last trusted it, surfaces a blocking error and returns true so the caller can
     * abort BEFORE encrypting/transmitting to a possibly attacker-substituted key. The user clears
     * the flag by acknowledging the "Security key changed" banner (dismissE2EKeyChanged). This must
     * run before transport routing so TUNNEL/OPEN (NOSTR) sends are gated too, not just VAULT.
     */
    private fun blockedByKeyChange(peerAddress: String): Boolean {
        if (zchatPreferences.isE2EKeyChanged(peerAddress)) {
            // Round 8 D8: the banner has no OK button; its × accepts the new key. In the phone's language.
            _sendMessageState.value = SendMessageState.Error(ChatSendCopy.KEY_CHANGED_VERIFY)
            // ZC-250: the short cue is a toast; the refusal also stays on screen (the key-changed banner, expanded with
            // chat_key_changed_send_refused) until the user collapses it or the flag clears. Nothing was sent or paid.
            keyChangeRefusalHolder().value = peerAddress
            return true
        }
        return false
    }

    /**
     * ZC-250 — the contact whose send the key-change gate ([blockedByKeyChange]) refused, or null. The chat screen keeps
     * that contact's key-changed banner expanded with the refusal notice while this names it. Cleared when the flag
     * clears ([dismissE2EKeyChanged]'s accepting branch, a Reset encryption, a verified ZBOOT) or by
     * [acknowledgeKeyChangeRefusal]. In memory only: the flag itself, which keeps the gate shut, is unchanged.
     */
    val keyChangeRefusal: StateFlow<String?>
        get() = keyChangeRefusalHolder()

    /** ZC-250 — the user collapsed the refusal notice. Only the notice goes; the key-change gate stays shut. */
    fun acknowledgeKeyChangeRefusal() {
        keyChangeRefusalHolder().value = null
    }

    private fun keyChangeRefusalHolder(): MutableStateFlow<String?> =
        keyChangeRefusalFlow ?: synchronized(this) {
            keyChangeRefusalFlow ?: MutableStateFlow<String?>(null).also { keyChangeRefusalFlow = it }
        }

    /** ZC-250 — [peerAddress]'s key-change flag was cleared: its refusal notice goes with it. */
    private fun clearKeyChangeRefusal(peerAddress: String) {
        keyChangeRefusalHolder().compareAndSet(peerAddress, null)
    }

    /**
     * MONEY-SAFETY guard for on-chain-only advanced features. Time-locked / block-locked / payment-locked
     * / conditional messages (and their unlocks) are on-chain primitives — they cannot be enforced over a
     * NOSTR relay (no block height, no payment escrow). In TUNNEL/OPEN conversations they MUST NOT silently
     * spend ZEC: only the one-time key exchange may go on-chain. If the conversation isn't VAULT, surface a
     * clear, non-charging notice and return true so the caller aborts BEFORE createChunkedMessageProposal.
     * Audit: these 6 entrypoints called createChunkedMessageProposal with no mode check (ZEC drain).
     */
    private fun blockOnChainFeatureIfNotVault(peerAddress: String, featureLabel: String): Boolean {
        val mode = zchatPreferences.getConversationMode(peerAddress)
        if (mode == co.electriccoin.zcash.ui.screen.chat.model.ConversationMode.VAULT) return false
        // Round 8 D8: one translated sentence (it named the feature and the mode in an English-only template).
        _sendMessageState.value = SendMessageState.Error(ChatSendCopy.ON_CHAIN_FEATURE_ONLY)
        Log.w("ZCHAT_MONEY", "Blocked on-chain feature '$featureLabel' in $mode mode for ${peerAddress.redactAddress()} (no charge)")
        return true
    }

    private fun handleNostrRouteIfApplicable(
        peerAddress: String,
        message: String,
        retryPendingId: String? = null,
    ): Boolean {
        val mode = zchatPreferences.getConversationMode(peerAddress)

        // SR-A (fix-all 2.13.0, owner decision W-16, 28 Sep: "Link on-chain always"). In a Shielded chat nothing goes over
        // the relays from here, an attachment's link included: its link and key travel inside the paid Shielded
        // transaction the user was asked the exact price for (sendAttachmentBlob), with no relay fallback ever, whether or
        // not the contact's relay key is known. Tunnel and Open are unchanged below. (This replaces #bug-image-send's free
        // relay route for a Shielded ZFILE, which published the link of a Shielded chat's photo over the relays.)
        if (mode == co.electriccoin.zcash.ui.screen.chat.model.ConversationMode.VAULT) return false
        // ZC-1352: the user sends again. Before the route below starts the bootstrap.
        if (!ZBootMessage.isBootMessage(message)) userStartsSetupAgain(peerAddress)

        val peerPub = zchatPreferences.getPeerNostrPubkey(peerAddress)
        val peerRelay = zchatPreferences.getPeerNostrRelay(peerAddress)

        when (mode) {
            co.electriccoin.zcash.ui.screen.chat.model.ConversationMode.OPEN -> {
                // MONEY-SAFETY (#224 invariant #1): an OPEN send must NEVER spend ZEC on-chain. We ALWAYS
                // handle it on the NOSTR path — publish-or-FAIL — and NEVER return false (which would let
                // sendMessage/sendReply fall through to the charged shielded pipeline). If the publisher
                // isn't ready yet, NostrChatBridge.publish returns acks=0 → the row is marked FAILED
                // (retryable), still no on-chain charge.
                if (peerPub == null) {
                    // OPEN is only ever set once the peer's NOSTR key is known, so this is a corrupted
                    // state — render FAILED rather than silently charging an on-chain memo.
                    Log.w("ZCHAT_NOSTR", "OPEN without peer NOSTR key — rendering FAILED (NOT charging on-chain)")
                    renderOutgoingNostrFailed(peerAddress, message, retryPendingId)
                    return true
                }
                // First-contact identity: wrap OPEN content as a v4 INIT carrying OUR address so an
                // unknown-pubkey recipient can place us in their Message Requests inbox (and a known
                // recipient unwraps it transparently in observeNostrInbound). ZBOOT / address-not-loaded
                // fall back to raw. publishNostrAndRenderLocal publishes [wirePayload] but renders the
                // local bubble from [message].
                // T1b-1 §2: the selected account's identity; none (raw message) while it is being re-read after a switch.
                val ourAddr = chatIdentityForSelectedAccount()
                val wire =
                    // ZC-1474: a ZATT goes only to the bound key, so it is never wrapped (it needs no first-contact address).
                    if (ourAddr != null &&
                        !co.electriccoin.zcash.ui.screen.chat.model.ZBootMessage
                            .isBootMessage(message) &&
                        !ZATTMessage.isZatt(message)
                    ) {
                        // ZC-1480 item 3: this INIT reaches the contact over the relays only; the first on-chain message
                        // under the same id must carry our address too, so the contact's phone can place it.
                        val openConvId = zchatPreferences.getOrCreateConversationId(peerAddress).first
                        zchatPreferences.markConversationInitOwedOnChain(peerAddress, openConvId)
                        co.electriccoin.zcash.ui.screen.chat.model.ZMSGProtocol.createV4InitMessage(
                            openConvId,
                            ourAddr,
                            message,
                        )
                    } else {
                        message
                    }
                publishNostrAndRenderLocal(peerAddress, peerPub, message, wirePayload = wire, retryPendingId = retryPendingId)
                return true
            }
            co.electriccoin.zcash.ui.screen.chat.model.ConversationMode.TUNNEL -> {
                // TUNNEL may legitimately fall back to the shielded ZBOOT bootstrap (the ONE on-chain
                // memo it's allowed to send), so it — and only it — honors the outbound-not-ready
                // fall-through. OPEN above never reaches here, so it can't be charged.
                if (!co.electriccoin.zcash.ui.nostr.NostrChatBridge
                        .isOutboundReady()
                ) {
                    // ONLY the on-chain ZBOOT handshake may fall through to the shielded path when the
                    // publisher is down — it's the ONE on-chain memo TUNNEL is allowed to send. A user
                    // CONTENT payload must NEVER be charged on-chain (the invariant this branch enforces),
                    // so render it FAILED (retryable) rather than letting sendMessage/sendReply fall through
                    // to the charged shielded pipeline. Previously this returned false for ALL types, so a
                    // content message on an established TUNNEL was charged whenever the publisher was briefly
                    // unregistered (e.g. right after process start).
                    if (co.electriccoin.zcash.ui.screen.chat.model.ZBootMessage
                            .isBootMessage(message)
                    ) {
                        Log.w("ZCHAT_NOSTR", "outbound not ready; TUNNEL ZBOOT falling back to shielded")
                        return false
                    }
                    Log.w("ZCHAT_NOSTR", "outbound not ready; TUNNEL content NOT charged on-chain — rendering FAILED (retryable)")
                    renderOutgoingNostrFailed(peerAddress, message, retryPendingId)
                    return true
                }
                if (peerPub != null) {
                    publishNostrAndRenderLocal(peerAddress, peerPub, message, retryPendingId = retryPendingId)
                    return true
                }
                // The ZBOOT handshake itself is the ONE on-chain memo TUNNEL is allowed to send
                // (it's how the peer learns our NOSTR identity). Let it fall through to the shielded
                // path. A user content payload must NOT — see below.
                if (co.electriccoin.zcash.ui.screen.chat.model.ZBootMessage
                        .isBootMessage(message)
                ) {
                    return false
                }
                // Bootstrap not complete. A TUNNEL content message must NEVER be charged on-chain:
                // (a) kick the one-time ZBOOT handshake (on-chain) so the peer learns our NOSTR key,
                // (b) queue the payload, (c) render a "waiting for secure connection" pending bubble
                // (NOT an on-chain pending — no tx, no fee, no block-time timer), and (d) report
                // HANDLED (true) so sendMessage/sendReply stop before the shielded on-chain send.
                // flushTunnelPendingPayloads() publishes the queue over NOSTR once peerPub arrives.
                ensureNostrBootstrapSent(peerAddress)
                // compute() = atomic enqueue on the PROCESS-WIDE queue (companion) — see its decl.
                // HIGH-006: the waiting bubble persists the payload to the ENCRYPTED pending store
                // under this id BEFORE we report accepted (the caller clears the draft on true), so
                // process death can't lose the user's first tunnel message. The flush removes the row
                // once the payload is handed to the NOSTR publish path (which persists its own row).
                val waitId = retryPendingId ?: "tunnel-wait-${System.nanoTime()}"
                tunnelPendingPayloads.compute(peerAddress) { _, list ->
                    (list ?: mutableListOf()).apply { add(QueuedTunnelPayload(waitId, message)) }
                }
                renderTunnelWaitingBubble(peerAddress, message, waitId)
                Log.d("ZCHAT_NOSTR", "TUNNEL pre-bootstrap — queued payload (no on-chain charge), awaiting peer NOSTR key")
                return true
            }
            co.electriccoin.zcash.ui.screen.chat.model.ConversationMode.VAULT -> return false
        }
    }

    // tunnelPendingPayloads — PROCESS-WIDE, declared in the companion (two-VM flush, #38). See there.

    // MONEY-SAFETY: peer address -> peer pubkey we have ALREADY paid an on-chain KEXACK for. A KEXACK
    // costs ~1000 zatoshi, and the inbound handler used to fire one on EVERY received KEX — so a peer
    // re-sending KEX (or NOSTR re-delivering it) drained the wallet 1000 zatoshi per duplicate. We now
    // record success here and skip re-acking the same key. A FAILED KEXACK is NOT recorded (so it still
    // retries), and a genuinely changed peer key clears the entry (so the new key is re-acked once).
    // kexAckedKeys — process-wide, in the companion (HS-1).

    // CONCURRENCY: the inbound handlers (handleKEXMessage, routeIncomingBoot) fire once PER received
    // memo, and a single KEX/ZBOOT often arrives as several memos or is re-scanned across sync passes →
    // multiple coroutines launch at once. Without an atomic in-flight guard they ALL pass the cheap
    // pref/idempotency check before any of them sets it, then submit DUPLICATE on-chain sends that
    // contend for the one spendable note → every duplicate fails with transient insufficient funds (the
    // failure STORM seen on-device: 4× concurrent KEXACK/ZBOOT sends). These sets make "claim + send"
    // atomic per peer: add() returns false if a send is already in flight, so duplicates bail instantly.
    // kexAckInFlight and nostrBootInFlight are PROCESS-WIDE (companion) so the atomic claim spans the coexisting list +
    // detail ChatViewModel instances — otherwise the KEXACK-receipt ZBOOT (list VM) and a chat-open /
    // block-tick ZBOOT (detail VM) could each claim independently and double-send for the single note.

    /**
     * Render a queued TUNNEL payload as a local "waiting for secure connection" bubble. This is a
     * NOSTR-pending state, NOT an on-chain pending: there is no tx, no fee, and no block-time/75s
     * timer. The bubble's id is the queued payload's identity so [flushTunnelPendingPayloads] can
     * drop it (the real "nostr-out-…" bubble from [publishNostrAndRenderLocal] replaces it) once the
     * peer's NOSTR key arrives. Mirrors [publishNostrAndRenderLocal]'s reply-ref / ZFILE handling so
     * the sender sees clean text / a file card, not the raw U+0001 marker or "ZFILE|…" memo.
     *
     * HIGH-006: also persists the row to the ENCRYPTED pending store under [localId] — the RAM queue
     * dies with the process, and the caller-side draft is cleared once the send is accepted, so
     * without this row the user's first tunnel message was permanently lost on process death.
     * [loadPendingMessagesFromPrefs] re-queues persisted tunnel-wait rows on cold start.
     */
    private fun renderTunnelWaitingBubble(peerAddress: String, plaintext: String, localId: String) {
        val now = Instant.now()
        val (localReplyTo, localReplyPreview, strippedPlaintext) = untagReply(plaintext)
        val localFile =
            if (co.electriccoin.zcash.ui.screen.chat.model.ZFILEMessage
                    .isFileMessage(strippedPlaintext)
            ) {
                co.electriccoin.zcash.ui.screen.chat.model.ZFILEMessage
                    .parse(strippedPlaintext)
            } else {
                null
            }
        val localMsg =
            if (localFile != null) {
                ChatMessage(
                    id = localId,
                    txId = null,
                    text = "📎 ${localFile.displayText}",
                    timestamp = now,
                    isOutgoing = true,
                    peerAddress = peerAddress,
                    isPending = true,
                    status = MessageStatus.SENDING,
                    replyToId = localReplyTo,
                    replyToPreview = localReplyPreview,
                    fileHash = localFile.hash,
                    fileZfileContent = strippedPlaintext,
                    fileBlurhash = localFile.blurhash.takeIf { it.isNotEmpty() },
                    fileType = localFile.type,
                    fileViewOnce = localFile.viewOnce,
                    fileViewed = localFile.viewOnce && zchatPreferences.isFileViewed(localFile.hash),
                )
            } else {
                ChatMessage(
                    id = localId,
                    txId = null,
                    text = strippedPlaintext,
                    timestamp = now,
                    isOutgoing = true,
                    peerAddress = peerAddress,
                    isPending = true,
                    status = MessageStatus.SENDING,
                    replyToId = localReplyTo,
                    replyToPreview = localReplyPreview,
                )
            }
        pendingMessages.update { list -> list.filterNot { it.id == localId } + localMsg }
        // Durable copy (HIGH-006) — same encrypted store as every other NOSTR row. fileZfileContent
        // (files) / text (plain) + the reply fields carry everything needed to rebuild the wire
        // payload on cold-start rehydration.
        zchatPreferences.addPendingMessage(
            ZchatPreferences.PendingMessageData(
                id = localId,
                text = localMsg.text,
                timestampMillis = now.toEpochMilli(),
                peerAddress = peerAddress,
                isOutgoing = true,
                isPending = true,
                status = MessageStatus.SENDING.name,
                submitTracked = true,
                replyToId = localReplyTo,
                replyToPreview = localReplyPreview,
                fileZfileContent = localMsg.fileZfileContent,
            )
        )
    }

    /**
     * Flush any TUNNEL payloads queued while the peer's NOSTR identity was still unknown. Called the
     * moment we learn [peerPubHex] (from an inbound ZBOOT in [routeIncomingBoot], or piggybacked on a
     * KEX/KEXACK in [applyKEXNostr]). Each queued payload is published over NOSTR + rendered as its
     * own local bubble via [publishNostrAndRenderLocal]; the optimistic "tunnel-wait-…" placeholders
     * are dropped so they don't duplicate. Without this, [tunnelPendingPayloads] was write-only and
     * every pre-bootstrap TUNNEL message was lost.
     */
    private fun flushTunnelPendingPayloads(peerAddress: String, peerPubHex: String) {
        // T7BH-N1: nothing of the user's goes to a contact whose new key waits for the user. Checked before anything:
        // the process-wide queue is not claimed, the waiting rows and their "waiting for secure connection" bubbles
        // stay, and the decision flushes them ([resumeAfterKeyDecision]).
        if (zchatPreferences.isE2EKeyChanged(peerAddress)) {
            Log.d("ZCHAT_NOSTR", "Queued TUNNEL payload(s) for ${peerAddress.take(16)}… held: the contact's new key waits")
            return
        }
        // ALWAYS drop THIS instance's "waiting for secure connection" placeholders — even when the
        // OTHER ChatViewModel instance wins the atomic queue claim below, the placeholders rendered
        // here (per-instance pendingMessages) must not outlive the flush; the winner's real bubbles
        // arrive via the broadcastLocal emit in publishNostrAndRenderLocal. Idempotent + cheap when
        // nothing was queued.
        pendingMessages.update { list -> list.filterNot { it.id.startsWith("tunnel-wait-") && it.peerAddress == peerAddress } }
        // remove() = atomic claim of the PROCESS-WIDE queue: exactly one instance gets the payloads.
        val queued = tunnelPendingPayloads.remove(peerAddress) ?: return
        if (queued.isEmpty()) return
        // SR-B2 (fix-all 2.13.0): the mode is read AFTER the claim, so the one check covers every caller (the three
        // routeIncomingBoot paths, applyKEXNostr and the rehydrate in loadPendingMessagesFromPrefs). A chat the user switched
        // to Shielded while these waited (an unset mode counts as Shielded) publishes nothing: each payload becomes a FAILED
        // row with its reason under a FRESH nostr-out- id (never q.id: addPendingMessage is keyed by id, so removing q.id
        // next would delete it, and a tunnel-wait- id is dropped from memory by every later flush), and only then is the
        // tunnel-wait row removed. Nothing was published or paid; Retry sends it as a new Shielded send (retryMessage). A
        // chat routeIncomingBoot just adopted to Tunnel reads Tunnel here and flushes as before.
        if (zchatPreferences.getConversationMode(peerAddress) == ConversationMode.VAULT) {
            queued.forEach { q ->
                val failed =
                    renderOutgoingNostrFailed(
                        peerAddress,
                        q.payload,
                        retryPendingId = null,
                        reason = ChatSendCopy.FAILED_SWITCHED_TO_SHIELDED,
                    )
                zchatPreferences.removePendingMessage(q.id)
                co.electriccoin.zcash.ui.nostr.NostrChatBridge
                    .emitLocalMessage(failed)
            }
            Log.w("ZCHAT_NOSTR", "SR-B2: ${queued.size} queued Tunnel payload(s) not published (the chat is Shielded now)")
            return
        }
        queued.forEach { q ->
            // broadcastLocal so the OTHER instance (whose placeholder was just cleared) renders the
            // real bubble live instead of waiting for its next persisted-store reload.
            publishNostrAndRenderLocal(peerAddress, peerPubHex, q.payload, broadcastLocal = true)
            // Durable dequeue (HIGH-006) AFTER the handoff: publishNostrAndRenderLocal has persisted
            // its own "nostr-out-…" row by now, so dropping the tunnel-wait row can't lose the message.
            zchatPreferences.removePendingMessage(q.id)
        }
        Log.d("ZCHAT_NOSTR", "Flushed ${queued.size} queued TUNNEL payload(s) over NOSTR for ${peerAddress.take(16)}…")
    }

    /**
     * Render + persist an outbound NOSTR message as immediately FAILED (retryable) WITHOUT any on-chain
     * spend. Used by the OPEN money-safety path when the message can't be published (missing peer key).
     * The user keeps the text and can retry once the channel is ready — we never silently charge ZEC.
     * SR-B2: [reason] is the row's failure reason (a queued Tunnel payload whose chat switched to Shielded says so); the
     * row is returned so a caller can hand it to the other ChatViewModel instance.
     */
    private fun renderOutgoingNostrFailed(
        peerAddress: String,
        plaintext: String,
        retryPendingId: String? = null,
        reason: String = ChatSendCopy.FAILED_NOT_CONNECTED,
    ): ChatMessage {
        val now = Instant.now()
        val localId = retryPendingId ?: "nostr-out-${System.nanoTime()}"
        // ZC-421: a Retry that cannot publish rewrites its row with the rumor pair the row holds (handed over by retryMessage).
        val keptPair = retryPendingId?.let { relayRetryPairs.remove(it) }
        val (replyTo, replyPreview, stripped) = untagReply(plaintext)
        // ZC-1474: a ZFILE or a free attachment (ZATT) line shows as its file card, never as the raw line.
        val file = ZATTMessage.fileRefOf(stripped)
        val msg =
            ChatMessage(
                id = localId,
                txId = null,
                text = if (file != null) "📎 ${file.displayText}" else stripped,
                timestamp = now,
                isOutgoing = true,
                peerAddress = peerAddress,
                isPending = false,
                status = MessageStatus.FAILED,
                replyToId = replyTo,
                replyToPreview = replyPreview,
                fileHash = file?.hash,
                fileZfileContent = file?.let { stripped },
                fileBlurhash = file?.blurhash?.takeIf { it.isNotEmpty() },
                fileType = file?.type,
                failureReason = reason,
            )
        pendingMessages.update { list -> list.filterNot { it.id == localId } + msg }
        zchatPreferences.addPendingMessage(
            ZchatPreferences.PendingMessageData(
                id = localId,
                text = msg.text,
                timestampMillis = now.toEpochMilli(),
                peerAddress = peerAddress,
                isOutgoing = true,
                isPending = false,
                status = MessageStatus.FAILED.name,
                submitTracked = true,
                replyToId = replyTo,
                replyToPreview = replyPreview,
                fileZfileContent = msg.fileZfileContent,
                failureReason = msg.failureReason,
                relayRumorAtSec = keptPair?.atSec,
                relayRumorId = keptPair?.rumorId,
            )
        )
        return msg
    }

    /**
     * Publish [wirePayload] over NOSTR to [peerPubHex] and render/persist the sender's local bubble from
     * [plaintext]. [wirePayload] defaults to [plaintext]; pass a different value when the wire form
     * differs from what the user sees locally — e.g. an OPEN first message whose wire is a v4 INIT
     * (carrying our address) but whose bubble should show only the typed text. The local bubble must
     * NEVER render the raw envelope.
     */
    private fun publishNostrAndRenderLocal(
        peerAddress: String,
        peerPubHex: String,
        plaintext: String,
        wirePayload: String = plaintext,
        // #38 two-VM flush: when the tunnel-outbox flush runs in the ChatViewModel instance the user is
        // NOT looking at (list vs detail), broadcast the resolved bubble over the local-message channel
        // so the other instance renders it live (its "waiting…" placeholder was already cleared). The
        // emitting instance dedups on id, so this never double-renders locally.
        broadcastLocal: Boolean = false,
        retryPendingId: String? = null,
    ) {
        val now = Instant.now()
        val localId = retryPendingId ?: "nostr-out-${System.nanoTime()}"
        // ZC-421 (Z13): the stored row holds its rumor's second and id before the rumor is published. A Retry hands over the
        // pair its stored row holds (retryMessage); a first send takes the pair of the rumor it is about to publish before
        // its row is first written, so the row holds it from that write. No rumor publisher: no pair, today's path.
        val handedPair = retryPendingId?.let { relayRetryPairs.remove(it) }
        val firstPair =
            if (retryPendingId == null && NostrChatBridge.canPublishRumorAt()) {
                runCatching { NostrChatBridge.rumorIdAt(wirePayload, peerPubHex, now.epochSecond) }
                    .getOrNull()
                    ?.let { RelayRumorPair(now.epochSecond, it) }
            } else {
                null
            }
        val rowPair = handedPair ?: firstPair
        // The reply-ref rides the wire (plaintext, published below) but must be stripped from the
        // sender's OWN local bubble: otherwise the sender sees the raw U+0001 marker (and, for a
        // reply-to-file, the "ZFILE|…" body never parses into a file card). replyToId threads it.
        val (localReplyTo, localReplyPreview, strippedPlaintext) = untagReply(plaintext)
        // Parse a ZFILE ref into the sender's OWN file bubble — mirrors the inbound NOSTR parse so
        // the sender sees a file card, not the raw "ZFILE|hash|…|base64key" memo (which would leak
        // the wrapped key into the visible bubble text and never render the image). ZC-1474: a free attachment's ZATT line
        // (its file key inside) gets the same file card.
        val localFile = ZATTMessage.fileRefOf(strippedPlaintext)
        val localMsg =
            if (localFile != null) {
                ChatMessage(
                    id = localId,
                    txId = null,
                    text = "📎 ${localFile.displayText}",
                    timestamp = now,
                    isOutgoing = true,
                    peerAddress = peerAddress,
                    isPending = true,
                    status = MessageStatus.SENDING,
                    replyToId = localReplyTo,
                    replyToPreview = localReplyPreview,
                    fileHash = localFile.hash,
                    fileZfileContent = strippedPlaintext,
                    fileBlurhash = localFile.blurhash.takeIf { it.isNotEmpty() },
                    fileType = localFile.type,
                    fileViewOnce = localFile.viewOnce,
                    fileViewed = localFile.viewOnce && zchatPreferences.isFileViewed(localFile.hash),
                )
            } else {
                ChatMessage(
                    id = localId,
                    txId = null,
                    text = strippedPlaintext,
                    timestamp = now,
                    isOutgoing = true,
                    peerAddress = peerAddress,
                    isPending = true,
                    status = MessageStatus.SENDING,
                    replyToId = localReplyTo,
                    replyToPreview = localReplyPreview,
                )
            }
        pendingMessages.update { list -> list.filterNot { it.id == localId } + localMsg }
        // Persist the outbound NOSTR row so it survives process death / ChatViewModel recreation.
        // Unlike on-chain sends, a NOSTR message has no ledger entry to rebuild from — without this
        // it lives only in the in-memory pendingMessages and vanishes on reload. txId stays null, so
        // the convertToConversations dedup never matches it against a confirmed tx (i.e. never removes it).
        val sendingRow =
            ZchatPreferences.PendingMessageData(
                id = localId,
                text = localMsg.text,
                timestampMillis = now.toEpochMilli(),
                peerAddress = peerAddress,
                isOutgoing = true,
                isPending = true,
                status = MessageStatus.SENDING.name,
                submitTracked = true,
                replyToId = localReplyTo,
                replyToPreview = localReplyPreview,
                fileZfileContent = localMsg.fileZfileContent,
                relayRumorAtSec = rowPair?.atSec,
                relayRumorId = rowPair?.rumorId,
            )
        // ZC-1071: this screen publishes the row until its launch below ends (released when the returned job completes,
        // so a launch cancelled before its body starts releases it too; a cleared screen registers nothing).
        if (viewModelScope.coroutineContext[kotlinx.coroutines.Job]?.isActive != false) LiveSenders.running(localId, this)
        zchatPreferences.addPendingMessage(sendingRow)
        // ZC-1114: the id the row is stored under once the publish re-keyed it (told with the release).
        var storedAs: String? = null
        val publish =
            viewModelScope.launch {
                // ZC-393: a Retry of a row only a public relay took re-sends the wrap the relay outbox still keeps (same event
                // id, same rumor id). ZC-421: nothing kept (a restart) → the same rumor in a new wrap when the row holds its pair,
                // else a new message, as before (publishRelayRow).
                val sent =
                    publishRelayRow(
                        rowId = localId,
                        payload = wirePayload,
                        peerPubHex = peerPubHex,
                        peerAddress = peerAddress,
                        kept = rowPair,
                        fresh = firstPair != null,
                        retry = retryPendingId != null,
                        nowSec = now.epochSecond,
                    ) { atSec, rumorId ->
                        kotlinx.coroutines.withContext(kotlinx.coroutines.Dispatchers.IO) {
                            zchatPreferences.commitPendingMessage(sendingRow.copy(relayRumorAtSec = atSec, relayRumorId = rumorId))
                        }
                    }
                val result = sent.result
                // ZC-393: acks counts only the relays every ZChat version reads (ZChat's relay, nos.lol).
                val acks = result?.acks ?: 0
                val finalStatus = if (acks > 0) MessageStatus.SENT else MessageStatus.FAILED
                // R2-7 (c): a relay-less failure says why above its Retry. ZC-393: one only a public relay took says so.
                val failureReason =
                    when {
                        finalStatus != MessageStatus.FAILED -> null
                        (result?.readableAcks ?: 0) > 0 -> ChatSendCopy.FAILED_ONLY_PUBLIC_RELAY
                        else -> ChatSendCopy.FAILED_NO_RELAY
                    }
                // #202: re-key our optimistic bubble from the throwaway "nostr-out-…" id to the STABLE
                // shared rumor id ("nmsg-<rumorId>") that the RECIPIENT also assigns to this message — so a
                // reaction/reply (which targets the message's id) correlates across both devices. The user
                // can only react AFTER the send resolves, so the id is settled by then. Drop the old persisted
                // row and re-persist under the new id to keep storage consistent.
                val finalId = result?.messageId?.takeIf { it.isNotEmpty() }?.let { "nmsg-$it" } ?: localId
                pendingMessages.update { list ->
                    list.map { m ->
                        if (m.id == localId) {
                            m.copy(id = finalId, isPending = false, status = finalStatus, failureReason = failureReason)
                        } else {
                            m
                        }
                    }
                }
                // Update the persisted copy to its resolved state (under finalId) so a restart shows the
                // right status (SENT/FAILED) AND the same correlatable id instead of a perpetual "SENDING".
                zchatPreferences.addPendingMessage(
                    ZchatPreferences.PendingMessageData(
                        id = finalId,
                        text = localMsg.text,
                        timestampMillis = now.toEpochMilli(),
                        peerAddress = peerAddress,
                        isOutgoing = true,
                        isPending = false,
                        status = finalStatus.name,
                        submitTracked = true,
                        replyToId = localReplyTo,
                        replyToPreview = localReplyPreview,
                        fileZfileContent = localMsg.fileZfileContent,
                        failureReason = failureReason,
                        relayRumorAtSec = sent.atSec,
                        relayRumorId = sent.rumorId,
                    )
                )
                if (finalId != localId) {
                    zchatPreferences.removePendingMessage(localId)
                    storedAs = finalId
                }
                if (broadcastLocal) {
                    // After the id is settled + the row persisted: hand the resolved bubble to every other
                    // ChatViewModel instance (observeLocalMessages id-dedups, incl. in this emitter).
                    co.electriccoin.zcash.ui.nostr.NostrChatBridge.emitLocalMessage(
                        localMsg.copy(id = finalId, isPending = false, status = finalStatus, failureReason = failureReason)
                    )
                }
                Log.d("ZCHAT_NOSTR", "published to $acks relay(s) for ${peerAddress.take(16)}… (id=$finalId)")
            }
        publish.invokeOnCompletion { LiveSenders.release(localId, this@ChatViewModel, replacedBy = storedAs) }
    }

    /** ZC-421 — the rumor pair of a relay row ([ZchatPreferences.PendingMessageData.relayRumorAtSec], relayRumorId). */
    private class RelayRumorPair(
        val atSec: Long?,
        val rumorId: String?,
        // The row's last publish reached no relay at all (its Retry makes a new message: "not-taken" in the log).
        val notTaken: Boolean = false,
    )

    /**
     * ZC-421 — what [publishRelayRow] did: the relay layer's answer (null: nothing was published, or the attempt failed), the
     * rumor pair the row holds afterwards, and, for a payment request, whether it was refused (nothing sent).
     */
    private class RelayRowSend(
        val result: NostrChatBridge.PublishResult?,
        val atSec: Long?,
        val rumorId: String?,
        val refused: Boolean = false,
    )

    /**
     * ZC-421 — one relay publish of the row [rowId]'s [payload] to [peerPubHex], for both relay-row writers
     * ([publishNostrAndRenderLocal], the relay branch of [sendPaymentRequest]). [kept] is the rumor pair the stored row holds
     * ([fresh]: a first send's pair, on the row since its first write); [writePair] rewrites the stored row with a pair (or
     * none) and throws when the store does not confirm it. It calls the relay bridge and the store, nothing else: free.
     *
     * A message: the kept wrap first (ZC-393); no rumor publisher: the plain publisher, as before; the same rumor in a new
     * wrap when the row holds its second, less than 24 hours old, in a chat with no disappearing timer, checked by id (a
     * rumor that would get another id publishes nothing); otherwise a new message at [nowSec] whose pair is on the stored
     * row before it is published, and stays only when a relay took it. A rumor re-sent or re-made keeps its pair whatever
     * the answer: an earlier copy may be out. A payment request ([isRequest]) has one rumor for as long as its row exists:
     * the kept wrap, else that rumor while its second is less than 29 days old, else nothing ([RelayRowSend.refused]).
     */
    @Suppress("TooGenericExceptionCaught", "CyclomaticComplexMethod", "ReturnCount", "LongParameterList", "LongMethod")
    private suspend fun publishRelayRow(
        rowId: String,
        payload: String,
        peerPubHex: String,
        peerAddress: String,
        kept: RelayRumorPair?,
        retry: Boolean,
        nowSec: Long,
        fresh: Boolean = false,
        isRequest: Boolean = false,
        writePair: suspend (atSec: Long?, rumorId: String?) -> Unit,
    ): RelayRowSend {
        val keptSec = kept?.atSec
        val keptId = kept?.rumorId
        if (isRequest && keptId != null) {
            if (retry) NostrChatBridge.resendKept(keptId, peerPubHex)?.let { return RelayRowSend(it, keptSec, keptId) }
            if (!NostrChatBridge.canPublishRumorAt()) return RelayRowSend(null, keptSec, keptId)
            val reason =
                when {
                    keptSec == null -> "no-second"
                    nowSec - keptSec >= REQUEST_RESEND_WINDOW_SEC -> "older-29d"
                    else ->
                        NostrChatBridge.publishRumorAt(payload, peerPubHex, keptSec, expectedRumorId = keptId)?.let {
                            return RelayRowSend(it, keptSec, keptId)
                        } ?: "id-differs"
                }
            Log.w("ZCHAT_NOSTR", "Request not sent again ($reason)")
            return RelayRowSend(null, keptSec, keptId, refused = true)
        }
        // What the stored row holds; a failed checked write means nothing was published.
        var heldSec = keptSec
        var heldId = keptId
        var writeFailed = false
        val write: suspend (Long?, String?) -> Unit = { atSec, rumorId ->
            try {
                writePair(atSec, rumorId)
            } catch (e: Exception) {
                writeFailed = true
                throw e
            }
            heldSec = atSec
            heldId = rumorId
        }
        return try {
            val rumorId = keptId ?: rowId.takeIf { it.startsWith(RELAY_ROW_PREFIX) }?.removePrefix(RELAY_ROW_PREFIX)
            if (retry && rumorId != null) {
                NostrChatBridge.resendKept(rumorId, peerPubHex)?.let { return RelayRowSend(it, keptSec, keptId) }
            }
            if (!NostrChatBridge.canPublishRumorAt()) {
                // Nothing can go out at all: the row keeps what it holds, and the caller fails it as today.
                if (!NostrChatBridge.isOutboundReady()) return RelayRowSend(NostrChatBridge.PublishResult(0, null), keptSec, keptId)
                if (retry) Log.d("ZCHAT_NOSTR", "Retry made a new message (no-publisher)")
                if (heldSec != null || heldId != null) write(null, null)
                return RelayRowSend(NostrChatBridge.publish(payload, peerPubHex), null, null)
            }
            var firstSend = false
            if (fresh && keptSec != null && keptId != null) {
                // A first send: the checked write confirms the pair its row holds since its first write.
                write(keptSec, keptId)
                firstSend = true
            } else if (retry) {
                val reason =
                    when {
                        rumorId == null || keptSec == null -> if (kept?.notTaken == true) "not-taken" else "no-second"
                        nowSec < keptSec || nowSec - keptSec >= RELAY_REMAKE_WINDOW_SEC -> "older-24h"
                        hasDisappearingTimer(peerAddress) -> "timer"
                        else -> {
                            val remade = NostrChatBridge.publishRumorAt(payload, peerPubHex, keptSec, expectedRumorId = rumorId)
                            if (remade != null) {
                                Log.d("ZCHAT_NOSTR", "Retry re-made rumor ${rumorId.take(8)} in a new wrap")
                                return RelayRowSend(remade, keptSec, rumorId)
                            }
                            "id-differs"
                        }
                    }
                Log.d("ZCHAT_NOSTR", "Retry made a new message ($reason)")
            }
            // A new rumor: its pair is on the stored row before it is published.
            val pairSec = if (firstSend) keptSec else nowSec
            val pairId =
                if (firstSend) keptId else NostrChatBridge.rumorIdAt(payload, peerPubHex, nowSec)?.also { write(nowSec, it) }
            if (pairSec != null && pairId != null) {
                NostrChatBridge.publishRumorAt(payload, peerPubHex, pairSec, expectedRumorId = pairId)?.let { r ->
                    val took = NostrChatBridge.relayTookIt(r)
                    return RelayRowSend(r, pairSec.takeIf { took }, pairId.takeIf { took })
                }
            }
            // The rumor publisher went away between the check and the call: the plain publisher, with no pair on the row.
            if (heldSec != null || heldId != null) write(null, null)
            RelayRowSend(NostrChatBridge.publish(payload, peerPubHex), null, null)
        } catch (e: Throwable) {
            // A failed checked write published nothing: the row keeps no pair. A publish that failed may have reached a
            // relay: the row keeps the pair it holds, so its Retry makes that rumor again.
            Log.w("ZCHAT_NOSTR", "relay publish of a row failed: ${e.javaClass.simpleName}")
            if (writeFailed) RelayRowSend(null, null, null) else RelayRowSend(null, heldSec, heldId)
        }
    }

    /** ZC-421: the chat with [peerAddress] has a disappearing timer (read only when a re-made rumor is about to go out). */
    private fun hasDisappearingTimer(peerAddress: String): Boolean =
        runCatching { zchatPreferences.getDisappearingTtl(peerAddress) }.getOrNull()?.let { it.ttlSeconds > 0 } ?: false

    /**
     * ZC-421 (Z13 item 5) — a relay row: an outgoing row whose id is a relay row's (`nostr-out-`, `nmsg-`), or a payment
     * request that holds its rumor id, with no recorded on-chain submit. Only a relay publish ever leaves one pending, so
     * nothing paid can be in doubt behind it.
     */
    private fun ZchatPreferences.PendingMessageData.isRelayRow(): Boolean =
        isOutgoing &&
            submitStartedAtMillis == null &&
            submittedTxIds.isEmpty() &&
            (
                id.startsWith(RELAY_OUT_PREFIX) ||
                    id.startsWith(RELAY_ROW_PREFIX) ||
                    (paymentRequestAmountZatoshi != null && relayRumorId != null)
            )

    /**
     * Validate and repair conversation ID mappings.
     * This function detects missing or inconsistent convId mappings and repairs them.
     * Essential for fixing message routing issues after wallet restore.
     *
     * Repair strategy (single-pass, snapshot-based):
     * 1. Load both convId→peer and peer→convId snapshots
     * 2. Build consistent target state in memory (conv→peer is authoritative)
     * 3. Write only entries that differ from current state
     * 4. Log all repairs for debugging
     *
     * Uses snapshots exclusively — never reads live data during iteration to prevent
     * stale-snapshot corruption where pass N sees pass N-1's writes as inconsistencies.
     *
     * Runs with convIdMutex held to prevent races with send/receive paths.
     */
    private fun validateAndRepairConvIdMappings() {
        viewModelScope.launch {
            try {
                convIdMutex.withLock {
                    try {
                        val allConvMappings = zchatPreferences.getAllConversationMappings() // convId -> peer
                        val allPeerMappings = zchatPreferences.getAllPeerToConvIdMappings() // peer -> convId
                        var repairCount = 0
                        var orphanCount = 0

                        Log.d("ZCHAT_REPAIR", "=== Validating ConvId Mappings (conv=${allConvMappings.size}, peer=${allPeerMappings.size}) ===")

                        // Build consistent target state in memory from both snapshots.
                        // Conv→peer direction is authoritative; peer→convId fills gaps.
                        val targetConvToPeer = mutableMapOf<String, String>() // convId -> peer
                        val targetPeerToConv = mutableMapOf<String, String>() // peer -> convId

                        // Phase 1: conv→peer entries are authoritative
                        val orphanConvIds = mutableListOf<String>()
                        for ((convId, peer) in allConvMappings) {
                            if (peer.isBlank()) {
                                Log.w("ZCHAT_REPAIR", "Orphaned conv entry with blank peer: ${convId.redactConvId()}")
                                orphanConvIds.add(convId)
                                orphanCount++
                                continue
                            }
                            targetConvToPeer[convId] = peer
                            // First convId seen for a peer wins
                            if (!targetPeerToConv.containsKey(peer)) {
                                targetPeerToConv[peer] = convId
                            }
                        }

                        // Phase 2: peer→convId fills gaps only (does not override authoritative entries)
                        for ((peer, convId) in allPeerMappings) {
                            if (!targetPeerToConv.containsKey(peer)) {
                                targetPeerToConv[peer] = convId
                                if (!targetConvToPeer.containsKey(convId)) {
                                    targetConvToPeer[convId] = peer
                                }
                            }
                        }

                        // Write only entries where this convId is the CHOSEN one for this peer.
                        // Skip entries where multiple convIds map to the same peer but this isn't
                        // the winner — calling setConversationMapping would overwrite the reverse mapping.
                        for ((convId, peer) in targetConvToPeer) {
                            val chosenConvId = targetPeerToConv[peer]
                            if (chosenConvId != convId) {
                                // This convId lost the "first wins" tie for this peer — skip write
                                Log.d("ZCHAT_REPAIR", "Skipping non-primary mapping: ${convId.redactConvId()} -> ${peer.redactAddress()} (primary is ${chosenConvId?.redactConvId()})")
                                continue
                            }
                            val currentForward = allConvMappings[convId]
                            val currentReverse = allPeerMappings[peer]
                            if (currentForward != peer || currentReverse != convId) {
                                Log.w("ZCHAT_REPAIR", "Repairing mapping: ${convId.redactConvId()} <-> ${peer.redactAddress()} " +
                                    "(was forward=${currentForward?.redactAddress()}, reverse=${currentReverse?.redactConvId()})")
                                zchatPreferences.setConversationMapping(convId, peer)
                                repairCount++
                            }
                        }

                        // Delete blank-peer orphan conv: entries to prevent getPeerByConversationId
                        // from returning blank strings that create degenerate conversation keys.
                        for (orphanConvId in orphanConvIds) {
                            zchatPreferences.removeConversationMapping(orphanConvId)
                            Log.w("ZCHAT_REPAIR", "Deleted orphan conv entry: ${orphanConvId.redactConvId()}")
                        }

                        if (repairCount > 0 || orphanCount > 0) {
                            Log.i("ZCHAT_REPAIR", "Repaired $repairCount mappings, deleted $orphanCount orphans")
                        } else {
                            Log.d("ZCHAT_REPAIR", "All ConvId mappings are consistent")
                        }
                    } catch (e: Exception) {
                        Log.e("ZCHAT_REPAIR", "Error validating ConvId mappings", e)
                    }
                }
            } finally {
                // Always open the gate, even if mutex acquisition or coroutine is cancelled.
                // This prevents loadConversations() from hanging forever.
                repairComplete.complete(Unit)
            }
        }
    }

    /**
     * Load pending messages from preferences.
     * These are messages that were sent but not yet confirmed on blockchain.
     * Persisting them ensures they survive screen navigation.
     */
    private fun loadPendingMessagesFromPrefs() {
        // ZC-1071: watch for rows other screens let go before reading the store, so none is missed in between.
        watchLiveSendReleases()
        val savedPending = zchatPreferences.getPendingMessages()
        if (savedPending.isNotEmpty()) {
            val chatMessages =
                savedPending.map { data -> storedPendingRowAsShown(data, rehydrateTunnelWait = true) }
            pendingMessages.value = chatMessages
            // ZC-1114: a row released after its live check above and before this assignment was missed by the release
            // listener (nothing shown yet): map every row shown in flight that is no longer live again.
            chatMessages
                .filter { it.isOutgoing && it.isPending && !isSendLiveInThisProcess(it.id) }
                .forEach { remapReleasedRow(it.id) }
            Log.d("ZCHAT_PENDING", "Loaded ${chatMessages.size} pending messages from preferences")
            // HIGH-006: a rehydrated tunnel-wait payload normally flushes when the peer's ZBOOT/KEX
            // arrives — but if the peer's NOSTR key is ALREADY known (bootstrap completed but the
            // process died before the flush), no new inbound event may ever fire and the queue would
            // strand forever. Kick the flush directly for those peers; it's idempotent (atomic claim)
            // and free (NOSTR only, no on-chain spend).
            savedPending
                .filter { it.id.startsWith("tunnel-wait-") }
                .map { it.peerAddress }
                .distinct()
                .forEach { peer ->
                    zchatPreferences.getPeerNostrPubkey(peer)?.let { pub ->
                        flushTunnelPendingPayloads(peer, pub)
                    }
                }
        }
    }

    /**
     * One stored pending row as this screen shows it (the loader's mapping; ZC-1071: also a row another screen let go).
     * [rehydrateTunnelWait]: a tunnel-wait row is put back into the process-wide tunnel queue (the loader only).
     */
    private fun storedPendingRowAsShown(
        data: ZchatPreferences.PendingMessageData,
        rehydrateTunnelWait: Boolean,
    ): ChatMessage {
        // Re-derive the file/voice bubble fields from the persisted raw "ZFILE|…" memo, mirroring
        // the live NOSTR send/receive parse so a restored voice/image row renders as a media card
        // (not the raw memo) and still downloads via fileHash.
        // ZC-1474: a stored free attachment (ZATT) line restores as its file card too.
        val restoredFile = data.fileZfileContent?.let { ZATTMessage.fileRefOf(it) }
        val restoredStatus =
            data.status
                ?.let { runCatching { MessageStatus.valueOf(it) }.getOrNull() }
                ?: MessageStatus.SENT
        // Reconcile ORPHANED in-flight sends. A message persisted as still-SENDING was being
        // driven by the in-memory messageQueue + a viewModelScope retry coroutine, NEITHER of
        // which survives process death or ViewModel clear (the prior scope is cancelled). On a
        // fresh ChatViewModel that send will never resume, leaving a perpetual "Sending after
        // confirmation" bubble that nothing completes. Surface it as FAILED so the user gets the
        // existing tap-to-retry affordance. We deliberately do NOT auto-resend: doSendMessage
        // persists the pending row BEFORE broadcasting, so a silent resend could double-send a tx
        // that actually went out (the real one, if broadcast, reappears via sync as a SENT bubble).
        // An OUTGOING row persisted as still-pending is in-flight: the data class documents that
        // outbound rows flip to not-pending once they reach SENT/FAILED, and the VAULT queue path
        // persists with status=null ("legacy on-chain pending"). So isPending — NOT the (often
        // null→SENT) status — is the reliable orphan signal.
        //
        // EXCEPT tunnel-wait rows (HIGH-006): a pre-bootstrap TUNNEL payload isn't orphaned —
        // it is deliberately parked until the peer's NOSTR key arrives. Re-queue it into the
        // PROCESS-WIDE queue (once per process — the coexisting list/detail instances both run
        // this loader) so the existing flush machinery publishes it, and keep the bubble in its
        // "waiting for secure connection" state instead of flipping it to FAILED.
        val isTunnelWait = data.id.startsWith("tunnel-wait-")
        // ZC-1979: never a row the user deleted (its id hidden) whose removal did not reach the disk.
        if (rehydrateTunnelWait && isTunnelWait && !rowIsHidden(data.id) && tunnelQueueRehydrated.add(data.id)) {
            // Rebuild the raw wire payload the same way the retry path does
            // (recoverRawSendPayload): raw ZFILE memo for files, the text itself otherwise,
            // re-tagged with its reply ref.
            val body = data.fileZfileContent ?: data.text
            val raw = data.replyToId?.let { tagReply(it, body, data.replyToPreview ?: "") } ?: body
            tunnelPendingPayloads.compute(data.peerAddress) { _, list ->
                (list ?: mutableListOf()).apply { add(QueuedTunnelPayload(data.id, raw)) }
            }
        }
        // ZC-1071: a row another screen of this process is still sending is not orphaned: it stays in flight
        // with its stored markers (no "ZChat was closed", no Retry that could take the send over).
        // ZC-1114: nor is a row stored in flight with the transactions its submit returned: it went out, sync settles it
        // (as remapReleasedRow leaves it); it stays in flight, so Retry refuses it.
        val isOrphanedInFlight =
            data.isOutgoing &&
                data.isPending &&
                !isTunnelWait &&
                data.submittedTxIds.isEmpty() &&
                !isSendLiveInThisProcess(data.id) &&
                // ZC-1271: an accepted first message waits for its funds on purpose and resumes at a later block.
                !data.waitsForFunds()
        // P2a: an on-chain row from an older build recorded nothing about its submit, and it was
        // persisted BEFORE the broadcast, so an interrupted one may have gone out: Retry must prove
        // it did not first. The row's own time stands in for the unknown submit time.
        val isLegacyOnChainInFlight =
            data.isOutgoing &&
                !data.submitTracked &&
                data.id.startsWith(ON_CHAIN_PENDING_PREFIX) &&
                (isOrphanedInFlight || restoredStatus == MessageStatus.FAILED)
        val submitStartedAt =
            data.submitStartedAtMillis ?: data.timestampMillis.takeIf { isLegacyOnChainInFlight }
        val effectiveStatus = if (isOrphanedInFlight) MessageStatus.FAILED else restoredStatus
        val effectivePending = if (isOrphanedInFlight) false else data.isPending
        return ChatMessage(
            id = data.id,
            txId = null,
            text = data.text,
            timestamp = java.time.Instant.ofEpochMilli(data.timestampMillis),
            isOutgoing = data.isOutgoing,
            peerAddress = data.peerAddress,
            isPending = effectivePending,
            status = effectiveStatus,
            // B7/B8: restore the system-note flag from the id so a persisted pill renders as a
            // centered pill (not an inbound bubble), isn't counted as unread, and doesn't become
            // the chat-list preview.
            isSystemNote =
                co.electriccoin.zcash.ui.screen.chat.model.SysNotes
                    .isSystemNoteId(data.id),
            replyToId = data.replyToId,
            replyToPreview = data.replyToPreview,
            fileHash = restoredFile?.hash,
            fileZfileContent = data.fileZfileContent,
            fileBlurhash = restoredFile?.blurhash?.takeIf { it.isNotEmpty() },
            fileType = restoredFile?.type,
            fileViewOnce = restoredFile?.viewOnce ?: false,
            fileViewed = restoredFile?.let { it.viewOnce && zchatPreferences.isFileViewed(it.hash) } ?: false,
            // #210: re-apply persisted NOSTR reactions. Without this they live only in the
            // in-memory StateFlow and are wiped here on every reload.
            reactions =
                zchatPreferences.getNostrReactions(data.id).map {
                    co.electriccoin.zcash.ui.screen.chat.model.MessageReaction(
                        emoji = it.emoji,
                        senderAddress = it.senderAddress,
                        timestamp = java.time.Instant.ofEpochMilli(it.timestampMillis),
                    )
                },
            // Rebuild an inbound NOSTR payment request (amount + Pay button). isPaid is derived
            // from paidRequestIds, mirroring the live inbound builder in observeNostrInbound.
            paymentRequest =
                data.paymentRequestAmountZatoshi?.let { amt ->
                    PaymentRequestInfo(
                        amountZatoshi = amt,
                        reason = data.paymentRequestReason ?: "",
                        isPaid = paidRequestIds.value.contains(data.id),
                        paidTxId = null,
                    )
                },
            sendAmountZatoshi = data.sendAmountZatoshi,
            submitStartedAtMillis = submitStartedAt,
            submitAttemptHeight = data.submitAttemptHeight,
            submittedTxIds = data.submittedTxIds,
            legacyUntrackedSubmit =
                data.isOutgoing && !data.submitTracked && data.id.startsWith(ON_CHAIN_PENDING_PREFIX),
            // R2-7 (c): the recorded reason, or, for a send this loader fails because the app was
            // closed while it waited, that reason.
            failureReason =
                data.failureReason
                    ?: ChatSendCopy.FAILED_APP_CLOSED.takeIf { isOrphanedInFlight },
            // F4: what earlier attempts' settling left on the row.
            supersededTxIds = data.supersededTxIds,
            notSentProvenAtHeight = data.resolvedNotSentAtHeight,
            waitsForFunds = data.waitsForFunds(),
        )
    }

    /** ZC-1071: a screen of this process is still sending [rowId]. */
    private fun isSendLiveInThisProcess(rowId: String): Boolean = LiveSenders.isLive(rowId)

    /**
     * ZC-1071 (review finding 1): from the first load on, this screen is told of the rows other screens let go, until
     * it is cleared (onCleared). Registered before the caller reads the store, so no release is missed in between.
     */
    private fun watchLiveSendReleases() {
        if (viewModelScope.coroutineContext[Job]?.isActive == false) return
        LiveSenders.listen(this) { rowId, sender, replacedBy -> if (sender !== this) remapReleasedRow(rowId, replacedBy) }
    }

    /**
     * ZC-1071 (review finding 1): another screen no longer sends [rowId] (the sender updates its own bubble). A row
     * this screen still shows in flight is mapped again from the store, as the loader maps it: what its sender
     * stored (FAILED with its reason, or sent), or, stored in flight with no live sender, not sent ("ZChat was
     * closed", Retry).
     * Left as they are: a row taken up again by a screen, a row this screen does not show in flight, a row no longer
     * stored, and a row stored in flight with the transactions its submit returned (it went out; sync settles it).
     * ZC-1114: a row its sender stored again under [replacedBy] (a relay send re-keyed to `nmsg-…`) is shown under that id
     * as stored (once), no longer in flight under the old one.
     * Nothing is built, paid or written.
     */
    private fun remapReleasedRow(
        rowId: String,
        replacedBy: String? = null,
    ) {
        if (isSendLiveInThisProcess(rowId) || rowId.startsWith("tunnel-wait-")) return
        val shown = pendingMessages.value.firstOrNull { it.id == rowId } ?: return
        if (!shown.isOutgoing || !shown.isPending) return
        val storedRows = zchatPreferences.getPendingMessages()
        if (replacedBy != null && replacedBy != rowId && storedRows.none { it.id == rowId }) {
            val replacement =
                storedRows
                    .firstOrNull { it.id == replacedBy }
                    ?.let { storedPendingRowAsShown(it, rehydrateTunnelWait = false) }
            pendingMessages.update { list ->
                val alreadyShown = list.any { it.id == replacedBy }
                list.mapNotNull { m ->
                    when {
                        m.id != rowId || !m.isPending -> m
                        replacement == null || alreadyShown -> null
                        else -> replacement
                    }
                }
            }
            return
        }
        val stored = storedRows.firstOrNull { it.id == rowId } ?: return
        if (stored.isPending && stored.submittedTxIds.isNotEmpty()) return
        val remapped = storedPendingRowAsShown(stored, rehydrateTunnelWait = false)
        pendingMessages.update { list -> list.map { if (it.id == rowId && it.isPending) remapped else it } }
    }

    /**
     * ZC-1071: this screen's run of [rowId] ended. The row stays live, as waiting, while it is in this screen's queue for
     * another run, unless the screen is cleared (its queue then never runs).
     */
    private fun releaseLiveSend(rowId: String) {
        val screenAlive = viewModelScope.coroutineContext[kotlinx.coroutines.Job]?.isActive != false
        val queuedHere = screenAlive && synchronized(messageQueue) { messageQueue.any { it.pendingId == rowId } }
        if (queuedHere) LiveSenders.waiting(rowId, this) else LiveSenders.release(rowId, this)
    }

    /** Load persisted call-log entries (incoming/outgoing/missed) and merge into the message list. */
    private fun loadCallLogsFromPrefs() {
        val saved = zchatPreferences.getCallLogMessages()
        if (saved.isEmpty()) return
        val msgs = saved.map { d ->
            ChatMessage(
                id = d.id,
                txId = null,
                text = "",
                timestamp = java.time.Instant.ofEpochMilli(d.timestampMillis),
                isOutgoing = d.isOutgoing,
                peerAddress = d.peerAddress,
                isPending = false,
                status = MessageStatus.SENT,
                callLog = co.electriccoin.zcash.ui.screen.chat.model.CallLogInfo(
                    // Guard against a malformed/legacy persisted type — valueOf would throw and crash the
                    // whole call-log/message mapping. Fall back to MISSED rather than crash.
                    type = runCatching {
                        co.electriccoin.zcash.ui.screen.chat.model.CallLogType.valueOf(d.type)
                    }.getOrDefault(co.electriccoin.zcash.ui.screen.chat.model.CallLogType.MISSED),
                    isVideo = d.isVideo,
                    durationSec = d.durationSec,
                ),
            )
        }
        pendingMessages.update { current ->
            val have = current.mapTo(HashSet()) { it.id }
            current + msgs.filter { it.id !in have }
        }
        Log.d("ZCHAT_FLOW", "Loaded ${msgs.size} call-log entries from preferences")
    }

    /** Live channel for local, non-transmitted messages (call logs) injected by the service. */
    private fun observeLocalMessages() {
        viewModelScope.launch {
            co.electriccoin.zcash.ui.nostr.NostrChatBridge.localMessages.collect { msg ->
                pendingMessages.update { current ->
                    if (current.any { it.id == msg.id }) current else current + msg
                }
            }
        }
    }

    /**
     * ZC-946 part 4 (PERF-SPEC revision 2 section 4): the user's settled relay sends that ANOTHER screen stored reach this
     * view model's [pendingMessages], the pass's existing input, the way [observeLocalMessages] hands a tunnel flush to
     * every view model: the chat list loads the store once, so without this its row never showed a send made in the
     * chat. Follows [ZchatPreferences.pendingRowsVersion]; a row is taken only when [StoredRelaySends.isSettledOwnRelaySend]
     * (never one still in flight: its sender is the other view model). A row this view model holds itself is never
     * touched; a row it took follows the store's later version and leaves when the store drops it. Display path only:
     * no row is written, retried or paid here.
     */
    private fun followStoredSends(): Job =
        viewModelScope.launch {
            var taken: Set<String> = emptySet()
            ZchatPreferences.pendingRowsVersion.collect {
                // Review 19 Oct, findings 3 and 4: a message the user hid (read fresh, hideMessage / hideChat keep the
                // stored row) is never taken, and the rows are read and built here, off the main thread; only the
                // rows this view model may take (not held, or taken before) are built.
                val heldNow = pendingMessages.value.mapTo(HashSet()) { it.id }
                val takenNow = taken
                val (hidden, built) =
                    withContext(storeReadDispatcher ?: Dispatchers.IO) {
                        val hidden = zchatPreferences.getHiddenMessageIds()
                        hidden to
                            zchatPreferences
                                .getPendingMessages()
                                .filter { StoredRelaySends.isSettledOwnRelaySend(it) && it.id !in hidden }
                                .filter { it.id !in heldNow || it.id in takenNow }
                                .associate { it.id to storedRelaySendRow(it) }
                    }
                var nowTaken: Set<String> = taken
                pendingMessages.update { current ->
                    val merge = StoredRelaySends.merge(current, taken, built)
                    nowTaken = merge.taken
                    // ZC-1353: a row this screen loaded itself and another screen deleted goes too, and its chat with it.
                    merge.rows.filterNot { it.id in hidden }
                }
                taken = nowTaken
            }
        }

    /** ZC-946 part 4: a settled relay send as the loader shows it (loadPendingMessagesFromPrefs' fields for such a row). */
    private fun storedRelaySendRow(data: ZchatPreferences.PendingMessageData): ChatMessage {
        // ZC-1474: a stored free attachment (ZATT) line restores as its file card too.
        val file = data.fileZfileContent?.let { ZATTMessage.fileRefOf(it) }
        // ZC-1502: a stored ZATT line that does not parse (it holds the file key) is never shown: a fixed file label.
        val unreadableZatt = listOfNotNull(data.text, data.fileZfileContent).any { ZATTMessage.isZatt(it) && ZATTMessage.parse(it) == null }
        return ChatMessage(
            id = data.id,
            txId = null,
            text = if (unreadableZatt) attachmentFailedLabel(AttachmentKind.FILE) else data.text,
            timestamp = java.time.Instant.ofEpochMilli(data.timestampMillis),
            isOutgoing = true,
            peerAddress = data.peerAddress,
            isPending = false,
            status = data.status?.let { runCatching { MessageStatus.valueOf(it) }.getOrNull() } ?: MessageStatus.SENT,
            replyToId = data.replyToId,
            replyToPreview = data.replyToPreview,
            fileHash = file?.hash,
            fileZfileContent = data.fileZfileContent,
            fileBlurhash = file?.blurhash?.takeIf { it.isNotEmpty() },
            fileType = file?.type,
            fileViewOnce = file?.viewOnce ?: false,
            fileViewed = file?.let { it.viewOnce && zchatPreferences.isFileViewed(it.hash) } ?: false,
            reactions =
                zchatPreferences.getNostrReactions(data.id).map {
                    co.electriccoin.zcash.ui.screen.chat.model.MessageReaction(
                        emoji = it.emoji,
                        senderAddress = it.senderAddress,
                        timestamp = java.time.Instant.ofEpochMilli(it.timestampMillis),
                    )
                },
            failureReason = data.failureReason,
        )
    }

    /** R2-2 (b) — the rule doSendMessage uses to send our KEX before a message, read before anything is stored. */
    private fun firstOnChainMessageNeedsKex(
        peerAddress: String,
        message: String,
    ): Boolean =
        zchatPreferences.getE2EOurPublicKey(peerAddress) == null &&
            !ZBootMessage.isBootMessage(message) &&
            !ZMSGProtocol.isKEXMessage(message) &&
            !ZMSGProtocol.isKEXAckMessage(message) &&
            !seedKeyProvider.isKeyCreationWaitingForHistory(peerAddress)

    /**
     * Whether the next message to [peerAddress] is the v4 INIT: no conversation id yet, or one whose INIT was
     * never submitted. B2 (Grok H1): the SAME question the send asks (getOrCreateConversationIdForMessage's
     * second value). Asking only "does an id exist?" priced a REPLY once a control (timer, mode change, ZBOOT,
     * rotation announce) had taken the id, while the confirmed send built the longer INIT.
     */
    private fun isFirstMessageTo(peerAddress: String): Boolean =
        zchatPreferences.needsConversationInit(peerAddress) ||
            // ZC-1480 item 3: an INIT the relays carried and the chain still owes (getOrCreateConversationIdForMessage).
            zchatPreferences.getConversationIdOwedInitOnChain(peerAddress) != null

    /**
     * R8-fixup F1 (REVIEW_R8 F1) — how many memos the on-chain builder packs [text] to [peerAddress] into, as doSendMessage
     * and sendReply send it: the ratchet's ciphertext when both keys are held (an E2E1 wire of exactly the same length:
     * AES-GCM adds a 16-byte tag, the header is fixed), the text itself otherwise; sized as the INIT or a reply the way
     * the send decides it.
     */
    private fun onChainMemoCount(
        peerAddress: String,
        text: String,
    ): Int {
        val self = _currentUserAddress.value
        // A short text fits one memo whatever the keys: skip the preference reads (the composer asks per keystroke).
        if (onChainMemoCountFor(text, encrypted = true, isInit = true, self = self) <= 1) return 1
        val encrypted =
            zchatPreferences.getE2EOurPublicKey(peerAddress) != null && zchatPreferences.getE2EPeerPublicKey(peerAddress) != null
        return onChainMemoCountFor(text, encrypted, isFirstMessageTo(peerAddress), self)
    }

    /**
     * Round 10a F-R9P-1 — what the composer's cost row shows for [text] typed to [peerAddress]: the least the on-chain send
     * costs, sized by the same rule the send's own cost question uses ([onChainMemoCount]: the encrypted wire when both
     * keys are held, the INIT or a reply, our address), a reply with its reply reference ([tagReply]) exactly as
     * [sendReply] sizes it. Outputs, platform fee and network fee; still a floor ("at least"), since a wallet whose balance
     * sits in several notes pays a larger network fee.
     */
    fun composerMessageCost(
        peerAddress: String,
        text: String,
        amountPerOutput: Long,
        replyToId: String? = null,
        replyPreview: String = "",
    ): Zatoshi {
        val capped = if (text.length > MAX_MESSAGE_INPUT_CHARS) capDraft(text) else text
        val sized =
            if (replyToId != null) {
                val preview = replyPreview.ifBlank { findMessageById(replyToId)?.displayText?.take(50) ?: "" }
                tagReply(replyToId, capped, preview)
            } else {
                capped
            }
        // Round 10b R10B-1 (F-R9C-4): a first message in a Shielded chat is asked about with its key exchange (and our
        // ZBOOT when it must go on-chain); the row shows that same total.
        if (zchatPreferences.getConversationMode(peerAddress) == co.electriccoin.zcash.ui.screen.chat.model.ConversationMode.VAULT &&
            firstOnChainMessageNeedsKex(peerAddress, sized)
        ) {
            return firstMessageQuote(peerAddress, sized, amountPerOutput).total
        }
        return onChainSendMinimumCost(onChainMemoCount(peerAddress, sized), Zatoshi(amountPerOutput))
    }

    /** Round 10b R10B-1 — what the first on-chain message to a contact is quoted as ([firstMessageQuote]). */
    private data class FirstMessageQuote(
        val transactions: Int,
        val total: Zatoshi,
        /** Our on-chain ZBOOT after the contact's KEXACK is part of it (their relay key is unknown). */
        val includesZboot: Boolean,
    )

    /**
     * Round 10b R10B-1 (F-R9C-1, F-R9C-4) — the one quote rule for a first on-chain message of [text] to [peerAddress]:
     * our KEX, then the message (sized by [onChainMemoCount], the send's own rule), then, when the contact's relay key is
     * unknown or the relays are not ready, our ZBOOT: a first-contact KEXACK never carries the relay key, so after it
     * the ZBOOT can only go on-chain. The question, the composer row and the ZBOOT's allowance all use it.
     */
    private fun firstMessageQuote(
        peerAddress: String,
        text: String,
        amountPerOutput: Long,
    ): FirstMessageQuote {
        val kexLeg = onChainSendMinimumCost()
        val messageLeg = onChainSendMinimumCost(onChainMemoCount(peerAddress, text), Zatoshi(amountPerOutput))
        val zbootOnChain = zchatPreferences.getPeerNostrPubkey(peerAddress) == null || !NostrChatBridge.isOutboundReady()
        return if (zbootOnChain) {
            FirstMessageQuote(3, kexLeg + messageLeg + onChainSendMinimumCost(), includesZboot = true)
        } else {
            FirstMessageQuote(2, kexLeg + messageLeg, includesZboot = false)
        }
    }

    /**
     * M2 (fix-all 2.13.0) — the plan check for a first message of [memos] memos at [amountZatoshi] to [peerAddress]:
     * can the wallet pay both our KEX and the message? Whatever it cannot answer is [FirstMessagePlan.Unchecked], a
     * thrown error included, and so is a check that was never set (a ViewModel built without one holds null there):
     * fail closed, never "fundable".
     */
    @Suppress("TooGenericExceptionCaught")
    private suspend fun checkFirstMessagePlan(
        peerAddress: String,
        memos: Int,
        amountZatoshi: Long,
    ): FirstMessagePlan =
        try {
            firstMessagePlanCheck.check(peerAddress, memos, Zatoshi(amountZatoshi))
        } catch (e: kotlinx.coroutines.CancellationException) {
            throw e
        } catch (e: Exception) {
            Log.w("ZCHAT_SEND", "First-message plan not checked: ${e.javaClass.simpleName}")
            FirstMessagePlan.Unchecked(e)
        }

    /**
     * M2 — what a refused first-message plan shows. [row]: the text stands above Retry on a queued or retried row (or a
     * send whose typed text is not handed back), so it names Retry instead of the input box. A Keystone or own-address
     * refusal from the check shows its own text.
     */
    private fun firstMessagePlanRefusal(
        plan: FirstMessagePlan,
        row: Boolean,
    ): String =
        when (plan) {
            FirstMessagePlan.WaitForFunds -> CreateChunkedMessageProposalUseCase.PENDING_BALANCE_WAIT_MESSAGE
            is FirstMessagePlan.Unchecked ->
                when (val cause = plan.cause) {
                    is co.electriccoin.zcash.ui.screen.chat.usecase.KeystoneChatSendRefusedException,
                    is co.electriccoin.zcash.ui.screen.chat.usecase.OwnAddressChatSendRefusedException,
                    -> cause.toZchatUserMessage(ChatSendCopy.FIRST_MESSAGE_PLAN_UNCHECKED)
                    else -> {
                        // ZC-782: the update refusal (also as a cause) shows the update sentence, not "try again".
                        val unchecked =
                            if (row) ChatSendCopy.FIRST_MESSAGE_PLAN_UNCHECKED_ROW else ChatSendCopy.FIRST_MESSAGE_PLAN_UNCHECKED
                        val update = co.electriccoin.zcash.ui.common.model.NetworkUpgradeRequiredException.MESSAGE
                        if (cause?.toZchatUserMessage(unchecked) == update) update else unchecked
                    }
                }
            else -> if (row) ChatSendCopy.FIRST_MESSAGE_PLAN_UNFUNDABLE_ROW else ChatSendCopy.FIRST_MESSAGE_PLAN_UNFUNDABLE
        }

    /**
     * FC-ID (ZC-892; FIRST-CONTACT-SPEC 5.3a item 4) — where a send that pays our KEX is planned and priced, before its
     * memos are counted: the id it goes out under is one this phone made for [peerAddress]
     * ([ZchatPreferences.ownConversationIdForStart]). Null (logged) when it could not be saved; [buildKexMemo] then sends
     * nothing.
     */
    private fun planOwnConversationId(peerAddress: String): String? =
        zchatPreferences.ownConversationIdForStart(peerAddress).also {
            if (it == null) {
                Log.w("KEX", "No own conversation id could be saved for ${peerAddress.redactAddress()}: no key exchange goes out")
            }
        }

    /**
     * M2 — whether a message to [peerAddress] pays our KEX first, as doSendMessage decides it: we hold no key for the
     * contact (and the history is not being read), or the selected account still owes the KEX and paying it now would
     * spend ([owedKexWouldPay]).
     */
    private suspend fun messageOwesKexFirst(peerAddress: String): Boolean =
        if (zchatPreferences.getE2EOurPublicKey(peerAddress) == null) {
            !seedKeyProvider.isKeyCreationWaitingForHistory(peerAddress)
        } else {
            kexOwedPeers.contains(peerAddress) &&
                owedKexBelongsToSelectedAccount(peerAddress, whenUnknown = true) &&
                owedKexWouldPay(peerAddress)
        }

    /**
     * ZC-285, ZC-300 — whether the KEX owed to [peerAddress] was quoted alone (a confirmed Reset encryption or key-change
     * reconnect), not as the first half of a first message. An unreadable reason reads as a first message.
     */
    private fun owedKexIsLone(peerAddress: String): Boolean {
        val reason = owedKexReason(peerAddress)
        return reason == ZchatPreferences.KEX_OWED_REASON_RESET || reason == ZchatPreferences.KEX_OWED_REASON_RECONNECT
    }

    /** ZC-285 — why the KEX to [peerAddress] is owed (null: a first message's, or the reason could not be read). */
    @Suppress("TooGenericExceptionCaught")
    private fun owedKexReason(peerAddress: String): String? =
        try {
            zchatPreferences.getKexOwedReason(peerAddress)
        } catch (e: Exception) {
            Log.w("KEX", "Owed KEX reason not read: ${e.javaClass.simpleName}")
            null
        }

    /**
     * M2 — false when the owed KEX to [peerAddress] would settle without a payment (payOwedKex's ALREADY_DELIVERED):
     * the exchange is complete, or a KEX carrying our current key was paid recently.
     *
     * ZC-535: a key-change reconnect's KEX is sent whatever the completeness says (the contact's stored key is the old
     * one), so for that owed reason only the last-hour rule can settle it. The rule itself is [kexSettlesUnpaid].
     */
    private fun owedKexWouldPay(peerAddress: String): Boolean {
        val ourKey = zchatPreferences.getE2EOurPublicKey(peerAddress) ?: return true
        val reconnect = owedKexReason(peerAddress) == ZchatPreferences.KEX_OWED_REASON_RECONNECT
        return !kexSettlesUnpaid(peerAddress, ourKey, reconnect) && !owedKexWasSubmitted(peerAddress, ourKey)
    }

    /**
     * ZC-626 — a KEX carrying [sentKey] was already submitted (or may have been) for the mark that still owes it to
     * [peerAddress]: its paid record is on disk, at any age. That record is stamped before the submit and withdrawn only
     * when the attempt provably sent nothing, and a new confirm removes an expired one before it pays
     * ([forgetExpiredKexPaidRecord]). So a mark whose clear was not saved never pays the same key exchange again after
     * the hour; the hour alone must not be what guards a stuck mark. Only asked while a mark is owed.
     */
    private fun owedKexWasSubmitted(
        peerAddress: String,
        sentKey: String,
    ): Boolean =
        HandshakePaidRecord.names(
            zchatPreferences.getHandshakePaidRecord(HandshakePaidRecord.slot(AutomaticSetupKind.KEX, peerAddress)),
            sentKey,
        )

    /**
     * ZC-626 — a new confirm of a KEX to [peerAddress] (a key-change reconnect after the hour re-sends the same key):
     * the paid record an earlier confirm left for our current key, once it is older than the hour, is removed, so
     * [owedKexWasSubmitted] reads only this confirm's own stamp. A record inside the hour stays (that KEX is not quoted
     * and not paid again). @return false only when the removal was not saved.
     */
    private fun forgetExpiredKexPaidRecord(peerAddress: String): Boolean {
        val ourKey = zchatPreferences.getE2EOurPublicKey(peerAddress) ?: return true
        if (!owedKexWasSubmitted(peerAddress, ourKey)) return true
        if (paidSetupCooldown(AutomaticSetupKind.KEX, peerAddress, ourKey) > 0L) return true
        return zchatPreferences.setHandshakePaidRecord(HandshakePaidRecord.slot(AutomaticSetupKind.KEX, peerAddress), null)
    }

    /**
     * ZC-536 — whether the confirmed action that wrote [peerAddress]'s quoted-ZBOOT allowance is still at its key
     * exchange: a KEX is owed (a Reset, a reconnect, a first message), or a reconnect is running.
     */
    private fun quotedActionAtItsKex(peerAddress: String): Boolean =
        kexOwedPeers.contains(peerAddress) ||
            reconnectsInFlight.contains(peerAddress) ||
            runCatching { zchatPreferences.isKexOwed(peerAddress) }.getOrDefault(true)

    /**
     * ZC-535 — the one rule for "a KEX carrying [sentKey] to [peerAddress] needs no payment now", shared by the spend
     * ([payOwedKex], before every attempt), the first-message plan ([owedKexWouldPay]) and the reconnect's question
     * ([reconnectPlan]), so the three can never disagree:
     * - the contact's reply completed the exchange; this does not apply to a key-change [reconnect], where the
     *   exchange reads as complete only because the contact's old key is still stored;
     * - a Reset replaced the key this KEX carries;
     * - a KEX carrying this key was paid within the cooldown (never twice).
     */
    private fun kexSettlesUnpaid(
        peerAddress: String,
        sentKey: String,
        reconnect: Boolean,
    ): Boolean =
        (!reconnect && zchatPreferences.isE2EKeyExchangeComplete(peerAddress)) ||
            zchatPreferences.getE2EOurPublicKey(peerAddress) != sentKey ||
            paidSetupCooldown(AutomaticSetupKind.KEX, peerAddress, sentKey) > 0L

    /**
     * ZC-535 — what a key-change reconnect of [peerAddress] would pay now: our key exchange ([kex]) and our relay
     * identity ([zboot]), each only when it is due. [count] is what the question quotes.
     */
    private data class ReconnectPlan(
        val kex: Boolean,
        val zboot: Boolean,
        val openKexSkipped: Boolean = false,
        val openZbootSkipped: Boolean = false,
    ) {
        val count: Int get() = (if (kex) 1 else 0) + (if (zboot) 1 else 0)
    }

    /**
     * ZC-535 — the plan of a key-change reconnect, read when × is tapped and again at Pay; it writes nothing.
     * - The KEX is due when we hold no key for the contact yet or [kexSettlesUnpaid] says it would be paid (a KEX of
     *   this key paid in the last hour is not sent again).
     * - The ZBOOT is due unless a ZBOOT carrying our current relay identity was paid in the last hour. An identity
     *   that cannot be read counts as due, as the question counted it before.
     */
    private suspend fun reconnectPlan(
        peerAddress: String,
        offer: ZchatPreferences.RefusedKeyOffer? = null,
    ): ReconnectPlan {
        val ourKey = zchatPreferences.getE2EOurPublicKey(peerAddress)
        val kexDue = ourKey == null || !kexSettlesUnpaid(peerAddress, ourKey, reconnect = true)
        // ZC-545: the accept of a remembered key in a Shielded chat. A key that came in a KEX means the contact
        // started a new exchange and needs our key: our KEX, under the same last-hour rule. A key that came in a KEXACK
        // answered our KEX: the contact holds our key and nothing is due. No relay identity is sent in Shielded.
        if (offer != null &&
            zchatPreferences.getConversationMode(peerAddress) == co.electriccoin.zcash.ui.screen.chat.model.ConversationMode.VAULT
        ) {
            return ReconnectPlan(kex = kexDue && !ZMSGProtocol.isKEXAckMessage(offer.memo), zboot = false)
        }
        val identity = getOurNostrPubkey()?.first
        val zbootDue = identity == null || paidSetupCooldown(AutomaticSetupKind.ZBOOT, peerAddress, identity) <= 0L
        if (openNeverSpends(peerAddress)) {
            return ReconnectPlan(kex = false, zboot = false, openKexSkipped = kexDue, openZbootSkipped = zbootDue)
        }
        return ReconnectPlan(kex = kexDue, zboot = zbootDue)
    }

    /**
     * M2 — the plan of an owed KEX paid on a block or a chat open: the KEX and the message that follows it, sized as the
     * contact's queued FAILED on-chain row (one memo at the default amount when there is none).
     */
    @Suppress("TooGenericExceptionCaught")
    private suspend fun owedKexPlan(peerAddress: String): FirstMessagePlan {
        // FC-ID (5.3a item 4): the KEX and the message after it are counted under an own-made id.
        planOwnConversationId(peerAddress)
        val row =
            try {
                zchatPreferences.getPendingMessages().firstOrNull {
                    it.peerAddress == peerAddress &&
                        it.isOutgoing &&
                        it.status == MessageStatus.FAILED.name &&
                        it.id.startsWith(ON_CHAIN_PENDING_PREFIX)
                }
            } catch (e: Exception) {
                return FirstMessagePlan.Unchecked(e)
            }
        val memos = row?.let { onChainMemoCount(peerAddress, it.text) } ?: 1
        return checkFirstMessagePlan(peerAddress, memos, row?.sendAmountZatoshi ?: DEFAULT_MESSAGE_AMOUNT)
    }

    /** R8-fixup F1 — the question before an on-chain message of [memos] memos: one transaction, every memo counted. */
    private fun longMessageConfirmation(
        memos: Int,
        amountZatoshi: Long,
    ): PaidActionConfirmation =
        PaidActionConfirmation(
            PaidAction.LONG_MESSAGE,
            onChainMessages = 1,
            totalCost = onChainSendMinimumCost(memos, Zatoshi(amountZatoshi)),
        )

    /**
     * Returns true if [resolvedPeerAddress] is a real Zcash address (unified u1... or sapling
     * zs...), i.e. routing successfully resolved the message to a recognizable peer.
     *
     * When this is true the "Unknown sender" banner must be suppressed even if the protocol parser
     * flagged a reason in isolation (HASH_NOT_IN_CACHE on cold start, VERSION_MISMATCH on a legacy
     * prefix), because routing mapped it to an established peer via the authenticated convId/contact
     * mapping. When false (routing fell back to a hash, raw convId, or "unknown"), the banner stays.
     *
     * This mirrors the address-validity heuristic the chat view uses to gate the banner.
     */
    private fun isResolvedToKnownPeer(resolvedPeerAddress: String): Boolean {
        return (resolvedPeerAddress.startsWith("u1") && resolvedPeerAddress.length > 100) ||
            (resolvedPeerAddress.startsWith("zs") && resolvedPeerAddress.length > 70)
    }

    /**
     * Round 8 P3 (PHONE_TRIAGE F1): the sender of a time-locked (ZTL|) or payment-request (ZREQ|) memo, as
     * (address the hash cache knows, or null; sender hash). parseMemo returns no sender for either, so the router
     * falls back to this. (null, null) for any other memo.
     */
    private fun specialMemoSender(memoText: String): Pair<String?, String?> =
        when {
            ZMSGProtocol.isTimeLock(memoText) ->
                ZMSGProtocol.parseTimeLock(memoText, addressCache)?.let { it.senderAddress to it.senderHash }
            ZMSGProtocol.isPaymentRequest(memoText) ->
                ZMSGProtocol.parsePaymentRequest(memoText, addressCache)?.let { it.senderAddress to it.senderHash }
            else -> null
        } ?: (null to null)

    private fun loadUserStatus() {
        val statusText = zchatPreferences.getUserStatus()
        val statusTimestamp = zchatPreferences.getUserStatusTimestamp()
        _userStatus.value = if (statusText.isNotBlank()) {
            UserStatus(statusText, Instant.ofEpochMilli(statusTimestamp))
        } else {
            UserStatus.DEFAULT
        }
    }

    private fun loadPeerStatuses() {
        val storedStatuses = zchatPreferences.getAllPeerStatuses()
        peerStatuses.value = storedStatuses.mapValues { (_, status) ->
            UserStatus(status)
        }
    }

    private fun observeBlockHeight() {
        viewModelScope.launch {
            try {
                val synchronizer = synchronizerProvider.getSynchronizer()
                synchronizer.networkHeight.collect { height ->
                    _blockHeight.value = height?.value
                    // ZC-114: the last tip, for minute estimates shown without a height of their own.
                    height?.value?.let { ChainTiming.lastTip = it }
                    onChainTip(height?.value)
                }
            } catch (_: Exception) {
                // Silently fail - block height is optional
            }
        }
        // Remote-kill floor: anchored from the chain tip and the wallet's own history, never from a
        // transaction offered to the kill check. Off the main thread: the anchor write is a commit().
        viewModelScope.launch(Dispatchers.Default) {
            try {
                combine(_blockHeight, transactionRepository.transactions) { tip, transactions ->
                    tip to transactions
                }.collect { (tip, transactions) ->
                    // Cheap plain-prefs read first, so an install without remote kill enabled does
                    // nothing more per emission.
                    if (!zchatPreferences.isRemoteKillEnabled()) return@collect
                    anchorRemoteKillFloorIfUnset(
                        tip = tip,
                        historyMinedHeights = transactions?.mapNotNull { it.overview.minedHeight?.value },
                    )
                }
            } catch (e: Exception) {
                if (e is kotlinx.coroutines.CancellationException) throw e
                // Fails CLOSED: with no floor the kill check never wipes.
                Log.w("ChatViewModel", "remote-kill floor anchor stopped: ${e.javaClass.simpleName}")
            }
        }
    }

    /** The work each new chain tip (about once per block) drives; see [observeBlockHeight]. */
    private fun onChainTip(height: Long?) {
        // Round 8 P1 (PHONE_TRIAGE F3): no tip sends a group reply. The first tip after a start turns each reply an
        // earlier build held for the consent (R3-4) into an invite that waits for Join, and pays nothing.
        restoreHeldGroupAccepts()
        // ZC-1271: a first message whose price was accepted goes before the automatic setups that compete for the note.
        resumeFundsWaitRows()
        retryPendingTunnelZboots(height)
        // ZC-420: our relay identity that only a public relay took, one contact per block, over the relays only.
        repairUnconfirmedRelayIdentities(height)
        // R9-2: a KEX confirmed with a first message and not sent yet (the screen closed, the process ended, funds were
        // confirming) goes on a later block, with no screen open and no second question.
        retryOwedKeyExchanges(height)
        // ZC-1334: and one New Chat's question covered, which has a leg on disk and no owed mark.
        payCoveredKeyExchange(height)
        // ZC-1338: and an Accept tapped while the funds confirmed.
        resumeAcceptsWaitingForFunds()
        // M3 (ZC-110): setups queued while the wallet could not pay one handshake are asked about once it can. Asks only.
        raiseHandshakeQuestionWhenFunded()
    }

    /**
     * ZC-420 — the chat-open half of the relay-identity repair, in every mode. A ZBOOT or a relay-key announce to
     * [peerAddress] that only a public relay took (one a ZChat 2.12.4 contact does not read) left a durable mark; this
     * confirms that copy from the wrap the relay outbox keeps, or delivers our current relay identity to the contact once
     * more over the relays. Free: it never pays and never asks. A contact with no mark costs one read of the mark.
     */
    fun repairUnconfirmedRelayIdentity(peerAddress: String) {
        if (!NostrChatBridge.isOutboundReady() || !NostrChatBridge.relayCopyMarksReady()) return
        viewModelScope.launch {
            if (NostrChatBridge.relayCopyExtra(RelayCopySlots.identity(peerAddress)) == null) return@launch
            repairUnconfirmedRelayIdentityNow(peerAddress)
        }
    }

    /**
     * ZC-420 — the block-tick half: at most one marked contact per block, picked by [height] as the Tunnel identity retry
     * picks, so a contact that cannot be repaired now never starves the others. The marks are listed off the main thread
     * (a listing decrypts the whole store); the pick and the repair then run where the identity sender runs.
     */
    private fun repairUnconfirmedRelayIdentities(height: Long?) {
        if (!NostrChatBridge.isOutboundReady() || !NostrChatBridge.relayCopyMarksReady()) return
        viewModelScope.launch {
            val peers =
                withContext(Dispatchers.Default) {
                    NostrChatBridge.unconfirmedRelayCopies(RelayCopySlots.identity(""))
                }.mapNotNull(RelayCopySlots::peerOf)
                    .distinct()
                    .sorted()
            if (peers.isEmpty()) return@launch
            repairUnconfirmedRelayIdentityNow(peers[((height ?: 0L).mod(peers.size.toLong())).toInt()])
        }
    }

    /**
     * ZC-420 — the gates of the relay-identity repair, in order; "kept" means the mark stays for a later try. Kept while
     * a Keystone account is selected, while a mark written before its publish is younger than a minute (that publish may
     * still run), while the identity sender holds the contact, while the seed is not ready, and while the contact's relay
     * key is missing (a key-change reconnect clears it; the next key exchange brings it back). Forgotten for one of our
     * own addresses, a contact whose E2E keys are gone (a Reset), a contact with no chat (a deleted one: nothing here
     * makes a conversation id) and a delivered-identity marker that was re-armed (the sender owns that identity again).
     * A marker of another identity while the mark names our current one is an announce that did not finish for this
     * contact: it runs again, free, and writes its own mark and marker. Otherwise our current identity is confirmed or
     * re-delivered over the relays; a mark of an older identity is first turned into one of the current identity, so
     * the kept wrap of the old one is never used.
     */
    private suspend fun repairUnconfirmedRelayIdentityNow(peerAddress: String) {
        val slot = RelayCopySlots.identity(peerAddress)
        if (!NostrChatBridge.isOutboundReady() || NostrChatBridge.relayCopyExtra(slot) == null) return
        if (keystoneAccountSelected()) return
        if (NostrChatBridge.relayCopyJustBegun(slot, RELAY_IDENTITY_PUBLISH_GRACE_MS)) return
        if (!nostrBootInFlight.add(peerAddress)) return
        try {
            val (ourPub, relay) = getOurNostrPubkey() ?: return
            val markedFor = NostrChatBridge.relayCopyExtra(slot) ?: return
            val forgetWhy =
                when {
                    zchatPreferences.isSelfAddress(peerAddress) -> "one of our own addresses"
                    zchatPreferences.getE2EPrivateKey(peerAddress) == null -> "no E2E keys for the contact"
                    zchatPreferences.getConversationId(peerAddress) == null -> "no chat with the contact"
                    else -> null
                }
            if (forgetWhy != null) {
                NostrChatBridge.forgetRelayCopy(slot)
                Log.d("ZCHAT_NOSTR", "RelayCopy: zb mark of ${peerAddress.take(16)}… dropped: $forgetWhy")
                return
            }
            val marker = zchatPreferences.getSentNostrBootPubkey(peerAddress)
            when {
                marker == null || (marker != ourPub && markedFor != ourPub) -> {
                    NostrChatBridge.forgetRelayCopy(slot)
                    Log.d("ZCHAT_NOSTR", "RelayCopy: zb mark of ${peerAddress.take(16)}… dropped: the sender owns that identity")
                }
                marker != ourPub -> {
                    if (zchatPreferences.getPeerNostrPubkey(peerAddress) == null) return
                    val announced = announceRotationOverNostr(peerAddress, ourPub, relay)
                    Log.d("ZCHAT_NOSTR", "RelayCopy: relay-key announce to ${peerAddress.take(16)}… run again (taken: $announced)")
                }
                else -> {
                    // ZC-739: our ZBOOT is not handed over while the contact's new key waits for the user; the mark stays.
                    if (zchatPreferences.isE2EKeyChanged(peerAddress)) return
                    val peerKey = zchatPreferences.getPeerNostrPubkey(peerAddress) ?: return
                    if (markedFor != ourPub) NostrChatBridge.beginRelayCopy(slot, extra = ourPub)
                    val outcome = NostrChatBridge.repairRelayCopy(slot, peerKey) { ownZbootMemo(peerAddress) }
                    Log.d("ZCHAT_NOSTR", "RelayCopy: zb repair for ${peerAddress.take(16)}…: $outcome")
                }
            }
        } catch (e: Exception) {
            if (e is kotlinx.coroutines.CancellationException) throw e
            Log.w("ZCHAT_NOSTR", "RelayCopy: zb repair failed: ${e.javaClass.simpleName}")
        } finally {
            nostrBootInFlight.remove(peerAddress)
        }
    }

    /**
     * ZC-420 — our current relay identity for [peerAddress], as the relay-first ZBOOT carries it (version 3, signed with
     * our E2E key for the contact, the epoch = the rotation index the key is derived at), for the repair; null when a part
     * is missing. It reads the conversation id and never makes one.
     */
    private suspend fun ownZbootMemo(peerAddress: String): String? {
        val ourPriv = zchatPreferences.getE2EPrivateKey(peerAddress) ?: return null
        val identity = deriveOurNostrIdentity() ?: return null
        val convId = zchatPreferences.getConversationId(peerAddress) ?: return null
        return zbootMemoFor(convId, ourPriv, identity.publicKey, identity.relay, identity.rotation.toLong())
    }

    /** ZC-420 — the signed version-3 ZBOOT of [ourNostrPub] for [convId]: the builder lines the identity sender used. */
    private fun zbootMemoFor(
        convId: String,
        ourPriv: String,
        ourNostrPub: String,
        ourRelay: String,
        epoch: Long,
    ): String {
        val signedData =
            co.electriccoin.zcash.ui.screen.chat.model.ZBootMessage
                .signedDataFor(convId, ourNostrPub, ourRelay, epoch)
        val sig = E2EEncryption.sign(ourPriv, signedData)
        return co.electriccoin.zcash.ui.screen.chat.model
            .ZBootMessage(convId, ourNostrPub, ourRelay, sig, epoch = epoch)
            .serialize()
    }

    /**
     * Anchor the remote-kill floor (see [ZchatPreferences.getRemoteKillArmedHeight]) when none is
     * recorded. No build has ever had a way to arm remote kill (DestroyManager.setupRemoteKill has no
     * caller), so an armed install necessarily has floor 0 and this is the ONLY floor writer that runs.
     *
     * The floor is `maxOf(tip, highest mined height in the wallet's history)`. The tip alone is not
     * enough: SDK 3.0.0 publishes lightwalletd's GetLatestBlock reply to networkHeight unclamped, so a
     * lagging server can report a tip BELOW transactions the wallet already holds, which would leave an
     * old matching transaction above the floor to wipe the wallet on a later scan. Every transaction
     * already in the history is by definition not a new signal, so the floor must cover all of them.
     * Unmined (mempool) transactions have no height and are not counted: they land above the floor
     * when mined and are judged then, which is what lets a live signal fire.
     *
     * Fails CLOSED: nothing is written until the tip is known AND the history has loaded
     * ([historyMinedHeights] is null until then); meanwhile the kill check returns without consuming
     * anything.
     */
    private fun anchorRemoteKillFloorIfUnset(tip: Long?, historyMinedHeights: List<Long>?) {
        if (!zchatPreferences.isRemoteKillEnabled()) return
        if (!zchatPreferences.hasRemoteKillPhrase()) return
        if (zchatPreferences.getRemoteKillArmedHeight() > 0L) return
        if (tip == null || tip <= 0L) return
        if (historyMinedHeights == null) return
        zchatPreferences.setRemoteKillArmedHeight(maxOf(tip, historyMinedHeights.maxOrNull() ?: 0L))
    }

    /**
     * Tunnel peers whose key exchange is complete and whose ZBOOT has not gone out (HS-6 quote input). ZC1013-X1: the
     * model's rule, which the turn-on confirm in Advanced Settings quotes too.
     */
    private fun zbootDuePeers(): Set<String> =
        runCatching {
            // ZC-739: a contact whose new key waits for the user is held, so it is not counted either (the model's rule
            // without it stays the Advanced Settings quote, never lower than this question's).
            co.electriccoin.zcash.ui.screen.chat.model
                .zbootDuePeers(zchatPreferences)
                .filterTo(HashSet()) { peer -> !zchatPreferences.isE2EKeyChanged(peer) }
        }.getOrDefault(emptySet())

    /**
     * HS-6: the user opened a chat, a deliberate gesture, so a setup they answered "Not now" to may ask once
     * more. Automatic retries (every block, every scan) never clear the declined set on their own.
     */
    fun askAgainForHandshakeConsent() {
        dismissedAutomaticSetups.clear()
    }

    /** R2-2 (b) — the paid tap waiting for [confirmPaidAction]; null when nothing waits. */
    @Volatile private var pendingPaidAction: (() -> Unit)? = null

    /** R3-2 (2) — what [dismissPaidAction] undoes for the waiting tap (a first message's typed text); null for none. */
    @Volatile private var pendingPaidDecline: (() -> Unit)? = null

    /** R3-2 (2) — text a cancelled cost prompt hands back to the chat input of [peerAddress]. */
    data class RestoredTypedText(
        val peerAddress: String,
        val text: String,
    )

    private val _restoredTypedText = MutableStateFlow<RestoredTypedText?>(null)

    /**
     * R3-2 (2) — the typed text of a first message whose cost prompt was cancelled. The chat screen cleared its
     * input when the send was accepted behind the prompt; it puts this text back and calls
     * [consumeRestoredTypedText]. The same text is also the chat's saved draft again.
     */
    val restoredTypedText: StateFlow<RestoredTypedText?>
        get() = _restoredTypedText

    /** R3-2 (2) — the chat input has taken [restoredTypedText]; do not hand it back again. */
    fun consumeRestoredTypedText() {
        _restoredTypedText.value = null
    }

    private fun askBeforePaying(
        action: PaidAction,
        onChainMessages: Int,
        pay: () -> Unit,
    ) = askBeforePaying(paidActionConfirmation(action, onChainMessages), pay = pay)

    /**
     * ZC-1822 (QA2 k1c), ZC-1834/ZC-1836 (QA2 k1c2) — the ZC-1417 margin rule before a price question for one on-chain
     * transaction of [cost]. A wallet whose confirmed Ironwood ([WalletAccount.peerSpendableBalance]) fails
     * [spendableCovers] (neither exactly the cost nor at least the cost plus the marginal fee) is not asked a price its Pay
     * cannot pay: it is told what it has and what this needs (the have/need text, [spendableNeed]), and true is returned;
     * nothing is stored, built or paid, and the caller refuses as its other refusals do.
     *
     * False (ask as before, the build decides) when:
     * - the account is not known yet: no selected account, or the synchronizer has not published its balances
     *   ([co.electriccoin.zcash.ui.common.model.UnifiedInfo.balancesPublished] false, ZC-1834; the empty figures are
     *   then placeholders, not a zero);
     * - waiting would cover the cost: confirmed plus confirming Ironwood meets [spendableCovers] (ZC-1836; confirming funds
     *   that would still fall short do not switch the rule off);
     * - the shielded-funds dialog answers the send ([shieldedFundsRefusal]).
     */
    private fun refusedByTheSpendableMargin(
        cost: Zatoshi,
        account: WalletAccount? = selectedAccountNow(),
    ): Boolean {
        val payer = account ?: return false
        if (!payer.unified.balancesPublished) return false
        val have = payer.peerSpendableBalance
        if (spendableCovers(have.value, cost.value)) return false
        val ironwood = payer.unified.ironwood
        val confirming = ironwood.changePending.value + ironwood.valuePending.value
        if (confirming > 0L && spendableCovers(have.value + confirming, cost.value)) return false
        if (shieldedFundsRefusal() != null) return false
        Log.w("ZCHAT_SEND", "ZC-1822: the spendable value cannot pay this transaction — not asked, nothing stored or paid")
        _sendMessageState.value = SendMessageState.Error(ChatSendCopy.messageShortfall(have, spendableNeed(have, cost)))
        return true
    }

    /**
     * R2-2 (b) — show [confirmation] and keep [pay] until the user confirms; nothing is paid here. R3-2 (2):
     * [onDecline] runs once if the user cancels instead (a first message gives its typed text back).
     *
     * T5b X-05: a question that was still open is replaced by this one, and that reads as Cancel for the tap that was
     * waiting: its undo runs once, after this question is in place (a first message's text is the draft again and is
     * handed back, a file bubble is left FAILED for Retry). Before this the waiting tap and its undo were only
     * overwritten, and the text was neither sent nor handed back.
     */
    private fun askBeforePaying(
        confirmation: PaidActionConfirmation,
        onDecline: (() -> Unit)? = null,
        pay: () -> Unit,
    ) {
        // SR-A (R-A4): a question an attachment is waiting on that this one replaces reads as Cancel (nothing uploaded).
        swapPaidAnswer(null)?.complete(false)
        val replacedDecline = pendingPaidDecline
        pendingPaidAction = pay
        pendingPaidDecline = onDecline
        _sendMessageState.value = SendMessageState.NeedsPaidActionConfirmation(confirmation)
        if (replacedDecline != null && replacedDecline !== onDecline) replacedDecline()
    }

    /** SR-A — the answer a waiting attachment's exact price question is awaited with ([awaitPaidAnswer]); null when none. */
    @Volatile private var pendingPaidAnswer: CompletableDeferred<Boolean>? = null

    private fun swapPaidAnswer(next: CompletableDeferred<Boolean>?): CompletableDeferred<Boolean>? =
        synchronized(paidAnswerLock) { pendingPaidAnswer.also { pendingPaidAnswer = next } }

    /**
     * SR-A (R-A4, C-SRA-4) — ask [confirmation] and suspend until it is answered: true only for Pay. Everything else is
     * Cancel: Cancel itself, another question replacing it, the question leaving the screen any other way (the screen
     * resets the state, another notice takes its place), and leaving the chat (the coroutine is cancelled; the
     * cancellation is rethrown to the caller, which treats it as Cancel too). Nothing is paid here.
     */
    private suspend fun awaitPaidAnswer(confirmation: PaidActionConfirmation): Boolean {
        val answer = CompletableDeferred<Boolean>()
        val pay: () -> Unit = { answer.complete(true) }
        askBeforePaying(confirmation, onDecline = { answer.complete(false) }, pay = pay)
        swapPaidAnswer(answer)
        val asked = _sendMessageState.value
        return try {
            kotlinx.coroutines.coroutineScope {
                val gone =
                    launch {
                        _sendMessageState.first { it != asked }
                        // Pay and Cancel clear the slot before the state moves on and then answer themselves; only a
                        // question that left the screen with its slot still ours is answered here.
                        if (pendingPaidAction === pay) answer.complete(false)
                    }
                answer.await().also { gone.cancel() }
            }
        } finally {
            if (pendingPaidAction === pay) {
                pendingPaidAction = null
                pendingPaidDecline = null
            }
            synchronized(paidAnswerLock) { if (pendingPaidAnswer === answer) pendingPaidAnswer = null }
            if (_sendMessageState.value === asked) _sendMessageState.value = SendMessageState.Idle
        }
    }

    /** R2-2 (b) — the user accepted the quoted cost: run the waiting paid tap once. */
    fun confirmPaidAction() {
        val pay = pendingPaidAction ?: return
        pendingPaidAction = null
        pendingPaidDecline = null
        // ZC-1272: the user read and accepted a price: the one-time cost notice has nothing to add, now or later. A key
        // change marks it when its work has run ([confirmKeyChangeReconnect]): nothing is written before that work's own
        // first write, so a process that ends at the tap leaves exactly what the accept's rules cover.
        val asked = (_sendMessageState.value as? SendMessageState.NeedsPaidActionConfirmation)?.confirmation?.action
        if (asked != PaidAction.KEY_CHANGE_ACCEPT && asked != PaidAction.KEY_CHANGE_RECONNECT) {
            zchatPreferences.setAcknowledgedMessageCost()
        }
        if (_sendMessageState.value is SendMessageState.NeedsPaidActionConfirmation) {
            _sendMessageState.value = SendMessageState.Idle
        }
        pay()
    }

    /** R2-2 (b) — the user declined: drop the waiting paid tap, pay nothing. R3-2 (2): undo what it took. */
    fun dismissPaidAction() {
        val decline = pendingPaidDecline
        pendingPaidDecline = null
        pendingPaidAction = null
        if (_sendMessageState.value is SendMessageState.NeedsPaidActionConfirmation) {
            _sendMessageState.value = SendMessageState.Idle
        }
        decline?.invoke()
    }

    /**
     * R3-2 (2) — a cancelled first message: the screen cleared its input and the draft when the send was
     * accepted behind the prompt. Save [text] as the chat's draft again and hand it back to the open input.
     *
     * T5b X-05: a text handed back while the chat already has a draft (an earlier text that was handed back, or what
     * the user typed since) is added to that draft on a new line ([mergedHandOffDraft]), never written over it.
     */
    private fun restoreTypedText(
        peerAddress: String,
        text: String,
    ) {
        zchatPreferences.setDraft(peerAddress, mergedHandOffDraft(zchatPreferences.getDraft(peerAddress), text))
        _restoredTypedText.value = RestoredTypedText(peerAddress, text)
    }

    /**
     * R6-4 — whether the automatic-spend question this instance raised is still open. Each screen has its own
     * ChatViewModel, so a question answered on another screen (Allow, or "Not now" to the same queued setups)
     * can still sit in this one's send state; the screen must not ask it again.
     */
    fun isHandshakeSpendQuestionOpen(): Boolean =
        // ZC1013-X1: under the standing consent only the setups declined before it was turned on still ask.
        (!zchatPreferences.hasConsentedToHandshakeSpend() || AutomaticSetupQueue.anyAskingUnderConsent(zchatPreferences)) &&
            !(queuedAutomaticSetups.isNotEmpty() && dismissedAutomaticSetups.containsAll(queuedAutomaticSetups))

    /**
     * The user agreed to pay for automatic handshakes. Persist it and clear the prompt. R9-2: the KEXACKs held for this
     * answer are sent at once, with no chat open; the other queued sends resume on the next block tick or chat open,
     * which is what re-armed their markers.
     */
    fun grantHandshakeSpendConsent() {
        // R5-2: this call releases EVERY queued automatic spend at once, so the consent they are paid under
        // must be on disk first. A write that was not confirmed releases nothing, instead of the app spending
        // against a consent no restart can find and then asking a second time for memos it has already paid for.
        //
        // Round 8 D10 (DECISIONS_NIGHT §6): the question no longer stays up with no word. It closes as for "Not now"
        // (it is not raised again for these same queued setups) and says why nothing was paid. No spending
        // decision changes: nothing is released and the consent is not read as given.
        if (!zchatPreferences.setConsentedToHandshakeSpend()) {
            Log.e("KEX", "handshake-spend consent not released: it could not be written")
            dismissedAutomaticSetups += queuedAutomaticSetups
            _sendMessageState.value = SendMessageState.Error(ChatSendCopy.STORAGE_PAUSED_PAID_STEP)
            return
        }
        // R9-2 (REVIEW_R8 F12, device D-F8): the KEXACKs held for this answer, read before the queue is cleared.
        val heldKexAcks =
            queuedAutomaticSetups
                .filter { it.kind == AutomaticSetupKind.KEXACK }
                .mapTo(linkedSetOf()) { it.target }
        // ZC1013-X1: with the queue, the setups that kept asking under the standing consent are answered.
        AutomaticSetupQueue.clearAllStored(zchatPreferences)
        if (_sendMessageState.value is SendMessageState.NeedsHandshakeSpendConsent) {
            _sendMessageState.value = SendMessageState.Idle
        }
        // R9-2: Allow sends them now. Each waited for a chat open (retryKexAckIfResponder), so on the phone the KEXACK
        // went 6.5 minutes after Allow, when the chat was opened. One after the other on the process-wide send scope
        // (the one spendable note), each through payKexAckOnce: at most one KEXACK per contact key, whichever screen
        // or chat open also tries it. A KEX of ours confirmed with a first message never waits for this answer
        // (payOwedKex), and a Tunnel ZBOOT is retried on every block; those need nothing from here.
        // ZC-1047: the Accepts whose answer waited for this question (their request is back on hold); Allow answers them.
        // ZC-1047-R1: only the Accepts tapped in this wallet (its store); another wallet's stay for its own Allow.
        val heldAccepts = synchronized(acceptsAwaitingConsent) { acceptsAwaitingConsent.remove(zchatPreferences)?.keys?.toSet() }.orEmpty()
        if (heldKexAcks.isNotEmpty() || heldAccepts.isNotEmpty()) {
            processSendScope().launch(Dispatchers.Main.immediate) {
                for (peer in heldAccepts) acceptInboundKexRequest(peer)
                for (peer in heldKexAcks - heldAccepts) retryKexAckOnce(peer)
            }
        }
        // Round 8 P1 (PHONE_TRIAGE F3): the consent no longer releases any group reply (R2-2 (d) sent each held one
        // here). A group join is paid only by its own Join.
    }

    /**
     * Block-driven ZBOOT maturation retry — the missing automatic trigger for the TUNNEL handshake.
     *
     * The initiator's on-chain ZBOOT (sole carrier of our NOSTR routing key when the peer's pubkey is
     * not yet known) must be funded by the KEX's CHANGE note, which needs ~10 confirmations; but the
     * per-send retry window is only ~4 blocks and every OTHER trigger is user-driven (chat-open, send,
     * call, manual reconnect). So a pair that handshakes and then leaves the chat deadlocks: the change
     * matures but nothing re-attempts the ZBOOT (root-caused live on a fresh 2-device pair — both sides
     * `bootsent=false`, no peer NOSTR pubkey, messages stuck "waiting for secure connection").
     *
     * networkHeight emits ~once per block, so this re-fires the stuck ZBOOT until it lands. All three
     * predicates are DURABLE prefs, so it survives process death and works from ANY ChatViewModel init
     * (list OR detail — observeBlockHeight is wired in init) with no chat-detail open required.
     * Idempotency + money-safety are entirely inside [sendNostrBootHandshake]: TUNNEL-only (#224 — OPEN
     * peers are never enumerated), ZBOOT-only (never a KEX — #208 single-note), the process-wide
     * `nostrBootInFlight` claim, the E2E self-gate, and the sent-marker. At most ONE peer per tick.
     * This predicate also auto-heals the #233 one-way (leg-4) case without a chat-open.
     *
     * ZC-534: besides the Tunnel chats, a contact in ANY mode whose quoted ZBOOT is marked owed
     * ([ZchatPreferences.isZbootOwed]) while its allowance stands is listed too, and is the only caller that passes
     * `resumeOwed`. Every candidate is sent under [ZbootOnChainRule.QUOTED_IN_SHIELDED], so a standing allowance is
     * spent as the quote it is. Still one ZBOOT per tick.
     */
    private fun retryPendingTunnelZboots(height: Long?) {
        viewModelScope.launch {
            // ZC-1364 (money-path rule 2): a ZBOOT another account's question covered is not paid by the account selected
            // now; its leg stays for the account that answered (as coveredSetupIsOf does for the KEX leg, ZC-1348).
            val selected = selectedAccountOrNull()?.let(GetDefaultUnifiedAddressUseCase::accountKeyOf)
            // ZC-1390: and an allowance another account's confirmed question (a Tunnel switch, a Reset) wrote.
            val coveredForAnother = { peer: String -> zbootAllowanceOfAnother(peer, selected) }
            val tunnel =
                zchatPreferences.getTunnelModePeers().filter { peer ->
                    !coveredForAnother(peer) &&
                        zchatPreferences.getSentNostrBootPubkey(peer) == null &&
                        zchatPreferences.isE2EKeyExchangeComplete(peer) &&
                        // ZC-739: held while the contact's new key waits for the user; it never uses up the block's pick.
                        !zchatPreferences.isE2EKeyChanged(peer) &&
                        !zchatPreferences.isAutomaticSetupWithdrawn(peer)
                }
            // ZC-534: and, in any mode, the contacts whose quoted ZBOOT is marked owed while its allowance stands (an
            // attempt that sent nothing and was cut off while it waited: the chat was left, or the process ended).
            // ZC-739: not while that contact's new key waits for the user (the mark and the allowance stay).
            val owed =
                zchatPreferences.getZbootOwedPeers().filterTo(mutableSetOf()) { peer ->
                    !coveredForAnother(peer) &&
                        !zchatPreferences.isE2EKeyChanged(peer) &&
                        !zchatPreferences.isAutomaticSetupWithdrawn(peer) &&
                        zbootQuoteStands(peer) &&
                        zchatPreferences.isE2EKeyExchangeComplete(peer)
                }
            val candidates = (tunnel + owed).distinct().sorted()
            if (candidates.isEmpty()) return@launch
            // ONE ZBOOT per tick (#208 single-note), but ROTATE by block height so a single permanently-failing
            // peer (e.g. a 0-balance wallet whose ZBOOT can never fund) can't STARVE the other pending peers —
            // each block advances the pick. Sorted first so the rotation is stable across ticks.
            val idx = ((height ?: 0L).mod(candidates.size.toLong())).toInt()
            val peer = candidates[idx]
            // ZC-534: an allowance a confirmed question left is spent as that quote (no standing-consent question for a
            // ZBOOT already quoted); with no allowance a Tunnel chat's ZBOOT is decided by the standing consent, as before.
            // ZC-1507 (M1): a Tunnel the contact moved this chat into sends our ZBOOT over the relays or not at all (as
            // startNostrBootstrap does); a quoted ZBOOT marked owed keeps its own consent.
            val rule =
                if (peer !in owed && modeMovedToPaidByPeer(peer)) ZbootOnChainRule.RELAY_ONLY else ZbootOnChainRule.QUOTED_IN_SHIELDED
            sendNostrBootHandshake(peer, rule, resumeOwed = peer in owed)
        }
    }

    private fun observeExchangeRate() {
        viewModelScope.launch {
            exchangeRateRepository.state.collect { state ->
                _zecPriceUsd.value = when (state) {
                    is ExchangeRateState.Data -> state.currencyConversion?.priceOfZec
                    else -> null
                }
            }
        }
    }

    /**
     * Observe wallet snapshot to provide detailed sync progress for the UI.
     * Shows progress percentage and description during wallet restore/sync.
     */
    private fun observeWalletSyncStatus() {
        viewModelScope.launch {
            combine(walletSnapshotDataSource.observe(), walletSyncClock.syncedAtMillis) { snapshot, syncedAt ->
                snapshot to syncedAt
            }.collect { (snapshot, syncedAt) ->
                if (snapshot == null) {
                    _walletSyncStatus.value = WalletSyncStatus(syncedAtMillis = syncedAt)
                    return@collect
                }

                val progress = snapshot.progress.decimal * 100f
                val isRestoring = snapshot.restoringState == WalletRestoringState.RESTORING
                val isInitiating = snapshot.restoringState == WalletRestoringState.INITIATING
                // Don't show sync progress for new wallets (SYNCING restoring state means
                // wallet was created with current chain height and has no history to scan)
                val isNewWallet = snapshot.restoringState == WalletRestoringState.SYNCING
                val isSyncing = !isNewWallet && snapshot.status == Synchronizer.Status.SYNCING

                val statusMessage = when {
                    isRestoring && progress < 10f -> "Initializing wallet restore..."
                    isRestoring && progress < 50f -> "Scanning blockchain history..."
                    isRestoring && progress < 90f -> "Retrieving your messages..."
                    isRestoring -> "Finalizing restore..."
                    isInitiating && progress < 10f -> "Setting up new wallet..."
                    isInitiating -> "Syncing initial data..."
                    isSyncing && progress < 50f -> "Checking for new messages..."
                    isSyncing && progress < 90f -> "Updating wallet..."
                    isSyncing -> "Almost done..."
                    snapshot.status == Synchronizer.Status.DISCONNECTED -> "Disconnected - reconnecting..."
                    snapshot.status == Synchronizer.Status.STOPPED -> "Sync stopped"
                    else -> ""
                }

                // Format block range if available (for UI display)
                // Uses wallet birthday as the start of the scan range (not block 0)
                val blockHeight = _blockHeight.value
                val scanningRange = if ((isRestoring || isInitiating || isSyncing) && blockHeight != null && blockHeight > 0) {
                    val birthday = walletBirthday ?: 0L
                    val blocksToScan = blockHeight - birthday
                    val scannedBlocks = (blocksToScan * progress / 100).toLong()
                    val currentScanBlock = birthday + scannedBlocks
                    "Blocks ${formatNumber(currentScanBlock)} - ${formatNumber(blockHeight)}"
                } else null

                _walletSyncStatus.value = WalletSyncStatus(
                    isRestoring = isRestoring,
                    isInitiating = isInitiating,
                    isSyncing = isSyncing,
                    progress = progress,
                    statusMessage = statusMessage,
                    scanningRange = scanningRange,
                    sdkStatus = snapshot.status,
                    syncedAtMillis = syncedAt
                )
            }
        }
    }

    private fun formatNumber(number: Long): String {
        return String.format("%,d", number)
    }

    private fun loadConversations() {
        // Cancel previous collection job to prevent duplicate coroutines
        conversationLoadJob?.cancel()
        conversationLoadJob = viewModelScope.launch {
            try {
                // Wait for convID repair to finish before processing conversations,
                // otherwise we may read partially-repaired mappings.
                repairComplete.await()
                // The new kept-invite sweep must not use an old identity load for a replacement wallet.
                val reinviteWallet = withHeldAcceptsLock { heldGroupAcceptsWallet() }

                // Get current user address - use default unified address for consistency after restore
                // IMPORTANT: Do NOT use fallback to account.unified.address - it may be a different diversified address
                // T1b-1 §2: read for one account, and remember which, so a switch is noticed.
                val identityAccount = accountDataSource.getSelectedAccount()
                val userAddress = getDefaultUnifiedAddress.forAccount(identityAccount)
                _currentUserAddress.value = userAddress
                identityAccountKey = GetDefaultUnifiedAddressUseCase.accountKeyOf(identityAccount)
                // ZC-946 part 2: the tag this collection's passes are kept under, read with its inputs (never the
                // mutable identityAccountKey): a pass of this collection is shown only to this account and wallet.
                val snapshotTag =
                    co.electriccoin.zcash.ui.screen.chat.datasource.ConversationSnapshotCache.Tag(
                        accountKey = GetDefaultUnifiedAddressUseCase.accountKeyOf(identityAccount),
                        userAddress = userAddress,
                        generation = zchatPreferences.walletScopeGeneration(),
                    )
                // T1b-1 §2: the identity follows the selected account (the Wallet-tab chip), not only this first load.
                launch {
                    accountDataSource.selectedAccount
                        .map { account -> account?.let(GetDefaultUnifiedAddressUseCase::accountKeyOf) }
                        .distinctUntilChanged()
                        .collect { key -> if (key != null && key != identityAccountKey) loadChatIdentity() }
                }

                // #205 — register every representation of OUR OWN address so self-identification is
                // drift-tolerant. The saved chat identity (P2g) is what we KEX-sign and display on the
                // receive screen, but the account can also surface a different diversified unified
                // address; record both so a self-check (self-message filter, am-I-kicked) by hash
                // recognises us regardless of which representation an inbound message carries.
                zchatPreferences.registerSelfAddress(userAddress)
                runCatching {
                    getSelectedWalletAccount().unified.address.address
                }.getOrNull()?.let { zchatPreferences.registerSelfAddress(it) }

                // Address (and self-address registry) is now ready — reprocess any NOSTR GROUP_INVITE that
                // arrived and was deferred while it was still loading (see pendingGroupInvites).
                drainPendingGroupInvites()
                // Unlike the queue drain's re-entrant NEW-invite caller, this load holds no group lock.
                sweepKeptReinvites(reinviteWallet)

                // Split into two flows to avoid cancelling expensive convertToConversations()
                // every time the countdown timer ticks (every second).
                //
                // Flow 1: Expensive conversation conversion — only re-runs when data changes
                // Flow 2: Lightweight sync metadata — can change every second without cost

                // Flow 1: Conversations (expensive, only on data changes)
                // A5 — has the wallet finished its first full history scan (restore / rescan / new wallet)?
                // Drives RestoreKexPolicy in the conversion and the provider's seed-index allocation. A flip to
                // complete waits HISTORY_SCAN_SETTLE_MS so the SDK's last transaction batch reaches the list
                // first; the value persisted from an earlier session is taken at once.
                var sawIncompleteScan = false
                val historyScanCompleteFlow =
                    walletSnapshotDataSource
                        .observe()
                        .filterNotNull()
                        .map { RestoreKexPolicy.isHistoryScanComplete(it.restoringState) }
                        .distinctUntilChanged()
                        .onEach { complete ->
                            if (!complete) {
                                sawIncompleteScan = true
                                // P2b: a restore / rescan started — no automatic ZBOOT pays until it is read.
                                processHistoryRead.set(false)
                                // P2d: and no send creates a key until restore recovery has run on the full history.
                                SeedDerivedE2EKeyProvider.processOwnHistoryRead.set(false)
                            } else if (sawIncompleteScan) {
                                delay(HISTORY_SCAN_SETTLE_MS)
                            }
                            SeedDerivedE2EKeyProvider.processHistoryScanComplete.set(complete)
                        }
                val scannedTransactions =
                    combine(
                        transactionRepository.transactions
                            .filterNotNull()
                            .debounce(300), // Batch rapid emissions during sync to avoid reprocessing
                        historyScanCompleteFlow,
                        restoreRecheck,
                    ) { transactions, scanComplete, _ -> transactions to scanComplete }
                // R9-6: also re-renders when a disappearing message's time is up (conversationRenderFlow).
                val conversationsFlow = conversationRenderPassFlow(scannedTransactions, userAddress)

                // Flow 2: Sync status (cheap, changes every second)
                val syncStatusFlow = combine(
                    _lastSyncTime,
                    _isRefreshing,
                    _secondsUntilNextSync,
                    _blockHeight,
                    _zecPriceUsd
                ) { lastSync, isRefreshing, secondsUntilNext, blockHeight, zecPrice ->
                    SyncStatus(lastSync, isRefreshing, secondsUntilNext, blockHeight, zecPrice)
                }

                // Receipts that may still be confirming, for the "N/10 confirmations" countdown. A cheap
                // projection of the same transactions flow, refreshed only when the list changes; the
                // countdown itself re-runs on every block tick because _blockHeight feeds syncStatusFlow.
                val pendingReceiptsFlow = transactionRepository.transactions.filterNotNull()
                    .debounce(300) // batch catch-up bursts, like conversationsFlow above
                    .map { it.toPendingReceipts() }
                    .distinctUntilChanged()
                    .flowOn(Dispatchers.Default)

                val combinedSyncFlow = combine(syncStatusFlow, _walletSyncStatus, pendingReceiptsFlow) { sync, walletSync, receipts ->
                    Triple(sync, walletSync, receipts)
                }

                // Combine conversations (cached) with sync metadata (fast-changing) and read markers.
                combine(
                    conversationsFlow,
                    accountDataSource.selectedAccount,
                    combinedSyncFlow,
                    readMarkers,
                    zchatPreferences.e2eHandshakeTicks
                ) { renderedPass, walletAccount, syncBundle, readMarkerMap, _ ->
                    val (syncStatus, walletSyncStatus, pendingReceipts) = syncBundle
                    val conversations = renderedPass.conversations

                    // Captured ONCE per emission so the unread predicate is consistent across all
                    // conversations and doesn't shift mid-pass.
                    val nowMs = System.currentTimeMillis()

                    // Add peer statuses, drafts, and E2E status to conversations
                    val drafts = zchatPreferences.getAllDrafts()
                    val conversationsWithStatus = conversations.map { conversation ->
                        withLiveStatus(
                            conversation = conversation,
                            draft = drafts[conversation.peerAddress],
                            lastRead = readMarkerMap[conversation.peerAddress] ?: 0L,
                            nowMs = nowMs,
                        )
                    }
                    val balance = walletAccount?.displayTotalBalance ?: Zatoshi(0)
                    // C-5: the Payment dialog's budget. Only Ironwood can pay a peer; the headline total
                    // above is unchanged.
                    val peerSendableBalance = walletAccount?.peerSpendableBalance ?: Zatoshi(0)
                    val privacyStatus = computePrivacyStatus(walletAccount, syncStatus.blockHeight, pendingReceipts)
                    // Load groups from preferences
                    val groups = loadAllGroups()
                    ChatListState.Success(
                        conversations = conversationsWithStatus,
                        groups = groups,
                        // Round 8 D4: invites from a new address that wait for Join (the row says so).
                        groupsAwaitingJoin = groups.map { it.groupId }.filterTo(mutableSetOf()) { groupInviteNeedsJoin(it) != null },
                        currentUserAddress = userAddress,
                        balance = balance,
                        peerSendableBalance = peerSendableBalance,
                        lastSyncTime = syncStatus.lastSyncTime,
                        isRefreshing = syncStatus.isRefreshing,
                        secondsUntilNextSync = syncStatus.secondsUntilNextSync,
                        blockHeight = syncStatus.blockHeight,
                        zecPriceUsd = syncStatus.zecPriceUsd,
                        privacyStatus = privacyStatus,
                        syncStatus = walletSyncStatus,
                        renderedPendingIds = renderedPass.pendingIds,
                    )
                }.collectLatest { state ->
                    showFinishedPass(state, snapshotTag.accountKey, snapshotTag.userAddress, snapshotTag.generation)
                }
            } catch (e: kotlinx.coroutines.CancellationException) {
                // Expected when setNickname() / contact rename triggers a reload —
                // loadConversations() cancels the prior job, the resulting
                // CancellationException is not a user-facing error. Rethrow so
                // structured concurrency stays intact, but DO NOT flip state to Error
                // (that turns the whole chat list into "StandaloneCoroutine was cancelled").
                throw e
            } catch (e: Exception) {
                _chatListState.value = ChatListState.Error(e.toZchatUserMessage("Failed to load conversations"))
            }
        }
    }

    /**
     * ZC-946 part 1: what the chat screens draw. The last finished pass ([chatListState], which every money, key and
     * trust reader keeps reading) with this view model's own sends that the pass does not have yet drawn early as
     * "sending" ([PendingOverlay]); the pass itself when there is none. Only the views read it.
     */
    @OptIn(kotlinx.coroutines.ExperimentalCoroutinesApi::class)
    fun displayChatList(): Flow<ChatListState> =
        combine(
            // ZC-946 part 2: while this view model's own pass runs, the last finished pass of this wallet (masked).
            _chatListState.flatMapLatest { state -> if (state is ChatListState.Loading) cachedSnapshot() else flowOf(state) },
            pendingMessages,
        ) { state, pending ->
            PendingOverlay.apply(state, pending)
        }

    /**
     * ZC-946 part 2: a finished pass of loadConversations' collection tagged ([accountKey], [userAddress], [generation]):
     * it becomes [chatListState], and it is kept for the next screen (ConversationSnapshotCache) only while the
     * wallet-scope generation is still the tag's, so a pass that ends after a Reset is never shown again.
     */
    private fun showFinishedPass(
        state: ChatListState.Success,
        accountKey: String,
        userAddress: String,
        generation: Long,
    ) {
        _chatListState.value = state
        if (zchatPreferences.walletScopeGeneration() == generation) {
            co.electriccoin.zcash.ui.screen.chat.datasource.ConversationSnapshotCache.put(
                co.electriccoin.zcash.ui.screen.chat.datasource.ConversationSnapshotCache
                    .Tag(accountKey, userAddress, generation),
                state,
            )
        }
    }

    /**
     * ZC-946 part 2: Loading until the selected account has emitted, then the kept pass through [CachedSnapshotMask]
     * when it was tagged with this account and the current wallet-scope generation, else Loading. Waits for neither
     * repairComplete nor identityAccountKey; reads the store and writes nothing.
     */
    private fun cachedSnapshot(): Flow<ChatListState> =
        accountDataSource.selectedAccount
            .map { account -> cachedSnapshotFor(account) ?: ChatListState.Loading }
            .onStart { emit(ChatListState.Loading) }
            .flowOn(renderDispatcher ?: Dispatchers.Default)

    private fun cachedSnapshotFor(account: WalletAccount?): ChatListState? {
        account ?: return null
        val entry =
            co.electriccoin.zcash.ui.screen.chat.datasource.ConversationSnapshotCache
                .get() ?: return null
        if (entry.tag.accountKey != GetDefaultUnifiedAddressUseCase.accountKeyOf(account)) return null
        if (entry.tag.generation != zchatPreferences.walletScopeGeneration()) return null
        val live =
            CachedSnapshotMask.Live(
                hiddenIds = hiddenMessages.value + zchatPreferences.getHiddenMessageIds(),
                expiredIds = zchatPreferences.getExpiredMessageIds(),
                nowMillis = ttlNowMillis(),
                ttlOf = zchatPreferences::getDisappearingTtl,
                contactNameOf = { peer -> zchatPreferences.getNickname(peer) ?: contactBook.getContact(peer)?.name },
                drafts = zchatPreferences.getAllDrafts(),
                balance = account.displayTotalBalance,
                peerSendableBalance = account.peerSpendableBalance,
            )
        return CachedSnapshotMask.mask(entry.state, entry.tag.userAddress, live)
    }

    /** ZC-946 part 1: one finished render pass, with the ids of the pending rows it received. */
    private class RenderedPass(
        val conversations: List<Conversation>,
        val pendingIds: Set<String>,
    )

    /** R9-6: what one conversation render reads. */
    private data class RenderInputs(
        val transactions: List<Transaction>,
        val historyScanComplete: Boolean,
        val hiddenMsgIds: Set<String>,
        val pending: List<ChatMessage>,
        val paidReqIds: Set<String>,
    )

    /** R9-6: the earliest expiry still ahead that a render pass saw (null = none), so the render re-runs then. */
    private class NextTtlExpiry {
        var atMillis: Long? = null
            private set

        fun offer(expireAtMillis: Long) {
            val current = atMillis
            if (current == null || expireAtMillis < current) atMillis = expireAtMillis
        }
    }

    /**
     * The conversations the chat list and the open chat show (loadConversations' Flow 1): convertToConversations over
     * the scanned transactions, the hidden set, the relay / pending rows, the paid requests and the timers, re-run when
     * any of them emits.
     *
     * R9-6 (REVIEW_R8 F14 = device D-F11): and when a disappearing message's time is up. The B17 expiry filter runs
     * only inside convertToConversations, so before this an expired row stayed in an open chat until the next block
     * or relay message (a 1-minute message stayed 2+ minutes on a phone). Each render now arms one ticker to the
     * nearest expiry it saw and re-renders when it fires; a new render re-arms it, and no timer or no expiry ahead
     * arms nothing.
     */
    private fun conversationRenderFlow(
        scannedTransactions: Flow<Pair<List<Transaction>, Boolean>>,
        userAddress: String,
    ): Flow<List<Conversation>> = conversationRenderPassFlow(scannedTransactions, userAddress).map { it.conversations }

    /** ZC-946 part 1: [conversationRenderFlow] with the ids of the pending rows each pass received. */
    private fun conversationRenderPassFlow(
        scannedTransactions: Flow<Pair<List<Transaction>, Boolean>>,
        userAddress: String,
    ): Flow<RenderedPass> =
        channelFlow {
            val expiryTick = MutableStateFlow(0L)
            var ticker: Job? = null
            combine(
                scannedTransactions,
                hiddenMessages,
                pendingMessages,
                paidRequestIds,
                zchatPreferences.disappearingTtls, // B17 — a TTL change re-runs the expiry render filter
            ) { (transactions, historyScanComplete), hiddenMsgIds, pending, paidReqIds, _ ->
                RenderInputs(transactions, historyScanComplete, hiddenMsgIds, pending, paidReqIds)
            }.combine(expiryTick) { inputs, _ -> inputs }
                // ZC-022 (KI-25 R9): the pass signal. A confirmation of a group's admin raises it, and every live
                // view model begins a history pass over the inputs it already has.
                .combine(historyPassSignal) { inputs, _ -> inputs }
                .collectLatest { inputs ->
                    val txList = inputs.transactions
                    val receiveCount = txList.count { it is co.electriccoin.zcash.ui.common.repository.ReceiveTransaction }
                    val sendCount = txList.count { it is co.electriccoin.zcash.ui.common.repository.SendTransaction }
                    Log.d(
                        "ZCHAT_FLOW",
                        "=== Transactions flow emitted: total=${txList.size} (rx=$receiveCount tx=$sendCount) " +
                            "pending=${inputs.pending.size} hidden=${inputs.hiddenMsgIds.size} ===",
                    )
                    val nextExpiry = NextTtlExpiry()
                    // Run the expensive conversion (CPU-heavy sort/loop + synchronous SharedPreferences
                    // commits in the address/convId caches) OFF the main thread to avoid the StrictMode
                    // disk-write-on-main violation and UI jank during sync.
                    val conversations =
                        withContext(renderDispatcher ?: Dispatchers.Default) {
                            convertToConversations(
                                txList,
                                userAddress,
                                inputs.hiddenMsgIds,
                                inputs.pending,
                                inputs.paidReqIds,
                                inputs.historyScanComplete,
                                nextExpiry,
                            )
                        }
                    ticker?.cancel()
                    ticker =
                        nextExpiry.atMillis?.let { expireAt ->
                            launch {
                                // A little after the time, so rows due within the same half second leave in one render.
                                delay((expireAt - ttlNowMillis()).coerceAtLeast(0L) + EXPIRY_TICK_SLACK_MS)
                                expiryTick.update { it + 1 }
                            }
                        }
                    send(RenderedPass(conversations, inputs.pending.mapTo(HashSet()) { it.id }))
                }
        }.conflate()

    private suspend fun convertToConversations(
        transactions: List<Transaction>,
        userAddress: String,
        hiddenMsgIds: Set<String> = emptySet(),
        pendingMsgs: List<ChatMessage> = emptyList(),
        paidReqIds: Set<String> = emptySet(),
        historyScanComplete: Boolean,
    ): List<Conversation> =
        convertToConversations(transactions, userAddress, hiddenMsgIds, pendingMsgs, paidReqIds, historyScanComplete, NextTtlExpiry())

    /** Each chat's mined KEXACK heights: (trusted, untrusted), by the rule of [markPreSessionRows]. */
    private fun kexAckHeightsByPeer(sightings: List<KexAckSighting>): Map<String, Pair<List<Long>, List<Long>>> {
        val heightsByPeer = HashMap<String, Pair<MutableList<Long>, MutableList<Long>>>()
        for (sighting in sightings) {
            val peer = runCatching { zchatPreferences.getPeerByConversationId(sighting.convId) }.getOrNull() ?: continue
            val trusted =
                sighting.own ||
                    (
                        sighting.payloadPub != null &&
                            runCatching { zchatPreferences.getE2EPeerPublicKey(peer) }.getOrNull() == sighting.payloadPub
                    )
            val heights = heightsByPeer.getOrPut(peer) { mutableListOf<Long>() to mutableListOf() }
            (if (trusted) heights.first else heights.second) += sighting.height
        }
        return heightsByPeer
    }

    /**
     * ZC-1792 F2 and F3 (QA2 k1, W-137: display only, no key change) — after a history pass:
     * - F2: a received row that failed to open and was mined before the chat's first trusted KEXACK (its session height)
     *   was sealed before the key exchange finished; its bubble says so instead of blaming a wallet restore.
     * - F3: a received row that failed and was mined before the contact's newest trusted KEXACK never arms the
     *   keys-out-of-sync banner: a Re-establish only helps messages sent after the latest handshake.
     * - ZC-1809: strict <, a row mined in the same block as the KEXACK may have been sealed after it: a real failure.
     * - ZC-1819: the set this settlement armed is recomputed every pass, a pass with no failure included: a contact it
     *   armed earlier and no qualifying failure arms now is cleared.
     * - ZC-1841, ZC-1847 (QA2 k1b2): a qualifying failure is answered by an incoming row of the contact this phone opened
     *   (now, earlier in this process, or a text it stored: [DecryptOutcomes.opened]) and mined strictly above the newest
     *   trusted KEXACK and strictly after the failure. The basis is the row's height, the same for every ViewModel
     *   instance, after a restart and whichever session opened it; our own saved text never counts. The banner is up
     *   while a qualifying failure has no such answer.
     * - QA2 pa3: ZC-1855, ZC-1856, the settlement is the banner's one owner (the live ownership guarded a path no production
     *   caller reaches, and made two ViewModels disagree). ZC-1857, a row with no height answers nothing and a failure with
     *   no height is answered by nothing ([DecryptOutcomes.Open.answers]). ZC-1859, our own failing row carries its height.
     *   ZC-1828, a row P-A's earlier-root reader opens is an open like any other, by its height.
     * - QA2 pa4: ZC-1863, an own failure mined before the newest trusted KEXACK is left out like an incoming one; ZC-1864, a
     *   failure with no height arms nothing until it has one.
     */
    private fun settleDecryptOutcomes(
        outcomes: DecryptOutcomes,
        sightings: List<KexAckSighting>,
        messagesByPeer: MutableMap<String, MutableList<ChatMessage>>,
    ) {
        val armedEarlier = settlementArmedPeers.orEmpty()
        val armedNow = HashSet<String>()
        val heights = if (outcomes.failures.isEmpty()) emptyMap() else kexAckHeightsByPeer(sightings)
        val keyMissing = noteCopy.get(R.string.chat_decrypt_placeholder_key_missing)
        val qualifying = HashMap<String, MutableList<DecryptOutcomes.Failure>>()
        for (failure in outcomes.failures) {
            val (trusted, untrusted) = heights[failure.peer] ?: (emptyList<Long>() to emptyList())
            val mined = failure.minedHeight
            val sessionHeight =
                co.electriccoin.zcash.ui.screen.chat.model.MessageAuthentication
                    .sessionHeight(trusted, untrusted)
            if (failure.incoming && mined != null && sessionHeight != null && mined < sessionHeight) {
                val rows = messagesByPeer[failure.peer]
                val index = rows?.indexOfFirst { it.id == failure.rowId && it.text == keyMissing } ?: -1
                if (rows != null && index >= 0) {
                    rows[index] = rows[index].copy(text = noteCopy.get(R.string.chat_decrypt_placeholder_before_key_exchange))
                }
            }
            val newestTrusted = trusted.maxOrNull()
            // ZC-1863 (QA2 pa4): our own rows carry a height now (ZC-1859), so an own row mined before the newest trusted
            // KEXACK is left out too: a Re-establish cannot help it either. ZC-1864: a failure with no height (not mined)
            // arms nothing; it waits for its height, as no open can answer it before (Open.answers).
            val beforeLatestHandshake = mined != null && newestTrusted != null && mined < newestTrusted
            if (mined != null && !beforeLatestHandshake) qualifying.getOrPut(failure.peer) { mutableListOf() } += failure
        }
        for (peer in outcomes.failures.mapTo(LinkedHashSet()) { it.peer }) {
            val newestTrusted = heights[peer]?.first?.maxOrNull()
            val opens = outcomes.opens.filter { it.peer == peer }
            val unanswered =
                qualifying[peer].orEmpty().any { failure -> opens.none { it.answers(failure, newestTrusted) } }
            if (unanswered) {
                decryptFailedPeers.add(peer)
                armedNow += peer
            } else {
                decryptFailedPeers.remove(peer)
            }
        }
        // ZC-1819: what an earlier pass armed and nothing in this pass arms again is cleared.
        for (peer in armedEarlier - armedNow) decryptFailedPeers.remove(peer)
        settlementArmedPeers = armedNow
    }

    /**
     * Round 10b R10B-2 (F-R9C-3) — set [ChatMessage.preSession] on each chat's rows from its session height
     * ([MessageAuthentication.sessionHeight]): the earliest mined KEXACK of any of its conversation ids, trusted when it
     * is our own or the contact's signed with the key we hold for them. A chat whose earliest KEXACK is not trusted, or
     * whose conversation id maps to no peer, keeps every row as it was (the chip shows as before).
     */
    private fun markPreSessionRows(
        sightings: List<KexAckSighting>,
        messagesByPeer: MutableMap<String, MutableList<ChatMessage>>,
    ) {
        // ZC-1943: each chat's heights of our own mined KEXACKs, to tell whether ours opened the session.
        val ownHeightsByPeer = HashMap<String, MutableSet<Long>>()
        for (sighting in sightings) {
            if (!sighting.own) continue
            val peer = runCatching { zchatPreferences.getPeerByConversationId(sighting.convId) }.getOrNull() ?: continue
            ownHeightsByPeer.getOrPut(peer) { HashSet() } += sighting.height
        }
        for ((peer, heights) in kexAckHeightsByPeer(sightings)) {
            val rows = messagesByPeer[peer] ?: continue
            val sessionHeight =
                co.electriccoin.zcash.ui.screen.chat.model.MessageAuthentication
                    .sessionHeight(heights.first, heights.second) ?: continue
            // ZC-1910: and the contact's plaintext from before its first ratcheted message (built before it had our KEXACK).
            val marked =
                co.electriccoin.zcash.ui.screen.chat.model.MessageAuthentication
                    .markBeforeContactRatchet(
                        co.electriccoin.zcash.ui.screen.chat.model.MessageAuthentication
                            .markPreSession(rows, sessionHeight),
                        sessionHeight,
                        sessionIsOurKexAck = ownHeightsByPeer[peer]?.contains(sessionHeight) == true,
                    )
            rows.clear()
            rows.addAll(marked)
        }
    }

    private suspend fun convertToConversations(
        transactions: List<Transaction>,
        userAddress: String,
        hiddenMsgIds: Set<String>,
        pendingMsgs: List<ChatMessage>,
        paidReqIds: Set<String>,
        historyScanComplete: Boolean,
        nextTtlExpiry: NextTtlExpiry,
    ): List<Conversation> {
        val pass = beginZbootHistoryPass()
        // ZC-022 (KI-25 R9): the pass takes its number, and reads the wallet generation, before its loop.
        val historyPass = beginHistoryPass()
        // ZC-704 (KI-25 R19): before the loop, so a removal of this phone the pass applies finds the invite to offer.
        handOverKeptReinvitesBeforeLoop(historyPass)
        return try {
            convertToConversationsInPass(
                transactions,
                userAddress,
                hiddenMsgIds,
                pendingMsgs,
                paidReqIds,
                historyScanComplete,
                nextTtlExpiry,
                pass,
                historyPass,
            )
        } finally {
            abandonZbootHistoryPass(pass)
        }
    }

    /**
     * ZC-599 — one of this wallet's own mined key exchanges: its id, its height and the addresses it paid. ZC-757 (k)
     * recheck 6: [paidTexts] are the texts its outputs actually paid (no fee address), without the holder addresses
     * [recipients] adds; [answeredOwnKeyExchange] reads only these. ZC-757 (k) round 15 (ZC-1167): [outputsUnreadable] is
     * true when this pass could not read its outputs ([paidTexts] is then empty, not "paid nothing").
     */
    private class OwnMinedKex(
        val convId: String,
        val height: Long,
        val recipients: List<String>,
        val paidTexts: List<String>,
        val outputsUnreadable: Boolean = false,
    )

    /** ZC-599 — a received, mined answer: the memo, its txid and height, its id and the address it claims. */
    private class InboundAnswer(
        val memo: String,
        val txId: String,
        val height: Long,
        val convId: String,
        val claimed: String?,
    )

    /** ZC-599: how an answer was asked for (legs 1 to 3 of 5.4 item 2), or not. ZC-634 reads the leg (5.5 items 2 c, 5, 6). */
    private enum class AnswerVerdict { LEG1, LEG2, LEG3, NOT_ASKED }

    /** ZC-634 (5.5 item 2a) — the contact key this wallet's own mined answer answered at an address, and whether it is settled. */
    private class OwnAnswerVerdict(
        val key: String,
        val settled: Boolean,
    )

    /**
     * ZC-599 (FIRST-CONTACT-SPEC 5.4 item 2) — whether this phone asked for [answer]. F is the address its id maps to, or
     * with no entry the address it claims (when a chat may be offered there). Asked when: leg 1, the id is this phone's
     * own for F and an own mined key exchange under it is at most one expiry window above the answer; leg 2, an own
     * mined key exchange to F is at or below the answer and F holds no contact key or exactly the answer's; leg 3, the
     * answer is mined at or below the network's upgrade height.
     */
    private fun judgeAnswer(
        answer: InboundAnswer,
        ownKex: List<OwnMinedKex>,
    ): AnswerVerdict {
        val filedUnder =
            zchatPreferences.getPeerByConversationId(answer.convId)
                ?: answer.claimed?.takeIf { mayOfferInboundChat(it) }
                ?: return AnswerVerdict.NOT_ASKED
        val leg1 =
            zchatPreferences.isOwnConversationId(answer.convId, filedUnder) &&
                ownKex.any { it.convId == answer.convId && KexAnswerWindow.ownKexCovers(it.height, answer.height) }
        if (leg1) return AnswerVerdict.LEG1
        val canonical = zchatPreferences.resolvePeerAddress(filedUnder)
        val held = zchatPreferences.getE2EPeerPublicKey(filedUnder)
        // ZC-1082 (N-13, flows 11 and 17): a restored wallet names the key exchange's destination by the receiver it paid.
        // For an answer under that key exchange's own id (only its recipient could read the id), the destination is "to F"
        // when its receivers sit within F's address; such an answer is taken with its claim mark (fails towards the mark).
        // Under any other id the text alone counts (flow 14), so an address built around the receiver claims nothing.
        val sentThere = { kex: OwnMinedKex ->
            kex.recipients.any { text ->
                zchatPreferences.resolvePeerAddress(text) == canonical ||
                    (
                        kex.convId == answer.convId &&
                            (ZcashReceivers.within(text, filedUnder) || ZcashReceivers.within(text, canonical))
                    )
            }
        }
        val leg2 =
            ownKex.any { kex -> kex.height <= answer.height && sentThere(kex) } &&
                (held == null || held == answerKey(answer.memo, filedUnder))
        if (leg2) return AnswerVerdict.LEG2
        val upgrade = ChainTiming.current.upgrade
        return if (upgrade != null && answer.height <= upgrade) AnswerVerdict.LEG3 else AnswerVerdict.NOT_ASKED
    }

    /** ZC-949 — the address a received answer is filed under (as [judgeAnswer] files it), or null. */
    private fun answerFiledUnder(answer: InboundAnswer): String? =
        zchatPreferences.getPeerByConversationId(answer.convId) ?: answer.claimed?.takeIf { mayOfferInboundChat(it) }

    /** ZC-949 — [judgeAnswer]'s leg 1 alone: under this phone's own id for the address it is filed under, asked by it. */
    private fun isLeg1Answer(
        answer: InboundAnswer,
        ownKex: List<OwnMinedKex>,
    ): Boolean {
        val filedUnder = answerFiledUnder(answer) ?: return false
        return zchatPreferences.isOwnConversationId(answer.convId, filedUnder) &&
            ownKex.any { it.convId == answer.convId && KexAnswerWindow.ownKexCovers(it.height, answer.height) }
    }

    /**
     * ZC-949 (FIRST-CONTACT-SPEC 5.5 item 2a) — this wallet's own mined answer for [key] at [peer] is settled: the proof is
     * in the history (a leg 1 answer filed under [peer] carrying [key]), or this wallet never began there: each of its own
     * mined key exchanges provably went to another address (none of its destination texts is [peer]'s, and a leg 1
     * answer under its id verifies, strictly, for exactly one of those texts). Everything else (no readable destination, a
     * text nothing vouches for) is not settled: the rule fails towards the hold.
     */
    private fun answerIsSettled(
        peer: String,
        key: String,
        ownKex: List<OwnMinedKex>,
        answers: List<InboundAnswer>,
    ): Boolean {
        val canonical = zchatPreferences.resolvePeerAddress(peer)
        val proof =
            answers.any { a ->
                val filedUnder = answerFiledUnder(a)
                filedUnder != null &&
                    zchatPreferences.resolvePeerAddress(filedUnder) == canonical &&
                    isLeg1Answer(a, ownKex) &&
                    answerKey(a.memo, filedUnder) == key
            }
        if (proof) return true
        return ownKex.all { kex ->
            kex.recipients.isNotEmpty() &&
                kex.recipients.none { zchatPreferences.resolvePeerAddress(it) == canonical } &&
                answers.any { a ->
                    val payload = ZMSGProtocol.parseKEXAckMessage(a.memo)?.second
                    a.convId == kex.convId &&
                        payload != null &&
                        isLeg1Answer(a, ownKex) &&
                        kex.recipients.count { text -> E2EEncryption.parseKEXAckPayloadFull(payload, text) != null } == 1
                }
        }
    }

    /** ZC-599 — the key an answer carries (its signature checked against [filedUnder] first, then as self-signed). */
    private fun answerKey(
        memo: String,
        filedUnder: String,
    ): String? {
        val payload = ZMSGProtocol.parseKEXAckMessage(memo)?.second ?: return null
        return (E2EEncryption.parseKEXAckPayloadFull(payload, filedUnder) ?: E2EEncryption.parseKEXAckPayloadFull(payload, null))?.publicKey
    }

    /**
     * ZC-599 — an asked answer: mapped to the address it is filed under when its id has no entry, then handled. ZC-634: the
     * [leg] it was asked by goes with its txid to the store part ([adoptKeyOffer]).
     */
    private fun takeAskedAnswer(
        answer: InboundAnswer,
        userAddress: String,
        leg: AnswerVerdict,
        ownKex: List<OwnMinedKex>,
    ) {
        // ZC-757 (k) round 9, round 12 (ZC-1155): an answer that claims another address than the one its id is filed under,
        // while an own key exchange under that id paid a text whose receivers sit within the claimed address, is refused
        // before anything is written: no key stored or held for anyone, no claim mark, no leg, no id move, no ZBOOT (the
        // pass also keeps its txid out of the filed address's KEXACK set, [refusedAnswerTxIds]).
        val claimed = answer.claimed
        val claimedCanon = claimed?.let { zchatPreferences.resolvePeerAddress(it) }
        if (answerClaimsAnotherHolder(answer, claimedCanon, ownKex)) {
            answerLegByTx.remove(answer.txId)
            Log.w("KEX", "Answer under an id filed for another holder of the paid receiver, or outputs unread — refused this pass")
            return
        }
        answerLegByTx[answer.txId] = leg
        // ZC-599 (re-review 26 Oct, finding 1; money recheck 26 Oct, findings 1-2; round 3): an old answer (leg 3) is
        // read as before, but it is proof that this phone asked only when an own mined key exchange at or below it went to
        // the address it is filed under, read as leg 2 reads a destination ([oldAnswerIsBacked]). One with no readable
        // destination, one that went elsewhere, or one mined after the answer backs nothing, and our key pair there is no
        // backing by itself. Unbacked, the store part gives it no asked record ([adoptKeyOffer]), so the key stays one this
        // phone never asked for (FC-2B) and a later key exchange with that key waits for Accept. Written for every taken
        // answer, so a stale entry never outlives a verdict. The address and key go to [unbackedOldAnswerKeys] as well
        // (every pass, so after a restart too): the key exchange part holds a repeat of that key for Accept even where our
        // key pair stands ([oldAnswerKeyUnasked]).
        val filedUnder = if (leg == AnswerVerdict.LEG3) answerFiledUnder(answer) else null
        val unbackedKey =
            filedUnder?.let { address ->
                answerKey(answer.memo, address)?.let { key -> zchatPreferences.resolvePeerAddress(address) to key }
            }
        if (leg == AnswerVerdict.LEG3 && !oldAnswerIsBacked(answer, filedUnder, ownKex)) {
            unbackedOldAnswerTx += answer.txId
            unbackedKey?.let { unbackedOldAnswerKeys += it }
        } else {
            unbackedOldAnswerTx -= answer.txId
            unbackedKey?.let { unbackedOldAnswerKeys -= it }
        }
        mapAskedAnswer(answer)
        // ZC-1137, ZC-757 (k) round 9 (R1): an answer this pass took by leg 1 or 2, with the address it claims itself
        // (resolved) and the key it carries ([answeredOwnKeyExchange]); the address its id is filed under never stands in.
        if ((leg == AnswerVerdict.LEG1 || leg == AnswerVerdict.LEG2) && claimed != null && claimedCanon != null) {
            answersTakenInPass += TakenAnswer(answer.convId, claimedCanon, answerKey(answer.memo, claimed))
        }
        handleKEXMessage(answer.memo, userAddress, answer.txId, mayActOnInboundHandshake = true, minedHeight = answer.height)
    }

    /**
     * ZC-757 (k) round 9 — [answer]'s id is filed under an address other than the one it claims ([claimedCanon]), and an
     * own key exchange under that id paid a text whose receivers sit within the claimed address: the id mapping (a
     * restored own id filed under another holder of that receiver) is not the answerer. Any read that fails answers no.
     * Round 14 (ZC-1166): only when no text our own key exchanges under that id paid is the filed address itself (read
     * as it stands or resolved): we paid only a receiver form inside the filed address, so the filing is a guess by the
     * restore (marked or not; our own message under the id files it unmarked, as an earlier build did). A chat this phone
     * started with a receiver form of the peer's own address is filed under exactly the text it paid, which the peer
     * answers claiming its full address: it takes the pre-ZC-757 path.
     * Round 15 (ZC-1167): refused when SOME text our own key exchanges under that id paid is not the filed address (as
     * it stands or resolved) and lies within the claimed address, even when another of them paid the filed address
     * itself (an earlier build sent our key exchange to the filed address under that id). And while the outputs of one
     * of those key exchanges cannot be read this pass, the answer waits (refused this pass, nothing written, judged
     * again by a later pass).
     */
    private fun answerClaimsAnotherHolder(
        answer: InboundAnswer,
        claimedCanon: String?,
        ownKex: List<OwnMinedKex>,
        waitOnUnreadable: Boolean = true,
    ): Boolean =
        runCatching {
            val claimed = answer.claimed ?: return@runCatching false
            val filed = zchatPreferences.getPeerByConversationId(answer.convId) ?: return@runCatching false
            val filedCanon = zchatPreferences.resolvePeerAddress(filed)
            val underId = ownKex.filter { it.convId == answer.convId }
            claimedCanon != null &&
                filedCanon != claimedCanon &&
                (
                    (waitOnUnreadable && underId.any { it.outputsUnreadable }) ||
                        underId.flatMap { it.paidTexts }.any { p ->
                            p != filed &&
                                zchatPreferences.resolvePeerAddress(p) != filedCanon &&
                                (ZcashReceivers.within(p, claimed) || ZcashReceivers.within(p, claimedCanon))
                        }
                )
        }.getOrDefault(false)

    /**
     * ZC-757 (k) round 12 (ZC-1155) — the txids of [answers] that [takeAskedAnswer] refuses on the merits
     * ([answerClaimsAnotherHolder] without the wait on unreadable outputs). Round 15b: an answer that only waits for our
     * outputs to be read is not in it ([answersWaitingOnUnreadableOutputs]).
     */
    private fun refusedAnswerTxIds(
        answers: List<InboundAnswer>,
        ownKex: List<OwnMinedKex>,
    ): Set<String> =
        answers
            .filter { answer ->
                val claimedCanon = answer.claimed?.let { zchatPreferences.resolvePeerAddress(it) }
                answerClaimsAnotherHolder(answer, claimedCanon, ownKex, waitOnUnreadable = false)
            }.mapTo(HashSet()) { it.txId }

    /**
     * ZC-757 (k) round 15b — the [answers] [takeAskedAnswer] refuses this pass only because one of our own key exchanges
     * under their id has outputs this pass cannot read (judged again by a later pass): they hold the processed-KEX floor
     * below their height, and their id's filed address keeps its stored KEXACK set this pass.
     */
    private fun answersWaitingOnUnreadableOutputs(
        answers: List<InboundAnswer>,
        ownKex: List<OwnMinedKex>,
    ): List<InboundAnswer> =
        answers.filter { answer ->
            val claimedCanon = answer.claimed?.let { zchatPreferences.resolvePeerAddress(it) }
            answerClaimsAnotherHolder(answer, claimedCanon, ownKex) &&
                !answerClaimsAnotherHolder(answer, claimedCanon, ownKex, waitOnUnreadable = false)
        }

    /**
     * ZC-1571 (owner W-133, option A) — the mined, received key exchanges under an id this phone has not filed that still
     * belong to an ESTABLISHED contact's root material, as (contact, txid). The sender files its own id under us, so it
     * folds such a key exchange; without this the two phones' KEX material never converged. Taken only when the payload's
     * verified sender is a contact whose stored key equals the payload's key (the key-match rule of
     * [E2EEncryption.mayRemapConvIdForKexAck], without its first-contact half: no stored key, nothing taken). A different
     * key never enters. Nothing is filed or remapped here; the material only.
     */
    private fun attributeUnfiledKex(candidates: List<UnfiledKexCandidate>): List<Pair<String, String>> =
        candidates.mapNotNull { c ->
            if (zchatPreferences.getPeerByConversationId(c.convId) != null) return@mapNotNull null
            val contact = zchatPreferences.resolvePeerAddress(c.sender)
            val held = zchatPreferences.getE2EPeerPublicKey(contact) ?: return@mapNotNull null
            if (held == c.publicKey) contact to c.txId else null
        }

    // ZC-1121: whether this view model's last history pass skipped a received transaction mined at or below the upgrade height
    // (hidden, or its memo unreadable), set by every pass before its key offers are handled; in memory only.
    @Volatile
    private var oldInboundUnreadInPass: Boolean = false

    /**
     * ZC-599 (money recheck 26 Oct, finding 1) — [key] at [peerAddress] came only from an old answer no own key exchange
     * backs ([takeAskedAnswer]) and no asked record names it (an Accept or an asked answer of that key puts one).
     */
    private fun oldAnswerKeyUnasked(
        peerAddress: String,
        key: String,
        unreadInPass: Boolean,
    ): Boolean =
        // The key alone first: no store read on the common path (no old answer carried this key).
        (
            unbackedOldAnswerKeys.any { it.second == key } &&
                (zchatPreferences.resolvePeerAddress(peerAddress) to key) in unbackedOldAnswerKeys ||
                // ZC-1121: the set is in memory only and refilled from the old answers a pass reads. While the last pass
                // skipped a received transaction at or below the upgrade height (hidden, memo unreadable), an old answer
                // there may have brought this key with nothing to back it (after a restart, nothing says otherwise): with no
                // asked record it fails towards the hold. Nothing is stored for it. ZC-1129: the flag of the pass that
                // handed the offer over ([unreadInPass]), not of a later pass that may have cleared it meanwhile.
                unreadInPass
        ) &&
            zchatPreferences.getKexAskedKey(peerAddress) != key

    /** ZC-599 — an asked answer's id, mapped to the address it claims when it has no entry (and a chat may be offered there). */
    private fun mapAskedAnswer(answer: InboundAnswer) {
        if (zchatPreferences.getPeerByConversationId(answer.convId) == null) {
            answer.claimed?.takeIf { mayOfferInboundChat(it) }?.let { zchatPreferences.setConversationMapping(answer.convId, it) }
        }
    }

    /**
     * ZC-599 (money recheck 26 Oct, finding 1; round 3) — an own mined key exchange at or below the old [answer] backs
     * it when it went to [filedUnder], the address the answer is filed under, read as leg 2 reads it ([judgeAnswer]'s
     * sentThere): a destination text that resolves to that address, or, for a key exchange under the answer's own id,
     * a text whose receivers sit within that address. A key exchange with no readable destination (restore) backs
     * nothing, nor does one that went elsewhere: both fail towards the hold.
     */
    private fun oldAnswerIsBacked(
        answer: InboundAnswer,
        filedUnder: String?,
        ownKex: List<OwnMinedKex>,
    ): Boolean {
        if (filedUnder == null) return false
        val canonical = zchatPreferences.resolvePeerAddress(filedUnder)
        return ownKex.any { kex ->
            kex.height <= answer.height &&
                kex.recipients.any { text ->
                    zchatPreferences.resolvePeerAddress(text) == canonical ||
                        (
                            kex.convId == answer.convId &&
                                (ZcashReceivers.within(text, filedUnder) || ZcashReceivers.within(text, canonical))
                        )
                }
        }
    }

    private suspend fun convertToConversationsInPass(
        transactions: List<Transaction>,
        userAddress: String,
        hiddenMsgIds: Set<String>,
        pendingMsgs: List<ChatMessage>,
        paidReqIds: Set<String>,
        historyScanComplete: Boolean,
        nextTtlExpiry: NextTtlExpiry,
        zbootPass: ZbootHistoryPass,
        historyPass: HistoryPass,
    ): List<Conversation> {
        val messagesByPeer = mutableMapOf<String, MutableList<ChatMessage>>()
        // ZC-1082 (review finding 2): the known peers are read again once in each pass.
        knownPeersInPass = null
        // C3 (B2 review item 7): the requests our outgoing ZREQ_FULFILL payments in this pass paid.
        val fulfilledSeenThisPass = mutableSetOf<String>()
        // R8-fixup F7: mined payments of our own requests seen this pass (request id to the most any one of them carried).
        val incomingFulfils = HashMap<String, Long>()
        // Round 8 P2: our own ZREQ_FULFILL payments as this pass saw them, read from every outgoing transaction's memos
        // before any rendering path can skip it, so the fulfil reconcile (reconcileStartedFulfils) never misses one.
        val ownFulfils = OwnFulfilSightings()

        // A5 restore key recovery (KR-2, KR-3; RestoreKexPolicy). A pass is STABLE when the history scan is
        // complete and it sees exactly the transactions the previous complete pass saw, so the list cannot be
        // the one from before the SDK's last batch. Only a stable, gap-free pass may act on a historical
        // inbound KEX or open a restored peer's send gate.
        val passFingerprint = transactions.mapTo(HashSet()) { it.id.txIdString() to it.overview.minedHeight?.value }.hashCode()
        val passStable = historyScanComplete && lastCompletePassFingerprint == passFingerprint
        if (lastCompletePassFingerprint != passFingerprint) restoreRecheckStreak = 0
        var memoReadFailures = 0
        // Of those, our own (sent) transactions: one of them may carry our latest key (see ownKeySightings).
        var ownMemoReadFailures = 0
        // ZC-074: the lowest mined height of an inbound transaction whose memo could not be read (it may hold a key
        // offer): the processed-KEX ceiling stays below it (see limitKexFloor below).
        var lowestUnreadInboundMinedHeight: Long? = null
        // Our own encrypted messages this pass could not read (no conversation id, no session yet, or the
        // outgoing peer did not resolve). Their counters never reached the send floor.
        var unattributedOwnEnvelopeGaps = 0
        val ownEnvelopeGapConvIds = mutableSetOf<String>()
        val ownEnvelopeGapPeers = mutableSetOf<String>()
        // Last verified MINED inbound KEX key per convId, and the peer key our own mined KEXACK answered with
        // the key we still hold (applied after the loop): no second KEXACK is paid for it after a restore.
        val lastInboundKexKeyByConv = HashMap<String, String>()
        val peerKeyAckedOnChain = HashMap<String, String>()
        // Inbound KEX memos, handled AFTER the loop so our own KEX/KEXACK later in this pass
        // (key recovery, acked-key evidence) is read first: memo, txid, mined height (null = not mined yet; KI-24).
        val inboundKeyOffers = mutableListOf<Triple<String, String, Long?>>()
        // ZC-599 (5.4 item 2): this wallet's own MINED key exchanges read so far (id, height, the addresses they paid), and
        // the received mined answers the loop could not judge yet (judged again after it, before the inbound key offers).
        val ownMinedKexSent = mutableListOf<OwnMinedKex>().also { ownMinedKexInPass = it }
        // ZC-1137: the answers this pass takes (leg 1 or 2), read by answeredOwnKeyExchange.
        answersTakenInPass = Collections.synchronizedSet(HashSet())
        val answersToJudge = mutableListOf<InboundAnswer>()
        // ZC-599 (money recheck 26 Oct, finding 2): the old answers (leg 3) the loop judged asked, taken after it.
        val oldAnswersToTake = mutableListOf<InboundAnswer>()
        // ZC-1121: whether this pass skipped a received transaction mined at or below the upgrade height (hidden, or its memo
        // unreadable): an old answer there is not judged, so its key may be missing from [unbackedOldAnswerKeys].
        var oldInboundUnread = false
        // ZC-1128: the hidden received pre-upgrade answers this pass read (a hidden row is never shown, so its memo may still
        // be read); judged after the loop like an old answer, and only an unbacked one raises [oldInboundUnread].
        val hiddenOldAnswers = mutableListOf<InboundAnswer>()
        // ZC-949 (FIRST-CONTACT-SPEC 5.5 item 2a): every received mined answer of this pass, for the settled test.
        val minedAnswers = mutableListOf<InboundAnswer>()
        var waitingHistoricalHandshakes = 0
        // P2d (2): every one of our own verified mined KEX/KEXACK keys, in scan order (oldest first), with the
        // conversation it was sent in. Restore recovery runs after the loop from each peer's LATEST key.
        val ownKeySightings = mutableListOf<Pair<String, String>>()
        // Our own mined KEXACKs (conversation, our key, the inbound peer key it answered), judged after recovery.
        val ownMinedKexAcks = mutableListOf<Triple<String, String, String?>>()
        // P2d (3): our own encrypted messages this pass could not read, by header (direction and counter in clear),
        // per resolved peer / per conversation / unattributed; and the peers and conversations with one whose
        // header could not be parsed (those keep the send gate shut, as before).
        val unreadOwnEnvelopesByPeer = HashMap<String, MutableList<Ciphertext>>()
        val unreadOwnEnvelopesByConv = HashMap<String, MutableList<Ciphertext>>()
        val unattributedUnreadOwnEnvelopes = mutableListOf<Ciphertext>()
        val unparsedOwnEnvelopePeers = mutableSetOf<String>()
        val unparsedOwnEnvelopeConvIds = mutableSetOf<String>()
        val rootChangedPeers = mutableSetOf<String>()
        // ZC-1586: each peer's own KEX/KEXACK scalars as they stood before this pass first wrote them; a pass that leaves them
        // changed drops the cached processors below, as a changed set does.
        val ownScalarsBefore = HashMap<String, Pair<String?, String?>>()
        // ZC-1608: what this pass decides for each peer's own KEX/KEXACK scalars, applied once after the loop: the newest own
        // non-expired key exchange of each kind met (the last in pass order, the value the per-row writes ended on), and the
        // own key exchanges the wallet lists as expired and never mined (ZC-1583).
        val ownKexScalarNewest = HashMap<String, String>()
        val ownKexAckScalarNewest = HashMap<String, String>()
        val ownKexExpiredUnmined = HashMap<String, MutableSet<String>>()
        val ownKexAckExpiredUnmined = HashMap<String, MutableSet<String>>()
        // R3-3 (1): headers of our own encrypted messages to a peer under a conversation id that is NOT its current
        // one (read or not), and the peers with one whose header or conversation id is unknown. The pass end settles
        // an older id's carried send counters from them (E2ERatchet.settleLegacyJump).
        val ownEnvelopesUnderOlderConv = HashMap<String, MutableList<Ciphertext>>()
        val ownEnvelopeHeaderUnknownPeers = mutableSetOf<String>()
        val sendConvIdsThisPass = HashMap<String, String>()
        val peersWithOlderConvEnvelopes = mutableSetOf<String>()

        // Track confirmed message IDs to remove from pending later
        val confirmedIds = mutableSetOf<String>()

        // ZC-310 (KI-127): the ids of our own sends the wallet lists as expired and never mined (SendTransaction.Failed,
        // no mined height). Their rows are built like any other, so everything the loop and the F4 reconcile read
        // stays as it was, and are taken out of the pass after that reconcile (below): they are never shown.
        val expiredUnminedOwnTxIds = mutableSetOf<String>()

        // R5 — peers whose seed-derived key was RE-DERIVED in THIS rescan pass (below). Used at
        // pass end to reconcile the send gate: a peer recovered THIS pass keeps its gate armed
        // (the root only converges on the NEXT full pass, so its counter floor can't be trusted
        // yet); a peer recovered in a PRIOR pass is un-gated once this fully-converged pass has
        // re-established (or proven absent) its own-outgoing floor. See reconcileRecoveryMarker.
        val recoveredThisPass = mutableSetOf<String>()

        // Reactions collected during the loop, keyed by the TARGET message's txid. Attached in a
        // post-pass after every message row is built, so the target exists no matter whether the
        // reaction tx was processed before or after the message it points at. Without this pass
        // incoming reactions were parsed and then dropped — they never reached the UI.
        val reactionsByTarget =
            mutableMapOf<String, MutableList<co.electriccoin.zcash.ui.screen.chat.model.MessageReaction>>()

        // R2-5 (c): the stored-text cache keys of each encrypted message this pass read, so an expired message's
        // decrypted text can be deleted with it (its tombstone keeps it from ever being decrypted again).
        val decryptedTextKeysByMessage = HashMap<String, MutableSet<String>>()

        // IMPORTANT: Sort transactions in chronological order (oldest first) so that
        // when processing replies, the original message has already been added to messagesByPeer.
        // This fixes the bug where replies were placed in new conversations because the
        // replyToTxId lookup couldn't find the original message (which was processed later).
        //
        // Sort by timestamp first (not minedHeight) to ensure pending outgoing messages
        // are processed in the correct chronological position. Previously, null minedHeight
        // was treated as Long.MAX_VALUE, causing pending outgoing messages to be sorted last.
        // This meant incoming REF replies couldn't find the original outgoing message.
        val sortedTransactions = transactions.sortedWith(
            compareBy<Transaction> { it.timestamp ?: Instant.MIN }
                .thenBy { it.overview.minedHeight?.value ?: 0L }
        )

        // Diagnostic counters for summary telemetry
        var diagTotal = 0; var diagOutgoing = 0; var diagIncoming = 0
        var diagSkipHidden = 0; var diagSkipNoMemo = 0; var diagSkipStatus = 0
        var diagSkipReaction = 0; var diagSkipKEX = 0; var diagSkipGroup = 0
        var diagSkipUnlock = 0; var diagSkipParseFail = 0; var diagSkipPeerFail = 0
        var diagSkipBlank = 0; var diagAdded = 0

        // B1/B2 (post-review rebuild): recompute the convergent KEX/KEXACK txid sets from THIS scan rather
        // than accumulating incrementally (the accumulate path was gated by the once-ever receive guard, so
        // it never converged and broke multi-KEX chats). Collect every MINED KEX/KEXACK txid per convId
        // (both directions) here; after the loop we REPLACE the stored sets. Both devices see the same
        // on-chain txs → identical sets → identical root; a reorged tx simply disappears next scan.
        val scannedKexByConv = HashMap<String, MutableSet<String>>()
        val scannedKexAckByConv = HashMap<String, MutableSet<String>>()
        // ZC-1792 (W-142, P-A): the heights of the key exchanges met so far this pass, and its failed earlier-root tries.
        val oldRootPass = OldRootFallback.Pass()
        // ZC-1824: the height of EVERY mined transaction, before the loop. Block timestamps do not follow heights, so a key
        // exchange mined below a row can come after it in the time-ordered loop; candidates still take only txids at or
        // below the row's height, and only the ones the current root reads.
        for (minedTx in sortedTransactions) {
            val minedAt =
                minedTx.overview.minedHeight
                    ?.value
                    ?.takeIf { it > 0L }
            // ZC-1865 (QA2 pa4): a transaction the wallet lists with no height (our own key exchange after a Re-establish,
            // not mined yet) is pending, not unknown: it will be mined above every row (OldRootFallback.candidates).
            if (minedAt != null) {
                oldRootPass.noteMined(minedTx.id.txIdString(), minedAt)
            } else {
                oldRootPass.notePending(minedTx.id.txIdString())
            }
        }
        // ZC-1571 (W-133): every mined, verified key exchange received this pass, for attributeUnfiledKex after the loop.
        val receivedMinedKex = mutableListOf<UnfiledKexCandidate>()
        // Round 10b R10B-2 (F-R9C-3): every mined KEXACK this pass saw (both directions), for each chat's session height.
        val kexAckSightings = mutableListOf<KexAckSighting>()
        // ZC-1792 F2/F3: the ratchet failures and fresh opens of this pass, settled after the loop against the KEXACK heights.
        val decryptOutcomes = DecryptOutcomes()

        // Round 8 P3: the contact book's addresses, read once per pass and only when a sender hash has no address.
        val knownContactAddresses: List<String> by lazy {
            runCatching { contactBook.getAllContacts().map { it.address } }
                .onFailure { Log.w("ZCHAT_V4", "contact book unreadable for hash routing: ${it.javaClass.simpleName}") }
                .getOrDefault(emptyList())
        }

        // ZC-1480 item 1: the chats this phone holds (conversation peers) and the contacts reached over the relays (a bound
        // relay key), read once per pass. A relay-only contact has no on-chain rows and is not in the contact book.
        val relayAndChatPeers: Set<String> by lazy {
            runCatching { zchatPreferences.getAllConversationPeerAddresses() + zchatPreferences.getPeersWithNostrPubkey() }
                .onFailure { Log.w("ZCHAT_V4", "chat peers unreadable for hash routing: ${it.javaClass.simpleName}") }
                .getOrDefault(emptySet())
        }

        // ZC-1279: one reading per transaction; a transaction of mixed memo kinds puts its other units right behind this one.
        val memoReads = ArrayDeque(sortedTransactions.map { it to null as List<String>? })
        while (memoReads.isNotEmpty()) {
            val (tx, memoUnit) = memoReads.removeFirst()
            diagTotal++
            val messageId = tx.id.txIdString()
            val txType = if (tx is co.electriccoin.zcash.ui.common.repository.SendTransaction) "SEND" else "RECEIVE"
            val height = tx.overview.minedHeight?.value ?: -1L
            if (txType == "SEND") diagOutgoing++ else diagIncoming++
            Log.d("ZCHAT_THREADING", "Processing tx: $messageId, type=$txType, height=$height")

            // Skip hidden messages
            if (messageId in hiddenMsgIds) {
                // Round 8 P2: a hidden own payment is not read here, so it could be a fulfil.
                ownFulfils.noteUnread(tx)
                // ZC-1121: a hidden received transaction could be an old answer this pass does not judge. ZC-1128: its memo is
                // read (nothing of it is shown or handled): only a key-exchange answer, judged after the loop, or a memo that
                // cannot be read raises the flag; a hidden plain chat message brings no key and does not.
                if (tx !is co.electriccoin.zcash.ui.common.repository.SendTransaction && height > 0 && minedAtOrBeforeUpgrade(height)) {
                    // ZC-1279: read by kind as the visible path is, so an answer beside other memos still counts as an old answer.
                    val hiddenMemos =
                        try {
                            ZMSGProtocol.splitMemosByKind(transactionRepository.getMemos(tx)).map { it.joinToString("\n").trim() }
                        } catch (e: Exception) {
                            Log.w("ZCHAT_FLOW", "getMemos failed for hidden $messageId: ${e.message}")
                            null
                        }
                    if (hiddenMemos == null) oldInboundUnread = true
                    hiddenMemos?.filter(ZMSGProtocol::isKEXAckMessage)?.forEach { hiddenMemo ->
                        val parsed = ZMSGProtocol.parseKEXAckMessage(hiddenMemo)
                        if (parsed == null) {
                            oldInboundUnread = true
                        } else {
                            val sender = E2EEncryption.parseKEXAckPayloadFull(parsed.second, null)?.senderAddress
                            hiddenOldAnswers += InboundAnswer(hiddenMemo, messageId, height, parsed.first, sender)
                        }
                    }
                }
                diagSkipHidden++
                Log.d("ZCHAT_FLOW", "SKIP hidden: $messageId")
                continue
            }

            // Get memos for this transaction
            val txMemos =
                memoUnit
                    ?: try {
                        transactionRepository.getMemos(tx)
                    } catch (e: Exception) {
                        Log.w("ZCHAT_FLOW", "getMemos failed for $messageId: ${e.message}")
                        memoReadFailures++ // KR-3: this pass did not read the whole history
                        if (tx is co.electriccoin.zcash.ui.common.repository.SendTransaction) {
                            ownMemoReadFailures++
                        } else {
                            tx.overview.minedHeight?.value?.takeIf { it > 0 }?.let { h ->
                                lowestUnreadInboundMinedHeight = minOf(lowestUnreadInboundMinedHeight ?: h, h)
                            }
                            // ZC-1121: an unreadable received memo could be an old answer this pass does not judge.
                            if (height > 0 && minedAtOrBeforeUpgrade(height)) oldInboundUnread = true
                        }
                        emptyList()
                    }
            if (memoUnit == null) ownFulfils.note(tx, txMemos)
            if (txMemos.isEmpty()) {
                diagSkipNoMemo++
                Log.d("ZCHAT_FLOW", "SKIP no-memo: $messageId type=$txType")
                continue
            }

            // ZC-1279: every reader below sees one unit: all the memos when they are one kind, as before. Processed-KEX marks,
            // legs and signatures stay as they are, by txid and by signature; a message unit touches none of them.
            val memos =
                if (memoUnit != null) {
                    memoUnit
                } else {
                    val units = ZMSGProtocol.splitMemosByKind(txMemos)
                    memoReads.addAll(0, units.drop(1).map { tx to it })
                    units.first()
                }
            val memoText = memos.joinToString("\n").trim()

            // AI credit top-up: a wallet PAYMENT to the AI-credit address (memo "ai-topup:<token>"), NOT a
            // chat message. Skip it so it never surfaces as a bogus conversation in the chat list. Re-derived
            // every scan (restore-proof, no local-state reliance). It still appears in the wallet's
            // Transaction History and the AI section's top-up history. (#9)
            if (memoText.startsWith(co.electriccoin.zcash.ui.screen.chat.model.ZMSGConstants.AI_TOPUP_MEMO_PREFIX)) {
                Log.d("ZCHAT_FLOW", "SKIP ai-topup memo (not a conversation): $messageId")
                continue
            }

            // Check for remote kill signal on incoming (received) transactions
            if (tx is co.electriccoin.zcash.ui.common.repository.ReceiveTransaction) {
                checkForRemoteKill(
                    amountZatoshi = tx.amount.value,
                    memo = memoText,
                    txId = messageId,
                    // The mined height is what lets the kill check tell a genuinely new signal from
                    // this wallet's re-delivered history. Null while unconfirmed — the check refuses
                    // to act on that and re-evaluates once the transaction is mined.
                    minedHeight = tx.overview.minedHeight?.value
                )
            }

            // Check for status messages (not regular chat messages)
            if (ZMSGProtocol.isStatus(memoText)) {
                // Parse and store peer status, but don't add as a chat message
                val parsedStatus = ZMSGProtocol.parseStatus(memoText, addressCache)
                if (parsedStatus != null && parsedStatus.senderAddress != null) {
                    peerStatuses.update { it + (parsedStatus.senderAddress to UserStatus(parsedStatus.statusText)) }
                    zchatPreferences.setPeerStatus(parsedStatus.senderAddress, parsedStatus.statusText)
                }
                diagSkipStatus++
                Log.d("ZCHAT_FLOW", "SKIP status: $messageId")
                continue // Status messages don't appear in chat
            }

            // Reactions are metadata, not chat rows — but instead of dropping them, collect them
            // against their target message's txid so the post-pass below can attach them. Read
            // receipts remain pure metadata and are dropped.
            if (ZMSGProtocol.isReaction(memoText)) {
                diagSkipReaction++
                val parsedReaction = ZMSGProtocol.parseReaction(memoText, addressCache)
                if (parsedReaction != null) {
                    reactionsByTarget.getOrPut(parsedReaction.targetTxId) { mutableListOf() }.add(
                        co.electriccoin.zcash.ui.screen.chat.model.MessageReaction(
                            emoji = parsedReaction.emoji,
                            senderAddress = parsedReaction.senderAddress,
                            // Stable, PERSISTED first-seen anchor for un-mined reaction txs (B3) so the
                            // countdown survives VM recreation on chat re-entry + process death.
                            timestamp = tx.timestamp?.also { zchatPreferences.clearPendingTxFirstSeen(tx.id.txIdString()) }
                                ?: Instant.ofEpochMilli(
                                    zchatPreferences.getOrPutPendingTxFirstSeenMillis(tx.id.txIdString(), System.currentTimeMillis())
                                ),
                        ),
                    )
                } else {
                    Log.d("ZCHAT_FLOW", "SKIP unparseable reaction: $messageId")
                }
                continue
            }
            if (ZMSGProtocol.isReadReceipt(memoText)) {
                diagSkipReaction++
                Log.d("ZCHAT_FLOW", "SKIP receipt: $messageId")
                continue
            }

            // ZC-638: the legacy unsigned key memo (no build since v2.9.3 writes one) is skipped whole: nothing is stored
            // for it and it is never shown. A message that only contains that text is an ordinary message.
            if (memoText.startsWith("E2E_INIT:")) {
                diagSkipKEX++
                Log.d("ZCHAT_FLOW", "SKIP legacy key memo: $messageId")
                continue
            }

            // Handle KEX (Key Exchange) messages - don't appear in chat
            if (ZMSGProtocol.isKEXMessage(memoText) || ZMSGProtocol.isKEXAckMessage(memoText)) {
                val txIdStr = tx.id.txIdString()
                // Collect this KEX/KEXACK into the per-scan convergent set (BOTH directions, MINED only).
                // convId comes from the signed KEX/KEXACK payload — present on send AND receive — so both
                // devices key the same tx to the same conversation. Replaced into prefs after the loop.
                //
                // D7 (security): include a txid ONLY when (a) the payload's self-signature VERIFIES and
                // (b) the verified pubkey is one we ALREADY hold for the resolved peer (our key for our
                // own sent KEX/KEXACK, the peer's key for theirs). Without this, an attacker who learns
                // the on-chain convId could mine a memo whose txid folds into OUR convergent root but not
                // the real peer's → root desync = availability DoS (confidentiality was never at risk —
                // the root also mixes the ECDH secret). Unmapped-peer (first contact) txids are still
                // carried by the legacy scalar setE2EKexTxId/setE2EKexAckTxId path below, unchanged.
                if (tx.overview.minedHeight != null) {
                    val scanKex = ZMSGProtocol.parseKEXMessage(memoText)
                    val scanAck = if (scanKex == null) ZMSGProtocol.parseKEXAckMessage(memoText) else null
                    val convId = scanKex?.first ?: scanAck?.first
                    // parseKEX(Ack)PayloadFull returns non-null ONLY if the embedded self-signature verifies.
                    val scanKexFull = scanKex?.second?.let { E2EEncryption.parseKEXPayloadFull(it, null) }
                    val scanPayloadPub =
                        scanKexFull?.publicKey
                            ?: scanAck?.second?.let { E2EEncryption.parseKEXAckPayloadFull(it, null)?.publicKey }
                    val scanPeer = convId?.let { zchatPreferences.getPeerByConversationId(it) }
                    if (scanPayloadPub != null) {
                        if (tx !is co.electriccoin.zcash.ui.common.repository.ReceiveTransaction) {
                            // A5 — our own key, seen on chain: key generation never hands it to another chat,
                            // and re-deriving it for this peer arms the send gate (SeedDerivedE2EKeyProvider).
                            HistoricalOwnKeyLedger.PROCESS.note(scanPayloadPub, scanPeer, tx.overview.minedHeight?.value ?: 0L)
                            if (convId != null) ownKeySightings += convId to scanPayloadPub
                        } else if (scanKex != null && convId != null) {
                            lastInboundKexKeyByConv[convId] = scanPayloadPub
                            // ZC-1571 (W-133): a mined key exchange received under an id this phone may never have
                            // filed; judged after the loop (attributeUnfiledKex) by its verified sender and key.
                            scanKexFull?.senderAddress?.let { sender ->
                                receivedMinedKex += UnfiledKexCandidate(convId, txIdStr, sender, scanPayloadPub)
                            }
                        }
                    }
                    // D1-recovery Stage 3b — restore-time key recovery. A SENT (non-Receive) KEX/KEXACK carries OUR
                    // OWN historical pubkey; after a seed restore no our-key is stored. P2d: the key is recovered
                    // AFTER the loop, from the LATEST of our keys for the peer (ownKeySightings above): after a
                    // Reset Encryption the peer holds our newest key, and recovering the first one the scan met
                    // (the oldest) left the chat broken for good. Our own mined KEXACK is judged after recovery too.
                    val ownMinedKexAck = scanAck != null && tx !is co.electriccoin.zcash.ui.common.repository.ReceiveTransaction
                    if (ownMinedKexAck && convId != null && scanPayloadPub != null) {
                        ownMinedKexAcks += Triple(convId, scanPayloadPub, lastInboundKexKeyByConv[convId])
                    }
                    // Round 10b R10B-2 (F-R9C-3): every mined KEXACK, for the chat's session height (markPreSessionRows).
                    val ackHeight = tx.overview.minedHeight?.value
                    if (scanAck != null && convId != null && ackHeight != null) {
                        kexAckSightings +=
                            KexAckSighting(
                                convId = convId,
                                height = ackHeight,
                                payloadPub = scanPayloadPub,
                                own = tx !is co.electriccoin.zcash.ui.common.repository.ReceiveTransaction,
                            )
                    }
                    // CROSS-VERSION COMPAT (xver §2.1) — fold on convId ALONE, byte-for-byte as live 2.12.4
                    // does. This scanned set REPLACES the stored set that feeds the convergent ratchet root
                    // (canonicalTxidMaterial → deriveRatchetRoot); the two peers MUST compute the identical
                    // set or their roots desync and every E2E message fails AEAD in both directions. The
                    // pubkey-match "D7" gate (verify + current-key match) excluded rotated-away / legacy /
                    // pre-address-embedding txids that a 2.12.4 peer still folds → our set shrank → root
                    // divergence for any rotation/reinstall/Reset-Encryption/seed-restore history, with NO
                    // in-app recovery until BOTH sides upgrade. Confidentiality was never at stake (the root
                    // also mixes the ECDH secret); D7 bore only on an availability DoS that live 2.12.4 is
                    // equally subject to — so matching 2.12.4 here is not a regression from the deployed state.
                    // D7 can only be reintroduced once the whole fleet folds identically (no 2.12.4 peers left).
                    if (convId != null) {
                        if (ZMSGProtocol.isKEXMessage(memoText)) {
                            scannedKexByConv.getOrPut(convId) { mutableSetOf() }.add(txIdStr)
                        } else if (ZMSGProtocol.isKEXAckMessage(memoText)) {
                            scannedKexAckByConv.getOrPut(convId) { mutableSetOf() }.add(txIdStr)
                        }
                    }
                }
                if (tx is co.electriccoin.zcash.ui.common.repository.ReceiveTransaction) {
                    // CATCH-UP-SYNC RACE FIX: when a KEX/KEXACK and a later TUNNEL-first-contact ZBOOT for
                    // the SAME peer land in ONE history scan, handleKEXMessage's convId→peer mapping write is
                    // ASYNC (viewModelScope.launch) and hasn't committed by the time convertToConversations
                    // routes the ZBOOT a few txs later in THIS synchronous scan — so getPeerByConversationId
                    // (the ZBOOT's convId fast-path) misses and it can't attribute this pass. Write the
                    // mapping SYNCHRONOUSLY here, but ONLY after parseKEXPayloadFull VERIFIES the (self-signed)
                    // payload and recovers the sender address, and ONLY on genuine first contact (no E2E key
                    // held yet) — so a malformed KEX can't pollute the map and an established peer's convId is
                    // never remapped by a forgeable self-signed KEX (mirrors handleKEXMessage's own guards,
                    // and setConversationMapping only fills peer→convId when none exists). Attribution/trust
                    // are unchanged; routeIncomingBoot still re-verifies the ZBOOT signature before adopting.
                    val kexParsedConvSender = ZMSGProtocol.parseKEXMessage(memoText)?.let { (cid, payload) ->
                        cid to E2EEncryption.parseKEXPayloadFull(payload, null)?.senderAddress
                    } ?: ZMSGProtocol.parseKEXAckMessage(memoText)?.let { (cid, payload) ->
                        cid to E2EEncryption.parseKEXAckPayloadFull(payload, null)?.senderAddress
                    }
                    val kexConvId = kexParsedConvSender?.first
                    val kexSender = kexParsedConvSender?.second
                    // KI-24 part A: the mined height goes with the txid, so a KEX the processed-KEX store evicted is
                    // still known as processed (its height floor) and is not handled again.
                    val kexMinedHeight = tx.overview.minedHeight?.value
                    val isAnswer = ZMSGProtocol.isKEXAckMessage(memoText)
                    // ZC-599 (5.4 items 1 and 7): the early mapping runs for a MINED key exchange only; an answer is mapped
                    // only once it was judged asked (below), so an answer nobody asked for and a memo that never mines
                    // leave no id entry.
                    if (!isAnswer &&
                        kexMinedHeight != null &&
                        kexConvId != null &&
                        kexSender != null &&
                        zchatPreferences.getE2EPeerPublicKey(kexSender) == null &&
                        mayOfferInboundChat(kexSender)
                    ) {
                        zchatPreferences.setConversationMapping(kexConvId, kexSender)
                        Log.d("KEX", "Sync convId→peer map for same-scan ZBOOT fast-path (first contact)")
                    }
                    if (isAnswer) {
                        // ZC-599, ZC-941 (5.4 items 2 and 7): an answer is used only when this phone asked, and is judged
                        // only once it is mined. One the loop cannot decide yet is judged again after it.
                        if (kexMinedHeight == null) {
                            Log.d("KEX", "Inbound answer not mined yet — not judged, nothing changed")
                        } else if (kexConvId != null) {
                            val answer = InboundAnswer(memoText, txIdStr, kexMinedHeight, kexConvId, kexSender)
                            minedAnswers += answer
                            val verdict = judgeAnswer(answer, ownMinedKexSent)
                            if (verdict == AnswerVerdict.LEG3) {
                                // ZC-599 (money recheck 26 Oct, finding 2): an old answer stays leg 3 and is mapped now, but
                                // whether an own key exchange backs it is decided after the loop, against all of them.
                                answerLegByTx[answer.txId] = verdict
                                mapAskedAnswer(answer)
                                oldAnswersToTake += answer
                            } else if (verdict != AnswerVerdict.NOT_ASKED) {
                                takeAskedAnswer(answer, userAddress, verdict, ownMinedKexSent)
                            } else {
                                answersToJudge += answer
                            }
                        }
                    } else {
                        // KR-2 — an inbound key offer (a KEX) generates our key and pays a
                        // KEXACK. It is judged after the loop, once this pass has read our own history.
                        inboundKeyOffers += Triple(memoText, txIdStr, kexMinedHeight)
                    }
                } else {
                    // FC-ID (5.3a item 2, revision 4a M1): this wallet's own MINED key exchange restores its id as own when
                    // the id has no entry yet, for the address the transaction's outputs name (never an own answer: its id
                    // is the other side's). No readable recipient: nothing is written.
                    val ownKexConvId = ZMSGProtocol.parseKEXMessage(memoText)?.first
                    if (ownKexConvId != null &&
                        tx.overview.minedHeight != null &&
                        zchatPreferences.getPeerByConversationId(ownKexConvId) == null
                    ) {
                        // ZC-1082: only for a destination that may vouch for the id (not a receiver form no single known
                        // address holds: the contact's answer is then judged by leg 2, with its mark). ZC-757 (k) round 10
                        // (ZC-1145): when the key exchange paid only a receiver form inside that address, the id is filed
                        // under it but never made its send id (no peer: entry): only the form's holder can read the id.
                        outgoingRecipientFromOutputs(tx)
                            ?.takeIf { it.vouched }
                            ?.let {
                                zchatPreferences.restoreOwnConversationId(ownKexConvId, it.address, asSendId = it.asSent == it.address)
                            }
                    }
                    // ZC-599 (5.4 item 2): what an inbound answer is judged against.
                    val ownKexHeight = tx.overview.minedHeight?.value
                    if (ownKexConvId != null && ownKexHeight != null) {
                        val paidTexts = paidTextsFromOutputs(tx)
                        ownMinedKexSent +=
                            OwnMinedKex(
                                ownKexConvId,
                                ownKexHeight,
                                outgoingRecipientsFromOutputs(paidTexts.orEmpty()),
                                paidTexts.orEmpty(),
                                outputsUnreadable = paidTexts == null,
                            )
                    }
                    // Keep the legacy scalar in sync for the derivation's backward-compat fold-in. ZC-1571 (Fable review of
                    // 242b2c113, finding 1): an own key exchange counts mined or NOT, as in 2.12.4: a reply sent before our
                    // KEX/KEXACK mines is sealed under a root that holds it, which the contact holds once it mines. One
                    // that expires unmined is dropped below (ZC-1583).
                    val convId = ZMSGProtocol.parseKEXMessage(memoText)?.first
                        ?: ZMSGProtocol.parseKEXAckMessage(memoText)?.first
                    val peer = convId?.let { zchatPreferences.getPeerByConversationId(it) }
                    // ZC-1583: one the wallet lists as expired and never mined (the ZC-310 test) can no longer mine, and the
                    // contact never holds it: it never becomes the scalar, and a scalar already holding it is dropped.
                    val expiredUnmined =
                        tx is co.electriccoin.zcash.ui.common.repository.SendTransaction.Failed &&
                            tx.overview.minedHeight == null
                    if (peer != null) {
                        ownScalarsBefore.getOrPut(peer) { zchatPreferences.getE2EKexTxId(peer) to zchatPreferences.getE2EKexAckTxId(peer) }
                    }
                    // ZC-1608: only collected here and written once after the loop. Writing at each row moved the scalar of a
                    // peer with two own key exchanges of one kind to the older one and back on every pass: a send in between
                    // was sealed under the older root, and a pass cut off in between left the older value stored.
                    if (peer != null && expiredUnmined) {
                        if (ZMSGProtocol.isKEXMessage(memoText)) {
                            ownKexExpiredUnmined.getOrPut(peer) { mutableSetOf() } += txIdStr
                        } else if (ZMSGProtocol.isKEXAckMessage(memoText)) {
                            ownKexAckExpiredUnmined.getOrPut(peer) { mutableSetOf() } += txIdStr
                        }
                    } else if (peer != null) {
                        if (ZMSGProtocol.isKEXMessage(memoText)) {
                            ownKexScalarNewest[peer] = txIdStr
                        } else if (ZMSGProtocol.isKEXAckMessage(memoText)) {
                            ownKexAckScalarNewest[peer] = txIdStr
                        }
                    }
                }
                diagSkipKEX++
                Log.d("ZCHAT_FLOW", "SKIP KEX: $messageId")
                continue
            }

            // Handle GROUP protocol messages (don't appear in regular chat)
            if (ZMSGGroupProtocol.isGroupMessage(memoText)) {
                // Round 8 MA2 (design §4.1): the handler is told about our own sends (the same test as the SEND/RECEIVE
                // label above), so our own sent invite is never taken as one we received.
                val ownSend = tx as? co.electriccoin.zcash.ui.common.repository.SendTransaction
                val ownGroupSend = ownSend?.recipient?.address?.let { ownGroupRecipient(tx, it) }
                // ZC-757 (k) recheck 3 finding 2: a row our own invite adds goes under the form actually paid when the
                // address it is filed under is not one this phone vouches for ([groupRecipientOf]).
                ownGroupSend?.let { send ->
                    groupRecipientOf(send).takeIf { it != send.address }?.let { historyPass.ownInviteRows[tx.id.txIdString()] = it }
                }
                // ZC-022 (KI-25 R9): with this pass's number, for the guard of the two admin branches.
                processGroupMessageInPass(
                    memoText,
                    tx.id,
                    tx.timestamp,
                    isOwnSend = ownSend != null,
                    // ZC-1082: the history's recipient as the pass files own sends (never a fee form; a receiver form
                    // under the one known address that holds it).
                    ownRecipient = ownGroupSend?.address,
                    minedHeight = tx.overview.minedHeight?.value,
                    pass = historyPass,
                )
                diagSkipGroup++
                Log.d("ZCHAT_FLOW", "SKIP group: $messageId")
                continue
            }

            // Check for payment requests
            var paymentRequestInfo: PaymentRequestInfo? = null
            if (ZMSGProtocol.isPaymentRequest(memoText)) {
                val parsedRequest = ZMSGProtocol.parsePaymentRequest(memoText, addressCache)
                if (parsedRequest != null) {
                    paymentRequestInfo = PaymentRequestInfo(
                        amountZatoshi = parsedRequest.amountZatoshi,
                        reason = parsedRequest.reason,
                        // Hide the "Pay" affordance once this request has been fulfilled (durable set),
                        // so the same on-chain request can't be paid twice.
                        isPaid = paidReqIds.contains(messageId),
                        paidTxId = null
                    )
                }
            }

            // Check for unlock messages (track which locked messages have been unlocked)
            if (ZMSGProtocol.isUnlock(memoText)) {
                val parsedUnlock = ZMSGProtocol.parseUnlock(memoText, addressCache)
                if (parsedUnlock != null) {
                    // Track the unlock (atomic update)
                    unlockedMessages.update { it + (parsedUnlock.originalTxId to messageId) }
                }
                diagSkipUnlock++
                Log.d("ZCHAT_FLOW", "SKIP unlock: $messageId")
                continue // Unlock messages don't appear as chat messages
            }

            // Check for time-locked messages
            var timeLockInfo: TimeLockInfo? = null
            // The ZTL| sender (hash, and the cached address) is read for routing by specialMemoSender below.
            if (ZMSGProtocol.isTimeLock(memoText)) {
                val parsedTimeLock = ZMSGProtocol.parseTimeLock(memoText, addressCache)
                if (parsedTimeLock != null) {
                    val currentTime = System.currentTimeMillis() / 1000
                    val currentHeight = _blockHeight.value
                    val isPaymentUnlocked = unlockedMessages.value.containsKey(messageId)
                    val unlockTxId = unlockedMessages.value[messageId]

                    // Determine if unlocked
                    val isUnlocked = when (parsedTimeLock.lockType) {
                        co.electriccoin.zcash.ui.screen.chat.model.TimeLockType.SCHEDULED ->
                            parsedTimeLock.unlockTimestamp != null && currentTime >= parsedTimeLock.unlockTimestamp
                        co.electriccoin.zcash.ui.screen.chat.model.TimeLockType.BLOCK_HEIGHT ->
                            currentHeight != null && parsedTimeLock.unlockBlockHeight != null &&
                                currentHeight >= parsedTimeLock.unlockBlockHeight
                        co.electriccoin.zcash.ui.screen.chat.model.TimeLockType.PAYMENT ->
                            isPaymentUnlocked
                        co.electriccoin.zcash.ui.screen.chat.model.TimeLockType.CONDITIONAL ->
                            isPaymentUnlocked // Conditional unlocks tracked the same way
                    }

                    timeLockInfo = TimeLockInfo(
                        lockType = when (parsedTimeLock.lockType) {
                            co.electriccoin.zcash.ui.screen.chat.model.TimeLockType.SCHEDULED -> TimeLockType.SCHEDULED
                            co.electriccoin.zcash.ui.screen.chat.model.TimeLockType.BLOCK_HEIGHT -> TimeLockType.BLOCK_HEIGHT
                            co.electriccoin.zcash.ui.screen.chat.model.TimeLockType.PAYMENT -> TimeLockType.PAYMENT
                            co.electriccoin.zcash.ui.screen.chat.model.TimeLockType.CONDITIONAL -> TimeLockType.CONDITIONAL
                        },
                        unlockTimestamp = parsedTimeLock.unlockTimestamp,
                        unlockBlockHeight = parsedTimeLock.unlockBlockHeight,
                        requiredPaymentZatoshi = parsedTimeLock.requiredPayment,
                        hint = parsedTimeLock.hint,
                        answerHash = parsedTimeLock.answerHash,
                        isUnlocked = isUnlocked,
                        unlockedBy = unlockTxId
                    )
                }
            }

            // Note: Platform fee address filtering for outgoing transactions is handled
            // inside resolveOutgoingPeerAddress() (Strategy 1 & 2), not here, to avoid
            // incorrectly discarding multi-output transactions.

            // Determine peer address and direction
            val isOutgoing = tx is co.electriccoin.zcash.ui.common.repository.SendTransaction

            // var (not val): an on-chain ZBOOT re-keys this row onto the peer that attributeBoot() resolves
            // it to (see the ZBOOT branch below), so a valid u1/zs conversation key replaces the raw convId
            // the 3-tier router falls back to when the shielded sender is unmapped.
            var peerAddress: String
            val displayMessage: String
            val unknownReason: UnknownReason?
            var outgoingFileHash: String? = null
            var incomingReplyToId: String? = null
            var incomingReplyPreview: String? = null
            var incomingFileHash: String? = null
            var capturedZfileContent: String? = null
            var capturedBlurhash: String? = null
            var capturedFileType: co.electriccoin.zcash.ui.screen.chat.model.ZFILEType? = null
            var capturedViewOnce = false
            // D9 "mark, don't reroute": outgoing stays true; the incoming branch downgrades this to
            // false when the RAW memo body was NOT a ratcheted E2E1 blob (forged-plaintext vector).
            var messageAuthenticated = true

            if (isOutgoing) {
                // For outgoing, resolve peer address with multi-layered fallbacks.
                val resolvedPeer = resolveOutgoingPeerAddress(
                    tx = tx,
                    memos = memos,
                    pendingMsgs = pendingMsgs
                )
                if (resolvedPeer == null) {
                    // P2b: an own ZBOOT whose recipient this pass cannot resolve still proves what we paid for.
                    recordOwnMinedZbootInPass(zbootPass, memoText.trim(), null, mined = tx.overview.minedHeight != null)
                    if (memoText.contains(OWN_ENVELOPE_MARKER)) {
                        // KR-3: one of our own encrypted messages whose counter this pass cannot floor by decrypting.
                        // P2d (3): keep its header so the pass end can floor above it instead.
                        val gapConvId = outgoingConvId(memoText) { null }
                        val header = ownEnvelopeHeader(memos)
                        when {
                            gapConvId != null -> {
                                ownEnvelopeGapConvIds += gapConvId
                                if (header != null) {
                                    unreadOwnEnvelopesByConv.getOrPut(gapConvId) { mutableListOf() } += header
                                } else {
                                    unparsedOwnEnvelopeConvIds += gapConvId
                                }
                            }
                            header != null -> unattributedUnreadOwnEnvelopes += header
                            else -> unattributedOwnEnvelopeGaps++
                        }
                    }
                    diagSkipPeerFail++
                    Log.w("ZCHAT_FLOW", "SKIP outgoing-peer-fail: $messageId memoLen=${memoText.length}")
                    continue
                }
                peerAddress = resolvedPeer

                Log.d("ZCHAT_THREADING", "Storing OUTGOING message: txId=${tx.id.txIdString()}, peerAddress=${peerAddress.redactAddress()}")

                val hasChunkedMemos = memos.any { ZMSGProtocol.isChunkedMemo(it) }

                val rawMessage = if (hasChunkedMemos) {
                    val reassembled = ZMSGProtocol.reassembleChunks(memos, addressCache)
                    reassembled?.message ?: extractMessageContent(memos.joinToString("\n"))
                } else {
                    extractMessageContent(memos.joinToString("\n").trim())
                }

                unknownReason = null
                addressCache.addConversationPartner(peerAddress)

                // CRITICAL: Extract and restore convId mapping from outgoing messages
                // Essential for wallet restore - mappings are rebuilt from blockchain txs.
                @Suppress("NAME_SHADOWING")
                val memoText = memos.joinToString("\n").trim()
                val extractedConvId = outgoingConvId(memoText) { zchatPreferences.getConversationId(peerAddress) }

                // R3-3 (1): our own message under an older conversation id of the peer, kept for the pass end (read
                // from its cached text or not, its header proves which root wrote it).
                if (CiphertextWireFormat.isRatcheted(rawMessage)) {
                    val header = CiphertextWireFormat.parse(rawMessage)
                    val sendConvId = sendConvIdsThisPass.getOrPut(peerAddress) { zchatPreferences.getConversationId(peerAddress).orEmpty() }
                    when {
                        header == null || extractedConvId == null -> ownEnvelopeHeaderUnknownPeers += peerAddress
                        extractedConvId != sendConvId -> {
                            ownEnvelopesUnderOlderConv.getOrPut(extractedConvId) { mutableListOf() } += header
                            peersWithOlderConvEnvelopes += peerAddress
                        }
                    }
                }
                // E2E ratchet decrypt: if the extracted message is E2E1:-prefixed, decrypt it
                rememberDecryptedTextKeys(decryptedTextKeysByMessage, messageId, extractedConvId, rawMessage)
                val decryptedOutgoing =
                    tryDecryptMessage(
                        rawMessage,
                        peerAddress,
                        extractedConvId,
                        onOpened = null,
                        outcomes = decryptOutcomes,
                        rowId = messageId,
                        // ZC-1859 (QA2 pa3): our own failing row carries its height, so a later incoming open answers it
                        // (with none, no open ever did and the paid Re-establish banner re-armed on every pass).
                        minedHeight = height.takeIf { it > 0 },
                        incoming = false,
                        oldRootRow = oldRootRowOf(oldRootPass, messageId, tx, fromContact = false),
                        onNotAttempted = {
                            // KR-3: our own message was not decrypted, so its counter did not raise the floor.
                            ownEnvelopeGapPeers += peerAddress
                            extractedConvId?.let { ownEnvelopeGapConvIds += it }
                            // P2d (3): its header lets the pass end floor above it instead.
                            val header = CiphertextWireFormat.parse(rawMessage)
                            if (header != null) {
                                unreadOwnEnvelopesByPeer.getOrPut(peerAddress) { mutableListOf() } += header
                            } else {
                                unparsedOwnEnvelopePeers += peerAddress
                                extractedConvId?.let { unparsedOwnEnvelopeConvIds += it }
                            }
                        },
                    )
                // Strip our OWN embedded reply-ref (U+0001 RPL:<txid>[U+001F preview] U+0001) so the
                // confirmed outgoing bubble shows clean text and keeps threading after the pending row
                // is gone. The embedded preview is a fallback when the quoted id can't be resolved locally.
                val (outgoingReplyTo, outgoingReplyPreview, decryptedContent) = untagReply(decryptedOutgoing)
                // B17 — our OWN outgoing TTL-control tx must not render a bubble (the local sysnote covers it).
                if (co.electriccoin.zcash.ui.screen.chat.model.ZMSGProtocol.isDisappearSetting(decryptedContent)) continue
                // ZMODE — same: our own outgoing mode-change control tx is covered by the local sysnote.
                if (co.electriccoin.zcash.ui.screen.chat.model.ZMSGProtocol.isModeChange(decryptedContent)) continue
                // ZPROF (avatar) is a NOSTR-only control — it must never render as a raw bubble even if a
                // "ZPROF|…" memo somehow lands on-chain (we never send one there). Drop it like ZMODE.
                if (co.electriccoin.zcash.ui.screen.chat.model.ZPROFMessage.isProfileMessage(decryptedContent)) continue
                // ZC-1474: a free attachment (ZATT) is relay-only; an on-chain one is never shown or fetched.
                if (ZATTMessage.isZatt(decryptedContent)) continue
                // HIGH-007 (MONEY): an OBSERVED outgoing ZREQ_FULFILL spend is the authoritative
                // "request paid" signal. The Keystone fulfill path can't mark at submit time (signing
                // happens later on the TransactionProgress screen), so without this the request's
                // "Pay" stayed live forever → double-pay. The signed spend shows up here as a pending
                // SendTransaction right after submit — mark then. Idempotent set-add (re-scans are
                // no-ops); also heals a Zashi mark lost to process death or seed restore. The
                // paidRequestIds flow is part of the conversations combine, so flipping it re-renders
                // the request bubble with isPaid=true.
                // C3 (B2 review item 8): a write that did not reach the disk is retried on later passes (in memory
                // the request is paid at once either way), and the ids seen here also mark this pass's free (NOSTR)
                // request bubbles paid below (item 7).
                // Round 8 P2 (PHONE_TRIAGE F2): a fulfil that expired unmined (SendTransaction.Failed) paid nothing. It
                // neither marks the request paid nor counts as seen; the fulfil reconcile can then offer Pay again.
                if (decryptedContent.startsWith("ZREQ_FULFILL|")) {
                    if (tx !is co.electriccoin.zcash.ui.common.repository.SendTransaction.Failed) {
                        val fulfilledId = decryptedContent.removePrefix("ZREQ_FULFILL|").trim()
                        if (fulfilledId.isNotEmpty()) {
                            fulfilledSeenThisPass += fulfilledId
                            if (!paidReqIds.contains(fulfilledId) || fulfilledId in unsavedPaidMarks) {
                                if (zchatPreferences.markRequestPaid(fulfilledId)) {
                                    unsavedPaidMarks.remove(fulfilledId)
                                } else {
                                    unsavedPaidMarks.add(fulfilledId)
                                    Log.w("ZCHAT_PAY", "scan-back paid marker not saved — a later pass writes it again")
                                }
                                paidRequestIds.update { it + fulfilledId }
                            }
                        }
                    }
                    // R8-fixup F7 (REVIEW_R8 F7): our payment of a request is shown by the request bubble ("Paid"), never
                    // as a text bubble holding the raw "ZREQ_FULFILL|<id>" memo.
                    diagSkipUnlock++
                    continue
                }
                if (outgoingReplyTo != null) incomingReplyToId = outgoingReplyTo
                if (outgoingReplyPreview != null) incomingReplyPreview = outgoingReplyPreview

                // ZFILE detection: if content is a file message, show metadata instead of raw ZFILE| string
                displayMessage = if (co.electriccoin.zcash.ui.screen.chat.model.ZFILEMessage.isFileMessage(decryptedContent)) {
                    val fileMsg = co.electriccoin.zcash.ui.screen.chat.model.ZFILEMessage.parse(decryptedContent)
                    if (fileMsg != null) {
                        outgoingFileHash = fileMsg.hash
                        capturedZfileContent = decryptedContent
                        capturedBlurhash = fileMsg.blurhash.takeIf { it.isNotEmpty() }
                        capturedFileType = fileMsg.type
                        capturedViewOnce = fileMsg.viewOnce
                        "\uD83D\uDCCE ${fileMsg.displayText}"
                    } else {
                        decryptedContent
                    }
                } else if (co.electriccoin.zcash.ui.screen.chat.model.ZBootMessage.isBootMessage(decryptedContent)) {
                    recordOwnMinedZbootInPass(zbootPass, decryptedContent, peerAddress, mined = tx.overview.minedHeight != null)
                    // Our own outbound NOSTR handshake \u2014 show a note, not the raw "ZBOOT|v1|\u2026" memo.
                    "\uD83D\uDD10 Secure connection request sent"
                } else {
                    decryptedContent
                }
                if (extractedConvId != null) {
                    val existingPeer = zchatPreferences.getPeerByConversationId(extractedConvId)
                    if (existingPeer == null) {
                        Log.d("ZCHAT_RESTORE", "Restoring convId mapping from outgoing: ${extractedConvId.redactConvId()} -> ${peerAddress.redactAddress()}")
                        // FC-ID (5.3a item 2): met first in this wallet's own send, so the id is this phone's own. ZC-1082:
                        // not for a receiver form no single known address holds (nothing may vouch for a key there).
                        if (resolveOwnSendText(peerAddress).let { it.vouched && it.address == peerAddress }) {
                            // ZC-757 (k) round 15 (ZC-1167): as the key exchange branch decides it, a send that paid only a
                            // receiver form inside the address files the id there with the nosendid marker (never its
                            // send id). Round 15b (W-95): the id becomes the address's send id only when the outputs prove
                            // the paid text is that address; unreadable outputs (a pending send matched by content) or a
                            // read naming another address file it with the marker (a restored chat may get a fresh id).
                            val asSendId =
                                outgoingRecipientFromOutputs(tx)
                                    ?.let { it.address == peerAddress && it.asSent == it.address }
                                    ?: false
                            zchatPreferences.restoreOwnConversationId(extractedConvId, peerAddress, asSendId = asSendId)
                        }
                    } else if (existingPeer != peerAddress) {
                        Log.w("ZCHAT_RESTORE", "ConvId ${extractedConvId.redactConvId()} already mapped to ${existingPeer.redactAddress()}, not overwriting with ${peerAddress.redactAddress()}")
                    }
                }
            } else {
                // R8-fixup F7 (REVIEW_R8 F7): a contact's payment of one of our requests is the bare "ZREQ_FULFILL|<id>" memo
                // (no envelope, no sender). It is never shown as a text bubble; a MINED one is matched to our own request
                // <id> after the loop (markOwnRequestsPaid), which then shows Paid if the payment carried at least the amount.
                if (memoText.startsWith(FULFIL_MEMO_PREFIX)) {
                    val requestId = memoText.removePrefix(FULFIL_MEMO_PREFIX).trim()
                    if (requestId.isNotEmpty() && tx.overview.minedHeight != null) {
                        incomingFulfils.merge(requestId, tx.amount.value, ::maxOf)
                    }
                    diagSkipUnlock++
                    continue
                }
                // For incoming, check if chunked or single memo
                val hasChunkedMemos = memos.any { ZMSGProtocol.isChunkedMemo(it) }

                val parsed = if (hasChunkedMemos) {
                    ZMSGProtocol.reassembleChunks(memos, addressCache)
                } else {
                    @Suppress("NAME_SHADOWING")
                    val memoText = memos.joinToString("\n").trim()
                    if (memoText.isNotBlank()) {
                        ZMSGProtocol.parseMemo(memoText, addressCache)
                    } else {
                        null
                    }
                }

                if (parsed == null) {
                    diagSkipParseFail++
                    // Privacy: never log memo content (HIGH-001b) — length only.
                    Log.d("ZCHAT_FLOW", "SKIP incoming-parse-null: $messageId chunked=$hasChunkedMemos memoLen=${memoText.length}")
                    continue
                }

                // === SIMPLIFIED 3-TIER ROUTING ===
                // Tier 1: ConvID lookup (HIGH confidence)
                // Tier 2: Direct address match (MEDIUM confidence)
                // Tier 3: New conversation (SAFE fallback)
                val resolvedPeerAddress = run {
                    // parseMemo returns no sender for a ZTL| (time-locked) or ZREQ| (payment request) memo: their
                    // only sender identity is the hash inside them. Fall back to it (and to the address the hash
                    // cache knows for it) so the message routes to the contact it names instead of a dead
                    // "unknown" chat. (#bug-timelock-reply; Round 8 P3, PHONE_TRIAGE F1 for ZREQ)
                    val (specialSenderAddr, specialSenderHash) = specialMemoSender(memoText)
                    val senderAddr = parsed.senderAddress ?: specialSenderAddr ?: "unknown"
                    val senderHash = parsed.senderHash ?: specialSenderHash
                    val convId = parsed.conversationId

                    Log.d("ZCHAT_V4", "=== Routing incoming message ===")
                    Log.d("ZCHAT_V4", "Sender hash: ${senderHash?.redactAddress()}, convId: ${convId?.redactConvId()}, msgLen: ${parsed.message.length}")

                    // ── TIER 1: ConvID lookup (highest confidence) ──
                    if (convId != null) {
                        // 1a: Direct convId → peer lookup
                        val peerFromConvId = zchatPreferences.getPeerByConversationId(convId)
                        if (peerFromConvId != null) {
                            // convID is a RANDOM 8-char id (~41 bits), so two peers can collide on
                            // one id. Trust the convID→peer mapping ONLY when the message's sender
                            // hash actually matches that peer; otherwise this is a collision and
                            // returning peerFromConvId would misroute the message into the wrong
                            // thread AND poison the hash cache. On mismatch, fall through to TIER2.
                            val hashMatches = senderHash == null ||
                                ZMSGProtocol.generateAddressHash(peerFromConvId) == senderHash ||
                                ZMSGProtocol.generateLegacyAddressHash(peerFromConvId) == senderHash
                            if (hashMatches) {
                                Log.d("ZCHAT_V4", "TIER1: Matched via convID -> ${peerFromConvId.redactAddress()}")
                                // Always cache sender hash → resolved peer for future lookups.
                                // Use validated caching since convID is a high-confidence source.
                                if (senderHash != null) {
                                    addressCache.cacheAddressValidated(senderHash, peerFromConvId)
                                    addressCache.addConversationPartner(peerFromConvId)
                                }
                                return@run peerFromConvId
                            }
                            Log.w("ZCHAT_V4", "TIER1 COLLISION: convID=${convId.redactConvId()} maps to ${peerFromConvId.redactAddress()} but senderHash=${senderHash.redactAddress()} mismatches; falling through to TIER2")
                        }

                        // 1b: Reverse lookup - check if any existing peer has this convId
                        val existingPeerForConvId = messagesByPeer.keys.find { peerAddr ->
                            zchatPreferences.getConversationId(peerAddr) == convId
                        }
                        if (existingPeerForConvId != null) {
                            Log.d("ZCHAT_V4", "TIER1: Matched via reverse peer->convId lookup -> ${existingPeerForConvId.redactAddress()}")
                            zchatPreferences.setConversationMapping(convId, existingPeerForConvId)
                            if (senderHash != null) {
                                addressCache.cacheAddressValidated(senderHash, existingPeerForConvId)
                            }
                            return@run existingPeerForConvId
                        }

                        // 1c: ConvId not found but we have sender address — new INIT from someone
                        if (senderAddr != "unknown") {
                            Log.d("ZCHAT_V4", "TIER1: New convID from ${senderAddr.redactAddress()} - storing mapping")
                            zchatPreferences.setConversationMapping(convId, senderAddr)
                            if (senderHash != null) {
                                addressCache.cacheAddressValidated(senderHash, senderAddr)
                            }
                            return@run senderAddr
                        }

                        // 1d: ConvId not found, no sender addr, try hash cache
                        if (senderHash != null) {
                            val cachedAddr = addressCache.getAddress(senderHash)
                            if (cachedAddr != null) {
                                Log.d("ZCHAT_V4", "TIER1: Matched via hash cache -> ${cachedAddr.redactAddress()}")
                                zchatPreferences.setConversationMapping(convId, cachedAddr)
                                return@run cachedAddr
                            }
                        }
                    }

                    // ── TIER 2: Direct address match (medium confidence) ──
                    if (senderAddr != "unknown") {
                        // 2a: Exact key match in existing conversations
                        if (messagesByPeer.containsKey(senderAddr)) {
                            Log.d("ZCHAT_V4", "TIER2: Matched via direct peer address -> ${senderAddr.redactAddress()}")
                            if (convId != null) {
                                zchatPreferences.setConversationMapping(convId, senderAddr)
                            }
                            return@run senderAddr
                        }

                        // 2b: Contact book match
                        if (contactBook.hasContact(senderAddr)) {
                            Log.d("ZCHAT_V4", "TIER2: Matched via contact book -> ${senderAddr.redactAddress()}")
                            if (convId != null) {
                                zchatPreferences.setConversationMapping(convId, senderAddr)
                            }
                            return@run senderAddr
                        }

                        // 2c: Hash match against existing conversations
                        val senderHashForMatch = senderHash ?: ZMSGProtocol.generateAddressHash(senderAddr)
                        val hashMatchConv = messagesByPeer.keys.find { existingPeerAddr ->
                            val existingHash = ZMSGProtocol.generateAddressHash(existingPeerAddr)
                            existingHash == senderHashForMatch
                        }
                        if (hashMatchConv != null) {
                            Log.d("ZCHAT_V4", "TIER2: Matched via hash comparison -> ${hashMatchConv.redactAddress()}")
                            addressCache.cacheAddress(senderHashForMatch, hashMatchConv)
                            // #bug-timelock-reply — register the peer as a conversation partner on this
                            // INBOUND hash resolution too (previously only outgoing sends did). Without it, a
                            // receive-only thread whose address-cache later gets cleared (reinstall/restore)
                            // could no longer hash-resolve an incoming time-lock → it stranded in a fresh
                            // "unknown <hash>" chat with replies blocked.
                            addressCache.addConversationPartner(hashMatchConv)
                            if (convId != null) {
                                zchatPreferences.setConversationMapping(convId, hashMatchConv)
                            }
                            return@run hashMatchConv
                        }
                    }

                    // ── TIER 2h (Round 8 P3): a sender hash and no address ──
                    // The hash names exactly one known contact (this pass's chats, the contact book, and since ZC-1480
                    // the stored chats and the contacts with a bound relay key): route there.
                    // The hash is SHA-256 of that very address, so caching it is safe; the message itself stays
                    // "not verified" (a plaintext memo anyone can send) and Pay pays the chat's own peer. With no
                    // match, or two or more, never guess: fall through to TIER 3. No convId mapping is written here.
                    if (senderAddr == "unknown" && senderHash != null) {
                        val candidates =
                            (messagesByPeer.keys + knownContactAddresses + relayAndChatPeers).filter(::isResolvedToKnownPeer)
                        val hashOnlyMatch = SenderHashMatch.unique(senderHash, candidates)
                        if (hashOnlyMatch != null) {
                            Log.d("ZCHAT_V4", "TIER2h: Matched a sender hash to one known contact -> ${hashOnlyMatch.redactAddress()}")
                            addressCache.cacheAddress(senderHash, hashOnlyMatch)
                            addressCache.addConversationPartner(hashOnlyMatch)
                            return@run hashOnlyMatch
                        }
                    }

                    // ── TIER 3: New conversation (safe fallback) ──
                    if (senderAddr != "unknown") {
                        Log.d("ZCHAT_V4", "TIER3: New conversation with sender -> ${senderAddr.redactAddress()}")
                        val hashToCache = senderHash ?: ZMSGProtocol.generateAddressHash(senderAddr)
                        addressCache.cacheAddress(hashToCache, senderAddr)
                        if (convId != null) {
                            zchatPreferences.setConversationMapping(convId, senderAddr)
                        }
                        senderAddr
                    } else if (senderHash != null) {
                        // Last resort: check partner match by hash
                        val partnerMatch = addressCache.findConversationPartnerByHash(senderHash)
                        if (partnerMatch != null) {
                            Log.d("ZCHAT_V4", "TIER3: Matched via conversation partner -> ${partnerMatch.redactAddress()}")
                            addressCache.cacheAddress(senderHash, partnerMatch)
                            if (convId != null) {
                                zchatPreferences.setConversationMapping(convId, partnerMatch)
                            }
                            return@run partnerMatch
                        }
                        Log.w("ZCHAT_V4", "TIER3: Unknown sender, using hash as key: ${senderHash.redactAddress()}")
                        senderHash
                    } else if (convId != null) {
                        // No sender address or hash, but we have a convId.
                        // Use convId as conversation key to preserve grouping.
                        // When a future message with same convId arrives with sender info,
                        // Tier 1c will create the proper mapping.
                        Log.w("ZCHAT_V4", "TIER3: No sender info but has convId=${convId.redactConvId()}, using as conversation key")
                        convId
                    } else {
                        Log.w("ZCHAT_V4", "TIER3: No sender info at all, using 'unknown'")
                        "unknown"
                    }
                }

                Log.d("ZCHAT_THREADING", "=== Final resolved peer: ${resolvedPeerAddress.redactAddress()} ===")
                peerAddress = resolvedPeerAddress

                // E2E decrypt + ZFILE detection for incoming messages
                val incomingConvId = parsed.conversationId
                // D9: classify authenticity on the RAW memo body (parsed.message) BEFORE decryption/
                // plaintext passthrough — a plaintext body anyone can pay to send is NOT authenticated.
                messageAuthenticated = co.electriccoin.zcash.ui.screen.chat.model.MessageAuthentication
                    .isBodyAuthenticated(isOutgoing = false, rawMemoBody = parsed.message)
                rememberDecryptedTextKeys(decryptedTextKeysByMessage, messageId, incomingConvId, parsed.message)
                var ratchetOpened = false
                val oldRootRow = oldRootRowOf(oldRootPass, messageId, tx, fromContact = true)
                val decryptedContent =
                    tryDecryptMessage(
                        parsed.message,
                        resolvedPeerAddress,
                        incomingConvId,
                        onNotAttempted = null,
                        onOpened = { ratchetOpened = true },
                        outcomes = decryptOutcomes,
                        rowId = messageId,
                        minedHeight = height.takeIf { it > 0 },
                        oldRootRow = oldRootRow,
                    )
                // W-72 (SPEC_F R5, R6): only a mined memo the ratchet opened with the stored key, an ordinary message.
                if (ratchetOpened &&
                    incomingConvId != null &&
                    height > 0 &&
                    parsed.messageType == co.electriccoin.zcash.ui.screen.chat.model.MessageType.REGULAR &&
                    CiphertextWireFormat.isRatcheted(parsed.message)
                ) {
                    noteLegacyKeyEvidence(
                        resolvedPeerAddress,
                        incomingConvId,
                        isInit = parsed.senderAddress != null,
                        minedHeight = height,
                    ) { id ->
                        transactions
                            .firstOrNull { it is co.electriccoin.zcash.ui.common.repository.SendTransaction && it.id.txIdString() == id }
                            ?.overview
                            ?.minedHeight
                            ?.value
                    }
                }
                // Strip the embedded reply-ref (U+0001 RPL:<txid> U+0001) the sender wrapped inside
                // the body so replies thread on the receiver. Fall back to the v3 RPL envelope txid
                // for legacy on-chain replies. Both feed ChatMessage.replyToId below.
                val (embeddedReplyTo, embeddedReplyPreview, incomingContent) = untagReply(decryptedContent)
                // B17 — disappearing-messages TTL control over VAULT. #187 CORE RULE: trusted ONLY when the
                // RAW memo was an E2E1 ratchet blob (parsed.message) whose AEAD decrypt succeeded AND the
                // sender resolves to a known peer — a bare plaintext ZEXP memo anyone can pay to send is
                // ALWAYS ignored (TTL mutates retention, so we do NOT follow the plaintext-ZREACT precedent).
                if (co.electriccoin.zcash.ui.screen.chat.model.ZMSGProtocol.isDisappearSetting(incomingContent)) {
                    // R2-5 (c) / M-CHT-02: and never while the contact's key change is unaccepted, as on NOSTR.
                    // ZC-1792 (W-142): never from a row an earlier root opened (display only).
                    if (co.electriccoin.zcash.ui.screen.chat.crypto.ratchet.CiphertextWireFormat.isRatcheted(parsed.message) &&
                        isResolvedToKnownPeer(resolvedPeerAddress) &&
                        oldRootRow?.opened != true &&
                        !zchatPreferences.isE2EKeyChanged(resolvedPeerAddress)
                    ) {
                        handleDisappearControl(resolvedPeerAddress, incomingContent)
                    } else {
                        Log.w("ZCHAT_TTL", "IGNORED unauthenticated/unattributed plaintext ZEXP memo (#187)")
                    }
                    continue
                }
                // Conversation-mode change control over VAULT (ZMODE) — same #187 CORE RULE as the ZEXP
                // gate above: trusted ONLY when the RAW memo was an E2E1 ratchet blob whose AEAD decrypt
                // succeeded AND the sender resolves to a known peer; a bare plaintext ZMODE memo anyone
                // can pay to send is ALWAYS ignored (the mode mutates transport routing + billing).
                if (co.electriccoin.zcash.ui.screen.chat.model.ZMSGProtocol.isModeChange(incomingContent)) {
                    // Round 8 D5 (sweep #15 / M-CHT-02): and never while the contact's key change is unaccepted, as on
                    // NOSTR and for the on-chain timer control.
                    if (co.electriccoin.zcash.ui.screen.chat.crypto.ratchet.CiphertextWireFormat.isRatcheted(parsed.message) &&
                        isResolvedToKnownPeer(resolvedPeerAddress) &&
                        oldRootRow?.opened != true &&
                        !zchatPreferences.isE2EKeyChanged(resolvedPeerAddress)
                    ) {
                        handleModeControl(resolvedPeerAddress, incomingContent)
                    } else {
                        Log.w("ZCHAT_MODE", "IGNORED unauthenticated/unattributed plaintext ZMODE memo (#187)")
                    }
                    continue
                }
                // ZPROF (avatar) is a NOSTR-only control — never render an on-chain "ZPROF|…" memo as a
                // bubble (we never send avatars on-chain; this only sheds a crafted/echoed one). Dropped, not
                // adopted: the on-chain path deliberately does NOT save avatars (they travel free NOSTR only).
                if (co.electriccoin.zcash.ui.screen.chat.model.ZPROFMessage.isProfileMessage(incomingContent)) continue
                // ZC-1474: a free attachment (ZATT) is accepted only from the bound relay key (observeNostrInbound). One in an
                // on-chain memo is authenticated by nothing (anyone who knows the address can send it): no bubble, no fetch.
                if (ZATTMessage.isZatt(incomingContent)) continue
                incomingReplyToId = embeddedReplyTo ?: parsed.replyToTxId
                if (embeddedReplyPreview != null) incomingReplyPreview = embeddedReplyPreview
                displayMessage = if (co.electriccoin.zcash.ui.screen.chat.model.ZFILEMessage.isFileMessage(incomingContent)) {
                    val fileMsg = co.electriccoin.zcash.ui.screen.chat.model.ZFILEMessage.parse(incomingContent)
                    if (fileMsg != null) {
                        incomingFileHash = fileMsg.hash
                        capturedZfileContent = incomingContent
                        capturedBlurhash = fileMsg.blurhash.takeIf { it.isNotEmpty() }
                        capturedFileType = fileMsg.type
                        capturedViewOnce = fileMsg.viewOnce
                        "\uD83D\uDCCE ${fileMsg.displayText}"
                    } else {
                        incomingContent
                    }
                } else if (co.electriccoin.zcash.ui.screen.chat.model.ZBootMessage.isBootMessage(incomingContent)) {
                    // Peer's NOSTR handshake (shielded ZBOOT): stash their pubkey + relay so NOSTR
                    // DMs and voice/video calls to them work. Only treat it as a handshake (and show
                    // the system note) if it actually PARSES \u2014 a plain message that merely starts with
                    // "ZBOOT|" must not be swallowed + replaced with a forged "Secure connection
                    // established" note. routeIncomingBoot still re-verifies the signature internally.
                    if (co.electriccoin.zcash.ui.screen.chat.model.ZBootMessage.parse(incomingContent) != null) {
                        // A shielded receive hides the Zcash sender, so an on-chain ZBOOT carries only a
                        // convId. When getPeerByConversationId(convId) is unmapped (catch-up-sync race OR an
                        // established-pair convId drift) the 3-tier router keyed this row on the RAW convId \u2014
                        // an invalid "address" that trips ChatDetailView's isValidAddress \u2192 the misleading
                        // "Unknown sender / you cannot reply" banner, a default-VAULT mode read, and no
                        // TUNNEL upgrade (so Honor's later free-NOSTR DM is dropped as unknown-pubkey).
                        //
                        // Give the on-chain ZBOOT the SAME signature-attribution the NOSTR path uses:
                        // attributeBoot verifies the ZBOOT against each established peer's stored E2E key and
                        // RETURNS the real peer it belongs to. routeIncomingBoot stays the SOLE trust gate
                        // (no relaxed check, no new bind site); a non-matching peer is side-effect-free.
                        val bootPeer = attributeBoot(incomingContent)
                        if (bootPeer != null) {
                            // Re-key the row onto the resolved real peer: it joins the actual conversation
                            // (valid u1/zs address \u2192 isValidAddress \u2192 NO banner, reply ENABLED), and
                            // routeIncomingBoot's success path already upgraded us to TUNNEL (mode
                            // convergence) + stored the peer's NOSTR pubkey (so the queued content DM is
                            // accepted). MONEY-SAFE: attribution only verified + stored a NOSTR pubkey; no
                            // spend was triggered.
                            peerAddress = bootPeer
                            "\uD83D\uDD10 Secure connection established \u2014 voice/video calls enabled"
                        } else {
                            // Genuinely unattributable (E2E key truly lost or the KEX hasn't landed yet): do
                            // NOT render a convId-keyed phantom chat with the misleading "Unknown sender"
                            // banner \u2014 a handshake memo is not user content. Drop it (blank \u2192 skipped below).
                            // A later scan re-attributes it once the KEX lands and the peer's E2E key is
                            // stored (routeIncomingBoot only dedups a ZBOOT it actually VERIFIED, so this
                            // stays retriable across re-scans).
                            Log.d("ZCHAT_NOSTR", "On-chain ZBOOT unattributable this scan (convId ${resolvedPeerAddress.take(12)}\u2026) \u2014 dropping render, will retry")
                            ""
                        }
                    } else {
                        incomingContent
                    }
                } else {
                    incomingContent
                }
                // Decide whether to surface the "Unknown sender" banner.
                //
                // parsed.reason reflects ONLY what the protocol parser could determine in isolation
                // (e.g. HASH_NOT_IN_CACHE after a cold restart, or VERSION_MISMATCH on a legacy
                // prefix). Routing above may have since resolved the message to a real, already-known
                // peer via the EXISTING authenticated conversation mapping (convId -> peer) or via a
                // direct/contact/hash match. In that case the sender IS recognized and the banner must
                // NOT show — clearing the reason here is what suppresses it (the view gates the banner
                // on whether peerAddress is a real Zcash address).
                //
                // SECURITY: we clear the reason ONLY when routing produced a real Zcash address
                // (u1.../zs...). If routing fell back to a hash, a raw convId, or "unknown" (i.e. the
                // convId did NOT map to an established peer, or there was no recognized ZCHAT prefix),
                // resolvedPeerAddress is NOT a real address, so we keep parsed.reason and the banner
                // still shows. A bare convId string in plaintext can never suppress the banner on its
                // own — it must resolve to an authenticated peer.
                //
                // Key off `peerAddress` (NOT resolvedPeerAddress): an on-chain ZBOOT above may have re-keyed
                // this row onto the real peer attributeBoot() resolved (a valid u1/zs address), so the banner
                // must clear for that authenticated peer too. For every other incoming message
                // peerAddress == resolvedPeerAddress, so this is unchanged there.
                unknownReason = if (isResolvedToKnownPeer(peerAddress)) null else parsed.reason
            }

            // ZC-1279: a transaction has one row, whose id is its txid: an earlier unit (a ZBOOT's note) leaves it to the last.
            if (memoReads.firstOrNull()?.first === tx) continue

            if (displayMessage.isBlank()) {
                diagSkipBlank++
                // Privacy: never log memo content (HIGH-001b) — length only.
                Log.w("ZCHAT_FLOW", "SKIP blank-message: $messageId type=$txType memoLen=${memoText.length} " +
                    "peer=${peerAddress.take(15)}... " +
                    "unknownReason=$unknownReason")
                continue
            }

            // For time-locked messages, use the parsed message content
            val finalMessage = if (timeLockInfo != null && ZMSGProtocol.isTimeLock(memoText)) {
                val parsedTimeLock = ZMSGProtocol.parseTimeLock(memoText, addressCache)
                parsedTimeLock?.message ?: displayMessage
            } else {
                displayMessage
            }

            // For payment requests, use the reason as display text
            val messageText = if (paymentRequestInfo != null) {
                paymentRequestInfo.reason.ifEmpty { "Payment request" }
            } else {
                finalMessage
            }

            val message = ChatMessage(
                id = messageId,
                txId = tx.id,
                text = messageText,
                // A pending tx has no block time yet. Anchor to the FIRST time we observed this txid,
                // PERSISTED (B3) so it survives VM recreation on chat re-entry AND process death — a
                // per-instance map re-anchored to now() every time the user left+reopened the chat, which
                // reset the outgoing ~75s send countdown and kept incoming messages perpetually newer than
                // the last-read marker (unread badge never cleared). Mined txs use their real block time
                // and evict the anchor.
                timestamp = tx.timestamp?.also { zchatPreferences.clearPendingTxFirstSeen(tx.id.txIdString()) }
                    ?: Instant.ofEpochMilli(
                        zchatPreferences.getOrPutPendingTxFirstSeenMillis(tx.id.txIdString(), System.currentTimeMillis())
                    ),
                isOutgoing = isOutgoing,
                peerAddress = peerAddress,
                isPending = tx is co.electriccoin.zcash.ui.common.repository.SendTransaction.Pending ||
                           tx is co.electriccoin.zcash.ui.common.repository.ReceiveTransaction.Pending,
                unknownReason = unknownReason,
                minedHeight = tx.overview.minedHeight?.value,
                txIndex = tx.overview.index?.toInt(),
                timeLock = timeLockInfo,
                paymentRequest = paymentRequestInfo,
                fileHash = outgoingFileHash ?: incomingFileHash,
                fileZfileContent = capturedZfileContent,
                fileBlurhash = capturedBlurhash,
                fileType = capturedFileType,
                fileViewOnce = capturedViewOnce,
                fileViewed = capturedViewOnce && (
                    (outgoingFileHash ?: incomingFileHash)?.let { zchatPreferences.isFileViewed(it) } == true
                ),
                replyToId = incomingReplyToId,
                replyToPreview = incomingReplyToId?.let { rid ->
                    // Use displayText (not raw text) so a quoted time-locked / payment-locked message
                    // shows "🔒 Locked message" instead of leaking its plaintext into the reply preview.
                    messagesByPeer[peerAddress]?.firstOrNull { it.id == rid }?.displayText?.take(50)
                } ?: incomingReplyPreview,
                // D9: true for outgoing (the branch above never downgrades it); for incoming, false
                // when the raw memo body was plaintext rather than a ratcheted E2E1 blob.
                authenticated = messageAuthenticated,
                paymentAmountZatoshi = paymentRowAmount(tx, isOutgoing, messageText),
            )

            messagesByPeer.getOrPut(peerAddress) { mutableListOf() }.add(message)
            confirmedIds.add(messageId)
            if (isOutgoing &&
                tx is co.electriccoin.zcash.ui.common.repository.SendTransaction.Failed &&
                tx.overview.minedHeight == null
            ) {
                expiredUnminedOwnTxIds.add(messageId)
            }
            diagAdded++
            // QA oracle (debug-only, no-op in release): per-message accept event for the on-device
            // runner. Redacted/hashed fields only — never plaintext (see InboundDiag).
            InboundDiag.logMessageAdded(message, InboundDiag.TRANSPORT_CHAIN)
            // ZC-1366: the contact wrote (a message the user has not deleted): the ZC-1352 withdrawn mark lifts.
            // ZC-1393: only an authenticated one (ratcheted under the chat's key). A plaintext memo can name any address.
            if (!isOutgoing &&
                messageId !in hiddenMsgIds &&
                !message.isSystemNote &&
                message.authenticated
            ) {
                userStartsSetupAgain(peerAddress)
            }
        }

        // ZC-1608: one write per peer and kind for the own scalars this pass decided: the newest own non-expired key exchange,
        // else drop a stored one the wallet lists as expired and never mined (ZC-1583), else leave it. ZC-1605: a write that
        // changes the stored value drops the cached processors at once, so neither a send later in this pass nor a pass cut
        // off before the end compare keeps the processor of the old root.
        for (peer in ownScalarsBefore.keys) {
            val storedKex = zchatPreferences.getE2EKexTxId(peer)
            val newestKex = ownKexScalarNewest[peer]
            if (newestKex != null) {
                zchatPreferences.setE2EKexTxId(peer, newestKex)
                if (storedKex != newestKex) invalidateMessageProcessors(peer)
            } else if (storedKex != null && storedKex in ownKexExpiredUnmined[peer].orEmpty()) {
                zchatPreferences.removeE2EKexTxId(peer)
                invalidateMessageProcessors(peer)
            }
            val storedAck = zchatPreferences.getE2EKexAckTxId(peer)
            val newestAck = ownKexAckScalarNewest[peer]
            if (newestAck != null) {
                zchatPreferences.setE2EKexAckTxId(peer, newestAck)
                if (storedAck != newestAck) invalidateMessageProcessors(peer)
            } else if (storedAck != null && storedAck in ownKexAckExpiredUnmined[peer].orEmpty()) {
                zchatPreferences.removeE2EKexAckTxId(peer)
                invalidateMessageProcessors(peer)
            }
        }

        // Round 8 P2 (PHONE_TRIAGE F2): withdraw a paid marker whose payment provably never reached the chain.
        val withdrawnFulfils =
            reconcileStartedFulfils(
                passComplete = historyScanComplete && passStable && memoReadFailures == 0,
                userAddress = userAddress,
                sightings = ownFulfils,
                messagesByPeer = messagesByPeer,
                pendingMsgs = pendingMsgs,
            )

        // F5 (fix-all 2.13.0, train T5): the paid requests whose payment is not mined yet say "Payment pending".
        val fulfilPending = fulfilPendingThisPass(historyScanComplete && passStable && memoReadFailures == 0, ownFulfils)

        // F4 (fix-all 2.13.0, train T4): settle the send attempts of the outgoing on-chain rows from the chain.
        val attemptRows = reconcileSendAttempts(historyScanComplete, messagesByPeer, pendingMsgs)
        // F8 (ZC-112): then the attempts that have no row (the handshakes, a Join reply, a key grant, the timer, a locked message).
        reconcileSendAttemptLedger(historyScanComplete, messagesByPeer, zbootPass)

        // ZC-310 (KI-127): an own send that expired unmined never reached the chain, so it has no chain row; without
        // this it rendered as CONFIRMED ("On the blockchain") beside, or instead of, its true pending row. Removed
        // only here: after the F4 reconcile read the rows (its inputs are unchanged) and before the pending merge
        // (F4 review point 5 hides a pending row behind its unmined chain copy; an expired copy no longer counts), so
        // the pending row shows with its F4 verdict and deleting it leaves nothing. Nothing is stored: a transaction
        // mined after all is listed as mined on that pass and shows again.
        if (expiredUnminedOwnTxIds.isNotEmpty()) {
            messagesByPeer.values.forEach { rows ->
                rows.removeAll { it.isOutgoing && it.txId?.txIdString() in expiredUnminedOwnTxIds }
            }
            confirmedIds.removeAll(expiredUnminedOwnTxIds)
            Log.i("ZCHAT_DIAG", "Expired unmined own sends not shown: ${expiredUnminedOwnTxIds.size}")
        }

        // === DIAGNOSTIC SUMMARY ===
        val diagSkipped = diagTotal - diagAdded
        Log.i("ZCHAT_DIAG", "=== convertToConversations SUMMARY ===")
        Log.i("ZCHAT_DIAG", "Total txs: $diagTotal (out=$diagOutgoing, in=$diagIncoming)")
        Log.i("ZCHAT_DIAG", "Added to chat: $diagAdded, Skipped: $diagSkipped")
        Log.i("ZCHAT_DIAG", "Skip reasons: hidden=$diagSkipHidden noMemo=$diagSkipNoMemo status=$diagSkipStatus " +
            "reaction=$diagSkipReaction KEX=$diagSkipKEX group=$diagSkipGroup unlock=$diagSkipUnlock " +
            "parseFail=$diagSkipParseFail peerFail=$diagSkipPeerFail blank=$diagSkipBlank")
        Log.i("ZCHAT_DIAG", "Conversations: ${messagesByPeer.size}, Pending msgs: ${pendingMsgs.size}")
        messagesByPeer.forEach { (peer, msgs) ->
            Log.d("ZCHAT_DIAG", "  Conv ${peer.redactAddress()}: ${msgs.size} msgs (out=${msgs.count { it.isOutgoing }}, in=${msgs.count { !it.isOutgoing }})")
        }

        // Track confirmed outgoing messages for deduplication with pending messages.
        // Key: peer address + full content hash, Value: list of confirmed messages.
        // Include unmined txs (txId != null) to suppress temporary duplicate rows.
        val confirmedOutgoingByContent = mutableMapOf<String, MutableList<ChatMessage>>()
        messagesByPeer.forEach { (peer, msgs) ->
            msgs.filter { it.isOutgoing && it.txId != null }.forEach { msg ->
                // Use SHA-256 hash of FULL content to avoid truncation collisions
                val contentHash = msg.text.toByteArray().let { bytes ->
                    java.security.MessageDigest.getInstance("SHA-256")
                        .digest(bytes)
                        .take(16)
                        .joinToString("") { "%02x".format(it) }
                }
                val contentKey = "$peer|$contentHash"
                confirmedOutgoingByContent.getOrPut(contentKey) { mutableListOf() }.add(msg)
            }
        }

        // Add pending messages that haven't been confirmed yet
        // Use content-based matching for deduplication
        val pendingToRemove = mutableListOf<String>()
        var pendingSuppressedByUnmined = 0
        // P2a — older-build rows have no transaction IDs; they are matched after every exact-ID row has claimed its
        // own transaction, oldest row first, so a transaction that belongs to a tracked row is never used for them.
        val legacyRows = mutableListOf<Pair<ChatMessage, String>>()
        // F4 (review point 6): our own chain rows by transaction id, so a row whose own transaction is shown retires
        // whatever the text it renders (a memo read later, or rendered differently, never leaves it beside its copy).
        val ownChainRowsByTxId = HashMap<String, ChatMessage>()
        messagesByPeer.values.forEach { rows ->
            rows.forEach { m -> if (m.isOutgoing) m.txId?.let { ownChainRowsByTxId[it.txIdString()] = m } }
        }
        for (listedMsg in pendingMsgs) {
            // F4: the row as this pass's send-attempt reconcile shows it (its verdict, or its proven-not-sent form).
            val pendingMsg = attemptRows[listedMsg.id] ?: listedMsg
            // A locally-deleted pending message (NOSTR in/out, local call-log) must not reappear.
            // On-chain deletes are filtered in the tx loop above via hiddenMsgIds; pending messages
            // never reach that loop, so without this check Delete was a silent no-op for anything
            // sent/received over NOSTR. Purge from the pending store too so the delete is permanent
            // instead of being re-filtered on every reload.
            if (pendingMsg.id in hiddenMsgIds) {
                pendingToRemove.add(pendingMsg.id)
                continue
            }
            // Use same hash algorithm for pending messages
            val contentHash = pendingMsg.text.toByteArray().let { bytes ->
                java.security.MessageDigest.getInstance("SHA-256")
                    .digest(bytes)
                    .take(16)
                    .joinToString("") { "%02x".format(it) }
            }
            val contentKey = "${pendingMsg.peerAddress}|$contentHash"
            if (pendingMsg.legacyUntrackedSubmit && pendingMsg.submittedTxIds.isEmpty()) {
                legacyRows += pendingMsg to contentKey
                continue
            }
            val matchingConfirmed = confirmedOutgoingByContent[contentKey]

            // Repeated plaintext is not the identity of a paid attempt. Until the SDK returns an
            // exact transaction ID, keep its durable payload and uncertainty marker, even if older
            // history has identical text. This also protects queued sends before their first submit.
            val matchingIndex =
                matchingConfirmed?.indexOfFirst { confirmed ->
                    !pendingMsg.id.startsWith(ON_CHAIN_PENDING_PREFIX) || confirmed.txId?.txIdString() in pendingMsg.submittedTxIds
                } ?: -1
            val matched =
                if (matchingConfirmed != null && matchingIndex >= 0) {
                    matchingConfirmed.removeAt(matchingIndex)
                } else {
                    pendingMsg.submittedTxIds.firstNotNullOfOrNull { ownChainRowsByTxId[it] }
                }
            if (matched != null) {
                if (matched.minedHeight != null) {
                    // Mined confirmed match: remove pending from state + persistence.
                    pendingToRemove.add(pendingMsg.id)
                    Log.d(
                        "ZCHAT_DEDUP",
                        "Pending ${pendingMsg.id} matched mined confirmed message for ${pendingMsg.peerAddress.redactAddress()}"
                    )
                } else {
                    // Unmined confirmed match: suppress duplicate in UI but keep pending persisted.
                    // This avoids temporary double rows while preventing premature permanent removal.
                    pendingSuppressedByUnmined++
                    Log.d(
                        "ZCHAT_DEDUP",
                        "Pending ${pendingMsg.id} matched unmined tx, suppressing duplicate for ${pendingMsg.peerAddress.redactAddress()}"
                    )
                }
            } else if (pendingMsg.id !in confirmedIds) {
                // No matching confirmed message, show pending. C3 (B2 review item 7): a free (NOSTR) payment request
                // row's isPaid was fixed when the row was built; it follows the paid set here, so the bubble drops
                // Pay once the request is paid (a Keystone fulfil, or the scan-back after a kill).
                val pr = pendingMsg.paymentRequest
                // Round 8 P2: a request whose started payment this pass proved never went out offers Pay again.
                val shown =
                    if (pr != null && pr.isPaid && pendingMsg.id in withdrawnFulfils) {
                        pendingMsg.copy(paymentRequest = pr.copy(isPaid = false))
                    } else if (pr != null &&
                        !pr.isPaid &&
                        pendingMsg.id !in withdrawnFulfils &&
                        (pendingMsg.id in paidReqIds || pendingMsg.id in fulfilledSeenThisPass)
                    ) {
                        pendingMsg.copy(paymentRequest = pr.copy(isPaid = true))
                    } else {
                        pendingMsg
                    }
                messagesByPeer.getOrPut(pendingMsg.peerAddress) { mutableListOf() }.add(shown)
            }
        }

        // P2a — retire-only match for older-build rows: a MINED outgoing transaction to the same contact with the
        // same text, first seen no earlier than the row was written (less a clock allowance), each used once. An
        // unmined one only hides the duplicate. Nothing here re-sends or unblocks Retry; it only retires the row.
        for ((legacyMsg, contentKey) in legacyRows.sortedBy { it.first.timestamp }) {
            val candidates = confirmedOutgoingByContent[contentKey]
            val notBefore = legacyMsg.timestamp.minusMillis(LEGACY_RETIRE_CLOCK_ALLOWANCE_MS)
            val index =
                candidates
                    ?.withIndex()
                    ?.filter { !it.value.timestamp.isBefore(notBefore) }
                    ?.minByOrNull { it.value.timestamp }
                    ?.index ?: -1
            if (candidates != null && index >= 0) {
                val matched = candidates.removeAt(index)
                if (matched.minedHeight != null) {
                    pendingToRemove.add(legacyMsg.id)
                    Log.d("ZCHAT_DEDUP", "Legacy pending ${legacyMsg.id} retired by a later mined copy")
                } else {
                    pendingSuppressedByUnmined++
                }
            } else if (legacyMsg.id !in confirmedIds) {
                messagesByPeer.getOrPut(legacyMsg.peerAddress) { mutableListOf() }.add(legacyMsg)
            }
        }

        // Remove pending messages from persistence only when their match is mined.
        if (pendingToRemove.isNotEmpty()) {
            val removedFromPending = mutableSetOf<String>()
            pendingMessages.update { current ->
                val filtered = current.filter { it.id !in pendingToRemove }
                current.filter { it.id in pendingToRemove }.forEach { removedFromPending.add(it.id) }
                filtered
            }
            // Also remove from preferences to keep persistence in sync
            if (removedFromPending.isNotEmpty()) {
                zchatPreferences.removePendingMessages(removedFromPending)
            }
        }

        val pendingShown = pendingMsgs.size - pendingToRemove.size - pendingSuppressedByUnmined
        Log.i(
            "ZCHAT_DIAG",
            "Dedup: minedRemoved=${pendingToRemove.size} unminedSuppressed=$pendingSuppressedByUnmined pendingShown=$pendingShown"
        )

        // R8-fixup F7: our own requests a contact paid (on-chain rows and free ones alike, so after the pending merge).
        if (incomingFulfils.isNotEmpty()) markOwnRequestsPaid(incomingFulfils, messagesByPeer)

        // F5: the contacts' requests we paid, on-chain rows and free ones alike: "Payment pending" until it is mined.
        markFulfilsPending(fulfilPending, messagesByPeer)

        // Attach collected reactions to their target rows (matched by txid). Done here, after both
        // the tx loop and pending merge, so the target is present regardless of arrival order.
        if (reactionsByTarget.isNotEmpty()) {
            for (msgs in messagesByPeer.values) {
                for (i in msgs.indices) {
                    // The sender reacts against the target's message id (ChatMessage.id), which for an
                    // on-chain message IS its txid string — the same value both peers derive from the
                    // transaction — so matching on id threads the reaction to the right row.
                    val collected = reactionsByTarget[msgs[i].id]
                    if (collected != null) {
                        msgs[i] = msgs[i].copy(reactions = msgs[i].reactions + collected)
                    }
                }
            }
        }

        // Round 10b R10B-2 (F-R9C-3): the rows mined before each chat's key exchange completed carry no unverified chip.
        if (kexAckSightings.isNotEmpty()) markPreSessionRows(kexAckSightings, messagesByPeer)
        // ZC-1792 F2/F3: honest bubbles and banner for rows mined before the key exchange finished.
        settleDecryptOutcomes(decryptOutcomes, kexAckSightings, messagesByPeer)

        // B1/B2: REPLACE the stored convergent txid sets with what this full chain scan observed, and
        // invalidate the cached processor when a set actually changed so the root re-derives. Recompute-
        // replace (not accumulate) is what makes both devices converge and heals pre-update/dual-KEX/reorg.
        val touchedConvs = scannedKexByConv.keys + scannedKexAckByConv.keys
        // ZC-757 (k) round 12 (ZC-1155): an answer [takeAskedAnswer] refuses (filed under one address, claiming another
        // holder of the receiver our key exchange paid) never enters the filed address's KEXACK set. Round 15b: one that
        // only waits for our outputs to be read leaves its id's KEXACK set as stored this pass (no replace).
        val refusedAnswerTxIds = refusedAnswerTxIds(minedAnswers, ownMinedKexSent)
        val waitingAnswers = answersWaitingOnUnreadableOutputs(minedAnswers, ownMinedKexSent)
        val waitingAnswerPeers = waitingAnswers.mapNotNullTo(HashSet()) { zchatPreferences.getPeerByConversationId(it.convId) }
        // ZC-1571 (owner W-133, option A): the material is per PEER, the union of the mined txids under every id filed
        // under that peer, replaced once per peer. Replacing once per id let the last id win (HashMap order), so two phones
        // with key exchanges under two ids derived different roots. A chat whose history sits under one id gets exactly
        // the set 2.12.4 stored (KexRootUnion2124GuardTest).
        val kexByPeer = LinkedHashMap<String, MutableSet<String>>()
        val ackByPeer = LinkedHashMap<String, MutableSet<String>>()
        for ((convId, txids) in scannedKexByConv) {
            val peer = zchatPreferences.getPeerByConversationId(convId) ?: continue
            kexByPeer.getOrPut(peer) { mutableSetOf() } += txids
        }
        for ((convId, txids) in scannedKexAckByConv) {
            val peer = zchatPreferences.getPeerByConversationId(convId) ?: continue
            ackByPeer.getOrPut(peer) { mutableSetOf() } += txids - refusedAnswerTxIds
        }
        for ((peer, txid) in attributeUnfiledKex(receivedMinedKex)) {
            kexByPeer.getOrPut(peer) { mutableSetOf() } += txid
        }
        // ZC-1586: an own scalar this pass changed or removed reaches the root only through a rebuilt processor (ZC-1605:
        // already dropped at the write). Only the net change holds the send gate: a scalar a pass moves and moves back
        // (two own key exchanges to one peer) leaves the root as it was.
        for ((peer, before) in ownScalarsBefore) {
            if (before != (zchatPreferences.getE2EKexTxId(peer) to zchatPreferences.getE2EKexAckTxId(peer))) {
                invalidateMessageProcessors(peer)
                rootChangedPeers += peer
            }
        }
        for (peer in kexByPeer.keys + ackByPeer.keys) {
            val newKex: Set<String> = kexByPeer[peer] ?: emptySet()
            val newAck: Set<String> = ackByPeer[peer] ?: emptySet()
            var changed = false
            if (newKex.isNotEmpty() && zchatPreferences.getKexTxIds(peer) != newKex) {
                zchatPreferences.setKexTxIds(peer, newKex); changed = true
            }
            if (peer !in waitingAnswerPeers && newAck.isNotEmpty() && zchatPreferences.getKexAckTxIds(peer) != newAck) {
                zchatPreferences.setKexAckTxIds(peer, newAck); changed = true
            }
            if (changed) {
                invalidateMessageProcessors(peer)
                rootChangedPeers += peer
            }
        }

        // P2d (2) — restore recovery, from each peer's LATEST own key on chain (see ownKeySightings). Only on a
        // complete, stable pass: while the history is still arriving the newest key may not have been read yet, and
        // a stored key is never replaced. Runs before the KEXACK evidence, the send-gate reconcile and the inbound
        // key offers below, all of which read the key it installs.
        val ownKeysByPeer = LinkedHashMap<String, MutableList<String>>()
        for ((sightingConvId, ownKey) in ownKeySightings) {
            val peer = zchatPreferences.getPeerByConversationId(sightingConvId) ?: continue
            ownKeysByPeer.getOrPut(peer) { mutableListOf() } += ownKey
        }
        // R2-4 (c): the pass must also have read every one of our own memos, or the latest key may be unread.
        val ownHistoryPassComplete =
            RestoreKexPolicy.isOwnHistoryPassComplete(
                historyScanComplete = historyScanComplete,
                passStable = passStable,
                ownMemoReadFailures = ownMemoReadFailures,
            )
        // Round 8 MA3: this pass saw every own sent GP (they recorded CHAIN_SENT above); what is still pending was cut off.
        if (ownHistoryPassComplete) runCatching { settleStrandedAnnouncePayments() }
        for ((peer, ownKeys) in ownKeysByPeer) {
            if (zchatPreferences.getE2EOurPublicKey(peer) != null) continue
            if (!ownHistoryPassComplete) {
                waitingHistoricalHandshakes++
                continue
            }
            if (seedKeyProvider.recoverLatestIfSeedDerived(peer, ownKeys)) {
                invalidateMessageProcessors(peer)
                // R5 — recovery armed this peer's send gate; it recovered THIS pass, so the pass-end reconcile keeps
                // it gated until the NEXT (converged) pass floors it.
                recoveredThisPass.add(peer)
                Log.i("KEX", "D1-recovery: re-derived our latest E2E key for ${peer.redactAddress()} from seed")
            }
        }
        for ((ackConvId, ackOwnKey, answeredPeerKey) in ownMinedKexAcks) {
            val peer = zchatPreferences.getPeerByConversationId(ackConvId) ?: continue
            RestoreKexPolicy
                .peerKeyAckedOnChain(
                    ownKexAckPublicKey = ackOwnKey,
                    currentOwnPublicKey = zchatPreferences.getE2EOurPublicKey(peer),
                    lastInboundPeerKexKey = answeredPeerKey,
                )?.let { peerKeyAckedOnChain[peer] = it }
        }

        // ZC-634 (5.5 items 2 and 2a): what this wallet's own mined answers say about the keys they answered, read before the
        // inbound key offers below are stored: an answered key whose answer is not settled is a claim like any other (A19).
        for ((ackConvId, _, answeredPeerKey) in ownMinedKexAcks) {
            val peer = zchatPreferences.getPeerByConversationId(ackConvId) ?: continue
            val key = answeredPeerKey ?: continue
            ownAnswerVerdicts[peer] = OwnAnswerVerdict(key, answerIsSettled(peer, key, ownMinedKexSent, minedAnswers))
        }

        // No paid KEXACK replay after a restore: record the peer key our own mined KEXACK already answered,
        // only where no marker exists yet (a live marker is never overwritten by history).
        for ((peer, ackedKey) in peerKeyAckedOnChain) {
            if (zchatPreferences.getSentKexAckPubkey(peer) == null) {
                zchatPreferences.setSentKexAckPubkey(peer, ackedKey)
                Log.d("KEX", "Restore: KEXACK for ${peer.redactAddress()} already on chain — recorded, not re-paid")
            }
            // ZC-949 (5.5 items 1 and 2a): a hold whose key this wallet's own mined answer already answered, and that
            // answer is settled, is dropped: the answer is paid (by a second device on the same phrase, or before a
            // restore), so its banner's "nothing has been paid" and an Accept that sends nothing would be false. An answer
            // that is not settled keeps its hold (and the hold keeps stopping the key's ZBOOT).
            if (zchatPreferences.getInboundKexAwaitingAccept(peer) == ackedKey &&
                answerIsSettled(peer, ackedKey, ownMinedKexSent, minedAnswers)
            ) {
                if (zchatPreferences.setInboundKexAwaitingAccept(peer, null)) {
                    Log.d("KEX", "Hold of ${peer.redactAddress()} dropped: this wallet's own mined answer settled its key")
                }
            }
        }

        // R5 pass-end reconcile — close the send gate's "block forever" risk. This pass has now
        // fully processed history (own-outgoing decrypts at ~3792 raised the counter floor for any
        // peer whose root was already converged coming in). For every E2E peer NOT freshly recovered
        // THIS pass, clear its recovery-pending marker: the floor is authoritative now (>0 → sends
        // resume above burned counters; ==0 → the peer had no own-outgoing history, so counter 0 is
        // safe). Peers recovered THIS pass stay gated until the next converged pass. Union of message
        // peers + KEX-touched peers covers every recovered peer (recovery requires an on-chain
        // self-KEX, which folds into touchedConvs once our key is held). reconcile is a no-op (no
        // lock) for the overwhelming majority that were never in recovery.
        val recoveryPeers = messagesByPeer.keys +
            touchedConvs.mapNotNull { zchatPreferences.getPeerByConversationId(it) }
        // KR-3 (GPT U2): only a pass that read the whole history, with a converged root and every one of our
        // own messages to the peer decrypted, may open the gate.
        val passHistoryComplete =
            RestoreKexPolicy.isPassHistoryComplete(
                historyScanComplete = historyScanComplete,
                passStable = passStable,
                memoReadFailures = memoReadFailures,
                unattributedOwnEnvelopeGaps = unattributedOwnEnvelopeGaps,
            )
        // R3-3 (1): settle the send counters a ratchet carries from an older conversation id of the peer (an app
        // version from before R2-4 kept them per id, and its Reset Encryption cleared the current id only). Sends to
        // the peer wait until this is done (getOrCreateMessageProcessor).
        val legacyJumpsWaiting =
            settleLegacyFloorJumps(
                peers = peersWithOlderConvEnvelopes + peersAwaitingLegacySettlement.orEmpty(),
                ownHistoryPassComplete = ownHistoryPassComplete,
                historyScanComplete = historyScanComplete,
                ownEnvelopesByConv = ownEnvelopesUnderOlderConv,
                unreadOwnEnvelopesByConv = unreadOwnEnvelopesByConv,
                unattributedOwnEnvelopes = unattributedUnreadOwnEnvelopes,
                headerUnknownPeers = ownEnvelopeHeaderUnknownPeers + unparsedOwnEnvelopePeers,
                headerUnknownConvIds = unparsedOwnEnvelopeConvIds,
                unattributedOwnEnvelopeGaps = unattributedOwnEnvelopeGaps,
            )
        var restoredPeerStillGated = false
        for (peer in recoveryPeers) {
            if (!zchatPreferences.isE2ERecoveryFloorPending(peer)) continue
            val sendConvId = zchatPreferences.getConversationId(peer)
            val ownEnvelopeGap =
                peer in ownEnvelopeGapPeers ||
                    sendConvId?.let { it in ownEnvelopeGapConvIds } == true ||
                    unattributedUnreadOwnEnvelopes.isNotEmpty()
            // P2d (3): an own message this pass could not read no longer keeps the gate shut once the send floor is
            // raised above it from its header (RestoreKexPolicy.floorSendCounterAboveUnreadOwnEnvelopes).
            val gapFloored =
                ownEnvelopeGap &&
                    passHistoryComplete &&
                    sendConvId != null &&
                    peer !in unparsedOwnEnvelopePeers &&
                    sendConvId !in unparsedOwnEnvelopeConvIds &&
                    floorAboveUnreadOwnEnvelopes(
                        peer,
                        sendConvId,
                        unreadOwnEnvelopesByPeer[peer].orEmpty() +
                            unreadOwnEnvelopesByConv[sendConvId].orEmpty() +
                            unattributedUnreadOwnEnvelopes,
                    )
            val historyCompleteForPeer =
                RestoreKexPolicy.mayReleaseSendGate(
                    passHistoryComplete = passHistoryComplete,
                    recoveredThisPass = false,
                    rootChangedThisPass = peer in rootChangedPeers,
                    ownEnvelopeGap = ownEnvelopeGap && !gapFloored,
                )
            seedKeyProvider.reconcileRecoveryMarker(
                peer,
                recoveredThisPass = peer in recoveredThisPass,
                historyComplete = historyCompleteForPeer,
            )
            if (zchatPreferences.isE2ERecoveryFloorPending(peer)) restoredPeerStillGated = true
        }

        // KI-24 fixup G-KI24-2: the processed-KEX floor must never pass a mined key offer the store has not recorded (put
        // off below, or handed to handleKEXMessage and not marked yet): it would take it for processed, and the contact's
        // key would never be stored or answered. Report the lowest such offer before any is handled; only a complete,
        // stable pass may let the floor rise, never above the highest mined height it read. ZC-074: only a real unknown
        // holds it (RestoreKexPolicy.isKexFloorPassComplete): such an offer, or an inbound memo this pass could not read,
        // each at its own mined height; our own messages (read or not) and unmined transactions do not.
        // ZC-599 (5.4 items 2 and 3): the answers the loop could not decide, judged against every own key exchange this
        // pass read. One that is not asked is neither mapped nor handled; it is marked processed only once two complete
        // passes at rising scanned heights judged it not asked, the second above its height plus one expiry window.
        val unaskedAnswerHeights = mutableListOf<Long>()
        val scannedTip = fullyScannedTip()
        // ZC-1128: a hidden old answer raises the flag unless it is backed as an old answer taken here would be (leg 3 with
        // an own mined key exchange to its address at or below it, not a leg 2 answer under a foreign id, which carries a
        // claim mark instead); every doubt fails towards the hold.
        val hiddenOldAnswerUnbacked =
            hiddenOldAnswers.any { answer ->
                val filedUnder = answerFiledUnder(answer)
                val foreignLeg2 =
                    filedUnder != null &&
                        judgeAnswer(answer, ownMinedKexSent) == AnswerVerdict.LEG2 &&
                        !zchatPreferences.isOwnConversationId(answer.convId, filedUnder) &&
                        ownMinedKexSent.none { it.convId == answer.convId }
                foreignLeg2 || !oldAnswerIsBacked(answer, filedUnder, ownMinedKexSent)
            }
        oldInboundUnreadInPass = oldInboundUnread || hiddenOldAnswerUnbacked
        // ZC-599 (money recheck 26 Oct, finding 2): the old answers the loop took by leg 3, now that every own key exchange of
        // the pass is read (one in the same block, later in the pass's order, backs an honest answer).
        // ZC-1123: judged again against all of them, one that now counts as leg 2 under an id that is not ours (no own id
        // record for its address, no own key exchange under it) is taken as leg 2 is there: with its claim mark, so a key
        // exchange repeating its key waits for Accept (W-62, as W62b). Under our own key exchange's id it stays leg 3.
        for (answer in oldAnswersToTake) {
            val filedUnder = answerFiledUnder(answer)
            val foreignLeg2 =
                filedUnder != null &&
                    judgeAnswer(answer, ownMinedKexSent) == AnswerVerdict.LEG2 &&
                    !zchatPreferences.isOwnConversationId(answer.convId, filedUnder) &&
                    ownMinedKexSent.none { it.convId == answer.convId }
            val leg = if (foreignLeg2) AnswerVerdict.LEG2 else AnswerVerdict.LEG3
            takeAskedAnswer(answer, userAddress, leg, ownMinedKexSent)
        }
        for (answer in answersToJudge) {
            val verdict = judgeAnswer(answer, ownMinedKexSent)
            if (verdict != AnswerVerdict.NOT_ASKED) {
                takeAskedAnswer(answer, userAddress, verdict, ownMinedKexSent)
                continue
            }
            if (zchatPreferences.hasProcessedKexTx(answer.txId, answer.height)) continue
            if (ownHistoryPassComplete && scannedTip != null) {
                val first = unaskedAnswerJudgedAt[answer.txId]
                if (first == null) {
                    unaskedAnswerJudgedAt[answer.txId] = scannedTip
                } else if (scannedTip > first && KexAnswerWindow.ownKexWaitIsOver(answer.height, scannedTip)) {
                    zchatPreferences.markKexTxProcessed(answer.txId, answer.height, scannedTip)
                    unaskedAnswerJudgedAt.remove(answer.txId)
                    Log.d("KEX", "Inbound answer nobody asked for — marked processed, nothing changed")
                    continue
                }
            }
            unaskedAnswerHeights += answer.height
        }
        // ZC-599 (5.4 item 4): a request an earlier build received keeps the id of its mined key exchange, where that
        // key is the responder mark's key and the id maps to that contact.
        for ((kexConvId, kexKey) in lastInboundKexKeyByConv) {
            val peer = zchatPreferences.getPeerByConversationId(kexConvId) ?: continue
            if (zchatPreferences.getReceivedKexPubkey(peer) == kexKey && zchatPreferences.getReceivedKexConvId(peer) == null) {
                zchatPreferences.setReceivedKexConvId(peer, kexConvId)
            }
        }
        val lowestUnrecordedOfferHeight =
            (
                inboundKeyOffers
                    .mapNotNull { (_, txId, height) ->
                        height?.takeIf { it > 0 && !zchatPreferences.hasProcessedKexTx(txId, it) }
                    } + unaskedAnswerHeights +
                    // ZC-757 (k) round 15b (compat-2124 rule 5): an answer waiting for our outputs to be read.
                    waitingAnswers.mapNotNull { a -> a.height.takeIf { !zchatPreferences.hasProcessedKexTx(a.txId, it) } }
            ).minOrNull()
        zchatPreferences.limitKexFloor(
            passComplete = RestoreKexPolicy.isKexFloorPassComplete(historyScanComplete, passStable),
            passTopHeight = transactions.maxOfOrNull { it.overview.minedHeight?.value ?: 0L }?.takeIf { it > 0 },
            lowestUnrecordedOfferHeight = listOfNotNull(lowestUnrecordedOfferHeight, lowestUnreadInboundMinedHeight).minOrNull(),
        )
        // KR-2: inbound key offers, after our own history in this pass has been read (see inboundKeyOffers). A
        // historical one is acted on only once the scan has read our own history.
        for ((memo, txId, kexMinedHeight) in inboundKeyOffers) {
            val mayAct =
                zchatPreferences.hasProcessedKexTx(txId, kexMinedHeight) ||
                    RestoreKexPolicy.mayActOnInboundHandshake(
                        kexMined = kexMinedHeight != null,
                        historyScanComplete = historyScanComplete,
                        passStable = ownHistoryPassComplete,
                    )
            // ZC-941 (5.4 item 7): an unmined key exchange waits for its own mining, which starts a pass by itself.
            if (!mayAct && kexMinedHeight != null) waitingHistoricalHandshakes++
            handleKEXMessage(memo, userAddress, txId, mayActOnInboundHandshake = mayAct, minedHeight = kexMinedHeight)
        }

        // Converge without waiting for an unrelated transaction: one more pass shortly, a bounded number of
        // times per transaction list, while a restored peer is still gated or a historical KEX still waits.
        lastCompletePassFingerprint = if (historyScanComplete) passFingerprint else null
        // P2b: this pass read the whole history, so every ZBOOT we already paid for is recorded (see
        // recordOwnMinedZbootInPass); automatic ZBOOTs may pay from now on.
        val zbootHistoryReady = finishZbootHistoryPass(zbootPass, historyScanComplete && memoReadFailures == 0)
        // ZC-704 (KI-25 R19): the end of every history pass, after the loop handed the chain's changes over: the
        // changes the groups kept from the relays. Only a pass that read the whole history runs those kept as refused.
        // ZC-757 (G2): the block time of the newest mined transaction the wallet lists, for a rebuilt group's key number.
        // ZC-1068: only from a pass that read the whole history (scan complete, every memo read): it opens the rebuilt
        // group's first new key, and our own removal may sit in what a partial pass did not read. The pass runs over the
        // wallet's stored transactions, so a phone with no network gets here too.
        if (historyScanComplete && memoReadFailures == 0) {
            transactions
                .filter { it.overview.minedHeight != null }
                .mapNotNull { it.timestamp?.toEpochMilli() }
                .maxOrNull()
                ?.let { newest ->
                    val rebuilt = co.electriccoin.zcash.ui.screen.chat.model.RebuiltGroupKey
                    if (newest > rebuilt.newestMinedTxMs) rebuilt.newestMinedTxMs = newest
                }
        }
        endHistoryPass(historyPass, historyScanComplete && memoReadFailures == 0)
        // ZC-785 (a): a latch. A later pass that does not end ready (a memo it could not read, another screen's pass
        // still holding a contact, a write the store did not save) never closes it: the contact it has not settled
        // keeps its evidence and waits by itself (the sender's own check), and every other contact goes on. Only the
        // start of a restore or rescan closes the gate again.
        if (historyScanComplete && memoReadFailures == 0 && zbootHistoryReady) processHistoryRead.set(true)
        // W-72 (SPEC_DECISIONS D2): once a pass read everything and acted on every key offer, the keys a restore rebuilt are
        // all stored (with their pre-update marks); keys stored from now on are marked only by the height rule.
        if (historyScanComplete &&
            memoReadFailures == 0 &&
            ownHistoryPassComplete &&
            waitingHistoricalHandshakes == 0 &&
            zchatPreferences.isLegacyHistoryRead() == false
        ) {
            zchatPreferences.setLegacyHistoryRead()
        }
        // P2d (1): restore recovery has now run on the full history (it runs on a complete, stable pass), so a send
        // may create a key for a peer that still has none. Until then sends to such a peer wait.
        if (ownHistoryPassComplete) SeedDerivedE2EKeyProvider.processOwnHistoryRead.set(true)
        val ownHistoryUnread = !SeedDerivedE2EKeyProvider.processOwnHistoryRead.get()
        if (historyScanComplete &&
            (restoredPeerStillGated || waitingHistoricalHandshakes > 0 || ownHistoryUnread || legacyJumpsWaiting)
        ) {
            if (restoreRecheckStreak < MAX_RESTORE_RECHECKS) {
                restoreRecheckStreak++
                viewModelScope.launch {
                    delay(RESTORE_RECHECK_DELAY_MS)
                    restoreRecheck.update { it + 1 }
                }
            }
        } else {
            restoreRecheckStreak = 0
        }

        // D11 (privacy) — attachment hashes of TTL-expired messages dropped by the render filter below.
        // Their DECRYPTED blobs would otherwise sit in the disk cache forever (nothing references an
        // expired message's hash again); collected here and securely purged after the map.
        val ttlExpiredFileHashes = mutableSetOf<String>()

        // B17/D10 — ids of TTL-expired rows, tombstoned durably after the map. The filter below is
        // LIVE-ONLY: without a tombstone every expired row RESURRECTS in full the moment the TTL is set
        // to Off (`ttlSeconds <= 0` returns allMessages) — two taps on an unlocked device, i.e. exactly
        // the coercion threat model disappearing messages exist to defend — while its attachments are
        // already irreversibly gone. Expiry must be one-way, like the file wipe.
        val ttlExpiredIds = mutableSetOf<String>()
        // R2-5 (c) / M-CHT-31: messages that expired on an earlier pass (durable, apart from ids the user hid).
        val knownExpiredIds = zchatPreferences.getExpiredMessageIds()

        // Convert to Conversation objects (only include conversations with visible messages)
        val conversations = messagesByPeer
            .filter { (_, messages) -> messages.isNotEmpty() }
            .map { (peerAddress, allMessages) ->
                // B17 — render-time expiry: hide messages past this conversation's synced TTL (exact to the
                // second; no restart needed). On-chain txs can only be HIDDEN locally — the durable sweep
                // tombstones them so they stay gone; this is the live view filter.
                val b17Ttl = zchatPreferences.getDisappearingTtl(peerAddress)
                val b17Now = ttlNowMillis() // R9-6: the ticker in conversationRenderFlow reads the same clock
                val unexpiredMessages = if (b17Ttl == null || b17Ttl.ttlSeconds <= 0L) allMessages else allMessages.filterNot { m ->
                    val expireAt = co.electriccoin.zcash.ui.screen.chat.model.DisappearPolicy.expireAtMillis(
                        m.timestamp.toEpochMilli(), b17Now, b17Ttl.ttlSeconds, b17Ttl.effectiveSinceMillis,
                        m.isPending, m.status == MessageStatus.FAILED, m.isSystemNote, m.callLog != null,
                        m.timeLock?.isUnlocked,
                        m.timeLock?.takeIf { it.lockType == co.electriccoin.zcash.ui.screen.chat.model.TimeLockType.SCHEDULED }?.unlockTimestamp?.times(1000),
                        m.timeLock?.takeIf { it.isUnlocked && it.lockType != co.electriccoin.zcash.ui.screen.chat.model.TimeLockType.SCHEDULED }
                            ?.let { zchatPreferences.getOrPutMessageExpiryAnchorMillis(m.id, b17Now) },
                    ) ?: Long.MAX_VALUE
                    val b17Expired = expireAt <= b17Now
                    if (b17Expired) {
                        ttlExpiredIds.add(m.id)
                        m.fileHash?.let { ttlExpiredFileHashes.add(it) }
                    } else if (expireAt != Long.MAX_VALUE) {
                        nextTtlExpiry.offer(expireAt) // R9-6: the render re-runs when this row's time is up
                    }
                    b17Expired
                }
                // R2-5 (c) / M-CHT-31: a reply embeds a preview of the message it quotes. Once that message
                // expired, the reply shows that it expired, never the text (also after the timer is turned off).
                val messages =
                    unexpiredMessages.map { m ->
                        val quoted = m.replyToId
                        if (quoted != null && (quoted in ttlExpiredIds || quoted in knownExpiredIds)) {
                            m.copy(replyToPreview = EXPIRED_QUOTE_PREVIEW)
                        } else {
                            m
                        }
                    }
                // Sort messages: block height (primary), tx index within block (secondary),
                // timestamp (tertiary), then ID for deterministic stability.
                //
                // #bug-msg-order — a pending message (null height) used to sort to Long.MAX_VALUE (the very
                // bottom), then JUMP up to its real block-height slot once mined — so a time-locked /
                // postponed message (which sits pending+locked for a long time) and its neighbours visibly
                // shuffled "before and after" each other as txs confirmed. Instead, anchor every un-mined
                // row to ONE bucket just above the chain tip, where its mined height usually lands, so it sits
                // near its eventual slot at once. Mined-vs-mined ordering is unchanged (those rows never use the
                // bucket); among pending/NOSTR rows the existing timestamp tie-break keeps chronological order.
                //
                // R5 (round-4 report 5A, MONEY) — that tip is the highest block this conversation had reached
                // AT THE ROW'S OWN TIME, not the highest block it ever reaches. The overall maximum anchored rows
                // that will NEVER be mined (relay messages, local notes, a delivered NOSTR bubble) above every
                // on-chain row, so a relay chat's first paid Shielded message landed at the TOP of the thread.
                //
                // Round 7c (R6-4 review finding 19) — a trade-off, not a promise of "no jump". A pending own send
                // U sent at tip T sits in bucket T+1, above a message M sent after it and mined at T+1 (sent order;
                // Round 7 below). If U then mines at T+2 it moves below M, once; the old bottom anchor jumped every
                // time U mined. While nothing is mined after U, it stays at the end. Display order only;
                // PaidMessageStaysInTheThreadTest pins this chosen order.
                val bucketByRow = java.util.IdentityHashMap<ChatMessage, Long>(messages.size)
                var tipSoFar = 0L
                for (row in messages.sortedBy { it.timestamp }) {
                    row.minedHeight?.let { if (it > tipSoFar) tipSoFar = it }
                    bucketByRow[row] = tipSoFar + 1
                }
                // Round 7 (THREAD-SORT-RELAY-VS-NEXT-BLOCK) — the position in a block orders two MINED rows only. A
                // row with no block (relay, local note, a send still waiting) that shares its bucket with the
                // rows mined at that height sorts above them: by the loop above, every row mined at that height
                // was sent no earlier than it, so this is the order they were sent in. Comparing its missing tx index
                // (Int.MAX_VALUE) against a real one put an older relay row BELOW the next block's reply. The
                // single key keeps the comparator a total order; mined-vs-mined is unchanged.
                val sortedMessages = messages.sortedWith(
                    compareBy<ChatMessage> { it.minedHeight ?: bucketByRow.getValue(it) }
                        .thenBy { if (it.minedHeight == null) -1 else it.txIndex ?: Int.MAX_VALUE }
                        .thenBy { it.timestamp }
                        .thenBy { it.txId?.txIdString() ?: it.id }
                )
                // Look up nickname (from preferences) or contact name (from contact book)
                // Nickname takes priority over contact book name
                val nickname = zchatPreferences.getNickname(peerAddress)
                val contact = contactBook.getContact(peerAddress)
                val displayContactName = nickname ?: contact?.name
                Conversation(
                    peerAddress = peerAddress,
                    messages = sortedMessages,
                    // Local-only system notes (e.g. the key-rotation pill) must not hijack the chat-list
                    // preview or leak into list search — exclude them from the lastMessage pick, falling
                    // back to the newest message overall only if a conversation somehow has nothing else.
                    lastMessage = messages.filterNot { it.isSystemNote }.maxByOrNull { it.timestamp }
                        ?: messages.maxByOrNull { it.timestamp },
                    contactName = displayContactName
                )
            }.sortedByDescending { it.lastMessage?.timestamp }

        // B17/D10 — DURABLE sweep (the half that never shipped). The TTL filter above is LIVE-ONLY: it
        // hides expired rows this pass, but (a) NOSTR rows are persisted isPending=false and are never
        // mined, so the mined-dedup above never removes them — their text sits in the encrypted pending
        // store forever; and (b) every expired row RESURRECTS in full the moment the TTL is set to Off,
        // because `ttlSeconds <= 0` returns allMessages unfiltered. Meanwhile the attachment wipe below
        // is already irreversible. Shipping the destructive half without this one means the app destroys
        // the photos it promised to delete and keeps the text it promised to delete. Tombstone the ids and
        // drop the retained text so expiry is one-way.
        //
        // ORDERING (load-bearing): this terminates only because the hidden-id filters (tx loop ~3472 and
        // the pending merge ~4283) run UPSTREAM of the TTL filter above — a tombstoned id never re-enters
        // ttlExpiredIds, so newTombstones is empty on the next pass. Do NOT move the TTL filter above the
        // hidden filter, or this becomes an unbounded write loop from the render pass.
        if (ttlExpiredIds.isNotEmpty()) {
            val newTombstones = ttlExpiredIds - hiddenMsgIds
            if (newTombstones.isNotEmpty()) {
                zchatPreferences.hideMessages(newTombstones) // durable tombstone: survives TTL-off
                zchatPreferences.markMessagesExpired(newTombstones) // R2-5 (c): replies show "expired"
                // R2-5 (c): delete the decrypted text of expired encrypted messages, on disk and in memory.
                newTombstones.forEach { id ->
                    decryptedTextKeysByMessage[id]?.forEach { key ->
                        decryptedTextCache.remove(key)
                        zchatPreferences.removeDecryptedText(key)
                    }
                }
                zchatPreferences.removePendingMessages(newTombstones) // delete retained NOSTR plaintext
                // Safe ONLY inside this branch: a tombstoned row is filtered upstream forever, so its
                // anchor is never re-read. Clearing the anchor of a still-VISIBLE row would re-anchor it
                // at a fresh `now` and it would never expire.
                newTombstones.forEach { zchatPreferences.clearMessageExpiryAnchor(it) }
                pendingMessages.update { list -> list.filterNot { it.id in newTombstones } }
                hiddenMessages.update { it + newTombstones }
            }
        }

        // D11 (privacy) — securely purge the cached decrypted blobs of TTL-expired attachments. The
        // isFileViewed skip makes this frequent render pass one-shot per hash: mark it viewed (also
        // blocks any re-download via downloadAndCacheFile's guard), then overwrite+delete on IO.
        // Uses the already-initialized cache instance (getFileCache needs a Context this scan doesn't
        // have); if it isn't built yet we skip WITHOUT marking viewed, so a later pass retries.
        if (ttlExpiredFileHashes.isNotEmpty()) {
            val expiredCache = _fileCache
            if (expiredCache != null) {
                val toPurge = ttlExpiredFileHashes.toList()
                viewModelScope.launch(kotlinx.coroutines.Dispatchers.IO) {
                    for (hash in toPurge) {
                        if (zchatPreferences.isFileViewed(hash)) continue
                        zchatPreferences.markFileViewed(hash)
                        expiredCache.secureDelete(hash)
                    }
                }
            }
        }

        return conversations
    }

    /**
     * Extract just the message content from a ZMSG formatted memo.
     * For chunked messages, this extracts from a single chunk (use reassembleChunks for full message).
     */
    private fun extractMessageContent(memo: String): String {
        // Use constants from ZMSGConstants for consistency
        val prefixV4 = ZMSGConstants.Prefixes.V4       // "ZMSG|v4|"
        val prefixV4C = ZMSGConstants.Prefixes.V4C     // "ZMSG|v4c|"
        val prefixV3 = ZMSGConstants.Prefixes.V3       // "ZMSG|v3|"
        val prefixV3C = ZMSGConstants.Prefixes.V3C     // "ZMSG|v3c|"
        val prefixV2 = ZMSGConstants.Prefixes.V2       // "ZMSG|v2|"
        val initMarker = ZMSGConstants.Markers.INIT    // "INIT|"
        val contMarker = ZMSGConstants.Markers.CONT    // "CONT|"
        val refMarker = ZMSGConstants.Markers.REF      // "REF|"
        val replyMarker = ZMSGConstants.Markers.REPLY  // "RPL|"
        val hashLen = ZMSGConstants.HASH_LENGTH        // 12
        val hashLenNew = ZMSGConstants.HASH_LENGTH_NEW // 16

        // Helper for |INIT| marker (includes pipes)
        val initWithPipes = "|${initMarker.dropLast(1)}|"  // "|INIT|"
        val contWithPipes = "|${contMarker.dropLast(1)}|"  // "|CONT|"
        val initMarkerLen = initWithPipes.length           // 6
        val contMarkerLen = contWithPipes.length           // 6

        // v3 combined prefixes
        val prefixV3Rpl = prefixV3 + replyMarker       // "ZMSG|v3|RPL|"
        val prefixV3Init = prefixV3 + initMarker       // "ZMSG|v3|INIT|"
        val prefixV3Ref = prefixV3 + refMarker         // "ZMSG|v3|REF|"

        return when {
            // v4 INIT: ZMSG|v4|<convID>|INIT|<address>|<message>
            memo.startsWith(prefixV4) && !memo.startsWith(prefixV4C) && memo.contains(initWithPipes) -> {
                val initIndex = memo.indexOf(initWithPipes)
                val afterInit = memo.substring(initIndex + initMarkerLen)
                val sepIndex = afterInit.indexOf('|')
                if (sepIndex != -1) afterInit.substring(sepIndex + 1) else afterInit
            }
            // v4 reply: ZMSG|v4|<convID>|<hash>|<message> (new) or ZMSG|v4|<convID>|<message> (legacy)
            memo.startsWith(prefixV4) && !memo.startsWith(prefixV4C) -> {
                val parts = memo.split("|", limit = 5)
                when {
                    // New format with hash: check if parts[3] is 12 or 16-char hex (legacy/new hash)
                    parts.size >= 5 && (parts[3].length == hashLen || parts[3].length == hashLenNew) && parts[3].all { it in '0'..'9' || it in 'a'..'f' } -> parts[4]
                    // Legacy format without hash
                    parts.size >= 4 -> parts[3]
                    else -> memo
                }
            }
            // v4 Chunked INIT: ZMSG|v4c|1/N|<convID>|INIT|<address>|<message>
            memo.startsWith(prefixV4C) && memo.contains(initWithPipes) -> {
                val initIndex = memo.indexOf(initWithPipes)
                val afterInit = memo.substring(initIndex + initMarkerLen)
                val sepIndex = afterInit.indexOf('|')
                if (sepIndex != -1) afterInit.substring(sepIndex + 1) else afterInit
            }
            // v4 Chunked CONT: ZMSG|v4c|M/N|CONT|<message>
            memo.startsWith(prefixV4C) && memo.contains(contWithPipes) -> {
                val contIndex = memo.indexOf(contWithPipes)
                memo.substring(contIndex + contMarkerLen)
            }
            // v4 Chunked reply: ZMSG|v4c|1/N|<convID>|<hash>|<message> (new) or ZMSG|v4c|1/N|<convID>|<message> (legacy)
            memo.startsWith(prefixV4C) -> {
                val parts = memo.split("|", limit = 6)
                when {
                    // New format with hash: check if parts[4] is 12 or 16-char hex (legacy/new hash)
                    parts.size >= 6 && (parts[4].length == hashLen || parts[4].length == hashLenNew) && parts[4].all { it in '0'..'9' || it in 'a'..'f' } -> parts[5]
                    // Legacy format without hash
                    parts.size >= 5 -> parts[4]
                    else -> memo
                }
            }
            // Chunked INIT: ZMSG|v3c|1/N|INIT|<address>|<message>
            memo.startsWith(prefixV3C) && memo.contains(initWithPipes) -> {
                val initIndex = memo.indexOf(initWithPipes)
                val afterInit = memo.substring(initIndex + initMarkerLen)
                val sepIndex = afterInit.indexOf('|')
                if (sepIndex != -1) afterInit.substring(sepIndex + 1) else afterInit
            }
            // Chunked CONT: ZMSG|v3c|M/N|CONT|<message>
            memo.startsWith(prefixV3C) && memo.contains(contWithPipes) -> {
                val contIndex = memo.indexOf(contWithPipes)
                memo.substring(contIndex + contMarkerLen)
            }
            // Chunked reply first: ZMSG|v3c|1/N|<hash>|<message>
            memo.startsWith(prefixV3C) -> {
                val parts = memo.split("|", limit = 5)
                if (parts.size >= 5) parts[4] else memo
            }
            // RPL with INIT: ZMSG|v3|RPL|<txid>|INIT|<address>|<message>
            memo.startsWith(prefixV3Rpl) && memo.contains(initWithPipes) -> {
                val initIndex = memo.indexOf(initWithPipes)
                val afterInit = memo.substring(initIndex + initMarkerLen)
                val sepIndex = afterInit.indexOf('|')
                if (sepIndex != -1) afterInit.substring(sepIndex + 1) else afterInit
            }
            // RPL with hash: ZMSG|v3|RPL|<txid>|<hash>|<message>
            memo.startsWith(prefixV3Rpl) -> {
                val parts = memo.split("|", limit = 6)
                if (parts.size >= 6) parts[5] else memo
            }
            // Regular INIT: ZMSG|v3|INIT|<address>|<message>
            memo.startsWith(prefixV3Init) -> {
                val parts = memo.split("|", limit = 5)
                if (parts.size >= 5) parts[4] else memo
            }
            // REF with INIT: ZMSG|v3|REF|<txid>|INIT|<address>|<message>
            memo.startsWith(prefixV3Ref) && memo.contains(initWithPipes) -> {
                val initIndex = memo.indexOf(initWithPipes)
                val afterInit = memo.substring(initIndex + initMarkerLen)
                val sepIndex = afterInit.indexOf('|')
                if (sepIndex != -1) afterInit.substring(sepIndex + 1) else afterInit
            }
            // REF with hash: ZMSG|v3|REF|<txid>|<hash>|<message>
            memo.startsWith(prefixV3Ref) -> {
                val parts = memo.split("|", limit = 6)
                if (parts.size >= 6) parts[5] else memo
            }
            // Regular reply with hash: ZMSG|v3|<hash>|<message>
            memo.startsWith(prefixV3) -> {
                val parts = memo.split("|", limit = 4)
                if (parts.size >= 4) parts[3] else memo
            }
            // Legacy v2: ZMSG|v2|<address>|<message>
            memo.startsWith(prefixV2) -> {
                val parts = memo.split("|", limit = 4)
                if (parts.size >= 4) parts[3] else memo
            }
            else -> memo
        }
    }

    /**
     * Extract conversation ID from a memo.
     * Used to restore convId mappings from outgoing messages after wallet restore.
     * Returns null if no convId is found (v2/v3 messages, non-ZMSG memos).
     *
     * Handles both single and chunked memos. For chunked memos, checks each line
     * to find the first chunk (which contains the convId).
     */
    internal fun extractConvIdFromMemo(memo: String): String? = ConvIdResolver.extractConvIdFromMemo(memo)

    internal fun outgoingConvId(memoText: String, stored: () -> String?): String? =
        ConvIdResolver.outgoingConvId(memoText, stored)

    /**
     * P2d (3): the clear header (direction, counter) of our own encrypted message in [memos], read the way the scan
     * reads an outgoing message body; null when the body is not a well-formed E2E1 envelope.
     */
    private fun ownEnvelopeHeader(memos: List<String>): Ciphertext? {
        val body =
            if (memos.any { ZMSGProtocol.isChunkedMemo(it) }) {
                ZMSGProtocol.reassembleChunks(memos, addressCache)?.message ?: extractMessageContent(memos.joinToString("\n"))
            } else {
                extractMessageContent(memos.joinToString("\n").trim())
            }
        return CiphertextWireFormat.parse(body)
    }

    /**
     * P2d (3): raise [peerAddress]'s send floor in [sendConvId] above our own [unread] messages to it (see
     * [RestoreKexPolicy.floorSendCounterAboveUnreadOwnEnvelopes]). False when it cannot: no key pair yet, or a raise
     * the peer could not follow.
     */
    private suspend fun floorAboveUnreadOwnEnvelopes(
        peerAddress: String,
        sendConvId: String,
        unread: List<Ciphertext>,
    ): Boolean {
        val ourPub = zchatPreferences.getE2EOurPublicKey(peerAddress) ?: return false
        val peerPub = zchatPreferences.getE2EPeerPublicKey(peerAddress) ?: return false
        // The same direction rule getOrCreateMessageProcessor gives the ratchet (isLower → direction 0).
        val myDirection: Byte = if (ourPub < peerPub) 0x00 else 0x01
        // The floor our sends to the peer actually read (R2-4 (a)): the one of the ratchet the next send uses.
        // ZC-545, ZC-564: obtained inside the session block; only its floor key (a hash of the root) leaves it.
        val floorKey =
            withPeerSession(peerAddress) { getOrCreateMessageProcessor(peerAddress, sendConvId)?.floorKey }
                ?: return false
        return RestoreKexPolicy.floorSendCounterAboveUnreadOwnEnvelopes(ratchetStateStore, floorKey, myDirection, unread)
    }

    /**
     * Resolve the real peer address for an outgoing transaction.
     *
     * Multi-layered fallback to prevent messages from silently disappearing:
     * 1. tx.recipient?.address (fast path - works when SDK has single/correct recipient)
     * 2. All recipients from SDK, filtering out the platform fee address
     * 3. Conversation ID from memo → peer address lookup in preferences
     * 4. Content-match against pending messages (last resort)
     *
     * Returns null only if ALL strategies fail (should be extremely rare).
     */
    private suspend fun resolveOutgoingPeerAddress(
        tx: Transaction,
        memos: List<String>,
        pendingMsgs: List<ChatMessage>
    ): String? {
        outgoingRecipientFromOutputs(tx)?.let { return it.address }
        return resolveOutgoingPeerAddressByMemo(tx, memos, pendingMsgs)
    }

    /**
     * Strategies 1 and 2 of [resolveOutgoingPeerAddress]: the address an own send pays, read from the outputs that leave
     * this wallet only (FC-ID uses it for an own key exchange, never the lookup by id). Null when none can be read.
     * ZC-1082: the destinations ZC-599 judges an answer against: each text as the wallet names it, and the known address
     * it resolves to when that one vouches (an address only a stranger's claim made known is never added).
     */
    private fun outgoingRecipientsFromOutputs(paidTexts: List<String>): List<String> =
        try {
            paidTexts
                .flatMap { text -> listOf(text) + listOfNotNull(resolveOwnSendText(text).takeIf { it.vouched }?.address) }
                .distinct()
        } catch (e: Exception) {
            if (e is kotlinx.coroutines.CancellationException) throw e
            emptyList()
        }

    /**
     * ZC-757 (k) recheck 6 — the texts an own send's outputs actually paid, fee addresses left out. Round 15 (ZC-1167): null
     * when they cannot be read (was empty, which read as "paid nothing").
     */
    private suspend fun paidTextsFromOutputs(tx: Transaction): List<String>? =
        try {
            transactionRepository
                .getAllRecipientAddresses(tx)
                .filterNot { ZMSGConstants.isPlatformFeeAddress(it) }
                .distinct()
        } catch (e: Exception) {
            if (e is kotlinx.coroutines.CancellationException) throw e
            null
        }

    /**
     * ZC-1082 — one destination of an own send as the pass files it. [vouched] is false for a receiver form (an address
     * with one receiver, as a restored wallet names its sends) that no single known address holds: such a text is kept as
     * it is, and it never vouches for a conversation id (FC-ID) or a key. [asSent] is the text the send named (the form
     * actually paid; ZC-757 (k) recheck 3, [groupRecipientOf]).
     */
    private class OwnSendRecipient(
        val address: String,
        val vouched: Boolean,
        val asSent: String,
    )

    /**
     * ZC-757 (k) recheck 3 finding 2 — the address a row our own group send adds goes under: the address the pass filed
     * [recipient] under when this phone vouches for it or that address answered our own key exchange
     * ([answeredOwnKeyExchange]) that paid the form actually paid (recheck 4 finding 1), else the form actually paid,
     * never a holder known only from a stranger's chat.
     */
    private fun groupRecipientOf(recipient: OwnSendRecipient): String =
        if (recipient.vouched || answeredOwnKeyExchange(recipient.address, listOf(recipient.asSent))) {
            recipient.address
        } else {
            recipient.asSent
        }

    /** ZC-757 (k) recheck 3 — this history pass's own mined key exchanges read so far (the pass's own list). */
    @Volatile private var ownMinedKexInPass: List<OwnMinedKex> = emptyList()

    /** ZC-757 (k) round 9 — an answer a history pass took: its id, the address it claims (resolved), the key it carries. */
    private data class TakenAnswer(
        val convId: String,
        val claimedCanon: String,
        val key: String?,
    )

    /**
     * ZC-1137 — the answers this history pass took by leg 1 or 2 ([takeAskedAnswer]). Round 9 (R1): with the address
     * each claims itself, never the address its id is filed under. An id this phone restored as its own
     * (restoreOwnConversationId) is no answer by itself, and never makes another party's answer count.
     */
    @Volatile private var answersTakenInPass: MutableSet<TakenAnswer> = Collections.synchronizedSet(HashSet())

    /**
     * ZC-757 (k) recheck 3 finding 1 — [address] answered one of our own mined key exchanges of this pass under its id:
     * the id is filed under [address] and the exchange paid a text whose receivers sit within [address]. Only the
     * holder of the paid receiver can read that id (the rule of [judgeAnswer]'s leg 2), so a stranger's address built
     * around another member's receiver never has it. Recheck 4 finding 1: the exchange counts only when a text it paid
     * holds one of [forms] (the receiver forms in question); an answer to an exchange that paid only the stranger's own
     * receiver says nothing about another member's form. Recheck 6: only a text the exchange actually paid counts
     * ([OwnMinedKex.paidTexts], never a holder address added for filing), and only when it equals a form in question or
     * lies inside it; a paid address that merely holds the form among other receivers is no evidence for it. ZC-1137:
     * only when this pass actually took an answer (leg 1 or 2) under the exchange's id from [address]
     * ([answersTakenInPass]); an id mapping alone (an own id restored for [address]) is no answer. Round 9 (R1): the
     * answer's own claimed address must resolve to [address]; an id mapped to [address] never makes another party's
     * answer count for it. Any read that fails answers no.
     */
    private fun answeredOwnKeyExchange(
        address: String,
        forms: Collection<String>,
    ): Boolean = ownKeyExchangeAnswers(address, forms).isNotEmpty()

    /** ZC-757 (k) round 9 — the answers that make [answeredOwnKeyExchange] true for [address] and [forms] (none: false). */
    private fun ownKeyExchangeAnswers(
        address: String,
        forms: Collection<String>,
    ): List<TakenAnswer> =
        runCatching {
            val canon = zchatPreferences.resolvePeerAddress(address)
            val taken = answersTakenInPass.toList()
            ownMinedKexInPass.toList().flatMap { kex ->
                val paidForm =
                    zchatPreferences.getPeerByConversationId(kex.convId) == address &&
                        kex.paidTexts.any { paid ->
                            ZcashReceivers.within(paid, address) && forms.any { ZcashReceivers.within(paid, it) }
                        }
                if (paidForm) taken.filter { it.convId == kex.convId && it.claimedCanon == canon } else emptyList()
            }
        }.getOrDefault(emptyList())

    /**
     * ZC-1082 (N-13) — [text], a destination of an own send that is not a fee address, as the pass files it. After a
     * restore the wallet library names each output by the single receiver its note was paid to; such a form is filed
     * under the ONE address this phone knows (contact book, chats, nicknames; never its own) whose receivers hold it,
     * the form itself counting as one holder when it is known. With none or several it is kept as it is. The result
     * vouches (FC-ID may write an own-id record for it) only for an address this phone vouches for itself
     * ([isVouchedPeer]): an address known only from a stranger's claim may decide the filing, never the trust (review
     * finding 1). Any other text (a full address, an undecodable one) is kept as it is and vouches, as before.
     */
    private fun resolveOwnSendText(text: String): OwnSendRecipient {
        val receivers = ZcashReceivers.of(text)
        if (receivers == null || receivers.size != 1) return OwnSendRecipient(text, vouched = true, asSent = text)
        // ZC-757 (k): a miss is not kept for the rest of the pass. An address this pass has just filed (M1's answer under
        // our own key exchange's id, after the pass's first own send read the list) holds the form, so read again; only
        // when the pass filed a chat since the last read (recheck finding 3), not on every miss.
        val peers = knownPeers()
        val holder =
            formHolder(text, peers)
                ?: if (chatsFiledSince(peers)) formHolder(text, readKnownPeers().also { knownPeersInPass = it }) else null
        return holder?.let { OwnSendRecipient(it, vouched = isVouchedPeer(it), asSent = text) }
            ?: OwnSendRecipient(text, vouched = false, asSent = text)
    }

    /** ZC-1082 — the addresses this phone knows a peer by ([candidates]), and those its contact book holds ([book]). */
    private class KnownPeers(
        val candidates: Set<String>,
        val book: Set<String>,
        val chats: Map<String, String>,
    )

    /**
     * ZC-1082 (review finding 2) — [KnownPeers], read once per history pass (reset at the pass's start); a form no known
     * address holds reads it again (ZC-757 (k)).
     */
    @Volatile private var knownPeersInPass: KnownPeers? = null

    private fun knownPeers(): KnownPeers = knownPeersInPass ?: readKnownPeers().also { knownPeersInPass = it }

    /**
     * ZC-757 (k) recheck finding 3 — the conversation ids were filed or changed since [peers] was read (one read of the id
     * file, not of the contact book). Any read that fails answers no.
     */
    private fun chatsFiledSince(peers: KnownPeers): Boolean =
        runCatching { zchatPreferences.getAllConversationMappings() != peers.chats }.getOrDefault(false)

    /** ZC-1082 — the one address of [peers] whose receivers hold the receiver form [form], or null with none or several. */
    private fun formHolder(
        form: String,
        peers: KnownPeers,
    ): String? = peers.candidates.filter { ZcashReceivers.within(form, it) }.singleOrNull()

    /** ZC-1082 — the addresses this phone knows a peer by: its contact book, its chats and its nicknames, never its own. */
    private fun readKnownPeers(): KnownPeers {
        val book = LinkedHashSet<String>()
        runCatching { contactBook.getAllContacts().forEach { book += it.address } }
        val known = LinkedHashSet<String>(book)
        val chats = runCatching { zchatPreferences.getAllConversationMappings() }.getOrDefault(emptyMap())
        known += chats.values
        runCatching { known += zchatPreferences.getAllPeerToConvIdMappings().keys }
        runCatching { known += zchatPreferences.getAllContactAddresses() }
        val candidates =
            known.filterTo(LinkedHashSet()) {
                it.isNotBlank() && !zchatPreferences.isSelfAddress(it) && !ZMSGConstants.isPlatformFeeAddress(it)
            }
        return KnownPeers(candidates, book.filterTo(LinkedHashSet()) { it in candidates }, chats)
    }

    /**
     * ZC-1082 (review finding 1 and its recheck) — [address] is one this phone vouches for itself: its contact book holds
     * it, or an own-id record names it. A stored contact key is not: a stranger's first key exchange is stored with no
     * claim mark (it waits for Accept instead), and keys stored before ZC-634 carry none. A chat a stranger's claim opened
     * is none of these. Any read that fails answers no.
     */
    private fun isVouchedPeer(address: String): Boolean {
        if (address in knownPeers().book) return true
        return runCatching {
            zchatPreferences.ownConversationId(address) != null ||
                zchatPreferences.getAllConversationMappings().any { (id, peer) ->
                    peer == address && zchatPreferences.isOwnConversationId(id, address)
                }
        }.getOrDefault(false)
    }

    /**
     * ZC-1082 — the recipient of our own group message as the pass files it: the history's [direct] recipient, or, when
     * that is a fee address (a restored send whose fee output came first), the send's own recipient from its outputs.
     */
    private suspend fun ownGroupRecipient(
        tx: Transaction,
        direct: String,
    ): OwnSendRecipient? =
        if (ZMSGConstants.isPlatformFeeAddress(direct)) {
            outgoingRecipientFromOutputs(tx)
        } else {
            resolveOwnSendText(direct)
        }

    /**
     * ZC-1273: the true amount of a payment row, per output. Null for any other row, for a transaction that did not go out, and
     * when the outputs cannot be read.
     */
    private suspend fun paymentRowAmount(
        tx: Transaction,
        isOutgoing: Boolean,
        text: String,
    ): Long? {
        val failed =
            tx is co.electriccoin.zcash.ui.common.repository.SendTransaction.Failed ||
                tx is co.electriccoin.zcash.ui.common.repository.ReceiveTransaction.Failed
        val paymentText =
            co.electriccoin.zcash.ui.screen.chat.model.PaymentBubble
                .isPaymentText(text)
        if (failed || !paymentText) return null
        return transactionRepository.getOutputValues(tx)?.let { outputs ->
            co.electriccoin.zcash.ui.screen.chat.model.PaymentBubble.amountFromOutputs(
                isOutgoing,
                outputs,
                ZMSGConstants::isPlatformFeeAddress,
            )
        }
    }

    private suspend fun outgoingRecipientFromOutputs(tx: Transaction): OwnSendRecipient? {
        // R2-5 (b): the outputs that leave this wallet (SDK 3.0.0 also lists the change back to it), or null
        // when they cannot be read. A platform-fee output (the current address or one an earlier build paid,
        // e.g. every message before 9 Sep) and an output to this wallet never name the peer.
        val externalRecipients =
            try {
                transactionRepository.getAllRecipientAddresses(tx)
            } catch (e: Exception) {
                Log.w("ZCHAT_RESOLVE", "getAllRecipientAddresses failed for tx ${tx.id.txIdString()}: ${e.message}")
                null
            }

        // Strategy 1: Direct recipient from SDK (most common case), when it leaves the wallet
        val directRecipient = (tx as? co.electriccoin.zcash.ui.common.repository.SendTransaction)?.recipient?.address
        if (directRecipient != null &&
            !ZMSGConstants.isPlatformFeeAddress(directRecipient) &&
            (externalRecipients == null || directRecipient in externalRecipients)
        ) {
            return resolveOwnSendText(directRecipient)
        }

        // Strategy 2: ALL recipients that leave the wallet, minus every platform fee address
        val nonFeeRecipient = externalRecipients?.firstOrNull { !ZMSGConstants.isPlatformFeeAddress(it) }
        if (nonFeeRecipient != null) {
            Log.d("ZCHAT_RESOLVE", "Resolved via all-recipients for tx ${tx.id.txIdString()}: ${nonFeeRecipient.redactAddress()}")
            return resolveOwnSendText(nonFeeRecipient)
        }
        return null
    }

    /** Strategies 3 and 4 of [resolveOutgoingPeerAddress]. */
    private suspend fun resolveOutgoingPeerAddressByMemo(
        tx: Transaction,
        memos: List<String>,
        pendingMsgs: List<ChatMessage>,
    ): String? {
        // Strategy 3: Extract convId from memo → look up peer address
        val memoText = memos.joinToString("\n").trim()
        val convId = extractConvIdFromMemo(memoText)
        if (convId != null) {
            val peerFromConvId = zchatPreferences.getPeerByConversationId(convId)
            if (peerFromConvId != null) {
                Log.d("ZCHAT_RESOLVE", "Resolved via convId for tx ${tx.id.txIdString()}: ${peerFromConvId.redactAddress()}")
                return peerFromConvId
            }
        }

        // Strategy 4: Match against pending messages by content + uniqueness constraint
        // Only use this fallback if exactly ONE pending message matches (avoids misrouting
        // when multiple conversations have identical message content like "hi")
        val displayText = try {
            val hasChunked = memos.any { ZMSGProtocol.isChunkedMemo(it) }
            if (hasChunked) {
                ZMSGProtocol.reassembleChunks(memos, addressCache)?.message
                    ?: extractMessageContent(memoText)
            } else {
                extractMessageContent(memoText)
            }
        } catch (e: Exception) { null }

        if (displayText != null) {
            val contentHash = displayText.toByteArray().let { bytes ->
                java.security.MessageDigest.getInstance("SHA-256")
                    .digest(bytes)
                    .take(16)
                    .joinToString("") { "%02x".format(it) }
            }
            val allMatching = pendingMsgs.filter { pending ->
                val pendingHash = pending.text.toByteArray().let { bytes ->
                    java.security.MessageDigest.getInstance("SHA-256")
                        .digest(bytes)
                        .take(16)
                        .joinToString("") { "%02x".format(it) }
                }
                pendingHash == contentHash
            }
            if (allMatching.size == 1) {
                // Unique match - safe to use
                Log.d("ZCHAT_RESOLVE", "Resolved via unique pending match for tx ${tx.id.txIdString()}: ${allMatching[0].peerAddress.redactAddress()}")
                return allMatching[0].peerAddress
            } else if (allMatching.size > 1) {
                // Ambiguous: multiple pending messages with same content across different peers
                // Check if they all point to the same peer (still safe)
                val distinctPeers = allMatching.map { it.peerAddress }.distinct()
                if (distinctPeers.size == 1) {
                    Log.d("ZCHAT_RESOLVE", "Resolved via pending match (${allMatching.size} matches, same peer): ${distinctPeers[0].redactAddress()}")
                    return distinctPeers[0]
                }
                Log.w("ZCHAT_RESOLVE", "AMBIGUOUS pending match for tx ${tx.id.txIdString()}: ${allMatching.size} matches across ${distinctPeers.size} peers, skipping")
            }
        }

        // All strategies exhausted
        val directRecipient = (tx as? co.electriccoin.zcash.ui.common.repository.SendTransaction)?.recipient?.address
        Log.e("ZCHAT_RESOLVE", "FAILED to resolve peer for outgoing tx ${tx.id.txIdString()}, " +
            "directRecipient=${directRecipient?.redactAddress()}, memoLen=${memoText.length}, convId=$convId")
        return null
    }

    /**
     * [conversation] with what the chat list and the chat screen show next to its messages: the peer's status, the
     * [draft], the E2E state, mute, unread (after [lastRead], up to [nowMs]) and the call channel. Round 8 P4: shared
     * by the list and by [emptyConversationFor], so a hidden chat opened from New Chat shows the same state.
     */
    private fun withLiveStatus(
        conversation: Conversation,
        draft: String?,
        lastRead: Long,
        nowMs: Long,
    ): Conversation {
        val peerStatus = peerStatuses.value[conversation.peerAddress]
        val e2eEnabled = zchatPreferences.isE2EEnabled(conversation.peerAddress)
        val e2eKeyExchangeComplete = zchatPreferences.isE2EKeyExchangeComplete(conversation.peerAddress)
        // #257 tri-state honesty: is OUR KEXACK settled with the peer? (legacy peers = yes)
        val e2ePeer = conversation.peerAddress
        val receivedKex = zchatPreferences.getReceivedKexPubkey(e2ePeer)
        val settlement =
            co.electriccoin.zcash.ui.screen.chat.model.E2EAckSettlement.settle(
                receivedKex,
                zchatPreferences.getSentKexAckPubkey(e2ePeer),
                zchatPreferences.getPeerNostrPubkey(e2ePeer),
                zchatPreferences.isE2EKeyChanged(e2ePeer),
            )
        // Adversarial-review fix: SETTLED_BACKFILL is DISPLAY-ONLY (peerNostrPubkey is set on
        // many paths BEFORE our ack lands — QR paste, a re-KEX's piggybacked pubkey, and B6's
        // reset preserves it). Do NOT durably stamp setSentKexAckPubkey here: during the
        // KEXACK-send window after a Reset that write would falsely record "ack sent" (lying
        // "On") and permanently block retryKexAckIfResponder after dismissE2EKeyChanged. The
        // settlement result below still renders the honest state without mutating handshake state.
        val e2eKexInFlight =
            !e2eKeyExchangeComplete &&
                zchatPreferences.getE2EOurPublicKey(e2ePeer) != null &&
                zchatPreferences.isOwnBootSent(e2ePeer)
        // Unread = PAST incoming chat messages newer than this conversation's last-read
        // marker. Bounding to <= now (not just > lastRead) keeps a future-dated message
        // (peer clock skew / not-yet-"arrived") from sticking the badge above the read
        // marker forever — it only counts once the wall clock actually reaches it.
        // Call-log and AI rows are local-only system entries, not unread mail.
        val unreadCount =
            conversation.messages.count {
                !it.isOutgoing &&
                    !it.isCallLog &&
                    !it.isAiMessage &&
                    !it.isSystemNote &&
                    it.timestamp.toEpochMilli() in (lastRead + 1)..nowMs
            }
        return conversation.copy(
            peerStatus = peerStatus,
            draft = draft,
            e2eEnabled = e2eEnabled,
            e2eKeyExchangeComplete = e2eKeyExchangeComplete,
            e2eAckSettled = settlement != co.electriccoin.zcash.ui.screen.chat.model.Settlement.PENDING,
            e2eKexInFlight = e2eKexInFlight,
            isMuted = zchatPreferences.isConversationMuted(conversation.peerAddress),
            unreadCount = unreadCount,
            // Calls route over the peer's NOSTR identity (free relay), not the message
            // transport — so they're placeable whenever we hold the peer's NOSTR pubkey,
            // even in a VAULT chat. Mirrors startCall's own peerPub != null gate.
            hasNostrCallChannel = zchatPreferences.getPeerNostrPubkey(conversation.peerAddress) != null,
            // Round 8 D9 (DECISIONS_NIGHT §3): the ⋮ menu's encryption row follows the send path.
            appLayerE2EPending = appLayerE2EPending(conversation.peerAddress),
            // W-72 (SPEC_F R8): re-read at every redraw (the handshake tick the mark's release bumps is one of its triggers).
            keyNotConfirmed = zchatPreferences.getLegacyKeyMark(conversation.peerAddress) != null,
        )
    }

    /**
     * Round 8 P4 (F6): the chat of a contact that already has one but has no visible messages (the user hid the
     * chat), empty, with its draft and its live E2E state. New Chat hands such a contact to its chat instead of
     * sending outside the ratchet; without this the chat screen showed "Conversation not found" and the contact
     * could not be written to at all. Null for an address with no chat, so no ghost chat is ever opened.
     */
    fun emptyConversationFor(peerAddress: String): Conversation? {
        if (!zchatPreferences.hasExistingChat(peerAddress)) return null
        val contactName = zchatPreferences.getNickname(peerAddress) ?: contactBook.getContact(peerAddress)?.name
        return withLiveStatus(
            conversation =
                Conversation(
                    peerAddress = peerAddress,
                    messages = emptyList(),
                    lastMessage = null,
                    contactName = contactName,
                ),
            draft = zchatPreferences.getDraft(peerAddress),
            lastRead = 0L,
            nowMs = System.currentTimeMillis(),
        )
    }

    fun getConversation(peerAddress: String): Conversation? {
        return when (val state = _chatListState.value) {
            is ChatListState.Success -> state.conversations.find { it.peerAddress == peerAddress }
            else -> null
        }
    }

    // ==========================================
    // DRAFT MESSAGE FUNCTIONS
    // ==========================================

    /**
     * Get the draft for a peer address.
     */
    fun getDraft(peerAddress: String): String? {
        return zchatPreferences.getDraft(peerAddress)
    }

    /**
     * Save a draft for a peer address.
     * Called when message text changes in the chat detail view, and with a text shared in from another app.
     * The draft is capped like typed text (SHARED-TEXT-CAP): a share used to be stored whole and became a
     * message of hundreds of paid memo outputs on one tap.
     */
    fun saveDraft(peerAddress: String, draft: String) {
        zchatPreferences.setDraft(peerAddress, capDraft(draft))
    }

    /**
     * Clear the draft for a peer address.
     * Called when a message is successfully sent.
     */
    fun clearDraft(peerAddress: String) {
        zchatPreferences.clearDraft(peerAddress)
    }

    // ==========================================
    // E2E ENCRYPTION FUNCTIONS
    // ==========================================

    /**
     * Check if E2E encryption is enabled for a peer.
     */
    fun isE2EEnabled(peerAddress: String): Boolean {
        return zchatPreferences.isE2EEnabled(peerAddress)
    }

    /**
     * Enable or disable E2E encryption for a peer.
     * When enabling:
     * - Generates keys if not already present
     * - Sends KEX (Key Exchange) message to peer
     * New keys use HKDF (V2) for key derivation.
     */
    /**
     * Toggle mute/unmute for a conversation.
     * When muted, no notifications will be shown for messages from this peer.
     */
    fun toggleMuteConversation(peerAddress: String) {
        if (zchatPreferences.isConversationMuted(peerAddress)) {
            zchatPreferences.unmuteConversation(peerAddress)
        } else {
            zchatPreferences.muteConversation(peerAddress)
        }
        // Trigger conversation list refresh
        refresh()
    }

    /**
     * Mark a conversation read up to now. Persists the last-read marker and updates the reactive
     * [readMarkers] map so the conversation list re-emits and the unread badge clears immediately.
     * Called when the user opens the conversation. Cheap: no SDK refresh.
     */
    fun markConversationRead(peerAddress: String) {
        // Mark read up to max(now, latest-message-time). Using ONLY the latest message timestamp is
        // fragile: this runs from a Compose LaunchedEffect that may fire before the newest message
        // has propagated into _chatListState, so the snapshot max can lag the real latest message and
        // leave it perpetually unread. now() is immune to that (every incoming timestamp is clamped to
        // <= now at receive, so "read up to now" clears all currently-visible mail), and the
        // message-max term still covers any outgoing/future-dated row beyond now. setLastReadTimestamp
        // is monotonic, so a genuinely newer message that arrives later still re-badges.
        val latestMsgMillis = (_chatListState.value as? ChatListState.Success)
            ?.conversations
            ?.firstOrNull { it.peerAddress == peerAddress }
            ?.messages
            ?.maxOfOrNull { it.timestamp.toEpochMilli() }
            ?: 0L
        val readUpTo = maxOf(System.currentTimeMillis(), latestMsgMillis)
        // setLastReadTimestamp is monotonic AND emits to the shared readMarkers flow, so EVERY
        // ChatViewModel instance (notably the chat-list one) recomputes unread off the new value —
        // no per-instance update needed (#226).
        zchatPreferences.setLastReadTimestamp(peerAddress, readUpTo)
    }

    fun setE2EEnabled(peerAddress: String, enabled: Boolean) {
        // ZC-893 (FC-2B, 5.4b item 6): a key this phone never asked for goes before our own start makes our key pair
        // (its removal turns E2E off; the switch below turns it on again).
        if (enabled && zchatPreferences.getE2EOurPublicKey(peerAddress) == null) dropUnaskedKeyBeforeOwnStart(peerAddress)
        zchatPreferences.setE2EEnabled(peerAddress, enabled)
        if (enabled) {
            userStartsSetupAgain(peerAddress)
            // Launched because seed-derived key generation is suspend (seed access via
            // PersistableWalletProvider); the KEX send stays ORDERED after the key exists.
            viewModelScope.launch {
                // Generate our key pair if not already present (D1-recovery Stage 3a: seed-derived,
                // provenance-marked; NEVER overwrites an existing key — provider re-checks under lock).
                // P2d (1): no key while a restored wallet has not read its history yet (see sendKEXMessage).
                if (zchatPreferences.getE2EOurPublicKey(peerAddress) == null &&
                    seedKeyProvider.getOrCreateKeyPairForSend(peerAddress) == null
                ) {
                    _sendMessageState.value = SendMessageState.Error(RESTORE_HISTORY_NOT_READ)
                    return@launch
                }

                // Send KEX message to initiate key exchange
                val ourAddress = _currentUserAddress.value
                if (ourAddress != null) {
                    // FC-ID (5.3a item 4): a lone key exchange goes out under an id this phone made for this address.
                    planOwnConversationId(peerAddress)
                    sendKEXMessage(peerAddress, ourAddress)
                } else {
                    Log.w("ChatViewModel", "Cannot send KEX - user address not available yet")
                }
            }
        }
    }

    /**
     * Get our public key for E2E encryption (to send to peer).
     */
    fun getE2EOurPublicKey(peerAddress: String): String? {
        return zchatPreferences.getE2EOurPublicKey(peerAddress)
    }

    /**
     * Round 8 D9 (DECISIONS_NIGHT §3) — true while a message to [peerAddress] goes out without ZChat's own end-to-end
     * layer: a Shielded chat with no ratchet and E2E off (the contact has not answered the key exchange). The text is
     * then inside the Zcash shielded memo only. The ONE predicate for this: doSendMessage and sendReply choose their
     * plaintext branch with it (passing [hasRatchet] = whether they got a ratchet processor), and the chat list
     * hydrates Conversation.appLayerE2EPending with it for the ⋮ menu (by default [hasRatchet] is whether both keys a
     * ratchet is built from are held; the send path builds one, and turns E2E on, whenever they are).
     */
    @JvmOverloads
    fun appLayerE2EPending(
        peerAddress: String,
        hasRatchet: Boolean = holdsRatchetKeys(peerAddress),
    ): Boolean =
        zchatPreferences.getConversationMode(peerAddress) ==
            co.electriccoin.zcash.ui.screen.chat.model.ConversationMode.VAULT &&
            !hasRatchet &&
            !zchatPreferences.isE2EEnabled(peerAddress)

    /** Whether we hold both keys a ratchet for [peerAddress] is derived from (see getOrCreateMessageProcessorUngated). */
    private fun holdsRatchetKeys(peerAddress: String): Boolean =
        zchatPreferences.getE2EOurPublicKey(peerAddress) != null &&
            zchatPreferences.getE2EPeerPublicKey(peerAddress) != null

    /**
     * Round 8 D9 (DECISIONS_NIGHT §3) — after a message went out on the [appLayerE2EPending] branch: the first time in
     * this chat, one system note says the message has Zcash's shielded encryption only and that ZChat adds its own once
     * the contact answers the key exchange. One stable id per peer (SysNotes.zcashOnlyNoteId); a later send finds it
     * and writes nothing. Protocol control memos (ZBOOT, KEX, KEXACK) are not the user's messages and write none.
     */
    private fun noteFirstZcashOnlyMessage(
        peerAddress: String,
        message: String,
    ) {
        if (co.electriccoin.zcash.ui.screen.chat.model.ZBootMessage
                .isBootMessage(message) ||
            ZMSGProtocol.isKEXMessage(message) ||
            ZMSGProtocol.isKEXAckMessage(message)
        ) {
            return
        }
        val id =
            co.electriccoin.zcash.ui.screen.chat.model.SysNotes
                .zcashOnlyNoteId(peerAddress)
        if (zchatPreferences.getPendingMessages().any { it.id == id }) return
        emitSystemNote(
            peerAddress,
            id,
            noteCopy.get(R.string.chat_note_first_message_zcash_only, peerLabel(peerAddress)),
        )
    }

    /**
     * Check if E2E key exchange is complete.
     */
    fun isE2EKeyExchangeComplete(peerAddress: String): Boolean {
        return zchatPreferences.isE2EKeyExchangeComplete(peerAddress)
    }

    /**
     * Derive the shared encryption key for a peer.
     * Uses the stored key version (V1 for legacy, V2 for HKDF).
     * @return The derived shared key, or null if key exchange is not complete.
     */
    fun getE2ESharedKey(peerAddress: String): ByteArray? {
        val ourPrivateKey = zchatPreferences.getE2EPrivateKey(peerAddress) ?: return null
        val peerPublicKey = zchatPreferences.getE2EPeerPublicKey(peerAddress) ?: return null
        val keyVersionInt = zchatPreferences.getE2EKeyVersion(peerAddress)
        val keyVersion = E2EKeyVersion.fromValue(keyVersionInt)

        return try {
            E2EEncryption.deriveSharedSecret(ourPrivateKey, peerPublicKey, keyVersion)
        } catch (e: Exception) {
            Log.e("ChatViewModel", "Failed to derive shared key for ${peerAddress.redactAddress()}", e)
            null
        }
    }

    /**
     * Get the E2E key derivation version for a peer.
     * @return Key version (1 = legacy SHA-256, 2 = HKDF)
     */
    fun getE2EKeyVersion(peerAddress: String): E2EKeyVersion {
        return E2EKeyVersion.fromValue(zchatPreferences.getE2EKeyVersion(peerAddress))
    }

    /** True if the peer's E2E public key has changed since last acknowledged by the user. */
    fun isE2EKeyChanged(peerAddress: String): Boolean =
        zchatPreferences.isE2EKeyChanged(peerAddress)

    /**
     * User dismissed the key-changed banner — clear the flag.
     *
     * In a Shielded chat this is free: the flag (and ZC-250's refusal notice) is cleared at once. In a Tunnel or Open chat
     * it re-sends our KEX and then our ZBOOT (R2-2 (b)), so the reconnect's price (KEY_CHANGE_RECONNECT) is asked first
     * and the banner stays until the user confirms.
     *
     * ZC-300 (fix-all 2.13.0): that confirm is the consent for exactly what it quoted, our KEX and our ZBOOT, and for
     * nothing else: the standing "Allow handshake transactions" consent is neither asked, read for them nor written. The
     * confirmed reconnect runs on the process-wide send scope ([processSendScope]), so leaving the chat never cancels it
     * between the dropped relay key and its KEX. With a Keystone account selected nothing changes and the Keystone text is
     * shown. Before the flag clears and the relay key drops it records the KEX as owed (the mark, the confirming account
     * and the reason [ZchatPreferences.KEX_OWED_REASON_RECONNECT]) and the ZBOOT allowance; if the store does not confirm
     * any of those writes, nothing changes, nothing is sent and the user is told ([ChatSendCopy.STORAGE_PAUSED_PAID_STEP]).
     * The KEX is then paid at once through [payOwedKex]; when it cannot go now it stays owed and a later block or chat
     * open pays it, once, at the price confirmed here, with no second question. Our ZBOOT goes over the relays first and
     * on-chain at most once, against the allowance written here, which it uses up.
     *
     * ZC-535 (WAIVERS.md W-31, option A): the reconnect really sends its key exchange. The contact's stored key is
     * the old one, so the exchange reading as complete no longer settles the reconnect's KEX as delivered
     * ([kexSettlesUnpaid]); and because a contact that already acked our key sends no KEXACK, the reconnect itself fires
     * our ZBOOT once its KEX is out ([fireReconnectZbootIfDue]); with an incomplete exchange the contact's KEXACK stays the
     * trigger. The question counts exactly the messages that are due ([reconnectPlan]): whichever of the two went out in
     * the last hour is neither quoted nor sent again, and with nothing due the × is a free accept (the flag and the
     * refusal cleared, the relay key dropped, nothing recorded, owed or paid). Pay reads the plan again: if it now costs
     * more than the question quoted, it asks again with the new count and pays nothing until that answer; otherwise it
     * pays only the messages due, never more than quoted. One reconnect per contact runs at a time
     * ([reconnectsInFlight]). A contact known to be on ZChat 2.12.4 or older gets one more sentence in the question
     * ([PaidActionConfirmation.contactIsOlder]); the quote is the same. A changed E2E key is still not adopted here.
     *
     * [costConfirmed] = true without a question shown stands for the full quote of [RECONNECT_FULL_QUOTE] messages.
     */
    fun dismissE2EKeyChanged(peerAddress: String, costConfirmed: Boolean = false) {
        // ZC-545 (R2): while a refused key is remembered the decision is made in its own dialog ([acceptRefusedKey],
        // [dismissRefusedKeyOffer]); this legacy accept changes nothing then, in any mode, and points to the warning.
        if (refusedKeyWaits(peerAddress)) {
            _sendMessageState.value = SendMessageState.Error(ChatSendCopy.KEY_CHANGED_VERIFY)
            return
        }
        if (zchatPreferences.getConversationMode(peerAddress) != co.electriccoin.zcash.ui.screen.chat.model.ConversationMode.VAULT) {
            if (costConfirmed) {
                confirmKeyChangeReconnect(peerAddress, quoted = RECONNECT_FULL_QUOTE)
                return
            }
            // ZC-535: the question counts the messages that are due now. Reading the plan pays and writes nothing.
            viewModelScope.launch {
                val plan =
                    try {
                        reconnectPlan(peerAddress)
                    } catch (e: Exception) {
                        if (e is kotlinx.coroutines.CancellationException) throw e
                        // Not read: quote both, the most a reconnect can pay; Pay reads the plan again.
                        Log.w("KEX", "Key-change reconnect plan not read: ${e.javaClass.simpleName}")
                        ReconnectPlan(kex = true, zboot = true)
                    }
                if (plan.count == 0) {
                    // Both went out in the last hour: nothing to pay, so nothing to ask.
                    confirmKeyChangeReconnect(peerAddress, quoted = 0)
                } else {
                    askKeyChangeReconnectPrice(peerAddress, plan)
                }
            }
            return
        }
        zchatPreferences.setE2EKeyChanged(peerAddress, false)
        clearKeyChangeRefusal(peerAddress)
        // ZC-739: the decision starts what waited for it.
        resumeAfterKeyDecision(peerAddress)
    }

    /**
     * ZC-535 — the reconnect's price question for [plan]: its count, and one more sentence for an older contact.
     * ZC-545: for the accept of a remembered key ([accepted]) in a Shielded chat the question is
     * [PaidAction.KEY_CHANGE_ACCEPT] (our key exchange alone); in a Tunnel or Open chat it is the reconnect's.
     */
    private fun askKeyChangeReconnectPrice(
        peerAddress: String,
        plan: ReconnectPlan,
        accepted: AcceptedKeyOffer? = null,
    ) {
        val shieldedAccept =
            accepted != null &&
                zchatPreferences.getConversationMode(peerAddress) == co.electriccoin.zcash.ui.screen.chat.model.ConversationMode.VAULT
        val action = if (shieldedAccept) PaidAction.KEY_CHANGE_ACCEPT else PaidAction.KEY_CHANGE_RECONNECT
        val confirmation =
            paidActionConfirmation(action, plan.count)
                .copy(contactIsOlder = isLegacyContact(peerAddress))
        askBeforePaying(confirmation) { confirmKeyChangeReconnect(peerAddress, quoted = plan.count, accepted = accepted) }
    }

    /**
     * ZC-300, ZC-535 — run the reconnect the user confirmed at a price of [quoted] on-chain messages (0: the free
     * accept). On the process-wide scope, not this screen's, so leaving the chat never cancels it between the dropped
     * relay key and its KEX. One per contact at a time: a second confirm while the first runs does nothing, so it can
     * never write a second allowance after the first one's ZBOOT used its own up.
     *
     * ZC-545: with [accepted] it is the accept of a remembered key, under the same claim.
     */
    private fun confirmKeyChangeReconnect(
        peerAddress: String,
        quoted: Int,
        accepted: AcceptedKeyOffer? = null,
    ) {
        processSendScope().launch(Dispatchers.Main.immediate) {
            if (!reconnectsInFlight.add(peerAddress)) {
                Log.d("KEX", "Key-change reconnect with ${peerAddress.redactAddress()} already running — not started twice")
                return@launch
            }
            try {
                reconnectAndPayOwedKex(peerAddress, quoted, accepted)
                // ZC-1272: the user read and accepted a price (a free accept quotes 0 and asks nothing).
                if (quoted > 0) zchatPreferences.setAcknowledgedMessageCost()
            } catch (e: Exception) {
                if (e is kotlinx.coroutines.CancellationException) throw e
                Log.w("KEX", "Key-change reconnect failed: ${e.javaClass.simpleName}")
            } finally {
                reconnectsInFlight.remove(peerAddress)
            }
        }
    }

    /**
     * ZC-300 — the confirmed key-change reconnect of [dismissE2EKeyChanged] (a Tunnel or Open chat): Keystone check, the
     * owed KEX and the ZBOOT allowance recorded (each write confirmed), the flag cleared and the relay key dropped, then
     * the KEX paid on the reconnect's own confirm.
     *
     * ZC-535: the plan is read again here, before anything is written. A plan above [quoted] asks again and changes
     * nothing; otherwise only the legs due are recorded and paid. With no KEX leg nothing is owed and our ZBOOT is fired
     * directly; with no ZBOOT leg no allowance is written; with neither nothing is recorded or paid at all.
     *
     * ZC-545: with [accepted] (the accept of a remembered key) the remembered key and our own key are checked again
     * before the plan, and where the reconnect clears the flag and drops the relay key the accept runs its own sequence
     * ([adoptRefusedKey]); the relay identity is kept, as Reset keeps it. With no [accepted] while a key is remembered
     * nothing changes (R2: never the legacy path).
     */
    private suspend fun reconnectAndPayOwedKex(
        peerAddress: String,
        quoted: Int,
        accepted: AcceptedKeyOffer? = null,
    ) {
        // T1b-1 §2: no KEX under a Keystone account (ZC-102). Nothing changes; the banner stays.
        if (keystoneAccountSelected()) {
            _sendMessageState.value = SendMessageState.Error(ChatSendCopy.KEYSTONE_AUTOMATIC_SETUP)
            return
        }
        if (accepted == null && refusedKeyWaits(peerAddress)) {
            _sendMessageState.value = SendMessageState.Error(ChatSendCopy.KEY_CHANGED_VERIFY)
            return
        }
        // ZC-624: the warning this reconnect was confirmed for is already gone (the contact's verified relay identity took
        // it down while the question was open). Nothing is written, dropped or paid; the fresh relay key stays bound.
        if (accepted == null && !zchatPreferences.isE2EKeyChanged(peerAddress)) {
            Log.d("KEX", "Key-change reconnect with ${peerAddress.redactAddress()} not needed any more — nothing changed")
            _sendMessageState.value = SendMessageState.Success(ChatSendCopy.KEY_CHANGE_RECONNECT_NOT_NEEDED)
            return
        }
        val offer =
            if (accepted == null) {
                null
            } else {
                // R2, R10: the confirm applies the test of the tap again.
                rememberedOfferFor(peerAddress, accepted) ?: run {
                    _sendMessageState.value = SendMessageState.Error(ChatSendCopy.KEY_CHANGE_CHANGED_AGAIN)
                    return
                }
            }
        val plan = reconnectPlan(peerAddress, offer)
        if (plan.count > quoted) {
            // The hour of a leg ended while the question was open: never pay more than quoted, ask the new price.
            askKeyChangeReconnectPrice(peerAddress, plan, accepted)
            return
        }
        if (accepted != null) {
            adoptRefusedKey(peerAddress, accepted, plan)
            return
        }
        if (plan.count > 0 &&
            !recordQuotedOwedKex(
                peerAddress,
                ZchatPreferences.KEX_OWED_REASON_RECONNECT,
                kexLeg = plan.kex,
                zbootLeg = plan.zboot,
            )
        ) {
            _sendMessageState.value = SendMessageState.Error(ChatSendCopy.STORAGE_PAUSED_PAID_STEP)
            return
        }
        zchatPreferences.setE2EKeyChanged(peerAddress, false)
        clearKeyChangeRefusal(peerAddress)
        // The user has now verified this change out-of-band (e.g. the peer rotated their NOSTR key —
        // #178 Part B). Clear the stale stored peer NOSTR pubkey so the NEXT signed KEX carrying the
        // peer's new key is ACCEPTED by applyKEXNostr (which otherwise refuses to overwrite a still-
        // stored differing key). Acceptance stays gated on this explicit user verification — it does NOT
        // auto-accept key changes. Then re-KEX so both sides converge on the new keys.
        zchatPreferences.setPeerNostrPubkey(peerAddress, null)
        if (plan.kex) {
            kexOwedPeers.add(peerAddress)
            // Its SENT branch fires our ZBOOT ([fireReconnectZbootIfDue]), now or after a later block pays the KEX.
            payQuotedOwedKex(peerAddress, "Reconnect")
        } else if (plan.zboot) {
            // The KEX went out in the last hour: only our relay identity is due.
            fireReconnectZbootIfDue(peerAddress)
        }
        finishOpenReconnect(peerAddress, plan)
        // ZC-739: then the free work that waited for the decision (its own quoted legs above are the only payments).
        resumeAfterKeyDecision(peerAddress, paidLegs = false)
    }

    /** ZC-880 (T11): explain only a remaining paid leg, after giving relay-only delivery its chance. */
    private suspend fun finishOpenReconnect(peerAddress: String, plan: ReconnectPlan) {
        if (plan.openKexSkipped) {
            _sendMessageState.value = SendMessageState.Success(ChatSendCopy.OPEN_NO_ONCHAIN_STEP)
        }
        if (!plan.openZbootSkipped) return
        if (zchatPreferences.getPeerNostrPubkey(peerAddress) == null) {
            _sendMessageState.value = SendMessageState.Success(ChatSendCopy.OPEN_NO_ONCHAIN_STEP)
            return
        }
        val delivered = CompletableDeferred<MemoSendOutcome>()
        val job = sendNostrBootHandshake(peerAddress, ZbootOnChainRule.RELAY_ONLY, result = delivered)
        if (job == null) {
            Log.d("ZCHAT_NOSTR", "Open reconnect identity delivery already in flight; no result claimed")
            return
        }
        if (plan.openKexSkipped) return
        job.join()
        if (!delivered.isCompleted || delivered.await() != MemoSendOutcome.SENT) {
            _sendMessageState.value = SendMessageState.Success(ChatSendCopy.OPEN_NO_ONCHAIN_STEP)
        }
    }

    /**
     * ZC-545 (R10) — the pair of keys an accept is bound to: the contact's refused key and OUR public key, the two
     * strings the safety number in the dialog was computed from. Compared as whole strings.
     */
    private data class AcceptedKeyOffer(
        val refusedKey: String,
        val ourKey: String,
    )

    /**
     * ZC-545 — what the key-changed dialog shows while a refused key of [peerAddress] is remembered, or null when none
     * is (the banner and its × are then ZC-535's). The dialog keeps this snapshot and passes its refusedKey and ourKey
     * back to [acceptRefusedKey].
     */
    fun refusedKeyOffer(peerAddress: String): co.electriccoin.zcash.ui.screen.chat.model.RefusedKeyOfferView? {
        if (!refusedKeyWaits(peerAddress)) return null
        val offer = zchatPreferences.getRefusedKeyOffer(peerAddress) ?: return null
        val ourKey = zchatPreferences.getE2EOurPublicKey(peerAddress) ?: return null
        val number = safetyNumberOf(ourKey, offer.publicKey) ?: return null
        val storedKey = zchatPreferences.getE2EPeerPublicKey(peerAddress)
        return co.electriccoin.zcash.ui.screen.chat.model.RefusedKeyOfferView(
            ourKey = ourKey,
            refusedKey = offer.publicKey,
            safetyNumber = number,
            firstSeenMs = offer.firstSeenMs,
            laterOffers = offer.laterOffers,
            fromKexAck = ZMSGProtocol.isKEXAckMessage(offer.memo),
            contactIsOlder = isLegacyContact(peerAddress),
            // False after an interrupted accept: the old key is gone (none stored, or the remembered key already is).
            oldKeyStored = storedKey != null && storedKey != offer.publicKey,
        )
    }

    /**
     * ZC-545 (WAIVERS.md W-32) — the user tapped "Accept this key" in the dialog that showed the safety number of
     * ([ourKey], [refusedKey]). The app adopts the contact's new key: never silently, only that key, only with our key
     * unchanged.
     *
     * 1. Peek: the remembered key equals [refusedKey] and our key equals [ourKey], as whole strings, and the remembered
     *    memo still verifies as that key from this contact; otherwise nothing changes
     *    ([ChatSendCopy.KEY_CHANGE_CHANGED_AGAIN]) and the legacy reconnect is never entered.
     * 2. Quote ([reconnectPlan]): in a Tunnel or Open chat ZC-535's reconnect (0, 1 or 2 on-chain messages); in a
     *    Shielded chat our key exchange alone when the key came in a KEX and no KEX of ours went out in the last hour,
     *    else nothing. A count above 0 asks first; Pay reads the plan again and never pays above the quote.
     * 3. The confirmed accept runs on the process-wide send scope under the one-reconnect-per-contact claim
     *    ([confirmKeyChangeReconnect], [adoptRefusedKey]). With a Keystone account selected nothing changes.
     */
    fun acceptRefusedKey(
        peerAddress: String,
        refusedKey: String,
        ourKey: String,
    ) {
        val accepted = AcceptedKeyOffer(refusedKey, ourKey)
        viewModelScope.launch {
            val offer = rememberedOfferFor(peerAddress, accepted)
            if (offer == null) {
                _sendMessageState.value = SendMessageState.Error(ChatSendCopy.KEY_CHANGE_CHANGED_AGAIN)
                return@launch
            }
            val plan =
                try {
                    reconnectPlan(peerAddress, offer)
                } catch (e: Exception) {
                    if (e is kotlinx.coroutines.CancellationException) throw e
                    // Not read: quote the most this accept can pay; Pay reads the plan again.
                    Log.w("KEX", "Key accept plan not read: ${e.javaClass.simpleName}")
                    val shielded =
                        zchatPreferences.getConversationMode(peerAddress) ==
                            co.electriccoin.zcash.ui.screen.chat.model.ConversationMode.VAULT
                    ReconnectPlan(kex = !shielded || !ZMSGProtocol.isKEXAckMessage(offer.memo), zboot = !shielded)
                }
            if (plan.count == 0) {
                confirmKeyChangeReconnect(peerAddress, quoted = 0, accepted = accepted)
            } else {
                askKeyChangeReconnectPrice(peerAddress, plan, accepted)
            }
        }
    }

    /**
     * ZC-545 (R2, R10) — the remembered offer an accept of [accepted] may adopt, or null: a record exists, its key
     * equals the accepted key and our stored key equals the accepted own key (whole strings, no digest or prefix), and
     * its memo still verifies as that key from [peerAddress] (a read-only [adoptKeyOffer]). Reads only.
     */
    private fun rememberedOfferFor(
        peerAddress: String,
        accepted: AcceptedKeyOffer,
    ): ZchatPreferences.RefusedKeyOffer? {
        val offer = zchatPreferences.getRefusedKeyOffer(peerAddress) ?: return null
        if (offer.publicKey != accepted.refusedKey) return null
        if (zchatPreferences.getE2EOurPublicKey(peerAddress) != accepted.ourKey) return null
        val resolved =
            adoptKeyOffer(offer.memo, offer.txId, peerAddress, accepted.refusedKey, KeyOfferMode.DRY_RUN)
                as? KeyOfferOutcome.Resolved ?: return null
        return if (resolved.peer == peerAddress && resolved.key == accepted.refusedKey) offer else null
    }

    /**
     * ZC-545 (R4, R5, R6, R9; spec sequence step 4 and 5) — the confirmed accept: Reset encryption's wipe for this contact
     * with our own key pair kept, then the first-contact adoption of the remembered memo, then the record and the flag
     * removed as the LAST write, all inside the contact's session lock; then, outside it, the payment [plan] quoted.
     *
     * Inside the lock, in this order:
     * a. the test of the tap again, before anything changes (our key can only change through a Reset, which holds this
     *    lock);
     * b. the record saved again unchanged (a confirmed write: a store that cannot save stops here, nothing changed)
     *    and, when a leg is due, the owed KEX and the ZBOOT allowance ([recordQuotedOwedKex]);
     * c. the ratchet wipe ([wipeRatchetState]);
     * d. one section under [peerKeyMonitor] with no suspension: the preference wipe ([wipeSessionPrefs], our key pair, the
     *    flag and the record kept), the adoption ([adoptKeyOffer], the only writer allowed while a record exists), and
     *    only if it stored the key the record's removal with the flag ([ZchatPreferences.takeRefusedKeyOffer]);
     * e. the refusal notice cleared and the session epoch raised.
     *
     * A process that ends before the last write leaves the record and the flag: the banner stays, sends stay refused,
     * no writer stores a key for the contact (R8), and the user accepts again. The adoption sends nothing; the only
     * payment is the quoted owed KEX and, in a Tunnel or Open chat, the ZBOOT the plan counted.
     */
    private suspend fun adoptRefusedKey(
        peerAddress: String,
        accepted: AcceptedKeyOffer,
        plan: ReconnectPlan,
    ) {
        var refusal: String? = null
        var adopted = false
        withPeerSession(peerAddress) {
            val offer = rememberedOfferFor(peerAddress, accepted)
            if (offer == null) {
                refusal = ChatSendCopy.KEY_CHANGE_CHANGED_AGAIN
                return@withPeerSession
            }
            val storeSaves =
                zchatPreferences.rememberRefusedKeyOffer(
                    peerAddress,
                    offer.publicKey,
                    offer.memo,
                    offer.txId,
                    System.currentTimeMillis(),
                )
            if (!storeSaves) {
                refusal = ChatSendCopy.KEY_ACCEPT_NOT_SAVED
                return@withPeerSession
            }
            // ZC-739-R3: the owed mark below is tagged with the key this accept quoted it for, so "Not their key" for that
            // key can drop exactly it (and never a Reconnect the user quoted before the key change). Not saved: nothing.
            if (plan.count > 0 && !zchatPreferences.setAcceptOwedKey(peerAddress, offer.publicKey)) {
                refusal = ChatSendCopy.STORAGE_PAUSED_PAID_STEP
                return@withPeerSession
            }
            if (plan.count > 0 &&
                !recordQuotedOwedKex(
                    peerAddress,
                    ZchatPreferences.KEX_OWED_REASON_RECONNECT,
                    kexLeg = plan.kex,
                    zbootLeg = plan.zboot,
                )
            ) {
                refusal = ChatSendCopy.STORAGE_PAUSED_PAID_STEP
                return@withPeerSession
            }
            val priorOwnBootSent = zchatPreferences.isOwnBootSent(peerAddress)
            wipeRatchetState(peerAddress)
            adopted =
                synchronized(peerKeyMonitor) {
                    val current = zchatPreferences.getRefusedKeyOffer(peerAddress)
                    if (current == null || current.publicKey != accepted.refusedKey) {
                        false
                    } else {
                        wipeSessionPrefs(
                            peerAddress,
                            ownBootSent = priorOwnBootSent || plan.kex,
                            keepOurKeys = true,
                            keepRefusal = true,
                            // ZC-636: outside a Shielded chat, an accept whose quote has no ZBOOT leg (our current identity
                            // went out within the hour) keeps the marker that says so; cleared, a later block or chat open
                            // pays that ZBOOT again under the standing consent, outside this quote. Our relay identity is
                            // unchanged by the contact's new key.
                            keepSentBoot =
                                !plan.zboot &&
                                    zchatPreferences.getConversationMode(peerAddress) !=
                                    co.electriccoin.zcash.ui.screen.chat.model.ConversationMode.VAULT,
                        )
                        val stored =
                            adoptKeyOffer(current.memo, current.txId, peerAddress, accepted.refusedKey, KeyOfferMode.ACCEPT)
                        // ZC-660: the adopted key is saved before the record goes; not saved, the accept does not finish.
                        stored is KeyOfferOutcome.Stored &&
                            zchatPreferences.setAcceptedKey(peerAddress, accepted.refusedKey) &&
                            zchatPreferences.takeRefusedKeyOffer(peerAddress, accepted.refusedKey) != null
                    }
                }
            if (adopted) clearKeyChangeRefusal(peerAddress)
            bumpPeerSessionEpoch(peerAddress)
        }
        refusal?.let {
            _sendMessageState.value = SendMessageState.Error(it)
            return
        }
        if (!adopted) {
            // The wipe ran and the last write did not: the banner and the record are still there.
            Log.w("KEX", "Key accept for ${peerAddress.redactAddress()} did not finish; the warning stays for another accept")
            _sendMessageState.value = SendMessageState.Error(ChatSendCopy.KEY_ACCEPT_INTERRUPTED)
            return
        }
        Log.d("KEX", "Accepted the new key of ${peerAddress.redactAddress()} after the user's comparison")
        if (plan.kex) {
            kexOwedPeers.add(peerAddress)
            // Its SENT branch fires our ZBOOT when the plan counted one ([fireReconnectZbootIfDue]).
            payQuotedOwedKex(peerAddress, "Accept")
        } else if (plan.zboot) {
            fireReconnectZbootIfDue(peerAddress)
        }
        finishOpenReconnect(peerAddress, plan)
        // ZC-739: the finished accept starts the free work that waited for it; its own quoted legs above are the only payments.
        resumeAfterKeyDecision(peerAddress, paidLegs = false)
    }

    /**
     * ZC-545 (R7), ZC-702 — "Not their key": only the whole [refusedKey] the dialog showed may be dropped, with the
     * flag cleared in one write. Nothing else changes: free, the old key stays, sends resume to it as the user decided.
     * Under the contact's session lock; a missing or different remembered key changes nothing and asks the user again.
     * Refused while the old key is no longer stored (an accept was interrupted after its wipe: the flag has to stay
     * until that accept is finished or encryption is reset).
     */
    fun dismissRefusedKeyOffer(
        peerAddress: String,
        refusedKey: String,
    ) {
        viewModelScope.launch {
            var refusal: String? = null
            withPeerSession(peerAddress) {
                val offer = zchatPreferences.getRefusedKeyOffer(peerAddress)
                val storedKey = zchatPreferences.getE2EPeerPublicKey(peerAddress)
                when {
                    offer == null || offer.publicKey != refusedKey -> refusal = ChatSendCopy.KEY_CHANGE_CHANGED_AGAIN
                    storedKey == null || storedKey == offer.publicKey -> refusal = ChatSendCopy.KEY_ACCEPT_INTERRUPTED
                    zchatPreferences.dismissRefusedKeyOffer(peerAddress, refusedKey) -> {
                        clearKeyChangeRefusal(peerAddress)
                        dropWhatAnAcceptOwedForTheRefusedKey(peerAddress, refusedKey)
                    }
                    else -> {
                        // The store compares again under its lock; a replaced offer is not a failed storage write.
                        val current = zchatPreferences.getRefusedKeyOffer(peerAddress)
                        refusal =
                            if (current == null || current.publicKey != refusedKey) {
                                ChatSendCopy.KEY_CHANGE_CHANGED_AGAIN
                            } else {
                                ChatSendCopy.KEY_ACCEPT_NOT_SAVED
                            }
                    }
                }
            }
            refusal?.let { _sendMessageState.value = SendMessageState.Error(it) }
            // ZC-739: "Not their key" took the flag down: what waited goes to the old key, as the user decided.
            if (refusal == null) resumeAfterKeyDecision(peerAddress)
        }
    }

    /**
     * ZC-739-R2 — "Not their key" is free. While a refused key was remembered, the only writer of a reconnect owed key
     * exchange is an "Accept the new key" (the legacy reconnect is refused then), so such a mark, and the ZBOOT allowance
     * written with it, was quoted for the key the user has now rejected: an accept that ended before its wipe left them.
     * Both go, so nothing is paid for that key. Under the contact's session lock, after the record's removal.
     */
    private fun dropWhatAnAcceptOwedForTheRefusedKey(
        peerAddress: String,
        refusedKey: String,
    ) {
        runCatching {
            // ZC-739-R3: only the mark an accept tagged with exactly this refused key; a Reconnect the user quoted before
            // the key change carries no tag and stays owed.
            val acceptWroteIt = zchatPreferences.getAcceptOwedKey(peerAddress) == refusedKey
            if (acceptWroteIt) zchatPreferences.setAcceptOwedKey(peerAddress, null)
            if (acceptWroteIt &&
                zchatPreferences.isKexOwed(peerAddress) &&
                owedKexReason(peerAddress) == ZchatPreferences.KEX_OWED_REASON_RECONNECT
            ) {
                if (!zchatPreferences.setKexOwed(peerAddress, false)) {
                    Log.w("KEX", "Not their key: the owed key exchange for the refused key was not cleared (not saved)")
                }
                kexOwedPeers.remove(peerAddress)
                withdrawZbootQuote(peerAddress)
                Log.d("KEX", "Not their key: what an interrupted accept owed for the refused key was dropped, nothing paid")
            }
        }.onFailure { Log.w("KEX", "Not their key: owed marks not read (${it.javaClass.simpleName})") }
    }

    /**
     * ZC-739 — the work held while [peerAddress]'s new key waited for the user, started once the flag is down: the owed key
     * exchange ([retryOwedKeyExchange], on the confirm that covered it), the answer of a responder
     * ([retryKexAckIfResponder]), the Tunnel messages queued for the relays when the contact's relay key is known, the
     * avatar, and, in a Tunnel chat, our ZBOOT (the held tick or rotation fallback; the sender returns when our current
     * identity was already delivered, and goes relay first, then on-chain under the standing consent as before). Each
     * runs by the path that would have run it, so each held payment is paid at most once. A FAILED message row is never
     * sent here: its Retry is the user's tap. Does nothing while the flag is still up.
     *
     * [paidLegs] false: the decision was a confirmed accept or reconnect, whose own quoted legs (its key exchange, its
     * ZBOOT) were just paid by its own path on its own confirm; only the free work runs here, so nothing is paid beyond
     * that quote.
     */
    private fun resumeAfterKeyDecision(
        peerAddress: String,
        paidLegs: Boolean = true,
    ) {
        // Best effort: the decision itself is already saved. A step that fails here pays nothing and stays held work for
        // the next block or chat open, which run the same paths; it never ends the decision's own coroutine.
        try {
            if (zchatPreferences.isE2EKeyChanged(peerAddress)) return
            // Only a contact with queued Tunnel messages has anything to flush.
            if (tunnelPendingPayloads[peerAddress]?.isNotEmpty() == true) {
                zchatPreferences.getPeerNostrPubkey(peerAddress)?.let { flushTunnelPendingPayloads(peerAddress, it) }
            }
            pushSelfAvatarTo(peerAddress)
            if (!paidLegs) return
            retryOwedKeyExchange(peerAddress)
            retryKexAckIfResponder(peerAddress)
            if (zchatPreferences.getConversationMode(peerAddress) == ConversationMode.TUNNEL) sendNostrBootHandshake(peerAddress)
        } catch (e: Exception) {
            if (e is kotlinx.coroutines.CancellationException) throw e
            Log.w("KEX", "Held work after the key decision not started now (${e.javaClass.simpleName}); the next block retries it")
        }
    }

    /**
     * ZC-535 — our ZBOOT of a confirmed key-change reconnect, when the exchange is complete. A contact that already acked
     * our key answers our KEX with nothing, so no KEXACK would ever trigger the ZBOOT the question quoted. Only while
     * the reconnect's allowance stands and no ZBOOT to this contact is in flight. The delivered-identity marker is
     * re-armed first, as the Reconnect tap does ([reSendOurIdentity]): the user asked for our identity again, and the
     * marker would otherwise swallow it. The sender then decides as always: over the relays first (free, the allowance
     * withdrawn), else on-chain once against the allowance, never within the hour of a paid ZBOOT. With an incomplete
     * exchange nothing happens here: the contact's KEXACK is the trigger.
     */
    private fun fireReconnectZbootIfDue(peerAddress: String) {
        if (!zbootQuoteStands(peerAddress)) return
        if (!zchatPreferences.isE2EKeyExchangeComplete(peerAddress)) return
        if (nostrBootInFlight.contains(peerAddress)) return
        val frame =
            registerZbootFrame(peerAddress, ZbootOnChainRule.QUOTED_IN_SHIELDED, resumeOwed = false, rearmQuoted = true)
                ?: return
        sendNostrBootHandshake(peerAddress, ZbootOnChainRule.QUOTED_IN_SHIELDED, resumeOwed = false, frame = frame)
    }

    /**
     * #178/#225 — rotate our account-wide NOSTR identity to a fresh key, CONTINUING every existing chat.
     * Bumps the derivation index, then ANNOUNCES the new pubkey to each NOSTR-mode peer over NOSTR
     * (announceRotationOverNostr) signed by our UNCHANGED E2E identity key — so the peer's app adopts the
     * new key automatically (routeIncomingBoot #225 treats a verified pubkey change as a legitimate
     * rotation, not MITM) and the conversation continues seamlessly. The announce is published FROM the
     * still-old publisher (before requestInboxRotation) so the peer can attribute it; an on-chain ZBOOT
     * is the durable fallback for an offline peer / publisher-down. OUTBOUND uses the new key immediately;
     * the INBOUND inbox hot-swaps too (#188) while keeping the old key subscribed for a bounded grace
     * window (#225) so in-flight DMs to the old key still land. Returns the new index. NOTE: the index is
     * local state; a seed-only restore returns to index 0 and peers re-learn the key via the same signed
     * announcement (no value at risk — the on-chain wallet recovers from seed as always).
     */
    fun rotateNostrIdentity(): Int {
        val next = zchatPreferences.getNostrRotationIndex() + 1
        // Bump the index FIRST so every derivation (getOurNostrPubkey, the on-chain ZBOOT) yields the NEW
        // pubkey. The live PUBLISHER still signs as the OLD identity until requestInboxRotation() below —
        // which is exactly what lets us announce the rotation FROM the old key (so peers can attribute it).
        zchatPreferences.setNostrRotationIndex(next)
        Log.w("ZCHAT_NOSTR", "NOSTR identity rotating to index $next — announcing to NOSTR peers")
        // NonCancellable: this whole sequence (announce each peer, THEN hot-swap the inbox) must complete
        // even if the chat-detail ViewModel that triggered it is torn down mid-flight — otherwise outbound
        // flips to the new key (index already persisted) while the inbound inbox never swaps and some peers
        // never get the announcement, until the next app launch (#225 review).
        viewModelScope.launch {
            kotlinx.coroutines.withContext(kotlinx.coroutines.NonCancellable) {
                val derived = getOurNostrPubkey()
                if (derived == null) {
                    // Seed not ready — still hot-swap the inbox so inbound follows the new key.
                    co.electriccoin.zcash.ui.nostr.NostrChatBridge.requestInboxRotation()
                    return@withContext
                }
                val (newPub, relay) = derived
                val peers = zchatPreferences.getAllPeerToConvIdMappings().keys.filter {
                    zchatPreferences.getConversationMode(it) !=
                        co.electriccoin.zcash.ui.screen.chat.model.ConversationMode.VAULT
                }
                var announced = 0
                peers.forEach { peer ->
                    // Allow the on-chain ZBOOT fallback to re-fire the new identity if NOSTR can't carry it.
                    zchatPreferences.setOwnBootSent(peer, false)
                    // PRIMARY: announce over NOSTR from the OLD identity (free, instant, attributable). The
                    // peer adopts the new pubkey on verifying the signature against our unchanged E2E key
                    // (routeIncomingBoot #225). Sent BEFORE requestInboxRotation so the publisher is still
                    // the old key the peer recognizes.
                    val ok = runCatching { announceRotationOverNostr(peer, newPub, relay) }.getOrDefault(false)
                    if (ok) {
                        announced++
                    } else {
                        // FALLBACK: durable on-chain ZBOOT (covers offline peer / publisher down) — only for
                        // NON-OPEN peers. An OPEN peer (#224) has no E2E key, so it cannot authenticate an
                        // on-chain E2E-signed ZBOOT (routeIncomingBoot drops it), and OPEN is no-on-chain by
                        // design. Its v4 NOSTR-key-signed announce above is the path; if that failed (publisher
                        // down), the grace-window re-subscribe + retry-on-next-NOSTR-contact recovers it (#250).
                        if (zchatPreferences.getConversationMode(peer) !=
                            co.electriccoin.zcash.ui.screen.chat.model.ConversationMode.OPEN) {
                            sendNostrBootHandshake(peer)
                        }
                    }
                }
                // NOW hot-swap the live INBOUND inbox to the new key — AFTER the announcements went out
                // under the old key. #188: service re-derives + re-subscribes (now with a #225 grace
                // window keeping the old key briefly live), no app restart needed.
                co.electriccoin.zcash.ui.nostr.NostrChatBridge.requestInboxRotation()
                Log.d("ZCHAT_NOSTR", "Rotation to index $next: announced over NOSTR to $announced/${peers.size} peer(s); inbox swapped")
            }
        }
        return next
    }

    /**
     * True once the user has confirmed this peer's safety number out-of-band. Lets the UI
     * distinguish a "verified" conversation from one that is merely TOFU-encrypted. Cleared
     * automatically when the peer's key changes (see the KEX/boot key-change handlers).
     */
    fun isE2EVerified(peerAddress: String): Boolean =
        zchatPreferences.isE2EVerified(peerAddress)

    /**
     * User confirmed the safety number matches out-of-band — mark the conversation verified.
     *
     * ZC-634 (5.5 items 6 and 9): while the contact key is only a claim the tap removes the mark and sets the verified flag
     * in one commit, then hands the ZBOOT the mark held back to [routeIncomingBoot], which binds it by the ordinary rules;
     * our reply goes over the relays only, so the tap pays nothing in any chat mode.
     */
    fun markE2EVerified(peerAddress: String) {
        // W-72 (SPEC_F R7): the pre-update mark goes with the tap, the verified flag in the same commit, and the ZBOOT it held
        // back is handed on (after a claim mark's release below, when one stands too).
        var legacyHeld: String? = null
        if (zchatPreferences.getLegacyKeyMark(peerAddress) != null) {
            // One store section removes the mark and hands back the ZBOOT it held ("" when none).
            legacyHeld =
                zchatPreferences.releaseLegacyKeyWithBoot(peerAddress, verified = true)?.takeIf { it.isNotEmpty() } ?: run {
                    if (zchatPreferences.getLegacyKeyMark(peerAddress) != null) {
                        Log.w("KEX", "Mark as verified: the pre-update mark was not removed — nothing changed")
                        return
                    }
                    null
                }
        }
        if (zchatPreferences.getKeyClaim(peerAddress) == null) {
            zchatPreferences.setE2EVerified(peerAddress, true)
            if (legacyHeld != null) {
                routeIncomingBoot(peerAddress, legacyHeld, sealedByBoundKey = false, replyRule = ZbootOnChainRule.RELAY_ONLY)
            }
            return
        }
        // Review of part B, finding 3: the held ZBOOT comes back from the call that removes the mark (one section).
        // Recheck of the review fixes, item 1: under peerKeyMonitor, so a proof being stored never interleaves with the tap.
        val held =
            synchronized(peerKeyMonitor) { zchatPreferences.releaseKeyClaim(peerAddress, verified = true) } ?: run {
                Log.w("KEX", "Mark as verified: the claim mark was not removed — nothing changed")
                // Review of 3426ade7d, finding 6: the pre-update mark's ZBOOT is not lost; the claim that stands holds it.
                if (legacyHeld != null) {
                    routeIncomingBoot(peerAddress, legacyHeld, sealedByBoundKey = false, replyRule = ZbootOnChainRule.RELAY_ONLY)
                }
                return
            }
        // Review of 3426ade7d, finding 6: the claim's held ZBOOT, or else the one the pre-update mark held.
        val handOn = held.takeIf { it.isNotEmpty() } ?: legacyHeld
        if (handOn != null) routeIncomingBoot(peerAddress, handOn, sealedByBoundKey = false, replyRule = ZbootOnChainRule.RELAY_ONLY)
    }

    /** W-72 (SPEC_F R8) — this chat's key carries a pre-update mark: the banner says "Not confirmed". */
    fun isKeyNotConfirmed(peerAddress: String): Boolean = zchatPreferences.getLegacyKeyMark(peerAddress) != null

    /** ZC-634 (5.5 item 8) — this chat's key is only a claim and a ZBOOT was held back: the banner says so. */
    fun isKeyClaimHeld(peerAddress: String): Boolean =
        zchatPreferences.getKeyClaim(peerAddress) != null && zchatPreferences.getHeldClaimBoot(peerAddress) != null

    /**
     * Compute a human-readable safety number for visual key verification.
     * Returns 32 hex chars (16 bytes of SHA-256 of the peer's pubkey) or null if
     * E2E is not set up for this peer.
     *
     * Both parties compute the SAME safety number because they both hash the
     * SAME peer pubkey. Alice hashes Bob's key; Bob hashes Alice's key. So Alice
     * and Bob will see DIFFERENT numbers (each sees their own peer's hash). To
     * get a shared number both can compare, hash the SORTED pair of pubkeys:
     * SHA-256(min(ourPub, peerPub) || max(ourPub, peerPub)).take(16) → 32 hex.
     */
    fun computeSafetyNumber(peerAddress: String): String? {
        val ourPubB64 = zchatPreferences.getE2EOurPublicKey(peerAddress) ?: return null
        val peerPubB64 = zchatPreferences.getE2EPeerPublicKey(peerAddress) ?: return null
        return computeSafetyNumber(ourPubB64, peerPubB64)
    }

    /** ZC-545 — [computeSafetyNumber] for a key that may not decode (a remembered offer): null instead of a throw. */
    private fun safetyNumberOf(
        ourPubB64: String,
        peerPubB64: String,
    ): String? = runCatching { computeSafetyNumber(ourPubB64, peerPubB64) }.getOrNull()

    /**
     * ZC-545 (G8) — the safety number of the pair ([ourPubB64], [peerPubB64]), pure: the dialog of a remembered refused
     * key shows the number of OUR key with THAT key, before anything is stored, and after the accept the stored pair
     * gives the same number.
     */
    fun computeSafetyNumber(
        ourPubB64: String,
        peerPubB64: String,
    ): String {
        // Hash raw pubkey bytes (not Base64 encoding) so the safety number is
        // stable across encoding format changes. Sort so both parties compute the same.
        val ourBytes = java.util.Base64.getDecoder().decode(ourPubB64)
        val peerBytes = java.util.Base64.getDecoder().decode(peerPubB64)
        // Order by the raw BYTES (unsigned lexicographic), not the Base64 strings. Base64 ordering can
        // differ from byte ordering, and we hash the bytes — so sorting by the string while hashing the
        // bytes contradicts this function's own spec. This does NOT change MITM detection (both parties
        // already sort the same key pair by the same rule and therefore agree); it aligns the code with
        // its documented algorithm and with any byte-sorting cross-platform client. Rollout note: it
        // changes the DISPLAYED number, so a previously-verified pair spanning old/new app versions
        // should re-compare out of band.
        var cmp = 0
        for (i in 0 until minOf(ourBytes.size, peerBytes.size)) {
            cmp = (ourBytes[i].toInt() and 0xff) - (peerBytes[i].toInt() and 0xff)
            if (cmp != 0) break
        }
        if (cmp == 0) cmp = ourBytes.size - peerBytes.size
        val (first, second) = if (cmp <= 0) ourBytes to peerBytes else peerBytes to ourBytes
        val hash = java.security.MessageDigest.getInstance("SHA-256")
            .digest(first + second)
        return hash.take(16).joinToString("") { "%02x".format(it) }
    }

    /**
     * Get or create a ratcheted [E2EMessageProcessor] for a peer conversation. Returns null
     * if E2E is not enabled or keys are not yet exchanged. The processor is cached per
     * (peerAddress, convId) pair so HKDF root derivation runs only once per conversation.
     */
    /**
     * Drop cached E2E processors for [peerAddress] so the next use re-derives the ratchet root from the
     * (now updated) convergent KEX/KEXACK txid set — used when a newly-mined KEX/KEXACK txid changes the
     * root material so both devices re-converge (B1/B2). Cache keys are "$peer:$convId".
     */
    private fun invalidateMessageProcessors(peerAddress: String) {
        synchronized(messageProcessors) { messageProcessors.keys.removeAll { it.startsWith("$peerAddress:") } }
    }

    private suspend fun getOrCreateMessageProcessor(
        peerAddress: String,
        convId: String,
        forSend: Boolean = false,
    ): co.electriccoin.zcash.ui.screen.chat.crypto.ratchet.E2EMessageProcessor? {
        val processor = getOrCreateMessageProcessorUngated(peerAddress, convId, forSend) ?: return null
        // R3-3 (1): a send waits while the ratchet still carries an older conversation id's counters the history pass
        // has not settled: sent now, it would use that counter for good, and it may be an older root's, beyond what
        // the peer accepts. The caller aborts ("try again in a moment"), never plaintext: the processor exists, so
        // E2E is on for this peer. The pass end settles them (settleLegacyFloorJumps).
        if (forSend && !RestoreKexPolicy.maySendBeforeLegacySettlement(processor.unsettledLegacyJumps())) {
            Log.w("ZCHAT_E2E", "Send to ${peerAddress.redactAddress()} waits: older conversation counters not settled yet")
            synchronized(messageProcessors) {
                peersAwaitingLegacySettlement = peersAwaitingLegacySettlement.orEmpty() + peerAddress
            }
            restoreRecheck.update { it + 1 }
            return null
        }
        return processor
    }

    /**
     * R4-3 (2): the reason to show when a send was refused, so the user is told the truth. A send the history
     * settlement is holding is not a missing key exchange and not a session re-establishing: the keys are there,
     * ZCHAT is reading this chat's history, nothing was sent and nothing was paid, and the wait is bounded
     * (RestoreKexPolicy.MAX_LEGACY_SETTLEMENT_WAITS).
     */
    private fun sendRefusedReason(peerAddress: String, otherwise: String): String =
        RestoreKexPolicy.sendRefusedReason(
            awaitingLegacySettlement = isAwaitingLegacySettlement(peerAddress),
            otherwise = otherwise,
        )

    /**
     * Round 8 D8 (F31) — [sendRefusedReason] for a control (the timer, the mode), which shows only as a toast with no
     * Retry button: while the history settlement holds [peerAddress] it says [whileReadingHistory] instead of
     * RestoreKexPolicy.STILL_READING_HISTORY ("…tap Retry then").
     */
    private fun sendRefusedReason(
        peerAddress: String,
        otherwise: String,
        whileReadingHistory: String,
    ): String = if (isAwaitingLegacySettlement(peerAddress)) whileReadingHistory else otherwise

    private fun isAwaitingLegacySettlement(peerAddress: String): Boolean =
        synchronized(messageProcessors) { peerAddress in peersAwaitingLegacySettlement.orEmpty() }

    /**
     * R3-3 (1): the pass end's settlement of the send counters a ratchet carries from an older conversation id (see
     * [co.electriccoin.zcash.ui.screen.chat.crypto.ratchet.E2ERatchet.settleLegacyJump]), for [peers]: the contacts
     * with one of our own messages under an older id in this pass, and those a send found waiting. Returns true
     * while one still waits for a pass that read all of our own messages.
     */
    @Suppress("LongParameterList", "CyclomaticComplexMethod")
    private suspend fun settleLegacyFloorJumps(
        peers: Set<String>,
        ownHistoryPassComplete: Boolean,
        historyScanComplete: Boolean,
        ownEnvelopesByConv: Map<String, List<Ciphertext>>,
        unreadOwnEnvelopesByConv: Map<String, List<Ciphertext>>,
        unattributedOwnEnvelopes: List<Ciphertext>,
        headerUnknownPeers: Set<String>,
        headerUnknownConvIds: Set<String>,
        unattributedOwnEnvelopeGaps: Int,
    ): Boolean {
        var waiting = false
        for (peer in peers) {
            var peerWaiting = false
            try {
                // Round 8 D8 (F32): a contact with no conversation id, no keys (after Reset encryption) or no ratchet has
                // nothing left to settle, so it is no longer marked as waiting; the refusals name their own reason again.
                val sendConvId = zchatPreferences.getConversationId(peer)
                if (sendConvId == null) {
                    forgetLegacySettlementWait(peer)
                    continue
                }
                if (zchatPreferences.getE2EOurPublicKey(peer) == null || zchatPreferences.getE2EPeerPublicKey(peer) == null) {
                    forgetLegacySettlementWait(peer)
                    continue
                }
                // ZC-545, ZC-564: one session block per contact around the processor and its settle calls.
                val stillWaiting: Boolean? =
                    withPeerSession(peer) {
                        val processor =
                            getOrCreateMessageProcessorUngated(peer, sendConvId, forSend = false)
                                ?: return@withPeerSession null
                        var jumpWaiting = false
                        for (olderConvId in processor.unsettledLegacyJumps()) {
                            // R4-3 (2): the wait is counted only over passes whose chain scan had finished, so a wallet
                            // still scanning waits for its scan however long that takes and spends none of the budget.
                            val waitKey = "$peer|$olderConvId"
                            val step =
                                RestoreKexPolicy.legacyJumpStep(
                                    ownHistoryPassComplete = ownHistoryPassComplete,
                                    ownEnvelopeHeaderUnknown =
                                        peer in headerUnknownPeers ||
                                            olderConvId in headerUnknownConvIds ||
                                            unattributedOwnEnvelopeGaps > 0,
                                    waitedCompletedScans = legacySettlementWaits[waitKey] ?: 0,
                                )
                            when (step) {
                                RestoreKexPolicy.LegacyJumpStep.WAIT -> {
                                    jumpWaiting = true
                                    if (historyScanComplete) {
                                        legacySettlementWaits[waitKey] = (legacySettlementWaits[waitKey] ?: 0) + 1
                                    }
                                }
                                RestoreKexPolicy.LegacyJumpStep.ADOPT -> {
                                    processor.adoptLegacyJump(olderConvId)
                                    legacySettlementWaits.remove(waitKey)
                                }
                                RestoreKexPolicy.LegacyJumpStep.SETTLE -> {
                                    processor.settleLegacyJump(
                                        olderConvId,
                                        ownEnvelopesByConv[olderConvId].orEmpty() +
                                            unreadOwnEnvelopesByConv[olderConvId].orEmpty() +
                                            unattributedOwnEnvelopes,
                                    )
                                    legacySettlementWaits.remove(waitKey)
                                }
                            }
                        }
                        jumpWaiting
                    }
                if (stillWaiting == null) {
                    forgetLegacySettlementWait(peer)
                    continue
                }
                if (stillWaiting) peerWaiting = true
            } catch (e: Exception) {
                if (e is kotlinx.coroutines.CancellationException) throw e
                peerWaiting = true
                Log.w("ZCHAT_E2E", "Older conversation counters of ${peer.redactAddress()} not settled: ${e.javaClass.simpleName}")
            }
            if (peerWaiting) {
                waiting = true
            } else {
                forgetLegacySettlementWait(peer)
            }
        }
        return waiting
    }

    /** R3-3 (1) / Round 8 D8 (F32): [peer]'s sends no longer wait for the settlement of older conversation counters. */
    private fun forgetLegacySettlementWait(peer: String) {
        synchronized(messageProcessors) {
            peersAwaitingLegacySettlement = peersAwaitingLegacySettlement.orEmpty() - peer
        }
    }

    /** ZC-1792 F1 — the protocol memos the Accept-first gate never refuses (they are how the key exchange completes). */
    private fun isHandshakeControlMemo(message: String): Boolean =
        co.electriccoin.zcash.ui.screen.chat.model.ZBootMessage
            .isBootMessage(message) ||
            ZMSGProtocol.isKEXMessage(message) ||
            ZMSGProtocol.isKEXAckMessage(message)

    private suspend fun getOrCreateMessageProcessorUngated(
        peerAddress: String,
        convId: String,
        forSend: Boolean,
    ): co.electriccoin.zcash.ui.screen.chat.crypto.ratchet.E2EMessageProcessor? {
        // ZC-545, ZC-564: read FIRST, before any state the processor is built from (see retireProcessorsOfEarlierEpoch).
        val sessionEpoch = peerSessionEpoch(peerAddress)
        // R5 SEND GATE (D1-recovery, nonce-reuse mitigation) — ONLY on the send path (forSend), never
        // on decrypt: after a seed restore re-derives a peer's key, the ratchet root is byte-identical
        // but this device's send-counter floor starts at 0, so a send BEFORE the rescan re-establishes
        // the floor would reuse a burned (root, direction, counter). Defer such sends fail-closed
        // (return null → every caller aborts and surfaces "try again in a moment"; NEVER counter 0,
        // NEVER plaintext). Must run OUTSIDE `synchronized` (suspend I/O) and BEFORE the cache hit so a
        // processor cached by a decrypt attempt can't smuggle a send past the gate. The decrypt path
        // (forSend=false) is exempt — it is what RE-ESTABLISHES the floor and clears the marker.
        if (forSend) {
            // Gate only a KEYED peer: an un-keyed peer has no burned counters to collide with (it will
            // re-KEX a fresh session; "Reset Encryption" allocates a NEW seed index → new root), so it
            // must never be blocked. For a keyed, seed-restored peer, defer the send until the recovery
            // marker clears at the pass-end reconcile. The marker — NOT the send-counter floor — is the
            // gate: the floor climbs incrementally during the rescan, so a mid-pass floor is only PARTIAL,
            // and consulting it (the old bug) would let a send restart at an already-burned counter and
            // reuse an AES-GCM (root, direction, counter). See SeedDerivedE2EKeyProvider.
            val ourPub = zchatPreferences.getE2EOurPublicKey(peerAddress)
            val peerPub = zchatPreferences.getE2EPeerPublicKey(peerAddress)
            if (ourPub != null && peerPub != null && seedKeyProvider.isSendBlockedPendingRecovery(peerAddress)) {
                Log.w(
                    "ZCHAT_E2E",
                    "R5 send gate: deferring send to ${peerAddress.redactAddress()} — restoring history, " +
                        "recovery marker still set (converged-pass floor not yet authoritative; would risk nonce reuse)"
                )
                return null
            }
            // ZC-1792 F1 backstop (fail-closed, before the cache hit): no send processor while our answer to the stored key
            // is unpaid. Null ends every seal site in a refusal (the row kept for Retry, nothing paid, never plaintext).
            if (ownAnswerToStoredKeyUnpaid(peerAddress)) {
                Log.w("ZCHAT_E2E", "ZC-1792 send gate: our answer to ${peerAddress.redactAddress()}'s key exchange is not paid")
                return null
            }
        }
        val cacheKey = "$peerAddress:$convId"
        // Synchronized to prevent TOCTOU race: two coroutines hitting a cache miss
        // simultaneously could create duplicate processors with desynchronized counters.
        synchronized(messageProcessors) {
            // ZC-545, ZC-564: a processor this instance cached before a wipe in ANY instance is never served after it.
            retireProcessorsOfEarlierEpoch(peerAddress, sessionEpoch)
            messageProcessors[cacheKey]?.let { return it }

            val sharedKey = getE2ESharedKey(peerAddress) ?: return null
            // #bug-plaintext-on-keyed-chat (found in deep 2-device testing: a VAULT message left Honor as
            // raw on-chain plaintext "CYC1_VAULT_H2S" because e2eEnabled was stuck false). A NON-NULL shared
            // key means a secure E2E session is ESTABLISHED with this peer (we hold our private + their
            // public key). E2E must therefore be ON — the send path must NEVER fall back to plaintext on a
            // chat the UI calls "shielded/encrypted". So instead of returning null here (which let the caller
            // send in the clear), SELF-HEAL a stuck e2eEnabled=false (the post-reset / KEXACK-initiator
            // artifact where the flag wasn't set even though the handshake completed) and build the processor
            // so the message is ENCRYPTED. Genuine non-E2E peers never reach here — getE2ESharedKey returns
            // null for them (no peer key) → caller sends the plaintext first-contact bootstrap, unaffected.
            if (!zchatPreferences.isE2EEnabled(peerAddress)) {
                zchatPreferences.setE2EEnabled(peerAddress, true)
                Log.w("ZCHAT_E2E", "Self-healed stuck e2eEnabled=false for ${peerAddress.redactAddress()} (keys exist → must encrypt, not plaintext)")
            }

            val ourPub = zchatPreferences.getE2EOurPublicKey(peerAddress) ?: return null
            val peerPub = zchatPreferences.getE2EPeerPublicKey(peerAddress) ?: return null
            val isLower = ourPub < peerPub

            // Root derivation using the CONVERGENT, generation-scoped KEX/KEXACK txid SETS (B1/B2 fix).
            // Both devices see the same mined KEX/KEXACK txs, so the SORTED union yields byte-identical
            // material on both sides — this is what stops the last-writer-wins scalar from giving A and B
            // different roots (→ AEADBadTag on the first VAULT send after an OPEN pair's dual KEX). The
            // legacy scalar is folded into the set so a pre-update single-KEX chat derives byte-identical
            // material to before (set empty + one scalar → "<txid>" == the old value) — no migration break.
            val kexTxId = co.electriccoin.zcash.ui.screen.chat.crypto.ratchet.E2ERatchet.canonicalTxidMaterial(
                zchatPreferences.getKexTxIds(peerAddress), zchatPreferences.getE2EKexTxId(peerAddress)
            )
            val kexAckTxId = co.electriccoin.zcash.ui.screen.chat.crypto.ratchet.E2ERatchet.canonicalTxidMaterial(
                zchatPreferences.getKexAckTxIds(peerAddress), zchatPreferences.getE2EKexAckTxId(peerAddress)
            )
            // Quantum Shield PSK: mix into root if active for this conversation
            val pskBase64 = zchatPreferences.getQuantumShieldPSK(peerAddress)
            val psk = pskBase64?.let { java.util.Base64.getDecoder().decode(it) }

            val rootKey = co.electriccoin.zcash.ui.screen.chat.crypto.ratchet.E2ERatchet.deriveRatchetRoot(
                ecdhSharedSecret = sharedKey,
                psk = psk,
                kexTxid = kexTxId,
                kexAckTxid = kexAckTxId,
            )

            val processor = co.electriccoin.zcash.ui.screen.chat.crypto.ratchet.E2EMessageProcessor(
                rootKey = rootKey,
                convId = convId,
                isLower = isLower,
                store = ratchetStateStore,
                legacyFloorKeys = conversationIdsOf(peerAddress) + convId,
                // R3-3 (1): what an older version kept under the id our sends use is this root's; what it kept under
                // any other id waits for the history pass (E2ERatchet.settleLegacyJump).
                sendConvId = zchatPreferences.getConversationId(peerAddress) ?: convId,
            )
            messageProcessors[cacheKey] = processor
            return processor
        }
    }

    /**
     * Every conversation id this device has mapped to [peerAddress]: its current one and any older one still
     * mapped. Counter floors were kept per conversation id before R2-4, so a ratchet reads all of them.
     */
    private fun conversationIdsOf(peerAddress: String): Set<String> =
        zchatPreferences.getAllConversationMappings().filterValues { it == peerAddress }.keys +
            listOfNotNull(zchatPreferences.getConversationId(peerAddress))

    /**
     * Try to decrypt an E2E-encrypted message content. If the content is not E2E-encrypted
     * (no E2E1: or E2E: prefix), returns it unchanged. Errors are logged and the raw content
     * is returned (fail-open for display — the user sees the encrypted blob, not a crash).
     */
    private suspend fun tryDecryptMessage(
        content: String,
        peerAddress: String,
        convId: String?,
        onNotAttempted: (() -> Unit)? = null,
    ): String = tryDecryptMessage(content, peerAddress, convId, onNotAttempted, onOpened = null)

    /**
     * [tryDecryptMessage]; W-72 (SPEC_F R5, R6): [onOpened] runs when the ratchet opened [content] (now, or earlier from the
     * cache). ZC-1792 F3: with [outcomes] a ratchet failure does not arm the keys-out-of-sync banner here; the history pass
     * decides at its end from the row's height ([settleDecryptOutcomes]), and records a fresh open with its height.
     */
    @Suppress("LongParameterList")
    private suspend fun tryDecryptMessage(
        content: String,
        peerAddress: String,
        convId: String?,
        onNotAttempted: (() -> Unit)?,
        onOpened: (() -> Unit)?,
        outcomes: DecryptOutcomes? = null,
        rowId: String? = null,
        minedHeight: Long? = null,
        incoming: Boolean = true,
        oldRootRow: OldRootFallback.Row? = null,
    ): String {
        // NOT a ratcheted envelope → plain content (or another protocol layer), return unchanged.
        if (!co.electriccoin.zcash.ui.screen.chat.crypto.ratchet.CiphertextWireFormat.isRatcheted(content)) return content
        // From here `content` IS a raw "E2E1:<dir>:<counter>:<b64>" ratchet blob. It must NEVER be
        // returned to the UI verbatim — doing so leaked literal "E2E1:00:…" bubbles to the peer after a
        // Reset/desync (B4). Every failure path below yields a placeholder, never the raw envelope.

        // Resolved only on the paths that show it (a successful decrypt never reads the app's strings).
        fun reestablishing() = noteCopy.get(R.string.chat_decrypt_placeholder_reestablishing)
        // Decrypt a ratcheted message EXACTLY ONCE, ever. The symmetric per-message-key ratchet
        // refuses to re-decrypt an already-consumed counter (a replay guard — NOT forward secrecy;
        // keys re-derive from the stored root), so a 2nd decrypt of the same ciphertext fails — but the UI
        // re-derives conversations from chain history on every sync. L1 = in-memory (this process);
        // L2 = encrypted prefs (survives restart). Only when BOTH miss do we run the ratchet, then
        // persist. Durable fix for the whole "re-decrypt → replay → 'Encrypted message'" bug class.
        // Can't decrypt without a conversation id / a live processor. Surface the transient placeholder
        // (UNcached, so the next derive retries once the session re-establishes) — never the raw blob. We
        // deliberately do NOT arm decryptFailedPeers here: these are transient one-scan misses (mapping not
        // restored yet, processor not built, OPEN chat with no E2E keys), and arming it would nudge the user
        // toward a ZEC-spending Reset for a glitch. Only a genuine AEAD failure (catch below) arms it.
        //
        // This guard runs BEFORE any cache read on purpose. The cache maps ciphertext to plaintext, so
        // consulting it without a conversation id turned it into an oracle: replay an envelope observed
        // elsewhere and the cache answered with the plaintext it learned in the original conversation.
        if (convId == null) {
            onNotAttempted?.invoke()
            return reestablishing()
        }
        val cacheKey = co.electriccoin.zcash.ui.screen.chat.crypto.DecryptedTextCacheKey.of(convId, content)
        decryptedTextCache[cacheKey]?.let { text ->
            // ZC-1811, ZC-1841, ZC-1847: an incoming text this phone opened (earlier in this process, or read from the store
            // into this cache) is noted with its height; the settlement decides from the height. Our own never counts.
            if (incoming) outcomes?.opened(peerAddress, minedHeight)
            onOpened?.invoke()
            return text
        }
        // Rows written before the key was conversation-bound are keyed on the ciphertext alone. Upgrade
        // one on first use rather than orphaning it: the ratchet will not re-decrypt a consumed counter,
        // so an orphaned row is a message that silently becomes unreadable.
        val legacyKey = co.electriccoin.zcash.ui.screen.chat.crypto.DecryptedTextCacheKey.legacyOf(content)
        val persisted =
            zchatPreferences.getDecryptedText(cacheKey)
                ?: zchatPreferences.getDecryptedText(legacyKey)?.also { migrated ->
                    zchatPreferences.putDecryptedText(cacheKey, migrated)
                    zchatPreferences.removeDecryptedText(legacyKey)
                }
        persisted?.let { cached ->
            // Heal a poisoned cache: an older build could persist a raw "E2E1:" blob as the "decrypted"
            // value. Never serve that back — scrub it and fall through to a real decrypt attempt.
            if (co.electriccoin.zcash.ui.screen.chat.crypto.ratchet.CiphertextWireFormat.isRatcheted(cached)) {
                zchatPreferences.removeDecryptedText(cacheKey)
                decryptedTextCache.remove(cacheKey)
            } else {
                decryptedTextCache[cacheKey] = cached
                // ZC-1810: a stored text never clears the keys-out-of-sync banner here, and our own saved outgoing plaintext
                // never counts. ZC-1841: an INCOMING stored text is noted with its height; the settlement counts it only when
                // mined above the newest trusted KEXACK and after the failure (a basis that outlives this instance and a
                // restart).
                if (incoming) outcomes?.opened(peerAddress, minedHeight)
                onOpened?.invoke()
                return cached
            }
        }
        // ZC-1792 (W-142, P-A), ZC-1823: the current root is always tried first, also for a row an earlier root opened
        // before: should that root be current again (a reorg took an exchange away), the real ratchet reads the row and
        // raises its floors (an own row's send floor above its counter: no (key, nonce) reuse). The row-bound text is read
        // only where the current root cannot answer: its replay and AEAD catches below.
        val opened =
            try {
                // ZC-545, ZC-564: obtain and decrypt in one session block; with no processor (a session being
                // re-established) nothing is attempted and the placeholder stays, as before.
                val plaintext =
                    withPeerSession(peerAddress) {
                        getOrCreateMessageProcessor(peerAddress, convId)?.decryptIncoming(content)
                    }
                if (plaintext == null) {
                    onNotAttempted?.invoke()
                    // ZC-1792 F2 / ZC-1632: no processor because the contact's key is not here yet: our key exchange is
                    // unanswered. ZC-1829: the text says it should open once the answer arrives (sent after it: the current
                    // root; sent before it: P-A's earlier root), and asks for a resend only if it still cannot be read then.
                    if (zchatPreferences.getE2EOurPublicKey(peerAddress) != null &&
                        zchatPreferences.getE2EPeerPublicKey(peerAddress) == null
                    ) {
                        return noteCopy.get(R.string.chat_decrypt_placeholder_awaiting_answer)
                    }
                    return reestablishing()
                }
                // Defensive: decryptIncoming should never hand back a raw envelope, but if it ever did, do
                // NOT cache/persist it (that is exactly how the cache got poisoned before).
                if (co.electriccoin.zcash.ui.screen.chat.crypto.ratchet.CiphertextWireFormat
                        .isRatcheted(plaintext)
                ) {
                    return reestablishing()
                }
                decryptedTextCache[cacheKey] = plaintext
                zchatPreferences.putDecryptedText(cacheKey, plaintext)
                // ZC-1810: only an INCOMING row is recovery evidence; the history settlement decides from its height.
                // ZC-1855, ZC-1856 (QA2 pa3): a decrypt outside a history pass (no [outcomes]; no production caller) neither
                // arms nor clears the banner: the settlement is its one owner, the same for every ViewModel.
                if (incoming) outcomes?.opened(peerAddress, minedHeight)
                onOpened?.invoke()
                plaintext
            } catch (e: co.electriccoin.zcash.ui.screen.chat.crypto.ratchet.ReplayDetectedException) {
                Log.d("ZCHAT_E2E", "Replay of counter ${e.counter} for ${peerAddress.redactAddress()} — already decrypted this session")
                // A replay of an already-seen message.
                return decryptedTextCache[cacheKey]
                    // ZC-1823: the current root consumed this counter (its own chain since): the row an earlier root opened.
                    ?: oldRootRow
                        ?.let { row -> oldRootTextAfterFailure(content, peerAddress, convId, row, open = false) }
                        ?.also { if (incoming) outcomes?.opened(peerAddress, minedHeight) }
                    ?: noteCopy.get(R.string.chat_decrypt_placeholder_replay)
            } catch (e: Exception) {
                // ZC-1792 (W-142, P-A): a mined row the current root cannot open may be sealed under the root as it stood at
                // its height; a row that reads that way returns here, display only (no onOpened, no key evidence, no control).
                // ZC-1828 (QA2 pa3, composed with K1b2's ZC-1841): an incoming row it opens is noted with its height like any
                // other open, so the settlement counts it only when mined above the newest trusted KEXACK and after a failure.
                if (e is javax.crypto.AEADBadTagException && oldRootRow != null) {
                    oldRootTextAfterFailure(content, peerAddress, convId, oldRootRow, open = true)?.let { text ->
                        if (incoming) outcomes?.opened(peerAddress, minedHeight)
                        return text
                    }
                }
                Log.w("ZCHAT_E2E", "Ratchet decrypt failed for ${peerAddress.redactAddress()}: ${e.javaClass.simpleName}")
                // The in-chat "re-establish encryption" recovery banner; ZC-1792 F3: in a history pass, at its end.
                // ZC-1855 (QA2 pa3): outside a pass (no production caller) nothing is armed; the settlement owns the banner.
                outcomes?.failed(peerAddress, rowId, minedHeight, incoming)
                // Decrypt failed (typically AEADBadTagException = the E2E key on THIS device doesn't match
                // the one the message was sealed with). The usual cause is a wallet RESTORE: E2E ratchet keys
                // live in local encrypted storage and are NOT derived from the seed (random per-device keys), so a
                // seed-only recovery brings back the on-chain ciphertext but not the key to open it \u2014 the old
                // message is then unreadable by design. A peer key-change can also cause it. The old cryptic
                // "Encrypted message (unable to decrypt)" made users think an important message was lost; this
                // explains the real reason and the recovery path (have the sender resend \u2192 a fresh exchange
                // re-keys both sides). Not persisted \u2014 recomputed each derive, so it auto-clears once a resent
                // message decrypts. (We intentionally do NOT make this a one-tap re-key: on an on-chain chat a
                // re-KEX spends ZEC, so re-establishing stays a deliberate user action via the chat menu.)
                return decryptedTextCache[cacheKey] ?: noteCopy.get(R.string.chat_decrypt_placeholder_key_missing)
            }
        return opened
    }

    /** R2-5 (c): note the stored-text cache keys (current and legacy) of an encrypted message this pass reads. */
    private fun rememberDecryptedTextKeys(
        into: MutableMap<String, MutableSet<String>>,
        messageId: String,
        convId: String?,
        wireCiphertext: String,
    ) {
        if (convId == null || !CiphertextWireFormat.isRatcheted(wireCiphertext)) return
        into.getOrPut(messageId) { mutableSetOf() } +=
            listOf(
                DecryptedTextCacheKey.of(convId, wireCiphertext),
                DecryptedTextCacheKey.legacyOf(wireCiphertext),
                // ZC-1792: the row-bound text an earlier root opened (OldRootFallback) expires with the row too.
                DecryptedTextCacheKey.ofRow(convId, messageId, wireCiphertext),
            )
    }

    /** ZC-1792 (W-142, P-A): the row [tx] for [OldRootFallback] in [pass], or null when it is not mined. */
    private fun oldRootRowOf(
        pass: OldRootFallback.Pass,
        messageId: String,
        tx: Transaction,
        fromContact: Boolean,
    ): OldRootFallback.Row? =
        tx.overview.minedHeight
            ?.value
            ?.takeIf { it > 0L }
            ?.let { OldRootFallback.Row(pass, messageId, it, fromContact) }

    /** ZC-1792: the contact's Quantum Shield PSK as the current root mixes it, or null. */
    private fun pskOf(peerAddress: String): ByteArray? {
        val pskBase64 = zchatPreferences.getQuantumShieldPSK(peerAddress) ?: return null
        return Base64.getDecoder().decode(pskBase64)
    }

    /**
     * ZC-1792 (W-142, P-A) after the current root failed [row]: its row-bound text, or (with [open]) the earlier root's
     * reading of it, or null. ZC-1823: called only from the current root's replay and AEAD catches. ZC-1825: a failure in
     * here (a corrupt preference, a decode) is null, so the row keeps its placeholder as every failure of
     * [tryDecryptMessage] does; a cancellation is rethrown.
     */
    @Suppress("TooGenericExceptionCaught")
    private suspend fun oldRootTextAfterFailure(
        content: String,
        peerAddress: String,
        convId: String,
        row: OldRootFallback.Row,
        open: Boolean,
    ): String? =
        try {
            storedOldRootText(content, convId, row)
                ?: if (open) openWithOldRoot(content, peerAddress, convId, row) else null
        } catch (e: kotlinx.coroutines.CancellationException) {
            throw e
        } catch (e: Exception) {
            Log.w("ZCHAT_E2E", "Earlier-root read failed for ${peerAddress.redactAddress()}: ${e.javaClass.simpleName}")
            null
        }

    /** ZC-1792 (W-142, P-A): the text [OldRootFallback] stored for [row] earlier ([DecryptedTextCacheKey.ofRow]), or null. */
    private fun storedOldRootText(
        content: String,
        convId: String,
        row: OldRootFallback.Row,
    ): String? =
        zchatPreferences
            .getDecryptedText(DecryptedTextCacheKey.ofRow(convId, row.txid, content))
            ?.takeUnless { CiphertextWireFormat.isRatcheted(it) }
            ?.also { row.markOpened() }

    /**
     * ZC-1792 (W-142, P-A): [content] of [row] under the root as it stood at the row's height, or null. Receive only:
     * the ratchet store, the floors and the processors are not touched; the text is stored under the row-bound key
     * ([DecryptedTextCacheKey.ofRow]), never the envelope key, so a later copy of the envelope is not answered from it.
     */
    private suspend fun openWithOldRoot(
        content: String,
        peerAddress: String,
        convId: String,
        row: OldRootFallback.Row,
    ): String? {
        val rowKey = DecryptedTextCacheKey.ofRow(convId, row.txid, content)
        val envelope = CiphertextWireFormat.parse(content) ?: return null
        val plaintext =
            withPeerSession(peerAddress) {
                val ecdh = getE2ESharedKey(peerAddress) ?: return@withPeerSession null
                val ourPub = zchatPreferences.getE2EOurPublicKey(peerAddress) ?: return@withPeerSession null
                val peerPub = zchatPreferences.getE2EPeerPublicKey(peerAddress) ?: return@withPeerSession null
                OldRootFallback.openRow(
                    row = row,
                    peer = peerAddress,
                    envelope = envelope,
                    headerConvId = convId,
                    ecdhSharedSecret = ecdh,
                    psk = pskOf(peerAddress),
                    isLower = ourPub < peerPub,
                    kexTxids = zchatPreferences.getKexTxIds(peerAddress),
                    kexScalar = zchatPreferences.getE2EKexTxId(peerAddress),
                    kexAckTxids = zchatPreferences.getKexAckTxIds(peerAddress),
                    kexAckScalar = zchatPreferences.getE2EKexAckTxId(peerAddress),
                    upgrades = ChainTiming.current,
                )
            }?.toString(Charsets.UTF_8) ?: return null
        if (CiphertextWireFormat.isRatcheted(plaintext)) return null
        zchatPreferences.putDecryptedText(rowKey, plaintext)
        return plaintext
    }

    /**
     * Send-time plaintext SELF-cache (recoverability). The decrypt path above seeds the L1/L2
     * decrypted-text cache only on a successful DECRYPT, so a sender's ability to read their OWN
     * mined message on rescan depended entirely on re-deriving its key from ratchet state — if that
     * state is ever lost or desynced (wipe/restore, one-sided reset), the sender couldn't read the
     * message they themselves wrote. Seed the SAME two caches, keyed by the SAME
     * [co.electriccoin.zcash.ui.screen.chat.crypto.DecryptedTextCacheKey] sha256(convId:wire) the decrypt
     * path uses, the moment the outgoing E2E1 ciphertext is produced — so a sender's own message is
     * always readable from cache, ratchet or not. The L2 row lives in the SAME
     * EncryptedSharedPreferences store/key space as decrypt-path rows (still encrypted at rest), so
     * every existing lifecycle rule — destroy-wipe (clearAll), poison-scrub, any TTL/disappearing
     * (D11) sweep of that store — covers self-cached rows identically.
     */
    private fun cacheOwnOutgoingPlaintext(convId: String, wireCiphertext: String, plaintext: String) {
        // Only a real ratcheted envelope gets a row, and a raw E2E1 blob must never be stored AS
        // the plaintext (mirrors tryDecryptMessage's cache-poison guard).
        if (!co.electriccoin.zcash.ui.screen.chat.crypto.ratchet.CiphertextWireFormat.isRatcheted(wireCiphertext)) return
        if (co.electriccoin.zcash.ui.screen.chat.crypto.ratchet.CiphertextWireFormat.isRatcheted(plaintext)) return
        val key = co.electriccoin.zcash.ui.screen.chat.crypto.DecryptedTextCacheKey.of(convId, wireCiphertext)
        decryptedTextCache[key] = plaintext
        zchatPreferences.putDecryptedText(key, plaintext)
    }

    // ==========================================
    // KEX (Key Exchange) PROTOCOL
    // ==========================================

    /** ZC-545 — who runs [adoptKeyOffer]. */
    private enum class KeyOfferMode {
        /** The inbound handler ([handleKEXMessage]): stores nothing while a refused key is remembered (R8). */
        LIVE,

        /** The accept's own adoption ([adoptRefusedKey]): the only writer allowed while a record exists. */
        ACCEPT,

        /** Read only: stops before the first write and answers the resolved sender and key. */
        DRY_RUN,
    }

    /** ZC-545 — what [adoptKeyOffer] did with a KEX or KEXACK memo. */
    private sealed interface KeyOfferOutcome {
        /** Not a key offer this call may act on (unparsable, unverified, another contact or key): nothing changed. */
        data object Ignored : KeyOfferOutcome

        /** A changed key, refused: flagged, verification dropped, the offer remembered or counted. Nothing stored. */
        data object Refused : KeyOfferOutcome

        /** [KeyOfferMode.DRY_RUN]: the memo verifies and is [key] from [peer]. Nothing was written. */
        data class Resolved(
            val peer: String,
            val key: String,
        ) : KeyOfferOutcome

        /**
         * [key] is stored as [peer]'s key; [nostrPubkeyHex] and [relayUrl] are what the memo carried, if anything. ZC-634:
         * [claim] whether the key is (still) only a claim; [releasedBoot] the ZBOOT the claim mark held back, when this
         * memo was the proof that released it (handed on by the caller).
         */
        data class Stored(
            val peer: String,
            val key: String,
            val convId: String,
            val nostrPubkeyHex: String?,
            val relayUrl: String?,
            val claim: Boolean = false,
            val releasedBoot: String? = null,
        ) : KeyOfferOutcome
    }

    /**
     * ZC-545 (G3, G5, G6, R8) — the store part of a KEX or KEXACK ([memoText]; [receivedTxId] its transaction): resolve
     * the sender (and map a genuinely new conversation id), verify the self-signature, apply the key-change guard, store
     * the contact's key and the txid scalar. It sends and pays nothing: the KEXACK, the responder marker and our ZBOOT
     * are the live handler's reply part ([handleKEXMessage]).
     *
     * It does not suspend and runs whole under [peerKeyMonitor], so no other writer of a contact's key and no accept
     * interleaves between reading the stored key and storing one.
     *
     * - [KeyOfferMode.LIVE]: a key that differs from the stored one is refused as before (flag, verification dropped)
     *   and now remembered ([ZchatPreferences.rememberRefusedKeyOffer]: the first one is the record, a later different
     *   one is only counted). While a record exists NO key is stored, also when none is stored (an accept was
     *   interrupted after its wipe): the offer is refused the same way, and no conversation id is mapped for it.
     * - [KeyOfferMode.ACCEPT]: the accept's adoption of the remembered memo, right after its wipe in the same section.
     * - [KeyOfferMode.DRY_RUN]: verifies and resolves only.
     *
     * [expectedPeer] and [expectedKey] (the accept and its dry run) make it answer [KeyOfferOutcome.Ignored], before any
     * write, for a memo that resolves to another contact or carries another key.
     */
    @Suppress("CyclomaticComplexMethod", "LongMethod", "ReturnCount", "NestedBlockDepth")
    private fun adoptKeyOffer(
        memoText: String,
        receivedTxId: String?,
        expectedPeer: String?,
        expectedKey: String?,
        mode: KeyOfferMode,
    ): KeyOfferOutcome =
        adoptKeyOffer(
            memoText,
            receivedTxId,
            expectedPeer,
            expectedKey,
            mode,
            minedHeight = null,
            historyUnread = null,
            unreadInPass = null,
        )

    /**
     * [adoptKeyOffer] with the memo's mined height ([minedHeight], null: not known) and whether the key store had not yet
     * finished its first complete history read when the offer was handed over ([historyUnread]; null: ask the store now),
     * for the W-72 restore rule. [unreadInPass] (ZC-1129) is whether the history pass that handed the offer over skipped an
     * old received transaction ([oldInboundUnreadInPass] as that pass set it; null: read the flag now).
     */
    private fun adoptKeyOffer(
        memoText: String,
        receivedTxId: String?,
        expectedPeer: String?,
        expectedKey: String?,
        mode: KeyOfferMode,
        minedHeight: Long?,
        historyUnread: Boolean?,
        unreadInPass: Boolean?,
    ): KeyOfferOutcome {
        // W-72 (ZC-852, SPEC_F R2, SPEC_DECISIONS D2): a key stored for the first time from a memo mined at or below the
        // upgrade height, or handed over before this key store's first complete history read (a restore), gets a mark.
        val legacyRule = minedAtOrBeforeUpgrade(minedHeight) || (historyUnread ?: (zchatPreferences.isLegacyHistoryRead() == false))
        return synchronized(peerKeyMonitor) {
            when {
                ZMSGProtocol.isKEXMessage(memoText) -> {
                    val parsed = ZMSGProtocol.parseKEXMessage(memoText) ?: return KeyOfferOutcome.Ignored
                    val (convId, kexPayload) = parsed

                    // OPEN-INBOX first contact (TOFU): resolve via an existing convId→peer mapping when
                    // we initiated; otherwise recover the sender's claimed address from the KEX payload
                    // so anyone with our (public) address can start a conversation we can reply to.
                    // SECURITY MODEL: this is trust-on-first-use, NOT proof of address control. The
                    // claimed address is NOT verified — but replying is still safe because our reply is
                    // sent on-chain TO that claimed address (a forger who claimed someone else's address
                    // cannot receive the reply). The residual risk is inbound spoofing, mitigated by (a)
                    // the conversation being UNVERIFIED until the user checks the safety number, and (b)
                    // the key-change warning below firing if an established contact's key ever differs.
                    val mappedSender = zchatPreferences.getPeerByConversationId(convId)
                    val senderAddress: String =
                        if (mappedSender != null) {
                            mappedSender
                        } else {
                            val recoveredKex = E2EEncryption.parseKEXPayloadFull(kexPayload, null)
                            val recovered = recoveredKex?.senderAddress
                            if (recovered == null) {
                                Log.w("KEX", "Cannot process KEX - no convId mapping and no address in payload: $convId")
                                return KeyOfferOutcome.Ignored
                            }
                            // R2-2 (a): the claimed address is ours, or not a valid mainnet Unified Address —
                            // nothing to answer and nothing to store (the scan never maps these either).
                            if (!mayOfferInboundChat(recovered)) {
                                Log.w("KEX", "KEX claims our own or an invalid address — ignored, nothing stored or sent")
                                return KeyOfferOutcome.Ignored
                            }
                            // ZC-545: the accept (and its dry run) is for one contact and one key; nothing is mapped
                            // for any other.
                            if (expectedPeer != null && recovered != expectedPeer) return KeyOfferOutcome.Ignored
                            if (expectedKey != null && recoveredKex.publicKey != expectedKey) return KeyOfferOutcome.Ignored
                            // SECURITY: only REMAP the outbound convId for a GENUINELY-NEW peer. A self-signed
                            // KEX carrying an ESTABLISHED peer P's address + a fresh unmapped convId is
                            // attacker-forgeable; without this check it would overwrite peer:P→convId and break
                            // our outbound threading to the real contact (the key-change guard below already
                            // refuses the key, but the remap persisted). If we already hold P's E2E key this is
                            // NOT first contact — process for the key-change flag but DON'T trust the convId.
                            // ZC-545 (R8): nor while a refused key waits for the user (no key may be stored then,
                            // although an interrupted accept can have left none); the accept's own adoption maps.
                            val mayMap =
                                mode != KeyOfferMode.DRY_RUN &&
                                    zchatPreferences.getE2EPeerPublicKey(recovered) == null &&
                                    (mode == KeyOfferMode.ACCEPT || !refusedKeyWaits(recovered))
                            if (mayMap) {
                                zchatPreferences.setConversationId(recovered, convId)
                                // New peer stays UNVERIFIED by default (isE2EVerified is only set via an
                                // explicit out-of-band markE2EVerified) — the UI surfaces that state.
                                Log.d("KEX", "Open-inbox first contact — recovered sender ${recovered.redactAddress()} (UNVERIFIED)")
                            } else if (mode != KeyOfferMode.DRY_RUN) {
                                Log.w(
                                    "KEX",
                                    "KEX for ESTABLISHED ${recovered.redactAddress()} carried an unmapped convId — NOT remapping " +
                                        "(unauthenticated); key-change guard applies",
                                )
                            }
                            recovered
                        }
                    if (expectedPeer != null && senderAddress != expectedPeer) return KeyOfferOutcome.Ignored

                    // Verify and extract public key (+ optional NOSTR fields for one-tap calling).
                    // Verify against the convId-mapped address first; fall back to the SELF-SIGNED
                    // payload address if that fails — the peer may sign with a different valid
                    // representation of its own UA than we have stored (see the KEXACK path for the
                    // full rationale; key-change TOFU still guards against a real MITM).
                    val parsedKex =
                        E2EEncryption.parseKEXPayloadFull(kexPayload, senderAddress)
                            ?: E2EEncryption.parseKEXPayloadFull(kexPayload, null)
                    if (parsedKex == null) {
                        Log.e("KEX", "KEX signature verification FAILED for ${senderAddress.redactAddress()}")
                        return KeyOfferOutcome.Ignored
                    }
                    val peerPublicKey = parsedKex.publicKey
                    if (expectedKey != null && peerPublicKey != expectedKey) return KeyOfferOutcome.Ignored

                    Log.d("KEX", "KEX verified from ${senderAddress.redactAddress()} - storing pubkey")

                    // SECURITY (self-signed-KEX key substitution): the KEX signature is verified against
                    // the payload's OWN pubkey (a self-signature), so it does NOT authenticate the sender
                    // as the ALREADY-ESTABLISHED peer — an attacker who can attribute a KEX to this
                    // conversation (e.g. reusing the on-chain convId) can self-sign a SUBSTITUTE key.
                    // REFUSE to auto-overwrite an established key.
                    // Flag the change for the banner and KEEP the old key so the real peer still decrypts
                    // and no silent MITM lands; do NOT derive a root or send a KEXACK to the unauthenticated
                    // key, and do NOT clear the sent-KEXACK marker (that would let the attacker's flood
                    // re-spend ZEC on paid KEXACKs — B5). A genuine reinstall re-establishes via user-
                    // initiated Reset Encryption, which clears the key so the next KEX is first-contact.
                    val previousPubkey = zchatPreferences.getE2EPeerPublicKey(senderAddress)
                    if (zchatPreferences.isSelfAddress(senderAddress)) {
                        Log.w("KEX", "KEX attributed to our own address — ignored, nothing stored or sent")
                        return KeyOfferOutcome.Ignored
                    }
                    if (mode == KeyOfferMode.DRY_RUN) return KeyOfferOutcome.Resolved(senderAddress, peerPublicKey)
                    // ZC-634 (5.5 item 2 b): read before anything below writes them.
                    val begunHere =
                        zchatPreferences.getE2EOurPublicKey(senderAddress) != null || zchatPreferences.isE2EEnabled(senderAddress)
                    var holdSetNow = false
                    if (mode == KeyOfferMode.ACCEPT) {
                        // The accept's wipe ran in this same section: only the accepted key itself can be stored
                        // already (an earlier, interrupted accept). Anything else is not this accept's to overwrite.
                        if (previousPubkey != null && previousPubkey != peerPublicKey) return KeyOfferOutcome.Ignored
                    } else if (mode == KeyOfferMode.LIVE) {
                        // ZC-545 (R8): while a refused key waits for the user, nothing but the accept stores a key.
                        val waits = refusedKeyWaits(senderAddress)
                        if (waits && previousPubkey == peerPublicKey) {
                            Log.d("KEX", "KEX repeats the stored key while a new key waits for the user — nothing to do")
                            return KeyOfferOutcome.Ignored
                        }
                        if (waits || (previousPubkey != null && previousPubkey != peerPublicKey)) {
                            Log.w(
                                "KEX",
                                "PEER KEY CHANGED for ${senderAddress.redactAddress()} — refusing auto-overwrite (self-signed KEX " +
                                    "can't authenticate an established peer); flagged for re-verify",
                            )
                            // ZC-545 (G5): the first refused key is remembered for the user's decision; a later
                            // different one is only counted. The flag is raised in the record's own commit.
                            zchatPreferences.rememberRefusedKeyOffer(
                                senderAddress,
                                peerPublicKey,
                                memoText,
                                receivedTxId,
                                System.currentTimeMillis(),
                            )
                            zchatPreferences.setE2EKeyChanged(senderAddress, true)
                            // A key change invalidates any prior out-of-band verification.
                            zchatPreferences.setE2EVerified(senderAddress, false)
                            return KeyOfferOutcome.Refused
                        }

                        // R2-2 (a) — a KEX from an address we have no chat with is a chat REQUEST. Anyone who knows
                        // our address can send one, so answering it at once let a stranger make us pay a KEXACK
                        // (about 17,000 zatoshi) per KEX, up to the budget, with nothing on screen. Its key is
                        // stored (so the chat can be shown and accepted) but nothing is paid until the user taps
                        // Accept ([acceptInboundKexRequest]); an invalid address is not offered at all. "No chat"
                        // is read before this KEX writes anything: no key of ours for them, E2E never turned on
                        // for them. ZC-822 (W-52): a saved contact is no exception (the sender address is claimed). A
                        // convId mapping is no signal (the history scan maps a stranger's KEX convId before this runs).
                        val firstContact = isFirstKeyExchange(senderAddress)
                        if (firstContact && !mayOfferInboundChat(senderAddress)) {
                            Log.w("KEX", "First-contact KEX from an invalid address — ignored, nothing stored or sent")
                            return KeyOfferOutcome.Ignored
                        }
                        // W-62 (owner, ZC-599): a key exchange that claims the contact this phone began a secure chat with and
                        // still waits for (our key pair, no contact key yet) is not answered by itself either: the paid answer
                        // waits for Accept, whose banner shows its price. Nothing is paid before the tap.
                        // ZC-634 (review T7aD/T7a 19 Oct, finding 1): also where E2E is on and our key pair is not made yet
                        // (setE2EEnabled before the key pair, a Reset's wipe): the reply part would make it and pay the answer.
                        // ZC-599 (re-review 26 Oct, finding 2): also where the stored key is the one this key exchange repeats
                        // and it is only a claim (an answer leg 2 took under an id not ours, never proven by leg 1 or Accept):
                        // a stranger's answer claiming the awaited contact must not let its key exchange skip the tap.
                        // ZC-599 (money recheck 26 Oct, finding 1): likewise a stored key only an old answer with no own key
                        // exchange behind it brought (no asked record), even where our key pair stands.
                        val awaited =
                            !firstContact &&
                                (
                                    previousPubkey == null ||
                                        (
                                            previousPubkey == peerPublicKey &&
                                                (
                                                    zchatPreferences.getKeyClaim(senderAddress) != null ||
                                                        oldAnswerKeyUnasked(
                                                            senderAddress,
                                                            peerPublicKey,
                                                            unreadInPass ?: oldInboundUnreadInPass,
                                                        )
                                                )
                                        )
                                ) &&
                                (
                                    zchatPreferences.getE2EOurPublicKey(senderAddress) != null ||
                                        zchatPreferences.isE2EEnabled(senderAddress)
                                )
                        if ((firstContact || awaited) && zchatPreferences.getSentKexAckPubkey(senderAddress) != peerPublicKey) {
                            // GPT-6 F3: a hold that was not saved is gone after a restart while the key stored
                            // below would stay, and the KEXACK would then be paid with no Accept. Store nothing.
                            if (!zchatPreferences.setInboundKexAwaitingAccept(senderAddress, peerPublicKey)) {
                                Log.w("KEX", "First-contact KEX: the Accept hold could not be saved — nothing stored or sent")
                                return KeyOfferOutcome.Ignored
                            }
                            holdSetNow = true
                            Log.d("KEX", "First-contact KEX from ${senderAddress.redactAddress()} — waits for Accept, nothing paid")
                        }
                    }

                    // First contact (TOFU) or a repeat of the same key — safe to store. ZC-634 (FC-5, 5.5 item 2): with its claim
                    // mark and (for a key the user accepted, ZC-893) its asked record, in one commit of the key store; a commit
                    // that is not saved stores nothing, and the memo is ignored as when the hold is not saved.
                    val claim =
                        keyExchangeKeyIsClaim(
                            senderAddress,
                            peerPublicKey,
                            previousPubkey,
                            begunHere = begunHere,
                        )
                    val askedNow = mode == KeyOfferMode.ACCEPT
                    val legacyNow = legacyRule && previousPubkey != peerPublicKey
                    if (!zchatPreferences.storePeerKey(senderAddress, peerPublicKey, claim, askedNow, legacyNow)) {
                        // ZC-1070 (a): the hold this memo set stays: a commit that was not saved may still sit in the store's
                        // memory, and with the hold nothing is paid for that key without the tap.
                        Log.w("KEX", "KEX from ${senderAddress.redactAddress()}: its key could not be saved — nothing sent")
                        return KeyOfferOutcome.Ignored
                    }
                    if (receivedTxId != null) {
                        // Legacy scalar only; the convergent set is recomputed from the chain scan in
                        // convertToConversations (this once-ever receive path can't populate it reliably).
                        // Mined only: an unmined KEX is never acted on (RestoreKexPolicy.mayActOnInboundHandshake).
                        zchatPreferences.setE2EKexTxId(senderAddress, receivedTxId)
                    }
                    // The accept has no reply part: the relay fields a memo carried are bound here. ZC-634 (5.5 item 5): not
                    // at an address with a hold or a claim mark.
                    if (mode == KeyOfferMode.ACCEPT &&
                        !claim &&
                        zchatPreferences.getInboundKexAwaitingAccept(senderAddress) == null &&
                        zchatPreferences.getLegacyKeyMark(senderAddress) == null &&
                        // W-72 (SPEC_DECISIONS D6): a key accepted over a pre-update mark is stored as a claim by the store.
                        zchatPreferences.getKeyClaim(senderAddress) == null
                    ) {
                        applyKEXNostr(senderAddress, parsedKex.nostrPubkeyHex, parsedKex.relayUrl)
                    }
                    KeyOfferOutcome.Stored(
                        senderAddress,
                        peerPublicKey,
                        convId,
                        parsedKex.nostrPubkeyHex,
                        parsedKex.relayUrl,
                        claim = claim,
                    )
                }

                ZMSGProtocol.isKEXAckMessage(memoText) -> {
                    val parsed = ZMSGProtocol.parseKEXAckMessage(memoText) ?: return KeyOfferOutcome.Ignored
                    val (convId, kexAckPayload) = parsed

                    // Resolve the sender AND verify the signature. With a known convId→peer mapping
                    // we verify against THAT address first (tightest binding). BUT a peer may sign its
                    // KEXACK with a DIFFERENT valid representation of its own unified address than the
                    // one we have stored for it (diversifier / derivation drift across reinstalls or
                    // SDK upgrades) — the signature binds (senderAddress||pubkey), so a representation
                    // mismatch makes the mapped-address verify FAIL even though the wire is perfectly
                    // self-consistent. That was a real first-contact-breaking bug: Honor's KEXACK was
                    // signed with its current self-address but Seeker had an older representation →
                    // "KEXACK signature verification FAILED" forever → the tunnel never completed.
                    // So fall back to verifying against the SELF-SIGNED payload address (pass null),
                    // exactly what the KEX path already does for first contact. Security is unchanged:
                    // the E2E key-change guard below flags a genuine key swap (MITM), and the key is
                    // TOFU-bound — address binding was never the actual protection.
                    val mappedSender = zchatPreferences.getPeerByConversationId(convId)
                    val parsedAck =
                        E2EEncryption.parseKEXAckPayloadFull(kexAckPayload, mappedSender)
                            ?: E2EEncryption.parseKEXAckPayloadFull(kexAckPayload, null)
                    if (parsedAck == null) {
                        Log.e("KEX", "KEXACK signature verification FAILED (convId=$convId)")
                        return KeyOfferOutcome.Ignored
                    }
                    if (mappedSender != null && parsedAck.senderAddress != null && parsedAck.senderAddress != mappedSender) {
                        Log.d(
                            "KEX",
                            "KEXACK signed with a different self-address representation than stored for convId=$convId — " +
                                "accepted via payload-address verify (key TOFU still applies)",
                        )
                    }
                    // Known mapping wins; otherwise use the address recovered+verified from the wire.
                    val senderAddress = mappedSender ?: parsedAck.senderAddress
                    if (senderAddress == null) {
                        Log.w("KEX", "Cannot process KEXACK - unknown conversation ID $convId and no recoverable signed address")
                        return KeyOfferOutcome.Ignored
                    }
                    val peerPublicKey = parsedAck.publicKey
                    // ZC-545: the accept (and its dry run) is for one contact and one key; checked before any write.
                    if (expectedPeer != null && senderAddress != expectedPeer) return KeyOfferOutcome.Ignored
                    if (expectedKey != null && peerPublicKey != expectedKey) return KeyOfferOutcome.Ignored
                    if (mode == KeyOfferMode.DRY_RUN) return KeyOfferOutcome.Resolved(senderAddress, peerPublicKey)
                    if (mappedSender == null) {
                        // First-contact / lost-mapping recovery: re-establish convId→peer so the ack lands.
                        // SECURITY: a KEXACK is only self-signed (verified against the payload's OWN pubkey),
                        // so it can't authenticate the sender as an ALREADY-ESTABLISHED peer. Only REMAP the
                        // outbound convId when this is genuinely first contact (no key held) OR the KEXACK's
                        // key MATCHES the key we already hold for this peer — the legitimate #205 case where
                        // an established peer re-KEXes under a drifted/unmapped convId and its TOFU key still
                        // matches, so the sender really is P. A self-signed KEXACK carrying an ESTABLISHED
                        // peer P's address + a fresh unmapped convId but a DIFFERENT key is attacker-forgeable:
                        // remapping it would overwrite peer:P→attacker-convId and break outbound threading. The
                        // key-change guard below refuses the substitute key, but the convId remap would already
                        // have persisted — gate it here too (symmetric with that guard's getE2EPeerPublicKey).
                        // ZC-545 (R8): nor while a refused key waits for the user; the accept's own adoption maps.
                        val heldKey = zchatPreferences.getE2EPeerPublicKey(senderAddress)
                        val mayMap =
                            E2EEncryption.mayRemapConvIdForKexAck(heldKey, parsedAck.publicKey) &&
                                (mode == KeyOfferMode.ACCEPT || !refusedKeyWaits(senderAddress))
                        if (mayMap) {
                            zchatPreferences.setConversationId(senderAddress, convId)
                            Log.d("KEX", "KEXACK first-contact recovery: mapped convId $convId → ${senderAddress.redactAddress()}")
                        } else {
                            Log.w(
                                "KEX",
                                "KEXACK for ESTABLISHED ${senderAddress.redactAddress()} carried an unmapped convId with a " +
                                    "DIFFERENT key — NOT remapping (unauthenticated); key-change guard applies",
                            )
                        }
                    }

                    Log.d("KEX", "KEXACK verified from ${senderAddress.redactAddress()} - key exchange complete!")

                    // Detect key change — SAME self-signature guard as the KEX path above. A KEXACK is
                    // self-signed too (verified against the payload's own pubkey), so it cannot authenticate
                    // an already-established peer; REFUSE to auto-overwrite (flag + keep old key + return),
                    // and a genuine reinstall re-establishes via user-initiated Reset Encryption.
                    val prevPub = zchatPreferences.getE2EPeerPublicKey(senderAddress)
                    if (mode == KeyOfferMode.ACCEPT) {
                        if (prevPub != null && prevPub != peerPublicKey) return KeyOfferOutcome.Ignored
                    } else if (mode == KeyOfferMode.LIVE) {
                        // ZC-545 (R8): while a refused key waits for the user, nothing but the accept stores a key.
                        val waits = refusedKeyWaits(senderAddress)
                        if (waits && prevPub == peerPublicKey) {
                            Log.d("KEX", "KEXACK repeats the stored key while a new key waits for the user — nothing to do")
                            return KeyOfferOutcome.Ignored
                        }
                        if (waits || (prevPub != null && prevPub != peerPublicKey)) {
                            Log.w(
                                "KEX",
                                "PEER KEY CHANGED via KEXACK for ${senderAddress.redactAddress()} — refusing auto-overwrite " +
                                    "(self-signed); flagged for re-verify",
                            )
                            // ZC-545 (G5): remembered for the user's decision (see the KEX branch).
                            zchatPreferences.rememberRefusedKeyOffer(
                                senderAddress,
                                peerPublicKey,
                                memoText,
                                receivedTxId,
                                System.currentTimeMillis(),
                            )
                            zchatPreferences.setE2EKeyChanged(senderAddress, true)
                            // A key change invalidates any prior out-of-band verification.
                            zchatPreferences.setE2EVerified(senderAddress, false)
                            return KeyOfferOutcome.Refused
                        }
                    }

                    // First contact (TOFU) or a repeat of the same key — safe to store. ZC-599 (5.4 item 5): an answer reaches
                    // this branch only when this phone asked for it (the pass's legs): the key it carries was taken on purpose
                    // (the asked record). ZC-634 (FC-5, 5.5 items 2 c and 6): a first key a leg 2 answer brought is a claim; a
                    // leg 1 answer that carries the stored key is the proof, and releases a mark with the ZBOOT it held back.
                    // One commit of the key store; a commit that is not saved stores nothing and the memo is ignored.
                    val leg = receivedTxId?.let { answerLegByTx[it] }
                    val markBefore = zchatPreferences.getKeyClaim(senderAddress)
                    val proofOffered =
                        mode == KeyOfferMode.LIVE && leg == AnswerVerdict.LEG1 && prevPub == peerPublicKey && markBefore != null
                    // Recheck of the review fixes (items 1 and 2): the key is stored first, with the mark as it stands now (a
                    // "Mark as verified" tap takes peerKeyMonitor too, so it cannot land in between), and only a saved commit
                    // lets the proof release the mark; the release hands back its held ZBOOT in the same store call.
                    val claim =
                        when {
                            proofOffered -> zchatPreferences.getKeyClaim(senderAddress) != null
                            prevPub == peerPublicKey && mode == KeyOfferMode.LIVE -> markBefore != null
                            mode == KeyOfferMode.ACCEPT -> leg != AnswerVerdict.LEG1 && leg != AnswerVerdict.LEG3
                            else -> leg == AnswerVerdict.LEG2
                        }
                    val legacyNow = legacyRule && prevPub != peerPublicKey
                    // ZC-599 (re-review 26 Oct, finding 1; money recheck 26 Oct, finding 1): an old answer with no own key
                    // exchange to that address at or below it is stored without the asked record, whether or not a key pair
                    // of ours stands there (see [takeAskedAnswer]).
                    val asked =
                        !(
                            mode == KeyOfferMode.LIVE &&
                                leg == AnswerVerdict.LEG3 &&
                                receivedTxId in unbackedOldAnswerTx
                        )
                    if (!zchatPreferences.storePeerKey(senderAddress, peerPublicKey, claim, asked = asked, legacy = legacyNow)) {
                        Log.w("KEX", "KEXACK from ${senderAddress.redactAddress()}: the contact key could not be saved — nothing stored")
                        return KeyOfferOutcome.Ignored
                    }
                    val released = if (proofOffered && claim) zchatPreferences.releaseKeyClaim(senderAddress, verified = false) else null
                    val proof = released != null
                    val heldBoot = released?.takeIf { it.isNotEmpty() }
                    if (proof) Log.d("KEX", "KEXACK under our own id carries the claimed key of ${senderAddress.redactAddress()}: released")
                    if (receivedTxId != null) {
                        // Legacy scalar only; convergent set is recomputed in convertToConversations.
                        // Mined only: an answer is judged only once it is mined (ZC-599/ZC-941, judgeAnswer).
                        zchatPreferences.setE2EKexAckTxId(senderAddress, receivedTxId)
                    }
                    // Receiving a KEXACK means WE were the KEX initiator and the exchange is now
                    // complete (we hold the peer's key + our own). Enable E2E here — the KEX-received
                    // path does this for the responder, but the initiator only ever sees a KEXACK, so
                    // without this an initiator-only peer was left e2eEnabled=false → its ratchet
                    // processor stayed null → it couldn't encrypt/decrypt (and the header showed "Off")
                    // even though the handshake succeeded. (#bug-e2e-initiator-enable)
                    zchatPreferences.setE2EEnabled(senderAddress, true)
                    // The accept has no reply part: the relay fields a memo carried are bound here (ZC-634, 5.5 item 5: not for a
                    // claim).
                    if (mode == KeyOfferMode.ACCEPT &&
                        !claim &&
                        zchatPreferences.getKeyClaim(senderAddress) == null &&
                        (leg == AnswerVerdict.LEG1 || zchatPreferences.getLegacyKeyMark(senderAddress) == null)
                    ) {
                        applyKEXNostr(senderAddress, parsedAck.nostrPubkeyHex, parsedAck.relayUrl)
                    }
                    KeyOfferOutcome.Stored(
                        senderAddress,
                        peerPublicKey,
                        convId,
                        parsedAck.nostrPubkeyHex,
                        parsedAck.relayUrl,
                        claim = claim,
                        releasedBoot = heldBoot,
                    )
                }

                else -> KeyOfferOutcome.Ignored
            }
        }
    }

    /**
     * ZC-634 (FC-5; FIRST-CONTACT-SPEC 5.5 items 2 and 2a) — whether [key], which a key exchange brings to [peer], is stored
     * as a claim. A repeat of the stored key keeps what stands. A first key ([previous] null, or the accept's wipe just
     * removed it) is a claim (a) where a relay key is bound, with a hold or without; (b) where this phone has itself begun
     * a secure chat there ([begunHere]: a key pair of ours or E2E switched on), also beside the W-62 hold (review of part
     * B, finding 1: the Accept tap releases the hold, never the mark; our own-id answer, leg 1, does); and where this
     * wallet's own mined answer answered it and that answer is not settled (A19). Never where that answer is settled. An
     * honest first contact (a hold, no relay key) gets none: the hold is the mark there, and Accept its release.
     */
    private fun keyExchangeKeyIsClaim(
        peer: String,
        key: String,
        previous: String?,
        begunHere: Boolean,
    ): Boolean {
        if (previous == key) return zchatPreferences.getKeyClaim(peer) != null
        val answered = ownAnswerVerdicts[peer]?.takeIf { it.key == key }
        if (answered != null) return !answered.settled
        if (zchatPreferences.getPeerNostrPubkey(peer) != null) return true
        return begunHere
    }

    /**
     * W-72 (SPEC_F R6, SPEC_DECISIONS D4) — a mined ordinary message from [peerAddress] that the ratchet opened with the
     * stored key, under [convId], at [minedHeight]. In the INIT form, under an id that address owns here (its `conv:` entry
     * names it) that is neither one of our own ids nor the chat's own one, above the upgrade height: the contact's probe,
     * which becomes the reply id.
     */
    private fun noteLegacyKeyEvidence(
        peerAddress: String,
        convId: String,
        isInit: Boolean,
        minedHeight: Long,
        ownSentMinedHeight: (String) -> Long?,
    ) {
        // W-72 (SPEC_F R5, R5n; SPEC_DECISIONS D7): the answer to our probe. Only under the probe id this phone made for
        // this address (own-id record and conv: both name it), mined above our earliest mined probe, opened by the ratchet
        // with the marked key (the caller's condition). Then the mark goes and its held ZBOOT is handed on (RELAY_ONLY).
        val probe = zchatPreferences.getLegacyProbe(peerAddress)
        if (probe != null &&
            probe == convId &&
            zchatPreferences.isOwnConversationId(convId, peerAddress) &&
            zchatPreferences.getPeerByConversationId(convId) == peerAddress
        ) {
            val probeMinedAt =
                zchatPreferences
                    .getLegacyProbeTxIds(peerAddress)
                    ?.split('\n')
                    ?.mapNotNull { ownSentMinedHeight(it) }
                    ?.minOrNull()
            if (probeMinedAt != null && minedHeight > probeMinedAt) clearLegacyMarkByAnswer(peerAddress)
            return
        }
        val probeOfTheirs =
            isInit &&
                zchatPreferences.getE2EPeerPublicKey(peerAddress) != null &&
                zchatPreferences.getPeerByConversationId(convId) == peerAddress &&
                !zchatPreferences.isOwnConversationId(convId, peerAddress) &&
                zchatPreferences.getConversationId(peerAddress) != convId &&
                ChainTiming.current.upgrade.let { it == null || minedHeight > it }
        if (probeOfTheirs) zchatPreferences.armReplyConversationId(peerAddress, convId, minedHeight)
    }

    /**
     * W-72 (SPEC_F R5, SPEC_DECISIONS D7) — the contact answered our probe: the pre-update mark goes (with its probe record,
     * not verified: only the user's tap sets that) in one store section that hands back the ZBOOT it held, which is then
     * handed to [routeIncomingBoot]: it verifies it against the now confirmed key and binds it; our reply goes over the
     * relays only. Nothing is paid.
     */
    private fun clearLegacyMarkByAnswer(peerAddress: String) {
        val held =
            zchatPreferences.releaseLegacyKeyWithBoot(peerAddress, verified = false) ?: run {
                Log.w("KEX", "The answer to our probe was read; the pre-update mark was not removed (the next pass tries again)")
                return
            }
        Log.d("KEX", "The answer to our probe confirmed ${peerAddress.redactAddress()}'s key; the pre-update mark is gone")
        if (held.isNotEmpty()) {
            // Review of 3426ade7d, finding 6: a claim mark that stands keeps the ZBOOT for its own release. ZC-1097 (as
            // ZC-1070 (c)): a claim released between the check and the hold ("Mark as verified", the proof) leaves an
            // unmarked contact's ZBOOT, handed on as with no claim, never dropped.
            val claimKeepsIt =
                zchatPreferences.getKeyClaim(peerAddress) != null &&
                    (zchatPreferences.holdClaimedBoot(peerAddress, held) || zchatPreferences.getKeyClaim(peerAddress) != null)
            if (!claimKeepsIt) {
                routeIncomingBoot(peerAddress, held, sealedByBoundKey = false, replyRule = ZbootOnChainRule.RELAY_ONLY)
            }
        }
    }

    /** W-72 (SPEC_F R4, SPEC_DECISIONS D4) — the id and form an on-chain ordinary message goes under, when not the chat's own. */
    private class LegacyRoute(
        val convId: String,
        val asInit: Boolean,
    )

    /**
     * W-72 (SPEC_F R4, R6; SPEC_DECISIONS D4, D5, D8) — for an on-chain ordinary message [text] to [peerAddress] (not a
     * control memo, not the chat's first message): the contact's probe id this phone has not answered (a plain reply under
     * it), else, while the contact's key carries a pre-update mark, our probe (the INIT under the probe id, made once and
     * reused) when the INIT form needs as many memos as the plain form, so the confirmed price is the price; else null.
     */
    private fun legacyOnChainRoute(
        peerAddress: String,
        text: String,
        self: String,
    ): LegacyRoute? {
        zchatPreferences.getReplyConversationId(peerAddress)?.let { return LegacyRoute(it, asInit = false) }
        if (zchatPreferences.getLegacyKeyMark(peerAddress) == null) return null
        val encrypted =
            zchatPreferences.getE2EOurPublicKey(peerAddress) != null && zchatPreferences.getE2EPeerPublicKey(peerAddress) != null
        val sameMemos =
            onChainMemoCountFor(text, encrypted, isInit = true, self = self) ==
                onChainMemoCountFor(text, encrypted, isInit = false, self = self)
        if (!sameMemos) return null
        val probe = zchatPreferences.startLegacyProbe(peerAddress) ?: return null
        return LegacyRoute(probe, asInit = true)
    }

    /**
     * W-72 (ZC-852, SPEC_F R2) — whether a memo mined at [minedHeight] is at or below the network's upgrade height (ZChat
     * 2.12.4 could not send on the chain after it). False when the height is not known and on a network with none.
     */
    private fun minedAtOrBeforeUpgrade(minedHeight: Long?): Boolean {
        val upgrade = ChainTiming.current.upgrade ?: return false
        return minedHeight != null && minedHeight <= upgrade
    }

    /**
     * ZC-545 (R1, R8) — whether a refused key of [peerAddress] waits for the user's decision. A record exists only while
     * the key-changed flag is up, so the flag is read first and the record only then.
     */
    private fun refusedKeyWaits(peerAddress: String): Boolean =
        zchatPreferences.isE2EKeyChanged(peerAddress) && zchatPreferences.getRefusedKeyOffer(peerAddress) != null

    /**
     * Handle incoming KEX or KEXACK messages.
     * - KEX: Verify signature, store peer pubkey, auto-enable E2E, send KEXACK
     * - KEXACK: Verify signature, store peer pubkey, mark exchange complete
     *
     * @param memoText The full memo containing the KEX message
     * @param ourAddress Our Zcash address (for sending KEXACK)
     * @param receivedTxId Transaction ID of the received KEX/KEXACK for root derivation
     */
    private fun handleKEXMessage(memoText: String, ourAddress: String, receivedTxId: String? = null) =
        handleKEXMessage(memoText, ourAddress, receivedTxId, mayActOnInboundHandshake = true)

    /** [handleKEXMessage] with no mined height known (the processed-KEX floor then never applies). */
    private fun handleKEXMessage(
        memoText: String,
        ourAddress: String,
        receivedTxId: String?,
        mayActOnInboundHandshake: Boolean,
    ) = handleKEXMessage(memoText, ourAddress, receivedTxId, mayActOnInboundHandshake, minedHeight = null)

    /**
     * [handleKEXMessage] as the history scan calls it. [mayActOnInboundHandshake] is
     * [co.electriccoin.zcash.ui.screen.chat.crypto.RestoreKexPolicy.mayActOnInboundHandshake] for this memo.
     * [minedHeight] is the transaction's mined height (null while unmined), for the processed-KEX floor (KI-24).
     */
    private fun handleKEXMessage(
        memoText: String,
        ourAddress: String,
        receivedTxId: String?,
        mayActOnInboundHandshake: Boolean,
        minedHeight: Long?,
    ) {
        // W-72 (review of 3426ade7d, finding 1): decided here, on the caller's thread, before the work is queued: the pass
        // records the complete read at its end, before the main thread runs what it queued.
        val historyUnread = zchatPreferences.isLegacyHistoryRead() == false
        // ZC-1129: likewise the skip flag of the pass that hands this offer over; a later pass may clear it before the main
        // thread runs this handler, and before it has put the old answer's key into the unbacked set.
        val unreadInPass = oldInboundUnreadInPass
        viewModelScope.launch {
            try {
                // KR-2 — a key offer (a KEX) the scan may not act on yet is left COMPLETELY
                // untouched: no processed-mark (a later pass must handle it), no key generation (it would
                // block recovery of our historical key), no KEXACK (the old device may already have paid it).
                if (!mayActOnInboundHandshake && !ZMSGProtocol.isKEXAckMessage(memoText)) {
                    Log.d("KEX", "Inbound key offer waits for the history scan to read our own history")
                    return@launch
                }
                // #201 anti-flap: a shielded wallet re-scans its ENTIRE history every sync. Without
                // per-txid dedup an OLD KEX tx (from a peer that has since rotated its key / reinstalled)
                // is re-handled on every pass → its now-superseded key differs from the stored one →
                // false "PEER KEY CHANGED" → the kexAckedKeys guard is cleared → a KEXACK is re-sent.
                // That churn perpetually LOCKS the single spendable note (every on-chain send then fails
                // "Insufficient balance (have 0)") and spams a false key-change alarm. Process each KEX/
                // KEXACK tx EXACTLY ONCE. Mark it consumed UP FRONT (atomic check-then-mark) so the N
                // concurrent re-scan invocations for one txid can't all slip past before any marks it,
                // and a slow KEXACK retry can't delay the mark. KEX/KEXACK handling is self-contained
                // (verify + store the key synchronously, before any send), so a thrown send is safely
                // best-effort (its own retry covers it; if the app dies the peer re-sends a NEW KEX with
                // a NEW txid). A genuine key rotation also arrives as a NEW tx → not skipped, still detected.
                // KI-24 part A: the store keeps 500 txids; one it has evicted is still processed when it was mined
                // at or below the store's height floor (never above the fully scanned height), so an old KEX is not
                // handled again (a false key change, or after a Reset an old key stored and a KEXACK paid for it).
                // The mark also gives a txid recorded before KI-24 its height, so its eviction can raise the floor.
                if (receivedTxId != null) {
                    val processed = zchatPreferences.hasProcessedKexTx(receivedTxId, minedHeight)
                    zchatPreferences.markKexTxProcessed(receivedTxId, minedHeight, fullyScannedTip())
                    if (processed) return@launch
                }
                when {
                    ZMSGProtocol.isKEXMessage(memoText) -> {
                        // ZC-545 (G3): the store part (resolve the sender, verify, the key-change guard, store the key and
                        // the txid) is [adoptKeyOffer]; the accept of a contact's new key runs the same code. What
                        // follows here is this handler's own reply part.
                        val stored =
                            adoptKeyOffer(
                                memoText,
                                receivedTxId,
                                expectedPeer = null,
                                expectedKey = null,
                                KeyOfferMode.LIVE,
                                minedHeight,
                                historyUnread,
                                unreadInPass,
                            )
                                as? KeyOfferOutcome.Stored ?: return@launch
                        val senderAddress = stored.peer
                        val peerPublicKey = stored.key
                        val convId = stored.convId
                        // ZC-1352: the contact wrote first (a new transaction): the normal rules decide from here.
                        userStartsSetupAgain(senderAddress)
                        // Durable RESPONDER marker: this branch runs ONLY for a RECEIVED KEX, so it is the
                        // one place that unambiguously means "we are the responder for this key". Gates the
                        // responder-side KEXACK retry (retryKexAckIfResponder) so the initiator never re-acks.
                        zchatPreferences.setReceivedKexPubkey(senderAddress, peerPublicKey)
                        // ZC-599 (5.4 item 4, FC-2a): every answer to this key exchange goes out under its id.
                        zchatPreferences.setReceivedKexConvId(senderAddress, convId)

                        // Generate our keys if needed (D1-recovery Stage 3a: seed-derived, so a future wipe+seed-restore
                        // re-derives this exact key; the provider NEVER overwrites an existing key — re-checked under its
                        // lock). ZC-893 (FC-2B, 5.4b item 3): whenever our key pair is missing, not only while E2E is off,
                        // so that Accept can send its answer.
                        if (zchatPreferences.getE2EOurPublicKey(senderAddress) == null) {
                            seedKeyProvider.getOrCreateKeyPair(senderAddress)
                        }
                        // Auto-enable E2E for this peer if not already
                        if (!zchatPreferences.isE2EEnabled(senderAddress)) {
                            zchatPreferences.setE2EEnabled(senderAddress, true)
                        }

                        // BUG-4 one-tap calling: if the KEX carried the peer's NOSTR pubkey + relay,
                        // store them now (TOFU-bound to the just-verified E2E key) so calls connect
                        // without a separate ZBOOT round-trip. Absent → existing ZBOOT path delivers it.
                        // ZC-634, ZC-950 (FC-4, 5.5 item 5): not while its key waits for Accept, nor while it is only a claim.
                        // W-72 (SPEC_F R3): nor while the key carries its pre-update mark.
                        val legacyStands = zchatPreferences.getLegacyKeyMark(senderAddress) != null
                        if (zchatPreferences.getInboundKexAwaitingAccept(senderAddress) == null && !stored.claim && !legacyStands) {
                            applyKEXNostr(senderAddress, stored.nostrPubkeyHex, stored.relayUrl)
                        }

                        // Send KEXACK in response — but only once per (peer, key). The peer (or NOSTR
                        // re-delivery, or a 2.12.4 peer re-sending the same key under a new txid) can
                        // re-send the same KEX repeatedly; re-acking each one burns ~17,000 zatoshi.
                        // payKexAckOnce takes the process-wide claim, checks the durable marker before
                        // the budget, and stamps it before the submit (HS-1/HS-2/HS-3).
                        payKexAckOnce(senderAddress, peerPublicKey, ourAddress, consumeBudget = true) { convId }
                    }

                    ZMSGProtocol.isKEXAckMessage(memoText) -> {
                        // ZC-545 (G3): the store part is [adoptKeyOffer]; the reply part follows.
                        val stored =
                            adoptKeyOffer(
                                memoText,
                                receivedTxId,
                                expectedPeer = null,
                                expectedKey = null,
                                KeyOfferMode.LIVE,
                                minedHeight,
                                historyUnread,
                                unreadInPass,
                            )
                                as? KeyOfferOutcome.Stored ?: return@launch
                        val senderAddress = stored.peer

                        // BUG-4 one-tap calling: store peer NOSTR pubkey + relay if the KEXACK carried
                        // them (TOFU-bound to the verified E2E key). On first contact the KEXACK can't
                        // fit them (the address fills the memo), so they're delivered by the ZBOOT below.
                        // ZC-634 (FC-4, 5.5 items 1 and 5): not while a key at that address waits for Accept, nor for a claim,
                        // nor for an answer taken by leg 2.
                        val leg = receivedTxId?.let { answerLegByTx[it] }
                        // W-72 (SPEC_F R3): while the pre-update mark stands, only a leg 1 answer's.
                        val bindsRelayFields =
                            zchatPreferences.getInboundKexAwaitingAccept(senderAddress) == null &&
                                !stored.claim &&
                                leg != AnswerVerdict.LEG2 &&
                                (leg == AnswerVerdict.LEG1 || zchatPreferences.getLegacyKeyMark(senderAddress) == null)
                        if (bindsRelayFields) {
                            applyKEXNostr(senderAddress, stored.nostrPubkeyHex, stored.relayUrl)
                        }
                        // ZC-634 (5.5 items 6 and 9): the proof released the mark; the ZBOOT it held back is handed on now (a
                        // relay event is not delivered twice), and its reply goes over the relays only.
                        val handedOn =
                            stored.releasedBoot?.let {
                                routeIncomingBoot(senderAddress, it, sealedByBoundKey = false, replyRule = ZbootOnChainRule.RELAY_ONLY)
                            } == true

                        // We (the KEX initiator) now hold the peer's E2E key → they can verify a ZBOOT
                        // from us. Deliver OUR NOSTR identity in its own memo NOW (sequenced AFTER the
                        // KEXACK so it doesn't race the KEX for the single spendable note). The peer's
                        // routeIncomingBoot will store it and reply with THEIR ZBOOT → both sides get
                        // each other's NOSTR pubkey → calls unlock. Idempotent (see sendNostrBootHandshake).
                        // Round 10b R10B-1 (F-R9C-1): a first-contact KEXACK never carries the peer's relay key, so this
                        // ZBOOT goes on-chain. In a Shielded chat that is paid only when the confirmed first-message
                        // question quoted it (3 transactions); the standing handshake consent never covers it there.
                        // ZC-634 (5.5 item 9): after a hand-over its reply was our ZBOOT, over the relays only.
                        if (!handedOn) sendNostrBootHandshake(senderAddress, ZbootOnChainRule.QUOTED_IN_SHIELDED)

                        // Log completion
                        if (zchatPreferences.isE2EKeyExchangeComplete(senderAddress)) {
                            Log.d("KEX", "E2E key exchange COMPLETE with ${senderAddress.redactAddress()}")
                        }
                    }
                }
            } catch (e: Exception) {
                Log.e("KEX", "Error handling KEX message", e)
            }
        }
    }

    /**
     * Send a KEX (Key Exchange) message to initiate E2E encryption.
     * Called when user enables E2E for a conversation.
     *
     * @param peerAddress The peer's Zcash address
     * @param ourAddress Our Zcash address
     * @param confirmedByQuote T3b-1: set by a confirmed mode switch whose quote counted this KEX. It is paid on that
     * answer while it stands (re-read before every attempt), never under the standing automatic-setup consent; null
     * (every other trigger) keeps the standing consent.
     */
    fun sendKEXMessage(
        peerAddress: String,
        ourAddress: String,
        confirmedByQuote: (() -> Boolean)? = null,
        retryOf: Long? = null,
    ) {
        viewModelScope.launch { sendKexOnce(peerAddress, ourAddress, confirmedByQuote, retryOf) }
    }

    /**
     * ZC-1472 — how one KEX send ended: its [outcome] (null when nothing was attempted), whether it reached the hand-over
     * to the network, and what its proposal paid there ([paid]; null when the network fee could not be read).
     * [sentNow] is the one fact a "sent" note may claim: this attempt went out (SENT also answers "already delivered by
     * another attempt", which paid nothing now).
     */
    private class KexEnd(
        val outcome: MemoSendOutcome?,
        val reachedSubmit: Boolean,
        val paid: Zatoshi?,
    ) {
        val sentNow: Boolean get() = outcome == MemoSendOutcome.SENT && reachedSubmit
    }

    /**
     * ZC-1472 — [sendKEXMessage] (same scope, same send, same consent) with its end handed to [onEnd]. Nothing is
     * reported when the chat's screen goes away before the send ends (its scope is cancelled, as for sendKEXMessage).
     */
    private fun launchKexReporting(
        peerAddress: String,
        ourAddress: String,
        confirmedByQuote: (() -> Boolean)?,
        onEnd: (KexEnd) -> Unit,
    ) {
        viewModelScope.launch {
            var reached = false
            var paid: Zatoshi? = null
            val sink =
                co.electriccoin.zcash.ui.screen.chat.usecase.ProposalPriceSink { price ->
                    reached = true
                    paid = price
                }
            val outcome = withContext(sink) { sendKexOnce(peerAddress, ourAddress, confirmedByQuote, retryOf = null) }
            onEnd(KexEnd(outcome, reached, paid))
        }
    }

    /** ZC-1472 — the persistent "Setting up Tunnel: key exchange sent, N ZEC" note, only for a KEX that went out now. */
    private fun noteTunnelSetup(
        peerAddress: String,
        end: KexEnd,
    ) {
        if (!end.sentNow) return
        val text =
            end.paid?.let {
                noteCopy.get(
                    R.string.chat_note_tunnel_setup_kex_sent,
                    zecDisplay(it, java.util.Locale.getDefault()),
                )
            } ?: noteCopy.get(R.string.chat_note_tunnel_setup_kex_sent_unpriced)
        emitSystemNote(peerAddress, setupNoteId(peerAddress, "kexsent"), text)
    }

    /** ZC-1472, ZC-1473 — one note per event, named like the other system notes (ID_PREFIX + tag + hashed peer + time). */
    private fun setupNoteId(
        peerAddress: String,
        tag: String,
    ): String =
        co.electriccoin.zcash.ui.screen.chat.model.SysNotes.ID_PREFIX + tag + "-" +
            java.security.MessageDigest
                .getInstance("SHA-256")
                .digest(peerAddress.toByteArray(Charsets.UTF_8))
                .joinToString("") { "%02x".format(it) }
                .take(12) + "-" + System.currentTimeMillis()

    /**
     * [sendKEXMessage]'s work, awaited by the Retry of the "Key exchange not sent" notice ([runHandshakeRetry]).
     *
     * F8 (ZC-112) — the KEX is one entry of the send-attempt ledger, keyed by the contact and the key it carries,
     * whichever path sends it. While an entry of that key stands (unresolved, mined and not yet deep, or proven not
     * sent) every attempt but the notice's Retry answers PENDING and changes nothing. [retryOf] is that Retry: the
     * marker of the NOT_SENT entry its quote was shown for. It skips only the guard that stops an automatic second
     * payment (the paid record of the last hour), keeps every correctness guard (the exchange completed, the key
     * replaced, our own address, a stranger's held request, the unread history, Keystone), is paid on its quote
     * ([confirmedByQuote]) and never under the standing consent, and a failure re-arms nothing.
     * @return what the send did, or null when nothing was attempted.
     */
    private suspend fun sendKexOnce(
        peerAddress: String,
        ourAddress: String,
        confirmedByQuote: (() -> Boolean)?,
        retryOf: Long?,
        // ZC-1235: a true-price question's answer; null is the one handshake, held for the next chat open when above it.
        payment: OwnSetupPayment? = null,
    ): MemoSendOutcome? {
        try {
            // Ensure we have keys
            var ourPublicKey = zchatPreferences.getE2EOurPublicKey(peerAddress)
            var ourPrivateKey = zchatPreferences.getE2EPrivateKey(peerAddress)
            // ZC-1272: the KEX leg a question covered: used up before anything is paid, so it can never pay a second one;
            // put back only when the attempt provably sent nothing.
            val coveredLeg = payment?.coveredKexLeg
            var legUsed = false
            var legOwner: String? = null

            if (ourPublicKey == null || ourPrivateKey == null) {
                // Generate keys (D1-recovery Stage 3a: seed-derived + provenance-marked; the
                // provider returns the STORED pair if another site won the race — never a
                // second generation for the same peer).
                // P2d (1): while a restored wallet has not read its history yet, create NO key and send no
                // KEX: the scan may still reinstall this peer's historical key, and a new key stored first
                // would block that for good. Re-arm the bootstrap marker so the KEX runs once it is read.
                // ZC-893 (FC-2B, 5.4b item 6): a key this phone never asked for goes before our key pair is made.
                dropUnaskedKeyBeforeOwnStart(peerAddress)
                val keyPair = seedKeyProvider.getOrCreateKeyPairForSend(peerAddress)
                if (keyPair == null) {
                    if (retryOf == null) zchatPreferences.setOwnBootSent(peerAddress, false)
                    Log.d("KEX", "KEX to ${peerAddress.redactAddress()} waits: the restored history is not read yet")
                    return null
                }
                ourPublicKey = keyPair.publicKey
                ourPrivateKey = keyPair.privateKey
            }

            val kexMessage =
                buildKexMemo(peerAddress, ourAddress, ourPublicKey, ourPrivateKey) ?: run {
                    // FC-ID: no own-made id for this address (a caller that skipped the plan step): nothing is paid.
                    if (retryOf == null) zchatPreferences.setOwnBootSent(peerAddress, false)
                    return MemoSendOutcome.NOTHING_SENT
                }

            // Send via transaction, block-aware-retrying a TRANSIENT note lock (e.g. our prior tx's
            // change still maturing). A permanent failure clears isOwnBootSent below to re-arm.
            //
            // P2b: before EVERY paid attempt, including one after a block wait, re-read what makes this
            // KEX unnecessary — the peer's reply completed the exchange, a Reset replaced the key it
            // carries, or a KEX for this same key was already paid within the cooldown (a Call tap, a
            // Reconnect tap or another screen). Any of those: send nothing and keep isOwnBootSent.
            val sentKey = ourPublicKey
            val paid = PaidSetupRecord(AutomaticSetupKind.KEX, peerAddress, sentKey)
            // F8: a key-change reconnect's KEX is not settled by the exchange reading as complete (ZC-535: the stored
            // key of the contact is the old one); the Retry of such a KEX keeps that rule.
            val retriesReconnect = retryOf != null && kexEntryIsReconnect(peerAddress, sentKey)
            val marker =
                HandshakeMarkerGuard(
                    alreadyDelivered = {
                        (zchatPreferences.isE2EKeyExchangeComplete(peerAddress) && !retriesReconnect) ||
                            zchatPreferences.getE2EOurPublicKey(peerAddress) != sentKey ||
                            // F8: the hour rule stops an automatic second payment; the Retry was quoted for this one.
                            (retryOf == null && paid.paidRecently())
                    },
                    stamp = {
                        if (coveredLeg != null) {
                            legOwner = quotedChatSetup(peerAddress)?.account
                            legUsed = storeQuotedChatSetup(peerAddress, quotedChatSetup(peerAddress)?.copy(kex = null))
                        }
                        (coveredLeg == null || legUsed) && paid.stamp()
                    },
                    unstamp = {
                        paid.unstamp()
                        if (legUsed) {
                            legUsed = false
                            // ZC-1348: the used-up leg may have taken the whole record, and its owner, with it.
                            val now = quotedChatSetup(peerAddress) ?: QuotedChatSetup(account = legOwner)
                            storeQuotedChatSetup(peerAddress, now.copy(kex = coveredLeg))
                        }
                    },
                )
            val outcome =
                sendAutomaticHandshakeMemoOutcome(
                    peerAddress,
                    ourAddress,
                    kexMessage,
                    AutomaticSetupKind.KEX,
                    marker,
                    confirmedByQuote = confirmedByQuote,
                    attempt = SendAttemptTag(SendAttemptKind.KEX, peerAddress, sentKey, retryOf = retryOf),
                    kexAnswer = ownSetupAttempt(peerAddress, zboot = false, payment),
                )
            when (outcome) {
                MemoSendOutcome.SENT -> Unit
                // F8: an earlier attempt of this key is still on the chain or waits for Retry: nothing is changed.
                MemoSendOutcome.PENDING ->
                    Log.d("KEX", "KEX to ${peerAddress.redactAddress()} waits: an earlier attempt of this key is still on the chain")
                MemoSendOutcome.NOTHING_SENT, MemoSendOutcome.MAY_HAVE_BEEN_SENT ->
                    // F8: a failed Retry re-arms nothing (the failed state it was confirmed for is still the truth).
                    if (retryOf == null) zchatPreferences.setOwnBootSent(peerAddress, false)
            }
            return outcome
        } catch (e: Exception) {
            // NEVER re-arm on cancellation. The repository broadcasts in its own detached scope, so
            // backing out of the chat cancels only our await — the KEX still reaches the network and
            // is paid for. Clearing isOwnBootSent there made the next chat open, before the peer's
            // KEXACK lands, send and pay for a second KEX (the E2E-completeness gate only blocks a
            // re-send once that KEXACK has arrived). Same rule as the ZBOOT sender. ZC-121 (F8): a cancel
            // before the attempt was handed to the SDK withdraws that attempt's own paid record
            // ([sendMemoWithBlockRetry]); the bootstrap marker stays, and the Call-tap and Reset force paths
            // recover it.
            if (!mayReArmHandshakeMarker(e)) throw e
            Log.e("KEX", "Failed to send KEX message", e)
            // A KEX carries OUR E2E key (and piggybacks our NOSTR pubkey) to the peer; if it failed
            // (e.g. single-note serialization left no spendable Orchard input this block) the peer
            // never received our key, so the bootstrap is NOT actually complete. ensureNostrBootstrapSent
            // sets isOwnBootSent=true before this async send resolves — clear it here so the next
            // non-force trigger (mode re-apply, periodic retry) re-fires the bootstrap and retries the
            // KEX, instead of a failed KEX leaving a permanently stuck half-handshake (ZBOOT sent, key
            // never delivered → peer drops every ZBOOT as "no verified E2E identity").
            if (retryOf == null) zchatPreferences.setOwnBootSent(peerAddress, false)
            return MemoSendOutcome.NOTHING_SENT
        }
    }

    /** F8: whether the ledger entry of the KEX carrying [key] to [peerAddress] is a key-change reconnect's (ZC-300). */
    private fun kexEntryIsReconnect(
        peerAddress: String,
        key: String,
    ): Boolean =
        runCatching {
            sendAttempts?.ledger?.get(SendAttemptLedgerRules.key(SendAttemptKind.KEX, peerAddress, key))?.reason
        }.getOrNull() == ZchatPreferences.KEX_OWED_REASON_RECONNECT

    /** The signed v4 KEX memo carrying our key pair's public half (and our NOSTR identity when we have one) to [peerAddress]. */
    private suspend fun buildKexMemo(
        peerAddress: String,
        ourAddress: String,
        ourPublicKey: String,
        ourPrivateKey: String,
    ): String? {
        // FC-ID (ZC-892; FIRST-CONTACT-SPEC 5.3a item 4): the KEX goes out only under an id this phone made for this
        // address, chosen where the send was planned and priced (planOwnConversationId, which also marks the first
        // message after it as the INIT). It makes no id here: an id another memo gave this address is never used, and a
        // caller that skipped the plan step sends nothing (null).
        val convId =
            convIdMutex.withLock { zchatPreferences.ownConversationId(peerAddress) } ?: run {
                Log.w("KEX", "KEX to ${peerAddress.redactAddress()} not built: no conversation id of this phone's own for it")
                return null
            }

        // BUG-4 one-tap calling: piggyback OUR NOSTR pubkey + relay onto the FIRST KEX so the
        // peer can place calls immediately, without a separate ZBOOT round-trip. Null (e.g.
        // seed unavailable) → omitted, and the peer falls back to the existing ZBOOT flow.
        val (ourNostrPub, ourRelay) = getOurNostrPubkey() ?: (null to null)

        // Create signed KEX payload
        val kexPayload =
            E2EEncryption.createKEXPayload(
                ourAddress,
                ourPublicKey,
                ourPrivateKey,
                ourNostrPub,
                ourRelay
            )

        Log.d("KEX", "Sending KEX to ${peerAddress.redactAddress()} convId=${convId.redactConvId()}")
        return ZMSGProtocol.createV4KEXMessage(convId, ourAddress, kexPayload)
    }

    /** R9-2 — what [payOwedKex] did about the KEX owed to one contact. */
    private sealed interface OwedKex {
        /** Nothing is owed any more: the KEX was sent, may have been sent, or is no longer needed. */
        data object Done : OwedKex

        /** Another attempt at the same KEX is running; this one did nothing. */
        data object Busy : OwedKex

        /** T1b-1 (C): the KEX is owed by an account that is not selected; nothing was paid and the mark stays for it. */
        data object OtherAccount : OwedKex

        /** Open keeps the owed mark untouched; no caller may continue a paid step on this outcome. */
        data object KeptForAnotherMode : OwedKex

        /** ZC-739: the contact's new key waits for the user; nothing was paid, the mark and its allowance stay. */
        data object KeyDecisionWaits : OwedKex

        /**
         * F8 (ZC-112): an earlier attempt of this KEX (the same key) is unresolved, mined and not yet deep, or proven not
         * sent and waiting for the notice's Retry. Nothing was built, stamped or paid; the owed mark, its account and its
         * reason are untouched. Not [Done] (the mark is not cleared) and not [NotSent] (there is no error to show).
         */
        data object Pending : OwedKex

        /** Nothing was sent and the KEX is still owed; [error] is why (what the message send reports). */
        data class NotSent(
            val error: Exception,
        ) : OwedKex
    }

    /**
     * R9-2 (REVIEW_R8 F4, device D-F7) — pay the KEX owed to [peerAddress]: the key exchange the user confirmed in the
     * first-message quote (PaidAction.FIRST_MESSAGE, "the key exchange goes first, then the message"). It never asks
     * again: the user's confirm of that quote is the consent, so the automatic-setup consent gate is not consulted
     * (asking it raised a second paid question for the same transaction). It never pays twice: one attempt per contact
     * at a time in this process ([owedKexLocks]), and the same durable paid-setup record as every KEX
     * ([PaidSetupRecord], stamped before the submit and withdrawn only when the attempt provably sent nothing), re-read
     * before every attempt with the exchange state and our current key. The owed mark is cleared once the KEX is SENT
     * or MAYBE_SENT (or no longer needed); a KEX that sent nothing stays owed and is retried by the next block or chat
     * open ([retryOwedKeyExchange]).
     *
     * [forSend] is the message send that owes this KEX: it waits for another attempt to finish (the message must go
     * after the KEX) and pays even when the owed mark could not be written. Otherwise (a block, a chat open) a running
     * attempt means [OwedKex.Busy], and only a KEX the durable mark still owes is paid.
     *
     * ZC-285, ZC-286: a confirmed Reset encryption owes its KEX the same way (reason
     * [ZchatPreferences.KEX_OWED_REASON_RESET]), and ZC-300 a confirmed key-change reconnect (reason
     * [ZchatPreferences.KEX_OWED_REASON_RECONNECT]); the confirm is the consent, and a later block or chat open pays it,
     * once, at the price confirmed there. Such a lone KEX (no message in its quote) is not held by M2's first-message plan
     * check. [voidOnKeystoneRefusal]: whether a Keystone refusal of the [forSend] attempt voids the mark (T1b-1 (D), a
     * message send, the default); the Reset and the reconnect pass false, because the keys are already wiped or the relay
     * key already dropped: the KEX stays owed for the account that confirmed it (T1b-1 (C)).
     *
     * ZC-535: a reconnect's KEX is not settled by the exchange reading as complete (the contact's stored key is the old
     * one); a Reset that replaced our key and a KEX of this key paid in the last hour still settle it
     * ([kexSettlesUnpaid]). Once it is out, the reconnect's ZBOOT is fired from here ([fireReconnectZbootIfDue]), so a
     * KEX a later block pays is followed by it too. The owed reason is read once, before the mark is cleared.
     *
     * F8 (ZC-112): the KEX is tagged in the send-attempt ledger under the same key as every KEX of this contact (the
     * contact and the key it carries), with the owed reason. An owed KEX is never a Retry: while an entry of that key
     * stands (unresolved, mined and not yet deep, or proven not sent and waiting for the notice's Retry) this answers
     * [OwedKex.Pending] before anything is stamped or built, and the owed mark, its account and its reason stay as they
     * are. The ledger's gate comes before the settle rules above, so an entry answers first. A KEX refused by M2's plan
     * check attempted nothing: no entry, no stamp, the mark kept.
     */
    private suspend fun payOwedKex(
        peerAddress: String,
        ourAddress: String,
        forSend: Boolean,
        // SR-A (R-A3): the KEX leg of a quoted send (counted in its exact question); the KEX pays exactly it or nothing.
        kexQuote: ChatSendQuote? = null,
        voidOnKeystoneRefusal: Boolean = forSend,
        // ZC-1235: the true price the user confirmed; with neither this nor [kexQuote] the one handshake is the limit.
        confirmedPrice: KexAnswerPrice? = null,
        // ZC-1289: the limit this attempt runs under; once it won nothing is paid, and its stamp and lock were let go.
        sendDeadline: SendBuildDeadline? = null,
        // ZC-1975: the message send's row was deleted by the user (read under the claim lock): nothing of this KEX is paid.
        rowDeleted: (() -> Boolean)? = null,
    ): OwedKex {
        // ZC-880: keep the old mark for a later mode; no plan, key creation, stamp or screen notice in Open.
        if (openNeverSpends(peerAddress)) return OwedKex.KeptForAnotherMode
        // ZC-739: stays owed while the contact's new key waits for the user; the decision pays it ([resumeAfterKeyDecision]).
        if (zchatPreferences.isE2EKeyChanged(peerAddress)) return OwedKex.KeyDecisionWaits
        val lock = owedKexLocks.computeIfAbsent(peerAddress) { Mutex() }
        if (forSend) {
            lock.lock()
        } else if (!lock.tryLock()) {
            return OwedKex.Busy
        }
        try {
            // ZC-1289: settled by its limit while it waited for the lock: nothing of this run may pay now.
            if (sendDeadline?.expired == true) return OwedKex.NotSent(SendBuildExpiredException())
            // ZC-1271: the first message this KEX belongs to stopped for the user's decision: only its Retry pays it now.
            if (!forSend && firstMessageStoppedForDecision(peerAddress)) return OwedKex.Busy
            // ZC-1992: nor does a block pay a first message's KEX whose every message the user deleted.
            // ZC-1999: only a mark that would pay; one that settles unpaid (a complete exchange, ZC-626) goes on to be cleared.
            if (!forSend &&
                !owedKexIsLone(peerAddress) &&
                runCatching { owedKexWouldPay(peerAddress) }.getOrDefault(true) &&
                owedKexOnlyForDeletedRows(peerAddress)
            ) {
                return OwedKex.Busy
            }
            // A caller waiting for the claim may have switched this chat to Open.
            if (openNeverSpends(peerAddress)) return OwedKex.KeptForAnotherMode
            if (!zchatPreferences.isKexOwed(peerAddress) && !(forSend && kexOwedPeers.contains(peerAddress))) {
                kexOwedPeers.remove(peerAddress)
                return OwedKex.Done
            }
            // T1b-1 (E): never a KEX to one of our own addresses. Nothing is sent and the mark is dropped.
            if (zchatPreferences.isSelfAddress(peerAddress)) {
                Log.w("KEX", "Owed KEX to one of our own addresses dropped — nothing sent")
                zchatPreferences.setKexOwed(peerAddress, false)
                kexOwedPeers.remove(peerAddress)
                return OwedKex.Done
            }
            // T1b-1 (C): only the account that confirmed the KEX pays it; another account neither pays nor clears it.
            if (!owedKexBelongsToSelectedAccount(peerAddress, whenUnknown = forSend)) {
                Log.d("KEX", "Owed KEX to ${peerAddress.redactAddress()} belongs to another account — not paid now")
                return OwedKex.OtherAccount
            }
            // M2 (fix-all 2.13.0): a block or a chat open pays an owed KEX alone only when the message after it can be
            // paid too (owedKexPlan). Otherwise nothing is paid or created, the mark stays for a later block, and the
            // answer is logged once until it changes (no notice on the screen, none per block). The message send's own
            // owed KEX (forSend) passed the same check in doSendMessage before the mark was written.
            // ZC-285: a KEX a Reset (or Reconnect) owes is quoted alone; no message follows it, so the gate does not apply.
            if (!forSend && !owedKexIsLone(peerAddress) && owedKexWouldPay(peerAddress)) {
                val plan = owedKexPlan(peerAddress)
                val kind = plan.javaClass.simpleName
                if (plan !is FirstMessagePlan.Fundable) {
                    if (owedKexPlanLogged.put(peerAddress, kind) != kind) {
                        Log.w("KEX", "Owed KEX to ${peerAddress.redactAddress()} not paid: its message can't follow ($kind)")
                    }
                    return OwedKex.NotSent(OwedKexPlanRefusedException(firstMessagePlanRefusal(plan, row = true)))
                }
                owedKexPlanLogged.remove(peerAddress)
            }
            // ZC-535: read once, here, before the SENT branch clears the mark and its reason with it.
            val owedReason = owedKexReason(peerAddress)
            val reconnect = owedReason == ZchatPreferences.KEX_OWED_REASON_RECONNECT
            val reset = owedReason == ZchatPreferences.KEX_OWED_REASON_RESET
            // ZC-1998 (money-path rule 2): a block's KEX of a first message; the user may delete that message while it runs.
            val blockFirstMessageKex = !forSend && !reconnect && !reset
            var ourPublicKey = zchatPreferences.getE2EOurPublicKey(peerAddress)
            var ourPrivateKey = zchatPreferences.getE2EPrivateKey(peerAddress)
            if (ourPublicKey == null || ourPrivateKey == null) {
                // P2d (1): a restored wallet that has not read its history yet creates no key.
                // ZC-893 (FC-2B, 5.4b item 6): a key this phone never asked for goes before our key pair is made.
                dropUnaskedKeyBeforeOwnStart(peerAddress)
                val keyPair =
                    seedKeyProvider.getOrCreateKeyPairForSend(peerAddress)
                        ?: return OwedKex.NotSent(UserFacingSendRefusal(RESTORE_HISTORY_NOT_READ))
                ourPublicKey = keyPair.publicKey
                ourPrivateKey = keyPair.privateKey
            }
            // FC-ID: a lone KEX (a confirmed Reset or reconnect, perhaps owed since before this build) is priced alone, so its
            // id may be made here; a message's KEX got its id where the message was planned.
            if (reconnect || reset) planOwnConversationId(peerAddress)
            val kexMessage =
                buildKexMemo(peerAddress, ourAddress, ourPublicKey, ourPrivateKey)
                    ?: return OwedKex.NotSent(IllegalStateException("The key exchange has no conversation id of this phone's own"))
            val sentKey = ourPublicKey
            val paid = PaidSetupRecord(AutomaticSetupKind.KEX, peerAddress, sentKey)
            // ZC-1289: a limit that wins while this build is parked lets a Retry pay: the stamp goes, and the lock with it.
            sendDeadline?.onExpiredLeg = {
                paid.unstamp()
                owedKexLocks.remove(peerAddress, lock)
            }
            var lastError: Exception? = null
            // ZC-536 (c): set when this KEX settled unpaid for no other reason than the exchange being complete.
            var settledByCompleteExchange = false
            // ZC-739-R1: set when an attempt stopped because the contact's new key waits for the user.
            var heldForKeyDecision = false
            // ZC-1394: set when an attempt stopped because another account is selected now.
            var heldForOtherAccount = false
            // ZC-1975: set when an attempt stopped because the message it goes before was deleted.
            var heldForDeletedRow = false
            val outcome =
                sendMemoWithBlockRetry(
                    destination = peerAddress,
                    sender = ourAddress,
                    memo = kexMessage,
                    beforeAttempt = {
                        when {
                            // ZC-1289: settled by its limit during a block wait.
                            sendDeadline?.expired == true -> MemoAttemptGate.STOP
                            // ZC-1975 (money-path rule 2): and the message's row deleted during a block wait.
                            rowDeleted?.invoke() == true -> {
                                heldForDeletedRow = true
                                MemoAttemptGate.STOP
                            }
                            // Re-read after every block wait: a switch to Open keeps the owed mark unpaid.
                            openNeverSpends(peerAddress) -> MemoAttemptGate.STOP
                            // ZC-1394 (money-path rule 2): and an account switch: the mark stays for the account that owns it.
                            !owedKexBelongsToSelectedAccount(peerAddress, whenUnknown = forSend) -> {
                                heldForOtherAccount = true
                                MemoAttemptGate.STOP
                            }
                            // ZC-739-R1: and the contact's new key arriving while this attempt waited: nothing is paid,
                            // nothing stamped, the mark and its allowance stay for the decision.
                            zchatPreferences.isE2EKeyChanged(peerAddress) -> {
                                heldForKeyDecision = true
                                MemoAttemptGate.STOP
                            }
                            // ZC-626: a KEX carrying this key was already submitted for this mark (its paid record is on
                            // disk, at any age; this attempt's own stamp is withdrawn before it waits for a block). The
                            // mark is stale (its clear was not saved): nothing is paid, and the clear is written again.
                            owedKexWasSubmitted(peerAddress, sentKey) -> MemoAttemptGate.ALREADY_DELIVERED
                            // The contact's reply completed the exchange, a Reset replaced the key, or another attempt
                            // (a Tunnel bootstrap, a Reconnect tap) already paid for a KEX carrying this key.
                            // ZC-535: a key-change reconnect's KEX is not settled by the completeness (stale old key).
                            kexSettlesUnpaid(peerAddress, sentKey, reconnect) -> {
                                // No paid record names this key (the branch above), so with our key unchanged the
                                // reason is the complete exchange.
                                settledByCompleteExchange = zchatPreferences.getE2EOurPublicKey(peerAddress) == sentKey
                                MemoAttemptGate.ALREADY_DELIVERED
                            }
                            // ZC-1998: a block's KEX whose mark Delete took, or whose every message is deleted, stops
                            // (after the settles above, so a stale mark that needs no payment is still cleared).
                            blockFirstMessageKex && blockKexLostItsMessage(peerAddress) -> {
                                heldForDeletedRow = true
                                MemoAttemptGate.STOP
                            }
                            !paid.stamp() -> {
                                Log.e("KEX", "Owed KEX not paid: its durable paid marker could not be written")
                                MemoAttemptGate.STOP
                            }
                            else -> MemoAttemptGate.PROCEED
                        }
                    },
                    afterNothingSent = {
                        sendDeadline?.endLeg()
                        // ZC-1289: after the limit won the record may be a Retry's; this run's stamp already went.
                        if (sendDeadline?.expired != true) paid.unstamp()
                    },
                    // ZC-1289: a build that wakes up after its limit pays nothing, however late.
                    beforeSubmit = {
                        // ZC-1975: a row deleted while this KEX was built pays nothing: thrown before the submit, so nothing
                        // is sent and this attempt's stamp is withdrawn.
                        if (rowDeleted?.invoke() == true) {
                            heldForDeletedRow = true
                            throw DeletedRowException()
                        }
                        // ZC-1998: and a block's KEX whose only message the user deleted while it was built.
                        if (blockFirstMessageKex && blockKexLostItsMessage(peerAddress)) {
                            heldForDeletedRow = true
                            throw DeletedRowException()
                        }
                        if (sendDeadline != null && !sendDeadline.claimLeg()) throw SendBuildExpiredException()
                    },
                    onFailure = { failure ->
                        lastError = failure
                        CreateChunkedMessageProposalUseCase.kexAnswerActualPrice(failure)?.let {
                            holdOwnSetupAtItsTruePrice(peerAddress, zboot = false, it)
                        }
                    },
                    sendQuote = kexQuote,
                    // F8: the same key as every KEX of this contact; an owed KEX is never a Retry (retryOf stays null),
                    // so with an entry of the key it answers PENDING and the mark stays.
                    attempt = SendAttemptTag(SendAttemptKind.KEX, peerAddress, sentKey, reason = owedReason),
                    // ZC-1272: a leg a question covered is the limit of this KEX; a retried figure may be above the usual one.
                    kexAnswerPrice =
                        if (kexQuote == null) {
                            confirmedPrice
                                ?: quotedChatSetup(peerAddress)?.kex?.let { KexAnswerPrice(Zatoshi(it)) }
                                ?: handshakeAnswerPrice()
                        } else {
                            null
                        },
                )
            if (outcome == MemoSendOutcome.SENT || outcome == MemoSendOutcome.MAY_HAVE_BEEN_SENT) {
                quotedChatSetup(peerAddress)?.let { storeQuotedChatSetup(peerAddress, it.copy(kex = null)) }
            }
            return when (outcome) {
                MemoSendOutcome.PENDING -> OwedKex.Pending
                MemoSendOutcome.SENT, MemoSendOutcome.MAY_HAVE_BEEN_SENT -> {
                    // ZC-285: a confirmed Reset replaced the key this attempt carried while it waited (it settled as already
                    // delivered). The mark is now that Reset's: kept for its own attempt, which pays the KEX for the new key.
                    if (zchatPreferences.getE2EOurPublicKey(peerAddress) != sentKey && owedKexIsLone(peerAddress)) {
                        Log.d("KEX", "Owed KEX to ${peerAddress.redactAddress()} replaced by a Reset — the Reset's KEX stays owed")
                        return OwedKex.Done
                    }
                    if (!zchatPreferences.setKexOwed(peerAddress, false)) {
                        // ZC-626: the stale mark is read again by the next block and by the next process. The paid
                        // record of this key settles it there without a payment at any age ([owedKexWasSubmitted]), and
                        // each of those settles writes this clear again until it is saved.
                        Log.w("KEX", "Owed KEX sent; clearing its owed mark was not saved (written again at the next block)")
                    }
                    kexOwedPeers.remove(peerAddress)
                    dropHeldOwnKexPrice(peerAddress, sentKey)
                    // ZC-536 (c): a Reset's KEX that settled because the contact's own key exchange completed it is
                    // followed by no key reply, so nothing will use the allowance the Reset wrote for its ZBOOT. Not for
                    // a settle by the hour rule (the key reply to the paid KEX is still to come and needs it), not for
                    // a reconnect (it fires its ZBOOT below), not for a first message, and not while a ZBOOT to this
                    // contact is in flight on it.
                    if (settledByCompleteExchange && reset && !nostrBootInFlight.contains(peerAddress)) {
                        settleQuotedAllowance(peerAddress)
                    }
                    // ZC-535: the reconnect's KEX is out; with a complete exchange no KEXACK will trigger its ZBOOT.
                    if (reconnect) fireReconnectZbootIfDue(peerAddress)
                    OwedKex.Done
                }
                MemoSendOutcome.NOTHING_SENT -> {
                    if (heldForDeletedRow) return OwedKex.NotSent(DeletedRowException())
                    if (openNeverSpends(peerAddress)) return OwedKex.KeptForAnotherMode
                    if (heldForKeyDecision) return OwedKex.KeyDecisionWaits
                    if (heldForOtherAccount) return OwedKex.OtherAccount
                    val error = lastError ?: UserFacingSendRefusal(ChatSendCopy.STORAGE_PAUSED_PAID_STEP)
                    // T1b-1 (D): a Keystone refusal is final for the send that confirmed this KEX: the user was told
                    // nothing was sent or paid, so its consent is void. The mark and any quoted ZBOOT go; no retry pays
                    // them. A retry refused after an account switch keeps the mark for the account that owns it.
                    if (forSend && voidOnKeystoneRefusal && error.isKeystoneRefusal()) {
                        Log.w("KEX", "Owed KEX refused on a Keystone account — the confirm is void, nothing kept owed")
                        zchatPreferences.setKexOwed(peerAddress, false)
                        withdrawZbootQuote(peerAddress)
                        kexOwedPeers.remove(peerAddress)
                    }
                    OwedKex.NotSent(error)
                }
            }
        } finally {
            sendDeadline?.endLeg()
            sendDeadline?.onExpiredLeg = null
            lock.unlock()
        }
    }

    /**
     * T1b-1 (C) — whether the KEX owed to [peerAddress] belongs to the selected account: the account stored with the
     * mark, or, for a mark stored without one (test builds before T1b-1), the ZChat account. When the selected account
     * cannot be read, [whenUnknown]: true only for the message send the user confirmed (the chokepoint reads the
     * account again and refuses a Keystone one); a block or chat-open retry pays nothing then.
     */
    private suspend fun owedKexBelongsToSelectedAccount(
        peerAddress: String,
        whenUnknown: Boolean,
    ): Boolean {
        val selected = selectedAccountOrNull() ?: return whenUnknown
        val owner = zchatPreferences.getKexOwedAccount(peerAddress)
        return if (owner.isNullOrEmpty()) {
            selected is ZashiAccount
        } else {
            owner == GetDefaultUnifiedAddressUseCase.accountKeyOf(selected)
        }
    }

    /** T1b-1 (D) — the chokepoint's Keystone refusal anywhere in this error's cause chain. */
    private fun Throwable.isKeystoneRefusal(): Boolean =
        generateSequence(this) { it.cause }
            .take(MAX_ERROR_CAUSE_DEPTH)
            .any { it is co.electriccoin.zcash.ui.screen.chat.usecase.KeystoneChatSendRefusedException }

    /**
     * R9-2 — send the KEX owed to [peerAddress], if any, without asking (it was confirmed with the first message). Runs
     * on the process-wide send scope, so closing the screen that called it does not cancel it. Called when a chat
     * opens (every mode) and, through [retryOwedKeyExchanges], on each new block.
     */
    fun retryOwedKeyExchange(peerAddress: String) {
        if (_currentUserAddress.value == null) return
        processSendScope().launch(Dispatchers.Main.immediate) {
            try {
                if (!zchatPreferences.isKexOwed(peerAddress)) return@launch
                // ZC-739: held, mark kept, while the contact's new key waits for the user.
                if (zchatPreferences.isE2EKeyChanged(peerAddress)) return@launch
                // T1b-1 §2: the KEX carries our address: the selected account's, re-read after an account switch.
                val ourAddress = currentChatIdentity() ?: return@launch
                // ZC-1289: a parked attempt must not hold this contact's lock for good; waking up late it pays nothing.
                val deadline = SendBuildDeadline()
                val limit =
                    sendBuildLimitScope.launch(Dispatchers.Main.immediate) {
                        kotlinx.coroutines.delay(SEND_TOTAL_LIMIT_MS)
                        if (deadline.expire()) deadline.releaseExpiredLeg()
                    }
                val result =
                    try {
                        payOwedKex(peerAddress, ourAddress, forSend = false, sendDeadline = deadline)
                    } finally {
                        limit.cancel()
                    }
                when (result) {
                    OwedKex.Done -> Log.d("KEX", "Owed KEX to ${peerAddress.redactAddress()} settled")
                    OwedKex.Busy, OwedKex.OtherAccount, OwedKex.KeptForAnotherMode, OwedKex.KeyDecisionWaits -> Unit
                    OwedKex.Pending ->
                        Log.d("KEX", "Owed KEX to ${peerAddress.redactAddress()} waits: an earlier attempt of this key is on the chain")
                    is OwedKex.NotSent ->
                        // M2: a plan refusal was logged once by payOwedKex; it is not repeated on every block.
                        if (result.error !is OwedKexPlanRefusedException) {
                            Log.w("KEX", "Owed KEX not sent yet (${result.error.javaClass.simpleName}); retried later")
                        }
                }
            } catch (e: Exception) {
                if (e is kotlinx.coroutines.CancellationException) throw e
                Log.w("KEX", "Owed KEX retry failed: ${e.javaClass.simpleName}")
            }
        }
    }

    /**
     * R9-2 — the block-tick half of [retryOwedKeyExchange]: at most one contact per block (#208 single note), rotated by
     * [height] so one contact whose KEX can never be funded does not starve the others. Also refreshes [kexOwedPeers]
     * from the durable marks, which is how a new process learns what an earlier one still owed.
     */
    private fun retryOwedKeyExchanges(height: Long?) {
        val owed =
            try {
                zchatPreferences.getKexOwedPeers()
            } catch (e: Exception) {
                Log.w("KEX", "Owed KEX marks not read: ${e.javaClass.simpleName}")
                return
            }
        kexOwedPeers.retainAll(owed)
        kexOwedPeers.addAll(owed)
        if (owed.isEmpty()) return
        val candidates = owed.sorted()
        retryOwedKeyExchange(candidates[(height ?: 0L).mod(candidates.size.toLong()).toInt()])
    }

    /**
     * ZC-1334 (money-path rule 2) — who consented: the user's Pay on New Chat's one question, which left [QuotedChatSetup.kex]
     * on disk. What it costs: at most that leg ([sendQuotedKex]); no question, no standing consent. At most one contact per
     * block, under the same gates as a chat open ([startNostrBootstrap]). Once only: the bootstrap marker goes down in the
     * same main-thread step as its check, the leg is used up before anything is paid, and the hour record and the send-attempt
     * ledger stop a second attempt. A failed attempt lowers the marker and restores the leg for a later block.
     */
    private fun payCoveredKeyExchange(height: Long?) {
        val peers =
            try {
                zchatPreferences.getQuotedChatSetupPeers()
            } catch (e: Exception) {
                Log.w("KEX", "Covered key exchanges not read: ${e.javaClass.simpleName}")
                return
            }
        if (peers.isEmpty()) return
        viewModelScope.launch {
            // ZC-1348: read first; the checks and the marker below stay one main-thread step.
            val selected = selectedAccountOrNull()?.let(GetDefaultUnifiedAddressUseCase::accountKeyOf)
            val due =
                peers
                    .filter { peer ->
                        quotedChatSetup(peer)?.kex != null &&
                            coveredSetupIsOf(peer, selected) &&
                            peer !in coveredMessagesBuilding &&
                            zchatPreferences.getConversationMode(peer) != ConversationMode.OPEN &&
                            !zchatPreferences.isE2EKeyChanged(peer) &&
                            !firstMessageOwnsKex(peer) &&
                            !zchatPreferences.isE2EKeyExchangeComplete(peer) &&
                            !zchatPreferences.isOwnBootSent(peer)
                    }.sorted()
            if (due.isEmpty()) return@launch
            val peer = due[(height ?: 0L).mod(due.size.toLong()).toInt()]
            val leg = quotedChatSetup(peer)?.kex ?: return@launch
            val ourAddress = _currentUserAddress.value ?: return@launch
            if (!zchatPreferences.setOwnBootSent(peer, true)) {
                Log.e("KEX", "Covered KEX not paid: its bootstrap-sent marker could not be written")
                return@launch
            }
            planOwnConversationId(peer)
            sendQuotedKex(peer, ourAddress, leg)
        }
    }

    /**
     * Send a KEXACK (Key Exchange Acknowledgment) in response to a KEX message. Only [payKexAckOnce] calls
     * this; [ackedPeerKey] is the peer key being acknowledged, whose durable sent-marker the retry loop
     * stamps before each attempt and re-reads after every block wait.
     */
    private suspend fun sendKEXAckMessage(
        peerAddress: String,
        ourAddress: String,
        convId: String,
        ackedPeerKey: String,
        retryOf: Long? = null,
        // ZC-1017: the quote a user's Accept was shown (the Tunnel offer); null keeps the rules below.
        confirmedByQuote: (() -> Boolean)? = null,
        answerPrice: KexAnswerPrice,
        // ZC-1338: an Accept tap's: it waits for the funds and is told at each wait; null keeps the automatic path's waits.
        onFundsWait: (() -> Unit)? = null,
        onRefused: (KexAnswerRefusal) -> Unit,
    ): KexAckOutcome {
        try {
            val ourPublicKey = zchatPreferences.getE2EOurPublicKey(peerAddress) ?: return KexAckOutcome.NOT_SENT
            val ourPrivateKey = zchatPreferences.getE2EPrivateKey(peerAddress) ?: return KexAckOutcome.NOT_SENT

            // BUG-4 one-tap calling: piggyback OUR NOSTR pubkey + relay onto the KEXACK too, so the
            // initiator learns our NOSTR identity from the handshake reply (no separate ZBOOT).
            val (ourNostrPub, ourRelay) = getOurNostrPubkey() ?: (null to null)

            // Create signed KEXACK payload
            val kexAckPayload = E2EEncryption.createKEXAckPayload(
                ourAddress, ourPublicKey, ourPrivateKey, ourNostrPub, ourRelay
            )

            // Create full KEXACK message
            val kexAckMessage = ZMSGProtocol.createV4KEXAckMessage(convId, ourAddress, kexAckPayload)

            Log.d("KEX", "Sending KEXACK to ${peerAddress.redactAddress()} convId=${convId.redactConvId()}")

            // Send via transaction. Block-aware-retry a TRANSIENT note lock — the KEXACK fires the
            // instant the peer's KEX lands, which momentarily locks our spendable note; without this
            // the KEXACK is silently dropped and the peer never gets our E2E key (handshake stalls).
            // P2h: whether THIS call stamped the marker for an attempt that went ahead. A "delivered" result
            // without it means another attempt paid for the key while this one waited, and nothing was sent.
            var submittedHere = false
            // Round 8 D10 (DECISIONS_NIGHT §6): whether this call's marker write failed (the attempt then sent nothing).
            var markerNotSaved = false
            val marker =
                HandshakeMarkerGuard(
                    // F8: for the notice's Retry the marker is known to be stale (the KEXACK it stands for never reached
                    // the chain), so it does not answer "delivered"; a replaced key still stops it ([handshakeQuoteStands]).
                    alreadyDelivered = { retryOf == null && zchatPreferences.getSentKexAckPubkey(peerAddress) == ackedPeerKey },
                    stamp = {
                        // R5-2: this marker is the ONLY durable record that stops the next chat open paying
                        // for the same KEXACK, so its write decides. On false nothing is sent and this
                        // attempt did not submit, so [submittedHere] stays false.
                        val saved = zchatPreferences.setSentKexAckPubkey(peerAddress, ackedPeerKey)
                        submittedHere = saved
                        if (!saved) {
                            Log.e("KEX", "KEXACK not paid: its sent-marker could not be written")
                            markerNotSaved = true
                        }
                        saved
                    },
                    unstamp = {
                        submittedHere = false
                        // F8: a Retry that sent nothing leaves the marker as it found it (set).
                        if (retryOf == null) clearSentKexAckIfStill(peerAddress, ackedPeerKey)
                    },
                )
            var ledgerRefused = false
            var lastFailure: Exception? = null
            val key = SendAttemptLedgerRules.key(SendAttemptKind.KEXACK, peerAddress, ackedPeerKey)
            val outcome =
                sendAutomaticHandshakeMemoOutcome(
                    peerAddress,
                    ourAddress,
                    kexAckMessage,
                    AutomaticSetupKind.KEXACK,
                    marker,
                    // F8: the Retry is paid on its quote, never under the standing consent.
                    confirmedByQuote = confirmedByQuote ?: retryOf?.let { s -> { handshakeQuoteStands(key, s) } },
                    // ZC-1233 round 3: a new key that arrived while this attempt was built stops it; nothing was stored or sent.
                    // ZC-1350: nor does a run that waited for a block pay once its Accept is gone (the chat was deleted).
                    beforeSubmit = {
                        val acceptGone =
                            zchatPreferences.getInboundKexAwaitingAccept(peerAddress) != null &&
                                acceptedChatRequests[peerAddress] != ackedPeerKey
                        if (acceptGone || !kexRequestStands(peerAddress, ackedPeerKey)) throw KexAnswerPreSubmitRefused()
                    },
                    attempt = SendAttemptTag(SendAttemptKind.KEXACK, peerAddress, ackedPeerKey, retryOf = retryOf),
                    kexAnswer =
                        KexAnswerAttempt(
                            price = answerPrice,
                            onLedgerRefusal = { ledgerRefused = true },
                            onAttemptStarting = { lastFailure = null },
                            onAttemptFailed = { lastFailure = it },
                            onBlockWait = onFundsWait,
                        ),
                )
            // ZC-1230, ZC-1233: only an outcome that proves nothing was sent.
            if (outcome == MemoSendOutcome.NOTHING_SENT) lastFailure?.let(::kexAnswerRefusalOf)?.let(onRefused)
            return when (outcome) {
                MemoSendOutcome.PENDING -> KexAckOutcome.PENDING
                MemoSendOutcome.NOTHING_SENT, MemoSendOutcome.MAY_HAVE_BEEN_SENT -> {
                    // F8: a KEXACK whose ledger entry could not be written sent nothing; the user is told why, as for a
                    // marker that could not be saved.
                    if (markerNotSaved || ledgerRefused) tellStoragePausedKexAck(peerAddress)
                    KexAckOutcome.NOT_SENT
                }
                MemoSendOutcome.SENT -> if (submittedHere) KexAckOutcome.SENT else KexAckOutcome.ALREADY_ACKED
            }
        } catch (e: Exception) {
            // NEVER report a cancellation as "not sent" (HS-2): backing out cancels only our await, the
            // detached repository scope still broadcasts, and a false here re-armed the marker so the next
            // chat open paid the same KEXACK again. Same rule as the KEX and ZBOOT senders.
            if (!mayReArmHandshakeMarker(e)) throw e
            Log.e("KEX", "Failed to send KEXACK", e)
            return KexAckOutcome.NOT_SENT
        }
    }

    /**
     * Round 8 D10 (DECISIONS_NIGHT §6) — a KEXACK to [peerAddress] was not sent because its sent-marker could not be
     * saved. Nothing was paid, and the next chat open tries again, but the responder cannot message until the phone's
     * store works, so the user is told why, once per process and contact ([storagePausedKexAckPeers]). Only the text
     * is new: the send decision is [payKexAckOnce]'s, unchanged. A question on screen is never replaced by it; the
     * notice then waits for a later attempt.
     */
    private fun tellStoragePausedKexAck(peerAddress: String) {
        when (_sendMessageState.value) {
            is SendMessageState.NeedsHandshakeSpendConsent,
            is SendMessageState.NeedsPaidActionConfirmation,
            is SendMessageState.NeedsIronwoodMigration,
            is SendMessageState.NeedsOrchardShielding,
            -> return
            else -> Unit
        }
        if (storagePausedKexAckPeers.add(peerAddress)) {
            _sendMessageState.value = SendMessageState.Error(ChatSendCopy.STORAGE_PAUSED_PAID_STEP)
        }
    }

    /**
     * Get peer's E2E public key if available (from completed key exchange).
     * Used by GroupViewModel for ECIES encryption.
     */
    fun getPeerE2EPublicKey(peerAddress: String): String? {
        return zchatPreferences.getE2EPeerPublicKey(peerAddress)
    }

    /**
     * Check if we have completed key exchange with a peer.
     * Required for ECIES group key encryption.
     */
    fun hasCompletedKEX(peerAddress: String): Boolean {
        return zchatPreferences.isE2EKeyExchangeComplete(peerAddress)
    }

    /**
     * Manual refresh triggered by pull-to-refresh.
     * Forces the SDK to refresh transactions and balances, then updates the UI state.
     */
    fun refresh() {
        viewModelScope.launch {
            _isRefreshing.value = true
            try {
                // Force SDK to refresh transactions and balances
                val synchronizer = synchronizerProvider.getSynchronizer() as SdkSynchronizer
                Log.i("ZCHAT_SYNC", "Manual refresh: starting...")
                synchronizer.refreshTransactions()
                synchronizer.refreshAllBalances()
                Log.i("ZCHAT_SYNC", "Manual refresh: completed")
            } catch (e: Exception) {
                // Log but don't fail - the sync will continue in the background
                Log.w("ZCHAT_SYNC", "Manual refresh failed: ${e.message}")
            }
            _lastSyncTime.value = Instant.now()
            _isRefreshing.value = false
            // Reset countdown
            resetCountdown()
        }
    }

    // ==========================================
    // REMOTE KILL FUNCTIONALITY
    // ==========================================

    /**
     * Check if a transaction is a remote kill signal.
     * Kill signal requires:
     * 1. Remote kill to be enabled in preferences
     * 2. Transaction amount matches the configured kill amount
     * 3. Memo contains ZCHAT_DESTROY:<secret_phrase> where phrase hash matches stored hash
     */
    private suspend fun checkForRemoteKill(
        amountZatoshi: Long,
        memo: String?,
        txId: String,
        minedHeight: Long?,
    ) {
        // Skip if remote kill not enabled (cheap checks first)
        if (!zchatPreferences.isRemoteKillEnabled()) return
        if (!zchatPreferences.hasRemoteKillPhrase()) return

        // Every early return from here down to the in-memory guard is a pure read that leaves the
        // transaction UNCONSUMED, so it is judged again on its next offer. That matters: SDK 3.0.0 scans
        // the mempool, so a live kill signal is normally first offered unmined (or before the floor is
        // anchored), and marking it seen at that point used to swallow it for the rest of the session.

        // GUARD 1 (primary) — a transaction can only be a kill signal if it was mined ABOVE the
        // height at which remote kill was armed.
        //
        // convertToConversations re-derives the whole conversation list from the wallet's FULL
        // on-chain history on every emission of transactionRepository.transactions, so every
        // historical received memo is offered to this check again on every cold start (and a rescan
        // re-delivers a long backlog in one pass). Previously the only thing standing in the way was
        // the in-memory set above, which is empty at that moment — so one matching transaction
        // anywhere in a user's past wiped their wallet again on every single launch.
        //
        // A height floor is also the correct semantics in its own right: a transaction that predates
        // arming was never a kill signal, so it must not become one retroactively.
        val armedHeight = zchatPreferences.getRemoteKillArmedHeight()
        // No floor yet: fail CLOSED — an unknown floor must never authorise a wipe. The floor is
        // anchored from the chain tip by anchorRemoteKillFloorIfUnset (observeBlockHeight), NEVER here
        // from a transaction: the transaction that wrote the anchor was returned unevaluated and then
        // sat at or below the floor it wrote, so a genuine kill signal could be lost for good.
        if (armedHeight <= 0L) return
        // An unmined transaction has no height to judge against the floor. It is re-offered here
        // once it is mined — and, because nothing above consumed it, it is evaluated then.
        if (minedHeight == null || minedHeight <= armedHeight) return

        val killAmount = zchatPreferences.getRemoteKillAmount()

        // Check if amount matches
        if (amountZatoshi != killAmount) return

        // Check if memo matches kill signal format
        if (memo == null) return
        val trimmedMemo = memo.trim()
        if (!trimmedMemo.startsWith(ZMSGConstants.REMOTE_KILL_PREFIX)) return

        // Extract phrase from memo and verify against stored hash
        val phraseFromMemo = trimmedMemo.removePrefix(ZMSGConstants.REMOTE_KILL_PREFIX)
        if (zchatPreferences.verifyRemoteKillPhrase(phraseFromMemo)) {
            // Atomic check-and-add: add() returns false if already present, closing the TOCTOU race
            // of two concurrent scans acting on the same signal. Deliberately placed HERE, after every
            // "not (yet) a signal" return, so only a transaction that is being acted on is consumed.
            // NOTE: this set is IN MEMORY ONLY. It is empty on every cold start, so it is a
            // within-session race guard and NEVER the replay guard — that is GUARD 1 and GUARD 2.
            if (!processedKillCheckTxIds.add(txId)) return
            // GUARD 2 (defence in depth) — a durable record of the signals this install has already
            // acted on, so a replay is still refused if the floor above is ever lost (pref
            // corruption, a partial restore that keeps the phrase hash but not the height). Only
            // MATCHING txids are recorded, so this set stays tiny and never evicts under traffic.
            if (zchatPreferences.hasProcessedKillSignalTx(txId)) return
            // Recorded (and committed) BEFORE the wipe starts: if the wipe is interrupted, the
            // signal must not be able to fire a second time on the next launch.
            zchatPreferences.markKillSignalTxProcessed(txId)
            android.util.Log.w("ChatViewModel", "REMOTE KILL SIGNAL DETECTED!")
            // Trigger destruction from the ViewModel's own scope (this runs inside the auto-refresh flow
            // collection on viewModelScope, which is alive even when no chat screen is composed). destroyAll
            // performs the wipe under NonCancellable, so it always completes once started.
            destroyManager.destroyAll(requestUninstall = true)
        }
    }

    /**
     * Start the auto-refresh timer that syncs every 60 seconds.
     */
    private fun startAutoRefreshTimer() {
        autoRefreshJob?.cancel()
        countdownJob?.cancel()

        // Set initial sync time
        _lastSyncTime.value = Instant.now()
        _secondsUntilNextSync.value = AUTO_REFRESH_INTERVAL_SECONDS

        // Start countdown
        startCountdown()

        // Start auto-refresh
        autoRefreshJob = viewModelScope.launch {
            while (true) {
                delay(AUTO_REFRESH_INTERVAL_SECONDS * 1000L)
                performAutoRefresh()
            }
        }
    }

    private fun startCountdown() {
        countdownJob?.cancel()
        countdownJob = viewModelScope.launch {
            var seconds = AUTO_REFRESH_INTERVAL_SECONDS
            while (seconds > 0) {
                _secondsUntilNextSync.value = seconds
                delay(1000L)
                seconds--
            }
            _secondsUntilNextSync.value = 0
        }
    }

    private fun resetCountdown() {
        _secondsUntilNextSync.value = AUTO_REFRESH_INTERVAL_SECONDS
        startCountdown()
    }

    private suspend fun performAutoRefresh() {
        // Don't set isRefreshing = true for auto-refresh
        // This prevents the pull-to-refresh animation from showing
        // Silently refresh transactions and balances from SDK
        try {
            val synchronizer = synchronizerProvider.getSynchronizer() as SdkSynchronizer
            val syncStatus = synchronizer.status.value
            Log.d("ZCHAT_SYNC", "Auto-refresh: status=$syncStatus blockHeight=${_blockHeight.value}")
            synchronizer.refreshTransactions()
            synchronizer.refreshAllBalances()
            Log.d("ZCHAT_SYNC", "Auto-refresh completed: blockHeight=${_blockHeight.value}")
        } catch (e: Exception) {
            // Log but don't fail - the sync will continue in the background
            Log.w("ZCHAT_SYNC", "Auto-refresh failed: ${e.message}")
        }
        // #37 — piggyback the free-NOSTR ZMODE delivery retry on the refresh tick (cheap no-op when
        // nothing is pending; never on-chain).
        retryPendingModeSyncs()
        // D3-2 trigger 5: a PENDING/ACTIVE shield's claim no relay acknowledged yet (free relay DM, never on chain).
        retryQsClaims()
        recomputeQsAlerts()
        _lastSyncTime.value = Instant.now()
        resetCountdown()
    }

    override fun onCleared() {
        super.onCleared()
        autoRefreshJob?.cancel()
        countdownJob?.cancel()
        // Round 8 MA3: a pass waiting for the relays is not run for a cleared screen.
        groupAnnouncer.close()
        // ZC-1071: this screen's queue never runs now; its queued rows are what a closed screen left (other screens may
        // judge them). Sends already running (the process-wide send scope) release their rows when they end.
        LiveSenders.releaseWaiting(this)
        LiveSenders.stopListening(this)
    }

    /**
     * Send a chat message to the specified peer address.
     * Uses ZMSGv3 protocol:
     * - First message to a new contact: INIT format (includes full address)
     * - Subsequent messages: Hash format (saves ~238 bytes for longer messages)
     *
     * For long messages, automatically splits into multiple outputs (chunked messages).
     *
     * If user hasn't acknowledged message cost yet, shows disclaimer first.
     */
    // ==========================================
    // QUANTUM SHIELD
    // ==========================================

    /** Get the Quantum Shield status for a conversation. */
    fun getQuantumShieldStatus(peerAddress: String): co.electriccoin.zcash.ui.screen.chat.crypto.QuantumShieldStatus {
        val psk = zchatPreferences.getQuantumShieldPSK(peerAddress)
        val ourSecret = zchatPreferences.getQuantumShieldOurSecret(peerAddress)
        return when {
            !psk.isNullOrEmpty() -> co.electriccoin.zcash.ui.screen.chat.crypto.QuantumShieldStatus.ACTIVE
            !ourSecret.isNullOrEmpty() -> co.electriccoin.zcash.ui.screen.chat.crypto.QuantumShieldStatus.PENDING
            else -> co.electriccoin.zcash.ui.screen.chat.crypto.QuantumShieldStatus.NONE
        }
    }

    /** Generate (or reuse) our Quantum Shield secret and return its QR payload string. */
    fun initiateQuantumShield(peerAddress: String): String {
        // IDEMPOTENT: if setup is already in progress (PENDING: our secret exists, no PSK yet), REUSE
        // the existing secret so re-opening the dialog shows the SAME QR. Regenerating a fresh secret
        // on every tap was a real bug — it invalidated any QR the peer had already scanned, so their
        // derived PSK no longer matched ours and the shield silently never activated. Only generate a
        // new secret when starting fresh (NONE) or re-initiating after a reset.
        val existing = zchatPreferences.getQuantumShieldOurSecret(peerAddress)
        val pskExists = !zchatPreferences.getQuantumShieldPSK(peerAddress).isNullOrEmpty()
        // Any time a secret already exists (PENDING or ACTIVE), REUSE it — never regenerate over a live
        // secret: in PENDING a fresh secret invalidates a QR the peer already scanned; in ACTIVE it would
        // orphan the agreed PSK on re-entry. Re-keying must go through resetQuantumShield() first.
        if (!existing.isNullOrEmpty()) {
            val secret = java.util.Base64.getDecoder().decode(existing)
            Log.d("ZCHAT_QS", "Quantum Shield re-using existing secret (active=$pskExists) for ${peerAddress.redactAddress()}")
            // R6-5: show the secret in the form it was made in. A secret 2.12.4 made keeps its padded
            // (2.12.4) QR, because the peer may already have scanned it as a 2.12.4 QR.
            val payload = QuantumShield.toQRPayload(secret, boundCapable = QuantumShield.isBoundCapable(existing))
            // D3-2 trigger 1: sends only when this shield's claim was never acknowledged by a relay.
            requestQsClaim(peerAddress)
            return payload
        }
        val secret = co.electriccoin.zcash.ui.screen.chat.crypto.QuantumShield.generateRandom()
        // R6-5: stored (and shown) unpadded, which tells the peer this phone binds the key (QuantumShield.toQRPayload).
        val b64 = QuantumShield.encodeSecret(secret)
        zchatPreferences.setQuantumShieldOurSecret(peerAddress, b64)
        // Invalidate cached processor so next message uses new root (once PSK is active)
        messageProcessors.keys.removeAll { it.startsWith(peerAddress) }
        Log.d("ZCHAT_QS", "Quantum Shield generated NEW secret for ${peerAddress.redactAddress()}")
        // D3-2 trigger 1: the new secret's claim (state u, its commitment, no key check yet).
        requestQsClaim(peerAddress)
        refreshQuantumShieldAlert(peerAddress)
        return co.electriccoin.zcash.ui.screen.chat.crypto.QuantumShield.toQRPayload(secret)
    }

    /**
     * Safety String (SAS) of the most recently completed Quantum Shield exchange, or null.
     * The UI shows it with "confirm this code matches on both devices" so users can detect a
     * tampered/swapped QR out-of-band (B1l / Grok MED-016). Cleared via [clearQuantumShieldSas].
     */
    val quantumShieldSas: StateFlow<QuantumShieldConfirmation?>
        get() = _quantumShieldSas.asStateFlow()
    private val _quantumShieldSas = MutableStateFlow<QuantumShieldConfirmation?>(null)

    /** Dismiss the Quantum Shield SAS confirmation (user acknowledged the code). */
    fun clearQuantumShieldSas() {
        _quantumShieldSas.value = null
    }

    /** Process peer's scanned QR payload and activate the shield if our secret exists. */
    fun completeQuantumShield(peerAddress: String, qrPayload: String): Boolean {
        // B1l: the PSK is BOUND to the canonical peer pair (our E2E pubkey + theirs). We bind to the
        // EXACT base64 E2E pubkeys established during KEX — NOT to Zcash addresses — because addresses
        // have a documented history of representation drift (#205 self-address drift, group exact-match
        // bugs); if Alice's stored peerAddress for Bob ever differed from Bob's own address string the
        // two sides would derive DIFFERENT PSKs and the shield would silently fail. The pubkeys are
        // exact, drift-free, and equally symmetric: Alice's {ourPub, peerPub} == Bob's {peerPub, ourPub}.
        // QuantumShield is only offered on an E2E-ready chat so both are present; fail closed otherwise.
        val ourPubKey = zchatPreferences.getE2EOurPublicKey(peerAddress)
        val peerPubKey = zchatPreferences.getE2EPeerPublicKey(peerAddress)
        if (ourPubKey.isNullOrEmpty() || peerPubKey.isNullOrEmpty()) {
            Log.w("ZCHAT_QS", "Quantum Shield: E2E pubkeys not ready — cannot bind PSK, rejecting scan")
            return false
        }
        // Idempotent: if the shield is already ACTIVE, a second scan (user scans twice, or scans a
        // different/stale QR) must NOT silently re-derive and overwrite the agreed PSK — that would
        // desync us from the peer and break the shield. Treat a repeat completion as a no-op success
        // (and re-surface the SAS so the user can re-compare it).
        val existingPskB64 = zchatPreferences.getQuantumShieldPSK(peerAddress)
        val ourSecretB64 = zchatPreferences.getQuantumShieldOurSecret(peerAddress)?.takeIf { it.isNotEmpty() }
        val peerQr = QuantumShield.parsePeerQr(qrPayload)
        if (!existingPskB64.isNullOrEmpty()) {
            Log.d("ZCHAT_QS", "Quantum Shield already ACTIVE for ${peerAddress.redactAddress()} — ignoring repeat scan")
            val existingPsk = java.util.Base64.getDecoder().decode(existingPskB64)
            // R6-5: a code only when this setup's key is the bound one — a shield set up with a 2.12.4 phone
            // (or by a phone before its update) has no code the other phone can show.
            // C7: which key that is was recorded at setup; the QR scanned now never changes the key, so it must
            // not change the answer either (a padded rescan hid a bound setup's code; a garbled one showed a code
            // on a 2.12.4 setup). Only a shield set up before the record existed checks the stored key itself.
            val recorded = zchatPreferences.getQuantumShieldBound(peerAddress)
            // F11 (G3): a readable QR is compared with the stored key. One that matches neither key our secret could
            // have agreed with it is another chat's code, or the other phone set the shield up again (the two phones
            // now hold different keys). Say so, neutrally, and store nothing; the stored key never changes here.
            val match = storedKeyMatch(existingPsk, ourSecretB64, peerQr, ourPubKey, peerPubKey)
            if (match == StoredKeyMatch.NEITHER) {
                // D3-3: the other phone's verified claim commits to exactly this QR's secret: it set Extra Security up
                // again, so the two phones now hold different keys. Otherwise F11's neutral answer. Nothing is stored.
                val setUpAgain = peerQr != null && isClaimedPeerSecret(peerAddress, peerQr.secret)
                Log.w("ZCHAT_QS", "Quantum Shield rescan for ${peerAddress.redactAddress()} matches neither key (again=$setUpAgain)")
                _quantumShieldSas.value =
                    QuantumShieldConfirmation(
                        code = null,
                        problem = if (setUpAgain) QsProblem.OTHER_PHONE_SET_UP_AGAIN else QsProblem.NOT_THIS_CHATS_CODE,
                    )
                return false
            }
            // F11 (G28): a bound match proves the record, so a shield set up before it existed gets it now. A 2.12.4-key
            // match writes nothing (QuantumShieldConfirmationTest: a repeat scan writes no record it cannot prove).
            if (recorded == null && match == StoredKeyMatch.BOUND) zchatPreferences.setQuantumShieldBound(peerAddress, true)
            val bound = recorded ?: (match == StoredKeyMatch.BOUND)
            _quantumShieldSas.value = quantumShieldConfirmation(bound, existingPsk, ourPubKey, peerPubKey)
            return true
        }
        if (peerQr == null || ourSecretB64 == null) return false
        // D3-3 scan rule: a padded (2.12.4-format) QR is refused when the other phone's verified claim says its code is
        // not one — using it would silently leave this setup without a security code. Nothing is written.
        val claims = qsClaims
        if (claims != null && !QuantumShield.acceptsScan(verifiedPeerClaim(peerAddress)?.claim, peerQr)) {
            Log.w("ZCHAT_QS", "Quantum Shield scan for ${peerAddress.redactAddress()} refused: older QR format against the peer's claim")
            _quantumShieldSas.value = QuantumShieldConfirmation(code = null, problem = QsProblem.QR_OLD_FORMAT)
            return false
        }
        val ourSecret = java.util.Base64.getDecoder().decode(ourSecretB64)
        val ourSecretBoundCapable = QuantumShield.isBoundCapable(ourSecretB64)

        // R6-5: the key BOTH phones derive — identity-bound (B1l) only when both phones bind it. A 2.12.4 phone
        // (which cannot be updated) always derives the unbound key; deriving the bound one against it left the
        // two phones with different keys and the chat unreadable.
        val psk =
            QuantumShield.deriveAgreedPSK(
                ourSecret = ourSecret,
                ourSecretBoundCapable = ourSecretBoundCapable,
                peer = peerQr,
                ourBinding = ourPubKey,
                peerBinding = peerPubKey,
            )
        val pskB64 = java.util.Base64.getEncoder().encodeToString(psk)
        val bound = QuantumShield.usesBoundKey(ourSecretBoundCapable, peerQr.boundCapable)
        // C7: record which key this is BEFORE the key itself, so a shield that is on always has the record (a
        // crash in between leaves the setup pending, and the next completion writes the record again).
        zchatPreferences.setQuantumShieldBound(peerAddress, bound)
        // D3-3: the setup record (when, and which QR we scanned) between the bound record and the key, so a shield that
        // is on has it; a crash before the key leaves the setup pending and the next completion writes it again.
        claims?.storeSetupRecord(peerAddress, QsSetupRecord(System.currentTimeMillis(), QuantumShield.commitment(peerQr.secret)))
        zchatPreferences.setQuantumShieldPSK(peerAddress, pskB64)
        _quantumShieldSas.value = quantumShieldConfirmation(bound, psk, ourPubKey, peerPubKey)
        if (!bound) Log.d("ZCHAT_QS", "Quantum Shield uses the 2.12.4 key for ${peerAddress.redactAddress()} (no code)")

        // Invalidate cached processor — new root key includes PSK
        messageProcessors.keys.removeAll { it.startsWith(peerAddress) }
        Log.d("ZCHAT_QS", "Quantum Shield ACTIVE for ${peerAddress.redactAddress()}")
        // D3-2 trigger 2: a new setup — the claim now carries the key check of the agreed key.
        requestQsClaim(peerAddress)
        refreshQuantumShieldAlert(peerAddress)
        return true
    }

    /** F11: which key of our secret and a rescanned QR the stored key is. */
    private enum class StoredKeyMatch { BOUND, UNBOUND, NEITHER, UNKNOWN }

    /**
     * C7 / F11: for a shield that is on — whether the stored key IS the bound key or the 2.12.4 key of our secret and
     * the rescanned QR's secret (whatever the QR's padding), or neither. An unreadable QR or a missing secret gives
     * UNKNOWN: nothing to compare, never "bound" by default. Derivation is unchanged; this only re-derives to compare
     * (constant time), it stores nothing.
     */
    private fun storedKeyMatch(
        storedPsk: ByteArray,
        ourSecretB64: String?,
        peerQr: QuantumShield.PeerQr?,
        ourPubKey: String,
        peerPubKey: String,
    ): StoredKeyMatch {
        if (ourSecretB64 == null || peerQr == null) return StoredKeyMatch.UNKNOWN
        val ourSecret =
            runCatching {
                java.util.Base64
                    .getDecoder()
                    .decode(ourSecretB64)
            }.getOrNull() ?: return StoredKeyMatch.UNKNOWN
        val boundKey = QuantumShield.derivePSK(ourSecret, peerQr.secret, ourPubKey, peerPubKey)
        if (java.security.MessageDigest.isEqual(boundKey, storedPsk)) return StoredKeyMatch.BOUND
        val unboundKey = QuantumShield.derivePSK(ourSecret, peerQr.secret)
        if (java.security.MessageDigest.isEqual(unboundKey, storedPsk)) return StoredKeyMatch.UNBOUND
        return StoredKeyMatch.NEITHER
    }

    /** The code to compare when the key is bound, or the "no code for this setup" confirmation (R6-5). */
    private fun quantumShieldConfirmation(
        bound: Boolean,
        psk: ByteArray,
        ourPubKey: String,
        peerPubKey: String,
    ) = QuantumShieldConfirmation(
        code = if (bound) QuantumShield.computeSafetyString(psk, ourPubKey, peerPubKey) else null
    )

    /** Reset Quantum Shield to NONE — clears PSK and secrets for this peer. */
    fun resetQuantumShield(peerAddress: String) {
        zchatPreferences.clearQuantumShieldPSK(peerAddress)
        // Clear our secret too so the UI returns to NONE
        zchatPreferences.setQuantumShieldOurSecret(peerAddress, "")
        // A pending SAS confirmation is meaningless after a reset
        _quantumShieldSas.value = null
        messageProcessors.keys.removeAll { it.startsWith(peerAddress) }
        Log.d("ZCHAT_QS", "Quantum Shield RESET for ${peerAddress.redactAddress()}")
        // D3-2 trigger 3: tell the other phone this side has no shield any more (state n).
        requestQsClaim(peerAddress)
        refreshQuantumShieldAlert(peerAddress)
    }

    // ==========================================
    // D3-2: QUANTUM SHIELD SIGNED CLAIM — the carrier (t5-specs SPECS §2.2)
    // ==========================================
    //
    // The claim (QsClaim, D3-1) is the content of one relay DM sent with NostrChatBridge.publish: free, never on chain,
    // never a proposal. Sent only to a Tunnel or Open chat (read when sending; an unset mode counts as Shielded) whose
    // relay key, E2E keys and relay publisher exist, whose peer key did not change, that is not one of our own chat
    // identities, and never while a Keystone account is selected. Received only in the relay reader's read-receipt
    // branch, stored only when the peer's E2E key signed it for ours. D3-3 acts on the stored claims; nothing here
    // shows anything.

    /** Triggers 1-4: send this chat's current claim unless a relay already acknowledged it (off the main thread). */
    private fun requestQsClaim(peerAddress: String) {
        if (qsClaims == null) return
        viewModelScope.launch(Dispatchers.IO) { sendQsClaim(peerAddress) }
    }

    /**
     * Trigger 5, from the refresh tick right after [retryPendingModeSyncs]: the claim of every PENDING or ACTIVE shield
     * that no relay acknowledged yet (a 0-ack publish, or a shield set up before this update). Writes nothing unless it
     * actually sends a claim (FD-5: after Destroy no preference file may come back).
     */
    private fun retryQsClaims() {
        if (qsClaims == null) return
        if (!NostrChatBridge.isOutboundReady()) return
        if (chatClosedForSelectedAccount()) return
        viewModelScope.launch(Dispatchers.IO) {
            val peers = runCatching { zchatPreferences.getRelayModePeers() }.getOrElse { return@launch }
            for (peer in peers) {
                if (getQuantumShieldStatus(peer) == co.electriccoin.zcash.ui.screen.chat.crypto.QuantumShieldStatus.NONE) continue
                sendQsClaim(peer)
            }
        }
    }

    /**
     * Sends [peerAddress]'s claim once per change. The process-wide [qsClaimInFlight] lets one screen publish at a time
     * (the list and the detail screen tick together); a request that arrives meanwhile is kept in [qsClaimWanted] and
     * handled by the sender that holds the peer, so a turn-off during a start's publish still sends its "n".
     */
    private suspend fun sendQsClaim(peerAddress: String) {
        qsClaimWanted.add(peerAddress)
        while (peerAddress in qsClaimWanted && qsClaimInFlight.add(peerAddress)) {
            try {
                while (qsClaimWanted.remove(peerAddress)) publishQsClaimOnce(peerAddress)
            } finally {
                qsClaimInFlight.remove(peerAddress)
            }
        }
    }

    @Suppress("ReturnCount", "TooGenericExceptionCaught")
    private suspend fun publishQsClaimOnce(peerAddress: String) {
        val claims = qsClaims ?: return
        if (!NostrChatBridge.isOutboundReady()) return
        if (chatClosedForSelectedAccount()) return
        if (zchatPreferences.isSelfAddress(peerAddress)) return
        val relayKey = zchatPreferences.getPeerNostrPubkey(peerAddress)?.takeIf { it.isNotBlank() } ?: return
        if (zchatPreferences.getConversationMode(peerAddress) == ConversationMode.VAULT) return
        if (zchatPreferences.isE2EKeyChanged(peerAddress)) return
        val privateKey = zchatPreferences.getE2EPrivateKey(peerAddress)?.takeIf { it.isNotEmpty() } ?: return
        val ourPub = zchatPreferences.getE2EOurPublicKey(peerAddress)?.takeIf { it.isNotEmpty() } ?: return
        val peerPub = zchatPreferences.getE2EPeerPublicKey(peerAddress)?.takeIf { it.isNotEmpty() } ?: return
        val current = ourQsClaim(peerAddress, ourPub, peerPub) ?: return
        val body = "${current.state}|${current.commit}|${current.kc}"
        val own = claims.ownClaim(peerAddress)
        // The same body keeps its seq (a resend the peer drops as not newer); a new body gets a higher one.
        val unchangedSeq = own?.takeIf { it.body == body }?.seq
        if (unchangedSeq != null && claims.sentSeq(peerAddress) >= unchangedSeq) return // a relay already has it
        // Our seq is committed BEFORE the publish: a crash after it never reuses the seq for another body.
        val seq = unchangedSeq ?: QsClaim.nextSeq(own?.seq ?: 0L, System.currentTimeMillis())
        if (unchangedSeq == null && !claims.commitOwnClaim(peerAddress, seq, body)) return
        val line =
            runCatching { current.copy(seq = seq).sign(privateKey, ourPub, peerPub).encode() }
                .getOrElse {
                    Log.w("ZCHAT_QS", "Quantum Shield claim for ${peerAddress.redactAddress()} not signed (${it.javaClass.simpleName})")
                    return
                }
        val acks =
            try {
                NostrChatBridge.publish(line, relayKey).acks
            } catch (e: Exception) {
                if (e is kotlinx.coroutines.CancellationException) throw e
                0
            }
        // Only a relay's acknowledgement makes it sent; 0 acks → the next trigger or tick tries again.
        if (acks > 0) claims.markSent(peerAddress, seq)
        Log.d("ZCHAT_QS", "Quantum Shield claim (${current.state}) to ${peerAddress.redactAddress()}: acks=$acks")
    }

    /** Our current claim for this chat, unsigned (seq 0): what our shield is, as one-way values only. */
    private fun ourQsClaim(
        peerAddress: String,
        ourPub: String,
        peerPub: String,
    ): QsClaim? {
        val secretB64 = zchatPreferences.getQuantumShieldOurSecret(peerAddress)?.takeIf { it.isNotEmpty() }
        val secret =
            secretB64?.let {
                runCatching {
                    java.util.Base64
                        .getDecoder()
                        .decode(it)
                }.getOrNull() ?: return null
            }
        val kc =
            zchatPreferences.getQuantumShieldPSK(peerAddress)?.takeIf { it.isNotEmpty() }?.let {
                val psk =
                    runCatching {
                        java.util.Base64
                            .getDecoder()
                            .decode(it)
                    }.getOrNull() ?: return null
                QuantumShield.keyCheck(psk, ourPub, peerPub)
            } ?: ""
        val state =
            when {
                secretB64 == null -> QsClaim.STATE_NONE
                QuantumShield.isBoundCapable(secretB64) -> QsClaim.STATE_UNPADDED
                else -> QsClaim.STATE_PADDED
            }
        val commit = secret?.let { QuantumShield.commitment(it) } ?: ""
        return QsClaim(state = state, commit = commit, kc = kc, seq = 0L, sig = "")
    }

    /**
     * The one gate every use of the peer's claim goes through: the stored record, only while it was signed by the
     * peer's current E2E key for our current one and the peer's key did not change. Covers all four key-change sites
     * (three in handleKEXMessage and bindPeerNostrKey), since each sets the flag this reads.
     */
    private fun verifiedPeerClaim(peerAddress: String): QsPeerClaim? {
        val claims = qsClaims ?: return null
        val record = claims.peerClaim(peerAddress) ?: return null
        if (zchatPreferences.isE2EKeyChanged(peerAddress)) return null
        val peerPub = zchatPreferences.getE2EPeerPublicKey(peerAddress)?.takeIf { it.isNotEmpty() } ?: return null
        val ourPub = zchatPreferences.getE2EOurPublicKey(peerAddress)?.takeIf { it.isNotEmpty() } ?: return null
        if (record.signerPub != peerPub || record.otherPub != ourPub) return null
        return record.takeIf { it.claim != null }
    }

    /**
     * The relay reader's read-receipt branch: stores a claim from an attributed peer whose key did not change, when it
     * parses strictly, the peer's E2E key signed it for ours, and its seq is above the stored claim's — a stored claim
     * that no longer passes [verifiedPeerClaim] (the peer reset its key) never blocks. Then trigger 4: our claim goes
     * back only if no relay acknowledged it yet (answered once, no ping-pong). The log names the reason only.
     */
    @Suppress("ReturnCount")
    private fun recordQsPeerClaim(
        peerAddress: String,
        line: String,
    ) {
        val claims = qsClaims ?: return
        if (!line.startsWith(QsClaim.PREFIX)) return // a plain read receipt: nothing to store
        if (peerAddress.isEmpty() || peerAddress == NostrChatBridge.UNATTRIBUTED_BOOT) {
            Log.w("ZCHAT_QS", "Quantum Shield claim dropped: unattributed sender")
            return
        }
        if (zchatPreferences.isE2EKeyChanged(peerAddress)) {
            Log.w("ZCHAT_QS", "Quantum Shield claim dropped: key-changed peer ${peerAddress.redactAddress()}")
            return
        }
        val claim = QsClaim.parse(line)
        val peerPub = zchatPreferences.getE2EPeerPublicKey(peerAddress)?.takeIf { it.isNotEmpty() }
        val ourPub = zchatPreferences.getE2EOurPublicKey(peerAddress)?.takeIf { it.isNotEmpty() }
        if (claim == null || peerPub == null || ourPub == null || !claim.verify(peerPub, ourPub)) {
            Log.w("ZCHAT_QS", "Quantum Shield claim dropped: not verified for ${peerAddress.redactAddress()}")
            return
        }
        val storedSeq = verifiedPeerClaim(peerAddress)?.claim?.seq
        if (storedSeq != null && claim.seq <= storedSeq) {
            Log.d("ZCHAT_QS", "Quantum Shield claim dropped: not newer for ${peerAddress.redactAddress()}")
            return
        }
        val record = QsPeerClaim(line = line, signerPub = peerPub, otherPub = ourPub, rxAt = System.currentTimeMillis())
        if (!claims.storePeerClaim(peerAddress, record)) return
        Log.d("ZCHAT_QS", "Quantum Shield claim (${claim.state}) stored for ${peerAddress.redactAddress()}")
        refreshQuantumShieldAlert(peerAddress)
        requestQsClaim(peerAddress)
    }

    // ==========================================
    // D3-3: QUANTUM SHIELD CLAIM ALERTS (t5-specs SPECS §2.2 "Alerts")
    // ==========================================

    /**
     * The claim alert of every chat this screen computed one for (QsAlert.NONE when there is nothing to show). Its own
     * holder: the scan confirmation ([quantumShieldSas]) never carries it. Recomputed on every stored claim, every local
     * Quantum Shield change, the refresh tick and when a chat opens ([refreshQuantumShieldAlert]); never sticky.
     */
    val quantumShieldAlerts: StateFlow<Map<String, QsAlert>>
        get() = qsAlertHolder()

    private fun qsAlertHolder(): MutableStateFlow<Map<String, QsAlert>> =
        qsAlertFlow ?: synchronized(this) {
            qsAlertFlow ?: MutableStateFlow<Map<String, QsAlert>>(emptyMap()).also { qsAlertFlow = it }
        }

    /**
     * ZC-1476: the Extra Security status of every chat this screen read, as state, so the ⋮ entry and the header follow a
     * local change (enable, scan, cancel, turn off) without waiting for an unrelated recomposition. Updated with
     * [refreshQuantumShieldAlert], which every local Quantum Shield change and the chat opening call.
     */
    val quantumShieldStatuses: StateFlow<Map<String, co.electriccoin.zcash.ui.screen.chat.crypto.QuantumShieldStatus>>
        get() = qsStatusHolder()

    @Volatile private var qsStatusFlow: MutableStateFlow<Map<String, co.electriccoin.zcash.ui.screen.chat.crypto.QuantumShieldStatus>>? =
        null

    private fun qsStatusHolder(): MutableStateFlow<Map<String, co.electriccoin.zcash.ui.screen.chat.crypto.QuantumShieldStatus>> =
        qsStatusFlow ?: synchronized(this) {
            qsStatusFlow ?: MutableStateFlow<Map<String, co.electriccoin.zcash.ui.screen.chat.crypto.QuantumShieldStatus>>(emptyMap())
                .also { qsStatusFlow = it }
        }

    /** Recomputes [peerAddress]'s alert (and, ZC-1476, its status) from what is stored now. Reads only; writes nothing. */
    fun refreshQuantumShieldAlert(peerAddress: String) {
        runCatching { getQuantumShieldStatus(peerAddress) }.getOrNull()?.let { status ->
            val statuses = qsStatusHolder()
            synchronized(statuses) { statuses.value = statuses.value + (peerAddress to status) }
        }
        if (qsClaims == null) return
        val alert = runCatching { computeQsAlert(peerAddress) }.getOrDefault(QsAlert.NONE)
        val holder = qsAlertHolder()
        synchronized(holder) { holder.value = holder.value + (peerAddress to alert) }
    }

    /**
     * The refresh tick, right after [retryQsClaims]: every chat this screen shows an alert for, and every Tunnel or Open
     * chat (the ones claims are sent in). Reads only, so it writes nothing (FD-5).
     */
    private fun recomputeQsAlerts() {
        if (qsClaims == null) return
        val relayPeers = runCatching { zchatPreferences.getRelayModePeers() }.getOrDefault(emptyList())
        (qsAlertHolder().value.keys + relayPeers).forEach { refreshQuantumShieldAlert(it) }
    }

    @Suppress("ReturnCount")
    private fun computeQsAlert(peerAddress: String): QsAlert {
        val claims = qsClaims ?: return QsAlert.NONE
        val record = verifiedPeerClaim(peerAddress) ?: return QsAlert.NONE
        val pskB64 = zchatPreferences.getQuantumShieldPSK(peerAddress)?.takeIf { it.isNotEmpty() } ?: return QsAlert.NONE
        val ourPub = zchatPreferences.getE2EOurPublicKey(peerAddress)?.takeIf { it.isNotEmpty() } ?: return QsAlert.NONE
        val peerPub = zchatPreferences.getE2EPeerPublicKey(peerAddress)?.takeIf { it.isNotEmpty() } ?: return QsAlert.NONE
        val psk =
            runCatching {
                java.util.Base64
                    .getDecoder()
                    .decode(pskB64)
            }.getOrNull() ?: return QsAlert.NONE
        val secretB64 = zchatPreferences.getQuantumShieldOurSecret(peerAddress)?.takeIf { it.isNotEmpty() }
        val setup = claims.setupRecord(peerAddress)
        val own =
            QuantumShield.OwnShield(
                keyCheck = QuantumShield.keyCheck(psk, ourPub, peerPub),
                bound = zchatPreferences.getQuantumShieldBound(peerAddress),
                secretUnpadded = secretB64 != null && QuantumShield.isBoundCapable(secretB64),
                activeAt = setup?.activeAt ?: 0L,
                setupPeerCommit = setup?.peerCommit,
            )
        return QuantumShield.alertFor(own, record.claim, record.rxAt)
    }

    /** D3-3: whether the other phone's newest verified claim commits to exactly [secret] (the QR it shows now). */
    private fun isClaimedPeerSecret(
        peerAddress: String,
        secret: ByteArray,
    ): Boolean {
        val claim = verifiedPeerClaim(peerAddress)?.claim ?: return false
        return claim.commit.isNotEmpty() && claim.commit == QuantumShield.commitment(secret)
    }

    /**
     * Quantum Shield PSK bytes for this conversation, or null when the shield isn't ACTIVE.
     * Mixed into every file-key wrap/unwrap (HIGH-003) so attachments get the same post-quantum
     * layer as the message ratchet (deriveRatchetRoot already mixes it). ACTIVE is defined as a
     * non-empty stored PSK, so a non-null return here IS the fail-closed guarantee: whenever the
     * shield is active the PSK is mixed — there is no active-but-omitted path.
     */
    private fun getQuantumShieldPSKBytes(peerAddress: String): ByteArray? =
        zchatPreferences.getQuantumShieldPSK(peerAddress)
            ?.takeIf { it.isNotEmpty() }
            ?.let { java.util.Base64.getDecoder().decode(it) }

    /**
     * Download, decrypt, and cache a file referenced by a ZFILE message.
     * Called in the background when a ZFILE message is detected.
     */
    fun downloadAndCacheFile(
        zfileContent: String,
        peerAddress: String,
        context: android.content.Context,
    ) {
        // ZC-1474: a free attachment's ZATT line carries the file key itself (read only from the bound relay key, kept in
        // the encrypted pending store); a ZFILE's key is unwrapped with the chat's shared key below.
        val zatt = ZATTMessage.parse(zfileContent)
        val parsed = ZATTMessage.fileRefOf(zfileContent) ?: return
        // SECURITY (view-once + D11 TTL-expiry): a burned hash — view-once consumed via
        // markFileViewed(), OR TTL-expired and purged by the convertToConversations sweep — has had
        // its cache file securely wiped + deleted, after which the auto-download trigger sees
        // `!cacheFile.exists()` and would re-fetch the file from the relay, resurrecting content
        // that was already destroyed. Refuse to re-download ANY already-burned hash.
        if (zchatPreferences.isFileViewed(parsed.hash)) return
        val cache = getFileCache(context)
        if (cache.has(parsed.hash)) return // Already cached
        // Reject before touching the network if the memo itself declares an oversized file.
        if (parsed.size > maxFileDownloadBytes) {
            Log.e("ZCHAT_FILE", "Refusing oversized ZFILE ${parsed.hash}: declared size=${parsed.size} > cap=$maxFileDownloadBytes")
            return
        }
        if (fileDownloadsInProgress.putIfAbsent(parsed.hash, true) != null) return // Already downloading
        // #211: run on Dispatchers.IO — this coroutine streams + decrypts the blob and writes it to the
        // disk cache (FileDownloadCache.put). On the default Main dispatcher that disk write trips
        // StrictMode (and risks jank/ANR for larger files). The progress/state updates below are
        // StateFlow writes, safe from any thread.

        viewModelScope.launch(kotlinx.coroutines.Dispatchers.IO) {
            try {
                // Clear any prior failure marker so a manual retry repaints as "in progress".
                setFileDownloadFailed(parsed.hash, false)
                Log.d("ZCHAT_FILE", "Downloading file: ${parsed.url.redactUrl()}")
                updateFileProgress(parsed.hash, 0f)

                // Stream the encrypted file with byte-level progress, enforcing a hard size cap as we
                // read so a lying/absent Content-Length can't make us buffer an unbounded body into
                // memory (OOM). Reserve the last 5% of the bar for decrypt+cache write so the user
                // doesn't see "100%" while we're still working.
                val client = fileHttpClientProvider.create()
                val encryptedBytes = try {
                    client.prepareGet(parsed.url) {
                        onDownload { bytesReceivedTotal, contentLength ->
                            val total = contentLength ?: parsed.size
                            if (total > 0) {
                                updateFileProgress(parsed.hash, (bytesReceivedTotal.toFloat() / total) * 0.95f)
                            }
                        }
                    }.execute { response ->
                        val declaredLen = response.headers[io.ktor.http.HttpHeaders.ContentLength]?.toLongOrNull()
                        if (declaredLen != null && declaredLen > maxFileDownloadBytes) {
                            throw java.io.IOException("Content-Length $declaredLen exceeds cap $maxFileDownloadBytes")
                        }
                        val channel = response.bodyAsChannel()
                        val out = java.io.ByteArrayOutputStream()
                        val buf = ByteArray(64 * 1024)
                        var total = 0L
                        while (true) {
                            val read = channel.readAvailable(buf, 0, buf.size)
                            if (read == -1) break
                            if (read == 0) continue
                            total += read
                            if (total > maxFileDownloadBytes) {
                                throw java.io.IOException("download exceeded cap $maxFileDownloadBytes mid-stream")
                            }
                            out.write(buf, 0, read)
                        }
                        out.toByteArray()
                    }
                } finally {
                    client.close()
                }

                Log.d("ZCHAT_FILE", "Downloaded ${encryptedBytes.size} bytes from ${parsed.url.redactUrl()}")

                // Verify integrity: size + SHA-256 of ciphertext must match ZFILE metadata
                if (!co.electriccoin.zcash.ui.screen.chat.filesharing.FileIntegrityCheck.verify(
                        encryptedBytes, parsed.hash, parsed.size
                    )
                ) {
                    Log.e("ZCHAT_FILE", "Integrity check FAILED for ${parsed.hash} — " +
                        "expected size=${parsed.size} got=${encryptedBytes.size}")
                    setFileDownloadFailed(parsed.hash, true)
                    return@launch
                }

                // ZC-1474: a free attachment's ZATT line carries its file key; no shared key is read or needed.
                if (zatt != null) {
                    val opened =
                        co.electriccoin.zcash.ui.screen.chat.crypto.E2EEncryption
                            .decryptFile(encryptedBytes, zatt.fileKey)
                    cache.put(parsed.hash, opened)
                    updateFileProgress(parsed.hash, 1f)
                    return@launch
                }

                // Unwrap key using the E2E shared secret. If we have NO shared secret with this peer
                // we cannot decrypt — ABORT, don't silently unwrap with an all-zero key. A zero key is
                // predictable and identical across peers; falling back to it contradicts the app's
                // "fail closed, never weaken crypto" policy. Surface as a failed download instead.
                val sharedKey = getE2ESharedKey(peerAddress)
                if (sharedKey == null) {
                    Log.e("ZCHAT_FILE", "No E2E shared secret with ${peerAddress.redactAddress()} — cannot decrypt file ${parsed.hash} (need KEX first)")
                    setFileDownloadFailed(parsed.hash, true)
                    return@launch
                }
                val wrappedKeyBytes = java.util.Base64.getDecoder().decode(parsed.wrappedKey)
                // Mix the Quantum Shield PSK when the shield is ACTIVE (HIGH-003 — matches the wrap
                // side and the message ratchet). Files wrapped BEFORE the shield activated (or by an
                // older build) are classical-only; falling back to a PSK-less unwrap for those does
                // not weaken anything — it only reads what the sender actually produced.
                val qsPsk = getQuantumShieldPSKBytes(peerAddress)
                val fileKey = try {
                    co.electriccoin.zcash.ui.screen.chat.crypto.E2EEncryption.unwrapFileKey(wrappedKeyBytes, sharedKey, psk = qsPsk)
                } catch (e: javax.crypto.AEADBadTagException) {
                    if (qsPsk == null) throw e
                    co.electriccoin.zcash.ui.screen.chat.crypto.E2EEncryption.unwrapFileKey(wrappedKeyBytes, sharedKey)
                }
                // A corrupt or forged wrappedKey can unwrap to a wrong-sized key — reject before use.
                require(fileKey.size == 32) { "Unwrapped file key has wrong size: ${fileKey.size}" }

                // Decrypt
                val decryptedBytes = co.electriccoin.zcash.ui.screen.chat.crypto.E2EEncryption.decryptFile(encryptedBytes, fileKey)
                Log.d("ZCHAT_FILE", "Decrypted ${decryptedBytes.size} bytes, caching as ${parsed.hash}")

                // Cache
                cache.put(parsed.hash, decryptedBytes)
                updateFileProgress(parsed.hash, 1f)
            } catch (e: Exception) {
                Log.w("ZCHAT_FILE", "File download/decrypt failed for ${parsed.hash}: ${e.message}")
                setFileDownloadFailed(parsed.hash, true)
            } finally {
                fileDownloadsInProgress.remove(parsed.hash)
                // Brief visible "100%" then clear so the bubble flips to the image. If we cleared
                // immediately the bar would flash off before the bitmap decode finishes.
                kotlinx.coroutines.delay(500)
                updateFileProgress(parsed.hash, null)
            }
        }
    }

    /**
     * SR-C2 — why a photo, file or voice note cannot be sent to [peerAddress] now, or null when it can. Every attachment's
     * file key is wrapped with the chat's end-to-end shared key ([getE2ESharedKey]); only a key exchange makes one, and
     * an Open chat never makes one. The gate is keyed on that key, not on the chat's mode: a Tunnel chat or a Shielded
     * chat with a new contact can lack it too.
     */
    fun attachmentBlockReason(peerAddress: String): AttachmentBlockReason? {
        // ZC-1793: under an unpaid answer the shared key exists but nothing may be sealed with it (ZC-1792 F1).
        val keyed = getE2ESharedKey(peerAddress) != null
        val answerUnpaid = keyed && ownAnswerToStoredKeyUnpaid(peerAddress)
        if (keyed && !answerUnpaid) return null
        // ZC-1474 (W-123): no key is needed for the free relay path (Open or Tunnel, bound relay key, zatt1 recorded).
        if (attachmentRoute(peerAddress) == AttachmentTransport.Route.NOSTR_ZATT) return null
        if (answerUnpaid) return AttachmentBlockReason.PEER_MUST_ACCEPT
        val ourKey = zchatPreferences.getE2EOurPublicKey(peerAddress)
        // P2d: no key is created for this contact until this process has read the wallet's history (the send path's rule;
        // the provider reads the same process-wide flag, which the history scan sets).
        val historyUnread =
            seedKeyProvider.isKeyCreationWaitingForHistory(peerAddress) || !SeedDerivedE2EKeyProvider.processOwnHistoryRead.get()
        return when {
            ourKey == null && historyUnread -> AttachmentBlockReason.STILL_READING_HISTORY
            // ZC-1474: the contact's KEX waits here behind Accept; only that Accept makes the key.
            zchatPreferences.getInboundKexAwaitingAccept(peerAddress) != null ->
                AttachmentBlockReason.PEER_MUST_ACCEPT
            // ZC-1474: our key pair is made before anything is paid, so it alone proves nothing went out. A KEX still owed
            // with none of ours on chain was never sent.
            ourKey != null &&
                zchatPreferences.getE2EPeerPublicKey(peerAddress) == null &&
                zchatPreferences.isKexOwed(peerAddress) &&
                zchatPreferences.getKexTxIds(peerAddress).isEmpty() ->
                AttachmentBlockReason.KEX_NOT_SENT
            // Our KEX exists; the contact's answer has not arrived. A switch or a message would not make a new one.
            ourKey != null && zchatPreferences.getE2EPeerPublicKey(peerAddress) == null ->
                AttachmentBlockReason.KEY_EXCHANGE_UNANSWERED
            zchatPreferences.getConversationMode(peerAddress) == ConversationMode.VAULT ->
                AttachmentBlockReason.NEEDS_KEY_EXCHANGE_SHIELDED
            else -> AttachmentBlockReason.NEEDS_KEY_EXCHANGE
        }
    }

    /** ZC-1474 (W-123) — which way an attachment to [peerAddress] goes now ([AttachmentTransport.choose]). */
    private fun attachmentRoute(peerAddress: String): AttachmentTransport.Route =
        AttachmentTransport.choose(
            mode = zchatPreferences.getConversationMode(peerAddress),
            peerNostrKeyBound = !zchatPreferences.getPeerNostrPubkey(peerAddress).isNullOrBlank(),
            peerCap2130 = peerReadsZatt(peerAddress),
            // ZC-1793: a key we may not seal with yet (ZC-1792 F1) is no wrap route; the free relay route stays open.
            hasE2ESharedKey = getE2ESharedKey(peerAddress) != null && !ownAnswerToStoredKeyUnpaid(peerAddress),
        )

    /** ZC-1474 — the contact's newest relay rumor carried zatt1 (no record, or a store that cannot be read: false). */
    private fun peerReadsZatt(peerAddress: String): Boolean =
        runCatching { zchatPreferences.getPeerZattCap(peerAddress) }.getOrNull()?.capIronwood == true

    /**
     * ZC-1474 — the bound relay key a ZATT may go to now, or null: the chat is Open or Tunnel, the key is bound, zatt1 is
     * recorded (a shared key does not matter here), the contact's key did not change, and no Keystone account closes the
     * chat. Asked again after the upload and by [sendMessage]'s backstop.
     */
    private fun zattRecipientKey(peerAddress: String): String? {
        val key = zchatPreferences.getPeerNostrPubkey(peerAddress)?.takeIf { it.isNotBlank() } ?: return null
        val open =
            AttachmentTransport.freeRouteOpen(
                mode = zchatPreferences.getConversationMode(peerAddress),
                peerNostrKeyBound = true,
                peerCap2130 = peerReadsZatt(peerAddress),
            )
        if (!open || zchatPreferences.isE2EKeyChanged(peerAddress) || chatClosedForSelectedAccount()) return null
        return key
    }

    /** ZC-1474 — why a ZATT cannot go to [peerAddress] now, as the row and the notice say it. */
    private fun zattRefusalReason(peerAddress: String): String =
        when {
            chatClosedForSelectedAccount() -> ChatSendCopy.KEYSTONE_CHATS_CLOSED
            zchatPreferences.isE2EKeyChanged(peerAddress) -> ChatSendCopy.KEY_CHANGED_VERIFY
            zchatPreferences.getConversationMode(peerAddress) == ConversationMode.VAULT -> ChatSendCopy.ATTACHMENT_SWITCHED_TO_SHIELDED
            else -> ChatSendCopy.ATTACHMENT_NEEDS_KEY_EXCHANGE
        }

    /**
     * SR-C2 — the chat screen asks this before it opens a picker, the camera or the recorder, and every attachment
     * handler asks it at its entry (before the upload slot, before anything is read or compressed). True: the chat has
     * no key to lock an attachment with, the notice is on screen, and nothing was prepared, uploaded, sent or paid.
     */
    fun refuseAttachmentIfBlocked(peerAddress: String): Boolean {
        // ZC-250: a key-changed chat still has its old key, so SR-C2's gate alone would read, encrypt and upload the
        // attachment before sendMessage's key-change gate refused its link. Refuse here first: nothing is read,
        // uploaded, sent or paid, and the key-changed notice shows.
        if (blockedByKeyChange(peerAddress)) {
            Log.w("ZCHAT_FILE", "ZC-250: attachment refused before anything was prepared — the contact's key changed")
            return true
        }
        val reason = attachmentBlockReason(peerAddress) ?: return false
        Log.w("ZCHAT_FILE", "SR-C2: attachment refused before anything was prepared — $reason")
        showAttachmentBlocked(reason)
        return true
    }

    /** SR-C2 — the notice for [reason]: the key-exchange dialog, or a plain notice while the history is still read. */
    private fun showAttachmentBlocked(reason: AttachmentBlockReason) {
        _sendMessageState.value =
            if (reason == AttachmentBlockReason.STILL_READING_HISTORY) {
                SendMessageState.Error(ChatSendCopy.ATTACHMENT_STILL_READING_HISTORY)
            } else {
                SendMessageState.AttachmentNeedsKeyExchange(reason)
            }
    }

    /**
     * SR-C2 — the backstop: the key vanished between the entry check and the wrap (a key reset in between). Nothing was
     * uploaded; the optimistic bubble goes (no FAILED row whose Retry could never work) and the notice is shown.
     */
    private fun refuseAttachmentWithoutKey(
        peerAddress: String,
        optimisticId: String,
    ) {
        Log.w("ZCHAT_FILE", "SR-C2: no end-to-end key at the wrap — attachment dropped before upload")
        pendingMessages.update { list -> list.filterNot { it.id == optimisticId } }
        showAttachmentBlocked(attachmentBlockReason(peerAddress) ?: AttachmentBlockReason.NEEDS_KEY_EXCHANGE)
    }

    /**
     * Map a photo/file send failure to a clear, file-specific message. The on-chain send surfaces a raw
     * "wait for your ZEC to confirm" / "insufficient balance" string that is baffling when the user just
     * tried to send a photo. SR-A: in a Shielded chat every attachment's link goes on-chain at an exact price, so these
     * are the Shielded attachment's own texts, resources in the phone's language ([ChatSendCopy]), for a photo, a file
     * and a voice note alike ([attachmentSendErrorMessage]). (#bug-image-send)
     */
    private fun photoSendErrorMessage(
        e: Exception,
        kexPaidFirst: Boolean = false,
    ): String = attachmentSendErrorMessage(e, ChatSendCopy.PHOTO_SEND_FAILED, kexPaidFirst)

    /**
     * SR-A — [photoSendErrorMessage] for any attachment kind; [fallback] when nothing more specific is known.
     * T5b X-06: [kexPaidFirst] — this send paid its owed key exchange before the link was refused, so the price-changed
     * text says so instead of "Nothing was paid".
     */
    private fun attachmentSendErrorMessage(
        e: Exception,
        fallback: String,
        kexPaidFirst: Boolean = false,
    ): String {
        val raw = e.message ?: ""
        return when {
            // SR-A: the proposal was not the quoted transaction; the link was not paid and Retry asks the new price.
            generateSequence<Throwable>(e) { it.cause }.take(MAX_ERROR_CAUSE_DEPTH).any { it is SendQuoteChangedException } ->
                if (kexPaidFirst) ChatSendCopy.ATTACHMENT_PRICE_CHANGED_KEX_PAID else ChatSendCopy.ATTACHMENT_PRICE_CHANGED
            raw.contains("confirm on-chain", ignoreCase = true) -> ChatSendCopy.ATTACHMENT_STILL_CONFIRMING
            raw.contains("Insufficient balance", ignoreCase = true) -> ChatSendCopy.ATTACHMENT_NO_FUNDS_ROW
            // ZC-1417: the message shortfall with the SDK's figures is still a shortfall for an attachment row.
            ChatSendCopy.messageShortfallFigures(raw) != null -> ChatSendCopy.ATTACHMENT_NO_FUNDS_ROW
            raw.isBlank() -> fallback
            // Never surface a raw SDK/exception string to the user — classify or use a plain fallback.
            else -> e.toZchatUserMessage(fallback)
        }
    }

    /**
     * Handle a picked image URI from the image picker. Compresses, encrypts, uploads
     * via NIP-96/Blossom, creates a ZFILE message, and sends it as a memo.
     */
    fun handlePickedImage(
        peerAddress: String,
        uri: android.net.Uri,
        context: android.content.Context,
    ) = handlePickedImage(peerAddress, uri, context, viewOnce = false)

    /**
     * View-once variant of [handlePickedImage]. Sets the viewOnce bit in the ZFILE memo and
     * also wipes the sender's own local cache after upload so neither party can re-view it.
     */
    fun handlePickedImageViewOnce(
        peerAddress: String,
        uri: android.net.Uri,
        context: android.content.Context,
    ) = handlePickedImage(peerAddress, uri, context, viewOnce = true)

    private fun handlePickedImage(
        peerAddress: String,
        uri: android.net.Uri,
        context: android.content.Context,
        viewOnce: Boolean,
    ) = handlePickedImage(peerAddress, context, viewOnce) {
        // Memory-bounded prep: never load the full source bytes for large images.
        // For sources > 500KB, the picker URI is opened twice — first for bounds, then
        // for the sampled decode — so a 50MP HEIC source no longer OOMs on readBytes().
        co.electriccoin.zcash.ui.screen.chat.filesharing.ImageUploadPrep
            .prepare(context.contentResolver, uri)
    }

    /**
     * The photo flow after the picker. [prepare] returns the compressed JPEG, or null when the image cannot be read;
     * it runs on Dispatchers.IO: prepare() does ContentResolver queries + openInputStream + BitmapFactory stream
     * decodes, all blocking disk I/O that must not touch the main thread (StrictMode DiskReadViolation, #203).
     */
    private fun handlePickedImage(
        peerAddress: String,
        context: android.content.Context,
        viewOnce: Boolean,
        prepare: () -> ByteArray?,
    ) {
        // T1b-1 §2: nothing is uploaded or sent while a Keystone account is selected.
        if (chatClosedForSelectedAccount()) {
            refuseClosedChat("a photo")
            return
        }
        // SR-C2: no end-to-end key → the notice, before the upload slot and before the picture is read or compressed.
        if (refuseAttachmentIfBlocked(peerAddress)) return
        // Atomically claim the upload slot. Rejects a second tap that races with the first,
        // not just a strictly-later one (read-then-launch was not atomic).
        if (!uploadProgressTracker.tryStart()) {
            // F-R9P-2: say so instead of ignoring the pick (the photo stays in the gallery to send again).
            Log.w("ZCHAT_FILE", "Image pick refused: upload already in progress")
            _sendMessageState.value =
                co.electriccoin.zcash.ui.screen.chat.model.SendMessageState
                    .Error(noteCopy.get(R.string.chat_upload_busy))
            return
        }
        // Optimistic bubble id — the message renders BEFORE compression/encryption/upload
        // so the user sees instant feedback instead of 5–10s of nothing. We update it twice:
        // once to attach the local thumbnail (post-compress) and once on failure (FAILED state).
        // On success the bubble is removed right before sendMessage() inserts the final
        // pending entry; the renderer sees a seamless handoff because both reference the
        // same on-disk cache file (sha256 of the encrypted bytes).
        val optimisticId = "${AttachmentKind.PHOTO.idPrefix}${System.nanoTime()}"
        viewModelScope.launch {
            try {
                // 1) Insert a "preparing" placeholder so the chat reacts within one frame.
                pendingMessages.update {
                    it +
                        ChatMessage(
                            id = optimisticId,
                            txId = null,
                            text = noteCopy.get(R.string.chat_photo_preparing),
                            timestamp = Instant.now(),
                            isOutgoing = true,
                            peerAddress = peerAddress,
                            isPending = true,
                            status = MessageStatus.SENDING,
                        )
                }

                val compressed =
                    kotlinx.coroutines.withContext(kotlinx.coroutines.Dispatchers.IO) { prepare() }
                        ?: throw Exception("Cannot read or process image (too large, unsupported, or unreadable)")
                uploadProgressTracker.compressed()

                // Encrypt
                val fileKey =
                    co.electriccoin.zcash.ui.screen.chat.crypto.E2EEncryption
                        .generateFileKey()
                val encrypted =
                    co.electriccoin.zcash.ui.screen.chat.crypto.E2EEncryption
                        .encryptFile(compressed, fileKey)
                uploadProgressTracker.encrypted()

                // 2) Pre-cache the plaintext under the final ZFILE hash so the renderer can
                // show the image straight from disk while the upload runs. The renderer reads
                // from cacheDir/zchat_files/<hash> and is happy either with a downloaded blob
                // or — as here — our own plaintext pre-write.
                val sha256Hex =
                    co.electriccoin.zcash.ui.nostr.FileUploadManager
                        .sha256Hex(encrypted)
                val zfileHash = sha256Hex.take(32)
                val cacheDir = java.io.File(context.cacheDir, "zchat_files").apply { mkdirs() }
                val cacheFile = java.io.File(cacheDir, zfileHash)
                kotlinx.coroutines.withContext(kotlinx.coroutines.Dispatchers.IO) {
                    runCatching { cacheFile.writeBytes(compressed) }
                        .onFailure { Log.w("ZCHAT_FILE", "Optimistic cache write failed: ${it.message}") }
                }
                pendingMessages.update { list ->
                    list.map { m ->
                        if (m.id == optimisticId) {
                            m.copy(
                                text = if (viewOnce) "🔒 View once photo" else "📷 Photo",
                                // fileHash present → MessageBubble renders from cache and shows
                                // uploadProgress overlay via isOutgoingInFlight (ChatDetailView:778).
                                fileHash = zfileHash,
                                fileType = co.electriccoin.zcash.ui.screen.chat.model.ZFILEType.JPEG,
                                fileViewOnce = viewOnce,
                                // fileZfileContent stays null so the download-trigger
                                // LaunchedEffect (AndroidChat:506) skips this message.
                            )
                        } else {
                            m
                        }
                    }
                }

                // ZC-1474 (W-123): no shared key, an Open or Tunnel chat with a bound zatt1 contact — the free path.
                if (attachmentRoute(peerAddress) == AttachmentTransport.Route.NOSTR_ZATT) {
                    val type = co.electriccoin.zcash.ui.screen.chat.model.ZFILEType.JPEG
                    if (!sendZattAttachment(context, peerAddress, optimisticId, AttachmentKind.PHOTO, encrypted, fileKey, type, viewOnce)) {
                        return@launch
                    }
                    kotlinx.coroutines.delay(400)
                    return@launch
                }

                // Wrap the file key with the E2E shared secret. ABORT if there's none: wrapping with
                // an all-zero key is NOT encryption — the key is public, so anyone who sees the memo
                // can unwrap it and decrypt the file. The app is fail-closed (never silently downgrade
                // crypto), so refuse to send rather than ship an effectively-plaintext file. The outer
                // catch resets the upload progress and surfaces the failure.
                val sharedKey =
                    getE2ESharedKey(peerAddress)
                        ?: throw AttachmentKeyMissingException()
                // HIGH-003 (B1l) + xver §2.2: the Quantum Shield PSK is already mixed into the ratchet ROOT on
                // BOTH this build and live 2.12.4, so attachments inherit the post-quantum binding via the
                // file-key's shared secret. We must NOT additionally PSK-mix the file-key WRAP here: a 2.12.4
                // receiver unwraps classical-only with no PSK fallback → AEADBadTagException → silent one-way
                // attachment-download failure during the mixed-version rollout. Restore
                // `psk = getQuantumShieldPSKBytes(peerAddress)` once 2.12.4 has exited the fleet (~2.14.0). The
                // receive side (unwrapFileKey) keeps its PSK-then-classical fallback, so 2.13.0↔2.13.0 interops.
                val wrappedKey =
                    co.electriccoin.zcash.ui.screen.chat.crypto.E2EEncryption.wrapFileKey(
                        fileKey,
                        sharedKey
                    )
                val wrappedKeyB64 =
                    java.util.Base64
                        .getEncoder()
                        .encodeToString(wrappedKey)

                Log.d("ZCHAT_FILE", "Image: ${compressed.size}B compressed, ${encrypted.size}B encrypted, sha256=${sha256Hex.take(16)}...")

                // 3) Upload, then hand the optimistic bubble off to the send — but only AFTER it accepts, and take the
                // bubble back if the send is refused (now, or at the first-message cost prompt). Dropping it on a
                // refusal would vanish the photo while the indicator below claimed "sent" (R4-4 2). View-once: the
                // sender's local plaintext is wiped once the send is accepted (sendAttachmentBlob).
                val entry =
                    AttachmentRetryStore.Entry(
                        hash = zfileHash,
                        typeCode = co.electriccoin.zcash.ui.screen.chat.model.ZFILEType.JPEG.code,
                        wrappedKeyB64 = wrappedKeyB64,
                        viewOnce = viewOnce,
                        durationMs = null,
                    )
                if (!keepAndSendAttachment(context, peerAddress, optimisticId, AttachmentKind.PHOTO, encrypted, entry)) {
                    return@launch
                }
                Log.d("ZCHAT_FILE", "ZFILE message sent for ${peerAddress.redactAddress()} viewOnce=$viewOnce")
                // Brief visible "Sent" state before clearing the bar. If cancelled, CancellationException
                // propagates out of delay; the finally below still clears the tracker.
                kotlinx.coroutines.delay(400)
            } catch (e: kotlinx.coroutines.CancellationException) {
                // Scope was cancelled (e.g. navigation away). Don't mark as failed; just let the
                // finally clear state, and rethrow so cancellation semantics are preserved.
                // The optimistic bubble stays in pendingMessages until the next loadConversations
                // pass rebuilds it from sources — acceptable since cancellation is rare.
                throw e
            } catch (e: AttachmentKeyMissingException) {
                refuseAttachmentWithoutKey(peerAddress, optimisticId)
            } catch (e: Exception) {
                Log.e("ZCHAT_FILE", "Image send failed: ${e.message}", e)
                // Surface the failure on the optimistic bubble itself instead of as a toast-only
                // error — the bubble was the user's visible commitment, leaving it pending forever
                // would be misleading.
                val reason = attachmentFailureReason(AttachmentKind.PHOTO, e)
                markAttachmentFailed(optimisticId, AttachmentKind.PHOTO, reason)
                _sendMessageState.value =
                    co.electriccoin.zcash.ui.screen.chat.model.SendMessageState
                        .Error(reason)
            } finally {
                uploadProgressTracker.reset()
            }
        }
    }

    /**
     * Handle a picked arbitrary file URI (PDF, ZIP, TXT, image, etc.).
     * Reads bytes (capped at 25 MB to keep heap bounded), encrypts, uploads, and sends
     * a ZFILE message tagged with the resolved [ZFILEType]. Files outside the known
     * type set are rejected before any upload.
     */
    fun handlePickedFile(peerAddress: String, uri: android.net.Uri, context: android.content.Context) {
        val cr = context.contentResolver
        // A provider that refuses the query reads as an unknown type / unknown size: the checks below then refuse it.
        val mime = runCatching { cr.getType(uri) }.getOrNull()
        val size =
            runCatching {
                cr.query(uri, arrayOf(android.provider.OpenableColumns.SIZE), null, null, null)?.use { c ->
                    if (c.moveToFirst()) c.getLong(0) else -1L
                }
            }.getOrNull() ?: -1L
        handlePickedFile(peerAddress, context, mime, size) { cr.openInputStream(uri) }
    }

    /**
     * R9-4 — the file flow after the picker: the picked file's MIME type, its declared size (-1 = unknown) and a way to
     * open its bytes (read on Dispatchers.IO). A file refused before any upload (unsupported type, too large) shows its
     * error only. From the read on, the file has a bubble: a failed upload leaves it FAILED, and its Retry uploads the
     * same ciphertext again (retryAttachment); before this a failed file left no row at all.
     */
    private fun handlePickedFile(
        peerAddress: String,
        context: android.content.Context,
        mime: String?,
        declaredSize: Long,
        open: () -> java.io.InputStream?,
    ) {
        // T1b-1 §2: nothing is uploaded or sent while a Keystone account is selected.
        if (chatClosedForSelectedAccount()) {
            refuseClosedChat("a file")
            return
        }
        // SR-C2: no end-to-end key → the notice, before the upload slot and before the file is read.
        if (refuseAttachmentIfBlocked(peerAddress)) return
        if (!uploadProgressTracker.tryStart()) {
            // F-R9P-2: say so instead of ignoring the pick (the file stays where it was picked from).
            Log.w("ZCHAT_FILE", "File pick refused: upload already in progress")
            _sendMessageState.value =
                co.electriccoin.zcash.ui.screen.chat.model.SendMessageState
                    .Error(noteCopy.get(R.string.chat_upload_busy))
            return
        }
        val mimeType = mime ?: "application/octet-stream"
        val fileType =
            co.electriccoin.zcash.ui.screen.chat.model.ZFILEType
                .fromMime(mimeType)
        // Hard cap to keep heap bounded — same envelope as the image flow.
        val maxBytes = 25L * 1024L * 1024L
        val refusal =
            when {
                fileType == null -> "Unsupported file type: $mimeType (supported: JPEG/PNG/GIF/WebP/PDF/ZIP/TXT)"
                declaredSize in 1..maxBytes || declaredSize == -1L -> null
                else -> "File too large (${declaredSize / (1024 * 1024)} MB; max 25 MB)"
            }
        if (fileType == null || refusal != null) {
            Log.e("ZCHAT_FILE", "File send refused: $refusal")
            _sendMessageState.value =
                co.electriccoin.zcash.ui.screen.chat.model.SendMessageState.Error(
                    attachmentFailureReason(AttachmentKind.FILE, Exception(refusal)),
                )
            uploadProgressTracker.reset()
            return
        }
        val optimisticId = "${AttachmentKind.FILE.idPrefix}${System.nanoTime()}"
        viewModelScope.launch {
            try {
                val rawBytes =
                    kotlinx.coroutines.withContext(kotlinx.coroutines.Dispatchers.IO) {
                        open()?.use { input ->
                            java.io
                                .ByteArrayOutputStream()
                                .also { out ->
                                    val buf = ByteArray(8192)
                                    var total = 0L
                                    while (true) {
                                        val n = input.read(buf)
                                        if (n < 0) break
                                        total += n
                                        if (total > maxBytes) throw Exception("File too large (max 25 MB)")
                                        out.write(buf, 0, n)
                                    }
                                }.toByteArray()
                        }
                    } ?: throw Exception("Cannot read file")

                uploadProgressTracker.compressed()

                val fileKey =
                    co.electriccoin.zcash.ui.screen.chat.crypto.E2EEncryption
                        .generateFileKey()
                val encrypted =
                    co.electriccoin.zcash.ui.screen.chat.crypto.E2EEncryption
                        .encryptFile(rawBytes, fileKey)
                uploadProgressTracker.encrypted()
                val sha256 =
                    co.electriccoin.zcash.ui.nostr.FileUploadManager
                        .sha256Hex(encrypted)

                // R9-4: the file's bubble, like the photo's and the voice note's. It is a plain text bubble (no fileHash:
                // nothing is cached to render from) until the send hands it off to the ZFILE row.
                pendingMessages.update {
                    it +
                        ChatMessage(
                            id = optimisticId,
                            txId = null,
                            text =
                                co.electriccoin.zcash.ui.screen.chat.model
                                    .ZFILEMessage(
                                        hash = sha256.take(32),
                                        type = fileType,
                                        size = encrypted.size.toLong(),
                                        url = "",
                                        wrappedKey = "",
                                        blurhash = "",
                                    ).let(::fileRowText),
                            timestamp = Instant.now(),
                            isOutgoing = true,
                            peerAddress = peerAddress,
                            isPending = true,
                            status = MessageStatus.SENDING,
                        )
                }

                // ZC-1474 (W-123): no shared key, an Open or Tunnel chat with a bound zatt1 contact — the free path.
                if (attachmentRoute(peerAddress) == AttachmentTransport.Route.NOSTR_ZATT) {
                    if (!sendZattAttachment(context, peerAddress, optimisticId, AttachmentKind.FILE, encrypted, fileKey, fileType, false)) {
                        return@launch
                    }
                    kotlinx.coroutines.delay(400)
                    return@launch
                }

                // Fail closed: no E2E shared secret → refuse to send. An all-zero wrap key is public,
                // so the file would be decryptable by anyone reading the memo (effectively plaintext).
                val sharedKey =
                    getE2ESharedKey(peerAddress)
                        ?: throw AttachmentKeyMissingException()
                // HIGH-003 (B1l) + xver §2.2: the Quantum Shield PSK is already mixed into the ratchet ROOT on
                // BOTH this build and live 2.12.4, so attachments inherit the post-quantum binding via the
                // file-key's shared secret. We must NOT additionally PSK-mix the file-key WRAP here: a 2.12.4
                // receiver unwraps classical-only with no PSK fallback → AEADBadTagException → silent one-way
                // attachment-download failure during the mixed-version rollout. Restore
                // `psk = getQuantumShieldPSKBytes(peerAddress)` once 2.12.4 has exited the fleet (~2.14.0). The
                // receive side (unwrapFileKey) keeps its PSK-then-classical fallback, so 2.13.0↔2.13.0 interops.
                val wrappedKey =
                    co.electriccoin.zcash.ui.screen.chat.crypto.E2EEncryption.wrapFileKey(
                        fileKey,
                        sharedKey
                    )
                val wrappedKeyB64 =
                    java.util.Base64
                        .getEncoder()
                        .encodeToString(wrappedKey)

                Log.d("ZCHAT_FILE", "File: ${rawBytes.size}B raw, ${encrypted.size}B encrypted, mime=$mimeType, type=${fileType.code}")

                val entry =
                    AttachmentRetryStore.Entry(
                        hash = sha256.take(32),
                        typeCode = fileType.code,
                        wrappedKeyB64 = wrappedKeyB64,
                        viewOnce = false,
                        durationMs = null,
                    )
                if (!keepAndSendAttachment(context, peerAddress, optimisticId, AttachmentKind.FILE, encrypted, entry)) {
                    // Rejected before queuing (peer key changed / funds need Orchard shielding), or the cost prompt
                    // was declined: sendMessage surfaces its own state and the bubble is FAILED (retryable).
                    Log.w("ZCHAT_FILE", "File send rejected before queue — not marking sent")
                    return@launch
                }
                kotlinx.coroutines.delay(400)
            } catch (e: kotlinx.coroutines.CancellationException) {
                throw e
            } catch (e: AttachmentKeyMissingException) {
                refuseAttachmentWithoutKey(peerAddress, optimisticId)
            } catch (e: Exception) {
                Log.e("ZCHAT_FILE", "File send failed: ${e.message}", e)
                val reason = attachmentFailureReason(AttachmentKind.FILE, e)
                markAttachmentFailed(optimisticId, AttachmentKind.FILE, reason)
                _sendMessageState.value =
                    co.electriccoin.zcash.ui.screen.chat.model.SendMessageState
                        .Error(reason)
            } finally {
                uploadProgressTracker.reset()
            }
        }
    }

    /**
     * Upload + send a recorded voice message file (M4A). Shares the existing ZFILE
     * pipeline with handlePickedFile but skips the URI/MIME detour. The caller
     * (chat input mic button) supplies the already-finalized file path from
     * [AudioRecorder.stop]. The recording is deleted from disk on success or failure.
     */
    fun handleRecordedAudio(
        peerAddress: String,
        file: java.io.File,
        durationMs: Long,
        context: android.content.Context,
    ) = handleRecordedAudio(peerAddress, file, durationMs, context, viewOnce = false)

    fun handleRecordedAudioViewOnce(
        peerAddress: String,
        file: java.io.File,
        durationMs: Long,
        context: android.content.Context,
    ) = handleRecordedAudio(peerAddress, file, durationMs, context, viewOnce = true)

    private fun handleRecordedAudio(
        peerAddress: String,
        file: java.io.File,
        durationMs: Long,
        context: android.content.Context,
        viewOnce: Boolean,
    ) {
        // SR-C2: no end-to-end key → the notice and no bubble. The take can never be sent from this chat as it is (its
        // key would be wrapped with the missing key), so its cache file goes as after any failed voice note.
        if (refuseAttachmentIfBlocked(peerAddress)) {
            runCatching { file.delete() }
            return
        }
        val optimisticId = "${AttachmentKind.VOICE.idPrefix}${System.nanoTime()}"
        // Optimistic bubble — appears at once so the user sees the recording commit, also while another upload
        // holds the slot. Duration label lets them sanity-check the take.
        val durationSec = (durationMs / 1000).coerceAtLeast(1).toInt()
        pendingMessages.update {
            it +
                ChatMessage(
                    id = optimisticId,
                    txId = null,
                    text = noteCopy.get(R.string.chat_voice_uploading, durationSec),
                    timestamp = Instant.now(),
                    isOutgoing = true,
                    peerAddress = peerAddress,
                    isPending = true,
                    status = MessageStatus.SENDING,
                )
        }
        viewModelScope.launch {
            // Only the holder of the upload slot may free it: a note cancelled while it waits must not reset
            // the slot of the upload it was waiting for.
            var holdsSlot = false
            try {
                // F-R9P-2: a voice note recorded while another upload runs is never dropped (its recording exists
                // nowhere else). It waits for the slot BEFORE it is read or encrypted, so its bubble carries no
                // fileHash yet and cannot show the other upload's progress.
                while (!uploadProgressTracker.tryStart()) {
                    uploadProgressTracker.progress.first { it == null }
                }
                holdsSlot = true
                val rawBytes = file.readBytes()
                uploadProgressTracker.compressed()

                val fileKey =
                    co.electriccoin.zcash.ui.screen.chat.crypto.E2EEncryption
                        .generateFileKey()
                val encrypted =
                    co.electriccoin.zcash.ui.screen.chat.crypto.E2EEncryption
                        .encryptFile(rawBytes, fileKey)
                uploadProgressTracker.encrypted()

                // ZC-1474 (W-123): no shared key, an Open or Tunnel chat with a bound zatt1 contact — the free path: the file
                // key goes inside the authenticated relay message, so nothing is wrapped.
                val freeRoute = attachmentRoute(peerAddress) == AttachmentTransport.Route.NOSTR_ZATT
                val wrappedKeyB64 =
                    if (freeRoute) {
                        ""
                    } else {
                        // Fail closed: no E2E shared secret → refuse to send. An all-zero wrap key is public,
                        // so the file would be decryptable by anyone reading the memo (effectively plaintext).
                        val sharedKey =
                            getE2ESharedKey(peerAddress)
                                ?: throw AttachmentKeyMissingException()
                        // HIGH-003 (B1l) + xver §2.2: the Quantum Shield PSK is already mixed into the ratchet ROOT on
                        // BOTH this build and live 2.12.4, so attachments inherit the post-quantum binding via the
                        // file-key's shared secret. We must NOT additionally PSK-mix the file-key WRAP here: a 2.12.4
                        // receiver unwraps classical-only with no PSK fallback → AEADBadTagException → silent one-way
                        // attachment-download failure during the mixed-version rollout. Restore
                        // `psk = getQuantumShieldPSKBytes(peerAddress)` once 2.12.4 has exited the fleet (~2.14.0). The
                        // receive side (unwrapFileKey) keeps its PSK-then-classical fallback, so 2.13.0↔2.13.0 interops.
                        val wrappedKey =
                            co.electriccoin.zcash.ui.screen.chat.crypto.E2EEncryption.wrapFileKey(
                                fileKey,
                                sharedKey
                            )
                        java.util.Base64
                            .getEncoder()
                            .encodeToString(wrappedKey)
                    }

                val sha256Hex =
                    co.electriccoin.zcash.ui.nostr.FileUploadManager
                        .sha256Hex(encrypted)
                val zfileHash = sha256Hex.take(32)

                // Pre-cache plaintext so our own outgoing bubble can play back without
                // a download round-trip — same trick as the image optimistic path.
                val cacheDir = java.io.File(context.cacheDir, "zchat_files").apply { mkdirs() }
                runCatching { java.io.File(cacheDir, zfileHash).writeBytes(rawBytes) }
                    .onFailure { Log.w("ZCHAT_FILE", "Audio cache write failed: ${it.message}") }
                pendingMessages.update { list ->
                    list.map { m ->
                        if (m.id == optimisticId) {
                            m.copy(
                                fileHash = zfileHash,
                                fileType = co.electriccoin.zcash.ui.screen.chat.model.ZFILEType.M4A,
                                fileDurationMs = durationMs,
                                fileViewOnce = viewOnce,
                            )
                        } else {
                            m
                        }
                    }
                }

                if (freeRoute) {
                    val type = co.electriccoin.zcash.ui.screen.chat.model.ZFILEType.M4A
                    if (!sendZattAttachment(context, peerAddress, optimisticId, AttachmentKind.VOICE, encrypted, fileKey, type, viewOnce)) {
                        return@launch
                    }
                    kotlinx.coroutines.delay(400)
                    return@launch
                }

                // Only hand the optimistic bubble off to the send's pending entry on ACCEPT, and take it back
                // if the send is refused (now, or at the first-message cost prompt) — otherwise the voice
                // message vanishes while the indicator below claims "sent" (R4-4 2). View-once: the sender's
                // plaintext is wiped once the send is accepted (sendAttachmentBlob).
                val entry =
                    AttachmentRetryStore.Entry(
                        hash = zfileHash,
                        typeCode = co.electriccoin.zcash.ui.screen.chat.model.ZFILEType.M4A.code,
                        wrappedKeyB64 = wrappedKeyB64,
                        viewOnce = viewOnce,
                        durationMs = durationMs,
                    )
                if (!keepAndSendAttachment(context, peerAddress, optimisticId, AttachmentKind.VOICE, encrypted, entry)) {
                    return@launch
                }
                kotlinx.coroutines.delay(400)
            } catch (e: kotlinx.coroutines.CancellationException) {
                throw e
            } catch (e: AttachmentKeyMissingException) {
                refuseAttachmentWithoutKey(peerAddress, optimisticId)
            } catch (e: Exception) {
                Log.e("ZCHAT_FILE", "Audio send failed: ${e.message}", e)
                val reason = attachmentFailureReason(AttachmentKind.VOICE, e)
                markAttachmentFailed(optimisticId, AttachmentKind.VOICE, reason)
                _sendMessageState.value =
                    co.electriccoin.zcash.ui.screen.chat.model.SendMessageState
                        .Error(reason)
            } finally {
                runCatching { file.delete() }
                if (holdsSlot) uploadProgressTracker.reset()
            }
        }
    }

    /** R9-4 — the retry copies of failed attachments; made from the first picker's context (its cache directory). */
    @Volatile private var attachmentRetryStore: AttachmentRetryStore? = null

    private fun attachmentRetryStoreFor(context: android.content.Context): AttachmentRetryStore =
        attachmentRetryStore
            ?: AttachmentRetryStore(
                java.io.File(
                    context.cacheDir,
                    AttachmentRetryStore.DIR_NAME,
                ),
            ).also { attachmentRetryStore = it }

    /** R10A-2 (F-R9P-4) — an outgoing file row, «📎 Document (7.0 MB)», in the phone's language. */
    private fun fileRowText(file: co.electriccoin.zcash.ui.screen.chat.model.ZFILEMessage): String =
        "📎 " + noteCopy.get(file.typeLabelRes, file.sizeText)

    /** R9-4 — the FAILED bubble's text in the phone's language (it was English on every phone). */
    private fun attachmentFailedLabel(kind: AttachmentKind): String = noteCopy.get(kind.failedLabel)

    /** R9-4 — why an attachment failed, as its bubble and the send notice say it (ChatSendCopy constants are localized). */
    private fun attachmentFailureReason(
        kind: AttachmentKind,
        e: Exception,
    ): String =
        when {
            // SR-C2: never "Please try again" for a chat with no end-to-end key.
            e is AttachmentKeyMissingException -> ChatSendCopy.ATTACHMENT_NEEDS_KEY_EXCHANGE
            else -> attachmentFailureReasonOf(kind, e)
        }

    private fun attachmentFailureReasonOf(
        kind: AttachmentKind,
        e: Exception,
    ): String =
        when (kind) {
            AttachmentKind.PHOTO -> photoSendErrorMessage(e)
            AttachmentKind.FILE -> attachmentSendErrorMessage(e, ChatSendCopy.FILE_SEND_FAILED)
            AttachmentKind.VOICE -> attachmentSendErrorMessage(e, ChatSendCopy.VOICE_MESSAGE_FAILED)
        }

    private fun markAttachmentFailed(
        optimisticId: String,
        kind: AttachmentKind,
        reason: String?,
    ) {
        pendingMessages.update { list ->
            list.map { m ->
                if (m.id == optimisticId) {
                    m.copy(text = attachmentFailedLabel(kind), isPending = false, status = MessageStatus.FAILED, failureReason = reason)
                } else {
                    m
                }
            }
        }
    }

    /**
     * R9-4 — keep the encrypted blob for a Retry (ciphertext and the WRAPPED file key only, in the app's cache; a
     * copy older than 24 h is swept first), then upload and send it. A copy that cannot be written only costs the
     * Retry; the send goes on. Returns [sendAttachmentBlob]'s answer.
     */
    private suspend fun keepAndSendAttachment(
        context: android.content.Context,
        peerAddress: String,
        optimisticId: String,
        kind: AttachmentKind,
        encrypted: ByteArray,
        entry: AttachmentRetryStore.Entry,
    ): Boolean {
        val store = attachmentRetryStoreFor(context)
        withContext(kotlinx.coroutines.Dispatchers.IO) {
            runCatching {
                store.sweep()
                store.put(optimisticId, encrypted, entry)
            }.onFailure { Log.w("ZCHAT_FILE", "Retry copy not kept: ${it.javaClass.simpleName}") }
        }
        return sendAttachmentBlob(peerAddress, optimisticId, kind, encrypted, entry, store, retry = false)
    }

    /**
     * R9-4 — the one upload + send of a photo, a file, a voice note and their Retry: upload [encrypted] as an opaque
     * blob, build the ZFILE and hand it to the send with the optimistic bubble [optimisticId]. Throws when the upload
     * fails (the caller marks the bubble FAILED; the retry copy is kept). False when the send was refused or the
     * cost prompt declined (the bubble is FAILED, the retry copy kept). True once the send accepted it; the retry copy
     * is then removed as soon as the ZFILE is handed to the send, and a view-once attachment's local plaintext is
     * wiped.
     *
     * SR-A (owner decision W-16, "Link on-chain always"): in a Shielded chat the link goes on-chain inside the ratchet,
     * never over the relays, and nothing is uploaded before the user answered one exact price question
     * ([shieldedAttachmentQuote]; [retry] asks it as the Retry's question). The upload then takes only a url that keeps
     * the quoted memo count, and the send carries the quote, so it pays exactly that or nothing.
     */
    private suspend fun sendAttachmentBlob(
        peerAddress: String,
        optimisticId: String,
        kind: AttachmentKind,
        encrypted: ByteArray,
        entry: AttachmentRetryStore.Entry,
        store: AttachmentRetryStore?,
        retry: Boolean,
    ): Boolean {
        // SR-C1 (KI-37): a contact whose newest relay message came from ZChat 2.12 or older is warned about first, before
        // the upload and before any send or price question; the first attempt and every Retry ask.
        if (!legacyContactAttachmentAllowed(peerAddress, optimisticId, kind)) return false
        val type =
            co.electriccoin.zcash.ui.screen.chat.model.ZFILEType
                .fromCode(entry.typeCode)
                ?: error("Unknown attachment type")

        // The line this attachment sends, with the url the upload returns (blurhash empty, as it is sent).
        fun lineWith(url: String): String =
            co.electriccoin.zcash.ui.screen.chat.model
                .ZFILEMessage(
                    hash = entry.hash,
                    type = type,
                    size = encrypted.size.toLong(),
                    url = url,
                    wrappedKey = entry.wrappedKeyB64,
                    blurhash = "",
                    viewOnce = entry.viewOnce,
                ).serialize()
        // SR-A: in a Shielded chat, the exact price first, before anything is uploaded; null when declined or refused
        // (the bubble is FAILED with its retry copy, nothing uploaded or paid).
        val sendQuote: ChatSendQuote? =
            if (zchatPreferences.getConversationMode(peerAddress) == ConversationMode.VAULT) {
                shieldedAttachmentQuote(peerAddress, optimisticId, kind, lineWith(WORST_CASE_ATTACHMENT_URL), entry, retry, store)
                    ?: return false
            } else {
                null
            }
        // SR-A (R-A1): a url whose line would need another memo count than the price paid for is skipped like an
        // off-allow-list url, and the next host is tried. Tunnel and Open take any allowed url.
        val acceptUrl: (String) -> Boolean =
            if (sendQuote == null) {
                { true }
            } else {
                { url -> onChainMemoCount(peerAddress, lineWith(url)) == sendQuote.chunkCount }
            }
        val fileUrl = uploadAttachmentBlob(encrypted, acceptUrl)
        // T5b X-04: the mode was read before the upload. A chat switched to Shielded while it ran has no exact price
        // for this link, and a Shielded link is never paid without one: nothing is sent or paid, the bubble is FAILED
        // with its retry copy, and its Retry asks the exact question (SHIELDED_ATTACHMENT_RETRY) before it sends.
        if (sendQuote == null && zchatPreferences.getConversationMode(peerAddress) == ConversationMode.VAULT) {
            Log.w("ZCHAT_FILE", "T5b X-04: the chat became Shielded during the upload — link not sent, nothing paid")
            markAttachmentFailed(optimisticId, kind, ChatSendCopy.ATTACHMENT_SWITCHED_TO_SHIELDED)
            _sendMessageState.value = SendMessageState.Error(ChatSendCopy.ATTACHMENT_SWITCHED_TO_SHIELDED)
            return false
        }
        val accepted =
            sendFileWithOptimisticBubble(
                peerAddress,
                lineWith(fileUrl),
                optimisticId,
                attachmentFailedLabel(kind),
                onHandedOff = { store?.let { s -> runCatching { s.remove(optimisticId) } } },
                sendQuote = sendQuote,
            )
        if (!accepted) return false
        uploadProgressTracker.sent()
        // View-once: wipe the sender's local cache so neither side has the plaintext sitting on disk. The bubble will
        // rebuild via convertToConversations as the tx confirms, picking up fileViewOnce + (after we mark it) fileViewed.
        if (entry.viewOnce) {
            // B2b — the sender's plaintext gets the SAME secure overwrite as the receiver's: a plain delete() left the
            // decrypted bytes recoverable on disk. On IO — it's disk I/O.
            store?.dir?.parentFile?.let { cacheRoot ->
                withContext(kotlinx.coroutines.Dispatchers.IO) { secureWipeFile(java.io.File(cacheRoot, "zchat_files/${entry.hash}")) }
            }
            zchatPreferences.markFileViewed(entry.hash)
        }
        return true
    }

    /**
     * R9-4 — upload [encrypted] (AES ciphertext) as an opaque blob under our relay identity to the first host whose url
     * [acceptUrl] takes; returns that url, or throws when the upload failed. Shared by [sendAttachmentBlob] and
     * [sendZattAttachment].
     */
    private suspend fun uploadAttachmentBlob(
        encrypted: ByteArray,
        acceptUrl: (String) -> Boolean,
    ): String {
        // Derive NOSTR identity from BIP39 seed for NIP-96/Blossom auth
        val wallet = persistableWalletProvider.requirePersistableWallet()
        val bip39Seed = Mnemonics.MnemonicCode(wallet.seedPhrase.joinToString()).toSeed()
        val nostrIdentity =
            co.electriccoin.zcash.ui.nostr.NOSTRIdentity
                .fromSeed(bip39Seed, zchatPreferences.getNostrRotationIndex())
        val uploadManager =
            co.electriccoin.zcash.ui.nostr
                .FileUploadManager(nostrIdentity, fileHttpClientProvider, acceptUrl)
        uploadProgressTracker.uploading(0.1f)
        // R8-fixup F3: the body is AES ciphertext, so it is declared as an opaque blob. The servers now read the body and
        // refuse a blob declared image/jpeg whose bytes are not a JPEG (FileUploadManager.blossomServers). The receiver
        // routes by ZFILEType, not the server's MIME type.
        val uploadResult =
            uploadManager.upload(encrypted, FileUploadManager.ENCRYPTED_BLOB_CONTENT_TYPE) { fraction ->
                uploadProgressTracker.uploading(fraction)
            }
        uploadProgressTracker.uploaded()
        return when (uploadResult) {
            is co.electriccoin.zcash.ui.nostr.UploadOutcome.Success -> {
                Log.d("ZCHAT_FILE", "Upload success: ${uploadResult.url.redactUrl()}")
                uploadResult.url
            }
            is co.electriccoin.zcash.ui.nostr.UploadOutcome.Failure -> {
                Log.e("ZCHAT_FILE", "Upload failed: ${uploadResult.error} (${uploadResult.serverUrl})")
                throw Exception("Upload failed: ${uploadResult.error}")
            }
        }
    }

    /**
     * ZC-1474 (W-123) — the free path of a photo, file or voice note ([AttachmentTransport.Route.NOSTR_ZATT]): upload
     * [encrypted] as today, ask the route again ([zattRecipientKey]: the chat may have become Shielded, the relay key been
     * unbound or changed, or zatt1 been lost while it ran), then publish one ZATT carrying [fileKey] to the contact's bound
     * relay key ([publishNostrAndRenderLocal]; never INIT-wrapped, never on chain). No proposal, nothing paid. No retry
     * copy is kept: a failed upload throws (the caller marks the bubble FAILED; its Retry asks to pick the file again).
     * False: the route closed during the upload; the bubble is FAILED with the reason and nothing was sent.
     */
    private suspend fun sendZattAttachment(
        context: android.content.Context,
        peerAddress: String,
        optimisticId: String,
        kind: AttachmentKind,
        encrypted: ByteArray,
        fileKey: ByteArray,
        type: co.electriccoin.zcash.ui.screen.chat.model.ZFILEType,
        viewOnce: Boolean,
    ): Boolean {
        val hash = FileUploadManager.sha256Hex(encrypted).take(32)

        // ZC-1502: the line this attachment sends with [url], or null when the contact's ZATTMessage.parse would reject
        // it (a size over MAX_SIZE_BYTES, a url off the media allow-list, a line too long): such a line is never sent.
        fun lineWith(url: String): String? =
            runCatching { ZATTMessage.build(hash, type, encrypted.size.toLong(), url, fileKey, blurhash = "", viewOnce = viewOnce) }
                .getOrNull()
                ?.takeIf { ZATTMessage.parse(it) != null }

        // ZC-1502: a file whose line no url could make readable (e.g. at the pick cap, whose ciphertext is 28 bytes over
        // the cap) is refused before the upload: FAILED bubble, nothing uploaded, sent or paid.
        if (lineWith(WORST_CASE_ATTACHMENT_URL) == null) {
            val reason = attachmentFailureReasonOf(kind, Exception())
            Log.w("ZCHAT_FILE", "ZC-1502: this free attachment could not be read by the contact — not uploaded, nothing sent or paid")
            markAttachmentFailed(optimisticId, kind, reason)
            _sendMessageState.value = SendMessageState.Error(reason)
            return false
        }
        // ZC-1502: the upload takes only a url whose line parses (the media allow-list among others).
        val url = uploadAttachmentBlob(encrypted) { url -> lineWith(url) != null }
        val peerPub = zattRecipientKey(peerAddress)
        if (peerPub == null) {
            val reason = zattRefusalReason(peerAddress)
            Log.w("ZCHAT_FILE", "ZC-1474: the free route closed during the upload — link not sent, nothing paid")
            markAttachmentFailed(optimisticId, kind, reason)
            _sendMessageState.value = SendMessageState.Error(reason)
            return false
        }
        val line =
            lineWith(url) ?: run {
                val reason = attachmentFailureReasonOf(kind, Exception())
                Log.w("ZCHAT_FILE", "ZC-1502: the uploaded link would not be readable — not sent, nothing paid")
                markAttachmentFailed(optimisticId, kind, reason)
                _sendMessageState.value = SendMessageState.Error(reason)
                return false
            }
        pendingMessages.update { list -> list.filterNot { it.id == optimisticId } }
        publishNostrAndRenderLocal(peerAddress, peerPub, line)
        uploadProgressTracker.sent()
        // View-once: the sender's plaintext gets the same secure wipe as on the paid path (sendAttachmentBlob).
        if (viewOnce) {
            withContext(kotlinx.coroutines.Dispatchers.IO) { secureWipeFile(java.io.File(context.cacheDir, "zchat_files/$hash")) }
            zchatPreferences.markFileViewed(hash)
        }
        Log.d("ZCHAT_FILE", "ZC-1474: free attachment sent over the relays to ${peerAddress.redactAddress()}")
        return true
    }

    /** SR-A — what pricing a Shielded attachment's link answered. */
    private sealed interface ShieldedLinkPrice {
        /** Ask [confirmation]; on Pay the send carries [quote] and pays exactly it, or nothing. */
        data class Quoted(
            val quote: ChatSendQuote,
            val confirmation: PaidActionConfirmation,
        ) : ShieldedLinkPrice

        /** Refused before anything is uploaded or paid: show [state]; the row keeps [rowReason]. */
        data class Refused(
            val state: SendMessageState,
            val rowReason: String?,
        ) : ShieldedLinkPrice
    }

    /**
     * SR-A (C-SRA-4, R-A3, R-A5) — the exact price of sending [line] (an attachment's link) to [peerAddress] on-chain, or
     * why not. First sendMessage's own pre-checks (the Keystone closure, a key change, a stranded Orchard balance,
     * Sapling-only funds, [shieldedFundsRefusal]); then the memo count ([onChainMemoCount], the send's own rule) and the
     * SDK's price of that one transaction ([CreateChunkedMessageProposalUseCase.priceMessage]). A key exchange the
     * selected account still owes goes first in the same send, so it is priced too and counted as a second transaction in
     * one exact total, only when M2's plan check says both can be paid (owner W-18 Q20, "quote both"). A probe that
     * throws, needs Orchard inputs or more than one transaction is S-A8; a shortfall is S-A6 when waiting covers it
     * (our change or a running send), else S-A5. Nothing is stored, uploaded or paid here.
     */
    @Suppress("TooGenericExceptionCaught", "ReturnCount")
    private suspend fun priceShieldedLink(
        peerAddress: String,
        line: String,
        action: PaidAction,
    ): ShieldedLinkPrice {
        if (chatClosedForSelectedAccount() || keystoneAccountSelected()) {
            Log.w("ZCHAT_SEND", "K0/T1b-1: a Shielded attachment refused — a Keystone account is selected; nothing uploaded or paid")
            return ShieldedLinkPrice.Refused(SendMessageState.Error(ChatSendCopy.KEYSTONE_CHATS_CLOSED), ChatSendCopy.KEYSTONE_CHATS_CLOSED)
        }
        if (zchatPreferences.isE2EKeyChanged(peerAddress)) {
            return ShieldedLinkPrice.Refused(SendMessageState.Error(ChatSendCopy.KEY_CHANGED_VERIFY), ChatSendCopy.KEY_CHANGED_VERIFY)
        }
        shieldedFundsRefusal()?.let { return ShieldedLinkPrice.Refused(it, null) }
        val unavailable =
            ShieldedLinkPrice.Refused(
                SendMessageState.Error(ChatSendCopy.ATTACHMENT_PRICE_UNAVAILABLE),
                ChatSendCopy.ATTACHMENT_PRICE_UNAVAILABLE,
            )
        val amount = Zatoshi(DEFAULT_MESSAGE_AMOUNT)
        val kexAmount = CreateChunkedMessageProposalUseCase.DEFAULT_AMOUNT_PER_OUTPUT
        val owesKex = messageOwesKexFirst(peerAddress)
        // FC-ID (5.3a item 4): a link that pays our KEX first is counted under the own-made id it goes out under.
        if (owesKex) planOwnConversationId(peerAddress)
        val memos = onChainMemoCount(peerAddress, line)
        if (owesKex) {
            val plan = checkFirstMessagePlan(peerAddress, memos, amount.value)
            if (plan !is FirstMessagePlan.Fundable) {
                val refusal = firstMessagePlanRefusal(plan, row = true)
                return ShieldedLinkPrice.Refused(SendMessageState.Error(refusal), refusal)
            }
        }
        val (link, kex) =
            try {
                createChunkedMessageProposal.priceMessage(peerAddress, memos, amount) to
                    if (owesKex) createChunkedMessageProposal.priceMessage(peerAddress, 1, kexAmount) else null
            } catch (e: kotlinx.coroutines.CancellationException) {
                throw e
            } catch (e: Exception) {
                Log.w("ZCHAT_SEND", "SR-A: the Shielded attachment could not be priced (${e.javaClass.simpleName})")
                // ZC-782: the update refusal shows the update sentence, not "tap Retry in a moment".
                if (e is co.electriccoin.zcash.ui.common.model.NetworkUpgradeRequiredException) {
                    val update = e.toZchatUserMessage(ChatSendCopy.ATTACHMENT_PRICE_UNAVAILABLE)
                    return ShieldedLinkPrice.Refused(SendMessageState.Error(update), update)
                }
                return unavailable
            }
        val probes = listOfNotNull(link, kex)
        if (probes.any { it is FeeProbe.Built && (it.usesOrchardInputs || it.transactionCount != 1) }) {
            Log.w("ZCHAT_SEND", "SR-A: the Shielded attachment's price needs Orchard inputs or another transaction — refused")
            return unavailable
        }
        if (probes.any { it is FeeProbe.Short }) {
            val floor =
                Zatoshi(
                    onChainSendMinimumCost(memos, amount).value + if (owesKex) onChainSendMinimumCost().value else 0L,
                )
            return shortShieldedLinkRefusal(peerAddress, floor)
        }
        val linkFee = (link as FeeProbe.Built).fee
        val kexQuote =
            (kex as? FeeProbe.Built)?.let { built ->
                ChatSendQuote(
                    recipient = peerAddress,
                    chunkCount = 1,
                    amountPerOutput = kexAmount,
                    total = Zatoshi(CreateChunkedMessageProposalUseCase.totalCost(1, kexAmount).value + built.fee.value),
                    fee = built.fee,
                )
            }
        val quote =
            ChatSendQuote(
                recipient = peerAddress,
                chunkCount = memos,
                amountPerOutput = amount,
                total = Zatoshi(CreateChunkedMessageProposalUseCase.totalCost(memos, amount).value + linkFee.value),
                fee = linkFee,
                transactions = if (kexQuote != null) 2 else 1,
                kexLeg = kexQuote,
            )
        val confirmation =
            PaidActionConfirmation(
                action = action,
                onChainMessages = quote.transactions,
                totalCost = Zatoshi(quote.total.value + (kexQuote?.total?.value ?: 0L)),
                includesRelayIdentity = false,
                includesChatSetup = false,
                exact = true,
                networkFee = Zatoshi(linkFee.value + (kexQuote?.fee?.value ?: 0L)),
                memos = memos,
            )
        return ShieldedLinkPrice.Quoted(quote, confirmation)
    }

    /**
     * SR-A (R-A5) — the wallet cannot pay [floor] right now. "Still confirming" (S-A6) when waiting covers it: Ironwood
     * still confirming would pay it ([ShortfallReason.classify]), or another send is running and the wallet's Ironwood in
     * all covers it; otherwise the empty-wallet notice (S-A5) with what the wallet can spend.
     */
    private suspend fun shortShieldedLinkRefusal(
        peerAddress: String,
        floor: Zatoshi,
    ): ShieldedLinkPrice.Refused {
        val account = selectedAccountOrNull()
        val ironwood = account?.unified?.ironwood
        val confirming =
            account != null &&
                ironwood != null &&
                (
                    ShortfallReason.classify(account, floor) is ShortfallReason.StillConfirming ||
                        (
                            _sendMessageState.value is SendMessageState.Sending &&
                                ironwood.available + ironwood.changePending + ironwood.valuePending >= floor
                        )
                )
        Log.w("ZCHAT_SEND", "SR-A: the Shielded attachment is short (confirming=$confirming) — nothing uploaded or paid")
        return if (confirming) {
            ShieldedLinkPrice.Refused(
                SendMessageState.Error(ChatSendCopy.ATTACHMENT_STILL_CONFIRMING),
                ChatSendCopy.ATTACHMENT_STILL_CONFIRMING,
            )
        } else {
            ShieldedLinkPrice.Refused(
                SendMessageState.ShieldedAttachmentNeedsFunds(peerAddress, floor, ironwood?.available ?: Zatoshi(0)),
                ChatSendCopy.ATTACHMENT_NO_FUNDS_ROW,
            )
        }
    }

    /**
     * SR-A (C-SRA-4) — a Shielded attachment's exact price question, asked after SR-C2's gate and SR-C1's warning and
     * before the upload ([worstLine] is its line with the longest url the hosts return). Null: refused or declined, and
     * the bubble [optimisticId] is FAILED with its retry copy (nothing uploaded, nothing paid). On Pay (R-A4) the
     * Keystone closure, a key change and today's shared key are checked again, the cost notice counts as accepted (the
     * question was the consent), and the quote the send must match is returned.
     */
    @Suppress("LongParameterList")
    private suspend fun shieldedAttachmentQuote(
        peerAddress: String,
        optimisticId: String,
        kind: AttachmentKind,
        worstLine: String,
        entry: AttachmentRetryStore.Entry,
        retry: Boolean,
        store: AttachmentRetryStore?,
    ): ChatSendQuote? {
        val action = if (retry) PaidAction.SHIELDED_ATTACHMENT_RETRY else PaidAction.SHIELDED_ATTACHMENT
        val price = priceShieldedLink(peerAddress, worstLine, action)
        if (price is ShieldedLinkPrice.Refused) {
            Log.w("ZCHAT_FILE", "SR-A: Shielded attachment refused before the upload — nothing uploaded or paid")
            markAttachmentFailed(optimisticId, kind, price.rowReason)
            _sendMessageState.value = price.state
            return null
        }
        price as ShieldedLinkPrice.Quoted
        Log.d("ZCHAT_FILE", "SR-A: exact price asked before the upload (${price.quote.transactions} tx, ${price.quote.chunkCount} memos)")
        val paid =
            try {
                awaitPaidAnswer(price.confirmation)
            } catch (e: kotlinx.coroutines.CancellationException) {
                // Leaving the chat with the question open: nothing uploaded; the row stays FAILED with its retry copy.
                markAttachmentFailed(optimisticId, kind, null)
                throw e
            }
        if (!paid) {
            Log.d("ZCHAT_FILE", "SR-A: the Shielded attachment's price was declined — nothing uploaded or paid")
            markAttachmentFailed(optimisticId, kind, null)
            return null
        }
        shieldedPayRefusal(peerAddress, entry.wrappedKeyB64)?.let { reason ->
            if (reason == ChatSendCopy.ATTACHMENT_RETRY_COPY_GONE && store != null) {
                withContext(Dispatchers.IO) { runCatching { store.remove(optimisticId) } }
            }
            markAttachmentFailed(optimisticId, kind, reason)
            return null
        }
        zchatPreferences.setAcknowledgedMessageCost()
        return price.quote
    }

    /**
     * SR-A (R-A4) — after Pay, before anything is uploaded or sent: a Keystone account selected meanwhile, a key change,
     * or a new shared key that no longer opens [wrappedKeyB64] (the contact could not open the file) refuses; the reason
     * is shown and returned. Null: go on.
     */
    private suspend fun shieldedPayRefusal(
        peerAddress: String,
        wrappedKeyB64: String,
    ): String? {
        if (chatClosedForSelectedAccount() || keystoneAccountSelected()) {
            refuseClosedChat("a paid Shielded attachment")
            return ChatSendCopy.KEYSTONE_CHATS_CLOSED
        }
        if (blockedByKeyChange(peerAddress)) return ChatSendCopy.KEY_CHANGED_VERIFY
        if (!sharedKeyOpens(peerAddress, wrappedKeyB64)) {
            Log.w("ZCHAT_FILE", "SR-A: the chat's key changed since this attachment was prepared — nothing uploaded or paid")
            _sendMessageState.value = SendMessageState.Error(ChatSendCopy.ATTACHMENT_RETRY_COPY_GONE)
            return ChatSendCopy.ATTACHMENT_RETRY_COPY_GONE
        }
        return null
    }

    /** Whether today's shared key with [peerAddress] opens the wrapped file key [wrappedKeyB64]. */
    private fun sharedKeyOpens(
        peerAddress: String,
        wrappedKeyB64: String,
    ): Boolean {
        val sharedKey = getE2ESharedKey(peerAddress) ?: return false
        return runCatching {
            co.electriccoin.zcash.ui.screen.chat.crypto.E2EEncryption.unwrapFileKey(
                java.util.Base64
                    .getDecoder()
                    .decode(wrappedKeyB64),
                sharedKey,
            )
        }.isSuccess
    }

    /**
     * SR-A (R-A2, C-SRA-7) — Retry of a FAILED Shielded link row ([failed], a `pending_` row whose submit never started,
     * or a `nostr-out-` row an older build left): the stored line is priced again and the exact Retry question asked
     * (S-A10); nothing is uploaded again. On Pay the quote goes to [retryMessage], which claims and sends the row once
     * with it. Called under [retryClaimLock], after F4's "may have been sent" refusal. True: the question (or a refusal
     * notice after pricing) is on its way.
     */
    private fun retryShieldedLink(
        peerAddress: String,
        failed: ChatMessage,
        rawMessage: String,
    ): Boolean {
        val messageId = failed.id
        if (messageId.startsWith(ON_CHAIN_PENDING_PREFIX) && !shieldedLinkRowNeverSubmitted(peerAddress, messageId)) {
            _sendMessageState.value = SendMessageState.Error(SubmitAttemptProof.MAY_HAVE_BEEN_SENT)
            return false
        }
        attachmentBlockReason(peerAddress)?.let {
            showAttachmentBlocked(it)
            return false
        }
        val wrappedKey =
            co.electriccoin.zcash.ui.screen.chat.model.ZFILEMessage
                .parse(rawMessage)
                ?.wrappedKey
        if (wrappedKey == null || !sharedKeyOpens(peerAddress, wrappedKey)) {
            _sendMessageState.value = SendMessageState.Error(ChatSendCopy.ATTACHMENT_RETRY_COPY_GONE)
            return false
        }
        if (chatClosedForSelectedAccount()) {
            refuseClosedChat("a Shielded link retry")
            return false
        }
        if (blockedByKeyChange(peerAddress)) return false
        viewModelScope.launch {
            val price = priceShieldedLink(peerAddress, rawMessage, PaidAction.SHIELDED_ATTACHMENT_RETRY)
            if (price is ShieldedLinkPrice.Refused) {
                Log.w("ZCHAT_FILE", "SR-A: the Shielded link's Retry was refused before anything was paid")
                price.rowReason?.let { reason ->
                    pendingMessages.update { list -> list.map { if (it.id == messageId) it.copy(failureReason = reason) else it } }
                }
                _sendMessageState.value = price.state
                return@launch
            }
            price as ShieldedLinkPrice.Quoted
            // T5b X-06: the earlier try of this row paid its key exchange before the link was refused; the question says
            // so instead of "The earlier try was not paid".
            val confirmation =
                if (failed.failureReason == ChatSendCopy.ATTACHMENT_PRICE_CHANGED_KEX_PAID) {
                    price.confirmation.copy(keyExchangeAlreadyPaid = true)
                } else {
                    price.confirmation
                }
            if (!awaitPaidAnswer(confirmation)) return@launch
            if (shieldedPayRefusal(peerAddress, wrappedKey) != null) return@launch
            zchatPreferences.setAcknowledgedMessageCost()
            confirmedShieldedRetryQuotes[messageId] = price.quote
            if (!retryMessage(peerAddress, messageId, costConfirmed = true)) confirmedShieldedRetryQuotes.remove(messageId)
        }
        return true
    }

    /** SR-A — F4's proof, read from the stored row, that the `pending_` row [messageId] never started a submit. */
    @Suppress("TooGenericExceptionCaught")
    private fun shieldedLinkRowNeverSubmitted(
        peerAddress: String,
        messageId: String,
    ): Boolean =
        try {
            val row = zchatPreferences.getPendingMessages().firstOrNull { it.id == messageId }
            val neverSubmittedQueue =
                row != null &&
                    row.submitTracked &&
                    row.isPending &&
                    (row.status == null || row.status == MessageStatus.SENDING.name)
            row != null &&
                row.peerAddress == peerAddress &&
                row.submitStartedAtMillis == null &&
                row.submittedTxIds.isEmpty() &&
                (neverSubmittedQueue || (!row.isPending && row.status == MessageStatus.FAILED.name))
        } catch (e: Exception) {
            Log.w("ZCHAT_SEND", "SR-A: the Shielded link row could not be read: ${e.javaClass.simpleName}")
            false
        }

    /**
     * SR-A (A-11) — a FAILED `nostr-out-` link row in a chat that is Shielded now, after Pay: sent on-chain as a new
     * `pending_` row with [quote] (an on-chain send is tracked by its `pending_` id from the submit on), and the relay row
     * is removed only once that send was accepted. Never over the relays, never a second upload.
     */
    private fun resendRelayLinkOnChain(
        peerAddress: String,
        failed: ChatMessage,
        rawMessage: String,
        quote: ChatSendQuote,
    ): Boolean {
        val accepted =
            sendMessage(
                peerAddress,
                rawMessage,
                failed.sendAmountZatoshi ?: DEFAULT_MESSAGE_AMOUNT,
                restoreTextOnCancel = false,
                sendQuote = quote,
            )
        if (accepted) {
            pendingMessages.update { list -> list.filterNot { it.id == failed.id } }
            runCatching { zchatPreferences.removePendingMessage(failed.id) }
        }
        return accepted
    }

    /**
     * SR-C1 — the answer the open KI-37 warning waits for (true = "Send anyway"); null when none is open. Nullable and
     * swapped only under the class-wide [legacyAttachmentAnswerLock], so an instance built without its constructor
     * (tests) reads it as "none open" instead of failing the attachment.
     */
    @Volatile private var legacyAttachmentAnswer: CompletableDeferred<Boolean>? = null

    /** SR-C1 — puts [next] in place of the waiting answer and returns the one it replaced (null when none was open). */
    private fun swapLegacyAttachmentAnswer(next: CompletableDeferred<Boolean>?): CompletableDeferred<Boolean>? =
        synchronized(legacyAttachmentAnswerLock) { legacyAttachmentAnswer.also { legacyAttachmentAnswer = next } }

    /**
     * SR-C1 (KI-37) — true when this contact's newest relay rumor carried no Ironwood capability tag: its ZChat is 2.12
     * or older and shows a 2.13 attachment's link as a line of code. No rumor on record (or a store that cannot be read)
     * is not a reason to warn.
     */
    private fun isLegacyContact(peerAddress: String): Boolean =
        runCatching { zchatPreferences.getPeerIronwoodCap(peerAddress) }.getOrNull()?.capIronwood == false

    /**
     * SR-C1 (KI-37) — for a contact on ZChat 2.12 or older, show the warning and wait for the answer. True: go on with
     * the upload ("Send anyway", or no warning needed). False: nothing is uploaded, sent or paid; the bubble [optimisticId]
     * is FAILED with the reason and keeps its retry copy, whose Retry asks again. A Keystone account selected while the
     * warning was open refuses as every chat action does.
     */
    private suspend fun legacyContactAttachmentAllowed(
        peerAddress: String,
        optimisticId: String,
        kind: AttachmentKind,
    ): Boolean {
        if (!isLegacyContact(peerAddress)) return true
        Log.w("ZCHAT_FILE", "SR-C1: contact's newest relay message came from an older ZChat — warning before the upload")
        val sendAnyway = askLegacyContactAttachment(peerAddress)
        if (sendAnyway && !chatClosedForSelectedAccount()) return true
        if (sendAnyway) {
            refuseClosedChat("an attachment")
            markAttachmentFailed(optimisticId, kind, ChatSendCopy.KEYSTONE_CHATS_CLOSED)
        } else {
            markAttachmentFailed(optimisticId, kind, ChatSendCopy.ATTACHMENT_LEGACY_CONTACT_CANCELLED)
        }
        return false
    }

    /**
     * SR-C1 — shows [SendMessageState.LegacyContactAttachmentWarning] and suspends until it is answered. Anything that
     * takes the warning off the screen other than "Send anyway" reads as Cancel: "Cancel", a dismissal (the screen resets
     * the state), another notice or question replacing it, or a newer warning. Leaving the chat cancels the wait.
     */
    private suspend fun askLegacyContactAttachment(peerAddress: String): Boolean {
        val answer = kotlinx.coroutines.CompletableDeferred<Boolean>()
        swapLegacyAttachmentAnswer(answer)?.complete(false)
        val warning = SendMessageState.LegacyContactAttachmentWarning(peerAddress, askId = System.nanoTime())
        _sendMessageState.value = warning
        return try {
            kotlinx.coroutines.coroutineScope {
                val gone =
                    launch {
                        _sendMessageState.first { it != warning }
                        answer.complete(false)
                    }
                answer.await().also { gone.cancel() }
            }
        } finally {
            synchronized(legacyAttachmentAnswerLock) { if (legacyAttachmentAnswer === answer) legacyAttachmentAnswer = null }
            if (_sendMessageState.value == warning) _sendMessageState.value = SendMessageState.Idle
        }
    }

    /** SR-C1 — "Send anyway" on the KI-37 warning: the attachment is uploaded and sent as it would have been. */
    fun confirmLegacyContactAttachment() {
        swapLegacyAttachmentAnswer(null)?.complete(true)
        if (_sendMessageState.value is SendMessageState.LegacyContactAttachmentWarning) {
            _sendMessageState.value = SendMessageState.Idle
        }
    }

    /** SR-C1 — "Cancel" on the KI-37 warning: nothing is uploaded; the row stays FAILED with its retry copy. */
    fun cancelLegacyContactAttachment() {
        swapLegacyAttachmentAnswer(null)?.complete(false)
        if (_sendMessageState.value is SendMessageState.LegacyContactAttachmentWarning) {
            _sendMessageState.value = SendMessageState.Idle
        }
    }

    /**
     * R9-4 — Retry on a FAILED photo, file or voice bubble whose ZFILE was never handed to a send (its upload failed,
     * or the send was refused or its cost declined before anything was stored): upload the kept ciphertext again and
     * send it, exactly as the first attempt would have. Nothing about it can have been paid, so nothing is asked here
     * that the send itself does not ask. False (nothing started) when no retry copy is kept (older than 24 h, deleted,
     * or the app restarted) or another upload is running.
     */
    private fun retryAttachment(
        peerAddress: String,
        failed: ChatMessage,
    ): Boolean {
        val kind = AttachmentKind.ofId(failed.id) ?: return false
        // ZC-250: nothing is uploaded again for a contact whose key changed; the row stays FAILED and the notice shows.
        if (blockedByKeyChange(peerAddress)) return false
        // SR-C2: a Retry is never silent. With no end-to-end key it shows the notice (the row stays FAILED); with no
        // retry copy kept it says the attachment must be picked (or recorded) again; a busy upload slot says so.
        val blocked = attachmentBlockReason(peerAddress)
        if (blocked != null) {
            showAttachmentBlocked(blocked)
            return false
        }
        val store = attachmentRetryStore
        if (store == null || !store.contains(failed.id)) {
            _sendMessageState.value = SendMessageState.Error(ChatSendCopy.ATTACHMENT_RETRY_COPY_GONE)
            return false
        }
        if (!uploadProgressTracker.tryStart()) {
            _sendMessageState.value = SendMessageState.Error(noteCopy.get(R.string.chat_upload_busy))
            return false
        }
        val optimisticId = failed.id
        pendingMessages.update { list ->
            list.map { if (it.id == optimisticId) it.copy(isPending = true, status = MessageStatus.SENDING, failureReason = null) else it }
        }
        viewModelScope.launch {
            try {
                val (encrypted, entry) =
                    withContext(kotlinx.coroutines.Dispatchers.IO) { store.get(optimisticId) }
                        ?: throw Exception("Retry copy is gone")
                uploadProgressTracker.encrypted()
                // The chat's key may have changed since the file was prepared (a new key exchange): the peer could not
                // open a file key wrapped with the old one. Check that today's shared secret still opens it.
                val sharedKey =
                    getE2ESharedKey(peerAddress)
                        ?: throw AttachmentKeyMissingException()
                val opens =
                    runCatching {
                        co.electriccoin.zcash.ui.screen.chat.crypto.E2EEncryption.unwrapFileKey(
                            java.util.Base64
                                .getDecoder()
                                .decode(entry.wrappedKeyB64),
                            sharedKey,
                        )
                    }.isSuccess
                if (!opens) {
                    withContext(kotlinx.coroutines.Dispatchers.IO) { store.remove(optimisticId) }
                    error("The chat's key changed since this attachment was prepared")
                }
                // SR-A: in a Shielded chat this asks the exact price again, as the Retry's question (S-A10).
                if (!sendAttachmentBlob(peerAddress, optimisticId, kind, encrypted, entry, store, retry = true)) return@launch
                kotlinx.coroutines.delay(400)
            } catch (e: kotlinx.coroutines.CancellationException) {
                throw e
            } catch (e: Exception) {
                Log.e("ZCHAT_FILE", "Attachment retry failed: ${e.javaClass.simpleName}")
                val reason = attachmentFailureReason(kind, e)
                markAttachmentFailed(optimisticId, kind, reason)
                if (e is AttachmentKeyMissingException) {
                    // SR-C2 backstop: the key vanished after the entry check; the row stays FAILED and names it.
                    showAttachmentBlocked(attachmentBlockReason(peerAddress) ?: AttachmentBlockReason.NEEDS_KEY_EXCHANGE)
                    return@launch
                }
                _sendMessageState.value =
                    co.electriccoin.zcash.ui.screen.chat.model.SendMessageState
                        .Error(reason)
            } finally {
                uploadProgressTracker.reset()
            }
        }
        return true
    }

    /**
     * Handle a /ai slash command in chat. Renders the user's prompt + the AI's reply as
     * local-only messages (isAiMessage = true) — never sent on-chain, never ratcheted,
     * never debited against the user's ZEC balance. AI usage is charged against the
     * separate Venice credit balance (see AI tab).
     *
     * SECURITY: Reject sloppy variants ("/AI ", "/ai" without space) BEFORE this hits the
     * normal send path so the user can't accidentally leak their AI prompt to the peer
     * over the encrypted chat channel.
     */
    @Suppress("TooGenericExceptionCaught")
    fun handleAiCommand(peerAddress: String, prompt: String, context: android.content.Context) {
        if (prompt.isBlank()) return
        val now = java.time.Instant.now()
        val userMsgId = "ai-user-${System.nanoTime()}"
        val replyMsgId = "ai-reply-${System.nanoTime()}"

        // Insert user's prompt as a local outgoing message (renders immediately)
        val userMsg = ChatMessage(
            id = userMsgId,
            txId = null,
            text = prompt,
            timestamp = now,
            isOutgoing = true,
            peerAddress = peerAddress,
            isPending = false,
            status = MessageStatus.SENT,
            isAiMessage = true,
        )
        pendingMessages.update { it + userMsg }

        // Insert a placeholder "AI is thinking…" reply that we'll overwrite on success
        val thinkingMsg = ChatMessage(
            id = replyMsgId,
            txId = null,
            text = "🤖 Thinking…",
            timestamp = now.plusMillis(1),
            isOutgoing = false,
            peerAddress = peerAddress,
            isPending = true,
            status = MessageStatus.SENDING,
            isAiMessage = true,
        )
        pendingMessages.update { it + thinkingMsg }

        viewModelScope.launch {
            try {
                val prefs = co.electriccoin.zcash.ui.screen.ai.AiPreferences(context.applicationContext)
                val client = co.electriccoin.zcash.ui.screen.ai.AiApiClient()
                // AI-KEY-S: the key comes from the one place that decides about it, after key/state answered.
                val access =
                    org.koin.java.KoinJavaComponent.get<co.electriccoin.zcash.ui.screen.ai.AiAccountAccess>(
                        co.electriccoin.zcash.ui.screen.ai.AiAccountAccess::class.java,
                    )
                // Round 3: the fence is noted before the key is read, and the request stays under it.
                val fence = access.scopeNow()
                val token = access.keyForCharge().first
                if (token == null) {
                    replaceAiMessage(replyMsgId, peerAddress, "🤖 Could not initialize AI. Open AI tab first.", failed = true)
                    return@launch
                }
                val ticket = fence.forKey(token)
                // Use the user's selected model from the AI tab. Fall back to the cheap default
                // so we don't accidentally bill an expensive model when the user never opened
                // the AI tab. NOTE: this also respects free-tier gating server-side.
                val selectedModel = prefs.getSelectedChatModel() ?: "venice-uncensored-1-2"
                val turn =
                    co.electriccoin.zcash.ui.screen.ai.AiChatTurn(
                        co.electriccoin.zcash.ui.screen.ai.AiChatTurn.ROLE_USER,
                        prompt,
                        System.currentTimeMillis(),
                    )
                // ZC-1194: a refused call was never charged: it goes to AiAccountAccess and runs once more on the new key.
                val answered =
                    access.request<co.electriccoin.zcash.ui.screen.ai.ChatResult>(
                        ticket,
                        isRefused = { it is co.electriccoin.zcash.ui.screen.ai.ChatResult.Failure && it.refused },
                        refuse = { access.onRefused(it.key, it.fence) },
                        told = { _, _ -> },
                    ) { key -> client.chat(token = key, model = selectedModel, history = listOf(turn), maxTokens = 1024) }
                when (val r = answered?.result) {
                    null -> {
                        // ZC-1238: the request may have been billed before the wallet changed: this says so.
                        val walletChanged = context.getString(R.string.ai_wallet_changed)
                        replaceAiMessage(replyMsgId, peerAddress, "🤖 $walletChanged", failed = true)
                    }
                    is co.electriccoin.zcash.ui.screen.ai.ChatResult.Success -> {
                        replaceAiMessage(replyMsgId, peerAddress, "🤖 ${r.reply}", failed = false)
                    }
                    is co.electriccoin.zcash.ui.screen.ai.ChatResult.OutOfCredit -> {
                        replaceAiMessage(replyMsgId, peerAddress, "🤖 Out of AI credit. Top up in the AI tab.", failed = true)
                    }
                    is co.electriccoin.zcash.ui.screen.ai.ChatResult.Failure -> {
                        replaceAiMessage(replyMsgId, peerAddress, "🤖 ${r.error}", failed = true)
                    }
                }
            } catch (e: Exception) {
                Log.e("ZCHAT_AI", "AI command failed: ${e.message}", e)
                replaceAiMessage(replyMsgId, peerAddress, "🤖 AI request failed.", failed = true)
            }
        }
    }

    private fun replaceAiMessage(id: String, peerAddress: String, text: String, failed: Boolean) {
        pendingMessages.update { list ->
            list.map { m ->
                if (m.id == id) m.copy(
                    text = text,
                    isPending = false,
                    status = if (failed) MessageStatus.FAILED else MessageStatus.SENT,
                ) else m
            }
        }
    }

    /**
     * R4-4 (2) — hand a file send's optimistic bubble [optimisticId] over to [sendMessage].
     *
     * The photo and voice paths show a bubble the moment the user picks the file and keep it up through
     * compression, encryption and upload. Returns true when the send was ACCEPTED, and only then is the
     * bubble dropped — [sendMessage] has stored its own pending row, and both reference the same on-disk
     * cache file, so the handoff is seamless.
     *
     * "Accepted" includes a send still WAITING behind the first-message cost prompt (R2-2 b), which is why
     * the undo is passed as well: if the user cancels the prompt, or confirms it and the send is then refused
     * before anything is queued, the bubble is left FAILED (retryable) with [failedText]. Without it the
     * bubble vanished, no file was ever sent, and the upload indicator had already said "sent".
     */
    private fun sendFileWithOptimisticBubble(
        peerAddress: String,
        message: String,
        optimisticId: String,
        failedText: String,
    ): Boolean = sendFileWithOptimisticBubble(peerAddress, message, optimisticId, failedText, onHandedOff = null)

    /**
     * R9-4: [onHandedOff] runs once the ZFILE is really handed to the send: at once when the send takes it, or, when
     * it waits behind the cost prompt, after the user confirms and the send takes it. It never runs when the bubble is
     * left FAILED (a refusal, a declined prompt), so a failed attachment keeps what its Retry needs.
     */
    private fun sendFileWithOptimisticBubble(
        peerAddress: String,
        message: String,
        optimisticId: String,
        failedText: String,
        onHandedOff: (() -> Unit)?,
        // SR-A: the exact price the user paid for (a Shielded attachment); the send pays exactly it or nothing.
        sendQuote: ChatSendQuote? = null,
    ): Boolean {
        // Read once, before the handoff: a send waiting behind the cost prompt is already "accepted", so by
        // the time the user answers it the bubble has been handed off and there is nothing left to mark.
        val shown = pendingMessages.value.firstOrNull { it.id == optimisticId }

        fun failed(m: ChatMessage) = m.copy(text = failedText, isPending = false, status = MessageStatus.FAILED)

        val markFailed = {
            pendingMessages.update { list ->
                when {
                    list.any { it.id == optimisticId } -> list.map { if (it.id == optimisticId) failed(it) else it }
                    // Handed off to a send that never happened: put it back rather than leave the chat with
                    // nothing to retry and an upload indicator that already said "sent".
                    shown != null -> list + failed(shown)
                    else -> list
                }
            }
        }
        val accepted =
            sendMessage(peerAddress, message, restoreTextOnCancel = false, onCostDeclined = markFailed, sendQuote = sendQuote)
        if (!accepted) {
            markFailed()
            return false
        }
        pendingMessages.update { list -> list.filterNot { it.id == optimisticId } }
        if (onHandedOff != null) {
            val waitingForAnswer = pendingPaidDecline === markFailed
            val pay = pendingPaidAction
            when {
                // Behind the cost prompt: the confirmed send puts the bubble back FAILED (markFailed) when it is refused.
                waitingForAnswer && pay != null ->
                    pendingPaidAction = {
                        pay()
                        if (pendingMessages.value.none { it.id == optimisticId }) onHandedOff()
                    }
                // Behind the one-time cost notice: kept until it is swept (it may still be declined).
                _showCostDisclaimer.value -> Unit
                else -> onHandedOff()
            }
        }
        return true
    }

    @Suppress("TooGenericExceptionCaught")
    fun sendMessage(
        peerAddress: String,
        message: String,
        amountZatoshi: Long = DEFAULT_MESSAGE_AMOUNT,
        retryPendingId: String? = null,
        retryClaimStartedAt: Long? = null,
        costConfirmed: Boolean = false,
        restoreTextOnCancel: Boolean = true,
        onCostDeclined: (() -> Unit)? = null,
        // SR-A (C-SRA-2): the exact price the user was asked and paid (a Shielded attachment's link). Its send asks
        // nothing more and carries the quote to the use case, which pays exactly it or nothing.
        sendQuote: ChatSendQuote? = null,
        // SR-B2: called once, right before the send takes the payload (after every question and refusal); false = the
        // payload was already taken (another tap or screen), so nothing is stored or sent. The Retry of a row a Shielded
        // switch left removes that row here, so Cancel, a dismissed notice or a refusal keep it with its text.
        claimPayload: (() -> Boolean)? = null,
    ): Boolean {
        // Returns true when the send was ACCEPTED (broadcast, queued, or deferred behind the cost
        // disclaimer) and false when REJECTED before anything was queued (key changed / funds not in
        // the Orchard pool) — the caller keeps the user's typed text on false so it isn't lost
        // (B1-msg-lost-on-blocked-send). R3-2 (2): a send deferred behind the first-message cost prompt is
        // accepted (the screen clears its input); if the user cancels, the text is handed back
        // (restoredTypedText) unless [restoreTextOnCancel] is false (a file payload is not typed text).
        // R4-4 (2): [onCostDeclined] replaces that undo for a caller that cleared something else instead (a
        // file send's optimistic bubble), and BOTH now also run when the user CONFIRMS and the send is then
        // refused before anything is queued — the screen had already cleared what it holds.

        // B9 (SHARED-TEXT-CAP): no send pays for more than a MAX_MESSAGE_INPUT_CHARS message, whatever text
        // reaches it — a draft stored by an older version, a retry of a row stored before the cap, any caller.
        // The composer already trims to the same cap, so a message typed or shared today is never cut here.
        if (message.length > MAX_MESSAGE_INPUT_CHARS) {
            return sendMessage(
                peerAddress,
                capDraft(message),
                amountZatoshi,
                retryPendingId,
                retryClaimStartedAt,
                costConfirmed,
                restoreTextOnCancel,
                onCostDeclined,
                sendQuote,
                claimPayload,
            )
        }

        // T1b-1 (A) and §2: with a Keystone account selected the chat is closed on every transport. Refused before the
        // relay route and before the first-message question, so nothing is written (no owed KEX, no quoted ZBOOT, no
        // key, no conversation id, no row) and the screen keeps the typed text.
        if (chatClosedForSelectedAccount()) {
            refuseClosedChat("a message")
            return false
        }

        // SECURITY (TOFU / MITM): block a key-changed peer BEFORE transport routing so TUNNEL/OPEN
        // (NOSTR) sends are gated too, not just the VAULT path below. EXEMPT the ZBOOT handshake:
        // it is precisely how trust is RE-established after a key change, and ensureNostrBootstrapSent
        // routes it through here — gating it would DEADLOCK recovery (you could never re-handshake a
        // peer whose key rotated). Only content (text/file/etc.) stays gated.
        if (!co.electriccoin.zcash.ui.screen.chat.model.ZBootMessage
                .isBootMessage(message) &&
            blockedByKeyChange(peerAddress)
        ) {
            return false
        }

        // ZC-1474 (W-123) backstop: a ZATT line holds its file key, so it goes only over the relays to the bound key of a
        // zatt1 contact in an Open or Tunnel chat (a Retry included; the app never reply-tags one). Anything else is
        // refused: nothing stored or paid.
        val zattPayload = ZATTMessage.isZatt(message)
        if (zattPayload && zattRecipientKey(peerAddress) == null) {
            Log.w("ZCHAT_SEND", "ZC-1474: a free attachment line refused — this chat has no free relay route to the contact")
            _sendMessageState.value = SendMessageState.Error(zattRefusalReason(peerAddress))
            return false
        }

        // Route via the conversation's transport mode. VAULT (default) falls through to
        // the existing shielded pipeline below; TUNNEL/OPEN send through NIP-17 instead.
        // A retry retains its original paid/free lane as well as its amount. In particular a paid
        // file retry must not become a Nostr row still carrying a paid pending_ identity.
        if (retryPendingId == null || !retryPendingId.startsWith(ON_CHAIN_PENDING_PREFIX)) {
            if (handleNostrRouteIfApplicable(peerAddress, message, retryPendingId)) return true
        }
        // ZC-1474 backstop: never on a non-relay route.
        if (zattPayload) {
            Log.w("ZCHAT_SEND", "ZC-1474: a free attachment line refused on a non-relay route — nothing stored or paid")
            _sendMessageState.value = SendMessageState.Error(zattRefusalReason(peerAddress))
            return false
        }
        if (retryPendingId != null && !retryPendingId.startsWith(ON_CHAIN_PENDING_PREFIX)) {
            _sendMessageState.value = SendMessageState.Error(RETRY_MODE_CHANGED)
            return false
        }
        // ZC-1792 F1: a responder whose answer is not paid seals nothing Shielded (a message or an attachment line), before
        // any question or payment; nothing is stored, built or paid, and the caller keeps the text (a Retry keeps its row).
        // The handshake memos are exempt.
        if (!isHandshakeControlMemo(message) && ownAnswerToStoredKeyUnpaid(peerAddress)) {
            // ZC-1861 (QA2 pa3): a Retry of a row whose earlier run paid its setup (rowsWithKexPaid, carried over a restart
            // from the row's reason by retryMessage) never says nothing was paid.
            refuseAcceptFirst(peerAddress, setupPaid = retryPendingId != null && retryPendingId in rowsWithKexPaid)
            return false
        }

        // R2-2 (b): the first on-chain message to a new contact is preceded by our paid KEX (doSendMessage). Ask
        // first, quoting both transactions; nothing is stored or sent until the user confirms.
        // SR-A: a quoted send was asked its exact price already; that question was the consent.
        val priceAccepted = costConfirmed || sendQuote != null
        if (!priceAccepted && retryPendingId == null && firstOnChainMessageNeedsKex(peerAddress, message)) {
            // R4-4 (2): one undo for both answers to the prompt. The screen cleared its input (and a file
            // send its bubble) the moment this send was accepted behind the prompt, so the undo must run on
            // Cancel AND when the user confirms and the confirmed send is refused before anything is queued
            // (the spendable value moved into sealed Orchard, the peer's key changed). It never runs when
            // the send goes out.
            val undo: (() -> Unit)? =
                onCostDeclined ?: if (restoreTextOnCancel) ({ restoreTypedText(peerAddress, message) }) else null
            // R4-6 (round 3 report 4 item 10): the message is counted with the SAME sizer the on-chain builder packs
            // with (a v4 INIT's first memo chunk embeds our full unified address inline). Round 10b R10B-1 (F-R9C-1): and
            // our ZBOOT is counted when it must go on-chain after the contact's KEXACK, so the spend never exceeds this.
            // FC-ID (5.3a item 4): the id is made before the question counts the memos, so a contact who wrote first under
            // its own id does not make the first message counted (and sent) as a reply.
            planOwnConversationId(peerAddress)
            val quote = firstMessageQuote(peerAddress, message, amountZatoshi)
            val memos = onChainMemoCount(peerAddress, message)
            // M2 (fix-all 2.13.0): before the question, the same plan check the send's gate asks (a courtesy: it spares
            // the user a question whose Pay would be refused). A plan the wallet cannot pay, or one that could not be
            // checked, is refused here with the text back; nothing is stored or paid. The send stays accepted behind the
            // check, as behind the question; a refusal decided before this call returns rejects it instead (false), so
            // the screen never clears a text that was already handed back.
            val checkState =
                java.util.concurrent.atomic
                    .AtomicInteger(PLAN_CHECK_RUNNING)
            // ZC-1271: typed text with funds still confirming is asked its price and then waits; a file keeps the refusal.
            val mayWaitForFunds =
                onCostDeclined == null &&
                    restoreTextOnCancel &&
                    !co.electriccoin.zcash.ui.screen.chat.model.ZFILEMessage
                        .isFileMessage(message)
            viewModelScope.launch {
                // T5b X-02: the send was accepted behind this check, so the screen has cleared its input and the draft.
                // A chat left before the check answered asks nothing, and its text (or its file bubble) is handed back
                // like a cancelled question: the typed text is the chat's draft again.
                var askedAccount: String? = null
                // ZC-1395: the account this question is asked under; a queued send of it pays from no other.
                var confirmingAccount: String? = null
                val plan =
                    try {
                        checkFirstMessagePlan(peerAddress, memos, amountZatoshi).also {
                            confirmingAccount = selectedAccountOrNull()?.let(GetDefaultUnifiedAddressUseCase::accountKeyOf)
                            if (mayWaitForFunds) askedAccount = confirmingAccount
                            if (coroutineContext[Job]?.isActive == false) {
                                throw kotlinx.coroutines.CancellationException("The chat was left during the plan check")
                            }
                        }
                    } catch (e: kotlinx.coroutines.CancellationException) {
                        undo?.invoke()
                        throw e
                    }
                // ZC-1326: with no known account nothing could name who pays at a later block, so funds still confirming refuse.
                val mayWaitAsAsked = mayWaitForFunds && plan is FirstMessagePlan.WaitForFunds && askedAccount != null
                if (plan !is FirstMessagePlan.Fundable && !mayWaitAsAsked) {
                    val handsTextBack = onCostDeclined == null && restoreTextOnCancel
                    _sendMessageState.value = SendMessageState.Error(firstMessagePlanRefusal(plan, row = !handsTextBack))
                    checkState.compareAndSet(PLAN_CHECK_RUNNING, PLAN_CHECK_REFUSED_BEFORE_RETURN)
                    undo?.invoke()
                    return@launch
                }
                askBeforePaying(
                    PaidActionConfirmation(
                        PaidAction.FIRST_MESSAGE,
                        onChainMessages = quote.transactions,
                        totalCost = quote.total,
                        includesRelayIdentity = quote.includesZboot,
                        // ZC-1272: the screen states each leg.
                        setupLegs = quote.transactions - 1,
                        setupLegCost = onChainSendMinimumCost(),
                        messageLegCost = onChainSendMinimumCost(memos, Zatoshi(amountZatoshi)),
                        waitsForFunds = plan is FirstMessagePlan.WaitForFunds,
                    ),
                    onDecline = undo,
                ) {
                    // T1b-1 (B): the account may have changed to a Keystone one while the question was open. Nothing is
                    // stored, the text is handed back, and the Keystone text is shown.
                    if (chatClosedForSelectedAccount()) {
                        refuseClosedChat("a confirmed first message")
                        undo?.invoke()
                        return@askBeforePaying
                    }
                    // R10B-1: the quoted ZBOOT may later be paid only against a record on disk, written before anything
                    // is paid (R5-2).
                    // ZC-590: that record is written by the send, once it has taken the message (after its gate,
                    // [takeUnsentZbootQuote]); until then the quote is only remembered here (unsentZbootQuotes). So a
                    // confirmed first message that is never sent (a refusal, a dismissed cost notice, the end of the
                    // process) leaves nothing on disk that a later KEXACK or inbound ZBOOT could pay on.
                    if (quote.includesZboot) unsentZbootQuotes.add(peerAddress)
                    // ZC-1271: what this Pay accepted, for the row the send saves if the funds are still confirming.
                    // ZC-1396: and on every path the total the question showed, the message leg's ceiling.
                    acceptedFirstMessages[peerAddress] =
                        AcceptedFirstMessage(
                            quote.total.value,
                            askedAccount,
                            confirmingAccount,
                            waits = mayWaitForFunds,
                            mode = storedModeOf(zchatPreferences.getConversationMode(peerAddress)),
                        )
                    val accepted =
                        sendMessage(
                            peerAddress,
                            message,
                            amountZatoshi,
                            costConfirmed = true,
                            restoreTextOnCancel = restoreTextOnCancel,
                            onCostDeclined = onCostDeclined,
                            claimPayload = claimPayload,
                        )
                    if (!accepted) {
                        acceptedFirstMessages.remove(peerAddress)
                        // T1b-1 (B): a confirmed first message refused before anything was queued leaves no quoted ZBOOT
                        // behind for a later KEXACK to pay.
                        if (quote.includesZboot) withdrawZbootQuote(peerAddress)
                        unsentZbootQuotes.remove(peerAddress)
                        undo?.invoke()
                    }
                }
            }
            return checkState.compareAndSet(PLAN_CHECK_RUNNING, PLAN_CHECK_RETURNED) ||
                checkState.get() != PLAN_CHECK_REFUSED_BEFORE_RETURN
        }

        // ZC-1478 (W-122, M1): the contact moved this chat to Shielded and the user was asked no price in it since. The
        // first on-chain message asks once, with its price (every memo counted), before anything is stored or paid; the
        // answered question (this one or the first-message one above) clears the mark, so it is asked once.
        if (retryPendingId == null &&
            !ZBootMessage.isBootMessage(message) &&
            modeMovedToPaidByPeer(peerAddress)
        ) {
            if (priceAccepted) {
                // ZC-1508: the mark goes only once this send's proposal is submitted (onSubmitStarting in doSendMessage); a
                // Pay that submits nothing leaves the next send asking. Without an accepted-price record the mark stays.
                acceptedFirstMessages.computeIfPresent(peerAddress) { _, it -> it.copy(clearsPeerMovedMark = true) }
            } else {
                val memos = onChainMemoCount(peerAddress, message)
                val undo: (() -> Unit)? =
                    onCostDeclined ?: if (restoreTextOnCancel) ({ restoreTypedText(peerAddress, message) }) else null
                val shown = onChainSendMinimumCost(memos, Zatoshi(amountZatoshi))
                if (refusedByTheSpendableMargin(shown)) return false
                askBeforePaying(
                    PaidActionConfirmation(
                        PaidAction.PEER_MOVED_TO_SHIELDED,
                        onChainMessages = 1,
                        totalCost = shown,
                    ),
                    onDecline = undo,
                ) {
                    // ZC-1506 (money-path rule 1): the figure shown is this message's ceiling; a proposal above it stops
                    // with FAILED_ABOVE_ACCEPTED_PRICE and nothing is signed or submitted. No account and no funds wait.
                    acceptedFirstMessages[peerAddress] =
                        AcceptedFirstMessage(shown.value, accountKey = null, waits = false, messageOnly = true)
                    val accepted =
                        sendMessage(
                            peerAddress,
                            message,
                            amountZatoshi,
                            costConfirmed = true,
                            restoreTextOnCancel = restoreTextOnCancel,
                            onCostDeclined = onCostDeclined,
                            claimPayload = claimPayload,
                        )
                    if (!accepted) {
                        acceptedFirstMessages.remove(peerAddress)
                        undo?.invoke()
                    }
                }
                return true
            }
        }

        // R8-fixup F1 (REVIEW_R8 F1, device D-F1): an on-chain message whose text needs more than one memo costs one
        // network-fee action per memo (a 5,000-character message is about 14 memos, 95,000 zatoshi). Ask first with every
        // memo counted, like the first message; nothing is stored or sent until the user confirms. A Retry asks in
        // retryMessage.
        if (!priceAccepted && retryPendingId == null && !ZBootMessage.isBootMessage(message)) {
            val memos = onChainMemoCount(peerAddress, message)
            if (memos > 1) {
                val undo: (() -> Unit)? =
                    onCostDeclined ?: if (restoreTextOnCancel) ({ restoreTypedText(peerAddress, message) }) else null
                val confirmation = longMessageConfirmation(memos, amountZatoshi)
                if (refusedByTheSpendableMargin(confirmation.totalCost)) return false
                askBeforePaying(confirmation, onDecline = undo) {
                    val accepted =
                        sendMessage(
                            peerAddress,
                            message,
                            amountZatoshi,
                            costConfirmed = true,
                            restoreTextOnCancel = restoreTextOnCancel,
                            onCostDeclined = onCostDeclined,
                            claimPayload = claimPayload,
                        )
                    if (!accepted) undo?.invoke()
                }
                return true
            }
        }

        // Messaging needs value in a shielded pool of the Orchard protocol (shieldedFundsRefusal). Rejected before
        // queue: nothing stored, so keep the user's typed text.
        shieldedFundsRefusal()?.let { refusal ->
            _sendMessageState.value = refusal
            return false
        }

        // Check if user has acknowledged that messages cost ZEC. SR-A, ZC-1272: not after a price question the user confirmed.
        if (!priceAccepted && !zchatPreferences.hasAcknowledgedMessageCost()) {
            pendingMessage = PendingMessageParams(peerAddress, message, amountZatoshi = amountZatoshi, claimPayload = claimPayload)
            _showCostDisclaimer.value = true
            // Deferred, not rejected: the text is retained in pendingMessage and re-sent on
            // acknowledge, so treat as accepted and let the input clear.
            return true
        }

        // If the memo is a serialized ZFILE, render the pending bubble as a file placeholder
        // instead of the raw "ZFILE|hash|j|..." text. Otherwise the sender sees one long-text
        // bubble plus a separate file bubble after confirmation.
        val pendingZfile =
            co.electriccoin.zcash.ui.screen.chat.model.ZFILEMessage
                .takeIf {
                    co.electriccoin.zcash.ui.screen.chat.model.ZFILEMessage
                        .isFileMessage(message)
                }?.parse(message)
        val pendingDisplayText =
            pendingZfile?.let(::fileRowText)
                ?: if (co.electriccoin.zcash.ui.screen.chat.model.ZBootMessage.isBootMessage(
                        message
                    )
                ) {
                    "🔐 Secure connection request sent"
                } else {
                    message
                }
        val pendingFileHash = pendingZfile?.hash
        val pendingFileZfileContent = pendingZfile?.let { message }
        val pendingFileBlurhash = pendingZfile?.blurhash?.takeIf { it.isNotEmpty() }

        // The SENDING row of a send that does not start at once (queued) or whose quote is bound to its id (SR-A), shown
        // and stored before the send runs. doSendMessage writes it itself for every other send.
        fun writePendingRow(pendingId: String): AcceptedFirstMessage? {
            val pendingChatMessage =
                ChatMessage(
                    id = pendingId,
                    txId = null,
                    text = pendingDisplayText,
                    timestamp = Instant.now(),
                    isOutgoing = true,
                    peerAddress = peerAddress,
                    isPending = true,
                    status = MessageStatus.SENDING,
                    fileHash = pendingFileHash,
                    fileZfileContent = pendingFileZfileContent,
                    fileBlurhash = pendingFileBlurhash,
                    sendAmountZatoshi = amountZatoshi,
                )
            pendingMessages.update { list -> list.filterNot { it.id == pendingId } + pendingChatMessage }
            // ZC-1071: this screen sends the row (queued or quoted) from now on; written before the row is stored.
            LiveSenders.waiting(pendingId, this@ChatViewModel)
            // ZC-1271: a confirmed first message queued behind another send keeps the price its Pay accepted.
            // ZC-1396: a send that may not wait for funds keeps it in its queue entry instead (returned), not on the row.
            val taken = acceptedFirstMessages.remove(peerAddress)
            val accepted = taken?.takeIf { it.waits }
            zchatPreferences.addPendingMessage(
                ZchatPreferences.PendingMessageData(
                    id = pendingId,
                    text = message,
                    timestampMillis = pendingChatMessage.timestamp.toEpochMilli(),
                    peerAddress = peerAddress,
                    sendAmountZatoshi = amountZatoshi,
                    submitTracked = true,
                    acceptedPriceZatoshi = accepted?.priceZatoshi,
                    acceptedAccountKey = accepted?.accountKey,
                )
            )
            return taken
        }

        // If a send is in progress, queue the message — show it as pending immediately
        if (_sendMessageState.value is SendMessageState.Sending) {
            if (retryPendingId != null) return false
            if (claimPayload?.invoke() == false) return false
            val pendingId = retryPendingId ?: "pending_${System.nanoTime()}"
            val firstMessage = writePendingRow(pendingId)
            // SR-A (C-SRA-2): a queued quoted send keeps its quote, by its pending id and in the queue entry.
            if (sendQuote != null) pendingSendQuotes[pendingId] = sendQuote
            synchronized(messageQueue) {
                messageQueue.add(
                    QueuedMessage(peerAddress, message, amountZatoshi, pendingId, sendQuote = sendQuote, firstMessage = firstMessage),
                )
            }
            Log.d("ZCHAT_SEND", "Message queued (${messageQueue.size} in queue): [${message.length} chars]")
            return true
        }

        // SR-A (C-SRA-2): the quote is bound to the row's pending id before the send runs (doSendMessage keeps its
        // signature and reads it there). A fresh quoted send writes its row here, so the id exists first.
        if (claimPayload?.invoke() == false) return false
        if (sendQuote != null) {
            val quotedId = retryPendingId ?: "pending_${System.nanoTime()}".also { writePendingRow(it) }
            pendingSendQuotes[quotedId] = sendQuote
            doSendMessage(peerAddress, message, amountZatoshi, existingPendingId = quotedId, expectedSubmitMarker = retryClaimStartedAt)
            return true
        }

        // User has acknowledged, proceed with sending
        doSendMessage(peerAddress, message, amountZatoshi, existingPendingId = retryPendingId, expectedSubmitMarker = retryClaimStartedAt)
        return true
    }

    /**
     * Retry keeps the durable logical message ID. The process-wide lock and a committed SENDING
     * claim stop a second chat screen from acting on a stale FAILED row. A crash after the claim
     * is conservative: the retained payload may have been submitted and is not automatically paid again.
     * Cached history, a guessed expiry and an empty tx-id list are not negative payment proofs.
     */
    @Suppress("TooGenericExceptionCaught")
    fun retryMessage(
        peerAddress: String,
        messageId: String,
        costConfirmed: Boolean = false,
    ): Boolean =
        synchronized(retryClaimLock) {
            val failed = pendingMessages.value.firstOrNull { it.id == messageId } ?: return@synchronized false
            if (!failed.isOutgoing || failed.status != MessageStatus.FAILED || failed.peerAddress != peerAddress) {
                return@synchronized false
            }
            // ZC-1071: a row another screen of this process is still sending is never taken over: nothing is built or paid
            // here. (One whose submit may have started is refused below with the may-have-been-sent reason, as before.)
            if (!failed.sendMayHaveGoneOut && isSendLiveInThisProcess(messageId)) {
                _sendMessageState.value = SendMessageState.Error(ChatSendCopy.RETRY_ALREADY_CLAIMED)
                return@synchronized false
            }
            // P2h: a payment request keeps no raw payload; it is sent again from its amount and reason.
            failed.paymentRequest?.let { request ->
                return@synchronized retryPaymentRequest(peerAddress, failed, request, costConfirmed)
            }
            // R9-4: a photo, file or voice bubble whose ZFILE was never handed to a send (its upload failed, or the send
            // was refused or its cost declined) carries no payload: Retry uploads its kept ciphertext again. Before this
            // it returned false here, and a bubble with no file hash yet fell through to be re-sent as its own label.
            if (failed.fileZfileContent == null && AttachmentKind.ofId(messageId) != null) {
                if (failed.sendMayHaveGoneOut) {
                    _sendMessageState.value = SendMessageState.Error(SubmitAttemptProof.MAY_HAVE_BEEN_SENT)
                    return@synchronized false
                }
                return@synchronized retryAttachment(peerAddress, failed)
            }
            val rawMessage = failed.recoverRawSendPayload() ?: return@synchronized false
            if (failed.sendMayHaveGoneOut) {
                _sendMessageState.value = SendMessageState.Error(SubmitAttemptProof.MAY_HAVE_BEEN_SENT)
                return@synchronized false
            }
            if (_sendMessageState.value is SendMessageState.Sending) return@synchronized false

            // ZC-1308 (money-path rule 1): a row stopped above the price the user accepted asks the current figure first.
            // Nothing is claimed or paid until Pay; the row stays stopped on Cancel. The same figure needs no new answer.
            if (!costConfirmed &&
                failed.failureReason == ChatSendCopy.FAILED_ABOVE_ACCEPTED_PRICE &&
                messageId.startsWith(ON_CHAIN_PENDING_PREFIX)
            ) {
                askRetryFigure(peerAddress, failed, rawMessage)
                return@synchronized true
            }

            // SR-A (R-A2, C-SRA-7): a FAILED Shielded link row in a chat that is Shielded now (`pending_` or `nostr-out-`)
            // is re-sent only through the exact Retry question, with the quote its Pay left here; never re-uploaded, never
            // RETRY_MODE_CHANGED, never sent without the quote. A row that may have been sent was refused above.
            var shieldedLinkQuote: ChatSendQuote? = null
            if (failed.fileZfileContent != null &&
                failed.replyToId == null &&
                co.electriccoin.zcash.ui.screen.chat.model.ZFILEMessage
                    .isFileMessage(rawMessage) &&
                zchatPreferences.getConversationMode(peerAddress) == ConversationMode.VAULT
            ) {
                val quote =
                    confirmedShieldedRetryQuotes.remove(messageId).takeIf { costConfirmed }
                        ?: return@synchronized retryShieldedLink(peerAddress, failed, rawMessage)
                if (!messageId.startsWith(ON_CHAIN_PENDING_PREFIX)) {
                    return@synchronized resendRelayLinkOnChain(peerAddress, failed, rawMessage, quote)
                }
                shieldedLinkQuote = quote
            }

            // SR-B2 (fix-all 2.13.0, C-SRB2-1): a queued Tunnel payload whose chat the user switched to Shielded before the
            // free connection was ready (a nostr-out- row with FAILED_SWITCHED_TO_SHIELDED, never published or paid) is sent
            // as a NEW Shielded send with every question of its path, instead of sendMessage / sendReply's
            // RETRY_MODE_CHANGED. A photo or file link took SR-A's exact question above.
            if (failed.failureReason == ChatSendCopy.FAILED_SWITCHED_TO_SHIELDED &&
                !messageId.startsWith(ON_CHAIN_PENDING_PREFIX) &&
                !co.electriccoin.zcash.ui.screen.chat.model.ZFILEMessage
                    .isFileMessage(rawMessage) &&
                zchatPreferences.getConversationMode(peerAddress) == ConversationMode.VAULT
            ) {
                return@synchronized resendSwitchedRowShielded(peerAddress, failed, rawMessage)
            }

            // R8-fixup F1: a paid Retry of a message that needs more than one memo asks first, as its first send did.
            // Nothing is claimed or sent until the user confirms; the row stays FAILED. True: the question is on screen.
            if (!costConfirmed && messageId.startsWith(ON_CHAIN_PENDING_PREFIX) && !ZBootMessage.isBootMessage(rawMessage)) {
                val retryText =
                    failed.replyToId?.let { tagReply(it, rawMessage, failed.replyToPreview.orEmpty()) } ?: rawMessage
                val memos = onChainMemoCount(peerAddress, retryText)
                if (memos > 1 &&
                    zchatPreferences.getConversationMode(peerAddress) ==
                    co.electriccoin.zcash.ui.screen.chat.model.ConversationMode.VAULT
                ) {
                    val confirmation = longMessageConfirmation(memos, failed.sendAmountZatoshi ?: DEFAULT_MESSAGE_AMOUNT)
                    // ZC-1822: the row stays FAILED.
                    if (refusedByTheSpendableMargin(confirmation.totalCost)) return@synchronized false
                    askBeforePaying(confirmation) {
                        retryMessage(peerAddress, messageId, costConfirmed = true)
                    }
                    return@synchronized true
                }
            }

            // A paid pending row must not silently switch transport or defer outside this durable claim.
            // ZC-1306: a row accepted in Tunnel (New Chat) was asked as on-chain, so its own mode is no switch.
            val retryMode = zchatPreferences.getConversationMode(peerAddress)
            val acceptedInThisMode =
                runCatching {
                    zchatPreferences.getPendingMessages().firstOrNull { it.id == messageId }?.acceptedMode == retryMode.name
                }.getOrDefault(false)
            if (messageId.startsWith(ON_CHAIN_PENDING_PREFIX) &&
                (
                    (retryMode.isNostrTransport && !acceptedInThisMode) ||
                        !zchatPreferences.hasAcknowledgedMessageCost()
                )
            ) {
                _sendMessageState.value = SendMessageState.Error(RETRY_MODE_CHANGED)
                return@synchronized false
            }
            try {
                val row =
                    zchatPreferences.getPendingMessages().firstOrNull { it.id == messageId }
                        ?: return@synchronized false
                val neverSubmittedQueue =
                    messageId.startsWith(ON_CHAIN_PENDING_PREFIX) &&
                        row.submitTracked &&
                        row.isPending &&
                        (row.status == null || row.status == MessageStatus.SENDING.name)
                // ZC-421 (Z13): a relay row the closed app left still stored as pending is retried, never refused as
                // possibly paid (nothing paid can be behind it); one another screen finished is not retried.
                val relayRow = row.isRelayRow()
                if (row.peerAddress != peerAddress ||
                    row.submitStartedAtMillis != null ||
                    row.submittedTxIds.isNotEmpty() ||
                    (!neverSubmittedQueue && !relayRow && (row.isPending || row.status != MessageStatus.FAILED.name))
                ) {
                    _sendMessageState.value = SendMessageState.Error(SubmitAttemptProof.MAY_HAVE_BEEN_SENT)
                    return@synchronized false
                }
                if (relayRow && !row.isPending && row.status != MessageStatus.FAILED.name) return@synchronized false
                if (relayRow && row.isPending) {
                    Log.d("ZCHAT_NOSTR", "Retry of a row left in flight (${if (row.relayRumorId != null) "pair" else "no-pair"})")
                }
                // ZC-421: the row's rumor pair goes to its writer through this per-row map (taken there, removed below).
                if (relayRow) {
                    relayRetryPairs[messageId] =
                        RelayRumorPair(row.relayRumorAtSec, row.relayRumorId, notTaken = row.failureReason == ChatSendCopy.FAILED_NO_RELAY)
                }
                val claimedAt = nextSubmitMarker().takeIf { messageId.startsWith(ON_CHAIN_PENDING_PREFIX) }
                // F4: the claimed row is in flight here until its send ends (or the dispatch is refused below).
                SendAttemptProcess.enter(messageId)
                // ZC-1271: the user's tap is this attempt's answer: it no longer waits on the earlier price.
                // ZC-1308: a figure the user just confirmed is this attempt's limit.
                val confirmedFigure = confirmedRetryFigures.remove(messageId)
                // ZC-1310: the reason this Retry clears is what a new process knows of the key exchange an earlier run paid.
                // ZC-1861 (QA2 pa3): so is the Accept-first refusal after a paid setup (ZC-1843): a Retry after a restart
                // must not write "nothing was paid" over it.
                if (row.failureReason == ChatSendCopy.FAILED_BUILD_TOO_LONG_KEX_PAID ||
                    row.failureReason == ChatSendCopy.FAILED_FUNDS_CONFIRMING_SETUP_PAID ||
                    row.failureReason == ChatSendCopy.ACCEPT_FIRST_NOT_SENT_SETUP_PAID
                ) {
                    rowsWithKexPaid += messageId
                }
                // ZC-1336: this Retry takes the row's one question with it; what it covered must not ask again.
                if (confirmedFigure == null) row.acceptedPriceZatoshi?.let { retriedAcceptedPrices[messageId] = it }
                zchatPreferences.commitPendingMessage(
                    row.copy(
                        isPending = true,
                        status = MessageStatus.SENDING.name,
                        submitStartedAtMillis = claimedAt,
                        failureReason = null,
                        acceptedPriceZatoshi = confirmedFigure,
                        acceptedAccountKey = row.acceptedAccountKey.takeIf { confirmedFigure != null },
                    ),
                )
                // Keep both memory and disk payloads until the retry is accepted; never delete before dispatch.
                pendingMessages.update { list ->
                    list.map {
                        if (it.id == messageId) {
                            it.copy(
                                isPending = true,
                                status = MessageStatus.SENDING,
                                submitStartedAtMillis = claimedAt,
                                failureReason = null,
                            )
                        } else {
                            it
                        }
                    }
                }
                val accepted =
                    if (failed.replyToId != null) {
                        sendReply(
                            peerAddress,
                            rawMessage,
                            failed.replyToId,
                            failed.replyToPreview.orEmpty(),
                            failed.sendAmountZatoshi ?: DEFAULT_MESSAGE_AMOUNT,
                            retryPendingId = messageId,
                            retryClaimStartedAt = claimedAt,
                        )
                    } else {
                        sendMessage(
                            peerAddress,
                            rawMessage,
                            failed.sendAmountZatoshi ?: DEFAULT_MESSAGE_AMOUNT,
                            messageId,
                            claimedAt,
                            sendQuote = shieldedLinkQuote,
                        )
                    }
                if (!accepted) {
                    // ZC-421: a refused dispatch takes no pair; an accepted one is taken by its writer (a reply's runs later).
                    relayRetryPairs.remove(messageId)
                    // Dispatch refusal means no asynchronous send was started. Restore only after a durable write.
                    zchatPreferences.commitPendingMessage(row)
                    pendingMessages.update { list -> list.map { if (it.id == messageId) failed else it } }
                    SendAttemptProcess.leave(messageId)
                }
                accepted
            } catch (e: Exception) {
                relayRetryPairs.remove(messageId)
                SendAttemptProcess.leave(messageId)
                Log.w("ZCHAT_SEND", "Retry could not be durably recorded: ${e.javaClass.simpleName}")
                _sendMessageState.value = SendMessageState.Error(RETRY_STORAGE_FAILED)
                false
            }
        }

    /**
     * ZC-1308 — the Retry of a row stopped above its accepted price: what its legs cost now. A wallet that cannot be probed
     * right now is priced by the formula (the send's own plan check then decides); no price at all sends nothing. Pay
     * becomes the row's new limit, leg by leg; a figure equal to the one accepted goes on without a question.
     */
    @Suppress("TooGenericExceptionCaught", "ReturnCount")
    private fun askRetryFigure(
        peerAddress: String,
        failed: ChatMessage,
        rawMessage: String,
    ) {
        val messageId = failed.id
        viewModelScope.launch {
            val amount = Zatoshi(failed.sendAmountZatoshi ?: DEFAULT_MESSAGE_AMOUNT)
            val memos = onChainMemoCount(peerAddress, rawMessage)
            val probe =
                try {
                    createChunkedMessageProposal.priceMessage(peerAddress, memos, amount)
                } catch (e: kotlinx.coroutines.CancellationException) {
                    throw e
                } catch (e: Exception) {
                    Log.w("ZCHAT_SEND", "A stopped row's new figure was not priced: ${e.javaClass.simpleName}")
                    _sendMessageState.value = SendMessageState.Error(ChatSendCopy.PRICE_QUOTE_UNAVAILABLE)
                    return@launch
                }
            if (probe is FeeProbe.Built && (probe.usesOrchardInputs || probe.transactionCount != 1)) {
                _sendMessageState.value = SendMessageState.Error(ChatSendCopy.PRICE_QUOTE_UNAVAILABLE)
                return@launch
            }
            val fee = (probe as? FeeProbe.Built)?.fee
            val floor = onChainSendMinimumCost().value
            val messageLeg =
                fee?.let { CreateChunkedMessageProposalUseCase.totalCost(memos, amount).value + it.value }
                    ?: onChainSendMinimumCost(memos, amount).value
            val dust = CreateChunkedMessageProposalUseCase.DEFAULT_AMOUNT_PER_OUTPUT
            val outputs = CreateChunkedMessageProposalUseCase.totalCost(1, dust).value
            val setupLeg = if (fee != null && memos == 1) maxOf(floor, outputs + fee.value) else floor
            val owesKex = messageOwesKexFirst(peerAddress)
            val zboot = owesKex && firstMessageQuote(peerAddress, rawMessage, amount.value).includesZboot
            val setupLegs = (if (owesKex) 1 else 0) + (if (zboot) 1 else 0)
            val total = messageLeg + setupLegs * setupLeg
            val askedAccount = selectedAccountOrNull()
            val pay = {
                // ZC-1348: the account selected at Pay answered; with none readable the legs are not stored and ask later.
                (selectedAccountNow() ?: askedAccount)?.let { payer ->
                    storeQuotedChatSetup(
                        peerAddress,
                        QuotedChatSetup(
                            kex = setupLeg.takeIf { owesKex },
                            message = messageLeg,
                            zboot = setupLeg.takeIf { zboot },
                            account = GetDefaultUnifiedAddressUseCase.accountKeyOf(payer),
                        ),
                    )
                }
                if (zboot) unsentZbootQuotes.add(peerAddress)
                confirmedRetryFigures[messageId] = total
                retryMessage(peerAddress, messageId, costConfirmed = true)
                Unit
            }
            val accepted = acceptedRowOf(messageId)?.acceptedPriceZatoshi
            if (accepted == total) {
                pay()
                return@launch
            }
            askBeforePaying(
                PaidActionConfirmation(
                    PaidAction.FIRST_MESSAGE,
                    onChainMessages = 1 + setupLegs,
                    totalCost = Zatoshi(total),
                    includesRelayIdentity = zboot,
                    setupLegs = setupLegs,
                    setupLegCost = Zatoshi(setupLeg),
                    messageLegCost = Zatoshi(messageLeg),
                ),
                pay = pay,
            )
        }
    }

    /**
     * SR-B2 — Retry of a FAILED row a Shielded switch left in the Tunnel queue ([failed], never published or paid): its
     * payload [rawMessage] goes out as a NEW Shielded send, a reply through [sendReply] (its reply kept), anything else
     * through [sendMessage], each with every question of its path (first message, several memos, the cost notice). The
     * row is removed only when that send takes the payload ([claimSwitchedRow], once); Cancel, a dismissed notice or a
     * refused send leave it FAILED with its text. Called under [retryClaimLock].
     */
    private fun resendSwitchedRowShielded(
        peerAddress: String,
        failed: ChatMessage,
        rawMessage: String,
    ): Boolean {
        val claim: () -> Boolean = { claimSwitchedRow(peerAddress, failed.id) }
        val amount = failed.sendAmountZatoshi ?: DEFAULT_MESSAGE_AMOUNT
        return if (failed.replyToId != null) {
            sendReply(peerAddress, rawMessage, failed.replyToId, failed.replyToPreview.orEmpty(), amount, claimPayload = claim)
        } else {
            sendMessage(peerAddress, rawMessage, amount, restoreTextOnCancel = false, claimPayload = claim)
        }
    }

    /**
     * SR-B2 — the new send takes the payload of the switched row [messageId]: true once, when the stored row is still
     * FAILED (it is then removed from the store and the chat); false when another tap or screen took it first, or the
     * store could not be written (nothing is sent then).
     */
    @Suppress("TooGenericExceptionCaught")
    private fun claimSwitchedRow(
        peerAddress: String,
        messageId: String,
    ): Boolean =
        synchronized(retryClaimLock) {
            try {
                val stored = zchatPreferences.getPendingMessages().firstOrNull { it.id == messageId }
                if (stored == null ||
                    stored.peerAddress != peerAddress ||
                    stored.isPending ||
                    stored.status != MessageStatus.FAILED.name
                ) {
                    _sendMessageState.value = SendMessageState.Error(ChatSendCopy.RETRY_ALREADY_CLAIMED)
                    false
                } else {
                    zchatPreferences.removePendingMessage(messageId)
                    pendingMessages.update { list -> list.filterNot { it.id == messageId } }
                    true
                }
            } catch (e: Exception) {
                Log.w("ZCHAT_SEND", "SR-B2: the switched row could not be taken: ${e.javaClass.simpleName}")
                _sendMessageState.value = SendMessageState.Error(RETRY_STORAGE_FAILED)
                false
            }
        }

    /**
     * P2h — Retry for a FAILED outgoing payment request, under [retryClaimLock]. Refused, with a reason, when its
     * on-chain submit may have started (P2a: never pay twice) or the chat now needs a cost the user has not
     * accepted. Otherwise the row is claimed as SENDING and [sendPaymentRequest] sends the same request again
     * under the same id, which overwrites the FAILED row rather than adding a second one.
     */
    @Suppress("TooGenericExceptionCaught", "ReturnCount")
    private fun retryPaymentRequest(
        peerAddress: String,
        failed: ChatMessage,
        request: co.electriccoin.zcash.ui.screen.chat.model.PaymentRequestInfo,
        costConfirmed: Boolean,
    ): Boolean {
        if (failed.sendMayHaveGoneOut || failed.submitStartedAtMillis != null || failed.submittedTxIds.isNotEmpty()) {
            _sendMessageState.value = SendMessageState.Error(SubmitAttemptProof.MAY_HAVE_BEEN_SENT)
            return false
        }
        if (_sendMessageState.value is SendMessageState.Sending) return false
        // ZC-1272: in a Shielded chat the question below answers for the cost, and its Pay marks the notice as read.
        if (!costConfirmed &&
            !zchatPreferences.hasAcknowledgedMessageCost() &&
            zchatPreferences.getConversationMode(peerAddress) != co.electriccoin.zcash.ui.screen.chat.model.ConversationMode.VAULT
        ) {
            _sendMessageState.value = SendMessageState.Error(RETRY_MODE_CHANGED)
            return false
        }
        // R2-2 (d): in a Shielded chat the request goes on-chain. A request that failed free (a Tunnel chat
        // since switched to Shielded) would otherwise turn into a paid one on a plain Retry tap: show the cost
        // first. Nothing is claimed or sent until the user confirms; the row stays FAILED. True: the tap is
        // handled (the question is on screen), so no "can't retry" notice.
        if (!costConfirmed &&
            zchatPreferences.getConversationMode(peerAddress) == co.electriccoin.zcash.ui.screen.chat.model.ConversationMode.VAULT
        ) {
            // ZC-421 (Z12 item 3, register ZC-474 for requests): a request sent over the relays is never sent again as a
            // second, on-chain request; read before the price question, it is refused with nothing quoted, sent or paid.
            val stored =
                runCatching { zchatPreferences.getPendingMessages().firstOrNull { it.id == failed.id } }
                    .getOrNull()
                    ?.takeIf { it.peerAddress == peerAddress }
            if (failed.id.startsWith(RELAY_ROW_PREFIX) || stored?.relayRumorId != null) {
                return refuseRequestResend(failed, stored, "shielded")
            }
            // ZC-1822: the row stays FAILED.
            if (refusedByTheSpendableMargin(paidActionConfirmation(PaidAction.PAYMENT_REQUEST_RETRY, 1).totalCost)) return false
            askBeforePaying(PaidAction.PAYMENT_REQUEST_RETRY, onChainMessages = 1) {
                retryMessage(peerAddress, failed.id, costConfirmed = true)
            }
            return true
        }
        val messageId = failed.id
        return try {
            // A FAILED request whose submit never started is either kept on disk (a free request no relay took)
            // or, for an on-chain request refused before the submit, only in memory.
            val row = zchatPreferences.getPendingMessages().firstOrNull { it.id == messageId }
            // ZC-421 (Z13): a relay request the closed app left still stored as pending holds its rumor pair and is sent
            // again as that request; one another screen finished is not retried.
            val relayRow = row?.isRelayRow() == true
            if (row != null &&
                (
                    row.peerAddress != peerAddress ||
                        row.submitStartedAtMillis != null ||
                        row.submittedTxIds.isNotEmpty() ||
                        (!relayRow && (row.isPending || row.status != MessageStatus.FAILED.name))
                )
            ) {
                _sendMessageState.value = SendMessageState.Error(SubmitAttemptProof.MAY_HAVE_BEEN_SENT)
                return false
            }
            if (row != null && relayRow && !row.isPending && row.status != MessageStatus.FAILED.name) return false
            if (row != null && relayRow && row.isPending) {
                Log.d("ZCHAT_NOSTR", "Retry of a row left in flight (${if (row.relayRumorId != null) "pair" else "no-pair"})")
            }
            val claim =
                (
                    row ?: ZchatPreferences.PendingMessageData(
                        id = messageId,
                        text = failed.text,
                        timestampMillis = failed.timestamp.toEpochMilli(),
                        peerAddress = peerAddress,
                        paymentRequestAmountZatoshi = request.amountZatoshi,
                        paymentRequestReason = request.reason,
                        submitTracked = true,
                    )
                ).copy(isOutgoing = true, isPending = true, status = MessageStatus.SENDING.name)
            // F4: the claimed request is in flight here until its send ends (or the dispatch is refused below).
            SendAttemptProcess.enter(messageId)
            zchatPreferences.commitPendingMessage(claim)
            pendingMessages.update { list ->
                list.map { if (it.id == messageId) it.copy(isPending = true, status = MessageStatus.SENDING) else it }
            }
            // ZC-421: the request's one rumor (its second and id) goes to its writer through the per-row map.
            if (row != null && relayRow) relayRetryPairs[messageId] = RelayRumorPair(row.relayRumorAtSec, row.relayRumorId)
            val accepted =
                sendPaymentRequest(
                    peerAddress,
                    request.amountZatoshi,
                    request.reason,
                    retryPendingId = messageId,
                    costConfirmed = costConfirmed,
                )
            if (!accepted) relayRetryPairs.remove(messageId)
            if (!accepted) {
                // Nothing was started: put the FAILED row back as it was.
                if (row != null) zchatPreferences.commitPendingMessage(row) else zchatPreferences.removePendingMessage(messageId)
                pendingMessages.update { list -> list.map { if (it.id == messageId) failed else it } }
                SendAttemptProcess.leave(messageId)
            }
            accepted
        } catch (e: Exception) {
            relayRetryPairs.remove(messageId)
            SendAttemptProcess.leave(messageId)
            Log.w("ZCHAT_SEND", "Payment request retry could not be durably recorded: ${e.javaClass.simpleName}")
            _sendMessageState.value = SendMessageState.Error(RETRY_STORAGE_FAILED)
            false
        }
    }

    /**
     * ZC-421 (Z12 item 3) — a payment request that cannot be sent again as the same request: nothing is quoted, sent or paid;
     * the row stays FAILED with its rumor pair and says so, and so does the send state. A second tap answers the same.
     */
    @Suppress("TooGenericExceptionCaught")
    private fun refuseRequestResend(
        failed: ChatMessage,
        stored: ZchatPreferences.PendingMessageData?,
        reason: String,
    ): Boolean {
        Log.w("ZCHAT_NOSTR", "Request not sent again ($reason)")
        val text = ChatSendCopy.PAYMENT_REQUEST_RESEND_REFUSED
        try {
            stored?.let {
                zchatPreferences.commitPendingMessage(it.copy(isPending = false, status = MessageStatus.FAILED.name, failureReason = text))
            }
        } catch (e: Exception) {
            Log.w("ZCHAT_SEND", "The refused request's row could not be saved: ${e.javaClass.simpleName}")
        }
        pendingMessages.update { list ->
            list.map { if (it.id == failed.id) it.copy(isPending = false, status = MessageStatus.FAILED, failureReason = text) else it }
        }
        _sendMessageState.value = SendMessageState.Error(text)
        return false
    }

    private class RetryClaimLostException : IllegalStateException()

    /** ZC-1975: the row a send pays for was deleted by the user during the send; nothing of it was paid. */
    private class DeletedRowException : IllegalStateException("The message was deleted during its send")

    /** ZC-1958: the account that is to pay this message is no longer selected; nothing was built or paid for it. */
    private class PayingAccountChangedException : IllegalStateException("The selected account changed during the send")

    /**
     * ZC-1276: the time limit of one send's build, outside its NonCancellable block. On a scope of its own, so leaving the
     * chat does not end it and it is no work of the send scope; timed on Dispatchers.Main like the run itself, so the two
     * never interleave.
     */
    private fun startBuildLimit(
        deadline: SendBuildDeadline,
        onExpired: () -> Unit,
    ): Job =
        sendBuildLimitScope.launch(Dispatchers.Main.immediate) {
            kotlinx.coroutines.delay(SEND_BUILD_LIMIT_MS)
            if (deadline.expire()) onExpired()
        }

    /**
     * ZC-1276: the limit won before any submit started, so nothing was stored or broadcast. The row becomes not sent, with
     * its reason and a working Retry, and this does what the parked run's finally would have done: that run may never end,
     * and once it does it leaves the row alone (a Retry may own it by then).
     */
    private fun settleStalledBuild(
        pendingId: String,
        expectedSubmitMarker: Long?,
        reason: String =
            if (pendingId in rowsWithKexPaid) ChatSendCopy.FAILED_BUILD_TOO_LONG_KEX_PAID else ChatSendCopy.FAILED_BUILD_TOO_LONG,
    ) {
        Log.w("ZCHAT_SEND", "A send passed its time limit before its submit: not sent")
        liveSendTotals.remove(pendingId)?.job?.cancel()
        pendingMessages.update { current ->
            current.map { msg ->
                if (msg.id == pendingId) {
                    msg.copy(status = MessageStatus.FAILED, isPending = false, timestamp = Instant.now(), failureReason = reason)
                } else {
                    msg
                }
            }
        }
        keepUnsubmittedFailure(pendingId, expectedSubmitMarker, reason)
        _sendMessageState.value = SendMessageState.Error(reason)
        SendAttemptProcess.leave(pendingId)
        LiveSenders.release(pendingId, this)
    }

    /** ZC-1290: one row's total limit: one per row in this process, armed once, carried across its runs. */
    private class LiveSendTotal(
        @Volatile var owner: ChatViewModel,
        @Volatile var expectedSubmitMarker: Long?,
    ) {
        @Volatile var job: Job? = null

        /** The run in progress; null between runs (in a queue, or waiting for funds). */
        @Volatile var run: SendBuildDeadline? = null
    }

    /** ZC-1271: what a Pay accepted for a first message, until its send takes it onto the row. */
    private data class AcceptedFirstMessage(
        val priceZatoshi: Long,
        // The account a funds wait may pay from (only a send that may wait for its funds names one).
        val accountKey: String?,
        // ZC-1395: the account selected when the question was asked, on every path (null when it could not be read).
        val confirmedAccountKey: String? = accountKey,
        // ZC-1396: false for a send that may not wait for funds (a file, a Retry, a switched row): its price is only a ceiling.
        val waits: Boolean = true,
        // ZC-1506: the price is the message's own transaction only (no setup leg in it): it is the ceiling as it stands.
        val messageOnly: Boolean = false,
        // ZC-1508: this Pay answered the contact-moved-to-a-paid-mode question; its submit clears that mark.
        val clearsPeerMovedMark: Boolean = false,
        // ZC-1945: the chat mode this Pay was given in, as a row stores it (acceptedMode): null = Shielded.
        val mode: String? = null,
    )

    /** ZC-1290: the row's total limit, armed the first time with [leftMs]; a later run or screen only takes it over. */
    private fun liveSendTotalFor(
        rowId: String,
        expectedSubmitMarker: Long?,
        leftMs: Long = SEND_TOTAL_LIMIT_MS,
    ): LiveSendTotal {
        var armed = false
        val total =
            liveSendTotals.computeIfAbsent(rowId) {
                armed = true
                LiveSendTotal(this, expectedSubmitMarker)
            }
        total.owner = this
        total.expectedSubmitMarker = expectedSubmitMarker
        if (armed) {
            total.job =
                sendBuildLimitScope.launch(Dispatchers.Main.immediate) {
                    kotlinx.coroutines.delay(leftMs)
                    while (true) {
                        val run = total.run
                        if (run == null || run.expire()) {
                            total.owner.settleLiveSendTotal(rowId, total)
                            return@launch
                        }
                        // A submit that started is never settled as not sent; its row is settled by what the submit did.
                        if (run.submitClaimed || run.expired) return@launch
                        kotlinx.coroutines.delay(SEND_TOTAL_RECHECK_MS)
                    }
                }
        }
        return total
    }

    /** ZC-1290: the row left flight some other way: its limit is over. */
    private fun finishLiveSendTotal(
        rowId: String,
        total: LiveSendTotal?,
    ) {
        if (total == null) return
        total.job?.cancel()
        liveSendTotals.remove(rowId, total)
    }

    /**
     * ZC-1290: the total passed with no submit of the message started: the row is not sent, its queue entry goes, a parked
     * key exchange lets go of its stamp and lock. A run that wakes up later pays nothing (its deadline expired).
     */
    private fun settleLiveSendTotal(
        rowId: String,
        total: LiveSendTotal,
    ) {
        // ZC-1379: only the row's current total settles it; a stale one (a Retry armed a new total) leaves the row alone.
        total.job?.cancel()
        if (!liveSendTotals.remove(rowId, total)) return
        synchronized(messageQueue) { messageQueue.removeAll { it.pendingId == rowId } }
        total.run?.releaseExpiredLeg()
        pendingSendQuotes.remove(rowId)
        val stored = runCatching { zchatPreferences.getPendingMessages().any { it.id == rowId } }.getOrDefault(true)
        if (!stored) return
        // A row waiting for funds has no live sender: registered, so its release reaches the other screens.
        if (!isSendLiveInThisProcess(rowId)) LiveSenders.waiting(rowId, this)
        settleStalledBuild(rowId, total.expectedSubmitMarker, ChatSendCopy.FAILED_WAITED_TOO_LONG)
        processNextQueuedMessage()
    }

    /**
     * ZC-1977: whether the user deleted (hid) [rowId] on this screen ([hideMessage] adds it here before it returns).
     * ZC-1990: or on another screen of this process ([LiveSenders.hidden]); no store read.
     */
    private fun rowHiddenHere(rowId: String): Boolean =
        runCatching { rowId in hiddenMessages.value || LiveSenders.isHidden(rowId) }.getOrDefault(false)

    /**
     * ZC-1979: whether the user deleted (hid) [rowId], on this screen or in the store (another screen, an earlier process);
     * a store that cannot be read says no, as [storedRowExists].
     */
    @Suppress("TooGenericExceptionCaught")
    private fun rowIsHidden(rowId: String): Boolean =
        rowHiddenHere(rowId) ||
            try {
                rowId in zchatPreferences.getHiddenMessageIds()
            } catch (e: Exception) {
                Log.w("ZCHAT_SEND", "Hidden rows not read: ${e.javaClass.simpleName}")
                false
            }

    /** ZC-1959: whether [rowId] is in the store; [whenUnreadable] when the store cannot be read. */
    @Suppress("TooGenericExceptionCaught")
    private fun storedRowExists(
        rowId: String,
        whenUnreadable: Boolean,
    ): Boolean =
        try {
            zchatPreferences.getPendingMessages().any { it.id == rowId }
        } catch (e: Exception) {
            Log.w("ZCHAT_SEND", "Stored rows not read: ${e.javaClass.simpleName}")
            whenUnreadable
        }

    /**
     * ZC-1959: the row this run sent was deleted by the user: nothing of it is written or paid; the queue goes on.
     * ZC-1976 (money-path rule 2): the Delete may have landed before this run wrote the ZBOOT allowance its question quoted
     * ([zbootWrittenByRun]); that allowance goes, and the quote not yet taken with it, unless another unsent row of the
     * contact still needs them.
     * ZC-1992: under the same condition a KEX still owed for the contact was owed only for that row: it goes with it, as
     * [cancelKexOwedOnlyFor] does for a deleted row that is not sending, so no later block pays it alone.
     */
    @Suppress("TooGenericExceptionCaught")
    private fun stopForDeletedRow(
        rowId: String,
        peerAddress: String,
        zbootWrittenByRun: Boolean,
    ) {
        Log.w("ZCHAT_SEND", "The message was deleted while its send was checked: nothing paid")
        // ZC-1991: rows that cannot be read may hold another unsent message of the contact: the allowance stays.
        val rows = runCatching { zchatPreferences.getPendingMessages() }.getOrNull()
        val hidden = runCatching { zchatPreferences.getHiddenMessageIds() }.getOrDefault(emptySet())
        if (rows != null && !anotherUnsentRowNeedsSetup(peerAddress, rowId, rows, hidden) && !owedKexIsLone(peerAddress)) {
            unsentZbootQuotes.remove(peerAddress)
            val kexOwed =
                kexOwedPeers.contains(peerAddress) || runCatching { zchatPreferences.isKexOwed(peerAddress) }.getOrDefault(true)
            if (kexOwed && rowId.isUnsentRowId()) {
                try {
                    withdrawKexOwedOnlyFor(peerAddress, rowId, rows, hidden, withdrawSetup = true)
                } catch (e: Exception) {
                    Log.w("KEX", "A deleted message's owed KEX not withdrawn: ${e.javaClass.simpleName}")
                    // The allowance this run wrote goes all the same.
                    if (zbootWrittenByRun) runCatching { withdrawZbootQuote(peerAddress) }
                }
            } else if (zbootWrittenByRun) {
                withdrawZbootQuote(peerAddress)
            }
        }
        _sendMessageState.value = SendMessageState.Idle
        processNextQueuedMessage()
    }

    /** ZC-1271: [rowId]'s stored row, when it carries a price the user accepted. */
    @Suppress("TooGenericExceptionCaught")
    private fun acceptedRowOf(rowId: String): ZchatPreferences.PendingMessageData? =
        try {
            zchatPreferences.getPendingMessages().firstOrNull { it.id == rowId && it.acceptedPriceZatoshi != null }
        } catch (e: Exception) {
            Log.w("ZCHAT_SEND", "Stored rows not read: ${e.javaClass.simpleName}")
            null
        }

    /** ZC-1271: a first message to [peerAddress] was stopped for the user: not sent, its accepted price still on the row. */
    @Suppress("TooGenericExceptionCaught")
    private fun firstMessageStoppedForDecision(peerAddress: String): Boolean =
        try {
            zchatPreferences.getPendingMessages().any {
                it.peerAddress == peerAddress &&
                    it.isOutgoing &&
                    it.acceptedPriceZatoshi != null &&
                    it.status == MessageStatus.FAILED.name
            }
        } catch (e: Exception) {
            Log.w("KEX", "Stored rows not read: ${e.javaClass.simpleName}")
            true
        }

    /**
     * ZC-1271: the most the message's own transaction may cost on an accepted row: the accepted total less our key
     * exchange's price and, when the total counted one, our ZBOOT's. Fixed by the row, so a restart between the two legs
     * reads the same figure. The key exchange itself is held to the one handshake price ([payOwedKex]).
     */
    private fun acceptedMessageCeiling(
        accepted: Long,
        peerAddress: String,
        message: String,
        amountZatoshi: Long,
    ): KexAnswerPrice {
        val setupLeg = onChainSendMinimumCost().value
        val messageLeg = onChainSendMinimumCost(onChainMemoCount(peerAddress, message), Zatoshi(amountZatoshi)).value
        val left = accepted - setupLeg
        return KexAnswerPrice(Zatoshi((if (left >= messageLeg + setupLeg) left - setupLeg else left).coerceAtLeast(0L)))
    }

    /**
     * ZC-1271: at each block, the accepted first messages stored as waiting for their funds are sent once they can be,
     * from the row on disk, by any screen: a process-wide claim means two screens hearing one block pay once, and a row
     * with a live sender or a started submit is never touched. Who consented: the user's Pay on the price question, whose
     * total is on the row. It never pays above that total, and a plan that changed stops the row for good: only its
     * Retry sends it.
     */
    @Suppress("TooGenericExceptionCaught")
    private fun resumeFundsWaitRows() {
        val rows =
            try {
                zchatPreferences.getPendingMessages().filter { it.waitsForFunds() }
            } catch (e: Exception) {
                Log.w("ZCHAT_SEND", "Stored rows not read: ${e.javaClass.simpleName}")
                return
            }
        val now = System.currentTimeMillis()
        for (row in rows) {
            // A row a screen is running or holds in its queue is that screen's, with its limit armed.
            if (isSendLiveInThisProcess(row.id)) continue
            // ZC-1979 (money-path rule 2): a row the user deleted (its id hidden) whose removal did not reach the disk.
            if (rowIsHidden(row.id)) continue
            val age = (now - row.timestampMillis).coerceAtLeast(0L)
            val total = liveSendTotalFor(row.id, null, (SEND_TOTAL_LIMIT_MS - age).coerceAtLeast(0L))
            // A phone that slept stops the timer (Dispatchers.Main) but not the row's age: no payment hours after the Pay.
            if (age >= SEND_TOTAL_LIMIT_MS && total.run == null) {
                if (liveSendTotals[row.id] === total) settleLiveSendTotal(row.id, total)
                continue
            }
            if (fundsWaitClaims.add(row.id)) resumeFundsWaitRow(row.id)
        }
    }

    /** ZC-1271: holds the row's claim until its send was started, or until this block's answer is to go on waiting. */
    private fun resumeFundsWaitRow(rowId: String) {
        viewModelScope.launch(Dispatchers.Main.immediate) {
            try {
                resumeFundsWaitRowClaimed(rowId)
            } finally {
                fundsWaitClaims.remove(rowId)
            }
        }
    }

    @Suppress("ReturnCount")
    private suspend fun resumeFundsWaitRowClaimed(rowId: String) {
        val row = acceptedRowOf(rowId)?.takeIf { it.waitsForFunds() } ?: return
        val accepted = row.acceptedPriceZatoshi ?: return
        val peer = row.peerAddress
        val amount = row.sendAmountZatoshi ?: DEFAULT_MESSAGE_AMOUNT
        // ZC-1306: a row New Chat accepted in Tunnel was asked as on-chain and goes on; any other switch stops it.
        if (zchatPreferences.getConversationMode(peer).name != (row.acceptedMode ?: ConversationMode.VAULT.name)) {
            stopFundsWaitRow(rowId, RETRY_MODE_CHANGED)
            return
        }
        // Only the account that accepted the price pays it; another account leaves the row waiting.
        // ZC-1326: a row that names no account was accepted by none: it stops, and no account pays it.
        val acceptedAccountKey = row.acceptedAccountKey
        if (acceptedAccountKey == null) {
            stopFundsWaitRow(rowId, ChatSendCopy.FAILED_NO_ACCEPTING_ACCOUNT)
            return
        }
        val account = selectedAccountOrNull() ?: return
        if (acceptedAccountKey != GetDefaultUnifiedAddressUseCase.accountKeyOf(account)) return
        // ZC-1335: before the first history pass of a cold start nothing can say whether a key exchange is owed. The row goes on
        // waiting (nothing written, nothing paid), and a later block asks again, within its total limit.
        if (zchatPreferences.getE2EOurPublicKey(peer) == null && seedKeyProvider.isKeyCreationWaitingForHistory(peer)) return
        val owesKex = messageOwesKexFirst(peer)
        if (owesKex) {
            planOwnConversationId(peer)
            val plan = checkFirstMessagePlan(peer, onChainMemoCount(peer, row.text), amount)
            when {
                plan is FirstMessagePlan.Fundable -> Unit
                // Still confirming, or not answerable at this block: asked again at the next one, within the total.
                plan is FirstMessagePlan.WaitForFunds -> return
                plan is FirstMessagePlan.Unchecked &&
                    plan.cause !is co.electriccoin.zcash.ui.screen.chat.usecase.KeystoneChatSendRefusedException &&
                    plan.cause !is co.electriccoin.zcash.ui.screen.chat.usecase.OwnAddressChatSendRefusedException -> return
                else -> {
                    stopFundsWaitRow(rowId, firstMessagePlanRefusal(plan, row = true))
                    return
                }
            }
        }
        // ZC-1909: a row whose key exchange already went out (parked after its message met confirming ZEC) waits while
        // the confirming ZEC is what would pay its message; nothing is built or paid at this block.
        if (!owesKex) {
            val need = onChainSendMinimumCost(onChainMemoCount(peer, row.text), Zatoshi(amount))
            val spendableNow =
                account.unified.ironwood.available.value
            if (!co.electriccoin.zcash.ui.common.model.SpendableCover
                    .covers(spendableNow, need.value) &&
                ShortfallReason.classify(account, need) is ShortfallReason.StillConfirming
            ) {
                return
            }
        }
        // Re-read after the waits above; a question or a send on this screen keeps its state, so a later block goes.
        val state = _sendMessageState.value
        if (state !is SendMessageState.Idle && state !is SendMessageState.Success && state !is SendMessageState.Error) return
        if (isSendLiveInThisProcess(rowId) || acceptedRowOf(rowId)?.waitsForFunds() != true) return
        if (owesKex) {
            val quote = firstMessageQuote(peer, row.text, amount)
            if (quote.total.value > accepted) {
                stopFundsWaitRow(rowId, ChatSendCopy.FAILED_ABOVE_ACCEPTED_PRICE)
                return
            }
            if (quote.includesZboot) unsentZbootQuotes.add(peer)
        }
        LiveSenders.running(rowId, this)
        pendingMessages.update { list ->
            val shown = list.firstOrNull { it.id == rowId }?.copy(waitsForFunds = false)
            if (shown == null) {
                list + storedPendingRowAsShown(row, rehydrateTunnelWait = false).copy(waitsForFunds = false)
            } else {
                list.map { if (it.id == rowId) shown else it }
            }
        }
        doSendMessage(peer, row.text, amount, existingPendingId = rowId)
    }

    /** ZC-1271: the row stops for the user: not sent with [reason]; its price stays on it, so no block pays it or its KEX. */
    private fun stopFundsWaitRow(
        rowId: String,
        reason: String,
    ) {
        Log.w("ZCHAT_SEND", "An accepted first message stopped for a decision: nothing more paid")
        keepUnsubmittedFailure(rowId, null, reason)
        _sendMessageState.value = SendMessageState.Error(reason)
        liveSendTotals[rowId]?.let { finishLiveSendTotal(rowId, it) }
        // Its release reaches the other screens that show it.
        if (!isSendLiveInThisProcess(rowId)) LiveSenders.waiting(rowId, this)
        LiveSenders.release(rowId, this)
    }

    /** M2 — an owed KEX not paid on a block or a chat open because the message after it cannot be paid. */
    private class OwedKexPlanRefusedException(
        message: String,
    ) : IllegalStateException(message)

    /** ZC-1340: the queue gave up on this row; a setup step its run paid is said, so "not sent" reads true. */
    private fun queueGaveUpReason(pendingId: String): String =
        if (pendingId in rowsWithKexPaid) ChatSendCopy.FAILED_FUNDS_CONFIRMING_SETUP_PAID else ChatSendCopy.FAILED_FUNDS_CONFIRMING

    /** ZC-1909: what a refused message needs: the SDK's figure, the shortfall text's, or the message's own minimum. */
    private fun shortfallNeedOf(
        e: Throwable,
        peerAddress: String,
        message: String,
        amountZatoshi: Long,
    ): Zatoshi =
        CreateChunkedMessageProposalUseCase.sdkShortfallNeed(e)
            ?: ChatSendCopy.messageShortfallFigures(e.message.orEmpty())?.second
            ?: onChainSendMinimumCost(onChainMemoCount(peerAddress, message), Zatoshi(amountZatoshi))

    /**
     * ZC-1909 (money-path rule 2): who consented to this message waiting and then paying by itself. Only a Pay that may
     * wait for funds and named the account it was asked under ([AcceptedFirstMessage.waits], not a message-only price),
     * or a row that already carries such a total (ZC-1271); null otherwise, and then nothing waits on it.
     */
    @Suppress("TooGenericExceptionCaught")
    private fun fundsWaitConsentOf(
        accepted: AcceptedFirstMessage?,
        rowId: String,
    ): AcceptedFirstMessage? =
        accepted?.takeIf { it.waits && it.accountKey != null && !it.messageOnly }
            ?: acceptedRowOf(rowId)?.let { row ->
                val price = row.acceptedPriceZatoshi ?: return@let null
                row.acceptedAccountKey?.let { AcceptedFirstMessage(price, it, mode = row.acceptedMode) }
            }

    /** ZC-1945: a mode as a row stores it (acceptedMode): null for Shielded, the name otherwise. */
    private fun storedModeOf(mode: ConversationMode): String? = mode.name.takeIf { mode != ConversationMode.VAULT }

    /** ZC-1909: whether the bubble of [rowId] shows the funds' progress (on screen only; the stored row decides the rest). */
    private fun showWaitingForFunds(
        rowId: String,
        waiting: Boolean,
    ) {
        pendingMessages.update { list -> list.map { if (it.id == rowId) it.copy(waitsForFunds = waiting) else it } }
    }

    /** ZC-1909: [parkRowForFunds] under a consent ([fundsWaitConsentOf]) given by the account selected now, else false. */
    private suspend fun parkWithConsent(
        pendingId: String,
        expectedSubmitMarker: Long?,
        accepted: AcceptedFirstMessage?,
        peerAddress: String,
    ): Boolean {
        // ZC-1947 (ZC-1396: a Retry may not wait for funds): a run that holds a marker on the row (a Retry's claim, or a
        // submit that started) is never parked; parking would clear the marker its own submit needs.
        if (expectedSubmitMarker != null) return false
        val consent = fundsWaitConsentOf(accepted, pendingId) ?: return false
        val account = selectedAccountOrNull() ?: return false
        if (consent.accountKey != GetDefaultUnifiedAddressUseCase.accountKeyOf(account)) return false
        return parkRowForFunds(pendingId, expectedSubmitMarker, consent, peerAddress)
    }

    /**
     * ZC-1909: the row goes back to waiting for its funds, as a ZC-1271 row does: in flight, no submit marker, the accepted
     * total and account on it, so resumeFundsWaitRows sends it at a later block and never above that total. Only a row no
     * submit of which ever started (the same proof keepUnsubmittedFailure asks); false leaves the row to the caller.
     */
    @Suppress("TooGenericExceptionCaught")
    private fun parkRowForFunds(
        pendingId: String,
        expectedSubmitMarker: Long?,
        consent: AcceptedFirstMessage,
        peerAddress: String,
    ): Boolean =
        synchronized(retryClaimLock) {
            try {
                val row = zchatPreferences.getPendingMessages().firstOrNull { it.id == pendingId } ?: return@synchronized false
                if (row.submitStartedAtMillis != expectedSubmitMarker || row.submittedTxIds.isNotEmpty()) return@synchronized false
                // ZC-1945 (money-path rule 2): the row waits only in the mode its Pay was given in; a chat that left it
                // since is not parked (nothing pays the message by itself), and the row keeps the consent's mode.
                if (storedModeOf(zchatPreferences.getConversationMode(peerAddress)) != consent.mode) return@synchronized false
                val parked =
                    row.copy(
                        isPending = true,
                        status = MessageStatus.SENDING.name,
                        submitStartedAtMillis = null,
                        submitAttemptHeight = null,
                        failureReason = null,
                        acceptedPriceZatoshi = consent.priceZatoshi,
                        acceptedAccountKey = consent.accountKey,
                        acceptedMode = consent.mode,
                    )
                if (!parked.waitsForFunds()) return@synchronized false
                zchatPreferences.commitPendingMessage(parked)
                pendingMessages.update { list ->
                    list.map {
                        if (it.id == pendingId) {
                            it.copy(
                                isPending = true,
                                status = MessageStatus.SENDING,
                                submitStartedAtMillis = null,
                                submitAttemptHeight = null,
                                failureReason = null,
                                waitsForFunds = true,
                            )
                        } else {
                            it
                        }
                    }
                }
                true
            } catch (e: Exception) {
                Log.w("ZCHAT_SEND", "The waiting row could not be saved: ${e.javaClass.simpleName}")
                false
            }
        }

    /** A failure known to precede SDK creation keeps its payload, amount and quote across a restart. */
    @Suppress("TooGenericExceptionCaught")
    private fun keepUnsubmittedFailure(
        pendingId: String,
        expectedSubmitMarker: Long?,
        failureReason: String? = null,
    ): Unit =
        synchronized(retryClaimLock) {
            try {
                val row = zchatPreferences.getPendingMessages().firstOrNull { it.id == pendingId } ?: return
                if (row.submitStartedAtMillis != expectedSubmitMarker) return
                zchatPreferences.commitPendingMessage(
                    row.copy(
                        isPending = false,
                        status = MessageStatus.FAILED.name,
                        submitStartedAtMillis = null,
                        submitAttemptHeight = null,
                        failureReason = failureReason,
                    ),
                )
                pendingMessages.update { list ->
                    list.map {
                        if (it.id == pendingId) {
                            it.copy(
                                isPending = false,
                                status = MessageStatus.FAILED,
                                submitStartedAtMillis = null,
                                submitAttemptHeight = null,
                                failureReason = failureReason,
                            )
                        } else {
                            it
                        }
                    }
                }
            } catch (e: Exception) {
                // Leave any existing may-have-submitted marker armed when persistence fails.
                Log.w("ZCHAT_SEND", "Failed message could not be saved: ${e.javaClass.simpleName}")
            }
        }

    /** The highest chain tip this ViewModel knows, or null. */
    @Suppress("TooGenericExceptionCaught", "SwallowedException")
    private fun knownChainTip(): Long? {
        val fromSynchronizer =
            try {
                synchronizerProvider.synchronizer.value
                    ?.networkHeight
                    ?.value
                    ?.value
            } catch (e: Exception) {
                null
            }
        return listOfNotNull(_blockHeight.value, fromSynchronizer).maxOrNull()?.takeIf { it > 0 }
    }

    /**
     * P2a — records, durably and before the SDK may store or broadcast anything, that the submit of
     * [row] starts now. Runs as the use case's onSubmitStarting; if the write fails, nothing is submitted.
     */
    private data class SubmitMarker(
        val startedAtMillis: Long,
        val height: Long?
    ) {
        fun applyTo(message: ChatMessage): ChatMessage =
            message.copy(submitStartedAtMillis = startedAtMillis, submitAttemptHeight = height)
    }

    private suspend fun recordSubmitStarted(row: ZchatPreferences.PendingMessageData): SubmitMarker {
        val startedAt = nextSubmitMarker()
        val height = knownChainTip()
        val accountHash = zchatAccountHash()
        withContext(Dispatchers.IO) {
            synchronized(retryClaimLock) {
                val current = zchatPreferences.getPendingMessages().firstOrNull { it.id == row.id }
                if (current == null || current.submitStartedAtMillis != row.submitStartedAtMillis) {
                    throw RetryClaimLostException()
                }
                // F4: from here until the send ends, this row is in flight in this process and never judged.
                SendAttemptProcess.enter(row.id)
                zchatPreferences.commitPendingMessage(
                    row.copy(
                        submitTracked = true,
                        submitStartedAtMillis = startedAt,
                        submitAttemptHeight = height,
                        // F4: this attempt's process and ZCHAT account (the K1 fast path); nothing of an earlier
                        // attempt's settling, except the ids a proven expiry replaced (a late landing is noticed).
                        submittedExpiries = emptyMap(),
                        attemptProcessId = SendAttemptProcess.ID,
                        attemptAccountHash = accountHash,
                        releaseAnchorHeight = null,
                        supersededTxIds = (row.supersededTxIds + current.supersededTxIds).distinct(),
                        resolvedNotSentAtHeight = null,
                    ),
                )
            }
        }
        // F4, debug builds only (a release build reads it as not armed): phone check (c1) ends the process here,
        // after the marker and before anything is created.
        FaultSeams.killHereIfArmed(FaultSeam.KILL_AFTER_MARKER_BEFORE_CREATE)
        val mark = SubmitMarker(startedAt, height)
        pendingMessages.update { list -> list.map { if (it.id == row.id) mark.applyTo(it) else it } }
        return mark
    }

    /** Link the returned SDK identities to the same durable owner before reconciliation can remove it. */
    private fun recordSubmittedTransactions(pendingId: String, marker: SubmitMarker?, outcome: SubmitResult?) {
        if (marker == null) return
        val ids =
            when (outcome) {
                is SubmitResult.Success -> outcome.txIds
                is SubmitResult.Failure -> outcome.txIds
                is SubmitResult.Partial -> outcome.txIds
                is SubmitResult.GrpcFailure -> outcome.txIds
                is SubmitResult.SentUnconfirmed -> outcome.txIds
                null -> emptyList()
            }.distinct()
        if (ids.isEmpty()) return
        synchronized(retryClaimLock) {
            val row = zchatPreferences.getPendingMessages().firstOrNull { it.id == pendingId } ?: return
            if (row.submitStartedAtMillis != marker.startedAtMillis) return
            // F4: merged with the ids (and their expiry heights) recorded before the submit, never replacing them.
            zchatPreferences.commitPendingMessage(row.copy(submittedTxIds = (row.submittedTxIds + ids).distinct()))
            pendingMessages.update { messages ->
                messages.map { if (it.id == pendingId) it.copy(submittedTxIds = (it.submittedTxIds + ids).distinct()) else it }
            }
        }
    }

    /**
     * F4 (fix-all 2.13.0, train T4; SPECS §1.4 step 4; T2 review G-F2-2): the send's stored transactions and their
     * expiry heights, recorded on the row BEFORE the first one is submitted (F2's onTransactionsStored). A checked write
     * under [retryClaimLock], made only while the row still carries this attempt's marker: if it throws, nothing is
     * submitted and the send is SentUnconfirmed with every id (createStoreAndSubmit). No timeout here: a timeout's
     * cancellation out of this step used to lose the ids.
     */
    private suspend fun recordStoredTransactions(
        pendingId: String,
        marker: SubmitMarker?,
        stored: List<co.electriccoin.zcash.ui.common.datasource.StoredTransaction>,
    ) {
        val mark = checkNotNull(marker) { "the stored transactions have no submit marker" }
        val ids = stored.map { it.txId }
        val expiries = stored.mapNotNull { s -> s.expiryHeight?.let { s.txId to it } }.toMap()
        withContext(Dispatchers.IO) {
            synchronized(retryClaimLock) {
                val row = zchatPreferences.getPendingMessages().firstOrNull { it.id == pendingId }
                check(row != null && row.submitStartedAtMillis == mark.startedAtMillis) { "the send's row changed" }
                warnIfExpiryBeyondTable(row.submitAttemptHeight, expiries.values)
                zchatPreferences.commitPendingMessage(
                    row.copy(
                        submittedTxIds = (row.submittedTxIds + ids).distinct(),
                        submittedExpiries = row.submittedExpiries + expiries,
                    ),
                )
            }
        }
        pendingMessages.update { list ->
            list.map { if (it.id == pendingId) it.copy(submittedTxIds = (it.submittedTxIds + ids).distinct()) else it }
        }
    }

    /**
     * ZC-114: a stored expiry later than ChainTiming's table allows for the attempt's height means the table is wrong
     * for the shipped SDK (the bounds used when no expiry is known would be short). Logged without a txid, so the first
     * phone log after an SDK bump shows it. Changes nothing.
     */
    private fun warnIfExpiryBeyondTable(
        attemptHeight: Long?,
        expiries: Collection<Long>,
    ) {
        val height = attemptHeight ?: return
        val lead = SendAttemptRules.tipLead(height)
        val bound = height + ChainTiming.maxExpiryDelta(height + lead) + lead
        val beyond = expiries.filter { it > bound }
        if (beyond.isNotEmpty()) {
            Log.w(
                "ZCHAT_SEND",
                "a stored expiry is ${beyond.max() - height} blocks past the attempt's height, beyond ChainTiming's " +
                    "bound of ${bound - height}: the expiry table does not match the SDK",
            )
        }
    }

    /**
     * P2a — a send failed after its submit started. Unless the SDK provably stored nothing, it may still go
     * out: keep the row (FAILED, with its submit record, persisted so a restart keeps it) and never re-queue it.
     */
    private fun keepPossiblySentFailure(
        row: ZchatPreferences.PendingMessageData,
        mark: SubmitMarker,
        failure: Exception? = null,
    ) {
        val now = Instant.now()
        // A stored rejection names the transactions the SDK kept; link them so a later mined copy retires the row.
        val storedIds = (failure as? SubmitRejectedException)?.txIds.orEmpty()
        val persisted = zchatPreferences.getPendingMessages().firstOrNull { it.id == row.id } ?: row
        val txIds = (persisted.submittedTxIds + storedIds).distinct()
        pendingMessages.update { current ->
            current.map { msg ->
                if (msg.id == row.id) {
                    mark.applyTo(msg).copy(
                        status = MessageStatus.FAILED,
                        isPending = false,
                        timestamp = now,
                        submittedTxIds = (msg.submittedTxIds + txIds).distinct(),
                    )
                } else {
                    msg
                }
            }
        }
        // Reconciliation may have removed the disk row while submission was in flight. Never recreate
        // a tracked-but-unmarked FAILED row: the captured submit marker remains authoritative.
        zchatPreferences.commitPendingMessage(
            persisted.copy(
                isOutgoing = true,
                isPending = false,
                status = MessageStatus.FAILED.name,
                submitTracked = true,
                submitStartedAtMillis = mark.startedAtMillis,
                submitAttemptHeight = mark.height,
                submittedTxIds = txIds,
            ),
        )
    }

    /**
     * SR-2 — the confirmation for a send the chokepoint did not throw on. [sent] only when it reported delivery;
     * [unconfirmed] for SubmitResult.GrpcFailure (stored, not delivered yet, re-broadcast by the SDK) and
     * SentUnconfirmed (the settlement threw after the broadcast), where nothing is known yet. A null outcome
     * (a flow that shows its own result screen) keeps [sent], as before.
     */
    private fun submittedSendState(
        outcome: SubmitResult?,
        sent: String,
        unconfirmed: String,
    ): SendMessageState.Success =
        if (outcome is SubmitResult.SentUnconfirmed || outcome is SubmitResult.GrpcFailure) {
            SendMessageState.Success(unconfirmed)
        } else {
            SendMessageState.Success(sent)
        }

