        @Volatile
        private var heldGroupAcceptScope: kotlinx.coroutines.CoroutineScope =
            kotlinx.coroutines.CoroutineScope(kotlinx.coroutines.SupervisorJob() + Dispatchers.Default)

        /**
         * R9-2 — the process-wide scope for sends that must outlive the screen that started them ([heldGroupAcceptScope]).
         * Nothing in the app cancels it; if it ever were cancelled, a fresh one replaces it, so a send is never dropped
         * without a word by a dead scope.
         */
        private fun processSendScope(): kotlinx.coroutines.CoroutineScope {
            val current = heldGroupAcceptScope
            if (current.coroutineContext[kotlinx.coroutines.Job]?.isActive != false) return current
            return synchronized(processSendScopeLock) {
                val again = heldGroupAcceptScope
                if (again.coroutineContext[kotlinx.coroutines.Job]?.isActive != false) {
                    again
                } else {
                    val fresh = kotlinx.coroutines.CoroutineScope(kotlinx.coroutines.SupervisorJob() + Dispatchers.Default)
                    heldGroupAcceptScope = fresh
                    fresh
                }
            }
        }

